(1855, -1, 'activate_deleterequest', 'error', 'You are going to delete the activation request.<br />\r\nThis will effectively suspend your account and you will not receive further emails.<br />\r\n<br />\r\nIf you instead want to activate your account, please click <a href=\"register.php?a=act&amp;i={1}&amp;u={2}\">here</a>.<br />\r\n<br />\r\n<strong><a href=\"register.php?do=killactivation&amp;i={1}&amp;u={2}\">Delete the activation request</a></strong>', 'vbulletin', 'vBulletin Solutions', 1163415387, '3.6.4'),
(1856, -1, 'activate_moderation', 'error', 'Your account has been activated but you are currently in the moderation queue to be added to the forum.', 'vbulletin', '', 0, ''),
(1857, -1, 'activate_requestdeleted', 'error', 'The activation request has been deleted. You will not receive further emails.', 'vbulletin', '', 0, ''),
(1858, -1, 'activate_wrongusergroup', 'error', 'Your account has already been activated so please try logging in.', 'vbulletin', '', 0, ''),
(1859, -1, 'additional_products_disable_x_y', 'error', 'The following products depend on <em>{1}</em> and must also be disabled:\r\n<ol>{2}</ol>\r\nTo continue disabling all these products, <a href=\"{3}\">click here</a>.', 'vbulletin', 'vBulletin Solutions', 1142519066, '3.6.0 Beta 1'),
(1860, -1, 'additional_products_enable_x_y', 'error', 'The following products are required by <em>{1}</em> and must also be enabled:\r\n<ol>{2}</ol>\r\nTo continue enabling all these products, <a href=\"{3}\">click here</a>.', 'vbulletin', 'vBulletin Solutions', 1142519066, '3.6.0 Beta 1'),
(1861, -1, 'admin_disabled_php_info', 'error', 'Sorry, the administrator has disabled PHP Info display.', 'vbulletin', '', 0, ''),
(1862, -1, 'adsense_not_deployed_upgrade_error', 'error', 'Your Google AdSense account is no longer associated with your vBulletin customer account. To redeploy Google AdSense, please associate a Google AdSense account in the vBulletin Members Area.', 'vbulletin', 'vBulletin Solutions', 1229643293, '3.8.0 Beta 4'),
(1863, -1, 'after_upgrade_360rc1', 'error', '<strong>As of vBulletin 3.6.0 RC1</strong>\r\n<ul>\r\n	<li>The <strong>Allow Signatures</strong> option has been removed. If you had this option disabled, you should use signature permissions to deny signatures for specific usergroups.</li>\r\n	<li>Apple&trade; has updated the iTunes podcast categories. We have followed suit and updated the categories within vBulletin. You will need to edit any podcasting forums and update to the proper category</li>\r\n</ul>', 'vbulletin', 'vBulletin Solutions', 1152214461, '3.6.0 Release Candidate 1'),
(1864, -1, 'after_upgrade_36_update_counters', 'error', 'After upgrading to vBulletin 3.6, you <strong>must</strong> rebuild thread information and then forum information on <a href=\"misc.php?do=chooser\">this page</a>.<br />\r\n<br />\r\nClick \"Address\" to rebuild thread information now. Once this has completed, you should still rebuild forum information!', 'vbulletin', 'vBulletin Solutions', 1150127028, '3.6.0 Beta 2'),
(1865, -1, 'after_upgrade_37_image_verification_disabled', 'error', 'vBulletin 3.7 removes the \"Simple Type\" option for GD-based image verification as it was not reliable at stopping bots. An alternative method for image verification is available, but your server does not appear to be compatible with this method.<br />\r\n<br />\r\nHuman verification is currently disabled. If you wish to verify that visitors are human, please select an alternative verification method by clicking \"Address\".', 'vbulletin', 'vBulletin Solutions', 1210088263, '3.7.1'),
(1866, -1, 'after_upgrade_37_moderator_permissions', 'error', 'vBulletin 3.7 adds additional moderator permissions. Values for these new permissions were determined based on existing permissions. Please review these permissions to ensure that they are correct.', 'vbulletin', 'vBulletin Solutions', 1209462374, '3.7.0'),
(1867, -1, 'after_upgrade_37_modified_css', 'error', 'You have one or more styles with custom CSS in the first (upper) <em>Additional CSS Definitions</em> field. You should move these custom declarations to the second (lower) field. Modified text will appear in RED and needs to be reverted after moving the custom CSS to the second field.<br /><br />\r\n\r\nFailure to do this will most likely result in the HTML of your forum not being presented properly.', 'vbulletin', 'vBulletin Solutions', 1201305954, '3.7.0 Beta 5'),
