(2045, -1, 'forumpasswordincorrect', 'error', '<p>The password you entered was incorrect. Please try again.<br />\r\n<b>Note</b>: This requires cookies to be enabled!</p>\r\n\r\n<form action=\"forumdisplay.php?do=doenterpwd\" method=\"post\">\r\n<input type=\"hidden\" name=\"s\" value=\"{1}\" />\r\n<input type=\"hidden\" name=\"do\" value=\"doenterpwd\" />\r\n<input type=\"hidden\" name=\"url\" value=\"{2}\" />\r\n<input type=\"hidden\" name=\"forumid\" value=\"{3}\" />\r\n{4}\r\n\r\n<table cellpadding=\"{5}\" cellspacing=\"{6}\" border=\"0\" align=\"center\">\r\n<tr>\r\n	<td><b>Password:</b></td>\r\n	<td><input type=\"password\" class=\"bginput\" name=\"newforumpwd\" /></td>\r\n	<td><input type=\"submit\" class=\"button\" value=\"Login!\" accesskey=\"s\" /></td>\r\n</tr>\r\n</table>\r\n\r\n</form>', 'vbulletin', 'vBulletin Solutions', 1142519066, '3.6.0 Beta 1'),
(2046, -1, 'forumpasswordmissing', 'error', '<p>Your administrator has required a password to access this forum. Please enter this password now.<br />\r\nNote: This requires cookies!</p>\r\n\r\n<form action=\"forumdisplay.php?do=doenterpwd\" method=\"post\">\r\n<input type=\"hidden\" name=\"s\" value=\"{1}\" />\r\n<input type=\"hidden\" name=\"do\" value=\"doenterpwd\" />\r\n<input type=\"hidden\" name=\"url\" value=\"{2}\" />\r\n<input type=\"hidden\" name=\"forumid\" value=\"{3}\" />\r\n<input type=\"hidden\" name=\"forceredirect\" value=\"1\" />\r\n{4}\r\n\r\n<table cellpadding=\"{5}\" cellspacing=\"{6}\" border=\"0\" align=\"center\">\r\n<tr>\r\n	<td><b>Password:</b></td>\r\n	<td><input type=\"password\" class=\"bginput\" name=\"newforumpwd\" /></td>\r\n	<td><input type=\"submit\" class=\"button\" value=\"Login!\" accesskey=\"s\" /></td>\r\n</tr>\r\n</table>\r\n\r\n</form>', 'vbulletin', 'vBulletin Solutions', 1142519066, '3.6.0 Beta 1'),
