(7701, -1, 'adminpermissions_edit_canadmincron_text', 'cphelptext', 'This setting determines whether an admin will be able to access the Scheduled Tasks area of the Admin CP.', 'vbulletin', 'vBulletin Solutions', 0, ''),
(7702, -1, 'adminpermissions_edit_canadmincron_title', 'cphelptext', 'Can Administer Cron', 'vbulletin', 'vBulletin Solutions', 0, ''),
(7703, -1, 'adminpermissions_edit_canadminmaintain_text', 'cphelptext', 'This setting determines whether an admin will be able to access the Maintenance area of the Admin CP.<br />\r\n<br />\r\nEnabling this allows an admin to potentially run code directly on your server, please ensure you trust the admin prior to enabling this permission.', 'vbulletin', 'vBulletin Solutions', 1194863484, '3.7.0 Beta 1'),
(7704, -1, 'adminpermissions_edit_canadminmaintain_title', 'cphelptext', 'Can Run Maintenance Tools', 'vbulletin', 'vBulletin Solutions', 0, ''),
(7705, -1, 'adminpermissions_edit_canadminplugins_text', 'cphelptext', 'This setting determines whether or not an admin will be able to manage the plugins used by your forum.<br />\r\n<br />\r\nEnabling this allows an admin to run code directly on your server, please ensure you trust the admin prior to enabling this permission.', 'vbulletin', 'vBulletin Solutions', 1194863445, '3.7.0 Beta 1'),
