(8813, -1, 'options_options_sg_allowed_bbcode_text', 'cphelptext', 'Use this option to specify which (if any) BB code tags your visitors may use when composing social group messages.\r\n\r\nBy default, Basic (B, I, U), Color and Link (URL, EMAIL, THREAD, POST) tags are enabled.', 'vbulletin', 'vBulletin Solutions', 1206966090, '3.7.0 Release Candidate 2'),
(8814, -1, 'options_options_sg_allowed_bbcode_title', 'cphelptext', 'Allowed BB Code Tags in Social Group Messages', 'vbulletin', 'vBulletin Solutions', 1205424027, '3.7.0 Release Candidate 1'),
(8815, -1, 'options_options_sg_allow_delete_empty_group_text', 'cphelptext', 'If this option is set to yes, the owner of a social group will always be able to delete the group if there are no other members. This is independent of the user group permission. If you set this to no, user group permissions will always be respected.<br />\r\n<br />\r\nSetting this to yes can allow users to clean up unpopular groups, but it can also create a loophole. An owner may be able to kick out all the members of a group and then delete it, thereby getting around the delete group permission.', 'vbulletin', 'vBulletin Solutions', 1211899263, '3.7.1'),
(8816, -1, 'options_options_sg_allow_delete_empty_group_title', 'cphelptext', 'Allow Owners to Delete Social Group if Empty', 'vbulletin', 'vBulletin Solutions', 1211899263, '3.7.1'),
(8817, -1, 'options_options_sg_allow_join_to_view_text', 'cphelptext', 'With this option enabled, social group owners may set up their groups in a manner that prevents non-members from viewing any of the group\'s content including messages and pictures.<br />\r\n<br />\r\nIf you do not want group owners to be able to do this, disable this option.', 'vbulletin', 'vBulletin Solutions', 1205423515, '3.7.0 Release Candidate 1'),
(8818, -1, 'options_options_sg_allow_join_to_view_title', 'cphelptext', 'Allow Join-to-View Groups', 'vbulletin', 'vBulletin Solutions', 1205423515, '3.7.0 Release Candidate 1'),
(8819, -1, 'options_options_sg_allow_owner_mod_queue_text', 'cphelptext', 'A group owner with the <em>Manage Own Social Groups\' Content</em> usergroup permission will be able to create or edit their social groups settings to force all new messages into the moderation queue with this setting enabled.<br />\r\n<br />\r\nIf they do this, messages will not appear to normal board users until approved by the group owner or other board staff member.', 'vbulletin', 'vBulletin Solutions', 1207560752, '3.7.0 Release Candidate 3'),
(8820, -1, 'options_options_sg_allow_owner_mod_queue_title', 'cphelptext', 'Allow Groups Owners to Force New Group Messages into Moderation Queue', 'vbulletin', 'vBulletin Solutions', 1205423372, '3.7.0 Release Candidate 1'),
(8821, -1, 'options_options_sg_category_cloud_size_text', 'cphelptext', 'This setting allows you to define the number of categories to display in the Social Group Overview.<br />\r\n<br />\r\n<b>Note: </b>This number must be at least 1.', 'vbulletin', 'vBulletin Solutions', 1218111503, '3.8.0 Alpha 1'),
(8822, -1, 'options_options_sg_category_cloud_size_title', 'cphelptext', 'Category Cloud Size', 'vbulletin', 'vBulletin Solutions', 1218111503, '3.8.0 Alpha 1'),
(8823, -1, 'options_options_sg_enablesocialgroupicons_text', 'cphelptext', 'If this is enabled users who create groups will be able to upload a group icon that will be displayed when viewing the group, and as a smaller version when viewing group listings.<br /><br />\r\n<br />\r\n<strong>Note: </strong>Social Group Image Icons are always limited to 200px by 200px and thumbnails are limited to 80px by 80px.', 'vbulletin', 'vBulletin Solutions', 1218111803, '3.8.0 Alpha 1'),
