(8825, -1, 'options_options_sg_enable_owner_only_discussions_text', 'cphelptext', 'If this is set to \'yes\' then users with the \'Can Limit Discussions in Own Groups to the Group Owner\' permission will be able to create Social Groups where only they can create new discussions.  Other users will still be able to post messages in the discussions as normal.', 'vbulletin', 'vBulletin Solutions', 1210943695, '3.7.1'),
(8826, -1, 'options_options_sg_enable_owner_only_discussions_title', 'cphelptext', 'Allow Group Owners to Limit New Discussions to Themselves', 'vbulletin', 'vBulletin Solutions', 1210943695, '3.7.1'),
(8827, -1, 'options_options_sg_maxperpage_text', 'cphelptext', 'This setting allows you to limit the number of groups users may display per page when listing social groups.<br />\r\n<br />\r\n<b>Note: </b>This number must be at least 1.', 'vbulletin', 'vBulletin Solutions', 1218113753, '3.8.0 Alpha 1'),
