(8829, -1, 'options_options_sg_name_maxchars_text', 'cphelptext', 'Enter a number of characters that define the maximum length for the name of user-created social groups.<br />\r\n<br />\r\nIf a user enters a name longer than this limit, an error will be generated and the name will be rejected.', 'vbulletin', 'vBulletin Solutions', 1205423033, '3.7.0 Release Candidate 1'),
(8830, -1, 'options_options_sg_name_maxchars_title', 'cphelptext', 'Social Group Name Maximum Length', 'vbulletin', 'vBulletin Solutions', 1205423033, '3.7.0 Release Candidate 1'),
(8831, -1, 'options_options_sg_newgroups_count_text', 'cphelptext', 'This setting allows you to define the number of groups displayed in the Newest Groups section of the Social Groups Overview.<br />\r\n<br />\r\n<b>Note: </b>This number must be at least 1.', 'vbulletin', 'vBulletin Solutions', 1218111541, '3.8.0 Alpha 1'),
