(10081, -1, 'user_add_password_text', 'cphelptext', 'Enter the user\'s password here.', 'vbulletin', 'vBulletin Solutions', 0, ''),
(10082, -1, 'user_add_password_title', 'cphelptext', 'Password', 'vbulletin', 'vBulletin Solutions', 0, ''),
(10083, -1, 'user_add_edit_adminavatar_text', 'cphelptext', 'This option allows the user to keep their custom avatar in the event that they lose permission to upload custom avatars.\r\n\r\nIf the user is moved to an usergroup that doesn\'t allow custom avatars; the user\'s avatar will not be visible in posts, their profile, and the member\'s list unless this option is enabled.\r\n\r\nThis option does not allow the user to change their avatar. Usergroup permission is required to accomplish that task.\r\n\r\nIf the admin changes or gives an a user a custom avatar when the user doesn\'t have usergroup permission to have one, this option will be automatically enabled.', 'vbulletin', 'vBulletin Solutions', 1144687826, '3.6.0 Beta 1'),
(10084, -1, 'user_add_edit_adminavatar_title', 'cphelptext', 'Keep Custom Avatar', 'vbulletin', 'vBulletin Solutions', 1144687826, '3.6.0 Beta 1'),
(10085, -1, 'user_add_edit_adminprofilepic_text', 'cphelptext', 'This option allows the user to keep their profile picture in the event that they lose permission to upload profile pictures.\r\n\r\nIf the user is moved to an usergroup that doesn\'t allow profile pictures; the user\'s picture will not be visible in their profile or on the member\'s list unless this option is enabled.\r\n\r\nThis option does not allow the user to change their picture. Usergroup permission is required to accomplish that task.\r\n\r\nIf the admin changes or gives an a user a profile picture when the user doesn\'t have usergroup permission to have one, this option will be automatically enabled.', 'vbulletin', 'vBulletin Solutions', 1144687906, '3.6.0 Beta 1'),
(10086, -1, 'user_add_edit_adminprofilepic_title', 'cphelptext', 'Keep Custom Profile Pic', 'vbulletin', 'vBulletin Solutions', 1144687906, '3.6.0 Beta 1'),
