(10204, -1, 'user_edit_receivepmbuddies_title', 'cphelptext', 'Receive Private Messages only from Contacts/Moderators', 'vbulletin', 'vBulletin Solutions', 1196766083, '3.7.0 Beta 1'),
(10205, -1, 'user_edit_vm_contactonly_text', 'cphelptext', 'When this option is set to yes, only Contacts of the user, or Moderators and Administrators may post a Visitor Message for this user.', 'vbulletin', 'vBulletin Solutions', 1207920870, '3.7.0 Release Candidate 4'),
(10206, -1, 'user_edit_vm_contactonly_title', 'cphelptext', 'Limit usage of Visitor Messages to Contacts and Moderators', 'vbulletin', 'vBulletin Solutions', 1207920870, '3.7.0 Release Candidate 4'),
