(10496, -1, 'usergroup_add_edit_cananimatesigpic_title', 'cphelptext', 'Can Upload Animated GIF for Signature', 'vbulletin', 'vBulletin Solutions', 1142519066, '3.6.0 Beta 1'),
(10497, -1, 'usergroup_add_edit_canprofilepic_text', 'cphelptext', 'This permission will allow members of this group to upload a profile picture on the <a href=\"../profile.php?do=editprofilepic\" target=\"_blank\">Edit Profile Picture</a> page in their User CP.  Profile pictures are uploaded from the user\'s computer or from a URL and are stored on your web server.<br /><br />\r\n\r\nProfile pictures must be enabled in your <a href=\"options.php?dogroup=userpix&amp;do=options\" target=\"_blank\">vBulletin options</a> for this setting to have any effect.', 'vbulletin', 'vBulletin Solutions', 0, ''),
