(10499, -1, 'usergroup_add_edit_sigpicmaxheight_text', 'cphelptext', 'If users can upload an image for their signature, this limits the maximum height of the image in pixels. You may use 0 to specify no limit.', 'vbulletin', 'vBulletin Solutions', 1142519066, '3.6.0 Beta 1'),
(10500, -1, 'usergroup_add_edit_sigpicmaxheight_title', 'cphelptext', 'Signature Image Maximum Height (pixels)', 'vbulletin', 'vBulletin Solutions', 1142519066, '3.6.0 Beta 1'),
(10501, -1, 'usergroup_add_edit_sigpicmaxwidth_text', 'cphelptext', 'If users can upload an image for their signature, this limits the maximum width of the image in pixels. You may use 0 to specify no limit.', 'vbulletin', 'vBulletin Solutions', 1142519066, '3.6.0 Beta 1'),
