	color: #22229C;\r\n}\r\na:visited, body_avisited\r\n{\r\n	color: #22229C;\r\n}\r\na:hover, a:active, body_ahover\r\n{\r\n	color: #FF4400;\r\n}\r\n.page\r\n{\r\n	background: #FFFFFF;\r\n	color: #000000;\r\n}\r\ntd, th, p, li\r\n{\r\n	font: 10pt verdana, geneva, lucida, \'lucida grande\', arial, helvetica, sans-serif;\r\n}\r\n.tborder\r\n{\r\n	background: #D1D1E1;\r\n	color: #000000;\r\n	border: 1px solid #0B198C;\r\n}\r\n.tcat\r\n{\r\n	background: #869BBF url(images/gradients/gradient_tcat.gif) repeat-x top left;\r\n	color: #FFFFFF;\r\n	font: bold 10pt verdana, geneva, lucida, \'lucida grande\', arial, helvetica, sans-serif;\r\n}\r\n.tcat a:link, .tcat_alink\r\n{\r\n	color: #ffffff;\r\n	text-decoration: none;\r\n}\r\n.tcat a:visited, .tcat_avisited\r\n{\r\n	color: #ffffff;\r\n	text-decoration: none;\r\n}\r\n.tcat a:hover, .tcat a:active, .tcat_ahover\r\n{\r\n	color: #FFFF66;\r\n	text-decoration: underline;\r\n}\r\n.thead\r\n{\r\n	background: #5C7099 url(images/gradients/gradient_thead.gif) repeat-x top left;\r\n	color: #FFFFFF;\r\n	font: bold 11px tahoma, verdana, geneva, lucida, \'lucida grande\', arial, helvetica, sans-serif;\r\n}\r\n.thead a:link, .thead_alink\r\n{\r\n	color: #FFFFFF;\r\n}\r\n.thead a:visited, .thead_avisited\r\n{\r\n	color: #FFFFFF;\r\n}\r\n.thead a:hover, .thead a:active, .thead_ahover\r\n{\r\n	color: #FFFF00;\r\n}\r\n.tfoot\r\n{\r\n	background: #3E5C92;\r\n	color: #E0E0F6;\r\n}\r\n.tfoot a:link, .tfoot_alink\r\n{\r\n	color: #E0E0F6;\r\n}\r\n.tfoot a:visited, .tfoot_avisited\r\n{\r\n	color: #E0E0F6;\r\n}\r\n.tfoot a:hover, .tfoot a:active, .tfoot_ahover\r\n{\r\n	color: #FFFF66;\r\n}\r\n.alt1, .alt1Active\r\n{\r\n	background: #F5F5FF;\r\n	color: #000000;\r\n}\r\n.alt2, .alt2Active\r\n{\r\n	background: #E1E4F2;\r\n	color: #000000;\r\n}\r\n.inlinemod\r\n{\r\n	background: #FFFFCC;\r\n	color: #000000;\r\n}\r\n.wysiwyg\r\n{\r\n	background: #F5F5FF;\r\n	color: #000000;\r\n	font: 10pt verdana, geneva, lucida, \'lucida grande\', arial, helvetica, sans-serif;\r\n	margin: 5px 10px 10px 10px;\r\n	padding: 0px;\r\n}\r\n.wysiwyg a:link, .wysiwyg_alink\r\n{\r\n	color: #22229C;\r\n}\r\n.wysiwyg a:visited, .wysiwyg_avisited\r\n{\r\n	color: #22229C;\r\n}\r\n.wysiwyg a:hover, .wysiwyg a:active, .wysiwyg_ahover\r\n{\r\n	color: #FF4400;\r\n}\r\ntextarea, .bginput\r\n{\r\n	font: 10pt verdana, geneva, lucida, \'lucida grande\', arial, helvetica, sans-serif;\r\n}\r\n.bginput option, .bginput optgroup\r\n{\r\n	font-size: 10pt;\r\n	font-family: verdana, geneva, lucida, \'lucida grande\', arial, helvetica, sans-serif;\r\n}\r\n.button\r\n{\r\n	font: 11px verdana, geneva, lucida, \'lucida grande\', arial, helvetica, sans-serif;\r\n}\r\nselect\r\n{\r\n	font: 11px verdana, geneva, lucida, \'lucida grande\', arial, helvetica, sans-serif;\r\n}\r\noption, optgroup\r\n{\r\n	font-size: 11px;\r\n	font-family: verdana, geneva, lucida, \'lucida grande\', arial, helvetica, sans-serif;\r\n}\r\n.smallfont\r\n{\r\n	font: 11px verdana, geneva, lucida, \'lucida grande\', arial, helvetica, sans-serif;\r\n}\r\n.time\r\n{\r\n	color: #666686;\r\n}\r\n.navbar\r\n{\r\n	font: 11px verdana, geneva, lucida, \'lucida grande\', arial, helvetica, sans-serif;\r\n}\r\n.highlight\r\n{\r\n	color: #FF0000;\r\n	font-weight: bold;\r\n}\r\n.fjsel\r\n{\r\n	background: #3E5C92;\r\n	color: #E0E0F6;\r\n}\r\n.fjdpth0\r\n{\r\n	background: #F7F7F7;\r\n	color: #000000;\r\n}\r\n.panel\r\n{\r\n	background: #E4E7F5 url(images/gradients/gradient_panel.gif) repeat-x top left;\r\n	color: #000000;\r\n	padding: 10px;\r\n	border: 2px outset;\r\n}\r\n.panelsurround\r\n{\r\n	background: #D1D4E0 url(images/gradients/gradient_panelsurround.gif) repeat-x top left;\r\n	color: #000000;\r\n}\r\nlegend\r\n{\r\n	color: #22229C;\r\n	font: 11px tahoma, verdana, geneva, lucida, \'lucida grande\', arial, helvetica, sans-serif;\r\n}\r\n.vbmenu_control\r\n{\r\n	background: #738FBF;\r\n	color: #FFFFFF;\r\n	font: bold 11px tahoma, verdana, geneva, lucida, \'lucida grande\', arial, helvetica, sans-serif;\r\n	padding: 3px 6px 3px 6px;\r\n	white-space: nowrap;\r\n}\r\n.vbmenu_control a:link, .vbmenu_control_alink\r\n{\r\n	color: #FFFFFF;\r\n	text-decoration: none;\r\n}\r\n.vbmenu_control a:visited, .vbmenu_control_avisited\r\n{\r\n	color: #FFFFFF;\r\n	text-decoration: none;\r\n}\r\n.vbmenu_control a:hover, .vbmenu_control a:active, .vbmenu_control_ahover\r\n{\r\n	color: #FFFFFF;\r\n	text-decoration: underline;\r\n}\r\n.vbmenu_popup\r\n{\r\n	background: #FFFFFF;\r\n	color: #000000;\r\n	border: 1px solid #0B198C;\r\n}\r\n.vbmenu_option\r\n{\r\n	background: #BBC7CE;\r\n	color: #000000;\r\n	font: 11px verdana, geneva, lucida, \'lucida grande\', arial, helvetica, sans-serif;\r\n	white-space: nowrap;\r\n	cursor: pointer;\r\n}\r\n.vbmenu_option a:link, .vbmenu_option_alink\r\n{\r\n	color: #22229C;\r\n	text-decoration: none;\r\n}\r\n.vbmenu_option a:visited, .vbmenu_option_avisited\r\n{\r\n	color: #22229C;\r\n	text-decoration: none;\r\n}\r\n.vbmenu_option a:hover, .vbmenu_option a:active, .vbmenu_option_ahover\r\n{\r\n	color: #FFFFFF;\r\n	text-decoration: none;\r\n}\r\n.vbmenu_hilite\r\n{\r\n	background: #8A949E;\r\n	color: #FFFFFF;\r\n	font: 11px verdana, geneva, lucida, \'lucida grande\', arial, helvetica, sans-serif;\r\n	white-space: nowrap;\r\n	cursor: pointer;\r\n}\r\n.vbmenu_hilite a:link, .vbmenu_hilite_alink\r\n{\r\n	color: #FFFFFF;\r\n	text-decoration: none;\r\n}\r\n.vbmenu_hilite a:visited, .vbmenu_hilite_avisited\r\n{\r\n	color: #FFFFFF;\r\n	text-decoration: none;\r\n}\r\n.vbmenu_hilite a:hover, .vbmenu_hilite a:active, .vbmenu_hilite_ahover\r\n{\r\n	color: #FFFFFF;\r\n	text-decoration: none;\r\n}\r\n/* ***** styling for \'big\' usernames on postbit etc. ***** */\r\n.bigusername { font-size: 14pt; }\r\n\r\n/* ***** small padding on \'thead\' elements ***** */\r\ntd.thead, th.thead, div.thead { padding: 4px; }\r\n\r\n/* ***** basic styles for multi-page nav elements */\r\n.pagenav a { text-decoration: none; }\r\n.pagenav td { padding: 2px 4px 2px 4px; }\r\n\r\n/* ***** de-emphasized text */\r\n.shade, a.shade:link, a.shade:visited { color: #777777; text-decoration: none; }\r\na.shade:active, a.shade:hover { color: #FF4400; text-decoration: underline; }\r\n.tcat .shade, .thead .shade, .tfoot .shade { color: #DDDDDD; }\r\n\r\n/* ***** define margin and font-size for elements inside panels ***** */\r\n.fieldset { margin-bottom: 6px; }\r\n.fieldset, .fieldset td, .fieldset p, .fieldset li { font-size: 11px; }\r\n</style>\r\n<link rel=\"stylesheet\" type=\"text/css\" href=\"clientscript/vbulletin_important.css?v=\" />', 'a:27:{s:11:\"cellpadding\";s:1:\"6\";s:11:\"cellspacing\";s:1:\"1\";s:14:\"codeblockwidth\";s:5:\"640px\";s:10:\"formspacer\";s:1:\"3\";s:9:\"formwidth\";s:5:\"640px\";s:16:\"formwidth_usercp\";s:5:\"480px\";s:11:\"htmldoctype\";s:121:\"<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\";s:16:\"htmlextrasfolder\";s:10:\"htmlextras\";s:12:\"imagesfolder\";s:6:\"images\";s:13:\"imgdir_attach\";s:13:\"images/attach\";s:13:\"imgdir_button\";s:14:\"images/buttons\";s:13:\"imgdir_editor\";s:13:\"images/editor\";s:11:\"imgdir_misc\";s:11:\"images/misc\";s:11:\"imgdir_poll\";s:12:\"images/polls\";s:13:\"imgdir_rating\";s:13:\"images/rating\";s:17:\"imgdir_reputation\";s:17:\"images/reputation\";s:17:\"imgdir_statusicon\";s:17:\"images/statusicon\";s:12:\"messagewidth\";s:5:\"540px\";s:19:\"messagewidth_usercp\";s:5:\"380px\";s:16:\"outerborderwidth\";s:2:\"20\";s:15:\"outertablewidth\";s:4:\"100%\";s:10:\"spacersize\";s:2:\"25\";s:10:\"tablewidth\";s:4:\"100%\";s:16:\"textareacols_ie4\";s:2:\"70\";s:16:\"textareacols_ns4\";s:2:\"50\";s:16:\"textareacols_ns6\";s:2:\"65\";s:10:\"titleimage\";s:37:\"images/misc/vbulletin3_logo_white.gif\";}', '', 'a:8:{s:14:\"pi_button_down\";a:4:{i:0;s:7:\"#98B5E2\";i:1;s:7:\"#000000\";i:2;s:3:\"0px\";i:3;s:17:\"1px solid #316AC5\";}s:15:\"pi_button_hover\";a:4:{i:0;s:7:\"#C1D2EE\";i:1;s:7:\"#000000\";i:2;s:3:\"0px\