(73, -1, 'albumbit', '<tr>\r\n	$template_hook[albumbit_start]\r\n	<td class=\\\"alt2\\\" valign=\\\"middle\\\" align=\\\"center\\\">\r\n		\".(($album[\'coverthumburl\']) ? (\"\r\n			<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$album[albumid]\\\"><img src=\\\"$album[coverthumburl]\\\" border=\\\"0\\\" alt=\\\"$vbphrase[picture]\\\" $album[coverdimensions] /></a>\r\n		\") : (\"\r\n			&nbsp;\r\n		\")).\"\r\n	</td>\r\n	<td class=\\\"alt1\\\" valign=\\\"middle\\\">\r\n		\".(($show[\'moderated\']) ? (\"<img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_misc]/moderated_small.gif\\\" alt=\\\"\" . construct_phrase(\"$vbphrase[x_moderated_pictures]\", \"$album[moderatedcount]\") . \"\\\" style=\\\"float:$stylevar[right]\\\" />\") : (\"\")).\"\r\n		<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$album[albumid]\\\"><strong>$album[title_html]</strong></a>\r\n		<div class=\\\"smallfont\\\">\r\n			$album[description_html]\r\n			\".(($show[\'personalalbum\']) ? (\"<span class=\\\"shade\\\">$albumtype</span>\") : (\"\")).\"\r\n		</div>\r\n	</td>\r\n	<td class=\\\"alt2\\\" valign=\\\"middle\\\" align=\\\"center\\\">$album[picturecount]</td>\r\n	<td class=\\\"alt1\\\" valign=\\\"middle\\\" nowrap=\\\"nowrap\\\">\r\n		\".(($album[\'lastpicturedate\']) ? (\"\r\n			$album[picturedate] \".((!$show[\'detailedtime\']) ? (\"<span class=\\\"time\\\">$album[picturetime]</span>\") : (\"\")).\"\r\n		\") : (\"\r\n			$vbphrase[none]\r\n		\")).\"\r\n	</td>\r\n	$template_hook[albumbit_end]\r\n</tr>', '<tr>\r\n	$template_hook[albumbit_start]\r\n	<td class=\"alt2\" valign=\"middle\" align=\"center\">\r\n		<if condition=\"$album[\'coverthumburl\']\">\r\n			<a href=\"album.php?$session[sessionurl]albumid=$album[albumid]\"><img src=\"$album[coverthumburl]\" border=\"0\" alt=\"$vbphrase[picture]\" $album[coverdimensions] /></a>\r\n		<else />\r\n			&nbsp;\r\n		</if>\r\n	</td>\r\n	<td class=\"alt1\" valign=\"middle\">\r\n		<if condition=\"$show[\'moderated\']\"><img class=\"inlineimg\" src=\"$stylevar[imgdir_misc]/moderated_small.gif\" alt=\"<phrase 1=\"$album[moderatedcount]\">$vbphrase[x_moderated_pictures]</phrase>\" style=\"float:$stylevar[right]\" /></if>\r\n		<a href=\"album.php?$session[sessionurl]albumid=$album[albumid]\"><strong>$album[title_html]</strong></a>\r\n		<div class=\"smallfont\">\r\n			$album[description_html]\r\n			<if condition=\"$show[\'personalalbum\']\"><span class=\"shade\">$albumtype</span></if>\r\n		</div>\r\n	</td>\r\n	<td class=\"alt2\" valign=\"middle\" align=\"center\">$album[picturecount]</td>\r\n	<td class=\"alt1\" valign=\"middle\" nowrap=\"nowrap\">\r\n		<if condition=\"$album[\'lastpicturedate\']\">\r\n			$album[picturedate] <if condition=\"!$show[\'detailedtime\']\"><span class=\"time\">$album[picturetime]</span></if>\r\n		<else />\r\n			$vbphrase[none]\r\n		</if>\r\n	</td>\r\n	$template_hook[albumbit_end]\r\n</tr>', 'template', 1218627606, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(74, -1, 'album_addgroup', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n$usercss\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - \" . construct_phrase(\"$vbphrase[xs_album_y]\", \"$userinfo[username]\", \"$albuminfo[title_html]\") . \" - $vbphrase[add_picture_to_groups]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<div id=\\\"usercss\\\">\r\n\r\n<form action=\\\"album.php?do=doaddgroup&amp;albumid=$albuminfo[albumid]&amp;pictureid=$pictureinfo[pictureid]\\\" method=\\\"post\\\">\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[add_picture_to_groups]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel floatcontainer\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n			\".(($pictureinfo[\'thumburl\']) ? (\"\r\n				<table width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" cellpadding=\\\"$stylevar[cellpadding]\\\">\r\n				<tr>\r\n					<td valign=\\\"middle\\\"><img src=\\\"$pictureinfo[thumburl]\\\" alt=\\\"$pictureinfo[caption_preview]\\\" border=\\\"0\\\" style=\\\"float: $stylevar[left]\\\" $pictureinfo[dimensions] /></td>\r\n					<td valign=\\\"top\\\" width=\\\"100%\\\">\r\n			\") : (\"\")).\"\r\n\r\n			<fieldset class=\\\"fieldset\\\">\r\n				<legend>$vbphrase[groups]</legend>\r\n				<table border=\\\"0\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" cellpadding=\\\"2\\\">\r\n					$groupbits\r\n				</table>\r\n			</fieldset>\r\n\r\n			\".(($pictureinfo[\'thumburl\']) ? (\"\r\n					</td>\r\n				</tr>\r\n				</table>\r\n			\") : (\"\")).\"\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"doaddgroup\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"albumid\\\" value=\\\"$albuminfo[albumid]\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"pictureid\\\" value=\\\"$pictureinfo[pictureid]\\\" />\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[add_picture_to_groups]\\\" accesskey=\\\"s\\\" tabindex=\\\"1\\\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n</form>\r\n\r\n</div>\r\n\r\n$footer\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n$usercss\r\n<title>$vboptions[bbtitle] - <phrase 1=\"$userinfo[username]\" 2=\"$albuminfo[title_html]\">$vbphrase[xs_album_y]</phrase> - $vbphrase[add_picture_to_groups]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<div id=\"usercss\">\r\n\r\n<form action=\"album.php?do=doaddgroup&amp;albumid=$albuminfo[albumid]&amp;pictureid=$pictureinfo[pictureid]\" method=\"post\">\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">$vbphrase[add_picture_to_groups]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel floatcontainer\">\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n			<if condition=\"$pictureinfo[\'thumburl\']\">\r\n				<table width=\"100%\" border=\"0\" cellspacing=\"$stylevar[cellspacing]\" cellpadding=\"$stylevar[cellpadding]\">\r\n				<tr>\r\n					<td valign=\"middle\"><img src=\"$pictureinfo[thumburl]\" alt=\"$pictureinfo[caption_preview]\" border=\"0\" style=\"float: $stylevar[left]\" $pictureinfo[dimensions] /></td>\r\n					<td valign=\"top\" width=\"100%\">\r\n			</if>\r\n\r\n			<fieldset class=\"fieldset\">\r\n				<legend>$vbphrase[groups]</legend>\r\n				<table border=\"0\" cellspacing=\"$stylevar[cellspacing]\" cellpadding=\"2\">\r\n					$groupbits\r\n				</table>\r\n			</fieldset>\r\n\r\n			<if condition=\"$pictureinfo[\'thumburl\']\">\r\n					</td>\r\n				</tr>\r\n				</table>\r\n			</if>\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n		<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n		<input type=\"hidden\" name=\"do\" value=\"doaddgroup\" />\r\n		<input type=\"hidden\" name=\"albumid\" value=\"$albuminfo[albumid]\" />\r\n		<input type=\"hidden\" name=\"pictureid\" value=\"$pictureinfo[pictureid]\" />\r\n		<input type=\"submit\" class=\"button\" value=\"$vbphrase[add_picture_to_groups]\" accesskey=\"s\" tabindex=\"1\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n</form>\r\n\r\n</div>\r\n\r\n$footer\r\n</body>\r\n</html>', 'template', 1208875378, 'vBulletin Solutions', '3.7.0 Release Candidate 4', 'vbulletin'),
(75, -1, 'album_addgroup_groupbit', '<tr>\r\n	<td>\r\n		<input type=\\\"checkbox\\\" name=\\\"groupids[$group[groupid]]\\\" value=\\\"$group[groupid]\\\" $group_checked />\r\n		<input type=\\\"hidden\\\" name=\\\"groupsshown[$group[groupid]]\\\" value=\\\"$group[groupid]\\\" />\r\n	</td>\r\n	<td width=\\\"100%\\\">\r\n		<strong>$group[name]</strong>\r\n		\".(($group[\'shortdescription\']) ? (\"<div class=\\\"smallfont\\\">$group[shortdescription]</div>\") : (\"\")).\"\r\n	</td>\r\n</tr>', '<tr>\r\n	<td>\r\n		<input type=\"checkbox\" name=\"groupids[$group[groupid]]\" value=\"$group[groupid]\" $group_checked />\r\n		<input type=\"hidden\" name=\"groupsshown[$group[groupid]]\" value=\"$group[groupid]\" />\r\n	</td>\r\n	<td width=\"100%\">\r\n		<strong>$group[name]</strong>\r\n		<if condition=\"$group[\'shortdescription\']\"><div class=\"smallfont\">$group[shortdescription]</div></if>\r\n	</td>\r\n</tr>', 'template', 1195485096, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
(76, -1, 'album_edit', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n$usercss\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - \".(($albuminfo[\'albumid\']) ? (\"$vbphrase[edit_album]\") : (\"$vbphrase[add_album]\")).\"</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<div id=\\\"usercss\\\">\r\n\r\n\".(($show[\'delete_option\']) ? (\"\r\n<form action=\\\"album.php?do=killalbum&amp;albumid=$albuminfo[albumid]\\\" method=\\\"post\\\">\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"killalbum\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"albumid\\\" value=\\\"$albuminfo[albumid]\\\" />\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		$vbphrase[delete_album]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n			<div class=\\\"smallfont\\\">\r\n				<span style=\\\"float: $stylevar[right]\\\"><input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[delete_album]\\\" accesskey=\\\"d\\\" tabindex=\\\"1\\\" /></span>\r\n				<input type=\\\"checkbox\\\" name=\\\"delete\\\" id=\\\"cb_delete\\\" value=\\\"1\\\" /><label for=\\\"cb_delete\\\">$vbphrase[to_delete_this_album]</label></div>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n</form>\r\n\r\n<br />\r\n\") : (\"\")).\"\r\n\r\n$errortable\r\n\r\n<form action=\\\"album.php?do=updatealbum&amp;u=$userinfo[userid]&amp;albumid=$formdata[albumid]\\\" method=\\\"post\\\">\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		\".(($albuminfo[\'title\']) ? (\"\r\n			<span class=\\\"smallfont normal\\\" style=\\\"float: $stylevar[right]\\\"><b>$vbphrase[album]</b>: <a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$albuminfo[albumid]\\\">$albuminfo[title_html]</a></span>\r\n		\") : (\"\")).\"\r\n		\".(($albuminfo[\'albumid\']) ? (\"$vbphrase[edit_album]\") : (\"$vbphrase[add_album]\")).\"\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\">\r\n			<table><tr><td align=\\\"$stylevar[left]\\\">\r\n			\".(($show[\'album_used_in_css\']) ? (\"\r\n				<fieldset style=\\\"margin-bottom: $stylevar[cellpadding]px\\\" class=\\\"fieldset\\\">\r\n					<div class=\\\"smallfont\\\" style=\\\"margin: $stylevar[cellpadding]px\\\">\r\n						$vbphrase[album_pictures_used_profile_styling]\r\n					</div>\r\n				</fieldset>\r\n			\") : (\"\")).\"\r\n\r\n			<div class=\\\"smallfont\\\">\r\n				$vbphrase[title]:\r\n				<div><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"title\\\" value=\\\"$formdata[title]\\\" size=\\\"50\\\" tabindex=\\\"1\\\" /></div>\r\n			</div>\r\n\r\n			<div style=\\\"margin-top: $stylevar[cellpadding]px\\\" class=\\\"smallfont\\\">\r\n				$vbphrase[description]: <span class=\\\"shade\\\">($vbphrase[bbcode_not_allowed])</span>\r\n				<div><textarea name=\\\"description\\\" rows=\\\"5\\\" cols=\\\"50\\\" tabindex=\\\"1\\\">$formdata[description]</textarea></div>\r\n			</div>\r\n\r\n			<div style=\\\"margin-top: $stylevar[cellpadding]px\\\" class=\\\"smallfont\\\">\r\n				$vbphrase[album_type]:\r\n				<div><label for=\\\"rb_albumtype_public\\\"><input type=\\\"radio\\\" name=\\\"albumtype\\\" value=\\\"public\\\"  id=\\\"rb_albumtype_public\\\" $formdata[albumtype_public] />$vbphrase[public]</label></div>\r\n				<div><label for=\\\"rb_albumtype_private\\\"><input type=\\\"radio\\\" name=\\\"albumtype\\\" value=\\\"private\\\" id=\\\"rb_albumtype_private\\\" $formdata[albumtype_private] />$vbphrase[private_only_visible_contacts_moderators]</label></div>\r\n				\".(($show[\'albumtype_profile\']) ? (\"<div><label for=\\\"rb_albumtype_profile\\\"><input type=\\\"radio\\\" name=\\\"albumtype\\\" value=\\\"profile\\\" id=\\\"rb_albumtype_profile\\\" $formdata[albumtype_profile] />$vbphrase[profile_pictures_modify_profile_style]</label></div>\") : (\"\")).\"\r\n			</div>\r\n			</td></tr></table>\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"updatealbum\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"albumid\\\" value=\\\"$formdata[albumid]\\\" />\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[submit]\\\" accesskey=\\\"s\\\" tabindex=\\\"1\\\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n</form>\r\n\r\n</div>\r\n\r\n$footer\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n$usercss\r\n<title>$vboptions[bbtitle] - <if condition=\"$albuminfo[\'albumid\']\">$vbphrase[edit_album]<else />$vbphrase[add_album]</if></title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<div id=\"usercss\">\r\n\r\n<if condition=\"$show[\'delete_option\']\">\r\n<form action=\"album.php?do=killalbum&amp;albumid=$albuminfo[albumid]\" method=\"post\">\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n<input type=\"hidden\" name=\"do\" value=\"killalbum\" />\r\n<input type=\"hidden\" name=\"albumid\" value=\"$albuminfo[albumid]\" />\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		$vbphrase[delete_album]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n			<div class=\"smallfont\">\r\n				<span style=\"float: $stylevar[right]\"><input type=\"submit\" class=\"button\" value=\"$vbphrase[delete_album]\" accesskey=\"d\" tabindex=\"1\" /></span>\r\n				<input type=\"checkbox\" name=\"delete\" id=\"cb_delete\" value=\"1\" /><label for=\"cb_delete\">$vbphrase[to_delete_this_album]</label></div>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n</form>\r\n\r\n<br />\r\n</if>\r\n\r\n$errortable\r\n\r\n<form action=\"album.php?do=updatealbum&amp;u=$userinfo[userid]&amp;albumid=$formdata[albumid]\" method=\"post\">\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		<if condition=\"$albuminfo[\'title\']\">\r\n			<span class=\"smallfont normal\" style=\"float: $stylevar[right]\"><b>$vbphrase[album]</b>: <a href=\"album.php?$session[sessionurl]albumid=$albuminfo[albumid]\">$albuminfo[title_html]</a></span>\r\n		</if>\r\n		<if condition=\"$albuminfo[\'albumid\']\">$vbphrase[edit_album]<else />$vbphrase[add_album]</if>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth]\">\r\n			<table><tr><td align=\"$stylevar[left]\">\r\n			<if condition=\"$show[\'album_used_in_css\']\">\r\n				<fieldset style=\"margin-bottom: $stylevar[cellpadding]px\" class=\"fieldset\">\r\n					<div class=\"smallfont\" style=\"margin: $stylevar[cellpadding]px\">\r\n						$vbphrase[album_pictures_used_profile_styling]\r\n					</div>\r\n				</fieldset>\r\n			</if>\r\n\r\n			<div class=\"smallfont\">\r\n				$vbphrase[title]:\r\n				<div><input type=\"text\" class=\"bginput\" name=\"title\" value=\"$formdata[title]\" size=\"50\" tabindex=\"1\" /></div>\r\n			</div>\r\n\r\n			<div style=\"margin-top: $stylevar[cellpadding]px\" class=\"smallfont\">\r\n				$vbphrase[description]: <span class=\"shade\">($vbphrase[bbcode_not_allowed])</span>\r\n				<div><textarea name=\"description\" rows=\"5\" cols=\"50\" tabindex=\"1\">$formdata[description]</textarea></div>\r\n			</div>\r\n\r\n			<div style=\"margin-top: $stylevar[cellpadding]px\" class=\"smallfont\">\r\n				$vbphrase[album_type]:\r\n				<div><label for=\"rb_albumtype_public\"><input type=\"radio\" name=\"albumtype\" value=\"public\"  id=\"rb_albumtype_public\" $formdata[albumtype_public] />$vbphrase[public]</label></div>\r\n				<div><label for=\"rb_albumtype_private\"><input type=\"radio\" name=\"albumtype\" value=\"private\" id=\"rb_albumtype_private\" $formdata[albumtype_private] />$vbphrase[private_only_visible_contacts_moderators]</label></div>\r\n				<if condition=\"$show[\'albumtype_profile\']\"><div><label for=\"rb_albumtype_profile\"><input type=\"radio\" name=\"albumtype\" value=\"profile\" id=\"rb_albumtype_profile\" $formdata[albumtype_profile] />$vbphrase[profile_pictures_modify_profile_style]</label></div></if>\r\n			</div>\r\n			</td></tr></table>\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n		<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n		<input type=\"hidden\" name=\"do\" value=\"updatealbum\" />\r\n		<input type=\"hidden\" name=\"albumid\" value=\"$formdata[albumid]\" />\r\n		<input type=\"submit\" class=\"button\" value=\"$vbphrase[submit]\" accesskey=\"s\" tabindex=\"1\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n</form>\r\n\r\n</div>\r\n\r\n$footer\r\n</body>\r\n</html>', 'template', 1208875679, 'vBulletin Solutions', '3.7.0 Release Candidate 4', 'vbulletin'),
(77, -1, 'album_latestbit', '<table class=\\\"album\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\">\r\n	<tr>\r\n		<td>\r\n			<table border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\">\r\n				<tr>\r\n					<td valign=\\\"middle\\\">\r\n						<table border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" width=\\\"1px\\\" align=\\\"center\\\">\r\n						<tr style=\\\"border-bottom:1px solid rgb(133,103,29)\\\">\r\n							<td class=\\\"album_tab\\\">\r\n								<img src=\\\"$stylevar[imgdir_misc]/album_folder_tab.png\\\" alt=\\\"tab\\\" /><br />\r\n							</td>\r\n						</tr>\r\n						<tr>\r\n							<td class=\\\"smallfont albumthumb\\\" align=\\\"center\\\" valign=\\\"middle\\\">\r\n							\".(($album[\'coverthumburl\']) ? (\"\r\n								<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$album[albumid]\\\">\r\n								<img class=\\\"album_cover\\\" src=\\\"$album[coverthumburl]\\\" alt=\\\"$vbphrase[picture]\\\" $album[coverdimensions] /></a><br />\r\n							\") : (\"\r\n								<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$albuminfo[albumid]\\\">$vbphrase[picture]</a>\r\n							\")).\"\r\n							\".(($show[\'moderation\']) ? (\"<br /><span class=\\\"shade\\\">$vbphrase[picture_moderated]</span>\") : (\"\")).\"\r\n							</td>\r\n						</tr>\r\n						</table>\r\n					</td>\r\n				</tr>\r\n				<tr>\r\n					<td class=\\\"album_details\\\" valign=\\\"top\\\" align=\\\"center\\\">\r\n					<div class=\\\"album_details\\\">\r\n						<div class=\\\"albumtitle smallfont\\\"><a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$album[albumid]\\\">$album[title_html]</a></div>\r\n						<div class=\\\"albumusername smallfont\\\"><a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$album[userid]\\\">$album[username]</a>, $album[picturedate]</div>\r\n					</div>\r\n					</td>\r\n				</tr>\r\n			</table>\r\n		</td>\r\n	</tr>\r\n</table>', '<table class=\"album\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n	<tr>\r\n		<td>\r\n			<table border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n				<tr>\r\n					<td valign=\"middle\">\r\n						<table border=\"0\" cellspacing=\"0\" cellpadding=\"0\" width=\"1px\" align=\"center\">\r\n						<tr style=\"border-bottom:1px solid rgb(133,103,29)\">\r\n							<td class=\"album_tab\">\r\n								<img src=\"$stylevar[imgdir_misc]/album_folder_tab.png\" alt=\"tab\" /><br />\r\n							</td>\r\n						</tr>\r\n						<tr>\r\n							<td class=\"smallfont albumthumb\" align=\"center\" valign=\"middle\">\r\n							<if condition=\"$album[\'coverthumburl\']\">\r\n								<a href=\"album.php?$session[sessionurl]albumid=$album[albumid]\">\r\n								<img class=\"album_cover\" src=\"$album[coverthumburl]\" alt=\"$vbphrase[picture]\" $album[coverdimensions] /></a><br />\r\n							<else />\r\n								<a href=\"album.php?$session[sessionurl]albumid=$albuminfo[albumid]\">$vbphrase[picture]</a>\r\n							</if>\r\n							<if condition=\"$show[\'moderation\']\"><br /><span class=\"shade\">$vbphrase[picture_moderated]</span></if>\r\n							</td>\r\n						</tr>\r\n						</table>\r\n					</td>\r\n				</tr>\r\n				<tr>\r\n					<td class=\"album_details\" valign=\"top\" align=\"center\">\r\n					<div class=\"album_details\">\r\n						<div class=\"albumtitle smallfont\"><a href=\"album.php?$session[sessionurl]albumid=$album[albumid]\">$album[title_html]</a></div>\r\n						<div class=\"albumusername smallfont\"><a href=\"member.php?$session[sessionurl]u=$album[userid]\">$album[username]</a>, $album[picturedate]</div>\r\n					</div>\r\n					</td>\r\n				</tr>\r\n			</table>\r\n		</td>\r\n	</tr>\r\n</table>', 'template', 1233923352, 'vBulletin Solutions', '3.8.2', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(78, -1, 'album_list', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n$usercss\r\n<style type=\\\"text/css\\\">\r\n<!--\r\n.albumthumb {\r\n	border: 1px solid rgb(133,103,29);\r\n	border-top: 0px;\r\n	background: url(\'$stylevar[imgdir_misc]/album_folder_bg.png\') top repeat-x;\r\n	background-color: #FFD677\r\n}\r\n.albumtitle {\r\n	font-weight:bold\r\n}\r\n.albumtitle a:link, .albumtitle a:visited {\r\n	text-decoration:none\r\n}\r\n.albumtitle a:hover, .albumtitle a:active {\r\n	text-decoration:underline\r\n}\r\n.albumusername a:link, .albumusername a:visited {\r\n	text-decoration:none\r\n}\r\n.albumusername a:hover, .albumusername a:active {\r\n	text-decoration:underline\r\n}\r\ntable.album {\r\n	width:{$album_width}px;\r\n	overflow: hidden;\r\n	height:{$album_height}px;\r\n	margin:16px;\r\n	float:$stylevar[left];\r\n}\r\ntd.album_tab {\r\n	background: url(\'$stylevar[imgdir_misc]/album_folder_top_bg.gif\');\r\n}\r\n.album_details {\r\n	display:block;\r\n	width:{$album_width}px;\r\n	height: 40px;\r\n	overflow:hidden\r\n}\r\nimg.album_cover\r\n{\r\n	margin:$stylevar[cellpadding]px;\r\n	border:1px solid rgb(133,103,29)\r\n}\r\n-->\r\n</style>\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $custompagetitle</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n$template_hook[album_overview_before_latest]\r\n\r\n\".(($latestbits) ? (\"\r\n<table width=\\\"100%\\\" border=\\\"0\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" class=\\\"tborder\\\">\r\n	<tr>\r\n		<td class=\\\"tcat\\\">\r\n			<span style=\\\"float:$stylevar[right]\\\"><a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=addalbum\\\" class=\\\"smallfont\\\">$vbphrase[create_new_album]</a></span>\r\n			<strong>$vbphrase[recently_updated_albums]</strong>\r\n		</td>\r\n	</tr>\r\n	<tr>\r\n		<td class=\\\"alt1\\\">\r\n			<div id=\\\"thumbcontainer\\\">\r\n				$latestbits\r\n			</div>\r\n		</td>\r\n	</tr>\r\n</table>\r\n\r\n\".(($latest_pagenav) ? (\"\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\" style=\\\"margin-top:3px\\\">\r\n<tr valign=\\\"top\\\">\r\n	<td align=\\\"$stylevar[right]\\\">$latest_pagenav</td>\r\n</tr>\r\n</table>\r\n\") : (\"\")).\"\r\n\r\n\") : (\"\")).\"\r\n\r\n\".(($show[\'user_albums\'] AND $latestbits) ? (\"\r\n<br />\r\n\") : (\"\")).\"\r\n\r\n$template_hook[album_overview_after_latest]\r\n\r\n<div id=\\\"usercss\\\">\r\n\".(($show[\'user_albums\']) ? (\"\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\" colspan=\\\"4\\\">\r\n		\" . construct_phrase(\"$vbphrase[xs_albums]\", \"$userinfo[username]\") . \"\r\n	</td>\r\n</tr>\r\n<tr>\r\n	$template_hook[album_overview_user_start_col]\r\n	<td class=\\\"thead\\\">&nbsp;</td>\r\n	<td class=\\\"thead\\\" width=\\\"80%\\\">$vbphrase[album_title]</td>\r\n	<td class=\\\"thead\\\" width=\\\"5%\\\" align=\\\"center\\\">$vbphrase[pictures]</td>\r\n	<td class=\\\"thead\\\" width=\\\"15%\\\" nowrap=\\\"nowrap\\\">$vbphrase[last_picture]</td>\r\n	$template_hook[album_overview_user_end_column]\r\n</tr>\r\n\r\n\".(($albumbits) ? (\"\r\n	$albumbits\r\n\") : (\"\r\n	<tr>\r\n	<td colspan=\\\"4\\\" class=\\\"alt1\\\" align=\\\"center\\\">\r\n		\".(($show[\'add_album_option\']) ? (\"\r\n			<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=addalbum\\\">$vbphrase[click_here_add_album_upload_pictures]</a>\r\n		\") : (\"\r\n			$vbphrase[this_user_has_no_albums]\r\n		\")).\"\r\n	</td>\r\n	</tr>\r\n\")).\"\r\n\r\n</table>\r\n\r\n\".(($show[\'add_album_option\'] OR $pagenav) ? (\"\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\