?v=$vboptions[simpleversion]\"></script>\r\n	<script type=\"text/javascript\">\r\n	<!--\r\n	inlineMod_comment = new vB_Inline_Mod(\'inlineMod_comment\', \'picturecomment\', \'picture_comment_inlinemod_form\', \'$vbphrase[go_x]\', \'vbulletin_inline\', \'message\');\r\n	//-->\r\n	</script>\r\n</if>\r\n\r\n</div>\r\n\r\n$footer\r\n</body>\r\n</html>', 'template', 1208875399, 'vBulletin Solutions', '3.7.0 Release Candidate 4', 'vbulletin'),
(80, -1, 'album_picturebit', '<table style=\\\"width:{$picturebit_width}px; height:{$picturebit_height}px; margin:5px; float:$stylevar[left]\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\">\r\n<tr>\r\n	<td class=\\\"smallfont\\\" align=\\\"center\\\" valign=\\\"middle\\\">\r\n	\".(($picture[\'thumburl\']) ? (\"\r\n		<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$albuminfo[albumid]&amp;pictureid=$picture[pictureid]\\\"><img class=\\\"alt2\\\" src=\\\"$picture[thumburl]\\\" alt=\\\"$picture[caption_preview]\\\" border=\\\"0\\\" style=\\\"\r\n			padding:$stylevar[cellpadding]px;\r\n			\".((!$usercss) ? (\"border:solid $stylevar[cellspacing]px $stylevar[tborder_bgcolor]\") : (\"\")).\"\r\n		\\\" $picture[dimensions] /></a>\r\n	\") : (\"\r\n		<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$albuminfo[albumid]&amp;pictureid=$picture[pictureid]\\\">\".(($picture[\'caption_preview\']) ? (\"$picture[caption_preview]\") : (\"$vbphrase[picture]\")).\"</a>\r\n	\")).\"\r\n	\".(($show[\'moderation\']) ? (\"<br /><span class=\\\"shade\\\">$vbphrase[picture_moderated]</span>\") : (\"\")).\"\r\n	</td>\r\n</tr>\r\n</table>', '<table style=\"width:{$picturebit_width}px; height:{$picturebit_height}px; margin:5px; float:$stylevar[left]\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tr>\r\n	<td class=\"smallfont\" align=\"center\" valign=\"middle\">\r\n	<if condition=\"$picture[\'thumburl\']\">\r\n		<a href=\"album.php?$session[sessionurl]albumid=$albuminfo[albumid]&amp;pictureid=$picture[pictureid]\"><img class=\"alt2\" src=\"$picture[thumburl]\" alt=\"$picture[caption_preview]\" border=\"0\" style=\"\r\n			padding:$stylevar[cellpadding]px;\r\n			<if condition=\"!$usercss\">border:solid $stylevar[cellspacing]px $stylevar[tborder_bgcolor]</if>\r\n		\" $picture[dimensions] /></a>\r\n	<else />\r\n		<a href=\"album.php?$session[sessionurl]albumid=$albuminfo[albumid]&amp;pi