(81, -1, 'album_picturebit_checkbox', '<table style=\\\"width:{$picturebit_width}px; height:{$picturebit_height}px; margin:5px; float:$stylevar[left]\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\">\r\n<tr>\r\n	<td class=\\\"smallfont\\\" align=\\\"center\\\" valign=\\\"middle\\\"><a name=\\\"page$page_anchor\\\"></a>\r\n	\".(($picture[\'thumburl\']) ? (\"\r\n		<div class=\\\"alt2\\\" style=\\\"\r\n			position:relative;\r\n			width:$picture[thumbnail_width]px;\r\n			padding:$stylevar[cellpadding]px;\r\n			\".((!$usercss) ? (\"border:solid $stylevar[cellspacing]px $stylevar[tborder_bgcolor];\") : (\"\")).\"\r\n		\\\">\r\n			<label for=\\\"cb_picture_$picture[pictureid]\\\"><img src=\\\"$picture[thumburl]\\\" alt=\\\"$picture[caption_preview]\\\" border=\\\"0\\\" $picture[dimensions] /></label>\r\n			<input type=\\\"checkbox\\\" name=\\\"pictureids[]\\\" id=\\\"cb_picture_$picture[pictureid]\\\" style=\\\"position:absolute; $stylevar[left]: 0px; top: 0px; padding: 0px\\\" value=\\\"$picture[pictureid]\\\" />\r\n		</div>\r\n	\") : (\"\r\n		<input type=\\\"checkbox\\\" name=\\\"pictureids[]\\\" id=\\\"cb_picture_$picture[pictureid]\\\" value=\\\"$picture[pictureid]\\\" /><label for=\\\"cb_picture_$picture[pictureid]\\\">\".(($picture[\'caption_preview\']) ? (\"$picture[caption_preview]\") : (\"$vbphrase[picture]\")).\"</label>\r\n	\")).\"\r\n	</td>\r\n</tr>\r\n</table>', '<table style=\"width:{$picturebit_width}px; height:{$picturebit_height}px; margin:5px; float:$stylevar[left]\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tr>\r\n	<td class=\"smallfont\" align=\"center\" valign=\"middle\"><a name=\"page$page_anchor\"></a>\r\n	<if condition=\"$picture[\'thumburl\']\">\r\n		<div class=\"alt2\" style=\"\r\n			position:relative;\r\n			width:$picture[thumbnail_width]px;\r\n			padding:$stylevar[cellpadding]px;\r\n			<if condition=\"!$usercss\">border:solid $stylevar[cellspacing]px $stylevar[tborder_bgcolor];</if>\r\n		\">\r\n			<label for=\"cb_picture_$picture[pictureid]\"><img src=\"$picture[thumburl]\" alt=\"$picture[caption_preview]\" border=\"0\" $picture[dimensions] /></label>\r\n			<input type=\"checkbox\" name=\"pictureids[]\" id=\"cb_picture_$picture[pictureid]\" style=\"position:absolute; $stylevar[left]: 0px; top: 0px; padding: 0px\" value=\"$picture[pictureid]\" />\r\n		</div>\r\n	<else />\r\n		<input type=\"checkbox\" name=\"pictureids[]\" id=\"cb_picture_$picture[pictureid]\" value=\"$picture[pictureid]\" /><label for=\"cb_picture_$picture[pictureid]\"><if condition=\"$picture[\'caption_preview\']\">$picture[caption_preview]<else />$vbphrase[picture]</if></label>\r\n	</if>\r\n	</td>\r\n</tr>\r\n</table>', 'template', 1202834218, 'vBulletin Solutions', '3.7.0 Beta 5', 'vbulletin'),
(82, -1, 'album_picturebit_unread', '<table style=\\\"width:{$picturebit_width}px; margin:5px; float:$stylevar[left]\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\">\r\n<tr>\r\n	<td class=\\\"smallfont\\\" align=\\\"center\\\" valign=\\\"middle\\\" style=\\\"height:{$picturebit_height}px\\\">\r\n	\".(($picture[\'thumburl\']) ? (\"\r\n		<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$picture[albumid]&amp;pictureid=$picture[pictureid]&amp;commentid=$picture[unreadcommentid]#picturecomment$picture[unreadcommentid]\\\"><img class=\\\"alt2\\\" src=\\\"$picture[thumburl]\\\" alt=\\\"$picture[caption_preview]\\\" border=\\\"0\\\" style=\\\"\r\n			padding:$stylevar[cellpadding]px;\r\n			\".((!$usercss) ? (\"border:solid $stylevar[cellspacing]px $stylevar[tborder_bgcolor]\") : (\"\")).\"\r\n		\\\" $picture[dimensions] /></a>\r\n	\") : (\"\r\n		<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$picture[albumid]&amp;pictureid=$picture[pictureid]&amp;commentid=$picture[unreadcommentid]#picturecomment$picture[unreadcommentid]\\\">\".(($picture[\'caption_preview\']) ? (\"$picture[caption_preview]\") : (\"$vbphrase[picture]\")).\"</a>\r\n	\")).\"\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"smallfont\\\" align=\\\"center\\\"><a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$picture[albumid]&amp;pictureid=$picture[pictureid]&amp;commentid=$picture[unreadcommentid]#picturecomment$picture[unreadcommentid]\\\">\" . construct_phrase(\"$vbphrase[x_unread]\", \"$picture[unreadcomments]\") . \"</a></td>\r\n</tr>\r\n</table>', '<table style=\"width:{$picturebit_width}px; margin:5px; float:$stylevar[left]\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tr>\r\n	<td class=\"smallfont\" align=\"center\" valign=\"middle\" style=\"height:{$picturebit_height}px\">\r\n	<if condition=\"$picture[\'thumburl\']\">\r\n		<a href=\"album.php?$ses