(83, -1, 'album_picturelist', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n$usercss\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - \" . construct_phrase(\"$vbphrase[xs_album_y]\", \"$userinfo[username]\", \"$albuminfo[title_html]\") . \"</title>\r\n\".(($show[\'add_group_form\']) ? (\"\r\n	<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_album.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n\") : (\"\")).\"\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<div id=\\\"usercss\\\">\r\n\r\n\".(($show[\'add_picture_option\'] OR $pagenav) ? (\"\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\" style=\\\"margin-bottom:3px\\\">\r\n<tr valign=\\\"bottom\\\">\r\n	<td>\r\n		\".(($show[\'add_picture_option\']) ? (\"\r\n			<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=addpictures&amp;albumid=$albuminfo[albumid]\\\"><img src=\\\"$stylevar[imgdir_button]/upload_pictures.png\\\" border=\\\"0\\\" class=\\\"inlineimg\\\" alt=\\\"$vbphrase[upload_pictures]\\\" /></a> <a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=addpictures&amp;albumid=$albuminfo[albumid]\\\">$vbphrase[upload_pictures]</a>\r\n		\") : (\"\r\n			&nbsp;\r\n		\")).\"\r\n	</td>\r\n	\".(($pagenav) ? (\"<td align=\\\"$stylevar[right]\\\">$pagenav</td>\") : (\"\")).\"\r\n</tr>\r\n</table>\r\n\") : (\"\")).\"\r\n\r\n\".(($show[\'add_group_form\']) ? (\"\r\n	<form action=\\\"album.php?do=doaddgroupmult&amp;albumid=$albuminfo[albumid]\\\" method=\\\"post\\\">\r\n	<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"doaddgroupmult\\\" />\r\n	<input type=\\\"hidden\\\" name=\\\"albumid\\\" value=\\\"$albuminfo[albumid]\\\" />\r\n	<input type=\\\"hidden\\\" name=\\\"page\\\" value=\\\"$input_pagenumber\\\" />\r\n	<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n	<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n\") : (\"\")).\"\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		\".(($show[\'edit_album_option\'] OR $show[\'usercss_switch\']) ? (\"\r\n		<div class=\\\"smallfont\\\" style=\\\"float: $stylevar[right]\\\">\r\n			\".(($show[\'edit_album_option\']) ? (\"\r\n				<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=editalbum&amp;albumid=$albuminfo[albumid]\\\">$vbphrase[edit_album]</a>\r\n				\".(($albuminfo[\'picturecount\']) ? (\"| <a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=editpictures&amp;albumid=$albuminfo[albumid]\\\">$vbphrase[edit_pictures]</a>\") : (\"\")).\"\r\n			\") : (\"\")).\"\r\n			\".(($show[\'usercss_switch\']) ? (\"\r\n				\".(($show[\'edit_album_option\']) ? (\"|\") : (\"\")).\"\r\n				<a href=\\\"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=switchusercss&amp;hash=\" . $GLOBALS[\'vbulletin\']->userinfo[\'logouthash\'] . \"&amp;u=$userinfo[userid]\\\">$usercss_switch_phrase</a>\r\n			\") : (\"\")).\"\r\n		</div>\r\n		\") : (\"\")).\"\r\n		$albuminfo[title_html]\".(($show[\'personalalbum\']) ? (\"<span class=\\\"shade smallfont\\\"> $albumtype</span>\") : (\"\")).\"\r\n	</td>\r\n</tr>\r\n\r\n\".(($albuminfo[\'description_html\']) ? (\"\r\n<tr>\r\n	<td class=\\\"alt2\\\">$albuminfo[description_html]</td>\r\n</tr>\r\n\") : (\"\")).\"\r\n\r\n<tr>\r\n	<td class=\\\"alt1\\\" id=\\\"picturebits\\\">\r\n		\".(($picturebits) ? (\"\r\n			$picturebits\r\n		\") : (\"\r\n			<div align=\\\"center\\\">\r\n			\".(($show[\'add_picture_option\']) ? (\"\r\n				<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=addpictures&amp;albumid=$albuminfo[albumid]\\\">$vbphrase[click_here_to_upload_pictures]</a>\r\n			\") : (\"\r\n				$vbphrase[this_album_has_no_pictures]\r\n			\")).\"\r\n			</div>\r\n		\")).\"\r\n	</td>\r\n</tr>\r\n\r\n\".(($show[\'add_group_form\']) ? (\"\r\n	<tr>\r\n		<td class=\\\"tfoot\\\" align=\\\"center\\\">\r\n			$vbphrase[add_selected_pictures_to]:\r\n			<select name=\\\"groupid\\\">\r\n				<option value=\\\"0\\\">&nbsp;</option>\r\n				$group_options\r\n			</select>\r\n			<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[add_pictures]\\\" />\r\n			<input type=\\\"submit\\\" class=\\\"button\\\" name=\\\"cancel\\\" value=\\\"$vbphrase[cancel]\\\" />\r\n			\".(($show[\'private_notice\']) ? (\"<div class=\\\"smallfont shade\\\" align=\\\"center\\\">$vbphrase[pictures_from_this_private_album]</div>\") : (\"\")).\"\r\n		</td>\r\n	</tr>\r\n\") : (\"\".(($show[\'add_group_row\']) ? (\"\r\n	<tr>\r\n		<td class=\\\"tfoot smallfont\\\" align=\\\"center\\\">\r\n			<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$albuminfo[albumid]&amp;addgroup=1\".(($pagenumber > 1) ? (\"&amp;page=$pagenumber\") : (\"\")).\"#page$pagenumber\\\">$vbphrase[add_pictures_to_a_group]</a>\r\n		</td>\r\n	</tr>\r\n\") : (\"\")).\"\")).\"\r\n</table>\r\n\r\n\".(($show[\'add_group_form\']) ? (\"\r\n	</form>\r\n\") : (\"\")).\"\r\n\r\n\".(($show[\'add_picture_option\'] OR $pagenav) ? (\"\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\" style=\\\"margin-top:3px\\\">\r\n<tr valign=\\\"top\\\">\r\n	<td>\r\n		\".(($show[\'add_picture_option\']) ? (\"\r\n			<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=addpictures&amp;albumid=$albuminfo[albumid]\\\"><img src=\\\"$stylevar[imgdir_button]/upload_pictures.png\\\" border=\\\"0\\\" class=\\\"inlineimg\\\" alt=\\\"$vbphrase[upload_pictures]\\\" /></a> <a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=addpictures&amp;albumid=$albuminfo[albumid]\\\">$vbphrase[upload_pictures]</a>\r\n		\") : (\"\r\n			&nbsp;\r\n		\")).\"\r\n	</td>\r\n	\".(($pagenav) ? (\"<td align=\\\"$stylevar[right]\\\">$pagenav</td>\") : (\"\")).\"\r\n</tr>\r\n</table>\r\n\") : (\"\")).\"\r\n\r\n</div>\r\n\r\n$footer\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n$usercss\r\n<title>$vboptions[bbtitle] - <phrase 1=\"$userinfo[username]\" 2=\"$albuminfo[title_html]\">$vbphrase[xs_album_y]</phrase></title>\r\n<if condition=\"$show[\'add_group_form\']\">\r\n	<script type=\"text/javascript\" src=\"clientscript/vbulletin_album.js?v=$vboptions[simpleversion]\"></script>\r\n</if>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<div id=\"usercss\">\r\n\r\n<if condition=\"$show[\'add_picture_option\'] OR $pagenav\">\r\n<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"margin-bottom:3px\">\r\n<tr valign=\"bottom\">\r\n	<td>\r\n		<if condition=\"$show[\'add_picture_option\']\">\r\n			<a href=\"album.php?$session[sessionurl]do=addpictures&amp;albumid=$albuminfo[albumid]\"><img src=\"$stylevar[imgdir_button]/upload_pictures.png\" border=\"0\" class=\"inlineimg\" alt=\"$vbphrase[upload_pictures]\" /></a> <a href=\"album.php?$session[sessionurl]do=addpictures&amp;albumid=$albuminfo[albumid]\">$vbphrase[upload_pictures]</a>\r\n		<else />\r\n			&nbsp;\r\n		</if>\r\n	</td>\r\n	<if condition=\"$pagenav\"><td align=\"$stylevar[right]\">$pagenav</td></if>\r\n</tr>\r\n</table>\r\n</if>\r\n\r\n<if condition=\"$show[\'add_group_form\']\">\r\n	<form action=\"album.php?do=doaddgroupmult&amp;albumid=$albuminfo[albumid]\" method=\"post\">\r\n	<input type=\"hidden\" name=\"do\" value=\"doaddgroupmult\" />\r\n	<input type=\"hidden\" name=\"albumid\" value=\"$albuminfo[albumid]\" />\r\n	<input type=\"hidden\" name=\"page\" value=\"$input_pagenumber\" />\r\n	<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n	<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n</if>\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		<if condition=\"$show[\'edit_album_option\'] OR $show[\'usercss_switch\']\">\r\n		<div class=\"smallfont\" style=\"float: $stylevar[right]\">\r\n			<if condition=\"$show[\'edit_album_option\']\">\r\n				<a href=\"album.php?$session[sessionurl]do=editalbum&amp;albumid=$albuminfo[albumid]\">$vbphrase[edit_album]</a>\r\n				<if condition=\"$albuminfo[\'picturecount\']\">| <a href=\"album.php?$session[sessionurl]do=editpictures&amp;albumid=$albuminfo[albumid]\">$vbphrase[edit_pictures]</a></if>\r\n			</if>\r\n			<if condition=\"$show[\'usercss_switch\']\">\r\n				<if condition=\"$show[\'edit_album_option\']\">|</if>\r\n				<a href=\"profile.php?$session[sessionurl]do=switchusercss&amp;hash=$bbuserinfo[logouthash]&amp;u=$userinfo[userid]\">$usercss_switch_phrase</a>\r\n			</if>\r\n		</div>\r\n		</if>\r\n		$albuminfo[title_html]<if condition=\"$show[\'personalalbum\']\"><span class=\"shade smallfont\"> $albumtype</span></if>\r\n	</td>\r\n</tr>\r\n\r\n<if condition=\"$albuminfo[\'description_html\']\">\r\n<tr>\r\n	<td class=\"alt2\">$albuminfo[description_html]</td>\r\n</tr>\r\n</if>\r\n\r\n<tr>\r\n	<td class=\"alt1\" id=\"picturebits\">\r\n		<if condition=\"$picturebits\">\r\n			$picturebits\r\n		<else />\r\n			<div align=\"center\">\r\n			<if condition=\"$show[\'add_picture_option\']\">\r\n				<a href=\"album.php?$session[sessionurl]do=addpictures&amp;albumid=$albuminfo[albumid]\">$vbphrase[click_here_to_upload_pictures]</a>\r\n			<else />\r\n				$vbphrase[this_album_has_no_pictures]\r\n			</if>\r\n			</div>\r\n		</if>\r\n	</td>\r\n</tr>\r\n\r\n<if condition=\"$show[\'add_group_form\']\">\r\n	<tr>\r\n		<td class=\"tfoot\" align=\"center\">\r\n			$vbphrase[add_selected_pictures_to]:\r\n			<select name=\"groupid\">\r\n				<option value=\"0\">&nbsp;</option>\r\n				$group_options\r\n			</select>\r\n			<input type=\"submit\" class=\"button\" value=\"$vbphrase[add_pictures]\" />\r\n			<input type=\"submit\" class=\"button\" name=\"cancel\" value=\"$vbphrase[cancel]\" />\r\n			<if condition=\"$show[\'private_notice\']\"><div class=\"smallfont shade\" align=\"center\">$vbphrase[pictures_from_this_private_album]</div></if>\r\n		</td>\r\n	</tr>\r\n<else /><if condition=\"$show[\'add_group_row\']\">\r\n	<tr>\r\n		<td class=\"tfoot smallfont\" align=\"center\">\r\n			<a href=\"album.php?$session[sessionurl]albumid=$albuminfo[albumid]&amp;addgroup=1<if condition=\"$pagenumber > 1\">&amp;page=$pagenumber</if>#page$pagenumber\">$vbphrase[add_pictures_to_a_group]</a>\r\n		</td>\r\n	</tr>\r\n</if></if>\r\n</table>\r\n\r\n<if condition=\"$show[\'add_group_form\']\">\r\n	</form>\r\n</if>\r\n\r\n<if condition=\"$show[\'add_picture_option\'] OR $pagenav\">\r\n<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"margin-top:3px\">\r\n<tr valign=\"top\">\r\n	<td>\r\n		<if condition=\"$show[\'add_picture_option\']\">\r\n			<a href=\"album.php?$session[sessionurl]do=addpictures&amp;albumid=$albuminfo[albumid]\"><img src=\"$stylevar[imgdir_button]/upload_pictures.png\" border=\"0\" class=\"inlineimg\" alt=\"$vbphrase[upload_pictures]\" /></a> <a href=\"album.php?$session[sessionurl]do=addpictures&amp;albumid=$albuminfo[albumid]\">$vbphrase[upload_pictures]</a>\r\n		<else />\r\n			&nbsp;\r\n		</if>\r\n	</td>\r\n	<if condition=\"$pagenav\"><td align=\"$stylevar[right]\">$pagenav</td></if>\r\n</tr>\r\n</table>\r\n</if>\r\n\r\n</div>\r\n\r\n$footer\r\n</body>\r\n</html>', 'template', 1217244680, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(84, -1, 'album_pictureview', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n$usercss\r\n$picturecomment_css\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - \" . construct_phrase(\"$vbphrase[xs_album_y]\", \"$userinfo[username]\", \"$albuminfo[title_html]\") . \" - $vbphrase[picture]</title>\r\n\r\n<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_quick_edit_generic.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_quick_edit_picturecomment.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<div id=\\\"usercss\\\">\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		<div class=\\\"smallfont\\\" style=\\\"float: $stylevar[right]\\\">\r\n			\".(($show[\'picture_nav\']) ? (\"\r\n				<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$albuminfo[albumid]&amp;pictureid=$pic_location[prev_pictureid]\\\">$pic_location[prev_text_short]</a> |\r\n				<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$albuminfo[albumid]&amp;pictureid=$pic_location[next_pictureid]\\\">$pic_location[next_text_short]</a>\r\n				\".(($show[\'usercss_switch\']) ? (\"|\") : (\"\")).\"\r\n			\") : (\"\")).\"\r\n			\".(($show[\'usercss_switch\']) ? (\"<a href=\\\"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=switchusercss&amp;hash=\" . $GLOBALS[\'vbulletin\']->userinfo[\'logouthash\'] . \"&amp;u=$userinfo[userid]\\\">$usercss_switch_phrase</a>\") : (\"\")).\"\r\n		</div>\r\n\r\n		\" . construct_phrase(\"$vbphrase[picture_x_of_y_from_album_z]\", \"$pic_location[pic_position]\", \"$albuminfo[picturecount]\", \"$albuminfo[title]\") . \"\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"alt1\\\" align=\\\"center\\\">\r\n		<table width=\\\"\".(($pictureinfo[\'width\'] < 400) ? (\"400\") : (\"$pictureinfo[width]\")).\"\\\" cellpadding=\\\"$stylevar[cellpadding]\\\">\r\n		<tr>\r\n			<td align=\\\"center\\\"><img src=\\\"picture.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$albuminfo[albumid]&amp;pictureid=$pictureinfo[pictureid]\\\" alt=\\\"$pictureinfo[caption_censored]\\\" /></td>\r\n		</tr>\r\n		\".(($show[\'moderation\']) ? (\"<tr><td align=\\\"center\\\"><strong>$vbphrase[picture_waiting_moderator_approval]</strong></td></tr>\") : (\"\")).\"\r\n		\".(($pictureinfo[\'caption_html\']) ? (\"\r\n			<tr>\r\n				<td align=\\\"$stylevar[left]\\\"><em>$pictureinfo[caption_html]</em></td>\r\n			</tr>\r\n		\") : (\"\")).\"\r\n		<tr>\r\n			<td align=\\\"$stylevar[left]\\\" class=\\\"smallfont\\\">\r\n				\".(($show[\'edit_picture_option\'] OR $show[\'add_group_link\'] OR $show[\'reportlink\']) ? (\"\r\n				<div class=\\\"smallfont normal\\\" style=\\\"float: $stylevar[right]\\\">\r\n					\".(($show[\'edit_picture_option\']) ? (\"\r\n						<div><a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=editpictures&amp;albumid=$albuminfo[albumid]&amp;pictureid=$pictureinfo[pictureid]&amp;frompicture=1\\\">$vbphrase[edit_picture]</a></div>\r\n					\") : (\"\")).\"\r\n					\".(($show[\'add_group_link\']) ? (\"\r\n						<div><a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=addgroup&amp;albumid=$albuminfo[albumid]&amp;pictureid=$pictureinfo[pictureid]\\\">$vbphrase[add_to_group]</a></div>\r\n					\") : (\"\")).\"\r\n					\".(($show[\'reportlink\']) ? (\"\r\n						<div><a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=report&amp;albumid=$albuminfo[albumid]&amp;pictureid=$pictureinfo[pictureid]\\\">$vbphrase[report_picture]</a></div>\r\n					\") : (\"\")).\"\r\n				</div>\r\n				\") : (\"\")).\"\r\n				<span class=\\\"shade\\\">$vbphrase[picture_added]</span> $pictureinfo[adddate] \".((!$show[\'detailedtime\']) ? (\"<span class=\\\"time\\\">$pictureinfo[addtime]</span>\") : (\"\")).\"\r\n				<br /><span class=\\\"shade\\\">\" . construct_phrase(\"$vbphrase[added_by_x]\", \"<a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$userinfo[userid]\\\">$userinfo[username]</a>\") . \"</span>\r\n			</td>\r\n		</tr>\r\n		\".(($show[\'picture_owner\']) ? (\"\r\n		<tr>\r\n			<td class=\\\"smallfont\\\" align=\\\"center\\\"><div style=\\\"text-align: $stylevar[left]; width: 400px\\\">\r\n				<div>$vbphrase[picture_url]<br />\r\n					<input type=\\\"text\\\" value=\\\"$pictureinfo[pictureurl]\\\" readonly=\\\"readonly\\\" class=\\\"bginput\\\" onfocus=\\\"this.select()\\\" dir=\\\"ltr\\\" size=\\\"30\\\" style=\\\"width:400px\\\" />\r\n				</div>\r\n				\r\n				<div>$vbphrase[bb_code]<br />\r\n					<input type=\\\"text\\\" value=\\\"[IMG]$pictureinfo[pictureurl][/IMG]\\\" readonly=\\\"readonly\\\" class=\\\"bginput\\\" onfocus=\\\"this.select()\\\" dir=\\\"ltr\\\" size=\\\"30\\\" style=\\\"width:400px\\\" />\r\n				</div>\r\n			</div></td>\r\n		</tr>\r\n		\") : (\"\")).\"\r\n		</table>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n\".(($show[\'picture_nav\']) ? (\"\r\n	<div class=\\\"smallfont\\\" align=\\\"center\\\" style=\\\"margin-top: $stylevar[cellpadding]px\\\">\r\n		<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$albuminfo[albumid]&amp;pictureid=$pic_location[prev_pictureid]\\\">$pic_location[prev_text]</a> |\r\n		<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$albuminfo[albumid]&amp;pictureid=$pic_location[next_pictureid]\\\">$pic_location[next_text]</a>\r\n	</div>\r\n\") : (\"\")).\"\r\n\r\n$picturecomment_commentarea\r\n\r\n\".(($show[\'picturecomment_options\'] AND $show[\'picture_nav\']) ? (\"\r\n	<div class=\\\"smallfont\\\" align=\\\"center\\\" style=\\\"margin-top: $stylevar[cellpadding]px\\\">\r\n		<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$albuminfo[albumid]&amp;pictureid=$pic_location[prev_pictureid]\\\">$pic_location[prev_text]</a> |\r\n		<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$albuminfo[albumid]&amp;pictureid=$pic_location[next_pictureid]\\\">$pic_location[next_text]</a>\r\n	</div>\r\n\") : (\"\")).\"\r\n\r\n</div>\r\n\r\n$footer\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n$usercss\r\n$picturecomment_css\r\n<title>$vboptions[bbtitle] - <phrase 1=\"$userinfo[username]\" 2=\"$albuminfo[title_html]\">$vbphrase[xs_album_y]</phrase> - $vbphrase[picture]</title>\r\n\r\n<script type=\"text/javascript\" src=\"clientscript/vbulletin_quick_edit_generic.js?v=$vboptions[simpleversion]\"></script>\r\n<script type=\"text/javascript\" src=\"clientscript/vbulletin_quick_edit_picturecomment.js?v=$vboptions[simpleversion]\"></script>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<div id=\"usercss\">\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		<div class=\"smallfont\" style=\"float: $stylevar[right]\">\r\n			<if condition=\"$show[\'picture_nav\']\">\r\n				<a href=\"album.php?$session[sessionurl]albumid=$albuminfo[albumid]&amp;pictureid=$pic_location[prev_pictureid]\">$pic_location[prev_text_short]</a> |\r\n				<a href=\"album.php?$session[sessionurl]albumid=$albuminfo[albumid]&amp;pictureid=$pic_location[next_pictureid]\">$pic_location[next_text_short]</a>\r\n				<if condition=\"$show[\'usercss_switch\']\">|</if>\r\n			</if>\r\n			<if condition=\"$show[\'usercss_switch\']\"><a href=\"profile.php?$session[sessionurl]do=switchusercss&amp;hash=$bbuserinfo[logouthash]&amp;u=$userinfo[userid]\">$usercss_switch_phrase</a></if>\r\n		</div>\r\n\r\n		<phrase 1=\"$pic_location[pic_position]\" 2=\"$albuminfo[picturecount]\" 3=\"$albuminfo[title]\">$vbphrase[picture_x_of_y_from_album_z]</phrase>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"alt1\" align=\"center\">\r\n		<table width=\"<if condition=\"$pictureinfo[\'width\'] < 400\">400<else />$pictureinfo[width]</if>\" cellpadding=\"$stylevar[cellpadding]\">\r\n		<tr>\r\n			<td align=\"center\"><img src=\"picture.php?$session[sessionurl]albumid=$albuminfo[albumid]&amp;pictureid=$pictureinfo[pictureid]\" alt=\"$pictureinfo[caption_censored]\" /></td>\r\n		</tr>\r\n		<if condition=\"$show[\'moderation\']\"><tr><td align=\"center\"><strong>$vbphrase[picture_waiting_moderator_approval]</strong></td></tr></if>\r\n		<if condition=\"$pictureinfo[\'caption_html\']\">\r\n			<tr>\r\n				<td align=\"$stylevar[left]\"><em>$pictureinfo[caption_html]</em></td>\r\n			</tr>\r\n		</if>\r\n		<tr>\r\n			<td align=\"$stylevar[left]\" class=\"smallfont\">\r\n				<if condition=\"$show[\'edit_picture_option\'] OR $show[\'add_group_link\'] OR $show[\'reportlink\']\">\r\n				<div class=\"smallfont normal\" style=\"float: $stylevar[right]\">\r\n					<if condition=\"$show[\'edit_picture_option\']\">\r\n						<div><a href=\"album.php?$session[sessionurl]do=editpictures&amp;albumid=$albuminfo[albumid]&amp;pictureid=$pictureinfo[pictureid]&amp;frompicture=1\">$vbphrase[edit_picture]</a></div>\r\n					</if>\r\n					<if condition=\"$show[\'add_group_link\']\">\r\n						<div><a href=\"album.php?$session[sessionurl]do=addgroup&amp;albumid=$albuminfo[albumid]&amp;pictureid=$pictureinfo[pictureid]\">$vbphrase[add_to_group]</a></div>\r\n					</if>\r\n					<if condition=\"$show[\'reportlink\']\">\r\n						<div><a href=\"album.php?$session[sessionurl]do=report&amp;albumid=$albuminfo[albumid]&amp;pictureid=$pictureinfo[pictureid]\">$vbphrase[report_picture]</a></div>\r\n					</if>\r\n				</div>\r\n				</if>\r\n				<span class=\"shade\">$vbphrase[picture_added]</span> $pictureinfo[adddate] <if condition=\"!$show[\'detailedtime\']\"><span class=\"time\">$pictureinfo[addtime]</span></if>\r\n				<br /><span class=\"shade\"><phrase 1=\'<a href=\"member.php?$session[sessionurl]u=$userinfo[userid]\">$userinfo[username]</a>\'>$vbphrase[added_by_x]</phrase></span>\r\n			</td>\r\n		</tr>\r\n		<if condition=\"$show[\'picture_owner\']\">\r\n		<tr>\r\n			<td class=\"smallfont\" align=\"center\"><div style=\"text-align: $stylevar[left]; width: 400px\">\r\n				<div>$vbphrase[picture_url]<br />\r\n					<input type=\"text\" value=\"$pictureinfo[pictureurl]\" readonly=\"readonly\" class=\"bginput\" onfocus=\"this.select()\" dir=\"ltr\" size=\"30\" style=\"width:400px\" />\r\n				</div>\r\n				\r\n				<div>$vbphrase[bb_code]<br />\r\n					<input type=\"text\" value=\"[IMG]$pictureinfo[pictureurl][/IMG]\" readonly=\"readonly\" class=\"bginput\" onfocus=\"this.select()\" dir=\"ltr\" size=\"30\" style=\"width:400px\" />\r\n				</div>\r\n			</div></td>\r\n		</tr>\r\n		</if>\r\n		</table>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<if condition=\"$show[\'picture_nav\']\">\r\n	<div class=\"smallfont\" align=\"center\" style=\"margin-top: $stylevar[cellpadding]px\">\r\n		<a href=\"album.php?$session[sessionurl]albumid=$albuminfo[albumid]&amp;pictureid=$pic_location[prev_pictureid]\">$pic_location[prev_text]</a> |\r\n		<a href=\"album.php?$session[sessionurl]albumid=$albuminfo[albumid]&amp;pictureid=$pic_location[next_pictureid]\">$pic_location[next_text]</a>\r\n	</div>\r\n</if>\r\n\r\n$picturecomment_commentarea\r\n\r\n<if condition=\"$show[\'picturecomment_options\'] AND $show[\'picture_nav\']\">\r\n	<div class=\"smallfont\" align=\"center\" style=\"margin-top: $stylevar[cellpadding]px\">\r\n		<a href=\"album.php?$session[sessionurl]albumid=$albuminfo[albumid]&amp;pictureid=$pic_location[prev_pictureid]\">$pic_location[prev_text]</a> |\r\n		<a href=\"album.php?$session[sessionurl]albumid=$albuminfo[albumid]&amp;pictureid=$pic_location[next_pictureid]\">$pic_location[next_text]</a>\r\n	</div>\r\n</if>\r\n\r\n</div>\r\n\r\n$footer\r\n</body>\r\n</html>', 'template', 1218457442, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(85, -1, 'album_picture_edit', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n$usercss\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $vbphrase[edit_pictures]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<div id=\\\"usercss\\\">\r\n\r\n\".(($pagenav) ? (\"<div style=\\\"margin-bottom: 3px\\\">$pagenav</div>\") : (\"\")).\"\r\n\r\n<form action=\\\"album.php?do=updatepictures&amp;albumid=$albuminfo[albumid]\\\" method=\\\"post\\\">\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		\".(($show[\'usercss_switch\']) ? (\"\r\n			<div class=\\\"smallfont\\\" style=\\\"float: $stylevar[right]\\\">\r\n				<a href=\\\"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=switchusercss&amp;hash=\" . $GLOBALS[\'vbulletin\']->userinfo[\'logouthash\'] . \"&amp;u=$userinfo[userid]\\\">$usercss_switch_phrase</a>\r\n				</div>\r\n		\") : (\"\")).\"\r\n		$vbphrase[edit_pictures]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n			\".(($error_message) ? (\"\r\n				<fieldset class=\\\"fieldset\\\">\r\n					<legend>$vbphrase[vbulletin_message]</legend>\r\n					<div class=\\\"smallfont\\\">$error_message</div>\r\n				</fieldset>\r\n			\") : (\"\")).\"\r\n\r\n			<fieldset style=\\\"border-style: none\\\">\r\n			<table width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"$stylevar[cellpadding]\\\">\r\n			<tr>\r\n				<td valign=\\\"top\\\">\r\n					<strong>$albuminfo[title_html]</strong>\r\n					\".(($albuminfo[\'description_html\']) ? (\"<div class=\\\"smallfont\\\">$albuminfo[description_html]</div>\") : (\"\")).\"\r\n				</td>\r\n				\".(($show[\'leave_cover\']) ? (\"\r\n				<td class=\\\"smallfont\\\" width=\\\"\".(($GLOBALS[\'vbulletin\']->options[\'album_thumbsize\'] > 170) ? (\"\" . $GLOBALS[\'vbulletin\']->options[\'album_thumbsize\'] . \"\") : (\"170\")).\"\\\" valign=\\\"bottom\\\">\r\n					<input type=\\\"radio\\\" name=\\\"coverpictureid\\\" id=\\\"rb_coverpictureid_0\\\" value=\\\"0\\\" checked=\\\"checked\\\" tabindex=\\\"1\\\" /><label for=\\\"rb_coverpictureid_0\\\">$vbphrase[leave_cover_unchanged]</label>\r\n				</td>\r\n				\") : (\"\")).\"\r\n			</tr>\r\n			</table>\r\n			</fieldset>\r\n\r\n			$picturebits\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"updatepictures\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"albumid\\\" value=\\\"$albuminfo[albumid]\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"frompicture\\\" value=\\\"$frompicture\\\" />\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[save_changes]\\\" accesskey=\\\"s\\\" tabindex=\\\"1\\\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n\r\n</table>\r\n</form>\r\n\r\n</div>\r\n\r\n$footer\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n$usercss\r\n<title>$vboptions[bbtitle] - $vbphrase[edit_pictures]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<div id=\"usercss\">\r\n\r\n<if condition=\"$pagenav\"><div style=\"margin-bottom: 3px\">$pagenav</div></if>\r\n\r\n<form action=\"album.php?do=updatepictures&amp;albumid=$albuminfo[albumid]\" method=\"post\">\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		<if condition=\"$show[\'usercss_switch\']\">\r\n			<div class=\"smallfont\" style=\"float: $stylevar[right]\">\r\n				<a href=\"profile.php?$session[sessionurl]do=switchusercss&amp;hash=$bbuserinfo[logouthash]&amp;u=$userinfo[userid]\">$usercss_switch_phrase</a>\r\n				</div>\r\n		</if>\r\n		$vbphrase[edit_pictures]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n			<if condition=\"$error_message\">\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[vbulletin_message]</legend>\r\n					<div class=\"smallfont\">$error_message</div>\r\n				</fieldset>\r\n			</if>\r\n\r\n			<fieldset style=\"border-style: none\">\r\n			<table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"$stylevar[cellpadding]\">\r\n			<tr>\r\n				<td valign=\"top\">\r\n					<strong>$albuminfo[title_html]</strong>\r\n					<if condition=\"$albuminfo[\'description_html\']\"><div class=\"smallfont\">$albuminfo[description_html]</div></if>\r\n				</td>\r\n				<if condition=\"$show[\'leave_cover\']\">\r\n				<td class=\"smallfont\" width=\"<if condition=\"$vboptions[\'album_thumbsize\'] > 170\">$vboptions[album_thumbsize]<else />170</if>\" valign=\"bottom\">\r\n					<input type=\"radio\" name=\"coverpictureid\" id=\"rb_coverpictureid_0\" value=\"0\" checked=\"checked\" tabindex=\"1\" /><label for=\"rb_coverpictureid_0\">$vbphrase[leave_cover_unchanged]</label>\r\n				</td>\r\n				</if>\r\n			</tr>\r\n			</table>\r\n			</fieldset>\r\n\r\n			$picturebits\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n		<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n		<input type=\"hidden\" name=\"do\" value=\"updatepictures\" />\r\n		<input type=\"hidden\" name=\"albumid\" value=\"$albuminfo[albumid]\" />\r\n		<input type=\"hidden\" name=\"frompicture\" value=\"$frompicture\" />\r\n		<input type=\"submit\" class=\"button\" value=\"$vbphrase[save_changes]\" accesskey=\"s\" tabindex=\"1\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n\r\n</table>\r\n</form>\r\n\r\n</div>\r\n\r\n$footer\r\n</body>\r\n</html>', 'template', 1214219544, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(86, -1, 'album_picture_editbit', '<fieldset style=\\\"margin-top: $stylevar[cellpadding]px\\\" class=\\\"fieldset\\\">\r\n<table width=\\\"100%\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"$stylevar[cellpadding]\\\">\r\n<tr>\r\n	<td class=\\\"smallfont\\\" valign=\\\"top\\\">\r\n		<div>\r\n			$vbphrase[caption]:\r\n			<div><textarea name=\\\"pictures[$picture[pictureid]][caption]\\\" rows=\\\"5\\\" cols=\\\"50\\\" style=\\\"width: 98%\\\" tabindex=\\\"1\\\">$picture[caption]</textarea></div>\r\n		</div>\r\n\r\n		\".(($show[\'move_to_album\']) ? (\"\r\n		<div style=\\\"float:$stylevar[right];padding-$stylevar[right]:$stylevar[cellpadding]px\\\">\r\n			<label for=\\\"cb_move_pic$picture[pictureid]\\\">$vbphrase[move_to_album]: </label> <select name=\\\"pictures[$picture[pictureid]][album]\\\" id=\\\"cb_move_pic$picture[pictureid]\\\" tabindex=\\\"1\\\" />$album_options</select>\r\n		</div>\r\n		\") : (\"\")).\"\r\n		\".(($show[\'delete_option\']) ? (\"\r\n		<div style=\\\"float:$stylevar[left]\\\">\r\n			<input type=\\\"checkbox\\\" name=\\\"pictures[$picture[pictureid]][delete]\\\" id=\\\"cb_delete_pic$picture[pictureid]\\\" value=\\\"1\\\" tabindex=\\\"1\\\" /><label for=\\\"cb_delete_pic$picture[pictureid]\\\">$vbphrase[delete_this_picture]</label> \".(($picture[\'usedincss\']) ? (\"<span class=\\\"shade\\\">($vbphrase[pictured_used_profile_styling])</span>\") : (\"\")).\"\r\n		</div>\r\n		\") : (\"\")).\"\r\n		\".(($show[\'approve_option\']) ? (\"\r\n		<div style=\\\"float:$stylevar[left];clear:$stylevar[left]\\\">\r\n			<input type=\\\"checkbox\\\" name=\\\"pictures[$picture[pictureid]][approve]\\\" id=\\\"cb_approve_pic$picture[pictureid]\\\" value=\\\"1\\\" tabindex=\\\"1\\\" /><label for=\\\"cb_approve_pic$picture[pictureid]\\\">$vbphrase[approve_this_picture]</label>\r\n		</div>		\r\n		\") : (\"\")).\"	\r\n	</td>\r\n	<td class=\\\"smallfont\\\" valign=\\\"top\\\" width=\\\"\".(($GLOBALS[\'vbulletin\']->options[\'album_thumbsize\'] > 170) ? (\"\" . $GLOBALS[\'vbulletin\']->options[\'album_thumbsize\'] . \"\") : (\"170\")).\"\\\">\r\n		<div style=\\\"white-space:nowrap\\\">\r\n		\".(($picture[\'thumburl\']) ? (\"\r\n			<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$albuminfo[albumid]&amp;pictureid=$picture[pictureid]\\\"><img src=\\\"$picture[thumburl]\\\" alt=\\\"$picture[caption_preview]\\\" border=\\\"0\\\" $picture[dimensions] /></a>\r\n		\") : (\"\r\n			<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$albuminfo[albumid]&amp;pictureid=$picture[pictureid]\\\">\".(($picture[\'caption_preview\']) ? (\"$picture[caption_preview]\") : (\"$vbphrase[picture]\")).\"</a>\r\n		\")).\"\r\n		</div>\r\n\r\n		\".(($show[\'album_cover\']) ? (\"\r\n		<div>\r\n			<input type=\\\"radio\\\" name=\\\"coverpictureid\\\" id=\\\"rb_coverpictureid_pic$picture[pictureid]\\\" value=\\\"$picture[pictureid]\\\" tabindex=\\\"1\\\" $cover_checked /><label for=\\\"rb_coverpictureid_pic$picture[pictureid]\\\">$vbphrase[this_is_album_cover]</label>\r\n		</div>\r\n		\") : (\"\".(($picture[\'state\'] == \'moderation\') ? (\"\r\n			<div class=\\\"shade\\\">$vbphrase[picture_moderated]</div>\r\n		\") : (\"\")).\"\")).\"\r\n	</td>\r\n</tr>\r\n</table>\r\n</fieldset>', '<fieldset style=\"margin-top: $stylevar[cellpadding]px\" class=\"fieldset\">\r\n<table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"$stylevar[cellpadding]\">\r\n<tr>\r\n	<td class=\"smallfont\" valign=\"top\">\r\n		<div>\r\n			$vbphrase[caption]:\r\n			<div><textarea name=\"pictures[$picture[pictureid]][caption]\" rows=\"5\" cols=\"50\" style=\"width: 98%\" tabindex=\"1\">$picture[caption]</textarea></div>\r\n		</div>\r\n\r\n		<if condition=\"$show[\'move_to_album\']\">\r\n		<div style=\"float:$stylevar[right];padding-$stylevar[right]:$stylevar[cellpadding]px\">\r\n			<label for=\"cb_move_pic$picture[pictureid]\">$vbphrase[move_to_album]: </label> <select name=\"pictures[$picture[pictureid]][album]\" id=\"cb_move_pic$picture[pictureid]\" tabindex=\"1\" />$album_options</select>\r\n		</div>\r\n		</if>\r\n		<if condition=\"$show[\'delete_option\']\">\r\n		<div style=\"float:$stylevar[left]\">\r\n			<input type=\"checkbox\" name=\"pictures[$picture[pictureid]][delete]\" id=\"cb_delete_pic$picture[pictureid]\" value=\"1\" tabindex=\"1\" /><label for=\"cb_delete_pic$picture[pictureid]\">$vbphrase[delete_this_picture]</label> <if condition=\"$picture[\'usedincss\']\"><span class=\"shade\">($vbphrase[pictured_used_profile_styling])</span></if>\r\n		</div>\r\n		</if>\r\n		<if condition=\"$show[\'approve_option\']\">\r\n		<div style=\"float:$stylevar[left];clear:$stylevar[left]\">\r\n			<input type=\"checkbox\" name=\"pictures[$picture[pictureid]][approve]\" id=\"cb_approve_pic$picture[pictureid]\" value=\"1\" tabindex=\"1\" /><label for=\"cb_approve_pic$picture[pictureid]\">$vbphrase[approve_this_picture]</label>\r\n		</div>		\r\n		</if>	\r\n	</td>\r\n	<td class=\"smallfont\" valign=\"top\" width=\"<if condition=\"$vboptions[\'album_thumbsize\'] > 170\">$vboptions[album_thumbsize]<else />170</if>\">\r\n		<div style=\"white-space:nowrap\">\r\n		<if condition=\"$picture[\'thumburl\']\">\r\n			<a href=\"album.php?$session[sessionurl]albumid=$albuminfo[albumid]&amp;pictureid=$picture[pictureid]\"><img src=\"$picture[thumburl]\" alt=\"$picture[caption_preview]\" border=\"0\" $picture[dimensions] /></a>\r\n		<else />\r\n			<a href=\"album.php?$session[sessionurl]albumid=$albuminfo[albumid]&amp;pictureid=$picture[pictureid]\"><if condition=\"$picture[\'caption_preview\']\">$picture[caption_preview]<else />$vbphrase[picture]</if></a>\r\n		</if>\r\n		</div>\r\n\r\n		<if condition=\"$show[\'album_cover\']\">\r\n		<div>\r\n			<input type=\"radio\" name=\"coverpictureid\" id=\"rb_coverpictureid_pic$picture[pictureid]\" value=\"$picture[pictureid]\" tabindex=\"1\" $cover_checked /><label for=\"rb_coverpictureid_pic$picture[pictureid]\">$vbphrase[this_is_album_cover]</label>\r\n		</div>\r\n		<else /><if condition=\"$picture[\'state\'] == \'moderation\'\">\r\n			<div class=\"shade\">$vbphrase[picture_moderated]</div>\r\n		</if></if>\r\n	</td>\r\n</tr>\r\n</table>\r\n</fieldset>', 'template', 1237551145, 'vBulletin Solutions', '3.8.2', 'vbulletin'),
(87, -1, 'album_picture_upload', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n$usercss\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $vbphrase[upload_pictures]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<div id=\\\"usercss\\\">\r\n\r\n$errortable\r\n\r\n<form action=\\\"album.php?do=uploadpictures&amp;albumid=$albuminfo[albumid]\\\" method=\\\"post\\\" enctype=\\\"multipart/form-data\\\">\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		$vbphrase[upload_pictures]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n			<fieldset class=\\\"fieldset\\\">\r\n				<legend>$vbphrase[pictures_to_upload]</legend>\r\n				<div style=\\\"padding:$stylevar[formspacer]px\\\">$uploadbits</div>\r\n				\".(($show[\'moderation\']) ? (\"\r\n					<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n					$vbphrase[picture_moderation_enabled]\r\n					</div>\r\n				\") : (\"\")).\"\r\n			</fieldset>\r\n\r\n			\".(($show[\'limit_info\']) ? (\"\r\n			<fieldset class=\\\"fieldset\\\">\r\n				<legend>$vbphrase[picture_limits]</legend>\r\n				<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n					<table border=\\\"0\\\" cellpadding=\\\"2\\\" cellspacing=\\\"0\\\">\r\n					<col style=\\\"padding-$stylevar[right]: $stylevar[cellpadding]px\\\" />\r\n					\".(($show[\'max_pic_limit\']) ? (\"\r\n						<tr>\r\n							<td nowrap=\\\"nowrap\\\">$vbphrase[pictures_remaining]</td>\r\n							<td>$limit_info[pic_remain]</td>\r\n						</tr>\r\n					\") : (\"\")).\"\r\n					\".(($show[\'max_totalsize_limit\']) ? (\"\r\n						<tr>\r\n							<td nowrap=\\\"nowrap\\\">$vbphrase[space_remaining]</td>\r\n							<td>$limit_info[totalsize_remain]</td>\r\n						</tr>\r\n					\") : (\"\")).\"\r\n					\".(($show[\'max_picsize_limit\']) ? (\"\r\n						<tr>\r\n							<td nowrap=\\\"nowrap\\\">$vbphrase[max_file_size_per_picture]</td>\r\n							<td>$limit_info[picsize_limit]</td>\r\n						</tr>\r\n					\") : (\"\")).\"\r\n					\".(($show[\'max_dim_limit\']) ? (\"\r\n						<tr>\r\n							<td nowrap=\\\"nowrap\\\">$vbphrase[max_picture_dimensions]</td>\r\n							<td>\" . construct_phrase(\"$vbphrase[x_by_y_pixels]\", \"$limit_info[width_limit]\", \"$limit_info[height_limit]\") . \"</td>\r\n						</tr>\r\n					\") : (\"\")).\"\r\n					</table>\r\n\r\n					\".(($show[\'max_dim_limit\'] OR $show[\'max_picsize_limit\']) ? (\"\r\n						<div class=\\\"smallfont shade\\\" style=\\\"padding:2px\\\">$vbphrase[pictures_automatically_resized_better_manually]</div>\r\n					\") : (\"\")).\"\r\n				</div>\r\n			</fieldset>\r\n			\") : (\"\")).\"\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"uploadpictures\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"albumid\\\" value=\\\"$albuminfo[albumid]\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"MAX_FILE_SIZE\\\" value=\\\"$inimaxattach\\\" />\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[upload_pictures]\\\" accesskey=\\\"s\\\" tabindex=\\\"1\\\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n</form>\r\n\r\n</div>\r\n\r\n$footer\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n$usercss\r\n<title>$vboptions[bbtitle] - $vbphrase[upload_pictures]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<div id=\"usercss\">\r\n\r\n$errortable\r\n\r\n<form action=\"album.php?do=uploadpictures&amp;albumid=$albuminfo[albumid]\" method=\"post\" enctype=\"multipart/form-data\">\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		$vbphrase[upload_pictures]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n			<fieldset class=\"fieldset\">\r\n				<legend>$vbphrase[pictures_to_upload]</legend>\r\n				<div style=\"padding:$stylevar[formspacer]px\">$uploadbits</div>\r\n				<if condition=\"$show[\'moderation\']\">\r\n					<div style=\"padding:$stylevar[formspacer]px\">\r\n					$vbphrase[picture_moderation_enabled]\r\n					</div>\r\n				</if>\r\n			</fieldset>\r\n\r\n			<if condition=\"$show[\'limit_info\']\">\r\n			<fieldset class=\"fieldset\">\r\n				<legend>$vbphrase[picture_limits]</legend>\r\n				<div style=\"padding:$stylevar[formspacer]px\">\r\n					<table border=\"0\" cellpadding=\"2\" cellspacing=\"0\">\r\n					<col style=\"padding-$stylevar[right]: $stylevar[cellpadding]px\" />\r\n					<if condition=\"$show[\'max_pic_limit\']\">\r\n						<tr>\r\n							<td nowrap=\"nowrap\">$vbphrase[pictures_remaining]</td>\r\n							<td>$limit_info[pic_remain]</td>\r\n						</tr>\r\n					</if>\r\n					<if condition=\"$show[\'max_totalsize_limit\']\">\r\n						<tr>\r\n							<td nowrap=\"nowrap\">$vbphrase[space_remaining]</td>\r\n							<td>$limit_info[totalsize_remain]</td>\r\n						</tr>\r\n					</if>\r\n					<if condition=\"$show[\'max_picsize_limit\']\">\r\n						<tr>\r\n							<td nowrap=\"nowrap\">$vbphrase[max_file_size_per_picture]</td>\r\n							<t