select>\r\n		</div>\r\n		<!-- / forum field -->\r\n\r\n		<!-- title field -->\r\n		<div class=\\\"smallfont\\\" style=\\\"margin-bottom:$stylevar[formspacer]px\\\">\r\n			$vbphrase[title]:<br />\r\n			<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"title\\\" value=\\\"$announcementinfo[title_safe]\\\" size=\\\"50\\\" tabindex=\\\"1\\\" />\r\n		</div>\r\n		<!-- / title field -->\r\n\r\n		<!-- message area -->\r\n		<div class=\\\"smallfont\\\">$vbphrase[message]:</div>\r\n		$messagearea\r\n		<!-- / message area -->\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" name=\\\"sbutton\\\" id=\\\"{$editorid}_save\\\" value=\\\"$vbphrase[save_changes]\\\" accesskey=\\\"s\\\" tabindex=\\\"1\\\" />\r\n	</div>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		<a style=\\\"float:$stylevar[right]\\\" href=\\\"#top\\\" onclick=\\\"return toggle_collapse(\'editannc_options\')\\\"><img id=\\\"collapseimg_editannc_options\\\" src=\\\"$stylevar[imgdir_button]/collapse_tcat$vbcollapse[collapseimg_editannc_options].gif\\\" alt=\\\"\\\" border=\\\"0\\\" /></a>\r\n		$vbphrase[additional_options]\r\n	</td>\r\n</tr>\r\n<tbody id=\\\"collapseobj_editannc_options\\\" style=\\\"$vbcollapse[collapseobj_editannc_options]\\\">\r\n	<tr valign=\\\"top\\\">\r\n		<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n		<div class=\\\"panel\\\">\r\n			<div style=\\\"width:$stylevar[formwidth_usercp]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n				<!-- date fields -->\r\n				<fieldset class=\\\"fieldset\\\">\r\n					<legend>$vbphrase[start_date] / $vbphrase[end_date]</legend>\r\n					<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n					<tr>\r\n						<td>\r\n							$vbphrase[start_date]<br />\r\n							<select name=\\\"startdate[month]\\\" tabindex=\\\"1\\\">\r\n								<option value=\\\"1\\\" $start_month_selected[1]>$vbphrase[january]</option>\r\n								<option value=\\\"2\\\" $start_month_selected[2]>$vbphrase[february]</option>\r\n								<option value=\\\"3\\\" $start_month_selected[3]>$vbphrase[march]</option>\r\n								<option value=\\\"4\\\" $start_month_selected[4]>$vbphrase[april]</option>\r\n								<option value=\\\"5\\\" $start_month_selected[5]>$vbphrase[may]</option>\r\n								<option value=\\\"6\\\" $start_month_selected[6]>$vbphrase[june]</option>\r\n								<option value=\\\"7\\\" $start_month_selected[7]>$vbphrase[july]</option>\r\n								<option value=\\\"8\\\" $start_month_selected[8]>$vbphrase[august]</option>\r\n								<option value=\\\"9\\\" $start_month_selected[9]>$vbphrase[september]</option>\r\n								<option value=\\\"10\\\" $start_month_selected[10]>$vbphrase[october]</option>\r\n								<option value=\\\"11\\\" $start_month_selected[11]>$vbphrase[november]</option>\r\n								<option value=\\\"12\\\" $start_month_selected[12]>$vbphrase[december]</option>\r\n							</select>\r\n							<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"startdate[day]\\\" value=\\\"$start_date_array[day]\\\" size=\\\"2\\\" tabindex=\\\"1\\\" />\r\n							<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"startdate[year]\\\" value=\\\"$start_date_array[year]\\\" size=\\\"4\\\" tabindex=\\\"1\\\" />\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td>\r\n							$vbphrase[end_date]<br />\r\n							<select name=\\\"enddate[month]\\\" tabindex=\\\"1\\\">\r\n								<option value=\\\"1\\\" $end_month_selected[1]>$vbphrase[january]</option>\r\n								<option value=\\\"2\\\" $end_month_selected[2]>$vbphrase[february]</option>\r\n								<option value=\\\"3\\\" $end_month_selected[3]>$vbphrase[march]</option>\r\n								<option value=\\\"4\\\" $end_month_selected[4]>$vbphrase[april]</option>\r\n								<option value=\\\"5\\\" $end_month_selected[5]>$vbphrase[may]</option>\r\n								<option value=\\\"6\\\" $end_month_selected[6]>$vbphrase[june]</option>\r\n								<option value=\\\"7\\\" $end_month_selected[7]>$vbphrase[july]</option>\r\n								<option value=\\\"8\\\" $end_month_selected[8]>$vbphrase[august]</option>\r\n								<option value=\\\"9\\\" $end_month_selected[9]>$vbphrase[september]</option>\r\n								<option value=\\\"10\\\" $end_month_selected[10]>$vbphrase[october]</option>\r\n								<option value=\\\"11\\\" $end_month_selected[11]>$vbphrase[november]</option>\r\n								<option value=\\\"12\\\" $end_month_selected[12]>$vbphrase[december]</option>\r\n							</select>\r\n							<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"enddate[day]\\\" value=\\\"$end_date_array[day]\\\" size=\\\"2\\\" tabindex=\\\"1\\\" />\r\n							<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"enddate[year]\\\" value=\\\"$end_date_array[year]\\\" size=\\\"4\\\" tabindex=\\\"1\\\" />\r\n						</td>\r\n					</tr>\r\n					</table>\r\n				</fieldset>\r\n				<!-- / date fields -->\r\n\r\n				<fieldset class=\\\"fieldset\\\">\r\n					<legend>$vbphrase[miscellaneous_options]</legend>\r\n					<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n						<div><label for=\\\"cb_bbcode\\\"><input type=\\\"checkbox\\\" name=\\\"options[allowbbcode]\\\" id=\\\"cb_bbcode\\\" value=\\\"1\\\" $checked[allowbbcode] />$vbphrase[allow_bbcode]</label></div>\r\n						<div><label for=\\\"cb_html\\\"><input type=\\\"checkbox\\\" name=\\\"options[allowhtml]\\\" id=\\\"cb_html\\\" value=\\\"1\\\" $checked[allowhtml] />$vbphrase[allow_html]</label></div>\r\n						<div><label for=\\\"cb_smilies\\\"><input type=\\\"checkbox\\\" name=\\\"options[allowsmilies]\\\" id=\\\"cb_smilies\\\" value=\\\"1\\\" $checked[allowsmilies] />$vbphrase[allow_smilies]</label></div>\r\n						<div><label for=\\\"cb_parseurl\\\"><input type=\\\"checkbox\\\" name=\\\"options[parseurl]\\\" value=\\\"1\\\" id=\\\"cb_parseurl\\\" tabindex=\\\"1\\\" $checked[parseurl] />$vbphrase[automatically_parse_links_in_text]</label></div>\r\n						<div><label for=\\\"cb_signature\\\"><input type=\\\"checkbox\\\" name=\\\"options[signature]\\\" value=\\\"1\\\" id=\\\"cb_signature\\\" tabindex=\\\"1\\\" $checked[signature] />$vbphrase[show_your_signature]</label></div>\r\n					</div>\r\n				</fieldset>\r\n\r\n				\".(($show[\'editing_mode\']) ? (\"\r\n					<div class=\\\"fieldset\\\">\r\n						<label for=\\\"cb_rstvws\\\"><input type=\\\"checkbox\\\" name=\\\"reset_views\\\" id=\\\"cb_rstvws\\\" value=\\\"1\\\" />$vbphrase[reset_views_counter]</label>\r\n					</div>\r\n				\") : (\"\")).\"\r\n\r\n			</div>\r\n		</div>\r\n\r\n		<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n			<input type=\\\"submit\\\" class=\\\"button\\\" name=\\\"sbutton\\\" value=\\\"$vbphrase[save_changes]\\\" tabindex=\\\"1\\\" />\r\n		</div>\r\n		</td>\r\n	</tr>\r\n</table>\r\n\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"update\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"announcementid\\\" value=\\\"$announcementinfo[announcementid]\\\" />\r\n</form>\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n	<title>$vboptions[bbtitle] - <if condition=\"$show[\'editing_mode\']\">$vbphrase[edit_announcement]<else />$vbphrase[post_new_announcement]</if></title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<if condition=\"$show[\'editing_mode\']\">\r\n<form action=\"announcement.php?do=delete&amp;a=$announcementinfo[announcementid]\" method=\"post\">\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		<a style=\"float:$stylevar[right]\" href=\"#top\" onclick=\"return toggle_collapse(\'editpost_delete\')\"><img id=\"collapseimg_editpost_delete\" src=\"$stylevar[imgdir_button]/collapse_tcat$vbcollapse[collapseimg_editpost_delete].gif\" alt=\"\" border=\"0\" /></a>\r\n		$vbphrase[delete_this_message]\r\n	</td>\r\n</tr>\r\n<tbody id=\"collapseobj_editpost_delete\" style=\"$vbcollapse[collapseobj_editpost_delete]\">\r\n	<tr>\r\n		<td class=\"panelsurround\" align=\"center\">\r\n		<div class=\"panel\">\r\n			<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n				<div class=\"fieldset\">\r\n					<div><label for=\"rb_del_leave\"><input type=\"radio\" name=\"delete\" value=\"\" id=\"rb_del_leave\" tabindex=\"1\" checked=\"checked\" />$vbphrase[do_not_delete_message]</label></div>\r\n					<div><label for=\"rb_del_soft\"><input type=\"radio\" name=\"delete\" value=\"delete\" id=\"rb_del_soft\" tabindex=\"1\" />$vbphrase[delete_message]</label></div>\r\n				</div>\r\n			</div>\r\n		</div>\r\n		<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n			<input type=\"submit\" class=\"button\" value=\"$vbphrase[delete_this_message]\" tabindex=\"1\" accesskey=\"d\" />\r\n		</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n<input type=\"hidden\" name=\"do\" value=\"delete\" />\r\n<input type=\"hidden\" name=\"announcementid\" value=\"$announcementinfo[announcementid]\" />\r\n</form>\r\n<br />\r\n</if>\r\n\r\n<form name=\"vbform\" action=\"announcement.php?do=update&amp;a=$announcementinfo[announcementid]\" method=\"post\"<if condition=\"!is_browser(\'webtv\')\"> onsubmit=\"return vB_Editor[\'$editorid\'].prepare_submit(0, 0)\"</if>>\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		<if condition=\"$show[\'editing_mode\']\">\r\n			<span class=\"smallfont\" style=\"float:$stylevar[right]\"><strong>$vbphrase[announcement]</strong> <a href=\"announcement.php?$session[sessionurl]a=$announcementinfo[announcementid]\">$announcementinfo[title]</a></span>\r\n			$vbphrase[edit_announcement]\r\n		<else />\r\n			$vbphrase[post_new_announcement]\r\n		</if>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n\r\n		$usernamecode\r\n\r\n		<!-- forum field -->\r\n		<div class=\"smallfont\" style=\"margin-bottom:$stylevar[formspacer]px\">\r\n			$vbphrase[forum]:<br />\r\n			<select name=\"forumid\" tabindex=\"1\">$forum_options</select>\r\n		</div>\r\n		<!-- / forum field -->\r\n\r\n		<!-- title field -->\r\n		<div class=\"smallfont\" style=\"margin-bottom:$stylevar[formspacer]px\">\r\n			$vbphrase[title]:<br />\r\n			<input type=\"text\" class=\"bginput\" name=\"title\" value=\"$announcementinfo[title_safe]\" size=\"50\" tabindex=\"1\" />\r\n		</div>\r\n		<!-- / title field -->\r\n\r\n		<!-- message area -->\r\n		<div class=\"smallfont\">$vbphrase[message]:</div>\r\n		$messagearea\r\n		<!-- / message area -->\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"submit\" class=\"button\" name=\"sbutton\" id=\"{$editorid}_save\" value=\"$vbphrase[save_changes]\" accesskey=\"s\" tabindex=\"1\" />\r\n	</div>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		<a style=\"float:$stylevar[right]\" href=\"#top\" onclick=\"return toggle_collapse(\'editannc_options\')\"><img id=\"collapseimg_editannc_options\" src=\"$stylevar[imgdir_button]/collapse_tcat$vbcollapse[collapseimg_editannc_options].gif\" alt=\"\" border=\"0\" /></a>\r\n		$vbphrase[additional_options]\r\n	</td>\r\n</tr>\r\n<tbody id=\"collapseobj_editannc_options\" style=\"$vbcollapse[collapseobj_editannc_options]\">\r\n	<tr valign=\"top\">\r\n		<td class=\"panelsurround\" align=\"center\">\r\n		<div class=\"panel\">\r\n			<div style=\"width:$stylevar[formwidth_usercp]\" align=\"$stylevar[left]\">\r\n\r\n				<!-- date fields -->\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[start_date] / $vbphrase[end_date]</legend>\r\n					<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n					<tr>\r\n						<td>\r\n							$vbphrase[start_date]<br />\r\n							<select name=\"startdate[month]\" tabindex=\"1\">\r\n								<option value=\"1\" $start_month_selected[1]>$vbphrase[january]</option>\r\n								<option value=\"2\" $start_month_selected[2]>$vbphrase[february]</option>\r\n								<option value=\"3\" $start_month_selected[3]>$vbphrase[march]</option>\r\n								<option value=\"4\" $start_month_selected[4]>$vbphrase[april]</option>\r\n								<option value=\"5\" $start_month_selected[5]>$vbphrase[may]</option>\r\n								<option value=\"6\" $start_month_selected[6]>$vbphrase[june]</option>\r\n								<option value=\"7\" $start_month_selected[7]>$vbphrase[july]</option>\r\n								<option value=\"8\" $start_month_selected[8]>$vbphrase[august]</option>\r\n								<option value=\"9\" $start_month_selected[9]>$vbphrase[september]</option>\r\n								<option value=\"10\" $start_month_selected[10]>$vbphrase[october]</option>\r\n								<option value=\"11\" $start_month_selected[11]>$vbphrase[november]</option>\r\n								<option value=\"12\" $start_month_selected[12]>$vbphrase[december]</option>\r\n							</select>\r\n							<input type=\"text\" class=\"bginput\" name=\"startdate[day]\" value=\"$start_date_array[day]\" size=\"2\" tabindex=\"1\" />\r\n							<input type=\"text\" class=\"bginput\" name=\"startdate[year]\" value=\"$start_date_array[year]\" size=\"4\" tabindex=\"1\" />\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td>\r\n							$vbphrase[end_date]<br />\r\n							<select name=\"enddate[month]\" tabindex=\"1\">\r\n								<option value=\"1\" $end_month_selected[1]>$vbphrase[january]</option>\r\n								<option value=\"2\" $end_month_selected[2]>$vbphrase[february]</option>\r\n								<option value=\"3\" $end_month_selected[3]>$vbphrase[march]</option>\r\n								<option value=\"4\" $end_month_selected[4]>$vbphrase[april]</option>\r\n								<option value=\"5\" $end_month_selected[5]>$vbphrase[may]</option>\r\n								<option value=\"6\" $end_month_selected[6]>$vbphrase[june]</option>\r\n								<option value=\"7\" $end_month_selected[7]>$vbphrase[july]</option>\r\n								<option value=\"8\" $end_month_selected[8]>$vbphrase[august]</option>\r\n								<option value=\"9\" $end_month_selected[9]>$vbphrase[september]</option>\r\n								<option value=\"10\" $end_month_selected[10]>$vbphrase[october]</option>\r\n								<option value=\"11\" $end_month_selected[11]>$vbphrase[november]</option>\r\n								<option value=\"12\" $end_month_selected[12]>$vbphrase[december]</option>\r\n							</select>\r\n							<input type=\"text\" class=\"bginput\" name=\"enddate[day]\" value=\"$end_date_array[day]\" size=\"2\" tabindex=\"1\" />\r\n							<input type=\"text\" class=\"bginput\" name=\"enddate[year]\" value=\"$end_date_array[year]\" size=\"4\" tabindex=\"1\" />\r\n						</td>\r\n					</tr>\r\n					</table>\r\n				</fieldset>\r\n				<!-- / date fields -->\r\n\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[miscellaneous_options]</legend>\r\n					<div style=\"padding:$stylevar[formspacer]px\">\r\n						<div><label for=\"cb_bbcode\"><input type=\"checkbox\" name=\"options[allowbbcode]\" id=\"cb_bbcode\" value=\"1\" $checked[allowbbcode] />$vbphrase[allow_bbcode]</label></div>\r\n						<div><label for=\"cb_html\"><input type=\"checkbox\" name=\"options[allowhtml]\" id=\"cb_html\" value=\"1\" $checked[allowhtml] />$vbphrase[allow_html]</label></div>\r\n						<div><label for=\"cb_smilies\"><input type=\"checkbox\" name=\"options[allowsmilies]\" id=\"cb_smilies\" value=\"1\" $checked[allowsmilies] />$vbphrase[allow_smilies]</label></div>\r\n						<div><label for=\"cb_parseurl\"><input type=\"checkbox\" name=\"options[parseurl]\" value=\"1\" id=\"cb_parseurl\" tabindex=\"1\" $checked[parseurl] />$vbphrase[automatically_parse_links_in_text]</label></div>\r\n						<div><label for=\"cb_signature\"><input type=\"checkbox\" name=\"options[signature]\" value=\"1\" id=\"cb_signature\" tabindex=\"1\" $checked[signature] />$vbphrase[show_your_signature]</label></div>\r\n					</div>\r\n				</fieldset>\r\n\r\n				<if condition=\"$show[\'editing_mode\']\">\r\n					<div class=\"fieldset\">\r\n						<label for=\"cb_rstvws\"><input type=\"checkbox\" name=\"reset_views\" id=\"cb_rstvws\" value=\"1\" />$vbphrase[reset_views_counter]</label>\r\n					</div>\r\n				</if>\r\n\r\n			</div>\r\n		</div>\r\n\r\n		<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n			<input type=\"submit\" class=\"button\" name=\"sbutton\" value=\"$vbphrase[save_changes]\" tabindex=\"1\" />\r\n		</div>\r\n		</td>\r\n	</tr>\r\n</table>\r\n\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n<input type=\"hidden\" name=\"do\" value=\"update\" />\r\n<input type=\"hidden\" name=\"announcementid\" value=\"$announcementinfo[announcementid]\" />\r\n</form>\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', 'template', 1208880816, 'vBulletin Solutions', '3.7.0 Release Candidate 4', 'vbulletin'),
(92, -1, 'bbcode_code', '<div style=\\\"margin:20px; margin-top:5px\\\">\r\n	<div class=\\\"smallfont\\\" style=\\\"margin-bottom:2px\\\">$vbphrase[code]:</div>\r\n	<pre class=\\\"alt2\\\" dir=\\\"ltr\\\" style=\\\"\r\n		margin: 0px;\r\n		padding: $stylevar[cellpadding]px;\r\n		border: 1px inset;\r\n		width: $stylevar[codeblockwidth];\r\n		height: {$blockheight}px;\r\n		text-align: left;\r\n		overflow: auto\\\">$code</pre>\r\n</div>', '<div style=\"margin:20px; margin-top:5px\">\r\n	<div class=\"smallfont\" style=\"margin-bottom:2px\">$vbphrase[code]:</div>\r\n	<pre class=\"alt2\" dir=\"ltr\" style=\"\r\n		margin: 0px;\r\n		padding: $stylevar[cellpadding]px;\r\n		border: 1px inset;\r\n		width: $stylevar[codeblockwidth];\r\n		height: {$blockheight}px;\r\n		text-align: left;\r\n		overflow: auto\">$code</pre>\r\n</div>', 'template', 1164202755, 'vBulletin Solutions', '3.6.4', 'vbulletin'),
(93, -1, 'bbcode_code_printable', '<div style=\\\"margin:20px; margin-top:5px\\\">\r\n	<div class=\\\"smallfont\\\" style=\\\"margin-bottom:2px\\\">$vbphrase[code]:</div>\r\n	<hr /><code style=\\\"margin:0px\\\" dir=\\\"ltr\\\" style=\\\"text-align:left\\\">$code</code><hr />\r\n</div>', '<div style=\"margin:20px; margin-top:5px\">\r\n	<div class=\"smallfont\" style=\"margin-bottom:2px\">$vbphrase[code]:</div>\r\n	<hr /><code style=\"margin:0px\" dir=\"ltr\" style=\"text-align:left\">$code</code><hr />\r\n</div>', 'template', 1136596081, 'vBulletin Solutions', '3.6.0 Beta 1', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(94, -1, 'bbcode_html', '<div style=\\\"margin:20px; margin-top:5px\\\">\r\n	<div class=\\\"smallfont\\\" style=\\\"margin-bottom:2px\\\">$vbphrase[html_code]:</div>\r\n	<pre class=\\\"alt2\\\" dir=\\\"ltr\\\" style=\\\"\r\n		margin: 0px;\r\n		padding: $stylevar[cellpadding]px;\r\n		border: 1px inset;\r\n		width: $stylevar[codeblockwidth];\r\n		height: {$blockheight}px;\r\n		text-align: left;\r\n		overflow: auto\\\">$code</pre>\r\n</div>', '<div style=\"margin:20px; margin-top:5px\">\r\n	<div class=\"smallfont\" style=\"margin-bottom:2px\">$vbphrase[html_code]:</div>\r\n	<pre class=\"alt2\" dir=\"ltr\" style=\"\r\n		margin: 0px;\r\n		padding: $stylevar[cellpadding]px;\r\n		border: 1px inset;\r\n		width: $stylevar[codeblockwidth];\r\n		height: {$blockheight}px;\r\n		text-align: left;\r\n		overflow: auto\">$code</pre>\r\n</div>', 'template', 1164202759, 'vBulletin Solutions', '3.6.4', 'vbulletin'),
(95, -1, 'bbcode_html_printable', '<div style=\\\"margin:20px; margin-top:5px\\\">\r\n	<div class=\\\"smallfont\\\" style=\\\"margin-bottom:2px\\\">$vbphrase[html_code]:</div>\r\n	<hr /><code style=\\\"margin:0px\\\" dir=\\\"ltr\\\" style=\\\"text-align:left\\\">$code</code><hr />\r\n</div>', '<div style=\"margin:20px; margin-top:5px\">\r\n	<div class=\"smallfont\" style=\"margin-bottom:2px\">$vbphrase[html_code]:</div>\r\n	<hr /><code style=\"margin:0px\" dir=\"ltr\" style=\"text-align:left\">$code</code><hr />\r\n</div>', 'template', 1136596090, 'vBulletin Solutions', '3.6.0 Beta 1', 'vbulletin'),
(96, -1, 'bbcode_php', '<div style=\\\"margin:20px; margin-top:5px\\\">\r\n	<div class=\\\"smallfont\\\" style=\\\"margin-bottom:2px\\\">$vbphrase[php_code]:</div>\r\n	<div class=\\\"alt2\\\" dir=\\\"ltr\\\" style=\\\"\r\n		margin: 0px;\r\n		padding: $stylevar[cellpadding]px;\r\n		border: 1px inset;\r\n		width: $stylevar[codeblockwidth];\r\n		height: {$blockheight}px;\r\n		text-align: left;\r\n		overflow: auto\\\">\r\n		<code style=\\\"white-space:nowrap\\\">\r\n			<!-- php buffer start -->$code<!-- php buffer end -->\r\n		</code>\r\n	</div>\r\n</div>', '<div style=\"margin:20px; margin-top:5px\">\r\n	<div class=\"smallfont\" style=\"margin-bottom:2px\">$vbphrase[php_code]:</div>\r\n	<div class=\"alt2\" dir=\"ltr\" style=\"\r\n		margin: 0px;\r\n		padding: $stylevar[cellpadding]px;\r\n		border: 1px inset;\r\n		width: $stylevar[codeblockwidth];\r\n		height: {$blockheight}px;\r\n		text-align: left;\r\n		overflow: auto\">\r\n		<code style=\"white-space:nowrap\">\r\n			<!-- php buffer start -->$code<!-- php buffer end -->\r\n		</code>\r\n	</div>\r\n</div>', 'template', 1164202763, 'vBulletin Solutions', '3.6.4', 'vbulletin'),
(97, -1, 'bbcode_php_printable', '<div style=\\\"margin:20px; margin-top:5px\\\">\r\n	<div class=\\\"smallfont\\\" style=\\\"margin-bottom:2px\\\">$vbphrase[php_code]:</div>\r\n	<div class=\\\"alt2\\\">\r\n		<hr />\r\n		<code style=\\\"white-space:nowrap\\\">\r\n		<div dir=\\\"ltr\\\" style=\\\"text-align:left;\\\">\r\n			<!-- php buffer start -->$code<!-- php buffer end -->\r\n		</div>\r\n		</code>\r\n		<hr />\r\n	</div>\r\n</div>', '<div style=\"margin:20px; margin-top:5px\">\r\n	<div class=\"smallfont\" style=\"margin-bottom:2px\">$vbphrase[php_code]:</div>\r\n	<div class=\"alt2\">\r\n		<hr />\r\n		<code style=\"white-space:nowrap\">\r\n		<div dir=\"ltr\" style=\"text-align:left;\">\r\n			<!-- php buffer start -->$code<!-- php buffer end -->\r\n		</div>\r\n		</code>\r\n		<hr />\r\n	</div>\r\n</div>', 'template', 1136596100, 'vBulletin Solutions', '3.6.0 Beta 1', 'vbulletin'),
(98, -1, 'bbcode_quote', '<div style=\\\"margin:20px; margin-top:5px; \".(($show[\'iewidthfix\']) ? (\"width: 100%;\") : (\"\")).\"\\\">\r\n	<div class=\\\"smallfont\\\" style=\\\"margin-bottom:2px\\\">$vbphrase[quote]:</div>\r\n	<table cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n	<tr>\r\n		<td class=\\\"alt2\\\" style=\\\"border:1px inset\\\">\r\n			\".(($show[\'username\']) ? (\"\r\n				<div>\r\n					\" . construct_phrase(\"$vbphrase[originally_posted_by_x]\", \"$username\") . \"\r\n					\".(($postid) ? (\"<a href=\\\"showthread.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"p=$postid#post$postid\\\" rel=\\\"nofollow\\\"><img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_button]/viewpost.gif\\\" border=\\\"0\\\" alt=\\\"$vbphrase[view_post]\\\" /></a>\") : (\"\")).\"\r\n				</div>\r\n				<div style=\\\"font-style:italic\\\">$message</div>\r\n			\") : (\"\r\n				$message\r\n			\")).\"\r\n		</td>\r\n	</tr>\r\n	</table>\r\n</div>', '<div style=\"margin:20px; margin-top:5px; <if condition=\"$show[\'iewidthfix\']\">width: 100%;</if>\">\r\n	<div class=\"smallfont\" style=\"margin-bottom:2px\">$vbphrase[quote]:</div>\r\n	<table cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"0\" border=\"0\" width=\"100%\">\r\n	<tr>\r\n		<td class=\"alt2\" style=\"border:1px inset\">\r\n			<if condition=\"$show[\'username\']\">\r\n				<div>\r\n					<phrase 1=\"$username\">$vbphrase[originally_posted_by_x]</phrase>\r\n					<if condition=\"$postid\"><a href=\"showthread.php?$session[sessionurl]p=$postid#post$postid\" rel=\"nofollow\"><img class=\"inlineimg\" src=\"$stylevar[imgdir_button]/viewpost.gif\" border=\"0\" alt=\"$vbphrase[view_post]\" /></a></if>\r\n				</div>\r\n				<div style=\"font-style:italic\">$message</div>\r\n			<else />\r\n				$message\r\n			</if>\r\n		</td>\r\n	</tr>\r\n	</table>\r\n</div>', 'template', 1149092965, 'vBulletin Solutions', '3.6.0 Beta 1', 'vbulletin'),
(99, -1, 'bbcode_quote_printable', '<div style=\\\"margin:20px; margin-top:5px; \".(($show[\'iewidthfix\']) ? (\"width: 100%;\") : (\"\")).\"\\\">\r\n	<div class=\\\"smallfont\\\" style=\\\"margin-bottom:2px\\\">$vbphrase[quote]:</div>\r\n	<table cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n	<tr>\r\n		<td class=\\\"alt2\\\">\r\n			<hr />\r\n			\".(($show[\'username\']) ? (\"\r\n				<div>\r\n					\" . construct_phrase(\"$vbphrase[originally_posted_by_x]\", \"$username\") . \"\r\n					\".(($postid) ? (\"\" . construct_phrase(\"($vbphrase[post_x])\", \"$postid\") . \"\") : (\"\")).\"\r\n				</div>\r\n				<div style=\\\"font-style:italic\\\">$message</div>\r\n			\") : (\"\r\n				$message\r\n			\")).\"\r\n			<hr />\r\n		</td>\r\n	</tr>\r\n	</table>\r\n</div>', '<div style=\"margin:20px; margin-top:5px; <if condition=\"$show[\'iewidthfix\']\">width: 100%;</if>\">\r\n	<div class=\"smallfont\" style=\"margin-bottom:2px\">$vbphrase[quote]:</div>\r\n	<table cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"0\" border=\"0\" width=\"100%\">\r\n	<tr>\r\n		<td class=\"alt2\">\r\n			<hr />\r\n			<if condition=\"$show[\'username\']\">\r\n				<div>\r\n					<phrase 1=\"$username\">$vbphrase[originally_posted_by_x]</phrase>\r\n					<if condition=\"$postid\"><phrase 1=\"$postid\">($vbphrase[post_x])</phrase></if>\r\n				</div>\r\n				<div style=\"font-style:italic\">$message</div>\r\n			<else />\r\n				$message\r\n			</if>\r\n			<hr />\r\n		</td>\r\n	</tr>\r\n	</table>\r\n</div>', 'template', 1142532097, 'vBulletin Solutions', '3.6.0 Beta 1', 'vbulletin'),
(100, -1, 'BUDDYLIST', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n	$headinclude\r\n	<title>$vbphrase[contacts] - \" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \"</title>\r\n	<meta http-equiv=\\\"refresh\\\" content=\\\"60; URL=misc.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=buddylist&amp;buddies=$buddies\\\" />\r\n	<script type=\\\"text/javascript\\\">\r\n	<!--\r\n	function pm(tform)\r\n	{\r\n		var users = new Array();\r\n		var arrCount = 0;\r\n		for (i = 0; i < tform.elements.length; i++)\r\n		{\r\n			var element = tform.elements[i];\r\n			if ((element.name != \\\"allbox\\\") && (element.type == \\\"checkbox\\\") && (element.checked == true))\r\n			{\r\n				users[arrCount] = element.value;\r\n				arrCount++;\r\n			}\r\n		}\r\n		if (arrCount == 0)\r\n		{\r\n			alert(\\\"$vbphrase[no_users_selected]\\\");\r\n		}\r\n		else\r\n		{\r\n			var querystring = \\\"\\\";\r\n			for (i = 0; i < users.length; i++)\r\n			{\r\n				querystring += \\\"&userid[]=\\\" + users[i];\r\n			}\r\n			if (opener && !opener.closed)\r\n			{ // parent window is still open\r\n				opener.location=\\\"private.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=newpm\\\" + querystring;\r\n			}\r\n			else\r\n			{ // parent window has closed or went to a different URL.\r\n				window.open(\\\"private.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=newpm\\\" + querystring, \\\"pm\\\");\r\n			}\r\n		}\r\n	}\r\n	// -->\r\n	</script>\r\n</head>\r\n\r\n<body style=\\\"margin:0px\\\">\r\n\r\n<form action=\\\"private.php\\\" method=\\\"post\\\" target=\\\"_blank\\\" name=\\\"vbform\\\">\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\" colspan=\\\"3\\\">$vbphrase[contacts]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"thead\\\" align=\\\"center\\\" colspan=\\\"3\\\"><span class=\\\"smallfont\\\">-- <strong>$vbphrase[online]</strong> --</span></td>\r\n</tr>\r\n$onlineusers\r\n<tr>\r\n	<td class=\\\"thead\\\" align=\\\"center\\\" colspan=\\\"3\\\"><span class=\\\"smallfont\\\">-- <strong>$vbphrase[offline]</strong> --</span></td>\r\n</tr>\r\n$offlineusers\r\n<tr>\r\n	<td class=\\\"tfoot\\\" align=\\\"center\\\" colspan=\\\"3\\\">\r\n		<input type=\\\"button\\\" class=\\\"button\\\" value=\\\"$vbphrase[reload]\\\" onclick=\\\"window.location = \'misc.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=buddylist&amp;buddies=$buddies\';\\\" />\r\n		<input type=\\\"button\\\" class=\\\"button\\\" value=\\\"$vbphrase[pm_users]\\\" onclick=\\\"pm(this.form);\\\" title=\\\"$vbphrase[send_private_message_to_selected_users]\\\" />\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>\r\n\r\n\".(($show[\'playsound\']) ? (\"\r\n<!--<embed src=\\\"YourAlertSound.wav\\\" hidden=\\\"True\\\"> -->\r\n\") : (\"\")).\"\r\n\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n	$headinclude\r\n	<title>$vbphrase[contacts] - $vboptions[bbtitle]</title>\r\n	<meta http-equiv=\"refresh\" content=\"60; URL=misc.php?$session[sessionurl]do=buddylist&amp;buddies=$buddies\" />\r\n	<script type=\"text/javascript\">\r\n	<!--\r\n	function pm(tform)\r\n	{\r\n		var users = new Array();\r\n		var arrCount = 0;\r\n		for (i = 0; i < tform.elements.length; i++)\r\n		{\r\n			var element = tform.elements[i];\r\n			if ((element.name != \"allbox\") && (element.type == \"checkbox\") && (element.checked == true))\r\n			{\r\n				users[arrCount] = element.value;\r\n				arrCount++;\r\n			}\r\n		}\r\n		if (arrCount == 0)\r\n		{\r\n			alert(\"$vbphrase[no_users_selected]\");\r\n		}\r\n		else\r\n		{\r\n			var querystring = \"\";\r\n			for (i = 0; i < users.length; i++)\r\n			{\r\n				querystring += \"&userid[]=\" + users[i];\r\n			}\r\n			if (opener && !opener.closed)\r\n			{ // parent window is still open\r\n				opener.location=\"private.php?$session[sessionurl]do=newpm\" + querystring;\r\n			}\r\n			else\r\n			{ // parent window has closed or went to a different URL.\r\n				window.open(\"private.php?$session[sessionurl]do=newpm\" + querystring, \"pm\");\r\n			}\r\n		}\r\n	}\r\n	// -->\r\n	</script>\r\n</head>\r\n\r\n<body style=\"margin:0px\">\r\n\r\n<form action=\"private.php\" method=\"post\" target=\"_blank\" name=\"vbform\">\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\">\r\n<tr>\r\n	<td class=\"tcat\" colspan=\"3\">$vbphrase[contacts]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"thead\" align=\"center\" colspan=\"3\"><span class=\"smallfont\">-- <strong>$vbphrase[online]</strong> --</span></td>\r\n</tr>\r\n$onlineusers\r\n<tr>\r\n	<td class=\"thead\" align=\"center\" colspan=\"3\"><span class=\"smallfont\">-- <strong>$vbphrase[offline]</strong> --</span></td>\r\n</tr>\r\n$offlineusers\r\n<tr>\r\n	<td class=\"tfoot\" align=\"center\" colspan=\"3\">\r\n		<input type=\"button\" class=\"button\" value=\"$vbphrase[reload]\" onclick=\"window.location = \'misc.php?$session[sessionurl]do=buddylist&amp;buddies=$buddies\';\" />\r\n		<input type=\"button\" class=\"button\" value=\"$vbphrase[pm_users]\" onclick=\"pm(this.form);\" title=\"$vbphrase[send_private_message_to_selected_users]\" />\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>\r\n\r\n<if condition=\"$show[\'playsound\']\">\r\n<!--<embed src=\"YourAlertSound.wav\" hidden=\"True\"> -->\r\n</if>\r\n\r\n</body>\r\n</html>', 'template', 1196779217, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
(101, -1, 'buddylistbit', '<tr>\r\n	<td class=\\\"alt1\\\"><a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$buddy[userid]\\\" target=\\\"_blank\\\"><img src=\\\"$stylevar[imgdir_statusicon]/user_$buddy[statusicon].gif\\\" alt=\\\"\\\" title=\\\"\" . construct_phrase(\"$vbphrase[x_is_y]\", \"$buddy[username]\", \"$buddy[statusicon]\") . \"\\\" border=\\\"0\\\" /></a></td>\r\n	<td class=\\\"alt2\\\" width=\\\"100%\\\"><label class=\\\"smallfont\\\" for=\\\"buddy_$buddy[userid]\\\">\".(($show[\'highlightuser\']) ? (\"<span class=\\\"highlight\\\">$buddy[username]</span>\") : (\"$buddy[username]\")).\"</label></td>\r\n	<td class=\\\"alt1\\\"><input type=\\\"checkbox\\\" name=\\\"userid[]\\\" id=\\\"buddy_$buddy[userid]\\\" value=\\\"$buddy[userid]\\\" /></td>\r\n</tr>\r\n', '<tr>\r\n	<td class=\"alt1\"><a href=\"member.php?$session[sessionurl]u=$buddy[userid]\" target=\"_blank\"><img src=\"$stylevar[imgdir_statusicon]/user_$buddy[statusicon].gif\" alt=\"\" title=\"<phrase 1=\"$buddy[username]\" 2=\"$buddy[statusicon]\">$vbphrase[x_is_y]</phrase>\" border=\"0\" /></a></td>\r\n	<td class=\"alt2\" width=\"100%\"><label class=\"smallfont\" for=\"buddy_$buddy[userid]\"><if condition=\"$show[\'highlightuser\']\"><span class=\"highlight\">$buddy[username]</span><else />$buddy[username]</if></label></td>\r\n	<td class=\"alt1\"><input type=\"checkbox\" name=\"userid[]\" id=\"buddy_$buddy[userid]\" value=\"$buddy[userid]\" /></td>\r\n</tr>\r\n', 'template', 1073078450, 'vBulletin Solutions', '', 'vbulletin'),
