(128, -1, 'calendar_weekly_day', '\".(($show[\'monthname\']) ? (\"\r\n<tr>\r\n	<td class=\\\"tcat\\\" colspan=\\\"2\\\">\r\n		<span style=\\\"float:$stylevar[right]\\\" class=\\\"smallfont\\\">\r\n			<a href=\\\"calendar.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"c=$calendarid&amp;week=$prevweek\\\"><strong>&laquo;</strong> $vbphrase[week]</a>\r\n			|\r\n			<a href=\\\"calendar.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"c=$calendarid&amp;week=$nextweek\\\">$vbphrase[week] <strong>&raquo;</strong></a>\r\n		</span>\r\n		$weekmonth $weekyear\r\n	</td>\r\n</tr>\r\n\") : (\"\")).\"\r\n<tr>\r\n	<td class=\\\"thead\\\" colspan=\\\"2\\\">\r\n		<a style=\\\"float:$stylevar[right]; font-weight:normal\\\" href=\\\"calendar.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=add&amp;c=$calendarinfo[calendarid]&amp;day={$weekyear}-{$month}-{$weekday}\\\">$vbphrase[add_new_event]</a>\r\n		$weekdayname\r\n	</td>\r\n</tr>\r\n<tr valign=\\\"top\\\">\r\n	<td class=\\\"alt2\\\" align=\\\"center\\\"><span style=\\\"font-size:14pt\\\">\r\n		\".(($show[\'events\']) ? (\"\r\n			<div style=\\\"cursor:pointer\\\" onclick=\\\"window.location=\'calendar.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=getinfo&amp;day={$weekyear}-{$month}-{$weekday}&amp;c=$calendarinfo[calendarid]\';\\\">$weekday</div>\r\n		\") : (\"\r\n			$weekday\r\n		\")).\"\r\n	</span></td>\r\n	\".(($show[\'highlighttoday\']) ? (\"\r\n		<td class=\\\"alt1\\\" width=\\\"100%\\\" style=\\\"border:1px solid red\\\" title=\\\"$weekmonth $weekday $weekyear\\\">\r\n	\") : (\"\r\n		<td class=\\\"alt1\\\" width=\\\"100%\\\" title=\\\"$weekmonth $weekday $weekyear\\\">\r\n	\")).\"\r\n		\".(($show[\'events\']) ? (\"\r\n			$userevents\r\n		\") : (\"\")).\"\r\n		\".(($show[\'birthdays\']) ? (\"\r\n			<div class=\\\"smallfont\\\">\r\n				<img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_misc]/birthday_small.gif\\\" alt=\\\"\\\" />\r\n				<str