(132, -1, 'editor_css', '<!-- Editor Styles -->\r\n<style type=\\\"text/css\\\" id=\\\"vbulletin_editor_css_dynamic\\\">\r\n<!--\r\n@import url(\\\"clientscript/vbulletin_editor.css?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\");\r\n\r\n.vBulletin_editor {\r\n	background: {$istyles[pi_button_normal][0]};\r\n	padding: $stylevar[cellpadding]px;\r\n}\r\n.imagebutton {\r\n	background: {$istyles[pi_button_normal][0]};\r\n	color: {$istyles[pi_button_normal][1]};\r\n	padding: {$istyles[pi_button_normal][2]};\r\n	border: {$istyles[pi_button_normal][3]};\r\n}\r\n.ocolor, .ofont, .osize, .osmilie, .osyscoloar, .smilietitle {\r\n	background: {$istyles[pi_menu_normal][0]};\r\n	color: {$istyles[pi_menu_normal][1]};\r\n	border: {$istyles[pi_menu_normal][3]};\r\n}\r\n.popup_pickbutton {\r\n	border: {$istyles[pi_menu_normal][3]};\r\n}\r\n.popup_feedback {\r\n	background: {$istyles[pi_menu_normal][0]};\r\n	color: {$istyles[pi_menu_normal][1]};\r\n	border-$stylevar[right]: {$istyles[pi_menu_normal][3]};\r\n}\r\n.popupwindow {\r\n	background: {$istyles[pi_menu_normal][0]};\r\n}\r\n#fontOut, #sizeOut, .popup_feedback div {\r\n	background: {$istyles[pi_menu_normal][0]};\r\n	color: {$istyles[pi_menu_normal][1]};\r\n}\r\n.alt_pickbutton {\r\n	border-$stylevar[left]: 1px solid {$istyles[pi_button_normal][0]};\r\n}\r\n.popup_feedback input, .popup_feedback div\r\n{\r\n	border: 0px solid;\r\n	padding: 0px 2px 0px 2px;\r\n	cursor: default;\r\n	font: 11px tahoma;\r\n	overflow: hidden;\r\n}\r\n-->\r\n</style>\r\n<!-- / Editor Styles -->', '<!-- Editor Styles -->\r\n<style type=\"text/css\" id=\"vbulletin_editor_css_dynamic\">\r\n<!--\r\n@import url(\"clientscript/vbulletin_editor.css?v=$vboptions[simpleversion]\");\r\n\r\n.vBulletin_editor {\r\n	background: {$istyles[pi_button_normal][0]};\r\n	padding: $stylevar[cellpadding]px;\r\n}\r\n.imagebutton {\r\n	background: {$istyles[pi_button_normal][0]};\r\n	color: {$istyles[pi_button_normal][1]};\r\n	padding: {$istyles[pi_button_normal][2]};\r\n	border: {$istyles[pi_button_normal][3]};\r\n}\r\n.ocolor, .ofont, .osize, .osmilie, .osyscoloar, .smilietitle {\r\n	background: {$istyles[pi_menu_normal][0]};\r\n	color: {$istyles[pi_menu_normal][1]};\r\n	border: {$istyles[pi_menu_normal][3]};\r\n}\r\n.popup_pickbutton {\r\n	border: {$istyles[pi_menu_normal][3]};\r\n}\r\n.popup_feedback {\r\n	background: {$istyles[pi_menu_normal][0]};\r\n	color: {$istyles[pi_menu_normal][1]};\r\n	border-$stylevar[right]: {$istyles[pi_menu_normal][3]};\r\n}\r\n.popupwindow {\r\n	background: {$istyles[pi_menu_normal][0]};\r\n}\r\n#fontOut, #sizeOut, .popup_feedback div {\r\n	background: {$istyles[pi_menu_normal][0]};\r\n	color: {$istyles[pi_menu_normal][1]};\r\n}\r\n.alt_pickbutton {\r\n	border-$stylevar[left]: 1px solid {$istyles[pi_button_normal][0]};\r\n}\r\n.popup_feedback input, .popup_feedback div\r\n{\r\n	border: 0px solid;\r\n	padding: 0px 2px 0px 2px;\r\n	cursor: default;\r\n	font: 11px tahoma;\r\n	overflow: hidden;\r\n}\r\n-->\r\n</style>\r\n<!-- / Editor Styles -->', 'template', 1203426342, 'vBulletin Solutions', '3.7.0 Beta 6', 'vbulletin'),
(133, -1, 'editor_jsoptions_font', 'Arial\r\nArial Black\r\nArial Narrow\r\nBook Antiqua\r\nCentury Gothic\r\nComic Sans MS\r\nCourier New\r\nFixedsys\r\nFranklin Gothic Medium\r\nGaramond\r\nGeorgia\r\nImpact\r\nLucida Console\r\nLucida Sans Unicode\r\nMicrosoft Sans Serif\r\nPalatino Linotype\r\nSystem\r\nTahoma\r\nTimes New Roman\r\nTrebuchet MS\r\nVerdana', 'Arial\r\nArial Black\r\nArial Narrow\r\nBook Antiqua\r\nCentury Gothic\r\nComic Sans MS\r\nCourier New\r\nFixedsys\r\nFranklin Gothic Medium\r\nGaramond\r\nGeorgia\r\nImpact\r\nLucida Console\r\nLucida Sans Unicode\r\nMicrosoft Sans Serif\r\nPalatino Linotype\r\nSystem\r\nTahoma\r\nTimes New Roman\r\nTrebuchet MS\r\nVerdana', 'template', 1061903840, 'vBulletin Solutions', '', 'vbulletin'),
