(136, -1, 'editor_smiliebox', '\".(($show[\'smiliebox\']) ? (\"\r\n<fieldset id=\\\"{$editorid}_smiliebox\\\" title=\\\"$vbphrase[smilies]\\\">\r\n	<legend>$vbphrase[smilies]</legend>\r\n	<table cellpadding=\\\"4\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" align=\\\"center\\\">\r\n	$smiliebits\r\n	\".(($show[\'moresmilieslink\']) ? (\"\r\n	<tr>\r\n		<td class=\\\"smallfont\\\" colspan=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'smcolumns\'] . \"\\\">[<a href=\\\"#\\\" onclick=\\\"vB_Editor[\'$editorid\'].open_smilie_window(smiliewindow_x, smiliewindow_y); return false\\\" title=\\\"\" . construct_phrase(\"$vbphrase[showing_x_smilies_of_y_total]\", \"\" . $GLOBALS[\'vbulletin\']->options[\'smtotal\'] . \"\", \"$totalsmilies\") . \"\\\">$vbphrase[more]</a>]</td>\r\n	</tr>\r\n	\") : (\"\")).\"\r\n	</table>\r\n</fieldset>\r\n\") : (\"\r\n<div id=\\\"smiliebox\\\" style=\\\"display:none\\\"></div>\r\n\")).\"', '<if condition=\"$show[\'smiliebox\']\">\r\n<fieldset id=\"{$editorid}_smiliebox\" title=\"$vbphrase[smilies]\">\r\n	<legend>$vbphrase[smilies]</legend>\r\n	<table cellpadding=\"4\" cellspacing=\"0\" border=\"0\" align=\"center\">\r\n	$smiliebits\r\n	<if condition=\"$show[\'moresmilieslink\']\">\r\n	<tr>\r\n		<td class=\"smallfont\" colspan=\"$vboptions[smcolumns]\">[<a href=\"#\" onclick=\"vB_Editor[\'$editorid\'].open_smilie_window(smiliewindow_x, smiliewindow_y); return false\" title=\"<phrase 1=\"$vboptions[smtotal]\" 2=\"$totalsmilies\">$vbphrase[showing_x_smilies_of_y_total]</phrase>\">$vbphrase[more]</a>]</td>\r\n	</tr>\r\n	</if>\r\n	</table>\r\n</fieldset>\r\n<else />\r\n<div id=\"smiliebox\" style=\"display:none\"></div>\r\n</if>', 'template', 1118866966, 'vBulletin Solutions', '3.5.0 Beta 2', 'vbulletin'),
(137, -1, 'editor_smiliebox_category', '<!--<tr>\r\n	<td class=\\\"smallfont\\\" colspan=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'smcolumns\'] . \"\\\" nowrap=\\\"nowrap\\\">$category</td>\r\n</tr>-->\r\n', '<!--<tr>\r\n	<td class=\"smallfont\" colspan=\"$vboptions[smcolumns]\" nowrap=\"nowrap\">$category</td>\r\n</tr>-->\r\n', 'template', 1067447256, 'vBulletin Solutions', '', 'vbulletin'),
(138, -1, 'editor_smiliebox_row', '<tr align=\\\"center\\\" valign=\\\"bottom\\\">\r\n$smiliecells\r\n</tr>\r\n', '<tr align=\"center\" valign=\"bottom\">\r\n$smiliecells\r\n</tr>\r\n', 'template', 1067444208, 'vBulletin Solutions', '', 'vbulletin'),
