(150, -1, 'FAQ', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $vbphrase[faq]\".(($show[\'faqtitle\']) ? (\": $faqtitle\") : (\"\")).\"</title>\r\n</head>\r\n<body>\r\n$header\r\n\r\n$navbar\r\n\r\n<form action=\\\"faq.php\\\" method=\\\"get\\\">\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"search\\\" />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<thead>\r\n	<tr>\r\n		<td class=\\\"tcat\\\">\r\n			<a style=\\\"float:$stylevar[right]\\\" href=\\\"#top\\\" onclick=\\\"return toggle_collapse(\'searchfaq\')\\\"><img id=\\\"collapseimg_searchfaq\\\" src=\\\"$stylevar[imgdir_button]/collapse_tcat$vbcollapse[collapseimg_searchfaq].gif\\\" alt=\\\"$vbphrase[search_faq]\\\" border=\\\"0\\\" /></a>\r\n			$vbphrase[search_faq]\r\n		</td>\r\n	</tr>\r\n</thead>\r\n<tbody id=\\\"collapseobj_searchfaq\\\" style=\\\"$vbcollapse[collapseobj_searchfaq]\\\">\r\n	<tr>\r\n		<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n		<div class=\\\"panel\\\">\r\n			<div style=\\\"width:$stylevar[formwidth]\\\">\r\n\r\n				<table class=\\\"fieldset\\\" cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n				<tr align=\\\"$stylevar[left]\\\">\r\n					<td>\r\n						$vbphrase[search_words]:<br />\r\n						<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"q\\\" value=\\\"$q\\\" size=\\\"25\\\" />\r\n					</td>\r\n					<td>\r\n						$vbphrase[matching_options]:<br />\r\n						<select name=\\\"match\\\">\r\n							<option value=\\\"any\\\" $matchselect[any]>$vbphrase[match_any_words]</option>\r\n							<option value=\\\"all\\\" $matchselect[all]>$vbphrase[match_all_words]</option>\r\n							<option value=\\\"phr\\\" $matchselect[phr]>$vbphrase[match_complete_phrase]</option>\r\n						</select>\r\n					</td>\r\n					<td>\r\n						$vbphrase[search_in]:<br />\r\n						<select name=\\\"titlesonly\\\">\r\n							<option value=\\\"1\\\" $titleselect[1]>$vbphrase[search_titles_only]</option>\r\n							<option value=\\\"0\\\" $titleselect[0]>$vbphrase[search_titles_and_text]</option>\r\n						</select>\r\n					</td>\r\n				</tr>\r\n				</table>\r\n\r\n			</div>\r\n		</div>\r\n\r\n		<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n			<input type=\\\"submit\\\" value=\\\"$vbphrase[search_faq]\\\" class=\\\"button\\\" accesskey=\\\"s\\\" />\r\n			<input type=\\\"reset\\\" value=\\\"$vbphrase[reset_fields]\\\" class=\\\"button\\\" accesskey=\\\"r\\\" />\r\n		</div>\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n</table>\r\n\r\n</form>\r\n\r\n<br />\r\n\r\n$faqbits\r\n\r\n$footer\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n<title>$vboptions[bbtitle] - $vbphrase[faq]<if condition=\"$show[\'faqtitle\']\">: $faqtitle</if></title>\r\n</head>\r\n<body>\r\n$header\r\n\r\n$navbar\r\n\r\n<form action=\"faq.php\" method=\"get\">\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"do\" value=\"search\" />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<thead>\r\n	<tr>\r\n		<td class=\"tcat\">\r\n			<a style=\"float:$stylevar[right]\" href=\"#top\" onclick=\"return toggle_collapse(\'searchfaq\')\"><img id=\"collapseimg_searchfaq\" src=\"$stylevar[imgdir_button]/collapse_tcat$vbcollapse[collapseimg_searchfaq].gif\" alt=\"$vbphrase[search_faq]\" border=\"0\" /></a>\r\n			$vbphrase[search_faq]\r\n		</td>\r\n	</tr>\r\n</thead>\r\n<tbody id=\"collapseobj_searchfaq\" style=\"$vbcollapse[collapseobj_searchfaq]\">\r\n	<tr>\r\n		<td class=\"panelsurround\" align=\"center\">\r\n		<div class=\"panel\">\r\n			<div style=\"width:$stylevar[formwidth]\">\r\n\r\n				<table class=\"fieldset\" cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n				<tr align=\"$stylevar[left]\">\r\n					<td>\r\n						$vbphrase[search_words]:<br />\r\n						<input type=\"text\" class=\"bginput\" name=\"q\" value=\"$q\" size=\"25\" />\r\n					</td>\r\n					<td>\r\n						$vbphrase[matching_options]:<br />\r\n						<select name=\"match\">\r\n							<option value=\"any\" $matchselect[any]>$vbphrase[match_any_words]</option>\r\n							<option value=\"all\" $matchselect[all]>$vbphrase[match_all_words]</option>\r\n							<option value=\"phr\" $matchselect[phr]>$vbphrase[match_complete_phrase]</option>\r\n						</select>\r\n					</td>\r\n					<td>\r\n						$vbphrase[search_in]:<br />\r\n						<select name=\"titlesonly\">\r\n							<option value=\"1\" $titleselect[1]>$vbphrase[search_titles_only]</option>\r\n							<option value=\"0\" $titleselect[0]>$vbphrase[search_titles_and_text]</option>\r\n						</select>\r\n					</td>\r\n				</tr>\r\n				</table>\r\n\r\n			</div>\r\n		</div>\r\n\r\n		<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n			<input type=\"submit\" value=\"$vbphrase[search_faq]\" class=\"button\" accesskey=\"s\" />\r\n			<input type=\"reset\" value=\"$vbphrase[reset_fields]\" class=\"button\" accesskey=\"r\" />\r\n		</div>\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n</table>\r\n\r\n</form>\r\n\r\n<br />\r\n\r\n$faqbits\r\n\r\n$footer\r\n</body>\r\n</html>', 'template', 1195729840, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
(151, -1, 'faqbit', '<a name=\\\"faq_$faq[faqname]\\\"></a>\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\".(($show[\'faqsublinks\']) ? (\"<a href=\\\"faq.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"faq=$faq[faqname]\\\">$faq[title]</a>\") : (\"$faq[title]\")).\"</td>\r\n</tr>\r\n\".(($show[\'faqtext\']) ? (\"\r\n<tr>\r\n	<td class=\\\"alt1\\\">$faq[text]</td>\r\n</tr>\r\n\") : (\"\")).\"\r\n\".(($show[\'faqsublinks\']) ? (\"\r\n<tr>\r\n	<td class=\\\"alt2\\\"><ul>$faqsublinks</ul></td>\r\n</tr>\r\n\") : (\"\")).\"\r\n</table>\r\n\r\n<br />\r\n', '<a name=\"faq_$faq[faqname]\"></a>\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\"><if condition=\"$show[\'faqsublinks\']\"><a href=\"faq.php?$session[sessionurl]faq=$faq[faqname]\">$faq[title]</a><else />$faq[title]</if></td>\r\n</tr>\r\n<if condition=\"$show[\'faqtext\']\">\r\n<tr>\r\n	<td class=\"alt1\">$faq[text]</td>\r\n</tr>\r\n</if>\r\n<if condition=\"$show[\'faqsublinks\']\">\r\n<tr>\r\n	<td class=\"alt2\"><ul>$faqsublinks</ul></td>\r\n</tr>\r\n</if>\r\n</table>\r\n\r\n<br />\r\n', 'template', 1070526899, 'vBulletin Solutions', '', 'vbulletin'),
(152, -1, 'faqbit_link', '<li><a href=\\\"faq.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"faq=$faq[faqname]#faq_$subfaq[faqname]\\\">$subfaq[title]</a></li>\r\n', '<li><a href=\"faq.php?$session[sessionurl]faq=$faq[faqname]#faq_$subfaq[faqname]\">$subfaq[title]</a></li>\r\n', 'template', 1068747203, 'vBulletin Solutions', '', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(153, -1, 'FORUMDISPLAY', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n<title>$foruminfo[title_clean]\".(($pagenumber>1) ? (\" - \" . construct_phrase(\"$vbphrase[page_x]\", \"$pagenumber\") . \"\") : (\"\")).\" - \" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \"</title>\r\n\".(($show[\'inlinemod\']) ? (\"<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_inlinemod.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\") : (\"\")).\"\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n\".(($show[\'forumslist\']) ? (\"\r\n<!-- sub-forum list  -->\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\" style=\\\"border-bottom-width:0px\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\" width=\\\"100%\\\">$vbphrase[subforums]<span class=\\\"normal\\\"> : $foruminfo[title]</span></td>\r\n	\".(($show[\'forumsearch\']) ? (\"\r\n	<td class=\\\"vbmenu_control\\\" id=\\\"forumsearch.subforums\\\" nowrap=\\\"nowrap\\\"><a href=\\\"search.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"f=$foruminfo[forumid]\\\" rel=\\\"nofollow\\\">$vbphrase[search_this_forum]</a> \".(($show[\'quicksearch\']) ? (\"<script type=\\\"text/javascript\\\"> vbmenu_register(\\\"forumsearch.subforums\\\"); </script>\") : (\"\")).\"</td>\r\n	\") : (\"\")).\"\r\n</tr>\r\n</table>\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<thead>\r\n	<tr align=\\\"center\\\">\r\n	  <td class=\\\"thead\\\">&nbsp;</td>\r\n	  <td class=\\\"thead\\\" width=\\\"100%\\\" align=\\\"$stylevar[left]\\\">$vbphrase[forum]</td>\r\n	  <td class=\\\"thead\\\">$vbphrase[last_post]</td>\r\n	  <td class=\\\"thead\\\">$vbphrase[threads]</td>\r\n	  <td class=\\\"thead\\\">$vbphrase[posts]</td>\r\n	  \".(($GLOBALS[\'vbulletin\']->options[showmoderatorcolumn]) ? (\"\r\n	  <td class=\\\"thead\\\">$vbphrase[moderator]</td>\r\n	  \") : (\"\")).\"\r\n	</tr>\r\n</thead>\r\n$forumbits\r\n</table>\r\n<br />\r\n<!-- / sub-forum list  -->\r\n\") : (\"\")).\"\r\n\r\n\".(($show[\'threadslist\']) ? (\"\r\n<!-- threads list  -->\r\n\r\n<form action=\\\"inlinemod.php?forumid=$forumid\\\" method=\\\"post\\\" id=\\\"inlinemodform\\\">\r\n<input type=\\\"hidden\\\" name=\\\"url\\\" value=\\\"$url\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"forumid\\\" value=\\\"$forumid\\\" />\r\n\r\n<!-- controls above thread list -->\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\" style=\\\"margin-bottom:3px\\\">\r\n<tr valign=\\\"bottom\\\">\r\n	<td class=\\\"smallfont\\\">\".(($show[\'newthreadlink\']) ? (\"<a href=\\\"newthread.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=newthread&amp;f=$foruminfo[forumid]\\\" rel=\\\"nofollow\\\"><img src=\\\"$stylevar[imgdir_button]/newthread.gif\\\" alt=\\\"$vbphrase[post_new_thread]\\\" border=\\\"0\\\" /></a>\") : (\"&nbsp;\")).\"</td>\r\n	\".(($pagenav) ? (\"<td align=\\\"$stylevar[right]\\\">$pagenav</td>\") : (\"\")).\"\r\n</tr>\r\n</table>\r\n<!-- / controls above thread list -->\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\" style=\\\"border-bottom-width:0px\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\" width=\\\"100%\\\">$vbphrase[threads_in_forum]<span class=\\\"normal\\\"> : $foruminfo[title]</span></td>\r\n	<td class=\\\"vbmenu_control\\\" id=\\\"forumtools\\\" nowrap=\\\"nowrap\\\"><a href=\\\"$show[nojs_link]#goto_forumtools\\\" rel=\\\"nofollow\\\">$vbphrase[forum_tools]</a> <script type=\\\"text/javascript\\\"> vbmenu_register(\\\"forumtools\\\"); </script></td>\r\n	\".(($show[\'forumsearch\']) ? (\"\r\n	<td class=\\\"vbmenu_control\\\" id=\\\"forumsearch\\\" nowrap=\\\"nowrap\\\">\".(($show[\'quicksearch\']) ? (\"<a href=\\\"$show[nojs_link]#goto_forumsearch\\\" rel=\\\"nofollow\\\">$vbphrase[search_this_forum]</a> <script type=\\\"text/javascript\\\"> vbmenu_register(\\\"forumsearch\\\"); </script>\") : (\"<a href=\\\"search.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"f=$foruminfo[forumid]\\\" rel=\\\"nofollow\\\">$vbphrase[search_this_forum]</a>\")).\"</td>\r\n	\") : (\"\")).\"\r\n</tr>\r\n</table>\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\" id=\\\"threadslist\\\">\r\n<tbody>\r\n$announcebits\r\n<tr>\r\n\".(($show[\'search_engine\']) ? (\"\r\n	\".(($show[\'threadicons\']) ? (\"\r\n		<td class=\\\"thead\\\" colspan=\\\"2\\\">&nbsp;</td>\r\n	\") : (\"\r\n		<td class=\\\"thead\\\">&nbsp;</td>\r\n	\")).\"\r\n	<td class=\\\"thead\\\" width=\\\"100%\\\">\r\n		\".(($show[\'threadratings\']) ? (\"<span style=\\\"float:$stylevar[right]\\\">$vbphrase[rating]</span>\") : (\"\")).\"\r\n		$vbphrase[thread] / $vbphrase[thread_starter]\r\n	</td>\r\n	<td class=\\\"thead\\\" width=\\\"150\\\" align=\\\"center\\\" nowrap=\\\"nowrap\\\"><span style=\\\"white-space:nowrap\\\">$vbphrase[last_post]</span></td>\r\n	<td class=\\\"thead\\\" align=\\\"center\\\" nowrap=\\\"nowrap\\\"><span style=\\\"white-space:nowrap\\\">$vbphrase[replies]</span></td>\r\n	<td class=\\\"thead\\\" align=\\\"center\\\" nowrap=\\\"nowrap\\\"><span style=\\\"white-space:nowrap\\\">$vbphrase[views]</span></td>\r\n\") : (\"\r\n	\".(($show[\'threadicons\']) ? (\"\r\n		<td class=\\\"thead\\\" colspan=\\\"2\\\">&nbsp;</td>\r\n	\") : (\"\r\n		<td class=\\\"thead\\\">&nbsp;</td>\r\n	\")).\"\r\n	<td class=\\\"thead\\\" width=\\\"100%\\\">\r\n		\".(($show[\'threadratings\']) ? (\"<span style=\\\"float:$stylevar[right]\\\"><a href=\\\"$sorturl&amp;order=desc&amp;sort=voteavg\\\" rel=\\\"nofollow\\\">$vbphrase[rating]</a> $sortarrow[voteavg]</span>\") : (\"\")).\"\r\n		<a href=\\\"$sorturl&amp;order=asc&amp;sort=title\\\" rel=\\\"nofollow\\\">$vbphrase[thread]</a> $sortarrow[title] /\r\n		<a href=\\\"$sorturl&amp;order=asc&amp;sort=postusername\\\" rel=\\\"nofollow\\\">$vbphrase[thread_starter]</a> $sortarrow[postusername]\r\n	</td>\r\n	<td class=\\\"thead\\\" width=\\\"150\\\" align=\\\"center\\\" nowrap=\\\"nowrap\\\"><span style=\\\"white-space:nowrap\\\"><a href=\\\"$sorturl&amp;order=desc&amp;sort=lastpost\\\" rel=\\\"nofollow\\\">$vbphrase[last_post]</a> $sortarrow[lastpost]</span></td>\r\n	<td class=\\\"thead\\\" align=\\\"center\\\" nowrap=\\\"nowrap\\\"><span style=\\\"white-space:nowrap\\\"><a href=\\\"$sorturl&amp;order=desc&amp;sort=replycount\\\" rel=\\\"nofollow\\\">$vbphrase[replies]</a> $sortarrow[replycount]</span></td>\r\n	<td class=\\\"thead\\\" align=\\\"center\\\" nowrap=\\\"nowrap\\\"><span style=\\\"white-space:nowrap\\\"><a href=\\\"$sorturl&amp;order=desc&amp;sort=views\\\" rel=\\\"nofollow\\\">$vbphrase[views]</a> $sortarrow[views]</span></td>\r\n\r\n	\".(($show[\'inlinemod\']) ? (\"\r\n		\".(($show[\'popups\']) ? (\"\r\n			<td class=\\\"vbmenu_control\\\" id=\\\"imod\\\" align=\\\"center\\\" title=\\\"$vbphrase[moderation]\\\"> <script type=\\\"text/javascript\\\"> vbmenu_register(\'imod\'); </script> </td>\r\n		\") : (\"\r\n			<td class=\\\"thead\\\" align=\\\"center\\\">\r\n				<input type=\\\"checkbox\\\" name=\\\"allbox\\\" id=\\\"checkall_all\\\" title=\\\"$vbphrase[check_uncheck_all]\\\" onclick=\\\"inlineMod.check_all()\\\" />\r\n			</td>\r\n		\")).\"\r\n	\") : (\"\")).\"\r\n\"