\r\n				$vbphrase[members]: $numbermembers\".(($show[\'activemembers\']) ? (\",\r\n					<span title=\\\"\" . construct_phrase(\"$vbphrase[within_the_last_x_days]\", \"\" . $GLOBALS[\'vbulletin\']->options[\'activememberdays\'] . \"\") . \"\\\">$vbphrase[active_members]: $activemembers</span>\r\n				\") : (\"\")).\"\r\n			</div>\r\n			<div>\" . construct_phrase(\"$vbphrase[welcome_to_our_newest_member_x]\", \"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$newuserid\", \"$newusername\") . \"</div>\r\n			$template_hook[forumhome_wgo_stats]\r\n		</div>\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n$template_hook[forumhome_wgo_pos3]\r\n\".(($show[\'birthdays\']) ? (\"\r\n<!-- today\'s birthdays -->\r\n<tbody>\r\n	<tr>\r\n		<td class=\\\"thead\\\" colspan=\\\"2\\\">\r\n			<a style=\\\"float:$stylevar[right]\\\" href=\\\"#top\\\" onclick=\\\"return toggle_collapse(\'forumhome_birthdays\')\\\"><img id=\\\"collapseimg_forumhome_birthdays\\\" src=\\\"$stylevar[imgdir_button]/collapse_thead$vbcollapse[collapseimg_forumhome_birthdays].gif\\\" alt=\\\"\\\" border=\\\"0\\\" /></a>\r\n			$vbphrase[todays_birthdays]\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n<tbody id=\\\"collapseobj_forumhome_birthdays\\\" style=\\\"$vbcollapse[collapseobj_forumhome_birthdays]\\\">\r\n	<tr>\r\n		<td class=\\\"alt2\\\"><a href=\\\"calendar.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=getday&amp;day=$today&amp;sb=1\\\"><img src=\\\"$stylevar[imgdir_misc]/birthday.gif\\\" alt=\\\"$vbphrase[view_birthdays]\\\" border=\\\"0\\\" /></a></td>\r\n		<td class=\\\"alt1\\\" width=\\\"100%\\\"><div class=\\\"smallfont\\\">$birthdays</div></td>\r\n	</tr>\r\n</tbody>\r\n<!-- end today\'s birthdays -->\r\n\") : (\"\")).\"\r\n$template_hook[forumhome_wgo_pos4]\r\n\".(($show[\'upcomingevents\']) ? (\"\r\n<tbody>\r\n	<tr>\r\n		<td class=\\\"thead\\\" colspan=\\\"2\\\">\r\n			<a style=\\\"float:$stylevar[right]\\\" href=\\\"#top\\\" onclick=\\\"return toggle_collapse(\'forumhom