(172, -1, 'help_avatars', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $vbphrase[avatar_list]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[avatars]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"alt1\\\">\r\n		$vbphrase[avatars_small_images]\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />\r\n\r\n\".(($show[\'pagenav\']) ? (\"\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\" style=\\\"margin-bottom:3px\\\">\r\n<tr valign=\\\"bottom\\\">\r\n	<td align=\\\"$stylevar[right]\\\">$pagenav</td>\r\n</tr>\r\n</table>\r\n\") : (\"\")).\"\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\" colspan=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'numavatarswide\'] . \"\\\">\r\n		\".(($totalavatars) ? (\"<span style=\\\"float:$stylevar[right]\\\">\" . construct_phrase(\"$vbphrase[showing_avatars_x_to_y_of_z]\", \"$first\", \"$last\", \"$totalavatars\") . \"</span>\") : (\"\")).\"\r\n		$vbphrase[avatar_list]\r\n	</td>\r\n</tr>\r\n\".(( $avatarbits != \'\' ) ? (\"\r\n$avatarbits\r\n\") : (\"\r\n<tr>\r\n	<td class=\\\"alt1\\\" align=\\\"center\\\" colspan=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'numavatarswide\'] . \"\\\">$vbphrase[no_predefined_avatars_available]</td>\r\n</tr>\r\n\")).\"\r\n</table>\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n<title>$vboptions[bbtitle] - $vbphrase[avatar_list]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">$vbphrase[avatars]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"alt1\">\r\n		$vbphrase[avatars_small_images]\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />\r\n\r\n<if condition=\"$show[\'pagenav\']\">\r\n<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"margin-bottom:3px\">\r\n<tr valign=\"bottom\">\r\n	<td align=\"$stylevar[right]\">$pagenav</td>\r\n</tr>\r\n</table>\r\n</if>\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\" colspan=\"$vboptions[numavatarswide]\">\r\n		<if condition=\"$totalavatars\"><span style=\"float:$stylevar[right]\"><phrase 1=\"$first\" 2=\"$last\" 3=\"$totalavatars\">$vbphrase[showing_avatars_x_to_y_of_z]</phrase></span></if>\r\n		$vbphrase[avatar_list]\r\n	</td>\r\n</tr>\r\n<if condition=\" $avatarbits != \'\' \">\r\n$avatarbits\r\n<else />\r\n<tr>\r\n	<td class=\"alt1\" align=\"center\" colspan=\"$vboptions[numavatarswide]\">$vbphrase[no_predefined_avatars_available]</td>\r\n</tr>\r\n</if>\r\n</table>\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', 'template', 1195729859, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
(173, -1, 'help_avatars_avatar', '	<td class=\\\"$bgclass\\\"><span class=\\\"smallfont\\\"><img src=\\\"$avatar[avatarpath]\\\" alt=\\\"$avatar[title]\\\" border=\\\"0\\\" /><br />$avatar[title]</span></td>', '	<td class=\"$bgclass\"><span class=\"smallfont\"><img src=\"$avatar[avatarpath]\" alt=\"$avatar[title]\" border=\"0\" /><br />$avatar[title]</span></td>', 'template', 1069239567, 'vBulletin Solutions', '', 'vbulletin'),
(174, -1, 'help_avatars_category', '<tr>\r\n	<td class=\\\"thead\\\" colspan=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'numavatarswide\'] . \"\\\">\" . construct_phrase(\"$vbphrase[x_requiring_at_least_y_posts]\", \"$avatar[category]\", \"$avatar[minimumposts]\") . \"</td>\r\n</tr>\r\n', '<tr>\r\n	<td class=\"thead\" colspan=\"$vboptions[numavatarswide]\"><phrase 1=\"$avatar[category]\" 2=\"$avatar[minimumposts]\">$vbphrase[x_requiring_at_least_y_posts]</phrase></td>\r\n</tr>\r\n', 'template', 1070053618, 'vBulletin Solutions', '', 'vbulletin'),
(175, -1, 'help_avatars_row', '<tr align=\\\"center\\\" valign=\\\"bottom\\\">\r\n$avatarcells\r\n\".(($remainingcolumns > 0) ? (\"\r\n	<td colspan=\\\"$remainingcolumns\\\">&nbsp;</td>\r\n\") : (\"\")).\"\r\n</tr>', '<tr align=\"center\" valign=\"bottom\">\r\n$avatarcells\r\n<if condition=\"$remainingcolumns > 0\">\r\n	<td colspan=\"$remainingcolumns\">&nbsp;</td>\r\n</if>\r\n</tr>', 'template', 1149698778, 'vBulletin Solutions', '3.6.0 Beta 1', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(176, -1, 'help_bbcodes', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $vbphrase[bbcode_list]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\" colspan=\\\"2\\\">$vbphrase[bb_code]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"alt1\\\" colspan=\\\"2\\\">\r\n		$vbphrase[bb_code_based_on_html]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"thead\\\" colspan=\\\"2\\\">$vbphrase[bbcode_list]</td>\r\n</tr>\r\n\".(($show[\'bbcodebasic\']) ? (\"\r\n	<tr align=\\\"center\\\">\r\n		<td class=\\\"alt2\\\"><a href=\\\"#basic\\\">[b]</a>, <a href=\\\"#basic\\\">[i]</a>, <a href=\\\"#basic\\\">[u]</a></td>\r\n		<td class=\\\"alt1\\\">$vbphrase[bold] / $vbphrase[italic] / $vbphrase[underline]</td>\r\n	</tr>\r\n\") : (\"\")).\"\r\n\".(($show[\'bbcodecolor\']) ? (\"\r\n	<tr align=\\\"center\\\">\r\n		<td class=\\\"alt2\\\"><a href=\\\"#color\\\">[color]</a></td>\r\n		<td class=\\\"alt1\\\">$vbphrase[color]</td>\r\n	</tr>\r\n\") : (\"\")).\"\r\n\".(($show[\'bbcodesize\']) ? (\"\r\n	<tr align=\\\"center\\\">\r\n		<td class=\\\"alt2\\\"><a href=\\\"#size\\\">[size]</a></td>\r\n		<td class=\\\"alt1\\\">$vbphrase[size]</td>\r\n	</tr>\r\n\") : (\"\")).\"\r\n\".(($show[\'bbcodefont\']) ? (\"\r\n	<tr align=\\\"center\\\">\r\n		<td class=\\\"alt2\\\"><a href=\\\"#font\\\">[font]</a></td>\r\n		<td class=\\\"alt1\\\">$vbphrase[font]</td>\r\n	</tr>\r\n\") : (\"\")).\"\r\n<tr align=\\\"center\\\">\r\n	<td class=\\\"alt2\\\"><a href=\\\"#highlight\\\">[highlight]</a></td>\r\n	<td class=\\\"alt1\\\">$vbphrase[highlight]</td>\r\n</tr>\r\n\".(($show[\'bbcodealign\']) ? (\"\r\n	<tr align=\\\"center\\\">\r\n		<td class=\\\"alt2\\\"><a href=\\\"#align\\\">[left]</a>, <a href=\\\"#align\\\">[right]</a>, <a href=\\\"#align\\\">[center]</a></td>\r\n		<td class=\\\"alt1\\\">$vbphrase[left] / $vbphrase[right] / $vbphrase[center]</td>\r\n	</tr>\r\n	<tr align=\\\"center\\\">\r\n		<td class=\\\"alt2\\\"><a href=\\\"#indent\\\">[indent]</a></td>\r\n		<td class=\\\"alt1\\\">$vbphrase[indent]</td>\r\n	</tr>\r\n\") : (\"\")).\"\r\n\".(($show[\'bbcodeurl\']) ? (\"\r\n	<tr align=\\\"center\\\">\r\n		<td class=\\\"alt2\\\"><a href=\\\"#email\\\">[email]</a></td>\r\n		<td class=\\\"alt1\\\">$vbphrase[email_linking]</td>\r\n	</tr>\r\n	<tr align=\\\"center\\\">\r\n		<td class=\\\"alt2\\\"><a href=\\\"#url\\\">[url]</a></td>\r\n		<td class=\\\"alt1\\\">$vbphrase[url_hyperlinking]</td>\r\n	</tr>\r\n	<tr align=\\\"center\\\">\r\n		<td class=\\\"alt2\\\"><a href=\\\"#thread\\\">[thread]</a></td>\r\n		<td class=\\\"alt1\\\">$vbphrase[thread_linking]</td>\r\n	</tr>\r\n	<tr align=\\\"center\\\">\r\n		<td class=\\\"alt2\\\"><a href=\\\"#post\\\">[post]</a></td>\r\n		<td class=\\\"alt1\\\">$vbphrase[post_linking]</td>\r\n	</tr>\r\n\") : (\"\")).\"\r\n\".(($show[\'bbcodelist\']) ? (\"\r\n	<tr align=\\\"center\\\">\r\n		<td class=\\\"alt2\\\"><a href=\\\"#list\\\">[list]</a></td>\r\n		<td class=\\\"alt1\\\">$vbphrase[bulleted_lists] / $vbphrase[advanced_lists]</td>\r\n	</tr>\r\n\") : (\"\")).\"\r\n<tr align=\\\"center\\\">\r\n	<td class=\\\"alt2\\\"><a href=\\\"#imgcode\\\">[img]</a></td>\r\n	<td class=\\\"alt1\\\">$vbphrase[images]</td>\r\n</tr>\r\n\".(($show[\'bbcodecode\']) ? (\"\r\n	<tr align=\\\"center\\\">\r\n		<td class=\\\"alt2\\\"><a href=\\\"#code\\\">[code]</a></td>\r\n		<td class=\\\"alt1\\\">$vbphrase[code]</td>\r\n	</tr>\r\n\") : (\"\")).\"\r\n\".(($show[\'bbcodephp\']) ? (\"\r\n	<tr align=\\\"center\\\">\r\n		<td class=\\\"alt2\\\"><a href=\\\"#php\\\">[php]</a></td>\r\n		<td class=\\\"alt1\\\">$vbphrase[php_code]</td>\r\n	</tr>\r\n\") : (\"\")).\"\r\n\".(($show[\'bbcodehtml\']) ? (\"\r\n	<tr align=\\\"center\\\">\r\n		<td class=\\\"alt2\\\"><a href=\\\"#html\\\">[html]</a></td>\r\n		<td class=\\\"alt1\\\">$vbphrase[html_code]</td>\r\n	</tr>\r\n\") : (\"\")).\"\r\n<tr align=\\\"center\\\">\r\n	<td class=\\\"alt2\\\"><a href=\\\"#quote\\\">[quote]</a></td>\r\n	<td class=\\\"alt1\\\">$vbphrase[quote]</td>\r\n</tr>\r\n<tr align=\\\"center\\\">\r\n	<td class=\\\"alt2\\\"><a href=\\\"#noparse\\\">[noparse]</a></td>\r\n	<td class=\\\"alt1\\\">$vbphrase[stop_bbcode_parsing]</td>\r\n</tr>\r\n<tr align=\\\"center\\\">\r\n	<td class=\\\"alt2\\\"><a href=\\\"#attach\\\">[attach]</a></td>\r\n	<td class=\\\"alt1\\\">$vbphrase[attachment]</td>\r\n</tr>\r\n\".(($show[\'bbcodesigpic\']) ? (\"\r\n	<tr align=\\\"center\\\">\r\n		<td class=\\\"alt2\\\"><a href=\\\"#sigpic\\\">[sigpic]</a></td>\r\n		<td class=\\\"alt1\\\">$vbphrase[signature_picture]</td>\r\n	</tr>\r\n\") : (\"\")).\"\r\n$template[bbcodelinks]\r\n<tr>\r\n	<td class=\\\"alt1\\\" colspan=\\\"2\\\">\r\n		$vbphrase[incorrect_bb_code_usage]\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />\r\n\r\n<!-- BEGIN vB CODE LIST -->\r\n\r\n<!-- Begin Allow Basic BBcode Conditional -->\r\n\".(($show[\'bbcodebasic\']) ? (\"\r\n\r\n	<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n	<tr>\r\n		<td class=\\\"tcat\\\" colspan=\\\"2\\\">$vbphrase[bold] / $vbphrase[italic] / $vbphrase[underline]<a name=\\\"basic\\\"></a></td>\r\n	</tr>\r\n	<tr>\r\n		<td class=\\\"thead\\\" colspan=\\\"2\\\" style=\\\"font-weight:normal\\\">$vbphrase[b_i_and_u_tags_allow]</td>\r\n	</tr>\r\n	<tr valign=\\\"top\\\">\r\n		<td class=\\\"alt1\\\" width=\\\"20%\\\"><strong>$vbphrase[usage]</strong></td>\r\n		<td class=\\\"alt1\\\">\r\n			[b]<span class=\\\"highlight\\\">$vbphrase[value]</span>[/b]<br />\r\n			[i]<span class=\\\"highlight\\\">$vbphrase[value]</span>[/i]<br />\r\n			[u]<span class=\\\"highlight\\\">$vbphrase[value]</span>[/u]\r\n		</td>\r\n	</tr>\r\n	<tr valign=\\\"top\\\">\r\n		<td class=\\\"alt2\\\" width=\\\"20%\\\"><strong>$vbphrase[example_usage]</strong></td>\r\n		<td class=\\\"alt2\\\">\r\n			[b]$vbphrase[this_text_is_bold][/b]<br />\r\n			[i]$vbphrase[this_text_is_italic][/i]<br />\r\n			[u]$vbphrase[this_text_is_underlined][/u]\r\n		</td>\r\n	</tr>\r\n	<tr valign=\\\"top\\\">\r\n		<td class=\\\"alt1\\\" width=\\\"20%\\\"><strong>$vbphrase[example_output]</strong></td>\r\n		<td class=\\\"alt1\\\">\r\n			<b>$vbphrase[this_text_is_bold]</b><br />\r\n			<i>$vbphrase[this_text_is_italic]</i><br />\r\n			<u>$vbphrase[this_text_is_underlined]</u>\r\n		</td>\r\n	</tr>\r\n	</table>\r\n	<br />\r\n\r\n\") : (\"\")).\"\r\n<!-- End Allow Basic BBcode Conditional -->\r\n\r\n\".(($show[\'bbcodecolor\']) ? (\"\r\n\r\n	<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n	<tr>\r\n		<td class=\\\"tcat\\\" colspan=\\\"2\\\">$vbphrase[color]<a name=\\\"color\\\"></a></td>\r\n	</tr>\r\n	<tr>\r\n		<td class=\\\"thead\\\" colspan=\\\"2\\\" style=\\\"font-weight:normal\\\">$vbphrase[color_tag_allows]</td>\r\n	</tr>\r\n	<tr valign=\\\"top\\\">\r\n		<td class=\\\"alt1\\\" width=\\\"20%\\\"><strong>$vbphrase[usage]</strong></td>\r\n		<td class=\\\"alt1\\\">[color=<span class=\\\"highlight\\\">$vbphrase[option]</span>]<span class=\\\"highlight\\\">$vbphrase[value]</span>[/color]</td>\r\n	</tr>\r\n	<tr valign=\\\"top\\\">\r\n		<td class=\\\"alt2\\\" width=\\\"20%\\\"><strong>$vbphrase[example_usage]</strong></td>\r\n		<td class=\\\"alt2\\\">[color=blue]$vbphrase[this_text_is_blue][/color]</td>\r\n	</tr>\r\n	<tr valign=\\\"top\\\">\r\n		<td class=\\\"alt1\\\" width=\\\"20%\\\"><strong>$vbphrase[example_output]</strong></td>\r\n		<td class=\\\"alt1\\\"><font color=\\\"blue\\\">$vbphrase[this_text_is_blue]</font></td>\r\n	</tr>\r\n	</table>\r\n	<br />\r\n\r\n\") :