(196, -1, 'im_yahoo', '<a href=\\\"#\\\" onclick=\\\"imwindow(\'yahoo\', \'$userinfo[userid]\', 400, 200); return false;\\\"><img src=\\\"$stylevar[imgdir_misc]/im_yahoo.gif\\\" alt=\\\"\" . construct_phrase(\"$vbphrase[send_message_via_yahoo_to_x]\", \"$userinfo[username]\") . \"\\\" border=\\\"0\\\" /></a>', '<a href=\"#\" onclick=\"imwindow(\'yahoo\', \'$userinfo[userid]\', 400, 200); return false;\"><img src=\"$stylevar[imgdir_misc]/im_yahoo.gif\" alt=\"<phrase 1=\"$userinfo[username]\">$vbphrase[send_message_via_yahoo_to_x]</phrase>\" border=\"0\" /></a>', 'template', 1119876714, 'vBulletin Solutions', '3.5.0 Beta 3', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(197, -1, 'MEMBERINFO', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n\r\n$usercss\r\n$memberinfo_css\r\n<style type=\\\"text/css\\\" id=\\\"vbulletin_tabctrl_css\\\">\r\n@import url(\\\"clientscript/vbulletin_tabctrl.css?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\");\r\n\".(($show[\'rtl\']) ? (\"@import url(\\\"clientscript/vbulletin_tabctrl_rtl.css?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\");\") : (\"\")).\"\r\n</style>\r\n\r\n<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_tabctrl.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_quick_edit_generic.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_quick_edit_visitormessage.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $vbphrase[view_profile]: $userinfo[username]</title>\r\n\r\n\".(($userinfo[\'userid\'] == $GLOBALS[\'vbulletin\']->userinfo[\'userid\']) ? (\"\r\n<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_profilefield_edit.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n\") : (\"\")).\"\r\n<script type=\\\"text/javascript\\\">\r\n<!--\r\nvbphrase[\'server_failed_respond_try_again\'] = \\\"$vbphrase[server_failed_respond_try_again]\\\";\r\nvbphrase[\'edit_value\'] = \\\"$vbphrase[edit_value_js]\\\";\r\n\r\n\".(($show[\'post_visitor_message\']) ? (\"\r\nfunction goto_post_pm()\r\n{\r\n	vB_TabCtrls[\'profile_tabs\'].switch_tab(\'visitor_messaging\');\r\n	fetch_object(\'visitor_messaging\').scrollIntoView();\r\n\r\n	var textarea = fetch_object(\'visitor_message_form_textarea\');\r\n	if (textarea)\r\n	{\r\n		textarea.focus();\r\n		textarea.select();\r\n	}\r\n	return false;\r\n}\r\n\") : (\"\")).\"\r\n-->\r\n</script>\r\n\r\n</head>\r\n<body>\r\n\r\n$header\r\n$navbar\r\n\r\n\r\n<!-- begin user css -->\r\n<div id=\\\"usercss\\\" class=\\\"floatcontainer\\\">\r\n\r\n<div id=\\\"content_container\\\">\r\n	<div id=\\\"content\\\">\r\n\r\n		<div id=\\\"main_userinfo\\\" class=\\\"floatcontainer\\\">\r\n			<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n			<tr>\r\n				\".(($blocks[\'profile_picture\']) ? (\"\r\n					<td id=\\\"profilepic_cell\\\" class=\\\"tborder alt2\\\">$blocks[profile_picture]</td>\r\n				\") : (\"\")).\"\r\n				<td valign=\\\"top\\\" width=\\\"100%\\\" id=\\\"username_box\\\"\".(($prepared[\'profilepicurl\']) ? (\" class=\\\"profilepic_adjacent\\\"\") : (\"\")).\">\r\n					\".(($prepared[\'rank\'] OR $prepared[\'reputationdisplay\']) ? (\"\r\n						<div id=\\\"reputation_rank\\\">\r\n							\".(($prepared[\'reputationdisplay\']) ? (\"\r\n								<div id=\\\"reputation\\\">$prepared[reputationdisplay]</div>\r\n							\") : (\"\")).\"\r\n							\".(($prepared[\'rank\']) ? (\"\r\n								<div id=\\\"rank\\\">$prepared[rank]</div>\r\n							\") : (\"\")).\"\r\n						</div>\r\n					\") : (\"\")).\"\r\n					<h1>$prepared[musername] $prepared[onlinestatus]</h1>\r\n					\".(($prepared[\'usertitle\']) ? (\"\r\n						<h2>$prepared[usertitle]</h2>\r\n					\") : (\"\")).\"\r\n				</td>\r\n			</tr>\r\n			</table>\r\n\r\n			<!-- link bar -->\r\n			<div class=\\\"tborder content_block\\\" id=\\\"link_bar\\\">\r\n			\".(($prepared[\'myprofile\'] OR $show[\'usercss_switch\'] OR $show[\'contactlinks\'] OR $show[\'userlists\'] OR $show[\'usernotes\'] OR $show[\'edit_profile\']) ? (\"\r\n				<ul class=\\\"thead block_row block_title list_no_decoration floatcontainer\\\">\r\n					\".(($prepared[\'myprofile\']) ? (\"\r\n						\".(($show[\'can_customize_profile\']) ? (\"\r\n							<li class=\\\"thead\\\" id=\\\"usercss_switch_link\\\"><a href=\\\"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=customize\\\">$vbphrase[customize_profile]</a></li>\r\n						\") : (\"\")).\"\r\n					\") : (\"\r\n						\".(($show[\'usercss_switch\']) ? (\"\r\n							<li class=\\\"thead\\\" id=\\\"usercss_switch_link\\\"><a href=\\\"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=switchusercss&amp;hash=\" . $GLOBALS[\'vbulletin\']->userinfo[\'logouthash\'] . \"&amp;u=$prepared[userid]\\\">$usercss_switch_phrase</a></li>\r\n						\") : (\"\")).\"\r\n					\")).\"\r\n\r\n					\".(($show[\'contactlinks\']) ? (\"\r\n						<li class=\\\"thead\\\" id=\\\"minicontact\\\"><a href=\\\"#contactinfo\\\">$vbphrase[send_message]</a> <script type=\\\"text/javascript\\\">vBmenu.register(\\\"minicontact\\\");</script></li>\r\n					\") : (\"\")).\"\r\n\r\n					\".(($show[\'userlists\']) ? (\"\r\n						<li class=\\\"thead\\\" id=\\\"userlists\\\"><a href=\\\"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=buddylist&amp;nojs=1\\\">$vbphrase[user_lists]</a> <script type=\\\"text/javascript\\\">vBmenu.register(\\\"userlists\\\");</script></li>\r\n					\") : (\"\")).\"\r\n\r\n					\".(($show[\'usernotes\']) ? (\"\r\n						<li class=\\\"thead\\\"><a href=\\\"usernote.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$prepared[userid]\\\">$vbphrase[user_notes] ($prepared[usernotecount])</a></li>\r\n					\") : (\"\")).\"\r\n\r\n					\".(($show[\'edit_profile\']) ? (\"\r\n						<li class=\\\"thead\\\"><a href=\\\"moderator.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=useroptions&amp;u=$userinfo[userid]\\\">$vbphrase[edit_user_profile]</a></li>\r\n					\") : (\"\")).\"\r\n\r\n				</ul>\r\n			\") : (\"\")).\"\r\n\r\n				<!-- current activity -->\r\n				\".(($prepared[\'lastactivitydate\'] OR $prepared[\'action\']) ? (\"\r\n					<div class=\\\"alt2 smallfont block_row\\\" id=\\\"activity_info\\\">\r\n						\".(($prepared[\'lastactivitydate\']) ? (\"\r\n							<div id=\\\"last_online\\\">\r\n								<span class=\\\"shade\\\">$vbphrase[last_activity]:</span> $prepared[lastactivitydate]\".((!$show[\'detailedtime\']) ? (\" <span class=\\\"time\\\">$prepared[lastactivitytime]</span>\") : (\"\")).\"\r\n							</div>\r\n						\") : (\"\")).\"\r\n						\".(($prepared[\'action\']) ? (\"\r\n							<span class=\\\"shade\\\">$vbphrase[current_activity]:</span> $prepared[action] $prepared[where]\r\n						\") : (\"\")).\"\r\n					</div>\r\n				\") : (\"\")).\"\r\n				<!-- / current activity -->\r\n\r\n			</div>\r\n			<!-- / link bar -->\r\n\r\n			<!-- user list menu -->\r\n			<ul id=\\\"userlists_menu\\\" class=\\\"vbmenu_popup list_no_decoration\\\" style=\\\"display: none\\\">\r\n				<li class=\\\"thead first\\\">\" . construct_phrase(\"$vbphrase[user_lists]\", \"$prepared[username]\") . \"</li>\r\n				\".(($prepared[\'canbefriend\']) ? (\"\r\n					<li class=\\\"vbmenu_option\\\">\r\n						<a href=\\\"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=addlist&amp;userlist=friend&amp;u=$prepared[userid]\\\">\".(($prepared[\'requestedfriend\']) ? (\"$vbphrase[confirm_friendship_request]\") : (\"$vbphrase[add_to_friends_list]\")).\"</a>\r\n					</li>\r\n				\") : (\"\")).\"\r\n				\".(($prepared[\'isfriend\']) ? (\"\r\n					<li class=\\\"vbmenu_option\\\">\r\n						<a href=\\\"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=removelist&amp;userlist=friend&amp;u=$prepared[userid]\\\">$vbphrase[remove_from_friends_list]</a>\r\n					</li>\r\n				\") : (\"\")).\"\r\n				\".(($show[\'addbuddylist\']) ? (\"\r\n					<li class=\\\"vbmenu_option\\\">\r\n						<a href=\\\"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=addlist&amp;userlist=buddy&amp;u=$prepared[userid]\\\">$vbphrase[add_to_contacts]</a>\r\n					</li>\r\n				\") : (\"\")).\"\r\n				\".(($show[\'removebuddylist\']) ? (\"\r\n					<li class=\\\"vbmenu_option\\\">\r\n						<a href=\\\"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=removelist&amp;userlist=buddy&amp;u=$prepared[userid]\\\">$vbphrase[remove_from_contacts]</a>\r\n					</li>\r\n				\") : (\"\")).\"\r\n				\".(($show[\'addignorelist\']) ? (\"\r\n					<li class=\\\"vbmenu_option\\\">\r\n						<a href=\\\"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=addlist&amp;userlist=ignore&amp;u=$prepared[userid]\\\">$vbphrase[add_to_ignore_list]</a>\r\n					</li>\r\n				\") : (\"\")).\"\r\n				\".(($show[\'removeignorelist\']) ? (\"\r\n					<li class=\\\"vbmenu_option\\\">\r\n						<a href=\\\"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=removelist&amp;userlist=ignore&amp;u=$prepared[userid]\\\">$vbphrase[remove_from_ignore_list]</a>\r\n					</li>\r\n				\") : (\"\")).\"\r\n			</ul>\r\n\r\n			\".(($show[\'contactlinks\']) ? (\"\r\n			<!-- contact popup menu -->\r\n			<ul id=\\\"minicontact_menu\\\" class=\\\"vbmenu_popup list_no_decoration\\\" style=\\\"display:none\\\">\r\n				\".(($show[\'post_visitor_message\'] OR $show[\'pm\'] OR $show[\'email\']) ? (\"\r\n					<li class=\\\"thead first\\\">\" . construct_phrase(\"$vbphrase[send_message_to_x]\", \"$prepared[username]\") . \"</li>\r\n				\") : (\"\")).\"\r\n				\".(($show[\'post_visitor_message\']) ? (\"<li class=\\\"vbmenu_option\\\"><img src=\\\"$stylevar[imgdir_button]/sendtofriend.gif\\\" alt=\\\"\\\" class=\\\"alt2 inlineimg\\\" /> <a href=\\\"visitormessage.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=message&amp;u=$prepared[userid]\\\" onclick=\\\"return goto_post_pm();\\\">\" . construct_phrase(\"$vbphrase[post_a_visitor_message_for_x]\", \"$prepared[username]\") . \"</a></li>\") : (\"\")).\"\r\n				\".(($show[\'pm\']) ? (\"\r\n					<li class=\\\"vbmenu_option\\\"><img src=\\\"$stylevar[imgdir_button]/sendtofriend.gif\\\" alt=\\\"\\\" class=\\\"alt2 inlineimg\\\" /> <a href=\\\"private.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=newpm&amp;u=$prepared[userid]\\\" rel=\\\"nofollow\\\">\" . construct_phrase(\"$vbphrase[send_private_message_to_x]\", \"$prepared[username]\") . \"</a></li>\r\n				\") : (\"\")).\"\r\n				\".(($blocks[\'contactinfo\']) ? (\"\r\n				\".(($show[\'email\']) ? (\"<li class=\\\"vbmenu_option\\\"><img src=\\\"$stylevar[imgdir_button]/sendtofriend.gif\\\" alt=\\\"\\\" class=\\\"alt2 inlineimg\\\" /> <a href=\\\"sendmessage.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=mailmember&amp;u=$prepared[userid]\\\" rel=\\\"nofollow\\\">\" . construct_phrase(\"$vbphrase[send_message_via_email_to_x]\", \"$prepared[username]\") . \"</a></li>\") : (\"\")).\"\r\n				\".(($prepared[\'hasimdetails\']) ? (\"\r\n					<li class=\\\"thead\".((!$show[\'post_visitor_message\'] AND !$show[\'pm\'] AND !$show[\'email\']) ? (\" first\") : (\"\")).\"\\\">$vbphrase[instant_messaging]</li>\r\n					\".(($prepared[\'icq\']) ? (\"\r\n						<li class=\\\"vbmenu_option\\\"><img class=\\\"alt2 inlineimg\\\" alt=\\\"\\\" src=\\\"$stylevar[imgdir_misc]/im_icq.gif\\\" />  <a href=\\\"#\\\" dir=\\\"ltr\\\" onclick=\\\"imwindow(\'icq\', \'$prepared[userid]\', 500, 450); return false;\\\">\" . construct_phrase(\"$vbphrase[send_icq_message_to_x]\", \"$prepared[username]\") . \"</a></li>\r\n					\") : (\"\")).\"\r\n					\".(($prepared[\'aim\']) ? (\"\r\n						<li class=\\\"vbmenu_option\\\"><img class=\\\"alt2 inlineimg\\\" alt=\\\"\\\" src=\\\"$stylevar[imgdir_misc]/im_aim.gif\\\" /> <a href=\\\"#\\\" dir=\\\"ltr\\\" onclick=\\\"imwindow(\'aim\', \'$prepared[userid]\', 400, 200); return false;\\\">\" . construct_phrase(\"$vbphrase[send_aim_message_to_x]\", \"$prepared[username]\") . \"</a></li>\r\n					\") : (\"\")).\"\r\n					\".(($prepared[\'msn\']) ? (\"\r\n						<li class=\\\"vbmenu_option\\\"><img class=\\\"alt2 inlineimg\\\" alt=\\\"\\\" src=\\\"$stylevar[imgdir_misc]/im_msn.gif\\\" /> <a href=\\\"#\\\" dir=\\\"ltr\\\" onclick=\\\"imwindow(\'msn\', \'$prepared[userid]\', 400, 200); return false;\\\">\" . construct_phrase(\"$vbphrase[send_msn_message_to_x]\", \"$prepared[username]\") . \"</a></li>\r\n					\") : (\"\")).\"\r\n					\".(($prepared[\'yahoo\']) ? (\"\r\n						<li class=\\\"vbmenu_option\\\"><img src=\\\"$stylevar[imgdir_misc]/im_yahoo.gif\\\" alt=\\\"\\\" class=\\\"alt2 inlineimg\\\" /> <a href=\\\"#\\\" dir=\\\"ltr\\\" onclick=\\\"imwindow(\'yahoo\', \'$prepared[userid]\', 400, 200); return false;\\\">\" . construct_phrase(\"$vbphrase[send_yahoo_message_to_x]\", \"$prepared[username]\") . \"</a></li>\r\n					\") : (\"\")).\"\r\n					\".(($prepared[\'skype\']) ? (\"\r\n						<li class=\\\"vbmenu_option\\\"><img src=\\\"$stylevar[imgdir_misc]/im_skype.gif\\\" alt=\\\"\\\" class=\\\"alt2 inlineimg\\\" /> <a href=\\\"#\\\" dir=\\\"ltr\\\" onclick=\\\"imwindow(\'skype\', \'$prepared[userid]\', 400, 285); return false;\\\">\" . construct_phrase(\"$vbphrase[send_skype_message_to_x]\", \"$prepared[username]\") . \"</a></li>\r\n					\") : (\"\")).\"\r\n				\") : (\"\")).\"\r\n				\") : (\"\")).\"\r\n			</ul>\r\n			<!-- / contact popup menu -->\r\n			\") : (\"\")).\"\r\n	</div>\r\n\r\n	<div id=\\\"profile_tabs\\\">\r\n		$template_hook[profile_left_first]\r\n		$blocks[visitor_messaging]\r\n		$blocks[aboutme]\r\n		$blocks[stats]\r\n		$blocks[friends]\r\n		$blocks[infractions]\r\n		$blocks[contactinfo]\r\n		$template_hook[profile_left_last]\r\n	</div>\r\n\r\n	<script type=\\\"text/javascript\\\">\r\n	<!--\r\n	vBulletin.register_control(\\\"vB_TabCtrl\\\", \\\"profile_tabs\\\", \\\"$selected_tab\\\", \\\"&raquo;\\\", \\\"profile.php?u=2&do=loadtab&tabid={1:tabid}\\\");\r\n	//-->\r\n	</script>\r\n\r\n</div>\r\n</div>\r\n\r\n<div id=\\\"sidebar_container\\\">\r\n	<!-- sidebar -->\r\n	$template_hook[profile_right_first]\r\n	$blocks[stats_mini]\r\n	$template_hook[profile_right_mini]\r\n	$blocks[friends_mini]\r\n	$blocks[albums]\r\n	$template_hook[profile_right_album]\r\n	$blocks[groups]\r\n	$blocks[visitors]\r\n	$template_hook[profile_right_last]\r\n	<!-- / sidebar -->\r\n</div>\r\n\r\n<!-- end usercss -->\r\n</div>\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n\r\n$usercss\r\n$memberinfo_css\r\n<style type=\"text/css\" id=\"vbulletin_tabctrl_css\">\r\n@import url(\"clientscript/vbulletin_tabctrl.css?v=$vboptions[simpleversion]\");\r\n<if condition=\"$show[\'rtl\']\">@import url(\"clientscript/vbulletin_tabctrl_rtl.css?v=$vboptions[simpleversion]\");</if>\r\n</style>\r\n\r\n<script type=\"text/javascript\" src=\"clientscript/vbulletin_tabctrl.js?v=$vboptions[simpleversion]\"></script>\r\n<script type=\"text/javascript\" src=\"clientscript/vbulletin_quick_edit_generic.js?v=$vboptions[simpleversion]\"></script>\r\n<script type=\"text/javascript\" src=\"clientscript/vbulletin_quick_edit_visitormessage.js?v=$vboptions[simpleversion]\"></script>\r\n\r\n<title>$vboptions[bbtitle] - $vbphrase[view_profile]: $userinfo[username]</title>\r\n\r\n<if condition=\"$userinfo[\'userid\'] == $bbuserinfo[\'userid\']\">\r\n<script type=\"text/javascript\" src=\"clientscript/vbulletin_profilefield_edit.js?v=$vboptions[simpleversion]\"></script>\r\n</if>\r\n<script type=\"text/javascript\">\r\n<!--\r\nvbphrase[\'server_failed_respond_try_again\'] = \"$vbphrase[server_failed_respond_try_again]\";\r\nvbphrase[\'edit_value\'] = \"$vbphrase[edit_value_js]\";\r\n\r\n<if condition=\"$show[\'post_visitor_message\']\">\r\nfunction goto_post_pm()\r\n{\r\n	vB_TabCtrls[\'profile_tabs\'].switch_tab(\'visitor_messaging\');\r\n	fetch_object(\'visitor_messaging\').scrollIntoView();\r\n\r\n	var textarea = fetch_object(\'visitor_message_form_textarea\');\r\n	if (textarea)\r\n	{\r\n		textarea.focus();\r\n		textarea.select();\r\n	}\r\n	return false;\r\n}\r\n</if>\r\n-->\r\n</script>\r\n\r\n</head>\r\n<body>\r\n\r\n$header\r\n$navbar\r\n\r\n\r\n<!-- begin user css -->\r\n<div id=\"usercss\" class=\"floatcontainer\">\r\n\r\n<div id=\"content_container\">\r\n	<div id=\"content\">\r\n\r\n		<div id=\"main_userinfo\" class=\"floatcontainer\">\r\n			<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\r\n			<tr>\r\n				<if condition=\"$blocks[\'profile_picture\']\">\r\n					<td id=\"profilepic_cell\" class=\"tborder alt2\">$blocks[profile_picture]</td>\r\n				</if>\r\n				<td valign=\"top\" width=\"100%\" id=\"username_box\"<if condition=\"$prepared[\'profilepicurl\']\"> class=\"profilepic_adjacent\"</if>>\r\n					<if condition=\"$prepared[\'rank\'] OR $prepared[\'reputationdisplay\']\">\r\n						<div id=\"reputation_rank\">\r\n							<if condition=\"$prepared[\'reputationdisplay\']\">\r\n								<div id=\"reputation\">$prepared[reputationdisplay]</div>\r\n							</if>\r\n							<if condition=\"$prepared[\'rank\']\">\r\n								<div id=\"rank\">$prepared[rank]</div>\r\n							</if>\r\n						</div>\r\n					</if>\r\n					<h1>$prepared[musername] $prepared[onlinestatus]</h1>\r\n					<if condition=\"$prepared[\'usertitle\']\">\r\n						<h2>$prepared[usertitle]</h2>\r\n					</if>\r\n				</td>\r\n			</tr>\r\n			</table>\r\n\r\n			<!-- link bar -->\r\n			<div class=\"tborder content_block\" id=\"link_bar\">\r\n			<if condition=\"$prepared[\'myprofile\'] OR $show[\'usercss_switch\'] OR $show[\'contactlinks\'] OR $show[\'userlists\'] OR $show[\'usernotes\'] OR $show[\'edit_profile\']\">\r\n				<ul class=\"thead block_row block_title list_no_decoration floatcontainer\">\r\n					<if condition=\"$prepared[\'myprofile\']\">\r\n						<if condition=\"$show[\'can_customize_profile\']\">\r\n							<li class=\"thead\" id=\"usercss_switch_link\"><a href=\"profile.php?$session[sessionurl]do=customize\">$vbphrase[customize_profile]</a></li>\r\n						</if>\r\n					<else />\r\n						<if condition=\"$show[\'usercss_switch\']\">\r\n							<li class=\"thead\" id=\"usercss_switch_link\"><a href=\"profile.php?$session[sessionurl]do=switchusercss&amp;hash=$bbuserinfo[logouthash]&amp;u=$prepared[userid]\">$usercss_switch_phrase</a></li>\r\n						</if>\r\n					</if>\r\n\r\n					<if condition=\"$show[\'contactlinks\']\">\r\n						<li class=\"thead\" id=\"minicontact\"><a href=\"#contactinfo\">$vbphrase[send_message]</a> <script type=\"text/javascript\">vBmenu.register(\"minicontact\");</script></li>\r\n					</if>\r\n\r\n					<if condition=\"$show[\'userlists\']\">\r\n						<li class=\"thead\" id=\"userlists\"><a href=\"profile.php?$session[sessionurl]do=buddylist&amp;nojs=1\">$vbphrase[user_lists]</a> <script type=\"text/javascript\">vBmenu.register(\"userlists\");</script></li>\r\n					</if>\r\n\r\n					<if condition=\"$show[\'usernotes\']\">\r\n						<li class=\"thead\"><a href=\"usernote.php?$session[sessionurl]u=$prepared[userid]\">$vbphrase[user_notes] ($prepared[usernotecount])</a></li>\r\n					</if>\r\n\r\n					<if condition=\"$show[\'edit_profile\']\">\r\n						<li class=\"thead\"><a href=\"moderator.php?$session[sessionurl]do=useroptions&amp;u=$userinfo[userid]\">$vbphrase[edit_user_profile]</a></li>\r\n					</if>\r\n\r\n				</ul>\r\n			</if>\r\n\r\n				<!-- current activity -->\r\n				<if condition=\"$prepared[\'lastactivitydate\'] OR $prepared[\'action\']\">\r\n					<div class=\"alt2 smallfont block_row\" id=\"activity_info\">\r\n						<if condition=\"$prepared[\'lastactivitydate\']\">\r\n							<div id=\"last_online\">\r\n								<span class=\"shade\">$vbphrase[last_activity]:</span> $prepared[lastactivitydate]<if condition=\"!$show[\'detailedtime\']\"> <span class=\"time\">$prepared[lastactivitytime]</span></if>\r\n							</div>\r\n						</if>\r\n						<if condition=\"$prepared[\'action\']\">\r\n							<span class=\"shade\">$vbphrase[current_activity]:</span> $prepared[action] $prepared[where]\r\n						</if>\r\n					</div>\r\n				</if>\r\n				<!-- / current activity -->\r\n\r\n			</div>\r\n			<!-- / link bar -->\r\n\r\n			<!-- user list menu -->\r\n			<ul id=\"userlists_menu\" class=\"vbmenu_popup list_no_decoration\" style=\"display: none\">\r\n				<li class=\"thead first\"><phrase 1=\"$prepared[username]\">$vbphrase[user_lists]</phrase></li>\r\n				<if condition=\"$prepared[\'canbefriend\']\">\r\n					<li class=\"vbmenu_option\">\r\n						<a href=\"profile.php?$session[sessionurl]do=addlist&amp;userlist=friend&amp;u=$prepared[userid]\"><if condition=\"$prepared[\'requestedfriend\']\">$vbphrase[confirm_friendship_request]<else />$vbphrase[add_to_friends_list]</if></a>\r\n					</li>\r\n				</if>\r\n				<if condition=\"$prepared[\'isfriend\']\">\r\n					<li class=\"vbmenu_option\">\r\n						<a href=\"profile.php?$session[sessionurl]do=removelist&amp;userlist=friend&amp;u=$prepared[userid]\">$vbphrase[remove_from_friends_list]</a>\r\n					</li>\r\n				</if>\r\n				<if condition=\"$show[\'addbuddylist\']\">\r\n					<li class=\"vbmenu_option\">\r\n						<a href=\"profile.php?$session[sessionurl]do=addlist&amp;userlist=buddy&amp;u=$prepared[userid]\">$vbphrase[add_to_contacts]</a>\r\n					</li>\r\n				</if>\r\n				<if condition=\"$show[\'removebuddylist\']\">\r\n					<li class=\"vbmenu_option\">\r\n						<a href=\"profile.php?$session[sessionurl]do=removelist&amp;userlist=buddy&amp;u=$prepared[userid]\">$vbphrase[remove_from_contacts]</a>\r\n					</li>\r\n				</if>\r\n				<if condition=\"$show[\'addignorelist\']\">\r\n					<li class=\"vbmenu_option\">\r\n						<a href=\"profile.php?$session[sessionurl]do=addlist&amp;userlist=ignore&amp;u=$prepared[userid]\">$vbphrase[add_to_ignore_list]</a>\r\n					</li>\r\n				</if>\r\n				<if condition=\"$show[\'removeignorelist\']\">\r\n					<li class=\"vbmenu_option\">\r\n						<a href=\"profile.php?$session[sessionurl]do=removelist&amp;userlist=ignore&amp;u=$prepared[userid]\">$vbphrase[remove_from_ignore_list]</a>\r\n					</li>\r\n				</if>\r\n			</ul>\r\n\r\n			<if condition=\"$show[\'contactlinks\']\">\r\n			<!-- contact popup menu -->\r\n			<ul id=\"minicontact_menu\" class=\"vbmenu_popup list_no_decoration\" style=\"display:none\">\r\n				<if condition=\"$show[\'post_visitor_message\'] OR $show[\'pm\'] OR $show[\'email\']\">\r\n					<li class=\"thead first\"><phrase 1=\"$prepared[username]\">$vbphrase[send_message_to_x]</phrase></li>\r\n				</if>\r\n				<if condition=\"$show[\'post_visitor_message\']\"><li class=\"vbmenu_option\"><img src=\"$stylevar[imgdir_button]/sendtofriend.gif\" alt=\"\" class=\"alt2 inlineimg\" /> <a href=\"visitormessage.php?$session[sessionurl]do=message&amp;u=$prepared[userid]\" onclick=\"return goto_post_pm();\"><phrase 1=\"$prepared[username]\">$vbphrase[post_a_visitor_message_for_x]</phrase></a></li></if>\r\n				<if condition=\"$show[\'pm\']\">\r\n					<li class=\"vbmenu_option\"><img src=\"$stylevar[imgdir_button]/sendtofriend.gif\" alt=\"\" class=\"alt2 inlineimg\" /> <a href=\"private.php?$session[sessionurl]do=newpm&amp;u=$prepared[userid]\" rel=\"nofollow\"><phrase 1=\"$prepared[username]\">$vbphrase[send_private_message_to_x]</phrase></a></li>\r\n				</if>\r\n				<if condition=\"$blocks[\'contactinfo\']\">\r\n				<if condition=\"$show[\'email\']\"><li class=\"vbmenu_option\"><img src=\"$stylevar[imgdir_button]/sendtofriend.gif\" alt=\"\" class=\"alt2 inlineimg\" /> <a href=\"sendmessage.php?$session[sessionurl]do=mailmember&amp;u=$prepared[userid]\" rel=\"nofollow\"><phrase 1=\"$prepared[username]\">$vbphrase[send_message_via_email_to_x]</phrase></a></li></if>\r\n				<if condition=\"$prepared[\'hasimdetails\']\">\r\n					<li class=\"thead<if condition=\"!$show[\'post_visitor_message\'] AND !$show[\'pm\'] AND !$show[\'email\']\"> first</if>\">$vbphrase[instant_messaging]</li>\r\n					<if condition=\"$prepared[\'icq\']\">\r\n						<li class=\"vbmenu_option\"><img class=\"alt2 inlineimg\" alt=\"\" src=\"$stylevar[imgdir_misc]/im_icq.gif\" />  <a href=\"#\" dir=\"ltr\" onclick=\"imwindow(\'icq\', \'$prepared[userid]\', 500, 450); return false;\"><phrase 1=\"$prepared[username]\">$vbphrase[send_icq_message_to_x]</phrase></a></li>\r\n					</if>\r\n					<if condition=\"$prepared[\'aim\']\">\r\n						<li class=\"vbmenu_option\"><img class=\"alt2 inlineimg\" alt=\"\" src=\"$stylevar[imgdir_misc]/im_aim.gif\" /> <a href=\"#\" dir=\"ltr\" onclick=\"imwindow(\'aim\', \'$prepared[userid]\', 400, 200); return false;\"><phrase 1=\"$prepared[username]\">$vbphrase[send_aim_message_to_x]</phrase></a></li>\r\n					</if>\r\n					<if condition=\"$prepared[\'msn\']\">\r\n						<li class=\"vbmenu_option\"><img class=\"alt2 inlineimg\" alt=\"\" src=\"$stylevar[imgdir_misc]/im_msn.gif\" /> <a href=\"#\" dir=\"ltr\" onclick=\"imwindow(\'msn\', \'$prepared[userid]\', 400, 200); return false;\"><phrase 1=\"$prepared[username]\">$vbphrase[send_msn_message_to_x]</phrase></a></li>\r\n					</if>\r\n					<if condition=\"$prepared[\'yahoo\']\">\r\n						<li class=\"vbmenu_option\"><img src=\"$stylevar[imgdir_misc]/im_yahoo.gif\" alt=\"\" class=\"alt2 inlineimg\" /> <a href=\"#\" dir=\"ltr\" onclick=\"imwindow(\'yahoo\', \'$prepared[userid]\', 400, 200); return false;\"><phrase 1=\"$prepared[username]\">$vbphrase[send_yahoo_message_to_x]</phrase></a></li>\r\n					</if>\r\n					<if condition=\"$prepared[\'skype\']\">\r\n						<li class=\"vbmenu_option\"><img src=\"$stylevar[imgdir_misc]/im_skype.gif\" alt=\"\" class=\"alt2 inlineimg\" /> <a href=\"#\" dir=\"ltr\" onclick=\"imwindow(\'skype\', \'$prepared[userid]\', 400, 285); return false;\"><phrase 1=\"$prepared[username]\">$vbphrase[send_skype_message_to_x]</phrase></a></li>\r\n					</if>\r\n				</if>\r\n				</if>\r\n			</ul>\r\n			<!-- / contact popup menu -->\r\n			</if>\r\n	</div>\r\n\r\n	<div id=\"profile_tabs\">\r\n		$template_hook[profile_left_first]\r\n		$blocks[visitor_messaging]\r\n		$blocks[aboutme]\r\n		$blocks[stats]\r\n		$blocks[friends]\r\n		$blocks[infractions]\r\n		$blocks[contactinfo]\r\n		$template_hook[profile_left_last]\r\n	</div>\r\n\r\n	<script type=\"text/javascript\">\r\n	<!--\r\n	vBulletin.register_control(\"vB_TabCtrl\", \"profile_tabs\", \"$selected_tab\", \"&raquo;\", \"profile.php?u=2&do=loadtab&tabid={1:tabid}\");\r\n	//-->\r\n	</script>\r\n\r\n</div>\r\n</div>\r\n\r\n<div id=\"sidebar_container\">\r\n	<!-- sidebar -->\r\n	$template_hook[profile_right_first]\r\n	$blocks[stats_mini]\r\n	$template_hook[profile_right_mini]\r\n	$blocks[friends_mini]\r\n	$blocks[albums]\r\n	$template_hook[profile_right_album]\r\n	$blocks[groups]\r\n	$blocks[visitors]\r\n	$template_hook[profile_right_last]\r\n	<!-- / sidebar -->\r\n</div>\r\n\r\n<!-- end usercss -->\r\n</div>\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', 'template', 1249925853, 'vBulletin Solutions', '3.8.4', 'vbulletin'),
(198, -1, 'memberinfo_albumbit', '<li>\r\n	\".(($album[\'coverthumburl\']) ? (\"\r\n		<a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$album[albumid]\\\"><img src=\\\"$album[coverthumburl]\\\" alt=\\\"$album[title_html]\\\" border=\\\"0\\\" /></a>\r\n	\") : (\"\")).\"\r\n	<div><a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$album[albumid]\\\">$album[title_html]</a></div>\r\n\r\n	\".(($album[\'lastpicturedate\']) ? (\"\r\n		<div class=\\\"smallfont\\\">$album[picturedate]\".((!$show[\'detailedtime\']) ? (\" <span class=\\\"time\\\">$album[picturetime]</span>\") : (\"\")).\"\r\n	\") : (\"\r\n		<div>$vbphrase[n_a]\r\n	\")).\"\r\n		\".(($show[\'moderated\']) ? (\" <img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_misc]/moderated_small.gif\\\" alt=\\\"\" . construct_phrase(\"$vbphrase[x_moderated_pictures]\", \"$album[moderatedcount]\") . \"\\\" />\") : (\"\")).\"\r\n	</div>\r\n</li>', '<li>\r\n	<if condition=\"$album[\'coverthumburl\']\">\r\n		<a href=\"album.php?$session[sessionurl]albumid=$album[albumid]\"><img src=\"$album[coverthumburl]\" alt=\"$album[title_html]\" border=\"0\" /></a>\r\n	</if>\r\n	<div><a href=\"album.php?$session[sessionurl]albumid=$album[albumid]\">$album[title_html]</a></div>\r\n\r\n	<if condition=\"$album[\'lastpicturedate\']\">\r\n		<div class=\"smallfont\">$album[picturedate]<if condition=\"!$show[\'detailedtime\']\"> <span class=\"time\">$album[picturetime]</span></if>\r\n	<else />\r\n		<div>$vbphrase[n_a]\r\n	</if>\r\n		<if condition=\"$show[\'moderated\']\"> <img class=\"inlineimg\" src=\"$stylevar[imgdir_misc]/moderated_small.gif\" alt=\"<phrase 1=\"$album[moderatedcount]\">$vbphrase[x_moderated_pictures]</phrase>\" /></if>\r\n	</div>\r\n</li>', 'template', 1203660803, 'vBulletin Solutions', '3.7.0 Beta 6', 'vbulletin'),
(199, -1, 'memberinfo_block', '<!-- $id -->\r\n<div id=\\\"$id\\\" class=\\\"tborder content_block\\\">\r\n	<h4 class=\\\"thead block_title\\\">\r\n		<a href=\\\"#top\\\" class=\\\"collapse_gadget\\\" onclick=\\\"return toggle_collapse(\'$id\')\\\"><img id=\\\"collapseimg_$id\\\" src=\\\"$stylevar[imgdir_button]/collapse_generic{$vbcollapse[\'collapseimg_\'.$id]}.gif\\\" alt=\\\"\\\" border=\\\"0\\\" /></a>\r\n		<a name=\\\"$id\\\"></a>\r\n		<span class=\\\"block_name\\\">$title</span>\r\n	</h4>\r\n	<div class=\\\"block_content\\\" id=\\\"collapseobj_$id\\\" style=\\\"{$vbcollapse[\'collapseobj_\'.$id]}\\\">$html</div>\r\n</div>\r\n<!-- / $id -->', '<!-- $id -->\r\n<div id=\"$id\" class=\"tborder content_block\">\r\n	<h4 class=\"thead block_title\">\r\n		<a href=\"#top\" class=\"collapse_gadget\" onclick=\"return toggle_collapse(\'$id\')\"><img id=\"collapseimg_$id\" src=\"$stylevar[imgdir_button]/collapse_generic{$vbcollapse[\'collapseimg_\'.$id]}.gif\" alt=\"\" border=\"0\" /></a>\r\n		<a name=\"$id\"></a>\r\n		<span class=\"block_name\">$title</span>\r\n	</h4>\r\n	<div class=\"block_content\" id=\"collapseobj_$id\" style=\"{$vbcollapse[\'collapseobj_\'.$id]}\">$html</div>\r\n</div>\r\n<!-- / $id -->', 'template', 1197973387, 'vBulletin Solutions', '3.7.0 Beta 3', 'vbulletin'),
(200, -1, 'memberinfo_block_aboutme', '<div class=\\\"alt1 block_row\\\">\r\n\".(($show[\'simple_link\']) ? (\"\r\n	<div id=\\\"simple_aboutme_link\\\"><a class=\\\"smallfont\\\" href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=\" . $GLOBALS[\'vbulletin\']->userinfo[\'userid\'] . \"&amp;tab=aboutme&amp;simple=1\\\">$vbphrase[view_your_about_me]</a></div>\r\n\") : (\"\")).\"\r\n\".(($show[\'edit_link\']) ? (\"\r\n	<div id=\\\"simple_aboutme_link\\\"><a class=\\\"smallfont\\\" href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=\" . $GLOBALS[\'vbulletin\']->userinfo[\'userid\'] . \"&amp;tab=aboutme\\\">$vbphrase[edit_your_about_me]</a></div>\r\n\") : (\"\")).\"\r\n<ul class=\\\"list_no_decoration\\\">\r\n	$block_data[fields]\r\n	\".(($prepared[\'signature\']) ? (\"\r\n		<li class=\\\"profilefield_category\\\">\r\n			$vbphrase[signature]\r\n			<dl class=\\\"list_no_decoration profilefield_list\\\"><dd id=\\\"signature\\\">$prepared[signature]</dd></dl>\r\n		</li>\r\n	\") : (\"\")).\"\r\n</ul>\r\n</div>', '<div class=\"alt1 block_row\">\r\n<if condition=\"$show[\'simple_link\']\">\r\n	<div id=\"simple_aboutme_link\"><a class=\"smallfont\" href=\"member.php?$session[sessionurl]u=$bbuserinfo[userid]&amp;tab=aboutme&amp;simple=1\">$vbphrase[view_your_about_me]</a></div>\r\n</if>\r\n<if condition=\"$show[\'edit_link\']\">\r\n	<div id=\"simple_aboutme_link\"><a class=\"smallfont\" href=\"member.php?$session[sessionurl]u=$bbuserinfo[userid]&amp;tab=aboutme\">$vbphrase[edit_your_about_me]</a></div>\r\n</if>\r\n<ul class=\"list_no_decoration\">\r\n	$block_data[fields]\r\n	<if condition=\"$prepared[\'signature\']\">\r\n		<li class=\"profilefield_category\">\r\n			$vbphrase[signature]\r\n			<dl class=\"list_no_decoration profilefield_list\"><dd id=\"signature\">$prepared[signature]</dd></dl>\r\n		</li>\r\n	</if>\r\n</ul>\r\n</div>', 'template', 1227014875, 'vBulletin Solutions', '3.8.0 Beta 3', 'vbulletin'),
