(204, -1, 'memberinfo_block_friends_mini', '<div class=\\\"alt1 smallfont block_row\\\">\r\n	\".(($block_data[\'friendbits\']) ? (\"\r\n		<div class=\\\"friends_counter\\\">\" . construct_phrase(\"$vbphrase[showing_x_of_y_friends]\", \"$block_data[showtotal]\", \"$prepared[friendcount]\") . \"</div>\r\n		<ul class=\\\"list_no_decoration\\\" id=\\\"friends_list\\\">$block_data[friendbits]</ul>\r\n	\") : (\"\".(($prepared[\'myprofile\']) ? (\"\r\n		$vbphrase[your_friends_list_is_empty]\r\n	\") : (\"\r\n		\" . construct_phrase(\"$vbphrase[x_has_not_made_any_friends_yet]\", \"$prepared[username]\") . \"\r\n	\")).\"\")).\"\r\n</div>\r\n<div class=\\\"alt2 smallfont block_row block_footer\\\">\r\n	\".(($prepared[\'myprofile\']) ? (\"\r\n		<a class=\\\"edit_friends_link\\\" href=\\\"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=buddylist\\\">$vbphrase[edit_your_friends_list]</a>\r\n	\") : (\"\".(($prepared[\'canbefriend\']) ? (\"\r\n		<a class=\\\"edit_friends_link\\\" href=\\\"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=addlist&amp;userlist=friend&amp;u=$prepared[userid]\\\">\" . construct_phrase(\"$vbphrase[befriend_x]\", \"$prepared[username]\") . \"</a>\r\n	\") : (\"\")).\"\")).\"\r\n	\".(($block_data[\'friendbits\']) ? (\"\r\n		<a href=\\\"#friends\\\" onclick=\\\"return vB_TabCtrls[\'profile_tabs\'].switch_tab(\'friends\');\\\">$vbphrase[show_all_friends]</a>\r\n	\") : (\"\r\n		&nbsp;\r\n	\")).\"\r\n</div>', '<div class=\"alt1 smallfont block_row\">\r\n	<if condition=\"$block_data[\'friendbits\']\">\r\n		<div class=\"friends_counter\"><phrase 1=\"$block_data[showtotal]\" 2=\"$prepared[friendcount]\">$vbphrase[showing_x_of_y_friends]</phrase></div>\r\n		<ul class=\"list_no_decoration\" id=\"friends_list\">$block_data[friendbits]</ul>\r\n	<else /><if condition=\"$prepared[\'myprofile\']\">\r\n		$vbphrase[your_friends_list_is_empty]\r\n	<else />\r\n		<phrase 1=\"$prepared[username]\">$vbphrase[x_has_not