(205, -1, 'memberinfo_block_groups', '\".(($block_data[\'membergroupcount\']) ? (\"\r\n	<div class=\\\"alt1 smallfont block_row\\\">\r\n		<span class=\\\"group_count\\\">($block_data[membergroupcount])</span> $vbphrase[public_usergroups]:\r\n		<ul class=\\\"list_no_decoration group_list\\\" id=\\\"public_usergroup_list\\\">\r\n			$block_data[membergroupbits]\r\n		</ul>\r\n	</div>\r\n\") : (\"\")).\"\r\n\".(($block_data[\'socialgroupcount\']) ? (\"\r\n	<div class=\\\"alt1 smallfont block_row\\\">\r\n					<span class=\\\"group_count\\\">($block_data[socialgroupcount])</span> $vbphrase[user_created_social_groups]:\r\n		<ul class=\\\"list_no_decoration group_list\\\" id=\\\"social_group_list\\\">\r\n			$block_data[socialgroupbits]\r\n		</ul>\r\n	</div>\r\n\") : (\"\")).\"\r\n\".((!$block_data[\'membergroupcount\'] AND !$block_data[\'socialgroupcount\']) ? (\"\r\n	<div class=\\\"alt1 smallfont block_row\\\">$vbphrase[you_not_member_any_groups]</div>\r\n\") : (\"\")).\"\r\n\".(($block_data[\'show_join_link\']) ? (\"\r\n	<div class=\\\"alt2 smallfont block_row block_footer\\\"><a href=\\\"group.php\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl_q\'] . \"\\\">$vbphrase[join_social_groups]</a></div>\r\n\") : (\"\")).\"', '<if condition=\"$block_data[\'membergroupcount\']\">\r\n	<div class=\"alt1 smallfont block_row\">\r\n		<span class=\"group_count\">($block_data[membergroupcount])</span> $vbphrase[public_usergroups]:\r\n		<ul class=\"list_no_decoration group_list\" id=\"public_usergroup_list\">\r\n			$block_data[membergroupbits]\r\n		</ul>\r\n	</div>\r\n</if>\r\n<if condition=\"$block_data[\'socialgroupcount\']\">\r\n	<div class=\"alt1 smallfont block_row\">\r\n					<span class=\"group_count\">($block_data[socialgroupcount])</span> $vbphrase[user_created_social_groups]:\r\n		<ul class=\"list_no_decoration group_list\" id=\"social_group_list\">\r\n			$block_data[socialgroupbits]\r\n		</ul>\r\n	</div>\r\n</if>\r\n<if condition=\"!$block_data[\'membergroupcount\'] AND !$block_data[\'socialgroupcount\']\">\r\n	<div class=\"alt1 smallfont block_row\">$vbphrase[you_not_member_any_groups]</div>\r\n</if>\r\n<if condition=\"$block_data[\'show_join_link\']\">\r\n	<div class=\"alt2 smallfont block_row block_footer\"><a href=\"group.php$session[sessionurl_q]\">$vbphrase[join_social_groups]</a></div>\r\n</if>', 'template', 1218539988, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(206, -1, 'memberinfo_block_infractions', '<table cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\" colspan=\\\"$_block_data[colspan]\".(($show[\'reverse\']) ? (\"5\") : (\"4\")).\"\\\">\r\n		<span style=\\\"float:$stylevar[right]\\\" class=\\\"smallfont\\\">\" . construct_phrase(\"$vbphrase[x_points_total]\", \"$userinfo[ipoints]\") . \"</span>\r\n		\".(($show[\'giveinfraction\']) ? (\"\r\n			<a style=\\\"text-decoration: underline\\\" href=\\\"infraction.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=report&amp;u=$userinfo[userid]\\\">$vbphrase[give_infraction]</a>\r\n		\") : (\"\")).\"\r\n	</td>\r\n</tr>\r\n\".(($block_data[\'infractionbits\']) ? (\"\r\n<tr>\r\n	<td class=\\\"thead\\\">&nbsp;</td>\r\n	<td class=\\\"thead\\\">$vbphrase[post] / $vbphrase[reason]</td>\r\n	<td class=\\\"thead\\\">$vbphrase[date] / $vbphrase[posted_by]</td>\r\n	<td class=\\\"thead\\\">$vbphrase[points] / $vbphrase[expires]</td>\r\n	\".(($show[\'reverse\']) ? (\"<td class=\\\"thead\\\">$vbphrase[view]</td>\") : (\"\")).\"\r\n</tr>\r\n<!--<tr>\r\n	<td class=\\\"thead\\\">&nbsp;</td>\r\n	<td class=\\\"thead\\\">$vbphrase[post]</td>\r\n	<td class=\\\"thead\\\">$vbphrase[date]</td>\r\n	<td class=\\\"thead\\\">$vbphrase[expires]</td>\r\n	<td class=\\\"thead\\\">$vbphrase[points]</td>\r\n	<td class=\\\"thead\\\">$vbphrase[reason]</td>\r\n	<td class=\\\"thead\\\" nowrap=\\\"nowrap\\\">$vbphrase[posted_by]</td>\r\n	\".(($show[\'reverse\']) ? (\"<td class=\\\"thead\\\">$vbphrase[details]</td>\") : (\"\")).\"\r\n</tr>-->\r\n$block_data[infractionbits]\r\n\") : (\"\")).\"\r\n</table>\r\n\r\n\".(($block_data[pagenav]) ? (\"\r\n<div class=\\\"alt2 block_row\\\" id=\\\"visitor_message_tab_footer\\\">\r\n	<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n	<tr>\r\n		<td class=\\\"smallfont\\\" align=\\\"$stylevar[right]\\\">$block_data[pagenav]</td>\r\n	</tr>\r\n	</table>\r\n</div>\r\n\") : (\"\")).\"', '<table cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\" colspan=\"$_block_data[colspan]<if condition=\"$show[\'reverse\']\">5<else />4</if>\">\r\n		<span style=\"float:$stylevar[right]\" class=\"smallfont\"><phrase 1=\"$userinfo[ipoints]\">$vbphrase[x_points_total]</phrase></span>\r\n		<if condition=\"$show[\'giveinfraction\']\">\r\n			<a style=\"text-decoration: underline\" href=\"infraction.php?$session[sessionurl]do=report&amp;u=$userinfo[userid]\">$vbphrase[give_infraction]</a>\r\n		</if>\r\n	</td>\r\n</tr>\r\n<if condition=\"$block_data[\'infractionbits\']\">\r\n<tr>\r\n	<td class=\"thead\">&nbsp;</td>\r\n	<td class=\"thead\">$vbphrase[post] / $vbphrase[reason]</td>\r\n	<td class=\"thead\">$vbphrase[date] / $vbphrase[posted_by]</td>\r\n	<td class=\"thead\">$vbphrase[points] / $vbphrase[expires]</td>\r\n	<if condition=\"$show[\'reverse\']\"><td class=\"thead\">$vbphrase[view]</td></if>\r\n</tr>\r\n<!--<tr>\r\n	<td class=\"thead\">&nbsp;</td>\r\n	<td class=\"thead\">$vbphrase[post]</td>\r\n	<td class=\"thead\">$vbphrase[date]</td>\r\n	<td class=\"thead\">$vbphrase[expires]</td>\r\n	<td class=\"thead\">$vbphrase[points]</td>\r\n	<td class=\"thead\">$vbphrase[reason]</td>\r\n	<td class=\"thead\" nowrap=\"nowrap\">$vbphrase[posted_by]</td>\r\n	<if condition=\"$show[\'reverse\']\"><td class=\"thead\">$vbphrase[details]</td></if>\r\n</tr>-->\r\n$block_data[infractionbits]\r\n</if>\r\n</table>\r\n\r\n<if condition=\"$block_data[pagenav]\">\r\n<div class=\"alt2 block_row\" id=\"visitor_message_tab_footer\">\r\n	<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\r\n	<tr>\r\n		<td class=\"smallfont\" align=\"$stylevar[right]\">$block_data[pagenav]</td>\r\n	</tr>\r\n	</table>\r\n</div>\r\n</if>', 'template', 1212413850, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(207, -1, 'memberinfo_block_ministats', '<div class=\\\"alt1 block_row\\\">\r\n	<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\">\r\n	<tr valign=\\\"top\\\">\r\n		<td width=\\\"100%\\\">\r\n			<dl class=\\\"smallfont list_no_decoration profilefield_list\\\">\r\n				\".(($prepared[\'birthday\']) ? (\"\r\n					<dt class=\\\"shade\\\">$vbphrase[birth_date]</dt>\r\n					<dd>$prepared[birthday] \".(($prepared[\'age\']) ? (\"($prepared[age])\") : (\"\")).\"</dd>\r\n					\") : (\"\".(($prepared[\'age\']) ? (\"\r\n						<dt class=\\\"shade\\\">$vbphrase[age]</dt>\r\n						<dd>$prepared[age]</dd>\r\n					\") : (\"\")).\"\")).\"\r\n				<dt class=\\\"shade\\\">$vbphrase[join_date]</dt>\r\n				<dd>$prepared[joindate]</dd>\r\n				<dt class=\\\"shade\\\">$vbphrase[total_posts]</dt>\r\n				<dd>$prepared[posts]</dd>\r\n				$template_hook[profile_ministats_list]\r\n			</dl>\r\n		</td>\r\n		\".(($prepared[\'avatarurl\']) ? (\"\r\n		<td><img src=\\\"$prepared[avatarurl]\\\" alt=\\\"\" . construct_phrase(\"$vbphrase[xs_avatar]\", \"$prepared[username]\") . \"\\\" $prepared[avatarsize] class=\\\"alt2\\\" id=\\\"user_avatar\\\" /></td>\r\n		\") : (\"\")).\"\r\n	</tr>\r\n	</table>\r\n</div>\r\n<div class=\\\"alt2 smallfont block_row block_footer\\\"><a href=\\\"#stats\\\" onclick=\\\"return vB_TabCtrls[\'profile_tabs\'].switch_tab(\'stats\')\\\">$vbphrase[show_all_statistics]</a></div>', '<div class=\"alt1 block_row\">\r\n	<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\r\n	<tr valign=\"top\">\r\n		<td width=\"100%\">\r\n			<dl class=\"smallfont list_no_decoration profilefield_list\">\r\n				<if condition=\"$prepared[\'birthday\']\">\r\n					<dt class=\"shade\">$vbphrase[birth_date]</dt>\r\n					<dd>$prepared[birthday] <if condition=\"$prepared[\'age\']\">($prepared[age])</if></dd>\r\n					<else /><if condition=\"$prepared[\'age\']\">\r\n						<dt class=\"shade\">$vbphrase[age]</dt>\r\n						<dd>$prepared[age]</dd>\r\n					</if></if>\r\n				<dt class=\"shade\">$vbphrase[join_date]</dt>\r\n				<dd>$prepared[joindate]</dd>\r\n				<dt class=\"shade\">$vbphrase[total_posts]</dt>\r\n				<dd>$prepared[posts]</dd>\r\n				$template_hook[profile_ministats_list]\r\n			</dl>\r\n		</td>\r\n		<if condition=\"$prepared[\'avatarurl\']\">\r\n		<td><img src=\"$prepared[avatarurl]\" alt=\"<phrase 1=\"$prepared[username]\">$vbphrase[xs_avatar]</phrase>\" $prepared[avatarsize] class=\"alt2\" id=\"user_avatar\" /></td>\r\n		</if>\r\n	</tr>\r\n	</table>\r\n</div>\r\n<div class=\"alt2 smallfont block_row block_footer\"><a href=\"#stats\" onclick=\"return vB_TabCtrls[\'profile_tabs\'].switch_tab(\'stats\')\">$vbphrase[show_all_statistics]</a></div>', 'template', 1196961753, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
(208, -1, 'memberinfo_block_profilefield', '\".(($show[\'profile_category_title\']) ? (\"\r\n<ul class=\\\"alt1 list_no_decoration block_row\\\">\r\n$block_data[fields]\r\n</ul>\r\n\") : (\"\r\n$block_data[fields]\r\n\")).\"', '<if condition=\"$show[\'profile_category_title\']\">\r\n<ul class=\"alt1 list_no_decoration block_row\">\r\n$block_data[fields]\r\n</ul>\r\n<else />\r\n$block_data[fields]\r\n</if>', 'template', 1194528568, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
(209, -1, 'memberinfo_block_profilepicture', '<img src=\\\"$prepared[profilepicurl]\\\" $prepared[profilepicsize] alt=\\\"\" . construct_phrase(\"$vbphrase[xs_picture]\", \"$prepared[username]\") . \"\\\" />', '<img src=\"$prepared[profilepicurl]\" $prepared[profilepicsize] alt=\"<phrase 1=\"$prepared[username]\">$vbphrase[xs_picture]</phrase>\" />', 'template', 1215173058, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(210, -1, 'memberinfo_block_recentvisitors', '\".(($block_data[\'visitorcount\']) ? (\"\r\n<div class=\\\"alt1 smallfont block_row\\\">\r\n	\" . construct_phrase(\"$vbphrase[last_x_visitors]\", \"$block_data[visitorcount]\") . \"\r\n	<ol class=\\\"list_no_decoration last_visitors_list\\\">\r\n		$block_data[visitorbits]\r\n	</ol>\r\n</div>\r\n\") : (\"\")).\"\r\n<div class=\\\"\".(($block_data[\'visitorcount\']) ? (\"alt2\") : (\"alt1\")).\" smallfont block_row block_footer\\\">\r\n	\" . construct_phrase(\"$vbphrase[this_page_has_x_visits]\", \"$prepared[profilevisits]\") . \"\r\n</div>', '<if condition=\"$block_data[\'visitorcount\']\">\r\n<div class=\"alt1 smallfont block_row\">\r\n	<phrase 1=\"$block_data[visitorcount]\">$vbphrase[last_x_visitors]</phrase>\r\n	<ol class=\"list_no_decoration last_visitors_list\">\r\n		$block_data[visitorbits]\r\n	</ol>\r\n</div>\r\n</if>\r\n<div class=\"<if condition=\"$block_data[\'visitorcount\']\">alt2<else />alt1</if> smallfont block_row block_footer\">\r\n	<phrase 1=\"$prepared[profilevisits]\">$vbphrase[this_page_has_x_visits]</phrase>\r\n</div>', 'template', 1196289604, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
(211, -1, 'memberinfo_block_statistics', '<div class=\\\"alt1 block_row\\\">\r\n	$template_hook[profile_stats_first]\r\n\r\n	<fieldset class=\\\"statistics_group\\\">\r\n		<legend>$vbphrase[total_posts]</legend>\r\n		<ul class=\\\"list_no_decoration\\\">\r\n			<li><span class=\\\"shade\\\">$vbphrase[total_posts]:</span> $prepared[posts]</li>\r\n			<li><span class=\\\"shade\\\">$vbphrase[posts_per_day]:</span> $prepared[postsperday]</li>\r\n			\".(($prepared[\'lastposturl\']) ? (\"\r\n				<li>\r\n					<span class=\\\"shade\\\">$vbphrase[last_post]:</span> <a href=\\\"$prepared[lastposturl]\\\">$prepared[lastposttitle]</a> $prepared[lastpostdate] <span class=\\\"time\\\">$prepared[lastposttime]</span>\r\n				</li>\r\n			\") : (\"\")).\"\r\n			<li><a href=\\\"search.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=finduser&amp;u=$userinfo[userid]\\\" rel=\\\"nofollow\\\">\" . construct_phrase(\"$vbphrase[find_all_posts_by_x]\", \"$prepared[username]\") . \"</a></li>\r\n			<li><a href=\\\"search.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=finduser&amp;u=$userinfo[userid]&amp;starteronly=1\\\" rel=\\\"nofollow\\\">\" . construct_phrase(\"$vbphrase[find_all_threads_started_by_x]\", \"$prepared[username]\") . \"</a></li>\r\n		</ul>\r\n	</fieldset>\r\n\r\n	\".(($show[\'album_block\']) ? (\"\r\n	<fieldset class=\\\"statistics_group\\\">\r\n		<legend>$vbphrase[albums]</legend>\r\n		<ul class=\\\"list_no_decoration\\\">\r\n			<li><span class=\\\"shade\\\">$vbphrase[total_albums]:</span> $block_data[albumcount]</li>\r\n			<li><span class=\\\"shade\\\">$vbphrase[total_pictures]:</span> $block_data[picturecount]</li>\r\n			<li><a href=\\\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$prepared[userid]\\\">\" . construct_phrase(\"$vbphrase[albums_created_by_x]\", \"$prepared[username]\") . \"</a></li>\r\n		</ul>\r\n	</fieldset>\r\n	\") : (\"\")).\"\r\n	\".(($show[\'vm_block\']) ? (\"\r\n	<fieldset class=\\\"statistics_group\\\">\r\n		<legend>$vbphrase[visitor_messages]</legend>\r\n		<ul class=\\\"list_no_decoration\\\">\r\n			<li><span class=\\\"shade\\\">$vbphrase[total_messages]:</span> $prepared[vm_total]</li>\r\n			<li><span class=\\\"shade\\\">$vbphrase[most_recent_message]:</span> $prepared[lastvm_date] \".((!$show[\'detailedtime\']) ? (\"$prepared[lastvm_time] \") : (\"\")).\"</li>\r\n			<li><a href=\\\"#visitor_messaging\\\" onclick=\\\"return vB_TabCtrls[\'profile_tabs\'].switch_tab(\'visitor_messaging\');\\\">\" . construct_phrase(\"$vbphrase[visitor_messages_for_x]\", \"$prepared[username]\") . \"</a></li>\r\n			\".(($show[\'post_visitor_message\']) ? (\"<li><a href=\\\"#visitor_messaging\\\" onclick=\\\"return goto_post_pm();\\\">\" . construct_phrase(\"$vbphrase[post_a_visitor_message_for_x]\", \"$prepared[username]\") . \"</a></li>\") : (\"\")).\"\r\n		</ul>\r\n	</fieldset>\r\n	\") : (\"\")).\"\r\n\r\n	\".(($show[\'usernote_block\']) ? (\"\r\n	<fieldset class=\\\"statistics_group\\\">\r\n		<legend>$vbphrase[user_notes]</legend>\r\n		<ul class=\\\"list_no_decoration\\\">\r\n			\".(($show[\'usernote_data\']) ? (\"\r\n			<li><span class=\\\"shade\\\">$vbphrase[total_user_notes]:</span> $prepared[usernotecount]</li>\r\n			<li><span class=\\\"shade\\\">$vbphrase[most_recent_user_note]:</span> $block_data[note_lastdate]\".((!$show[\'detailedtime\']) ? (\" <span class=\\\"time\\\">$block_data[note_lasttime]</span>\") : (\"\")).\"</li>\r\n			<li><a href=\\\"usernote.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$userinfo[userid]\\\">\" . construct_phrase(\"$vbphrase[user_notes_for_x]\", \"$prepared[username]\") . \"</a></li>\r\n			\") : (\"\")).\"\r\n			\".(($show[\'usernote_post\']) ? (\"<li><a href=\\\"usernote.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=newnote&amp;u=$userinfo[userid]\\\">$vbphrase[post_a_user_note]</a></li>\") : (\"\")).\"\r\n		</ul>\r\n	</fieldset>\r\n	\") : (\"\")).\"\r\n\r\n	$template