(233, -1, 'memberlist', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n	<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $vbphrase[members_list]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr align=\\\"center\\\">\r\n	$letterbits\r\n</tr>\r\n</table>\r\n\r\n\".(($show[\'popups\'] AND !$show[\'usergroup\']) ? (\"\r\n<!-- memberlist quick search form -->\r\n<div class=\\\"vbmenu_popup\\\" id=\\\"memberlist_search_menu\\\" style=\\\"display:none\\\">\r\n<form action=\\\"memberlist.php?do=getall\\\" method=\\\"post\\\">\r\n	<table cellpadding=\\\"4\\\" cellspacing=\\\"1\\\" border=\\\"0\\\">\r\n	<tr>\r\n		<td class=\\\"thead\\\">$vbphrase[search_members]</td>\r\n	</tr>\r\n	<tr>\r\n		<td class=\\\"vbmenu_option\\\" title=\\\"nohilite\\\">\r\n			<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n			<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n			<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"getall\\\" />\r\n			<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"ausername\\\" size=\\\"20\\\" value=\\\"$ltr\\\" title=\\\"$vbphrase[username]\\\" />$gobutton\r\n		</td>\r\n	</tr>\r\n	\".(($show[\'advancedlink\']) ? (\"\r\n	<tr>\r\n		<td class=\\\"vbmenu_option\\\"><a href=\\\"memberlist.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=search\\\">$vbphrase[advanced_search]</a></td>\r\n	</tr>\r\n	\") : (\"\")).\"\r\n	</table>\r\n</form>\r\n</div>\r\n<!-- / memberlist quick search form -->\r\n\") : (\"\")).\"\r\n\r\n<br />\r\n\r\n$spacer_close\r\n$spacer_open\r\n\r\n\".(($pagenav) ? (\"\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\" style=\\\"margin-bottom:3px\\\">\r\n<tr valign=\\\"bottom\\\">\r\n	<td align=\\\"$stylevar[right]\\\">$pagenav</td>\r\n</tr>\r\n</table>\r\n\") : (\"\")).\"\r\n\r\n<form action=\\\"profile.php?do=deleteusergroups&amp;usergroupid=$usergroupid\\\" method=\\\"post\\\">\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"deleteusergroups\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"usergroupid\\\" value=\\\"$usergroupid\\\" />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\" style=\\\"border-bottom-width:0px\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\" width=\\\"100%\\\">\r\n		<span class=\\\"smallfont\\\" style=\\\"float:$stylevar[right]\\\">\r\n			\" . construct_phrase(\"$vbphrase[showing_results_x_to_y_of_z]\", \"$first\", \"$last\", \"$totalusers\") . \"\r\n			<br />\r\n			\" . construct_phrase(\"$vbphrase[search_took_x_seconds]\", \"$searchtime\") . \"\r\n		</span>\r\n		\".(($show[\'usergroup\']) ? (\"\r\n		$vbphrase[members_of_usergroup]<span class=\\\"normal\\\">: $leadergroup[title]</span>\r\n		\") : (\"\r\n		\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \": $vbphrase[members_list]\r\n		\")).\"\r\n	</td>\r\n	\".((!$show[\'usergroup\']) ? (\"\r\n	<td class=\\\"vbmenu_control\\\" id=\\\"memberlist_search\\\"><a href=\\\"memberlist.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=search\\\">$vbphrase[search_members]</a> <script type=\\\"text/javascript\\\"> vbmenu_register(\\\"memberlist_search\\\"); </script></td>\r\n	\") : (\"\")).\"\r\n\r\n</tr>\r\n</table>\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr align=\\\"center\\\">\r\n	<td class=\\\"thead\\\" align=\\\"$stylevar[left]\\\" nowrap=\\\"nowrap\\\"><a href=\\\"$sorturl\".((!$show[\'sorturlnoargs\']) ? (\"&amp;\") : (\"\")).\"order=ASC&amp;sort=username&amp;pp=$perpage$usergrouplink\\\">$vbphrase[username]</a> $sortarrow[username]</td>\r\n	\".(($show[\'emailcol\']) ? (\"<td class=\\\"thead\\\" nowrap=\\\"nowrap\\\">$vbphrase[contact]</td>\") : (\"\")).\"\r\n	\".(($show[\'imicons\']) ? (\"<td class=\\\"thead\\\" nowrap=\\\"nowrap\\\">$vbphrase[instant_messaging]</td>\") : (\"\")).\"\r\n	\".(($show[\'homepagecol\']) ? (\"<td class=\\\"thead\\\" nowrap=\\\"nowrap\\\">$vbphrase[home_page]</td>\") : (\"\")).\"\r\n	\".(($show[\'searchcol\']) ? (\"<td class=\\\"thead\\\" nowrap=\\\"nowrap\\\">$vbphrase[find_posts]</td>\") : (\"\")).\"\r\n	\".(($show[\'datejoinedcol\']) ? (\"<td class=\\\"thead\\\" nowrap=\\\"nowrap\\\"><a href=\\\"$sorturl\".((!$show[\'sorturlnoargs\']) ? (\"&amp;\") : (\"\")).\"order=ASC&amp;sort=joindate&amp;pp=$perpage$usergrouplink\\\">$vbphrase[join_date]</a> $sortarrow[joindate]</td>\") : (\"\")).\"\r\n	\".(($show[\'postscol\']) ? (\"<td class=\\\"thead\\\" nowrap=\\\"nowrap\\\"><a href=\\\"$sorturl\".((!$show[\'sorturlnoargs\']) ? (\"&amp;\") : (\"\")).\"order=DESC&amp;sort=posts&amp;pp=$perpage$usergrouplink\\\">$vbphrase[posts]</a> $sortarrow[posts]</td>\") : (\"\")).\"\r\n\r\n	\".(($show[\'lastvisitcol\']) ? (\"<td class=\\\"thead\\\" nowrap=\\\"nowrap\\\"><a href=\\\"$sorturl\".((!$show[\'sorturlnoargs\']) ? (\"&amp;\") : (\"\")).\"order=DESC&amp;sort=lastvisit&amp;pp=$perpage$usergrouplink\\\">$vbphrase[last_visit]</a> $sortarrow[lastvisit]</td>\") : (\"\")).\"\r\n	\".(($show[\'reputationcol\']) ? (\"<td class=\\\"thead\\\" nowrap=\\\"nowrap\\\"><a href=\\\"$sorturl\".((!$show[\'sorturlnoargs\']) ? (\"&amp;\") : (\"\")).\"order=DESC&amp;sort=reputation&amp;pp=$perpage$usergrouplink\\\">$vbphrase[reputation]</a> $sortarrow[reputation]</td>\") : (\"\")).\"\r\n	\".(($show[\'avatarcol\']) ? (\"<td class=\\\"thead\\\" nowrap=\\\"nowrap\\\">$vbphrase[avatar]</td>\") : (\"\")).\"\r\n	\".(($show[\'profilepiccol\']) ? (\"<td class=\\\"thead\\\" nowrap=\\\"nowrap\\\">$vbphrase[profile_picture]</td>\") : (\"\")).\"\r\n	\".(($show[\'birthdaycol\']) ? (\"<td class=\\\"thead\\\" nowrap=\\\"nowrap\\\">$vbphrase[birthday]</td>\") : (\"\")).\"\r\n	\".(($show[\'agecol\']) ? (\"<td class=\\\"thead\\\" nowrap=\\\"nowrap\\\"><a href=\\\"$sorturl\".((!$show[\'sorturlnoargs\']) ? (\"&amp;\") : (\"\")).\"order=ASC&amp;sort=age&amp;pp=$perpage$usergrouplink\\\">$vbphrase[age]</a> $sortarrow[age]</td>\") : (\"\")).\"\r\n	\".(($show[\'customfields\']) ? (\"$customfieldsheader\") : (\"\")).\"\r\n	\".(($show[\'usergroup\']) ? (\"<td class=\\\"thead\\\"><input name=\\\"allbox\\\" type=\\\"checkbox\\\" value=\\\"Check All\\\" title=\\\"$vbphrase[check_uncheck_all]\\\" onclick=\\\"checkall(this.form);\\\" /></td>\") : (\"\")).\"\r\n</tr>\r\n$memberlistbits\r\n<tr>\r\n	<td class=\\\"tfoot\\\" colspan=\\\"$totalcols\\\" align=\\\"$stylevar[right]\\\">\r\n		<span class=\\\"smallfont\\\">\r\n		\".(($show[\'usergroup\']) ? (\"\r\n			<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[remove_selected_users]\\\" />\r\n		\") : (\"\r\n			\" . construct_phrase(\"$vbphrase[showing_results_x_to_y_of_z]\", \"$first\", \"$last\", \"$totalusers\") . \"\r\n		\")).\"\r\n		</span>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>\r\n\r\n\".(($pagenav) ? (\"\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\" style=\\\"margin-top:3px\\\">\r\n<tr valign=\\\"top\\\">\r\n	<td align=\\\"$stylevar[right]\\\">$pagenav</td>\r\n</tr>\r\n</table>\r\n\") : (\"\")).\"\r\n\r\n$spacer_close\r\n$spacer_open\r\n\r\n<br />\r\n\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n<tr>\r\n	<td width=\\\"100%\\\">&nbsp;</td>\r\n	<td>$forumjump</td>\r\n</tr>\r\n</table>\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n	<title>$vboptions[bbtitle] - $vbphrase[members_list]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr align=\"center\">\r\n	$letterbits\r\n</tr>\r\n</table>\r\n\r\n<if condition=\"$show[\'popups\'] AND !$show[\'usergroup\']\">\r\n<!-- memberlist quick search form -->\r\n<div class=\"vbmenu_popup\" id=\"memberlist_search_menu\" style=\"display:none\">\r\n<form action=\"memberlist.php?do=getall\" method=\"post\">\r\n	<table cellpadding=\"4\" cellspacing=\"1\" border=\"0\">\r\n	<tr>\r\n		<td class=\"thead\">$vbphrase[search_members]</td>\r\n	</tr>\r\n	<tr>\r\n		<td class=\"vbmenu_option\" title=\"nohilite\">\r\n			<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n			<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n			<input type=\"hidden\" name=\"do\" value=\"getall\" />\r\n			<input type=\"text\" class=\"bginput\" name=\"ausername\" size=\"20\" value=\"$ltr\" title=\"$vbphrase[username]\" />$gobutton\r\n		</td>\r\n	</tr>\r\n	<if condition=\"$show[\'advancedlink\']\">\r\n	<tr>\r\n		<td class=\"vbmenu_option\"><a href=\"memberlist.php?$session[sessionurl]do=search\">$vbphrase[advanced_search]</a></td>\r\n	</tr>\r\n	</if>\r\n	</table>\r\n</form>\r\n</div>\r\n<!-- / memberlist quick search form -->\r\n</if>\r\n\r\n<br />\r\n\r\n$spacer_close\r\n$spacer_open\r\n\r\n<if condition=\"$pagenav\">\r\n<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"margin-bottom:3px\">\r\n<tr valign=\"bottom\">\r\n	<td align=\"$stylevar[right]\">$pagenav</td>\r\n</tr>\r\n</table>\r\n</if>\r\n\r\n<form action=\"profile.php?do=deleteusergroups&amp;usergroupid=$usergroupid\" method=\"post\">\r\n<input type=\"hidden\" name=\"do\" value=\"deleteusergroups\" />\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n<input type=\"hidden\" name=\"usergroupid\" value=\"$usergroupid\" />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\" style=\"border-bottom-width:0px\">\r\n<tr>\r\n	<td class=\"tcat\" width=\"100%\">\r\n		<span class=\"smallfont\" style=\"float:$stylevar[right]\">\r\n			<phrase 1=\"$first\" 2=\"$last\" 3=\"$totalusers\">$vbphrase[showing_results_x_to_y_of_z]</phrase>\r\n			<br />\r\n			<phrase 1=\"$searchtime\">$vbphrase[search_took_x_seconds]</phrase>\r\n		</span>\r\n		<if condition=\"$show[\'usergroup\']\">\r\n		$vbphrase[members_of_usergroup]<span class=\"normal\">: $leadergroup[title]</span>\r\n		<else />\r\n		$vboptions[bbtitle]: $vbphrase[members_list]\r\n		</if>\r\n	</td>\r\n	<if condition=\"!$show[\'usergroup\']\">\r\n	<td class=\"vbmenu_control\" id=\"memberlist_search\"><a href=\"memberlist.php?$session[sessionurl]do=search\">$vbphrase[search_members]</a> <script type=\"text/javascript\"> vbmenu_register(\"memberlist_search\"); </script></td>\r\n	</if>\r\n\r\n</tr>\r\n</table>\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr align=\"center\">\r\n	<td class=\"thead\" align=\"$stylevar[left]\" nowrap=\"nowrap\"><a href=\"$sorturl<if condition=\"!$show[\'sorturlnoargs\']\">&amp;</if>order=ASC&amp;sort=username&amp;pp=$perpage$usergrouplink\">$vbphrase[username]</a> $sortarrow[username]</td>\r\n	<if condition=\"$show[\'emailcol\']\"><td class=\"thead\" nowrap=\"nowrap\">$vbphrase[contact]</td></if>\r\n	<if condition=\"$show[\'imicons\']\"><td class=\"thead\" nowrap=\"nowrap\">$vbphrase[instant_messaging]</td></if>\r\n	<if condition=\"$show[\'homepagecol\']\"><td class=\"thead\" nowrap=\"nowrap\">$vbphrase[home_page]</td></if>\r\n	<if condition=\"$show[\'searchcol\']\"><td class=\"thead\" nowrap=\"nowrap\">$vbphrase[find_posts]</td></if>\r\n	<if condition=\"$show[\'datejoinedcol\']\"><td class=\"thead\" nowrap=\"nowrap\"><a href=\"$sorturl<if condition=\"!$show[\'sorturlnoargs\']\">&amp;</if>order=ASC&amp;sort=joindate&amp;pp=$perpage$usergrouplink\">$vbphrase[join_date]</a> $sortarrow[joindate]</td></if>\r\n	<if condition=\"$show[\'postscol\']\"><td class=\"thead\" nowrap=\"nowrap\"><a href=\"$sorturl<if condition=\"!$show[\'sorturlnoargs\']\">&amp;</if>order=DESC&amp;sort=posts&amp;pp=$perpage$usergrouplink\">$vbphrase[posts]</a> $sortarrow[posts]</td></if>\r\n\r\n	<if condition=\"$show[\'lastvisitcol\']\"><td class=\"thead\" nowrap=\"nowrap\"><a href=\"$sorturl<if condition=\"!$show[\'sorturlnoargs\']\">&amp;</if>order=DESC&amp;sort=lastvisit&amp;pp=$perpage$usergrouplink\">$vbphrase[last_visit]</a> $sortarrow[lastvisit]</td></if>\r\n	<if condition=\"$show[\'reputationcol\']\"><td class=\"thead\" nowrap=\"nowrap\"><a href=\"$sorturl<if condition=\"!$show[\'sorturlnoargs\']\">&amp;</if>order=DESC&amp;sort=reputation&amp;pp=$perpage$usergrouplink\">$vbphrase[reputation]</a> $sortarrow[reputation]</td></if>\r\n	<if condition=\"$show[\'avatarcol\']\"><td class=\"thead\" nowrap=\"nowrap\">$vbphrase[avatar]</td></if>\r\n	<if condition=\"$show[\'profilepiccol\']\"><td class=\"thead\" nowrap=\"nowrap\">$vbphrase[profile_picture]</td></if>\r\n	<if condition=\"$show[\'birthdaycol\']\"><td class=\"thead\" nowrap=\"nowrap\">$vbphrase[birthday]</td></if>\r\n	<if condition=\"$show[\'agecol\']\"><td class=\"thead\" nowrap=\"nowrap\"><a href=\"$sorturl<if condition=\"!$show[\'sorturlnoargs\']\">&amp;</if>order=ASC&amp;sort=age&amp;pp=$perpage$usergrouplink\">$vbphrase[age]</a> $sortarrow[age]</td></if>\r\n	<if condition=\"$show[\'customfields\']\">$customfieldsheader</if>\r\n	<if condition=\"$show[\'usergroup\']\"><td class=\"thead\"><input name=\"allbox\" type=\"checkbox\" value=\"Check All\" title=\"$vbphrase[check_uncheck_all]\" onclick=\"checkall(this.form);\" /></td></if>\r\n</tr>\r\n$memberlistbits\r\n<tr>\r\n	<td class=\"tfoot\" colspan=\"$totalcols\" align=\"$stylevar[right]\">\r\n		<span class=\"smallfont\">\r\n		<if condition=\"$show[\'usergroup\']\">\r\n			<input type=\"submit\" class=\"button\" value=\"$vbphrase[remove_selected_users]\" />\r\n		<else />\r\n			<phrase 1=\"$first\" 2=\"$last\" 3=\"$totalusers\">$vbphrase[showing_results_x_to_y_of_z]</phrase>\r\n		</if>\r\n		</span>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>\r\n\r\n<if condition=\"$pagenav\">\r\n<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"margin-top:3px\">\r\n<tr valign=\"top\">\r\n	<td align=\"$stylevar[right]\">$pagenav</td>\r\n</tr>\r\n</table>\r\n</if>\r\n\r\n$spacer_close\r\n$spacer_open\r\n\r\n<br />\r\n\r\n<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\r\n<tr>\r\n	<td width=\"100%\">&nbsp;</td>\r\n	<td>$forumjump</td>\r\n</tr>\r\n</table>\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', 'template', 1212144677, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(234, -1, 'memberlist_letter', '\".(($show[\'selectedletter\']) ? (\"\r\n<td class=\\\"alt1\\\" width=\\\"3%\\\">[<strong>$currentletter</strong>]</td>\r\n\") : (\"\r\n<td class=\\\"alt2\\\" width=\\\"3%\\\"><a href=\\\"memberlist.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"ltr=$linkletter&amp;pp=$perpage&amp;sort=$sortfield&amp;order=$sortorder$usergrouplink$ltrurl\\\">$currentletter</a></td>\r\n\")).\"', '<if condition=\"$show[\'selectedletter\']\">\r\n<td class=\"alt1\" width=\"3%\">[<strong>$currentletter</strong>]</td>\r\n<else />\r\n<td class=\"alt2\" width=\"3%\"><a href=\"memberlist.php?$session[sessionurl]ltr=$linkletter&amp;pp=$perpage&amp;sort=$sortfield&amp;order=$sortorder$usergrouplink$ltrurl\">$currentletter</a></td>\r\n</if>', 'template', 1210086457, 'vBulletin Solutions', '3.7.1', 'vbulletin'),
(235, -1, 'memberlist_resultsbit', '<tr align=\\\"center\\\">\r\n	<td class=\\\"alt1Active\\\" align=\\\"$stylevar[left]\\\" id=\\\"u$userinfo[userid]\\\">\r\n		<a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$userinfo[userid]\\\">$userinfo[musername]</a>\r\n		\".(($show[\'usertitlecol\']) ? (\"<div class=\\\"smallfont\\\">$userinfo[usertitle]</div>\") : (\"\")).\"\r\n	</td>\r\n	\".(($show[\'emailcol\'] AND exec_switch_bg()) ? (\"<td class=\\\"$bgclass\\\">\".(($show[\'emaillink\']) ? (\"<a href=\\\"sendmessage.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=mailmember&amp;u=$userinfo[userid]\\\" target=\\\"_blank\\\" rel=\\\"nofollow\\\"><img src=\\\"$stylevar[imgdir_button]/email.gif\\\" alt=\\\"email.gif\\\" title=\\\"\" . construct_phrase(\"$vbphrase[click_here_to_email_x]\", \"$userinfo[username]\") . \"\\\" border=\\\"0\\\" /></a>\") : (\"\")).\"&nbsp;\".(($show[\'pmlink\']) ? (\"<a href=\\\"private.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=newpm&amp;u=$userinfo[userid]\\\" target=\\\"_blank\\\" rel=\\\"nofollow\\\"><img src=\\\"$stylevar[imgdir_button]/sendpm.gif\\\" alt=\\\"sendpm.gif\\\" title=\\\"\" . construct_phrase(\"$vbphrase[send_private_message_to_x]\", \"$userinfo[username]\") . \"\\\" border=\\\"0\\\" /></a>\") : (\"\")).\"</td>\") : (\"\")).\"\r\n	\".(($show[\'imicons\'] AND exec_switch_bg()) ? (\"<td class=\\\"$bgclass\\\">$userinfo[icqicon] $userinfo[aimicon] $userinfo[msnicon] $userinfo[yahooicon] $userinfo[skypeicon]</td>\") : (\"\")).\"\r\n	\".(($show[\'homepagecol\'] AND exec_switch_bg()) ? (\"<td class=\\\"$bgclass\\\">\".(($show[\'homepagelink\']) ? (\"<a href=\\\"$userinfo[homepage]\\\" target=\\\"_blank\\\"><img src=\\\"$stylevar[imgdir_button]/home.gif\\\" alt=\\\"home.gif\\\" title=\\\"\" . construct_phrase(\"$vbphrase[visit_xs_homepage]\", \"$userinfo[username]\") . \"\\\"  border=\\\"0\\\" /></a>\") : (\"&nbsp;\")).\"</td>\") : (\"\")).\"\r\n