(257, -1, 'modifyavatarbit', '	<td class=\\\"smallfont\\\" align=\\\"$stylevar[left]\\\">\r\n		<label for=\\\"rb_avatarid_$avatar[avatarid]\\\">\r\n			<img src=\\\"$avatar[avatarpath]\\\" alt=\\\"$avatar[title]\\\" border=\\\"0\\\" /><br />\r\n			<input type=\\\"radio\\\" name=\\\"avatarid\\\" value=\\\"$avatar[avatarid]\\\" id=\\\"rb_avatarid_$avatar[avatarid]\\\" $avatarchecked[$avatarid] />$avatar[title]\r\n		</label>\r\n	</td>\r\n', '	<td class=\"smallfont\" align=\"$stylevar[left]\">\r\n		<label for=\"rb_avatarid_$avatar[avatarid]\">\r\n			<img src=\"$avatar[avatarpath]\" alt=\"$avatar[title]\" border=\"0\" /><br />\r\n			<input type=\"radio\" name=\"avatarid\" value=\"$avatar[avatarid]\" id=\"rb_avatarid_$avatar[avatarid]\" $avatarchecked[$avatarid] />$avatar[title]\r\n		</label>\r\n	</td>\r\n', 'template', 1067805167, 'vBulletin Solutions', '', 'vbulletin'),
(258, -1, 'modifyavatarbit_custom', '<td class=\\\"smallfont\\\">\r\n	<img src=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'avatarurl\'] . \"\\\" alt=\\\"$vbphrase[custom_avatar]\\\" border=\\\"0\\\" />\r\n</td>', '<td class=\"smallfont\">\r\n	<img src=\"$bbuserinfo[avatarurl]\" alt=\"$vbphrase[custom_avatar]\" border=\"0\" />\r\n</td>', 'template', 1094754561, 'vBulletin Solutions', '', 'vbulletin'),
(259, -1, 'modifyavatarbit_noavatar', '<td class=\\\"alt1\\\" style=\\\"border:1px inset; padding:$stylevar[cellpadding]px\\\">\r\n	<span class=\\\"smallfont\\\">$vbphrase[no_avatar_specified]</span>\r\n</td>', '<td class=\"alt1\" style=\"border:1px inset; padding:$stylevar[cellpadding]px\">\r\n	<span class=\"smallfont\">$vbphrase[no_avatar_specified]</span>\r\n</td>', 'template', 1072807062, 'vBulletin Solutions', '', 'vbulletin'),
(260, -1, 'modifyavatar_category', '	<option value=\\\"$thiscategoryid\\\"$selected>$category[title] (\" . construct_phrase(\"$vbphrase[x_avatars]\", \"$category[avatars]\") . \")</option>\r\n', '	<option value=\"$thiscategoryid\"$selected>$category[title] (<phrase 1=\"$category[avatars]\">$vbphrase[x_avatars]</phrase>)</option>\r\n', 'template', 1070079040, 'vBulletin Solutions', '', 'vbulletin'),
(261, -1, 'modifybuddylist', '<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		<span style=\\\"float:$stylevar[right]\\\" class=\\\"smallfont\\\">$vbphrase[total]: <span id=\\\"buddycount\\\">$buddycount</span></span>\r\n		\".(($show[\'friend_controls\']) ? (\"$vbphrase[contacts_and_friends]\") : (\"$vbphrase[contacts]\")).\"\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div align=\\\"$stylevar[left]\\\">\r\n\r\n			<fieldset class=\\\"fieldset\\\">\r\n				<legend>\".(($show[\'friend_controls\']) ? (\"$vbphrase[contacts_and_friends]\") : (\"$vbphrase[contacts]\")).\"</legend>								\r\n				<form action=\\\"profile.php?do=updatelist&amp;userlist=buddy\\\" method=\\\"post\\\" id=\\\"buddylist_change_form\\\" class=\\\"floatcontainer\\\"  \".((!$show[\'buddylist\']) ? (\"style=\\\"display: none\\\"\") : (\"\")).\">\r\n					<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n					<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n					<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"updatelist\\\" />\r\n					<input type=\\\"hidden\\\" name=\\\"userlist\\\" value=\\\"buddy\\\" />\r\n					<div class=\\\"checkbox_ctrls floatcontainer\\\">\r\n						<input type=\\\"text\\\" id=\\\"userlist_filter\\\" class=\\\"filterbox_inactive bginput smallfont\\\" size=\\\"15\\\" value=\\\"$vbphrase[find_people_on_your_list]\\\" title=\\\"$vbphrase[userlist_filter_tooltip]\\\" />\r\n						<label class=\\\"show_avatars_ctrl shade\\\"><input type=\\\"checkbox\\\" id=\\\"buddylist_showavatars\\\"$showavatarchecked />$vbphrase[show_avatars]</label>\r\n						<!--<label class=\\\"check_all_ctrl shade\\\"><input type=\\\"checkbox\\\" id=\\\"buddylist_checkall\\\" checked=\\\"checked\\\" />$vbphrase[check_uncheck_all]</label>-->\r\n					</div>\r\n					\".(($show[\'avatars\']) ? (\"\r\n						<ul class=\\\"userlist userlist_showavatars floatcontainer\\\" id=\\\"buddylist\\\">\r\n					\") : (\"\r\n						<ul class=\\\"userlist userlist_hideavatars floatcontainer\\\" id=\\\"buddylist\\\">\r\n					\")).\"\r\n						$buddylist\r\n						<li style=\\\"display:none\\\">&nbsp;</li>\r\n					</ul>\r\n					<div class=\\\"submitrow smallfont\\\">\r\n						<img src=\\\"$stylevar[imgdir_misc]/progress.gif\\\" id=\\\"buddylist_change_progress\\\" class=\\\"inlineimg\\\" style=\\\"display:none\\\" alt=\\\"\\\" />\r\n						<input type=\\\"submit\\\" class=\\\"button\\\" id=\\\"submit_save\\\" value=\\\"$vbphrase[save_changes]\\\" />\r\n					</div>\r\n					<hr />\r\n				</form>\r\n				<form action=\\\"profile.php?do=updatelist&amp;userlist=buddy\\\" method=\\\"post\\\" id=\\\"buddylist_add_form\\\" class=\\\"floatcontainer\\\">\r\n					<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n					<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n					<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"updatelist\\\" />\r\n					<input type=\\\"hidden\\\" name=\\\"userlist\\\" value=\\\"buddy\\\" />\r\n					<div id=\\\"buddylist_error\\\" class=\\\"userlist_error floatcontainer\\\"><img src=\\\"$stylevar[imgdir_statusicon]/wol_error.gif\\\" id=\\\"buddylist_error_image\\\" class=\\\"userlist_error_image\\\" alt=\\\"\\\" /> <span id=\\\"buddylist_error_message\\\"></span></div>\r\n					<div class=\\\"userlist_form_controls\\\">\r\n						<label for=\\\"buddylist_add_txt\\\">$vbphrase[add_member_to_your_list]</label>\r\n						<div>\r\n							<span id=\\\"buddylist_add\\\"><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"username\\\" id=\\\"buddylist_add_txt\\\" size=\\\"35\\\" value=\\\"$buddy_username\\\" /></span>\r\n							<div id=\\\"buddylist_add_menu\\\" class=\\\"vbmenu_popup\\\" style=\\\"display:none\\\"></div>\r\n							<input type=\\\"submit\\\" class=\\\"button\\\" id=\\\"buddylist_submit\\\" value=\\\"$vbphrase[add_contact]\\\" />\r\n							\".(($show[\'friend_controls\']) ? (\"<input type=\\\"submit\\\" class=\\\"button\\\" name=\\\"makefriends\\\" id=\\\"friend_submit\\\" value=\\\"$vbphrase[add_friend]\\\" />\") : (\"\")).\"\r\n							<img src=\\\"$stylevar[imgdir_misc]/progress.gif\\\" id=\\\"buddylist_add_progress\\\" class=\\\"inlineimg\\\" style=\\\"display:none\\\" alt=\\\"\\\" />\r\n						</div>\r\n					</div>\r\n					<hr />\r\n				</form>\r\n				<div class=\\\"fieldsetpad\\\">\r\n					<div class=\\\"userlist_form_controls\\\">\".(($show[\'friend_controls\']) ? (\"$vbphrase[friends_instructions]\") : (\"$vbphrase[contacts_instructions]\")).\"</div>\r\n				</div>\r\n			</fieldset>\r\n\r\n			<fieldset class=\\\"fieldset\\\" id=\\\"incomingreqs_container\\\" \".((!$show[\'incominglist\']) ? (\"style=\\\"display: none\\\"\") : (\"\")).\">\r\n				<legend id=\\\"irc\\\">$vbphrase[incoming_friend_requests]</legend>\r\n				<form action=\\\"profile.php?do=updatelist&amp;userlist=approval\\\" method=\\\"post\\\" id=\\\"incomingreqs_change_form\\\" class=\\\"floatcontainer\\\">\r\n					<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n					<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n					<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"updatelist\\\" />\r\n					<input type=\\\"hidden\\\" name=\\\"userlist\\\" value=\\\"incoming\\\" />\r\n					<div class=\\\"checkbox_ctrls floatcontainer\\\">\r\n						<label class=\\\"check_all_ctrl shade\\\"><input type=\\\"checkbox\\\" id=\\\"incomingreqs_checkall\\\" />$vbphrase[check_uncheck_all]</label>\r\n						<label class=\\\"show_avatars_ctrl shade\\\"><input type=\\\"checkbox\\\" id=\\\"incomingreqs_showavatars\\\" checked=\\\"checked\\\" />$vbphrase[show_avatars]</label>\r\n					</div>\r\n					<div class=\\\"userlist_title\\\">$vbphrase[incoming_friend_requests]</div>\r\n					<div class=\\\"userlist_description\\\">$vbphrase[incoming_friend_requests_description]</div>\r\n					<ul class=\\\"userlist userlist_showavatars floatcontainer\\\" id=\\\"incomingreqs\\\">\r\n						$incominglist\r\n						<li style=\\\"display:none\\\">&nbsp;</li>\r\n					</ul>\r\n					<div class=\\\"submitrow smallfont\\\">\r\n						<div id=\\\"incomingreqs_action\\\">\r\n							<div><label for=\\\"incomingaction_accept\\\"><input type=\\\"radio\\\" name=\\\"incomingaction\\\" value=\\\"accept\\\" id=\\\"incomingaction_accept\\\" checked=\\\"checked\\\" />$vbphrase[accept_selected_friend_requests]</label></div>\r\n							<div><label for=\\\"incomingaction_reject\\\"><input type=\\\"radio\\\" name=\\\"incomingaction\\\" value=\\\"reject\\\" id=\\\"incomingaction_reject\\\" />$vbphrase[reject_selected_friend_requests]</label></div>\r\n						</div>\r\n						<img src=\\\"$stylevar[imgdir_misc]/progress.gif\\\" id=\\\"incomingreqs_change_progress\\\" class=\\\"inlineimg\\\" style=\\\"display:none\\\" alt=\\\"\\\" />\r\n						<input type=\\\"submit\\\" class=\\\"button\\\" id=\\\"incoming_submit\\\" value=\\\"$vbphrase[save_changes]\\\" />\r\n					</div>\r\n				</form>\r\n			</fieldset>\r\n\r\n		</div>\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n\".(($show[\'popups\']) ? (\"\r\n<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_ajax_namesugg.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n\") : (\"\")).\"\r\n<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_ajax_userlist.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n<script type=\\\"text/javascript\\\">\r\n<!--\r\n\".(($show[\'popups\']) ? (\"\r\nvBmenu.register(\\\"buddylist_add\\\", true);\r\nsnc_buddylist = new vB_AJAX_NameSuggest(\\\"snc_buddylist\\\", \\\"buddylist_add_txt\\\", \\\"buddylist_add\\\");\r\n\") : (\"\")).\"\r\n// ajax saver\r\nvBulletin.register_control(\\\"vB_UserList_Saver\\\", \\\"buddylist\\\");\r\nvBulletin.register_control(\\\"vB_UserList_Saver\\\", \\\"incomingreqs\\\");\r\n// img-label handler\r\nvBulletin.register_control(\\\"vB_UserList_Highlighter\\\", \\\"buddylist\\\");\r\nvBulletin.register_control(\\\"vB_UserList_Highlighter\\\", \\\"incomingreqs\\\");\r\nvBulletin.register_control(\\\"vB_UserList_Filter\\\", \\\"userlist_filter\\\", Array(\\\"buddylist\\\", \\\"incomingreqs\\\"), {\r\n	$js_userlist_array\r\n});\r\nvar vbphrase = {\r\n	\\\"remove_from_userlist_confirm\\\" : \\\"$vbphrase[remove_from_userlist_confirm]\\\"\r\n};\r\n//-->\r\n</script>', '<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		<span style=\"float:$stylevar[right]\" class=\"smallfont\">$vbphrase[total]: <span id=\"buddycount\">$buddycount</span></span>\r\n		<if condition=\"$show[\'friend_controls\']\">$vbphrase[contacts_and_friends]<else />$vbphrase[contacts]</if>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div align=\"$stylevar[left]\">\r\n\r\n			<fieldset class=\"fieldset\">\r\n				<legend><if condition=\"$show[\'friend_controls\']\">$vbphrase[contacts_and_friends]<else />$vbphrase[contacts]</if></legend>								\r\n				<form action=\"profile.php?do=updatelist&amp;userlist=buddy\" method=\"post\" id=\"buddylist_change_form\" class=\"floatcontainer\"  <if condition=\"!$show[\'buddylist\']\">style=\"display: none\"</if>>\r\n					<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n					<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n					<input type=\"hidden\" name=\"do\" value=\"updatelist\" />\r\n					<input type=\"hidden\" name=\"userlist\" value=\"buddy\" />\r\n					<div class=\"checkbox_ctrls floatcontainer\">\r\n						<input type=\"text\" id=\"userlist_filter\" class=\"filterbox_inactive bginput smallfont\" size=\"15\" value=\"$vbphrase[find_people_on_your_list]\" title=\"$vbphrase[userlist_filter_tooltip]\" />\r\n						<label class=\"show_avatars_ctrl shade\"><input type=\"checkbox\" id=\"buddylist_showavatars\"$showavatarchecked />$vbphrase[show_avatars]</label>\r\n						<!--<label class=\"check_all_ctrl shade\"><input type=\"checkbox\" id=\"buddylist_checkall\" checked=\"checked\" />$vbphrase[check_uncheck_all]</label>-->\r\n					</div>\r\n					<if condition=\"$show[\'avatars\']\">\r\n						<ul class=\"userlist userlist_showavatars floatcontainer\" id=\"buddylist\">\r\n					<else />\r\n						<ul class=\"userlist userlist_hideavatars floatcontainer\" id=\"buddylist\">\r\n					</if>\r\n						$buddylist\r\n						<li style=\"display:none\">&nbsp;</li>\r\n					</ul>\r\n					<div class=\"submitrow smallfont\">\r\n						<img src=\"$stylevar[imgdir_misc]/progress.gif\" id=\"buddylist_change_progress\" class=\"inlineimg\" style=\"display:none\" alt=\"\" />\r\n						<input type=\"submit\" class=\"button\" id=\"submit_save\" value=\"$vbphrase[save_changes]\" />\r\n					</div>\r\n					<hr />\r\n				</form>\r\n				<form action=\"profile.php?do=updatelist&amp;userlist=buddy\" method=\"post\" id=\"buddylist_add_form\" class=\"floatcontainer\">\r\n					<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n					<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n					<input type=\"hidden\" name=\"do\" value=\"updatelist\" />\r\n					<input type=\"hidden\" name=\"userlist\" value=\"buddy\" />\r\n					<div id=\"buddylist_error\" class=\"userlist_error floatcontainer\"><img src=\"$stylevar[imgdir_statusicon]/wol_error.gif\" id=\"buddylist_error_image\" class=\"userlist_error_image\" alt=\"\" /> <span id=\"buddylist_error_message\"></span></div>\r\n					<div class=\"userlist_form_controls\">\r\n						<label for=\"buddylist_add_txt\">$vbphrase[add_member_to_your_list]</label>\r\n						<div>\r\n							<span id=\"buddylist_add\"><input type=\"text\" class=\"bginput\" name=\"username\" id=\"buddylist_add_txt\" size=\"35\" value=\"$buddy_username\" /></span>\r\n							<div id=\"buddylist_add_menu\" class=\"vbmenu_popup\" style=\"display:none\"></div>\r\n							<input type=\"submit\" class=\"button\" id=\"buddylist_submit\" value=\"$vbphrase[add_contact]\" />\r\n							<if condition=\"$show[\'friend_controls\']\"><input type=\"submit\" class=\"button\" name=\"makefriends\" id=\"friend_submit\" value=\"$vbphrase[add_friend]\" /></if>\r\n							<img src=\"$stylevar[imgdir_misc]/progress.gif\" id=\"buddylist_add_progress\" class=\"inlineimg\" style=\"display:none\" alt=\"\" />\r\n						</div>\r\n					</div>\r\n					<hr />\r\n				</form>\r\n				<div class=\"fieldsetpad\">\r\n					<div class=\"userlist_form_controls\"><if condition=\"$show[\'friend_controls\']\">$vbphrase[friends_instructions]<else />$vbphrase[contacts_instructions]</if></div>\r\n				</div>\r\n			</fieldset>\r\n\r\n			<fieldset class=\"fieldset\" id=\"incomingreqs_container\" <if condition=\"!$show[\'incominglist\']\">style=\"display: none\"</if>>\r\n				<legend id=\"irc\">$vbphrase[incoming_friend_requests]</legend>\r\n				<form action=\"profile.php?do=updatelist&amp;userlist=approval\" method=\"post\" id=\"incomingreqs_change_form\" class=\"floatcontainer\">\r\n					<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n					<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n					<input type=\"hidden\" name=\"do\" value=\"updatelist\" />\r\n					<input type=\"hidden\" name=\"userlist\" value=\"incoming\" />\r\n					<div class=\"checkbox_ctrls floatcontainer\">\r\n						<label class=\"check_all_ctrl shade\"><input type=\"checkbox\" id=\"incomingreqs_checkall\" />$vbphrase[check_uncheck_all]</label>\r\n						<label class=\"show_avatars_ctrl shade\"><input type=\"checkbox\" id=\"incomingreqs_showavatars\" checked=\"checked\" />$vbphrase[show_avatars]</label>\r\n					</div>\r\n					<div class=\"userlist_title\">$vbphrase[incoming_friend_requests]</div>\r\n					<div class=\"userlist_description\">$vbphrase[incoming_friend_requests_description]</div>\r\n					<ul class=\"userlist userlist_showavatars floatcontainer\" id=\"incomingreqs\">\r\n						$incominglist\r\n						<li style=\"display:none\">&nbsp;</li>\r\n					</ul>\r\n					<div class=\"submitrow smallfont\">\r\n						<div id=\"incomingreqs_action\">\r\n							<div><label for=\"incomingaction_accept\"><input type=\"radio\" name=\"incomingaction\" value=\"accept\" id=\"incomingaction_accept\" checked=\"checked\" />$vbphrase[accept_selected_friend_requests]</label></div>\r\n							<div><label for=\"incomingaction_reject\"><input type=\"radio\" name=\"incomingaction\" value=\"reject\" id=\"incomingaction_reject\" />$vbphrase[reject_selected_friend_requests]</label></div>\r\n						</div>\r\n						<img src=\"$stylevar[imgdir_misc]/progress.gif\" id=\"incomingreqs_change_progress\" class=\"inlineimg\" style=\"display:none\" alt=\"\" />\r\n						<input type=\"submit\" class=\"button\" id=\"incoming_submit\" value=\"$vbphrase[save_changes]\" />\r\n					</div>\r\n				</form>\r\n			</fieldset>\r\n\r\n		</div>\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n<if condition=\"$show[\'popups\']\">\r\n<script type=\"text/javascript\" src=\"clientscript/vbulletin_ajax_namesugg.js?v=$vboptions[simpleversion]\"></script>\r\n</if>\r\n<script type=\"text/javascript\" src=\"clientscript/vbulletin_ajax_userlist.js?v=$vboptions[simpleversion]\"></script>\r\n<script type=\"text/javascript\">\r\n<!--\r\n<if condition=\"$show[\'popups\']\">\r\nvBmenu.register(\"buddylist_add\", true);\r\nsnc_buddylist = new vB_AJAX_NameSuggest(\"snc_buddylist\", \"buddylist_add_txt\", \"buddylist_add\");\r\n</if>\r\n// ajax saver\r\nvBulletin.register_control(\"vB_UserList_Saver\", \"buddylist\");\r\nvBulletin.register_control(\"vB_UserList_Saver\", \"incomingreqs\");\r\n// img-label handler\r\nvBulletin.register_control(\"vB_UserList_Highlighter\", \"buddylist\");\r\nvBulletin.register_control(\"vB_UserList_Highlighter\", \"incomingreqs\");\r\nvBulletin.register_control(\"vB_UserList_Filter\", \"userlist_filter\", Array(\"buddylist\", \"incomingreqs\"), {\r\n	$js_userlist_array\r\n});\r\nvar vbphrase = {\r\n	\"remove_from_userlist_confirm\" : \"$vbphrase[remove_from_userlist_confirm]\"\r\n};\r\n//-->\r\n</script>', 'template', 1213106768, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(262, -1, 'modifybuddylist_user', '<li id=\\\"{$container}_user$user[userid]\\\" class=\\\"alt1\\\">\r\n	<div class=\\\"username\\\">\r\n			<input type=\\\"hidden\\\" name=\\\"listbits[$user[type]_original][$user[userid]]\\\" value=\\\"$user[userid]\\\" />\r\n			<input type=\\\"checkbox\\\" name=\\\"listbits[$user[type]][$user[userid]]\\\" id=\\\"{$container}_usercheck_$user[userid]\\\" value=\\\"$user[userid]\\\"$user[checked]\r\n			/><label class=\\\"avatar_label\\\" for=\\\"{$container}_usercheck_$user[userid]\\\"\r\n			><img src=\\\"$user[avatarurl]\\\"\".(($user[\'avatarwidth\']) ? (\" width=\\\"$user[avatarwidth]\\\"\") : (\"\")).\"\".(($user[\'avatarheight\']) ? (\" height=\\\"$user[avatarheight]\\\"\") : (\"\")).\" id=\\\"{$container}_avatar_$user[userid]\\\" alt=\\\"\" . construct_phrase(\"$vbphrase[xs_avatar]\", \"$user[username]\") . \"\\\" border=\\\"0\\\"\r\n			/></label\r\n			><a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$user[userid]\\\" title=\\\"$vbphrase[view_profile]\\\">$user[username]</a>\r\n	</div>\r\n	\".(($show[\'outgoingrequest\']) ? (\"\r\n		<div class=\\\"friend shade\\\"><label for=\\\"{$container}_friendcheck_$user[userid]\\\"><input type=\\\"checkbox\\\" id=\\\"{$container}_friendcheck_$user[userid]\\\" checked=\\\"checked\\\" disabled=\\\"disabled\\\" />$vbphrase[friendship_requested]</label></div>\r\n	\") : (\"\".(($show[\'friend_checkbox\']) ? (\"\r\n		<div class=\\\"friend\\\">\r\n			<label for=\\\"{$container}_friendcheck_$user[userid]\\\"><input type=\\\"checkbox\\\" name=\\\"listbits[friend][$user[userid]]\\\" id=\\\"{$container}_friendcheck_$user[userid]\\\" value=\\\"$user[userid]\\\"$friendcheck_checked title=\\\"\" . construct_phrase(\"$vbphrase[tick_box_to_make_friends_with_x]\", \"$user[username]\") . \"\\\" />$vbphrase[friend]</label>\r\n			\".(($user[\'extended_type\'] == \'friend\') ? (\"<input type=\\\"hidden\\\" name=\\\"listbits[friend_original][$user[userid]]\\\" value=\\\"$user[userid]\\\" />\") : (\"\")).\"\r\n		</div>\r\n	\") : (\"\")).\"\")).\"\r\n	<hr />\r\n</li>\r\n', '<li id=\"{$container}_user$user[userid]\" class=\"alt1\">\r\n	<div class=\"username\">\r\n			<input type=\"hidden\" name=\"listbits[$user[type]_original][$user[userid]]\" value=\"$user[userid]\" />\r\n			<input type=\"checkbox\" name=\"listbits[$user[type]][$user[userid]]\" id=\"{$container}_usercheck_$user[userid]\" value=\"$user[userid]\"$user[checked]\r\n			/><label class=\"avatar_label\" for=\"{$container}_usercheck_$user[userid]\"\r\n			><img src=\"$user[avatarurl]\"<if condition=\"$user[\'avatarwidth\']\"> width=\"$user[avatarwidth]\"</if><if condition=\"$user[\'avatarheight\']\"> height=\"$user[avatarheight]\"</if> id=\"{$container}_avatar_$user[userid]\" alt=\"<phrase 1=\"$user[username]\">$vbphrase[xs_avatar]</phrase>\" border=\"0\"\r\n			/></label\r\n			><a href=\"member.php?$session[sessionurl]u=$user[userid]\" title=\"$vbphrase[view_profile]\">$user[username]</a>\r\n	</div>\r\n	<if condition=\"$show[\'outgoingrequest\']\">\r\n		<div class=\"friend shade\"><label for=\"{$container}_friendcheck_$user[userid]\"><input type=\"checkbox\" id=\"{$container}_friendcheck_$user[userid]\" checked=\"checked\" disabled=\"disabled\" />$vbphrase[friendship_requested]</label></div>\r\n	<else /><if condition=\"$show[\'friend_checkbox\']\">\r\n		<div class=\"friend\">\r\n			<label for=\"{$container}_friendcheck_$user[userid]\"><input type=\"checkbox\" name=\"listbits[friend][$user[userid]]\" id=\"{$container}_friendcheck_$user[userid]\" value=\"$user[userid]\"$friendcheck_checked title=\"<phrase 1=\"$user[username]\">$vbphrase[tick_box_to_make_friends_with_x]</phrase>\" />$vbphrase[friend]</label>\r\n			<if condition=\"$user[\'extended_type\'] == \'friend\'\"><input type=\"hidden\" name=\"listbits[friend_original][$user[userid]]\" value=\"$user[userid]\" /></if>\r\n		</div>\r\n	</if></if>\r\n	<hr />\r\n</li>\r\n', 'template', 1197388197, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(263, -1, 'modifyignorelist', '<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[ignore_list]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div align=\\\"$stylevar[left]\\\">\r\n\r\n			<fieldset class=\\\"fieldset\\\">\r\n				<legend>$vbphrase[ignore_list]</legend>\r\n				<form action=\\\"profile.php?do=updatelist&amp;userlist=ignore\\\" method=\\\"post\\\" id=\\\"ignorelist_change_form\\\" \".((!$show[\'ignorelist\']) ? (\"style=\\\"display: none\\\"\") : (\"\")).\">\r\n					<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n					<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n					<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"updatelist\\\" />\r\n					<input type=\\\"hidden\\\" name=\\\"userlist\\\" value=\\\"ignore\\\" />\r\n					\".(($ignorelist) ? (\"\r\n					<ul class=\\\"userlist floatcontainer\\\" id=\\\"ignorelist\\\">\r\n						$ignorelist\r\n					</ul>\r\n					\") : (\"\")).\"\r\n					<div class=\\\"submitrow smallfont\\\">\r\n						<label class=\\\"check_all_ctrl shade\\\"><input type=\\\"checkbox\\\" id=\\\"ignorelist_checkall\\\" checked=\\\"checked\\\" />$vbphrase[check_uncheck_all]</label>\r\n						<img src=\\\"$stylevar[imgdir_misc]/progress.gif\\\" id=\\\"ignorelist_change_progress\\\" class=\\\"inlineimg\\\" style=\\\"display:none\\\" alt=\\\"\\\" />\r\n						<input type=\\\"submit\\\" class=\\\"button\\\" id=\\\"submit_save\\\" value=\\\"$vbphrase[save_changes]\\\" />\r\n					</div>\r\n					<hr />\r\n				</form>\r\n				<form action=\\\"profile.php?do=updatelist&amp;userlist=ignore\\\" method=\\\"post\\\" id=\\\"ignorelist_add_form\\\">\r\n					<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n					<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n					<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"updatelist\\\" />\r\n					<input type=\\\"hidden\\\" name=\\\"userlist\\\" value=\\\"ignore\\\" />\r\n					<div id=\\\"ignorelist_error\\\" class=\\\"userlist_error floatcontainer\\\"><img src=\\\"$stylevar[imgdir_statusicon]/wol_error.gif\\\" id=\\\"ignorelist_error_image\\\" class=\\\"userlist_error_image\\\" alt=\\\"\\\" /> <span id=\\\"ignorelist_error_message\\\"></span></div>\r\n					<div class=\\\"userlist_form_controls\\\">\r\n						<label for=\\\"ignorelist_add_txt\\\">$vbphrase[add_member_to_your_list]</label>\r\n						<div>\r\n							<span id=\\\"ignorelist_add\\\"><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"username\\\" id=\\\"ignorelist_add_txt\\\" size=\\\"40\\\" value=\\\"$ignore_username\\\" /></span>\r\n							<div id=\\\"ignorelist_add_menu\\\" class=\\\"vbmenu_popup\\\" style=\\\"display:none\\\"></div>\r\n							<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[okay]\\\" />\r\n						</div>\r\n					</div>\r\n					<hr />\r\n				</form>\r\n				<div class=\\\"fieldsetpad\\\">\r\n					<div class=\\\"userlist_form_controls\\\">$vbphrase[ignorelist_instructions]</div>\r\n				</div>\r\n			</fieldset>\r\n\r\n		</div>\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n\".(($show[\'popups\']) ? (\"\r\n<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_ajax_namesugg.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n\") : (\"\")).\"\r\n<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_ajax_userlist.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n<script type=\\\"text/javascript\\\">\r\n<!--\r\n\".(($show[\'popups\']) ? (\"\r\nvBmenu.register(\\\"ignorelist_add\\\", true);\r\nsnc_ignorelist = new vB_AJAX_NameSuggest(\\\"snc_ignorelist\\\", \\\"ignorelist_add_txt\\\", \\\"ignorelist_add\\\");\r\n\") : (\"\")).\"\r\n// ajax saver\r\nvBulletin.register_control(\\\"vB_UserList_Saver\\\", \\\"ignorelist\\\");\r\n// img-label handler\r\nvBulletin.register_control(\\\"vB_UserList_Highlighter\\\", \\\"ignorelist\\\");\r\n//-->\r\n</script>', '<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">$vbphrase[ignore_list]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div align=\"$stylevar[left]\">\r\n\r\n			<fieldset class=\"fieldset\">\r\n				<legend>$vbphrase[ignore_list]</legend>\r\n				<form action=\"profile.php?do=updatelist&amp;userlist=ignore\" method=\"post\" id=\"ignorelist_change_form\" <if condition=\"!$show[\'ignorelist\']\">style=\"display: none\"</if>>\r\n					<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n					<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n					<input type=\"hidden\" name=\"do\" value=\"updatelist\" />\r\n					<input type=\"hidden\" name=\"userlist\" value=\"ignore\" />\r\n					<if condition=\"$ignorelist\">\r\n					<ul class=\"userlist floatcontainer\" id=\"ignorelist\">\r\n						$ignorelist\r\n					</ul>\r\n					</if>\r\n					<div class=\"submitrow smallfont\">\r\n						<label class=\"check_all_ctrl shade\"><input type=\"checkbox\" id=\"ignorelist_checkall\" checked=\"checked\" />$vbphrase[check_uncheck_all]</label>\r\n						<img src=\"$stylevar[imgdir_misc]/progress.gif\" id=\"ignorelist_change_progress\" class=\"inlineimg\" style=\"display:none\" alt=\"\" />\r\n						<input type=\"submit\" class=\"button\" id=\"submit_save\" value=\"$vbphrase[save_changes]\" />\r\n					</div>\r\n					<hr />\r\n				</form>\r\n				<form action=\"profile.php?do=updatelist&amp;userlist=ignore\" method=\"post\" id=\"ignorelist_add_form\">\r\n					<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n					<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n					<input type=\"hidden\" name=\"do\" value=\"updatelist\" />\r\n					<input type=\"hidden\" name=\"userlist\" value=\"ignore\" />\r\n					<div id=\"ignorelist_error\" class=\"userlist_error floatcontainer\"><img src=\"$stylevar[imgdir_statusicon]/wol_error.gif\" id=\"ignorelist_error_image\" class=\"userlist_error_image\" alt=\"\" /> <span id=\"ignorelist_error_message\"></span></div>\r\n					<div class=\"userlist_form_controls\">\r\n						<label for=\"ignorelist_add_txt\">$vbphrase[add_member_to_your_list]</label>\r\n						<div>\r\n							<span id=\"ignorelist_add\"><input type=\"text\" class=\"bginput\" name=\"username\" id=\"ignorelist_add_txt\" size=\"40\" value=\"$ignore_username\" /></span>\r\n							<div id=\"ignorelist_add_menu\" class=\"vbmenu_popup\" style=\"display:none\"></div>\r\n							<input type=\"submit\" class=\"button\" value=\"$vbphrase[okay]\" />\r\n						</div>\r\n					</div>\r\n					<hr />\r\n				</form>\r\n				<div class=\"fieldsetpad\">\r\n					<div class=\"userlist_form_controls\">$vbphrase[ignorelist_instructions]</div>\r\n				</div>\r\n			</fieldset>\r\n\r\n		</div>\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n<if condition=\"$show[\'popups\']\">\r\n<script type=\"text/javascript\" src=\"clientscript/vbulletin_ajax_namesugg.js?v=$vboptions[simpleversion]\"></script>\r\n</if>\r\n<script type=\"text/javascript\" src=\"clientscript/vbulletin_ajax_userlist.js?v=$vboptions[simpleversion]\"></script>\r\n<script type=\"text/javascript\">\r\n<!--\r\n<if condition=\"$show[\'popups\']\">\r\nvBmenu.register(\"ignorelist_add\", true);\r\nsnc_ignorelist = new vB_AJAX_NameSuggest(\"snc_ignorelist\", \"ignorelist_add_txt\", \"ignorelist_add\");\r\n</if>\r\n// ajax saver\r\nvBulletin.register_control(\"vB_UserList_Saver\", \"ignorelist\");\r\n// img-label handler\r\nvBulletin.register_control(\"vB_UserList_Highlighter\", \"ignorelist\");\r\n//-->\r\n</script>', 'template', 1213273344, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(264, -1, 'modifyignorelist_user', '<li id=\\\"user$user[userid]\\\">\r\n	<input type=\\\"checkbox\\\" name=\\\"listbits[ignore][$user[userid]]\\\" id=\\\"usercheck_$user[userid]\\\" value=\\\"$user[userid]\\\" checked=\\\"checked\\\" /><a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$user[userid]\\\">$user[username]</a><input type=\\\"hidden\\\" name=\\\"listbits[ignore_original][$user[userid]]\\\" value=\\\"$user[userid]\\\" />\r\n</li>', '<li id=\"user$user[userid]\">\r\n	<input type=\"checkbox\" name=\"listbits[ignore][$user[userid]]\" id=\"usercheck_$user[userid]\" value=\"$user[userid]\" checked=\"checked\" /><a href=\"member.php?$session[sessionurl]u=$user[userid]\">$user[username]</a><input type=\"hidden\" name=\"listbits[ignore_original][$user[userid]]\" value=\"$user[userid]\" />\r\n</li>', 'template', 1204241120, 'vBulletin Solutions', '3.7.0 Beta 6', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(265, -1, 'modifyoptions', '<script type=\\\"text/javascript\\\">\r\n<!--\r\nfunction toggle_disabled(status, objid)\r\n{\r\n	obj = fetch_object(objid);\r\n	if (obj)\r\n	{\r\n		obj.disabled = (status ? false : true);\r\n	}\r\n}\r\n//-->\r\n</script>\r\n\r\n<form action=\\\"profile.php?do=updateoptions\\\" method=\\\"post\\\">\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"updateoptions\\\" />\r\n\r\n$template_hook[usercp_options_start]\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<thead>\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[edit_options]<span class=\\\"normal\\\">: \" . $GLOBALS[\'vbulletin\']->userinfo[\'username\'] . \"</span></td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"thead\\\">\r\n		<a style=\\\"float:$stylevar[right]\\\" href=\\\"#top\\\" onclick=\\\"return toggle_collapse(\'uopt_login\')\\\"><img id=\\\"collapseimg_uopt_login\\\" src=\\\"$stylevar[imgdir_button]/collapse_thead$vbcollapse[collapseimg_uopt_login].gif\\\" alt=\\\"\\\" border=\\\"0\\\" /></a>\r\n		$vbphrase[login_privacy]\r\n	</td>\r\n</tr>\r\n</thead>\r\n<tbody id=\\\"collapseobj_uopt_login\\\" style=\\\"$vbcollapse[collapseobj_uopt_login]\\\">\r\n	<tr>\r\n		<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n		<div class=\\\"panel\\\">\r\n			<div style=\\\"width:$stylevar[formwidth_usercp]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n				\".(($show[\'invisibleoption\']) ? (\"\r\n				<fieldset class=\\\"fieldset\\\">\r\n					<legend><label for=\\\"cb_invisible\\\">$vbphrase[use_invisible_mode]</label></legend>\r\n					<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\