(282, -1, 'modifyusergroups_displaybit', '<tr>\r\n	<td class=\\\"$bgclass\\\">\r\n		$usergroup[opentag]$usergroup[title]$usergroup[closetag]\r\n		<div class=\\\"smallfont\\\">$usergroup[description]</div>\r\n	</td>\r\n	<td class=\\\"$bgclass\\\">$usergroup[usertitle]</td>\r\n	<td class=\\\"$bgclass\\\"><span class=\\\"smallfont\\\">\r\n		<label for=\\\"rb_identify_$usergroupid\\\"><input type=\\\"radio\\\" name=\\\"usergroupid\\\" value=\\\"$usergroupid\\\" id=\\\"rb_identify_$usergroupid\\\" $checked[$usergroupid] />$vbphrase[identify_as_member_of_group]</label>\r\n	</span></td>\r\n</tr>', '<tr>\r\n	<td class=\"$bgclass\">\r\n		$usergroup[opentag]$usergroup[title]$usergroup[closetag]\r\n		<div class=\"smallfont\">$usergroup[description]</div>\r\n	</td>\r\n	<td class=\"$bgclass\">$usergroup[usertitle]</td>\r\n	<td class=\"$bgclass\"><span class=\"smallfont\">\r\n		<label for=\"rb_identify_$usergroupid\"><input type=\"radio\" name=\"usergroupid\" value=\"$usergroupid\" id=\"rb_identify_$usergroupid\" $checked[$usergroupid] />$vbphrase[identify_as_member_of_group]</label>\r\n	</span></td>\r\n</tr>', 'template', 1077053171, 'vBulletin Solutions', '', 'vbulletin'),
(283, -1, 'modifyusergroups_groupleader', '<a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$leader[userid]\\\">$leader[username]</a>', '<a href=\"member.php?$session[sessionurl]u=$leader[userid]\">$leader[username]</a>', 'template', 1069262102, 'vBulletin Solutions', '', 'vbulletin'),
(284, -1, 'modifyusergroups_joinrequestbit', '<tr>\r\n	<td class=\\\"$bgclass\\\">$joinrequest[opentag]$joinrequest[title]$joinrequest[closetag]</td>\r\n	<td class=\\\"$bgclass\\\">$joinrequest[requests] \".(($joinrequest[\'requests\']) ? (\"<span class=\\\"smallfont\\\"><a href=\\\"joinrequests.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"usergroupid=$joinrequest[usergroupid]\\\">$vbphrase[review_join_requests]</a></span>\") : (\"\")).\"</td>\r\n	<td class=\\\"$bgclass\\\"><span class=\\\"smallfont\\\"><a href=\\\"memberlist.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"usergroupid=$joinrequest[usergroupid]\\\">$vbphrase[list_members]</a></span></td>\r\n</tr>\r\n', '<tr>\r\n	<td class=\"$bgclass\">$joinrequest[opentag]$joinrequest[title]$joinrequest[closetag]</td>\r\n	<td class=\"$bgclass\">$joinrequest[requests] <if condition=\"$joinrequest[\'requests\']\"><span class=\"smallfont\"><a href=\"joinrequests.php?$session[sessionurl]usergroupid=$joinrequest[usergroupid]\">$vbphrase[review_join_requests]</a></span></if></td>\r\n	<td class=\"$bgclass\"><span class=\"smallfont\"><a href=\"memberlist.php?$session[sessionurl]usergroupid=$joinrequest[usergroupid]\">$vbphrase[list_members]</a></span></td>\r\n</tr>\r\n', 'template', 1070080815, 'vBulletin Solutions', '', 'vbulletin'),
(285, -1, 'modifyusergroups_memberbit', '<tr>\r\n	<td class=\\\"$bgclass\\\">\r\n		$usergroup[opentag]$usergroup[title]$usergroup[closetag]\r\n		<div class=\\\"smallfont\\\">$usergroup[description]</div>\r\n	</td>\r\n	<td class=\\\"$bgclass\\\">$usergroup[usertitle]</td>\r\n	<td class=\\\"$bgclass\\\"><span class=\\\"smallfont\\\">\r\n	\".(($show[\'isleader\']) ? (\"\r\n	($vbphrase[leader_of_this_group])<br />\r\n	\") : (\"\r\n	<label for=\\\"rb_leave_$usergroup[usergroupid]\\\"><input type=\\\"radio\\\" name=\\\"usergroupid\\\" id=\\\"rb_leave_$usergroup[usergroupid]\\\" value=\\\"$usergroup[usergroupid]\\\" />$vbphrase[leave_group]</label>\r\n	\")).\"\r\n	</span></td>\r\n</tr>', '<tr>\r\n	<td class=\"$bgclass\">\r\n		$usergroup[opentag]$usergroup[title]$usergroup[closetag]\r\n		<div class=\"smallfont\">$usergroup[description]</div>\r\n	</td>\r\n	<td class=\"$bgclass\">$usergroup[usertitle]</td>\r\n	<td class=\"$bgclass\"><span class=\"smallfont\">\r\n	<if condition=\"$show[\'isleader\']\">\r\n	($vbphrase[leader_of_this_group])<br />\r\n	<else />\r\n	<label for=\"rb_leave_$usergroup[usergroupid]\"><input type=\"radio\" name=\"usergroupid\" id=\"rb_leave_$usergroup[usergroupid]\" value=\"$usergroup[usergroupid]\" />$vbphrase[leave_group]</label>\r\n	</if>\r\n	</span></td>\r\n</tr>', 'template', 1121360033, 'vBulletin Solutions', '3.5.0 Release Candidate 1', 'vbulletin'),
(286, -1, 'modifyusergroups_nonmemberbit', '<tr>\r\n	<td class=\\\"$bgclass\\\">\r\n		$usergroup[opentag]$usergroup[title]$usergroup[closetag]\r\n		<div class=\\\"smallfont\\\">$usergroup[description]</div>\r\n	</td>\r\n	<td class=\\\"$bgclass\\\"><span class=\\\"smallfont\\\">\r\n	\".(($ismoderated) ? (\"\r\n		$vbphrase[requests_approved_by_leader]<br />$vbphrase[group_leaders]: $groupleaders\r\n	\") : (\"\r\n		$vbphrase[anyone_free_to_join_group]\r\n	\")).\"\r\n	</span></td>\r\n	<td class=\\\"$bgclass\\\"><span class=\\\"smallfont\\\">\r\n	\".(($joinrequested) ? (\"\r\n		\" . construct_phrase(\"$vbphrase[requested_to_join_x_at_y]\", \"$joinrequest[date]\", \"$joinrequest[time]\") . \"\r\n		\".(($joinrequest[reason]) ? (\"<br /><strong>$vbphrase[request_reason]</strong>: <em>$joinrequest[reason]</em>\") : (\"\")).\"\r\n	\") : (\"\r\n		<label for=\\\"rb_join_$usergroup[usergroupid]\\\"><input type=\\\"radio\\\" name=\\\"usergroupid\\\" id=\\\"rb_join_$usergroup[usergroupid]\\\" value=\\\"$usergroup[usergroupid]\\\" />$vbphrase[join_group]</label>\r\n	\")).\"\r\n	</span></td>\r\n</tr>', '<tr>\r\n	<td class=\"$bgclass\">\r\n		$usergroup[opentag]$usergroup[title]$usergroup[closetag]\r\n		<div class=\"smallfont\">$usergroup[description]</div>\r\n	</td>\r\n	<td class=\"$bgclass\"><span class=\"smallfont\">\r\n	<if condition=\"$ismoderated\">\r\n		$vbphrase[requests_approved_by_leader]<br />$vbphrase[group_leaders]: $groupleaders\r\n	<else />\r\n		$vbphrase[anyone_free_to_join_group]\r\n	</if>\r\n	</span></td>\r\n	<td class=\"$bgclass\"><span class=\"smallfont\">\r\n	<if condition=\"$joinrequested\">\r\n		<phrase 1=\"$joinrequest[date]\" 2=\"$joinrequest[time]\">$vbphrase[requested_to_join_x_at_y]</phrase>\r\n		<if condition=\"$joinrequest[reason]\"><br /><strong>$vbphrase[request_reason]</strong>: <em>$joinrequest[reason]</em></if>\r\n	<else />\r\n		<label for=\"rb_join_$usergroup[usergroupid]\"><input type=\"radio\" name=\"usergroupid\" id=\"rb_join_$usergroup[usergroupid]\" value=\"$usergroup[usergroupid]\" />$vbphrase[join_group]</label>\r\n	</if>\r\n	</span></td>\r\n</tr>', 'template', 1121360039, 'vBulletin Solutions', '3.5.0 Release Candidate 1', 'vbulletin'),
(287, -1, 'modifyusergroups_requesttojoin', '<form action=\\\"profile.php?do=insertjoinrequest&amp;usergroupid=$usergroupid\\\" method=\\\"post\\\" onsubmit=\\\"return validatemessage(this.reason.value, 0, 0, 250, 0);\\\">\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"insertjoinrequest\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"usergroupid\\\" value=\\\"$usergroupid\\\" />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[request_to_join_group]<span class=\\\"normal\\\">: $usergroup[title]</span></td>\r\n</tr>\r\n\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth_usercp]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n		<fieldset class=\\\"fieldset\\\">\r\n			<legend>$vbphrase[join_request]</legend>\r\n			<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n			<tr>\r\n				<td>$vbphrase[reason_for_request]</td>\r\n			</tr>\r\n			<tr>\r\n				<td>\r\n					<div>$vbphrase[request_reason]:</div>\r\n					<div><input type=\\\"text\\\" name=\\\"reason\\\" value=\\\"\\\" maxlength=\\\"250\\\" size=\\\"50\\\" tabindex=\\\"1\\\" /></div>\r\n				</td>\r\n			</tr>\r\n			<tr>\r\n				<td>\r\n					<div>\" . construct_phrase(\"$vbphrase[request_to_join_x__moderated_by_leaders]\", \"$usergroup[title]\") . \":</div>\r\n					<div>$groupleaders</div>\r\n				</td>\r\n			</tr>\r\n			</table>\r\n		</fieldset>\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[send_request]\\\" accesskey=\\\"s\\\" tabindex=\\\"1\\\" />\r\n		<input type=\\\"reset\\\" class=\\\"button\\\" value=\\\"$vbphrase[reset_fields]\\\" accesskey=\\\"r\\\" tabindex=\\\"1\\\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>', '<form action=\"profile.php?do=insertjoinrequest&amp;usergroupid=$usergroupid\" method=\"post\" onsubmit=\"return validatemessage(this.reason.value, 0, 0, 250, 0);\">\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n<input type=\"hidden\" name=\"do\" value=\"insertjoinrequest\" />\r\n<input type=\"hidden\" name=\"usergroupid\" value=\"$usergroupid\" />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">$vbphrase[request_to_join_group]<span class=\"normal\">: $usergroup[title]</span></td>\r\n</tr>\r\n\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth_usercp]\" align=\"$stylevar[left]\">\r\n\r\n		<fieldset class=\"fieldset\">\r\n			<legend>$vbphrase[join_request]</legend>\r\n			<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n			<tr>\r\n				<td>$vbphrase[reason_for_request]</td>\r\n			</tr>\r\n			<tr>\r\n				<td>\r\n					<div>$vbphrase[request_reason]:</div>\r\n					<div><input type=\"text\" name=\"reason\" value=\"\" maxlength=\"250\" size=\"50\" tabindex=\"1\" /></div>\r\n				</td>\r\n			</tr>\r\n			<tr>\r\n				<td>\r\n					<div><phrase 1=\"$usergroup[title]\">$vbphrase[request_to_join_x__moderated_by_leaders]</phrase>:</div>\r\n					<div>$groupleaders</div>\r\n				</td>\r\n			</tr>\r\n			</table>\r\n		</fieldset>\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"submit\" class=\"button\" value=\"$vbphrase[send_request]\" accesskey=\"s\" tabindex=\"1\" />\r\n		<input type=\"reset\" class=\"button\" value=\"$vbphrase[reset_fields]\" accesskey=\"r\" tabindex=\"1\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>', 'template', 1208876305, 'vBulletin Solutions', '3.7.0 Release Candidate 4', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(288, -1, 'modifyuserlist_confirm', '<form action=\\\"profile.php?do=$action&amp;list=$list&amp;userid=$userid\\\" method=\\\"post\\\">\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"$action\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"userlist\\\" value=\\\"$userlist\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"userid\\\" value=\\\"$userid\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"url\\\" value=\\\"$url\\\" />\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[confirm_user_list_modification]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div class=\\\"smallfont\\\" style=\\\"width:$stylevar[formwidth_usercp]\\\" align=\\\"$stylevar[left]\\\">\r\n			\" . construct_phrase(\"$vbphrase[$confirm_phrase]\", \"$userinfo[username]\") . \"\r\n			\".(($show[\'friend_checkbox\']) ? (\"<div style=\\\"margin-top:1em\\\"><label for=\\\"also\\\"><input type=\\\"checkbox\\\" name=\\\"friend\\\" id=\\\"also\\\" value=\\\"1\\\"$friend_checked />\" . construct_phrase(\"$vbphrase[$supplemental_phrase]\", \"$userinfo[username]\") . \"</label></div>\") : (\"\")).\"\r\n			\".(($show[\'hiddenfriend\']) ? (\"<input type=\\\"hidden\\\" name=\\\"friend\\\" value=\\\"1\\\" />\") : (\"\")).\"\r\n		</div>\r\n	</div>\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[yes]\\\" name=\\\"confirm\\\" accesskey=\\\"s\\\" />\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[no]\\\" name=\\\"deny\\\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n</form>', '<form action=\"profile.php?do=$action&amp;list=$list&amp;userid=$userid\" method=\"post\">\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n<input type=\"hidden\" name=\"do\" value=\"$action\" />\r\n<input type=\"hidden\" name=\"userlist\" value=\"$userlist\" />\r\n<input type=\"hidden\" name=\"userid\" value=\"$userid\" />\r\n<input type=\"hidden\" name=\"url\" value=\"$url\" />\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">$vbphrase[confirm_user_list_modification]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div class=\"smallfont\" style=\"width:$stylevar[formwidth_usercp]\" align=\"$stylevar[left]\">\r\n			<phrase 1=\"$userinfo[username]\">$vbphrase[$confirm_phrase]</phrase>\r\n			<if condition=\"$show[\'friend_checkbox\']\"><div style=\"margin-top:1em\"><label for=\"also\"><input type=\"checkbox\" name=\"friend\" id=\"also\" value=\"1\"$friend_checked /><phrase 1=\"$userinfo[username]\">$vbphrase[$supplemental_phrase]</phrase></label></div></if>\r\n			<if condition=\"$show[\'hiddenfriend\']\"><input type=\"hidden\" name=\"friend\" value=\"1\" /></if>\r\n		</div>\r\n	</div>\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"submit\" class=\"button\" value=\"$vbphrase[yes]\" name=\"confirm\" accesskey=\"s\" />\r\n		<input type=\"submit\" class=\"button\" value=\"$vbphrase[no]\" name=\"deny\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n</form>', 'template', 1208880910, 'vBulletin Solutions', '3.7.0 Release Candidate 4', 'vbulletin'),
(289, -1, 'modifyuserlist_headinclude', '<style type=\\\"text/css\\\" id=\\\"vbulletin_user_list_editor_css\\\">\r\n<!--\r\nfieldset form, div.fieldsetpad { display:block; padding:6px; }\r\n\r\n.userlist_title { font-weight:bold; }\r\n.userlist_description { margin-bottom:6px; }\r\n\r\n.avatar_toggle { text-align:$stylevar[right]; }\r\n\r\ndiv.checkbox_ctrls { margin-bottom:6px; }\r\nlabel.show_avatars_ctrl { float:$stylevar[left]; }\r\nlabel.check_all_ctrl { float:$stylevar[right]; }\r\n\r\ndiv.submitrow { text-align:$stylevar[right]; }\r\ndiv.submitrow #incomingreqs_action { float:$stylevar[left]; text-align:$stylevar[left]; }\r\n\r\n.userlist_error { display:none; }\r\n.userlist_error_image { float:$stylevar[left]; margin-$stylevar[right]:6px; margin-bottom:6px; }\r\n\r\nul.userlist { list-style:none; padding:0px; margin:0px; }\r\nul.userlist li { float:$stylevar[left]; margin-$stylevar[right]:6px; margin-bottom:6px; width:175px; }\r\nul.userlist hr { display:none; }\r\n\r\n/* avatars shown */\r\nul.userlist_showavatars li { position:relative; width:215px; height:80px; border:solid 1px silver; padding:4px; }\r\nul.userlist_showavatars div.username a { padding-$stylevar[left]:6px; vertical-align:top; font-weight:bold; }\r\n\".((is_browser(\'firefox\') AND !is_browser(\'firefox\', 3) AND $stylevar[\'textdirection\'] == \'rtl\') ? (\"\r\n	ul.userlist_showavatars div.username a { padding-$stylevar[left]:0px; }\r\n\") : (\"\")).\"\r\nul.userlist_showavatars div.username input { position:absolute; $stylevar[left]:4px; top:4px; }\r\nul.userlist_showavatars div.friend label { position:absolute; $stylevar[right]:4px; bottom:4px; }\r\n\r\n/* avatars hidden */\r\nul.userlist_hideavatars li { position:relative; width:215px; border:solid 1px silver; padding:4px; }\r\nul.userlist_hideavatars label.avatar_label img { display:none; }\r\nul.userlist_hideavatars div.username a { font-weight:bold; }\r\n\r\n/* filterbox */\r\ninput#userlist_filter {\r\n	float:$stylevar[right];\r\n	width:150px;\r\n	height:1.3em;\r\n	padding-$stylevar[left]:16px;\r\n	background-image:url($stylevar[imgdir_misc]/magnifier.png);\r\n	background-position:left;\r\n	background-repeat:no-repeat;\r\n	display:none;\r\n}\r\ninput#userlist_filter.filterbox_inactive { color:silver; font-style:italic; }\r\n-->\r\n</style>', '<style type=\"text/css\" id=\"vbulletin_user_list_editor_css\">\r\n<!--\r\nfieldset form, div.fieldsetpad { display:block; padding:6px; }\r\n\r\n.userlist_title { font-weight:bold; }\r\n.userlist_description { margin-bottom:6px; }\r\n\r\n.avatar_toggle { text-align:$stylevar[right]; }\r\n\r\ndiv.checkbox_ctrls { margin-bottom:6px; }\r\nlabel.show_avatars_ctrl { float:$stylevar[left]; }\r\nlabel.check_all_ctrl { float:$stylevar[right]; }\r\n\r\ndiv.submitrow { text-align:$stylevar[right]; }\r\ndiv.submitrow #incomingreqs_action { float:$stylevar[left]; text-align:$stylevar[left]; }\r\n\r\n.userlist_error { display:none; }\r\n.userlist_error_image { float:$stylevar[left]; margin-$stylevar[right]:6px; margin-bottom:6px; }\r\n\r\nul.userlist { list-style:none; padding:0px; margin:0px; }\r\nul.userlist li { float:$stylevar[left]; margin-$stylevar[right]:6px; margin-bottom:6px; width:175px; }\r\nul.userlist hr { display:none; }\r\n\r\n/* avatars shown */\r\nul.userlist_showavatars li { position:relative; width:215px; height:80px; border:solid 1px silver; padding:4px; }\r\nul.userlist_showavatars div.username a { padding-$stylevar[left]:6px; vertical-align:top; font-weight:bold; }\r\n<if condition=\"is_browser(\'firefox\') AND !is_browser(\'firefox\', 3) AND $stylevar[\'textdirection\'] == \'rtl\'\">\r\n	ul.userlist_showavatars div.username a { padding-$stylevar[left]:0px; }\r\n</if>\r\nul.userlist_showavatars div.username input { position:absolute; $stylevar[left]:4px; top:4px; }\r\nul.userlist_showavatars div.friend label { position:absolute; $stylevar[right]:4px; bottom:4px; }\r\n\r\n/* avatars hidden */\r\nul.userlist_hideavatars li { position:relative; width:215px; border:solid 1px silver; padding:4px; }\r\nul.userlist_hideavatars label.avatar_label img { display:none; }\r\nul.userlist_hideavatars div.username a { font-weight:bold; }\r\n\r\n/* filterbox */\r\ninput#userlist_filter {\r\n	float:$stylevar[right];\r\n	width:150px;\r\n	height:1.3em;\r\n	padding-$stylevar[left]:16px;\r\n	background-image:url($stylevar[imgdir_misc]/magnifier.png);\r\n	background-position:left;\r\n	background-repeat:no-repeat;\r\n	display:none;\r\n}\r\ninput#userlist_filter.filterbox_inactive { color:silver; font-style:italic; }\r\n-->\r\n</style>', 'template', 1216986311, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(290, -1, 'navbar', '<br />\r\n\r\n<!-- breadcrumb, login, pm info -->\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"alt1\\\" width=\\\"100%\\\">\r\n		\".((is_array($navbits)) ? (\"\r\n			<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\">\r\n			<tr valign=\\\"bottom\\\">\r\n				<td><a href=\\\"#\\\" onclick=\\\"history.back(1); return false;\\\"><img src=\\\"$stylevar[imgdir_misc]/navbits_start.gif\\\" alt=\\\"$vbphrase[go_back]\\\" border=\\\"0\\\" /></a></td>\r\n				<td>&nbsp;</td>\r\n				<td width=\\\"100%\\\"><span class=\\\"navbar\\\"><a href=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'forumhome\'] . \".php\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl_q\'] . \"\\\" accesskey=\\\"1\\\">\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \"</a></span> $navbits[breadcrumb]</td>\r\n			</tr>\r\n			<tr>\r\n				<td class=\\\"navbar\\\" style=\\\"font-size:10pt; padding-top:1px\\\" colspan=\\\"3\\\">\".(($_SERVER[\'REQUEST_METHOD\'] == \'POST\') ? (\"<img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_misc]/navbits_finallink_$stylevar[textdirection].gif\\\" alt=\\\"\\\" border=\\\"0\\\" />\") : (\"<a href=\\\"\" . $GLOBALS[\'vbulletin\']->reloadurl . \"\\\"><img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_misc]/navbits_finallink_$stylevar[textdirection].gif\\\" alt=\\\"$vbphrase[reload_this_page]\\\" border=\\\"0\\\" /></a>\")).\" <strong>$navbits[lastelement]</strong></td>\r\n			</tr>\r\n			</table>\r\n		\") : (\"\r\n			<div class=\\\"navbar\\\" style=\\\"font-size:10pt\\\"><a href=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'forumhome\'] . \".php\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl_q\'] . \"\\\" accesskey=\\\"1\\\"><img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_misc]/navbits_start.gif\\\" alt=\\\"\\\" border=\\\"0\\\" /></a> <strong>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \"</strong></div>\r\n		\")).\"\r\n	</td>\r\n\".(($show[\'member\']) ? (\"\r\n	<td class=\\\"alt2\\\" nowrap=\\\"nowrap\\\">\r\n	<div class=\\\"smallfont\\\">\r\n		<strong>\" . construct_phrase(\"$vbphrase[welcome_x_link_y]\", \"\" . $GLOBALS[\'vbulletin\']->userinfo[\'username\'] . \"\", \"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=\" . $GLOBALS[\'vbulletin\']->userinfo[\'userid\'] . \"\") . \"</strong><br />\r\n		\" . construct_phrase(\"$vbphrase[last_visited_x_at_y]\", \"$pmbox[lastvisitdate]\", \"$pmbox[lastvisittime]\") . \"\r\n\r\n		\".(($show[\'notifications\']) ? (\"\r\n			<div><span id=\\\"notifications\\\"><a href=\\\"usercp.php\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl_q\'] . \"\\\">$vbphrase[your_notifications]:</a> <strong>$notifications_total</strong></span></div>\r\n			\".(($show[\'popups\']) ? (\"\r\n				<script type=\\\"text/javascript\\\"> vBmenu.register(\\\"notifications\\\"); </script>\r\n			\") : (\"\r\n				<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_notifications_nopopups.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n				<script type=\\\"text/javascript\\\"> vBulletin.register_control(\\\"vB_Notifications_NoPopups\\\", \\\"notifications\\\");  </script>\r\n			\")).\"\r\n		\") : (\"\".(($show[\'pmstats\']) ? (\"\r\n			<div>\" . construct_phrase(\"$vbphrase[private_messages_nav]\", \"$vbphrase[unread_x_nav_compiled]\", \"$vbphrase[total_x_nav_compiled]\", \"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl_q\'] . \"\") . \"</div>\r\n		\") : (\"\")).\"\")).\"\r\n\r\n		\".(($show[\'pmwarning\']) ? (\"<div><strong>\" . construct_phrase(\"$vbphrase[your_pm_box_is_x_full]\", \"$vbphrase[pmpercent_nav_compiled]\") . \"</strong></div>\") : (\"\")).\"\r\n	</div>\r\n	</td>\r\n\") : (\"\r\n	<td class=\\\"alt2\\\" nowrap=\\\"nowrap\\\" style=\\\"padding:0px\\\">\r\n		<!-- login form -->\r\n		<form action=\\\"login.php?do=login\\\" method=\\\"post\\\" onsubmit=\\\"md5hash(vb_login_password, vb_login_md5password, vb_login_md5password_utf, $show[nopasswordempty])\\\">\r\n		<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_md5.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n		<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n		<tr>\r\n			<td class=\\\"smallfont\\\" style=\\\"white-space: nowrap;\\\"><label for=\\\"navbar_username\\\">$vbphrase[username]</label></td>\r\n			<td><input type=\\\"text\\\" class=\\\"bginput\\\" style=\\\"font-size: 11px\\\" name=\\\"vb_login_username\\\" id=\\\"navbar_username\\\" size=\\\"10\\\" accesskey=\\\"u\\\" tabindex=\\\"101\\\" value=\\\"$vbphrase[username]\\\" onfocus=\\\"if (this.value == \'$vbphrase[username]\') this.value = \'\';\\\" /></td>\r\n			<td class=\\\"smallfont\\\" nowrap=\\\"nowrap\\\"><label for=\\\"cb_cookieuser_navbar\\\"><input type=\\\"checkbox\\\" name=\\\"cookieuser\\\" value=\\\"1\\\" tabindex=\\\"103\\\" id=\\\"cb_cookieuser_navbar\\\" accesskey=\\\"c\\\" />$vbphrase[remember_me]</label></td>\r\n		</tr>\r\n		<tr>\r\n			<td class=\\\"smallfont\\\"><label for=\\\"navbar_password\\\">$vbphrase[password]</label></td>\r\n			<td><input type=\\\"password\\\" class=\\\"bginput\\\" style=\\\"font-size: 11px\\\" name=\\\"vb_login_password\\\" id=\\\"navbar_password\\\" size=\\\"10\\\" tabindex=\\\"102\\\" /></td>\r\n			<td><input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[log_in]\\\" tabindex=\\\"104\\\" title=\\\"$vbphrase[enter_username_to_login_or_register]\\\" accesskey=\\\"s\\\" /></td>\r\n		</tr>\r\n		</table>\r\n		<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n		<input type=\\\"hidden\\\" 