dset\\\">\r\n					<legend>$vbphrase[miscellaneous_options]</legend>\r\n					<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n						\".(($show[\'parseurl\']) ? (\"<div><label for=\\\"cb_parseurl\\\"><input type=\\\"checkbox\\\" name=\\\"parseurl\\\" value=\\\"1\\\" id=\\\"cb_parseurl\\\" tabindex=\\\"1\\\" $checked[parseurl] />$vbphrase[automatically_parse_links_in_text]</label></div>\") : (\"\")).\"\r\n						$disablesmiliesoption\r\n					</div>\r\n				</fieldset>\r\n				\") : (\"\")).\"\r\n			</div>\r\n		</div>\r\n\r\n		<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		\".(($show[\'edit\']) ? (\"\r\n			<input type=\\\"submit\\\" class=\\\"button\\\" name=\\\"sbutton\\\" id=\\\"{$editorid}_save\\\" value=\\\"$vbphrase[save_changes]\\\" accesskey=\\\"s\\\" tabindex=\\\"1\\\" />\r\n			<input type=\\\"submit\\\" class=\\\"button\\\" name=\\\"preview\\\" value=\\\"$vbphrase[preview_message]\\\" accesskey=\\\"r\\\" tabindex=\\\"1\\\" />\r\n		\") : (\"\r\n			<input type=\\\"submit\\\" class=\\\"button\\\" name=\\\"sbutton\\\" id=\\\"{$editorid}_save\\\" value=\\\"$vbphrase[post_comment]\\\" accesskey=\\\"s\\\" tabindex=\\\"1\\\" />\r\n			<input type=\\\"submit\\\" class=\\\"button\\\" name=\\\"preview\\\" value=\\\"$vbphrase[preview]\\\" accesskey=\\\"r\\\" tabindex=\\\"1\\\" />\r\n		\")).\"\r\n		</div>\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n</table>\r\n\") : (\"\")).\"\r\n\r\n</form>\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n<title>$vboptions[bbtitle] - $pagetitle</title>\r\n</head>\r\n<body>\r\n$header\r\n\r\n$navbar\r\n\r\n<if condition=\"$show[\'delete\']\">\r\n<form action=\"picturecomment.php?do=deletemessage&amp;commentid=$commentinfo[commentid]\" method=\"post\">\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n<input type=\"hidden\" name=\"do\" value=\"deletemessage\" />\r\n<input type=\"hidden\" name=\"pictureid\" value=\"$pictureinfo[pictureid]\" />\r\n<input type=\"hidden\" name=\"albumid\" value=\"$pictureinfo[albumid]\" />\r\n<input type=\"hidden\" name=\"groupid\" value=\"$pictureinfo[groupid]\" />\r\n<input type=\"hidden\" name=\"commentid\" value=\"$commentinfo[commentid]\" />\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		<a style=\"float:$stylevar[right]\" href=\"#top\" onclick=\"return toggle_collapse(\'editpost_delete\')\"><img id=\"collapseimg_editpost_delete\" src=\"$stylevar[imgdir_button]/collapse_tcat$vbcollapse[collapseimg_editpost_delete].gif\" alt=\"\" border=\"0\" /></a>\r\n		$vbphrase[delete_message]\r\n	</td>\r\n</tr>\r\n<tbody id=\"collapseobj_editpost_delete\" style=\"$vbcollapse[collapseobj_editpost_delete]\">\r\n	<tr>\r\n		<td class=\"panelsurround\" align=\"center\">\r\n		<div class=\"panel\">\r\n			<div align=\"$stylevar[left]\" style=\"max-width:$stylevar[formwidth]; width:auto !important; width:$stylevar[formwidth_usercp]\">\r\n\r\n			<div class=\"fieldset\">$vbphrase[delete_message_check_appropriate_option]</div>\r\n\r\n			<fieldset class=\"fieldset\">\r\n				<legend>$vbphrase[deletion_options]</legend>\r\n				<div style=\"padding:$stylevar[formspacer]px\">\r\n					<div>\r\n						<label for=\"rb_del_leave\"><input type=\"radio\" name=\"deletemessage\" value=\"\" id=\"rb_del_leave\" tabindex=\"1\" checked=\"checked\" />$vbphrase[do_not_delete_message]</label>\r\n					</div>\r\n					<div>\r\n						<label for=\"rb_del_soft\"><input type=\"radio\" name=\"deletemessage\" value=\"soft\" id=\"rb_del_soft\" tabindex=\"1\" />$vbphrase[delete_message]</label>\r\n					</div>\r\n					<if condition=\"$show[\'physicaldeleteoption\']\">\r\n					<div>\r\n						<label for=\"rb_del_hard\"><input type=\"radio\" name=\"deletemessage\" value=\"remove\" id=\"rb_del_hard\" tabindex=\"1\" />$vbphrase[physically_remove_message]</label>\r\n					</div>\r\n					</if>\r\n				</div>\r\n			</fieldset>\r\n\r\n			<div class=\"smallfont\">\r\n				<div>$vbphrase[reason_for_deletion]:</div>\r\n				<input type=\"text\" class=\"bginput\" name=\"reason\" size=\"50\" tabindex=\"1\" title=\"$vbphrase[optional]\" />\r\n			</div>\r\n\r\n			</div>\r\n		</div>\r\n\r\n		<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n			<input type=\"submit\" class=\"button\" value=\"$vbphrase[delete]\" tabindex=\"1\" accesskey=\"d\" />\r\n		</div>\r\n\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n</table>\r\n</form>\r\n<br />\r\n</if>\r\n\r\n$postpreview\r\n\r\n<form action=\"picturecomment.php?do=message\" name=\"vbform\" method=\"post\"<if condition=\"!is_browser(\'webtv\')\"> onsubmit=\"return vB_Editor[\'$editorid\'].prepare_submit(0, $vboptions[postminchars])\"</if>>\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		<if condition=\"$show[\'edit\']\">\r\n			<span class=\"smallfont\" style=\"float:$stylevar[right]\"><strong>$vbphrase[user]</strong>: <a href=\"member.php?$session[sessionurl]u=$albuminfo[userid]\">$albuminfo[username]</a></span>\r\n			$vbphrase[edit_picture_comment]\r\n		<else />\r\n			$vbphrase[post_new_picture_comment]\r\n		</if>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div align=\"$stylevar[left]\" style=\"max-width:$stylevar[formwidth]; width:auto !important; width:$stylevar[formwidth_usercp]\">\r\n\r\n		$usernamecode\r\n\r\n		<!-- message area -->\r\n		<div class=\"smallfont\">$vbphrase[comment]:</div>\r\n		$messagearea\r\n		<!-- / message area -->\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n		<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n		<input type=\"hidden\" name=\"do\" value=\"message\" />\r\n		<input type=\"hidden\" name=\"pictureid\" value=\"$pictureinfo[pictureid]\" />\r\n		<input type=\"hidden\" name=\"albumid\" value=\"$pictureinfo[albumid]\" />\r\n		<input type=\"hidden\" name=\"groupid\" value=\"$pictureinfo[groupid]\" />\r\n		<input type=\"hidden\" name=\"commentid\" value=\"$commentinfo[commentid]\" />\r\n		<input type=\"hidden\" name=\"posthash\" value=\"$posthash\" />\r\n		<input type=\"hidden\" name=\"loggedinuser\" value=\"$bbuserinfo[userid]\" />\r\n		<input type=\"hidden\" name=\"u\" value=\"$userinfo[userid]\" />\r\n		<if condition=\"$show[\'edit\']\">\r\n			<input type=\"submit\" class=\"button\" name=\"sbutton\" id=\"{$editorid}_save\" value=\"$vbphrase[save_changes]\" accesskey=\"s\" tabindex=\"1\" />\r\n			<input type=\"submit\" class=\"button\" name=\"preview\" value=\"$vbphrase[preview_message]\" accesskey=\"r\" tabindex=\"1\" />\r\n		<else />\r\n			<input type=\"submit\" class=\"button\" name=\"sbutton\" id=\"{$editorid}_save\" value=\"$vbphrase[post_comment]\" accesskey=\"s\" tabindex=\"1\" />\r\n			<input type=\"submit\" class=\"button\" name=\"preview\" value=\"$vbphrase[preview]\" accesskey=\"r\" tabindex=\"1\" />\r\n		</if>\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<if condition=\"$show[\'additional_options\']\">\r\n<br />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<thead>\r\n	<tr>\r\n		<td class=\"tcat\">\r\n			<a style=\"float:$stylevar[right]\" href=\"#top\" onclick=\"return toggle_collapse(\'newpost_options\')\"><img id=\"collapseimg_newpost_options\" src=\"$stylevar[imgdir_button]/collapse_tcat$vbcollapse[collapseimg_newpost_options].gif\" alt=\"\" border=\"0\" /></a>\r\n			$vbphrase[additional_options]\r\n		</td>\r\n	</tr>\r\n</thead>\r\n<tbody id=\"collapseobj_newpost_options\" style=\"$vbcollapse[collapseobj_newpost_options]\">\r\n	<tr valign=\"top\">\r\n		<td class=\"panelsurround\" align=\"center\">\r\n		<div class=\"panel\">\r\n			<div align=\"$stylevar[left]\" style=\"width:$stylevar[formwidth]\">\r\n\r\n				<if condition=\"$show[\'misc_options\']\">\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[miscellaneous_options]</legend>\r\n					<div style=\"padding:$stylevar[formspacer]px\">\r\n						<if condition=\"$show[\'parseurl\']\"><div><label for=\"cb_parseurl\"><input type=\"checkbox\" name=\"parseurl\" value=\"1\" id=\"cb_parseurl\" tabindex=\"1\" $checked[parseurl] />$vbphrase[automatically_parse_links_in_text]</label></div></if>\r\n						$disablesmiliesoption\r\n					</div>\r\n				</fieldset>\r\n				</if>\r\n			</div>\r\n		</div>\r\n\r\n		<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<if condition=\"$show[\'edit\']\">\r\n			<input type=\"submit\" class=\"button\" name=\"sbutton\" id=\"{$editorid}_save\" value=\"$vbphrase[save_changes]\" accesskey=\"s\" tabindex=\"1\" />\r\n			<input type=\"submit\" class=\"button\" name=\"preview\" value=\"$vbphrase[preview_message]\" accesskey=\"r\" tabindex=\"1\" />\r\n		<else />\r\n			<input type=\"submit\" class=\"button\" name=\"sbutton\" id=\"{$editorid}_save\" value=\"$vbphrase[post_comment]\" accesskey=\"s\" tabindex=\"1\" />\r\n			<input type=\"submit\" class=\"button\" name=\"preview\" value=\"$vbphrase[preview]\" accesskey=\"r\" tabindex=\"1\" />\r\n		</if>\r\n		</div>\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n</table>\r\n</if>\r\n\r\n</form>\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', 'template', 1208876440, 'vBulletin Solutions', '3.7.0 Release Candidate 4', 'vbulletin'),
(320, -1, 'picturecomment_form', '\".(($show[\'quickcomment\']) ? (\"\r\n	$vBeditTemplate[clientscript]\r\n\r\n	<div class=\\\"alt1 smallfont block_row\\\">\r\n	<form action=\\\"picturecomment.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=message\\\" method=\\\"post\\\" id=\\\"message_form\\\">\r\n	<div align=\\\"center\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\">\r\n			<div style=\\\"display:none\\\" id=\\\"qc_error_div\\\" class=\\\"tborder\\\">\r\n				<div class=\\\"alt1 block_title\\\">\r\n					<div id=\\\"qc_error_header\\\">$vbphrase[errors_occured_when_submitted]</div>\r\n					<div id=\\\"qc_error_list\\\">&nbsp;</div>\r\n					<div id=\\\"qc_error_okay\\\"><input type=\\\"button\\\" class=\\\"button\\\" value=\\\"$vbphrase[okay]\\\" id=\\\"qc_hide_errors\\\" /></div>\r\n				</div>\r\n			</div>\r\n\r\n			<div class=\\\"smallfont messagetext\\\">\r\n				$vbphrase[comment]:\r\n				<span class=\\\"shade\\\">$vbphrase[note_comment_may_be_visible_locations]</span>\r\n			</div>\r\n			<div id=\\\"$editorid\\\" class=\\\"vBulletin_editor\\\">$messagearea</div>\r\n			\".(($allowed_bbcode) ? (\"<div class=\\\"allowed_bbcode\\\">$allowed_bbcode</div>\") : (\"\")).\"\r\n			<div class=\\\"submit_button\\\">\r\n				<input type=\\\"hidden\\\" name=\\\"fromquickcomment\\\" value=\\\"1\\\" />\r\n				<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n				<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n				<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"message\\\" />\r\n				<input type=\\\"hidden\\\" name=\\\"pictureid\\\" value=\\\"$pictureinfo[pictureid]\\\" />\r\n				<input type=\\\"hidden\\\" name=\\\"albumid\\\" value=\\\"$albuminfo[albumid]\\\" />\r\n				<input type=\\\"hidden\\\" name=\\\"groupid\\\" value=\\\"$group[groupid]\\\" />\r\n				<input type=\\\"hidden\\\" name=\\\"loggedinuser\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'userid\'] . \"\\\" />\r\n				<input type=\\\"hidden\\\" name=\\\"parseurl\\\" value=\\\"1\\\" />\r\n				<input type=\\\"hidden\\\" name=\\\"lastcomment\\\" value=\\\"$messagestats[lastcomment]\\\" />\r\n				<input type=\\\"hidden\\\" name=\\\"allow_ajax_qc\\\" value=\\\"$show[allow_ajax_qc]\\\" />\r\n\r\n				<input type=\\\"submit\\\" id=\\\"qr_submit\\\" value=\\\"$vbphrase[post_comment]\\\" name=\\\"sbutton\\\" class=\\\"button\\\" accesskey=\\\"s\\\" onclick=\\\"clickedelm = this.value\\\" />\r\n						<input type=\\\"submit\\\" id=\\\"qr_preview\\\" value=\\\"$vbphrase[go_advanced]\\\" name=\\\"preview\\\" class=\\\"button\\\" accesskey=\\\"x\\\" onclick=\\\"clickedelm = this.value\\\" />\r\n			</div>\r\n		</div>\r\n	</div>\r\n\r\n	<div align=\\\"center\\\" id=\\\"qc_posting_msg\\\" style=\\\"display:none; margin-top:$stylevar[cellpadding]px\\\">\r\n		<img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_misc]/progress.gif\\\" alt=\\\"$vbphrase[posting_comment] - $vbphrase[please_wait]\\\" />\r\n		<strong>$vbphrase[posting_message_please_wait]</strong>\r\n	</div>\r\n	</form>\r\n</div>\r\n\") : (\"\")).\"\r\n', '<if condition=\"$show[\'quickcomment\']\">\r\n	$vBeditTemplate[clientscript]\r\n\r\n	<div class=\"alt1 smallfont block_row\">\r\n	<form action=\"picturecomment.php?$session[sessionurl]do=message\" method=\"post\" id=\"message_form\">\r\n	<div align=\"center\">\r\n		<div style=\"width:$stylevar[formwidth]\">\r\n			<div style=\"display:none\" id=\"qc_error_div\" class=\"tborder\">\r\n				<div class=\"alt1 block_title\">\r\n					<div id=\"qc_error_header\">$vbphrase[errors_occured_when_submitted]</div>\r\n					<div id=\"qc_error_list\">&nbsp;</div>\r\n					<div id=\"qc_error_okay\"><input type=\"button\" class=\"button\" value=\"$vbphrase[okay]\" id=\"qc_hide_errors\" /></div>\r\n				</div>\r\n			</div>\r\n\r\n			<div class=\"smallfont messagetext\">\r\n				$vbphrase[comment]:\r\n				<span class=\"shade\">$vbphrase[note_comment_may_be_visible_locations]</span>\r\n			</div>\r\n			<div id=\"$editorid\" class=\"vBulletin_editor\">$messagearea</div>\r\n			<if condition=\"$allowed_bbcode\"><div class=\"allowed_bbcode\">$allowed_bbcode</div></if>\r\n			<div class=\"submit_button\">\r\n				<input type=\"hidden\" name=\"fromquickcomment\" value=\"1\" />\r\n				<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n				<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n				<input type=\"hidden\" name=\"do\" value=\"message\" />\r\n				<input type=\"hidden\" name=\"pictureid\" value=\"$pictureinfo[pictureid]\" />\r\n				<input type=\"hidden\" name=\"albumid\" value=\"$albuminfo[albumid]\" />\r\n				<input type=\"hidden\" name=\"groupid\" value=\"$group[groupid]\" />\r\n				<input type=\"hidden\" name=\"loggedinuser\" value=\"$bbuserinfo[userid]\" />\r\n				<input type=\"hidden\" name=\"parseurl\" value=\"1\" />\r\n				<input type=\"hidden\" name=\"lastcomment\" value=\"$messagestats[lastcomment]\" />\r\n				<input type=\"hidden\" name=\"allow_ajax_qc\" value=\"$show[allow_ajax_qc]\" />\r\n\r\n				<input type=\"submit\" id=\"qr_submit\" value=\"$vbphrase[post_comment]\" name=\"sbutton\" class=\"button\" accesskey=\"s\" onclick=\"clickedelm = this.value\" />\r\n						<input type=\"submit\" id=\"qr_preview\" value=\"$vbphrase[go_advanced]\" name=\"preview\" class=\"button\" accesskey=\"x\" onclick=\"clickedelm = this.value\" />\r\n			</div>\r\n		</div>\r\n	</div>\r\n\r\n	<div align=\"center\" id=\"qc_posting_msg\" style=\"display:none; margin-top:$stylevar[cellpadding]px\">\r\n		<img class=\"inlineimg\" src=\"$stylevar[imgdir_misc]/progress.gif\" alt=\"$vbphrase[posting_comment] - $vbphrase[please_wait]\" />\r\n		<strong>$vbphrase[posting_message_please_wait]</strong>\r\n	</div>\r\n	</form>\r\n</div>\r\n</if>\r\n', 'template', 1209736605, 'vBulletin Solutions', '3.7.1', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(321, -1, 'picturecomment_message', '<li id=\\\"picturecomment$message[commentid]\\\" class=\\\"floatcontainer\\\">\r\n	\".(($message[\'avatarurl\']) ? (\"\r\n		<div class=\\\"fixed_width_avatar\\\">\r\n			\".(($message[\'postuserid\']) ? (\"<a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$message[postuserid]\\\">\") : (\"\")).\"<img src=\\\"$message[avatarurl]\\\" class=\\\"alt2 avatar\\\"\".(($message[\'avatarwidth\']) ? (\" width=\\\"$message[avatarwidth]\\\"\") : (\"\")).\"\".(($message[\'avatarheight\']) ? (\" height=\\\"$message[avatarheight]\\\"\") : (\"\")).\" border=\\\"0\\\" alt=\\\"$message[username]\\\" />\".(($message[\'postuserid\']) ? (\"</a>\") : (\"\")).\"\r\n		</div>\r\n		<div class=\\\"message_avatar_margin\\\">\r\n	\") : (\"\")).\"\r\n	<div class=\\\"tborder info_bar\\\">\r\n		<div class=\\\"alt2 smallfont\\\">\r\n			\".(($show[\'inlinemod\']) ? (\"<input type=\\\"checkbox\\\" class=\\\"inlinemod_checkbox\\\" name=\\\"picturecommentlist[$message[commentid]]\\\" id=\\\"picturecommentlist_$message[commentid]\\\" value=\\\"$message[checkbox_value]\\\" title=\\\"$vbphrase[select_this_item_for_inline_moderation]\\\"  />\") : (\"\")).\"\r\n			<div class=\\\"message_date\\\">$message[date]\".((!$show[\'detailedtime\']) ? (\" <span class=\\\"time\\\">$message[time]</span>\") : (\"\")).\"</div>\r\n			\".(($message[\'postuserid\']) ? (\"\r\n				<a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$message[postuserid]\\\" class=\\\"smallfont username\\\">$message[musername]</a>\r\n			\") : (\"\r\n				<span class=\\\"smallfont username\\\">$message[musername]</span>\r\n			\")).\"\r\n			\".(($show[\'picture\']) ? (\"\r\n				<div>\" . construct_phrase(\"$vbphrase[picture_x_by_y]\", \"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$message[albumid]&amp;pictureid=$message[pictureid]\", \"$message[caption]\", \"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$message[pictureowner_userid]\", \"$message[pictureowner_name]\") . \"</div>\r\n			\") : (\"\")).\"\r\n		</div>\r\n	</div>\r\n\r\n	\".(($show[\'moderation\']) ? (\"<div class=\\\"shade\\\">$vbphrase[this_message_is_moderated]</div>\") : (\"\")).\"\r\n	<div id=\\\"picturecomment_text_$message[commentid]\\\">$message[message]</div>\r\n\r\n	<ul class=\\\"list_no_decoration controls\\\">\r\n		\".(($show[\'edit\']) ? (\"\r\n			<li class=\\\"smallfont\\\"><a href=\\\"picturecomment.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=message&amp;\".(($pictureinfo[\'groupid\']) ? (\"groupid=$pictureinfo[groupid]\") : (\"albumid=$pictureinfo[albumid]\")).\"&amp;pictureid=$pictureinfo[pictureid]&amp;commentid=$message[commentid]\\\" id=\\\"picturecomment_edit_$message[commentid]\\\">$vbphrase[edit]</a></li>\r\n		\") : (\"\")).\"\r\n		\".(($show[\'reportlink\']) ? (\"\r\n			<li class=\\\"smallfont\\\"><a href=\\\"picturecomment.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=report&amp;\".(($pictureinfo[\'groupid\']) ? (\"groupid=$pictureinfo[groupid]\") : (\"albumid=$pictureinfo[albumid]\")).\"&amp;pictureid=$pictureinfo[pictureid]&amp;commentid=$message[commentid]\\\">$vbphrase[report]</a></li>\r\n		\") : (\"\")).\"\r\n		\".(($message[\'messageipaddress\']) ? (\"\r\n			<li class=\\\"smallfont\\\"><a href=\\\"picturecomment.php?do=viewip&amp;\".(($pictureinfo[\'groupid\']) ? (\"groupid=$pictureinfo[groupid]\") : (\"albumid=$pictureinfo[albumid]\")).\"&amp;pictureid=$pictureinfo[pictureid]&amp;commentid=$message[commentid]\\\">$vbphrase[ip]</a></li>\r\n		\") : (\"\")).\"\r\n	</ul>\r\n\".(($message[\'avatarurl\']) ? (\"\r\n	</div>\r\n\") : (\"\")).\"\r\n<script type=\\\"text/javascript\\\"> \r\n<!-- \r\nvBulletin.register_control(\\\"vB_QuickEdit\\\", \\\"$message[commentid]\\\", \'PictureComment\', \'$pictureinfo[pictureid]\', \'\".(($pictureinfo[\'groupid\']) ? (\"$pictureinfo[groupid]\") : (\"$pictureinfo[albumid]\")).\"\', \".(($pictureinfo[\'groupid\']) ? (\"1\") : (\" 0\")).\" ); \r\n//--> \r\n</script> \r\n</li>', '<li id=\"picturecomment$message[commentid]\" class=\"floatcontainer\">\r\n	<if condition=\"$message[\'avatarurl\']\">\r\n		<div class=\"fixed_width_avatar\">\r\n			<if condition=\"$message[\'postuserid\']\"><a href=\"member.php?$session[sessionurl]u=$message[postuserid]\"></if><img src=\"$message[avatarurl]\" class=\"alt2 avatar\"<if condition=\"$message[\'avatarwidth\']\"> width=\"$message[avatarwidth]\"</if><if condition=\"$message[\'avatarheight\']\"> height=\"$message[avatarheight]\"</if> border=\"0\" alt=\"$message[username]\" /><if condition=\"$message[\'postuserid\']\"></a></if>\r\n		</div>\r\n		<div class=\"message_avatar_margin\">\r\n	</if>\r\n	<div class=\"tborder info_bar\">\r\n		<div class=\"alt2 smallfont\">\r\n			<if condition=\"$show[\'inlinemod\']\"><input type=\"checkbox\" class=\"inlinemod_checkbox\" name=\"picturecommentlist[$message[commentid]]\" id=\"picturecommentlist_$message[commentid]\" value=\"$message[checkbox_value]\" title=\"$vbphrase[select_this_item_for_inline_moderation]\"  /></if>\r\n			<div class=\"message_date\">$message[date]<if condition=\"!$show[\'detailedtime\']\"> <span class=\"time\">$message[time]</span></if></div>\r\n			<if condition=\"$message[\'postuserid\']\">\r\n				<a href=\"member.php?$session[sessionurl]u=$message[postuserid]\" class=\"smallfont username\">$message[musername]</a>\r\n			<else />\r\n				<span class=\"smallfont username\">$message[musername]</span>\r\n			</if>\r\n			<if condition=\"$show[\'picture\']\">\r\n				<div><phrase 1=\"album.php?$session[sessionurl]albumid=$message[albumid]&amp;pictureid=$message[pictureid]\" 2=\"$message[caption]\" 3=\"member.php?$session[sessionurl]u=$message[pictureowner_userid]\" 4=\"$message[pictureowner_name]\">$vbphrase[picture_x_by_y]</phrase></div>\r\n			</if>\r\n		</div>\r\n	</div>\r\n\r\n	<if condition=\"$show[\'moderation\']\"><div class=\"shade\">$vbphrase[this_message_is_moderated]</div></if>\r\n	<div id=\"picturecomment_text_$message[commentid]\">$message[message]</div>\r\n\r\n	<ul class=\"list_no_decoration controls\">\r\n		<if condition=\"$show[\'edit\']\">\r\n			<li class=\"smallfont\"><a href=\"picturecomment.php?$session[sessionurl]do=message&amp;<if condition=\"$pictureinfo[\'groupid\']\">groupid=$pictureinfo[groupid]<else />albumid=$pictureinfo[albumid]</if>&amp;pictureid=$pictureinfo[pictureid]&amp;commentid=$message[commentid]\" id=\"picturecomment_edit_$message[commentid]\">$vbphrase[edit]</a></li>\r\n		</if>\r\n		<if condition=\"$show[\'reportlink\']\">\r\n			<li class=\"smallfont\"><a href=\"picturecomment.php?$session[sessionurl]do=report&amp;<if condition=\"$pictureinfo[\'groupid\']\">groupid=$pictureinfo[groupid]<else />albumid=$pictureinfo[albumid]</if>&amp;pictureid=$pictureinfo[pictureid]&amp;commentid=$message[commentid]\">$vbphrase[report]</a></li>\r\n		</if>\r\n		<if condition=\"$message[\'messageipaddress\']\">\r\n			<li class=\"smallfont\"><a href=\"picturecomment.php?do=viewip&amp;<if condition=\"$pictureinfo[\'groupid\']\">groupid=$pictureinfo[groupid]<else />albumid=$pictureinfo[albumid]</if>&amp;pictureid=$pictureinfo[pictureid]&amp;commentid=$message[commentid]\">$vbphrase[ip]</a></li>\r\n		</if>\r\n	</ul>\r\n<if condition=\"$message[\'avatarurl\']\">\r\n	</div>\r\n</if>\r\n<script type=\"text/javascript\"> \r\n<!-- \r\nvBulletin.register_control(\"vB_QuickEdit\", \"$message[commentid]\", \'PictureComment\', \'$pictureinfo[pictureid]\', \'<if condition=\"$pictureinfo[\'groupid\']\">$pictureinfo[groupid]<else />$pictureinfo[albumid]</if>\', <if condition=\"$pictureinfo[\'groupid\']\">1<else /> 0</if> ); \r\n//--> \r\n</script> \r\n</li>', 'template', 1218204972, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(322, -1, 'picturecomment_message_deleted', '<li id=\\\"picturecomment$message[commentid]\\\" class=\\\"floatcontainer\\\">\r\n	<div class=\\\"tborder info_bar\\\">\r\n		<div class=\\\"alt2 smallfont\\\">\r\n			\".(($show[\'inlinemod\']) ? (\"<input type=\\\"checkbox\\\" class=\\\"inlinemod_checkbox\\\" name=\\\"picturecommentlist[$message[commentid]]\\\" id=\\\"picturecommentlist_$message[commentid]\\\" value=\\\"$message[checkbox_value]\\\" title=\\\"$vbphrase[select_this_item_for_inline_moderation]\\\"  />\") : (\"\")).\"\r\n			<div class=\\\"message_date\\\">$message[date]\".((!$show[\'detailedtime\']) ? (\" <span class=\\\"time\\\">$message[time]</span>\") : (\"\")).\"</div>\r\n			\".(($message[\'postuserid\']) ? (\"\r\n				<a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$message[postuserid]\\\" class=\\\"smallfont username\\\">$message[musername]</a>\r\n			\") : (\"\r\n				<span class=\\\"smallfont username\\\">$message[musername]</span>\r\n			\")).\"\r\n\r\n			\".(($show[\'picture\']) ? (\"\r\n				<div>\" . construct_phrase(\"$vbphrase[picture_x_by_y]\", \"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$message[albumid]&amp;pictureid=$message[pictureid]\", \"$message[caption]\", \"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$message[pictureowner_userid]\", \"$message[pictureowner_name]\") . \"</div>\r\n			\") : (\"\")).\"\r\n\r\n		</div>\r\n	</div>\r\n\r\n	\".(($show[\'deleted\']) ? (\"<div>$message[message]</div><br />\") : (\"\")).\"\r\n\r\n	<div class=\\\"smallfont deletedmessage\\\">\r\n		\" . construct_phrase(\"$vbphrase[message_deleted_by_x]\", \"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$message[del_userid]\", \"$message[del_username]\") . \"\r\n		\".(($message[\'del_reason\']) ? (\"<span class=\\\"shade\\\">$vbphrase[reason]</span> <em>$message[del_reason]</em>\") : (\"\")).\"\r\n	</div>\r\n	\r\n	\".(($show[\'edit\'] OR $show[\'reportlink\']) ? (\"\r\n		<ul class=\\\"list_no_decoration controls\\\">\r\n			\".(($show[\'edit\']) ? (\"\r\n				<li class=\\\"smallfont\\\"><a class=\\\"smallfont\\\" href=\\\"picturecomment.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=message&amp;\".(($pictureinfo[\'groupid\']) ? (\"groupid=$pictureinfo[groupid]\") : (\"albumid=$pictureinfo[albumid]\")).\"&amp;pictureid=$pictureinfo[pictureid]&amp;commentid=$message[commentid]\\\">$vbphrase[edit]</a></li>\r\n			\") : (\"\")).\"\r\n			\".(($show[\'reportlink\']) ? (\"\r\n				<li class=\\\"smallfont\\\"><a class=\\\"smallfont\\\" href=\\\"picturecomment.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=report&amp;\".(($pictureinfo[\'groupid\']) ? (\"groupid=$pictureinfo[groupid]\") : (\"albumid=$pictureinfo[albumid]\")).\"&amp;pictureid=$pictureinfo[pictureid]&amp;commentid=$message[commentid]\\\">$vbphrase[report]</a></li>\r\n			\") : (\"\")).\"\r\n		</ul>\r\n	\") : (\"\")).\"	\r\n</li>', '<li id=\"picturecomment$message[commentid]\" class=\"floatcontainer\">\r\n	<div class=\"tborder info_bar\">\r\n		<div class=\"alt2 smallfont\">\r\n			<if condition=\"$show[\'inlinemod\']\"><input type=\"checkbox\" class=\"inlinemod_checkbox\" name=\"picturecommentlist[$message[commentid]]\" id=\"picturecommentlist_$message[commentid]\" value=\"$message[checkbox_value]\" title=\"$vbphrase[select_this_item_for_inline_moderation]\"  /></if>\r\n			<div class=\"message_date\">$message[date]<if condition=\"!$show[\'detailedtime\']\"> <span class=\"time\">$message[time]</span></if></div>\r\n			<if condition=\"$message[\'postuserid\']\">\r\n				<a href=\"member.php?$session[sessionurl]u=$message[postuserid]\" class=\"smallfont username\">$message[musername]</a>\r\n			<else />\r\n				<span class=\"smallfont username\">$message[musername]</span>\r\n			</if>\r\n\r\n			<if condition=\"$show[\'picture\']\">\r\n				<div><phrase 1=\"album.php?$session[sessionurl]albumid=$message[albumid]&amp;pictureid=$message[pictureid]\" 2=\"$message[caption]\" 3=\"member.php?$session[sessionurl]u=$message[pictureowner_userid]\" 4=\"$message[pictureowner_name]\">$vbphrase[picture_x_by_y]</phrase></div>\r\n			</if>\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<if condition=\"$show[\'deleted\']\"><div>$message[message]</div><br /></if>\r\n\r\n	<div class=\"smallfont deletedmessage\">\r\n		<phrase 1=\"member.php?$session[sessionurl]u=$message[del_userid]\" 2=\"$message[del_username]\">$vbphrase[message_deleted_by_x]</phrase>\r\n		<if condition=\"$message[\'del_reason\']\"><span class=\"shade\">$vbphrase[reason]</span> <em>$message[del_reason]</em></if>\r\n	</div>\r\n	\r\n	<if condition=\"$show[\'edit\'] OR $show[\'reportlink\']\">\r\n		<ul class=\"list_no_decoration controls\">\r\n			<if condition=\"$show[\'edit\']\">\r\n				<li class=\"smallfont\"><a class=\"smallfont\" href=\"picturecomment.php?$session[sessionurl]do=message&amp;<if condition=\"$pictureinfo[\'groupid\']\">groupid=$pictureinfo[groupid]<else />albumid=$pictureinfo[albumid]</if>&amp;pictureid=$pictureinfo[pictureid]&amp;commentid=$message[commentid]\">$vbphrase[edit]</a></li>\r\n			</if>\r\n			<if condition=\"$show[\'reportlink\']\">\r\n				<li class=\"smallfont\"><a class=\"smallfont\" href=\"picturecomment.php?$session[sessionurl]do=report&amp;<if condition=\"$pictureinfo[\'groupid\']\">groupid=$pictureinfo[groupid]<else />albumid=$pictureinfo[albumid]</if>&amp;pictureid=$pictureinfo[pictureid]&amp;commentid=$message[commentid]\">$vbphrase[report]</a></li>\r\n			</if>\r\n		</ul>\r\n	</if>	\r\n</li>', 'template', 1219146391, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(323, -1, 'picturecomment_message_global_ignored', '<li id=\\\"picturecomment$message[commentid]\\\" class=\\\"floatcontainer\\\">\r\n	<div class=\\\"tborder info_bar\\\">\r\n		<div class=\\\"alt2 smallfont\\\">\r\n			\".(($show[\'inlinemod\']) ? (\"<input type=\\\"checkbox\\\" class=\\\"inlinemod_checkbox\\\" name=\\\"picturecommentlist[$message[commentid]]\\\" id=\\\"picturecommentlist_$message[commentid]\\\" value=\\\"$message[checkbox_value]\\\" title=\\\"$vbphrase[select_this_item_for_inline_moderation]\\\" />\") : (\"\")).\"\r\n			<div class=\\\"message_date\\\">$message[date]\".((!$show[\'detailedtime\']) ? (\" <span class=\\\"time\\\">$message[time]</span>\") : (\"\")).\"</div>\r\n			<a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$message[postuserid]\\\" class=\\\"smallfont username\\\">$message[musername]</a>\r\n\r\n			\".(($show[\'picture\']) ? (\"\r\n				<div>\" . construct_phrase(\"$vbphrase[picture_x_by_y]\", \"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$message[albumid]&amp;pictureid=$message[pictureid]\", \"$message[caption]\", \"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$message[pictureowner_userid]\", \"$message[pictureowner_name]\") . \"</div>\r\n			\") : (\"\")).\"\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div class=\\\"smallfont\\\" style=\\\"float: $stylevar[right]\\\">\r\n		<a href=\\\"\".(($pictureinfo[\'groupid\']) ? (\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=picture&amp;groupid=$pictureinfo[groupid]\") : (\"album.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"albumid=$pictureinfo[albumid]\")).\"&amp;pictureid=$pictureinfo[pictureid]&amp;commentid=$message[commentid]&amp;showignored=1#picturecomment$message[commentid]\\\">$vbphrase[show_message_text]</a>\r\n	</div>\r\n	<div class=\\\"smallfont\\\">\r\n		\" . construct_phrase(\"$vbphrase[administrator_decided_x_quiet]\", \"$mess