">\r\n		<strong>$vbphrase[download_all_private_messages_as]</strong>:<br />\r\n		<a href=\\\"private.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=downloadpm&amp;dowhat=xml\\\">$vbphrase[xml]</a> |\r\n		<a href=\\\"private.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=downloadpm&amp;dowhat=csv\\\">$vbphrase[csv]</a> |\r\n		<a href=\\\"private.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=downloadpm&amp;dowhat=txt\\\">$vbphrase[text]</a>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td valign=\\\"bottom\\\">$forumjump</td>\r\n</tr>\r\n</table>\r\n<!-- / forumjump -->', '<script type=\"text/javascript\">\r\n<!--\r\nfunction check_all_group(checkobj, value)\r\n{\r\n	formobj = checkobj.form;\r\n	for (var i = 0; i < formobj.elements.length; i++)\r\n	{\r\n		elm = formobj.elements[i];\r\n		if (elm.type == \"checkbox\" && elm.value == value)\r\n		{\r\n			elm.checked = checkobj.checked;\r\n		}\r\n	}\r\n}\r\n//-->\r\n</script>\r\n\r\n<form action=\"private.php\" method=\"get\">\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"pp\" value=\"$perpage\" />\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<thead>\r\n	<tr>\r\n		<td class=\"tcat\">\r\n			<a style=\"float:$stylevar[right]\" href=\"#top\" onclick=\"return toggle_collapse(\'pmlistinfo\')\"><img id=\"collapseimg_pmlistinfo\" src=\"$stylevar[imgdir_button]/collapse_tcat$vbcollapse[collapseimg_pmlistinfo].gif\" alt=\"\" border=\"0\" /></a>\r\n			$vbphrase[private_messages_in_folder]<span class=\"normal\">: <span id=\"nav_pmfolders.listinfo\">$foldername<script type=\"text/javascript\"> vbmenu_register(\"nav_pmfolders.listinfo\"); </script></span></span>\r\n		</td>\r\n	</tr>\r\n</thead>\r\n<tbody id=\"collapseobj_pmlistinfo\" style=\"$vbcollapse[collapseobj_pmlistinfo]\">\r\n	<tr>\r\n		<td class=\"panelsurround\" align=\"center\">\r\n		<div class=\"panel\">\r\n			<div style=\"width:$stylevar[formwidth_usercp]\" align=\"$stylevar[left]\">\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[folder_controls]</legend>\r\n					<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\" width=\"100%\">\r\n					<tr>\r\n						<td><phrase 1=\"$foldername\" 2=\"$totalmessages\" 3=\"$pmtotal\" 4=\"$pmquota\">$vbphrase[x_contains_y_z_messages_of_xx]</phrase> (<a href=\"private.php?do=emptyfolder&amp;folderid=$folderid\"><em>$vbphrase[empty_folder]</em></a>)</td>\r\n					</tr>\r\n					<tr>\r\n						<td>\r\n							<table style=\"border:2px groove\" cellpadding=\"0\" cellspacing=\"1\" border=\"0\" width=\"100%\">\r\n							<tr>\r\n								<if condition=\"$show[\'thisfoldertotal\']\"><td width=\"$tdwidth[folder]\" style=\"background-color:red; font-size:10px\" title=\"<phrase 1=\"$totalmessages\">$vbphrase[messages_stored_in_folder_x]</phrase>\">&nbsp;</td></if>\r\n								<if condition=\"$show[\'allfolderstotal\']\"><td width=\"$tdwidth[total]\" style=\"background-color:orange; font-size:10px\" title=\"<phrase 1=\"$bbuserinfo[pmtotal]\">$vbphrase[total_messages_in_all_folders_x]</phrase>\">&nbsp;</td></if>\r\n								<if condition=\"$tdwidth[quota] > 0\"><td width=\"$tdwidth[quota]\" style=\"background-color:green; font-size:10px\" title=\"<phrase 1=\"$permissions[pmquota]\">$vbphrase[maximum_allowed_messages_x]</phrase>\">&nbsp;</td></if>\r\n							</tr>\r\n							</table>\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td>\r\n							$vbphrase[jump_to_folder]:<br />\r\n							<select name=\"folderid\" onchange=\"this.form.submit();\">\r\n							$folderjump\r\n							</select>$gobutton\r\n						</td>\r\n					</tr>\r\n					<if condition=\"$receipts[\'unconfirmed\'] OR $receipts[\'confirmed\']\"><tr>\r\n						<td><a href=\"private.php?$session[sessionurl]do=trackpm\"><phrase 1=\"$receipts[confirmed]\" 2=\"$receipts[unconfirmed]\">$vbphrase[you_have_x_and_y_receipts]</phrase></a></td>\r\n					</tr></if>\r\n					</table>\r\n				</fieldset>\r\n			</div>\r\n		</div>\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n</table>\r\n</form>\r\n\r\n<br />\r\n\r\n<if condition=\"$show[\'messagelist\']\">\r\n\r\n<form id=\"pmform\" action=\"private.php?do=managepm&amp;folderid=$folderid\" method=\"post\">\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n<input type=\"hidden\" name=\"do\" value=\"managepm\" />\r\n<input type=\"hidden\" name=\"folderid\" value=\"$folderid\" />\r\n\r\n<if condition=\"$show[\'pagenav\']\">\r\n<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"margin-bottom:3px\">\r\n<tr valign=\"bottom\">\r\n	<if condition=\"$pagenav\"><td align=\"$stylevar[right]\">$pagenav</td></if>\r\n</tr>\r\n</table>\r\n</if>\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<thead>\r\n	<tr>\r\n		<td class=\"tcat\" colspan=\"4\" style=\"padding:$stylevar[cellpadding]px; padding-$stylevar[right]:0px\">\r\n			<span class=\"smallfont\" style=\"float:$stylevar[right]\">\r\n				<label for=\"checkall_all\">\r\n				$vbphrase[messages]: <strong>$totalmessages</strong>\r\n				<input type=\"checkbox\" name=\"allbox\" id=\"checkall_all\" title=\"$vbphrase[check_uncheck_all]\" onclick=\"inlineMod_pms.check_all(this.checked)\" />\r\n				</label>\r\n			</span>\r\n			$vbphrase[private_messages_in_folder]<span class=\"normal\">: <span id=\"nav_pmfolders.messagelist\">$foldername<script type=\"text/javascript\"> vbmenu_register(\"nav_pmfolders.messagelist\"); </script></span></span>\r\n		</td>\r\n	</tr>\r\n</thead>\r\n<if condition=\"$totalmessages\">\r\n<tbody>\r\n<tr class=\"block_title\">\r\n	<td class=\"thead\" <if condition=\"$show[\'pmicons\']\">colspan=\"2\"</if>></td>\r\n	<td class=\"thead\">\r\n		<div style=\"float:$stylevar[right]\">\r\n			<a href=\"$orderlinks[date]&amp;pp=$perpage&amp;page=$pagenumber\">$vbphrase[date]</a> $sortarrow[date]\r\n		</div>\r\n		<div>\r\n			<a href=\"$orderlinks[title]&amp;pp=$perpage&amp;page=$pagenumber\">$vbphrase[title]</a> $sortarrow[title] / \r\n			<a href=\"$orderlinks[sender]&amp;pp=$perpage&amp;page=$pagenumber\">$vbphrase[sender]</a> $sortarrow[sender]\r\n		</div>\r\n	</td>\r\n	<if condition=\"$show[\'pmcheckbox\']\">\r\n	<td class=\"thead\"></td>\r\n	</if>\r\n</tr>\r\n</tbody>\r\n$messagelist_periodgroups\r\n<else />\r\n<tbody>\r\n	<tr>\r\n		<td class=\"alt1\" colspan=\"4\" style=\"text-align:center\">\r\n			$vbphrase[no_messages_to_display]\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n</if>\r\n<tbody>\r\n	<tr>\r\n		<td class=\"tfoot\" align=\"$stylevar[right]\" colspan=\"4\">\r\n			<div class=\"smallfont\">\r\n				$vbphrase[selected_messages]:\r\n				<select name=\"dowhat\">\r\n					<if condition=\"$show[\'movetofolder\']\"><option value=\"move\">$vbphrase[move_to_folder]...</option></if>\r\n					<option value=\"delete\">$vbphrase[delete]</option>\r\n					<option value=\"read\">$vbphrase[mark_as_read]</option>\r\n					<option value=\"unread\">$vbphrase[mark_as_unread]</option>\r\n					<option value=\"xml\">$vbphrase[download_as_xml]</option>\r\n					<option value=\"csv\">$vbphrase[download_as_csv]</option>\r\n					<option value=\"txt\">$vbphrase[download_as_text]</option>\r\n					<optgroup label=\"____________________\">\r\n						<option value=\"clear\">$vbphrase[deselect_all_messages]</option>\r\n					</optgroup>\r\n				</select>\r\n				<input type=\"submit\" class=\"button\" value=\"$vbphrase[go]\" id=\"pm_inlinego\" />\r\n			</div>\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n</table>\r\n\r\n<script type=\"text/javascript\" src=\"clientscript/vbulletin_inlinemod.js?v=$vboptions[simpleversion]\"></script>\r\n<script type=\"text/javascript\">\r\n	<!--\r\n	inlineMod_pms = new vB_Inline_Mod(\'inlineMod_pms\', \'pm\', \'pmform\', \'$vbphrase[go_x]\', \'vbulletin_inline\', \'thread\');\r\n	//-->\r\n</script>\r\n</form>\r\n\r\n<if condition=\"$show[\'pagenav\']\">\r\n<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"margin-top:3px\">\r\n<tr valign=\"top\">\r\n	<if condition=\"$pagenav\"><td align=\"$stylevar[right]\">$pagenav</td></if>\r\n</tr>\r\n</table>\r\n</if>\r\n\r\n</if>\r\n\r\n<br />\r\n\r\n$sortfilter\r\n\r\n<br />\r\n\r\n<!-- forumjump -->\r\n<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr valign=\"top\">\r\n	<td width=\"100%\" rowspan=\"2\">\r\n		<table cellpadding=\"2\" cellspacing=\"0\" border=\"0\">\r\n		<tr>\r\n			<td><img src=\"$stylevar[imgdir_statusicon]/pm_new.gif\" alt=\"$vbphrase[unread_message]\" border=\"0\" /></td>\r\n			<td class=\"smallfont\">&nbsp; $vbphrase[unread_message]</td>\r\n		</tr>\r\n		<tr>\r\n			<td><img src=\"$stylevar[imgdir_statusicon]/pm_old.gif\" alt=\"$vbphrase[read_message]\" border=\"0\" /></td>\r\n			<td class=\"smallfont\">&nbsp; $vbphrase[read_message]</td>\r\n		</tr>\r\n		<tr>\r\n			<td><img src=\"$stylevar[imgdir_statusicon]/pm_replied.gif\" alt=\"$vbphrase[repliedto_message]\" border=\"0\" /></td>\r\n			<td class=\"smallfont\">&nbsp; $vbphrase[repliedto_message]</td>\r\n		</tr>\r\n		<tr>\r\n			<td><img src=\"$stylevar[imgdir_statusicon]/pm_forwarded.gif\" alt=\"$vbphrase[forwarded_message]\" border=\"0\" /></td>\r\n			<td class=\"smallfont\">&nbsp; $vbphrase[forwarded_message]</td>\r\n		</tr>\r\n		</table>\r\n	</td>\r\n	<td class=\"smallfont\" nowrap=\"nowrap\">\r\n		<strong>$vbphrase[download_all_private_messages_as]</strong>:<br />\r\n		<a href=\"private.php?$session[sessionurl]do=downloadpm&amp;dowhat=xml\">$vbphrase[xml]</a> |\r\n		<a href=\"private.php?$session[sessionurl]do=downloadpm&amp;dowhat=csv\">$vbphrase[csv]</a> |\r\n		<a href=\"private.php?$session[sessionurl]do=downloadpm&amp;dowhat=txt\">$vbphrase[text]</a>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td valign=\"bottom\">$forumjump</td>\r\n</tr>\r\n</table>\r\n<!-- / forumjump -->', 'template', 1223393656, 'vBulletin Solutions', '3.8.0 Alpha 2', 'vbulletin'),
(332, -1, 'pm_messagelistbit', '<tr>\r\n	<td class=\\\"alt1\\\"><img src=\\\"$stylevar[imgdir_statusicon]/pm_$pm[statusicon].gif\\\" alt=\\\"\\\" border=\\\"0\\\" /></td>\r\n	\".(($show[\'pmicons\']) ? (\"<td class=\\\"alt2\\\">\".(($show[\'pmicon\']) ? (\"<img src=\\\"$pm[iconpath]\\\" alt=\\\"$pm[icontitle]\\\" />\") : (\"&nbsp;\")).\"</td>\") : (\"\")).\"\r\n	<td class=\\\"alt1 alt1Active\\\" id=\\\"m$pm[pmid]\\\" width=\\\"100%\\\">\r\n		<div>\r\n			<span style=\\\"float:$stylevar[right]\\\" class=\\\"smallfont\\\">$pm[senddate]</span>\r\n			<a href=\\\"private.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=showpm&amp;pmid=$pm[pmid]\\\">\".(($show[\'unread\']) ? (\"<strong>$pm[title]</strong>\") : (\"$pm[title]\")).\"</a>\r\n		</div>\r\n		<div class=\\\"smallfont\\\">\r\n			<span style=\\\"float:$stylevar[right]\\\" class=\\\"time\\\">$pm[sendtime]</span>\r\n			\".(($show[\'unread\']) ? (\"<strong>$userbit</strong>\") : (\"$userbit\")).\"\r\n		</div>\r\n\r\n	</td>\r\n	\".(($show[\'pmcheckbox\']) ? (\"<td class=\\\"alt2\\\" align=\\\"center\\\" style=\\\"padding:0px\\\"><input type=\\\"checkbox\\\" name=\\\"pm[$pmid]\\\" id=\\\"pmlist_$pmid\\\" value=\\\"$groupid\\\" /></td>\") : (\"\")).\"\r\n</tr>', '<tr>\r\n	<td class=\"alt1\"><img src=\"$stylevar[imgdir_statusicon]/pm_$pm[statusicon].gif\" alt=\"\" border=\"0\" /></td>\r\n	<if condition=\"$show[\'pmicons\']\"><td class=\"alt2\"><if condition=\"$show[\'pmicon\']\"><img src=\"$pm[iconpath]\" alt=\"$pm[icontitle]\" /><else />&nbsp;</if></td></if>\r\n	<td class=\"alt1 alt1Active\" id=\"m$pm[pmid]\" width=\"100%\">\r\n		<div>\r\n			<span style=\"float:$stylevar[right]\" class=\"smallfont\">$pm[senddate]</span>\r\n			<a href=\"private.php?$session[sessionurl]do=showpm&amp;pmid=$pm[pmid]\"><if condition=\"$show[\'unread\']\"><strong>$pm[title]</strong><else />$pm[title]</if></a>\r\n		</div>\r\n		<div class=\"smallfont\">\r\n			<span style=\"float:$stylevar[right]\" class=\"time\">$pm[sendtime]</span>\r\n			<if condition=\"$show[\'unread\']\"><strong>$userbit</strong><else />$userbit</if>\r\n		</div>\r\n\r\n	</td>\r\n	<if condition=\"$show[\'pmcheckbox\']\"><td class=\"alt2\" align=\"center\" style=\"padding:0px\"><input type=\"checkbox\" name=\"pm[$pmid]\" id=\"pmlist_$pmid\" value=\"$groupid\" /></td></if>\r\n</tr>', 'template', 1221578878, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(333, -1, 'pm_messagelistbit_ignore', '<tr>\r\n	<td class=\\\"alt1\\\" colspan=\\\"3\\\">\r\n		<div class=\\\"smallfont\\\">\r\n			<span style=\\\"float:$stylevar[right]\\\"><a href=\\\"private.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=showpm&amp;pmid=$pm[pmid]\\\">$vbphrase[view_message]</a></span>\r\n			\" . construct_phrase(\"$vbphrase[x_is_on_your_ignore_list]\", \"$pm[fromusername]\", \"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=ignorelist\") . \"\r\n		</div>\r\n	</td>\r\n	\".(($show[\'pmcheckbox\']) ? (\"<td class=\\\"alt2\\\" align=\\\"center\\\" style=\\\"padding:0px\\\"><input type=\\\"checkbox\\\" name=\\\"pm[$pmid]\\\" value=\\\"$groupid\\\" checked=\\\"checked\\\" /></td>\") : (\"\")).\"\r\n</tr>', '<tr>\r\n	<td class=\"alt1\" colspan=\"3\">\r\n		<div class=\"smallfont\">\r\n			<span style=\"float:$stylevar[right]\"><a href=\"private.php?$session[sessionurl]do=showpm&amp;pmid=$pm[pmid]\">$vbphrase[view_message]</a></span>\r\n			<phrase 1=\"$pm[fromusername]\" 2=\"profile.php?$session[sessionurl]do=ignorelist\">$vbphrase[x_is_on_your_ignore_list]</phrase>\r\n		</div>\r\n	</td>\r\n	<if condition=\"$show[\'pmcheckbox\']\"><td class=\"alt2\" align=\"center\" style=\"padding:0px\"><input type=\"checkbox\" name=\"pm[$pmid]\" value=\"$groupid\" checked=\"checked\" /></td></if>\r\n</tr>', 'template', 1221578903, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(334, -1, 'pm_messagelistbit_user', '<span style=\\\"cursor:pointer\\\" onclick=\\\"window.location=\'member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$userid\';\\\">$username</span>', '<span style=\"cursor:pointer\" onclick=\"window.location=\'member.php?$session[sessionurl]u=$userid\';\">$username</span>', 'template', 1205932165, 'vBulletin Solutions', '3.7.0 Release Candidate 2', 'vbulletin'),
(335, -1, 'pm_messagelist_periodgroup', '<tbody>\r\n	<tr>\r\n		<td class=\\\"alt2\\\" colspan=\\\"\".(($show[\'pmicons\']) ? (\"3\") : (\"2\")).\"\\\" style=\\\"padding-top:3px; padding-bottom:3px; border-bottom:1px outset; cursor:pointer;\\\" ondblclick=\\\"toggle_collapse(\'pmf$groupid\')\\\" width=\\\"100%\\\">\r\n			<div class=\\\"smallfont\\\">\r\n				<span style=\\\"float:$stylevar[right]\\\">\r\n					<label for=\\\"checkall_$groupid\\\">$vbphrase[messages]: <strong>$messagesingroup</strong></label>\r\n				</span>\r\n				<a href=\\\"#top\\\" onclick=\\\"return toggle_collapse(\'pmf$groupid\')\\\"><img class=\\\"inlineimg\\\" id=\\\"collapseimg_pmf$groupid\\\" src=\\\"$stylevar[imgdir_button]/collapse_alt{$collapseimg_groupid}.gif\\\" alt=\\\"\\\" border=\\\"0\\\" /></a>\r\n				&nbsp;\r\n				<strong>$groupname</strong>\r\n			</div>\r\n		</td>\r\n		<td class=\\\"alt2\\\" style=\\\"padding:0px; border-bottom:1px outset\\\" align=\\\"center\\\"><input type=\\\"checkbox\\\" id=\\\"checkall_$groupid\\\" title=\\\"$vbphrase[select_deselect_all_in_group]\\\" onclick=\\\"inlineMod_pms.check_all(this.checked, \'$groupid\')\\\" /></td>\r\n	</tr>\r\n</tbody>\r\n<tbody id=\\\"collapseobj_pmf$groupid\\\" style=\\\"{$collapseobj_groupid}\\\">\r\n	$messagelistbits\r\n</tbody>', '<tbody>\r\n	<tr>\r\n		<td class=\"alt2\" colspan=\"<if condition=\"$show[\'pmicons\']\">3<else />2</if>\" style=\"padding-top:3px; padding-bottom:3px; border-bottom:1px outset; cursor:pointer;\" ondblclick=\"toggle_collapse(\'pmf$groupid\')\" width=\"100%\">\r\n			<div class=\"smallfont\">\r\n				<span style=\"float:$stylevar[right]\">\r\n					<label for=\"checkall_$groupid\">$vbphrase[messages]: <strong>$messagesingroup</strong></label>\r\n				</span>\r\n				<a href=\"#top\" onclick=\"return toggle_collapse(\'pmf$groupid\')\"><img class=\"inlineimg\" id=\"collapseimg_pmf$groupid\" src=\"$stylevar[imgdir_button]/collapse_alt{$collapseimg_groupid}.gif\" alt=\"\" border=\"0\" /></a>\r\n				&nbsp;\r\n				<strong>$groupname</strong>\r\n			</div>\r\n		</td>\r\n		<td class=\"alt2\" style=\"padding:0px; border-bottom:1px outset\" align=\"center\"><input type=\"checkbox\" id=\"checkall_$groupid\" title=\"$vbphrase[select_deselect_all_in_group]\" onclick=\"inlineMod_pms.check_all(this.checked, \'$groupid\')\" /></td>\r\n	</tr>\r\n</tbody>\r\n<tbody id=\"collapseobj_pmf$groupid\" style=\"{$collapseobj_groupid}\">\r\n	$messagelistbits\r\n</tbody>', 'template', 1223906167, 'vBulletin Solutions', '3.8.0 Beta 2', 'vbulletin'),
(336, -1, 'pm_movepm', '<form action=\\\"private.php?do=movepm\\\" method=\\\"post\\\">\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"movepm\\\"  />\r\n<input type=\\\"hidden\\\" name=\\\"messageids\\\" value=\\\"$messageids\\\" />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[move_private_messages]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth_usercp]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n			<fieldset class=\\\"fieldset\\\">\r\n				<legend>\" . construct_phrase(\"$vbphrase[move_x_items_from_y]\", \"$totalmessages\", \"$fromfolder\") . \"</legend>\r\n				<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n				<tr>\r\n					<td>$vbphrase[select_destination_folder_for_move]</td>\r\n				</tr>\r\n				<tr>\r\n					<td>\r\n						$vbphrase[folder_name]:<br />\r\n						<select name=\\\"folderid\\\">$folderoptions</select>\r\n					</td>\r\n				</tr>\r\n				</table>\r\n			</fieldset>\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[move_items]\\\" accesskey=\\\"s\\\" />\r\n		<input type=\\\"button\\\" class=\\\"button\\\" value=\\\"$vbphrase[cancel]\\\" accesskey=\\\"c\\\" onclick=\\\"history.back(1)\\\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>', '<form action=\"private.php?do=movepm\" method=\"post\">\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n<input type=\"hidden\" name=\"do\" value=\"movepm\"  />\r\n<input type=\"hidden\" name=\"messageids\" value=\"$messageids\" />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">$vbphrase[move_private_messages]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth_usercp]\" align=\"$stylevar[left]\">\r\n\r\n			<fieldset class=\"fieldset\">\r\n				<legend><phrase 1=\"$totalmessages\" 2=\"$fromfolder\">$vbphrase[move_x_items_from_y]</phrase></legend>\r\n				<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n				<tr>\r\n					<td>$vbphrase[select_destination_folder_for_move]</td>\r\n				</tr>\r\n				<tr>\r\n					<td>\r\n						$vbphrase[folder_name]:<br />\r\n						<select name=\"folderid\">$folderoptions</select>\r\n					</td>\r\n				</tr>\r\n				</table>\r\n			</fieldset>\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"submit\" class=\"button\" value=\"$vbphrase[move_items]\" accesskey=\"s\" />\r\n		<input type=\"button\" class=\"button\" value=\"$vbphrase[cancel]\" accesskey=\"c\" onclick=\"history.back(1)\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>', 'template', 1208876563, 'vBulletin Solutions', '3.7.0 Release Candidate 4', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(337, -1, 'pm_newpm', '<form action=\\\"private.php?do=insertpm&amp;pmid=$pm[pmid]\\\" method=\\\"post\\\" name=\\\"vbform\\\"\".((!is_browser(\'webtv\')) ? (\" onsubmit=\\\"return vB_Editor[\'$editorid\'].prepare_submit(this.title.value, 0)\\\"\") : (\"\")).\">\r\n\r\n$postpreview\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[post_new_private_message]</td>\r\n</tr>\r\n\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div align=\\\"$stylevar[left]\\\" style=\\\"max-width:$stylevar[formwidth]; width:auto !important; width:$stylevar[formwidth_usercp]\\\">\r\n\r\n		<!-- recipients field -->\r\n		<fieldset class=\\\"fieldset\\\">\r\n			<legend>$vbphrase[recipients]</legend>\r\n			<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n			<tr>\r\n				<td>\r\n					\".(($show[\'popups\']) ? (\"\r\n					<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_ajax_namesugg.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n					\") : (\"\")).\"\r\n					<div>$vbphrase[recipient_usernames]</div>\r\n					<div id=\\\"pmrecips\\\"><textarea id=\\\"pmrecips_txt\\\" name=\\\"recipients\\\" rows=\\\"\".((is_browser(\'mozilla\')) ? (\"1\") : (\"2\")).\"\\\" cols=\\\"50\\\" tabindex=\\\"1\\\">$pm[recipients]</textarea></div>\r\n					\".(($show[\'popups\']) ? (\"\r\n						<div class=\\\"vbmenu_popup\\\" id=\\\"pmrecips_menu\\\" style=\\\"display:none; z-index:50\\\"></div>\r\n						<script type=\\\"text/javascript\\\">\r\n						<!--\r\n						vbmenu_register(\'pmrecips\', true);\r\n						recip_sugg = new vB_AJAX_NameSuggest(\'recip_sugg\', \'pmrecips_txt\', \'pmrecips\');\r\n						\".(($show[\'sendmultiple\']) ? (\"recip_sugg.allow_multiple = true;\") : (\"\")).\"\r\n						//-->\r\n						</script>\r\n					\") : (\"\")).\"\r\n					\".(($show[\'sendmultiple\']) ? (\"\r\n						<span style=\\\"display:none\\\" onclick=\\\"return swapbcc(this);\\\" id=\\\"bccspan1\\\">[<a href=\\\"#\\\">$vbphrase[bcc]</a>]</span>\r\n						<span id=\\\"bccspan2\\\">$vbphrase[bcc] $vbphrase[recipient_usernames]<br /></span>\r\n						<div id=\\\"bccpmrecips\\\"><textarea id=\\\"bccpmrecips_txt\\\" name=\\\"bccrecipients\\\" rows=\\\"\".((is_browser(\'mozilla\')) ? (\"1\") : (\"2\")).\"\\\" cols=\\\"50\\\" tabindex=\\\"1\\\">$pm[bccrecipients]</textarea></div>\r\n						\".(($show[\'popups\']) ? (\"\r\n							<div class=\\\"vbmenu_popup\\\" id=\\\"bccpmrecips_menu\\\" style=\\\"display:none; z-index:50\\\"></div>\r\n							<script type=\\\"text/javascript\\\">\r\n							<!--\r\n							vbmenu_register(\'bccpmrecips\', true);\r\n							bccrecip_sugg = new vB_AJAX_NameSuggest(\'bccrecip_sugg\', \'bccpmrecips_txt\', \'bccpmrecips\');\r\n							bccrecip_sugg.allow_multiple = true;\r\n							\".(($show[\'bcclink\']) ? (\"\r\n							fetch_object(\'bccpmrecips\').style.display = \'none\';\r\n							fetch_object(\'bccspan2\').style.display = \'none\';\r\n							fetch_object(\'bccspan1\').style.display = \'\';\r\n							function swapbcc(obj)\r\n							{\r\n								obj.style.display = \'none\';\r\n								fetch_object(\'bccpmrecips\').style.display = \'\';\r\n								fetch_object(\'bccspan2\').style.display = \'\';\r\n								return false;\r\n							}\r\n							\") : (\"\")).\"\r\n							//-->\r\n							</script>\r\n						\") : (\"\")).\"\r\n					\") : (\"\")).\"\r\n				</td>\r\n			</tr>\r\n			<tr>\r\n				<td>\r\n					\".(($show[\'sendmax\']) ? (\"<div>\" . construct_phrase(\"$vbphrase[may_send_to_x_people]\", \"$permissions[pmsendmax]\") . \"</div>\") : (\"\")).\"\r\n					\".(($show[\'sendmultiple\']) ? (\"<div>$vbphrase[separate_multiple_names]</div>\") : (\"\")).\"\r\n				</td>\r\n			</tr>\r\n			</table>\r\n		</fieldset>\r\n		<!-- / recipients field -->\r\n\r\n		<!-- subject field -->\r\n		<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" class=\\\"fieldset\\\">\r\n		<tr>\r\n			<td class=\\\"smallfont\\\" colspan=\\\"3\\\">$vbphrase[title]:</td>\r\n		</tr>\r\n		<tr>\r\n			<td><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"title\\\" value=\\\"$pm[title]\\\" size=\\\"50\\\" maxlength=\\\"85\\\" tabindex=\\\"1\\\" /></td>\r\n			<td>&nbsp;&nbsp;</td>\r\n			<td><img id=\\\"display_posticon\\\" src=\\\"$selectedicon[src]\\\" alt=\\\"$selectedicon[alt]\\\" /></td>\r\n		</tr>\r\n		</table>\r\n		<!-- / subject field -->\r\n\r\n		<!-- message area -->\r\n		<div class=\\\"smallfont\\\">$vbphrase[message]:</div>\r\n		$messagearea\r\n		<!-- / message area -->\r\n\r\n		$posticons\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"insertpm\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"pmid\\\" value=\\\"$pm[pmid]\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"forward\\\" value=\\\"$pm[forward]\\\" />\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" name=\\\"sbutton\\\" id=\\\"{$editorid}_save\\\" value=\\\"$vbphrase[submit_message]\\\" accesskey=\\\"s\\\" tabindex=\\\"1\\\" />\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[preview_message]\\\" accesskey=\\\"r\\\" name=\\\"preview\\\" tabindex=\\\"1\\\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<thead>\r\n	<tr>\r\n		<td class=\\\"tcat\\\">\r\n 			<a name=\\\"options\\\" style=\\\"float:$stylevar[right]\\\" href=\\\"#top\\\" onclick=\\\"return toggle_collapse(\'newpost_options\')\\\"><img id=\\\"collapseimg_newpost_options\\\" src=\\\"$stylevar[imgdir_button]/collapse_tcat$vbcollapse[collapseimg_newpost_options].gif\\\" alt=\\\"\\\" border=\\\"0\\\" /></a>\r\n 			$vbphrase[additional_options]\r\n 		</td>\r\n	</tr>\r\n</thead>\r\n<tbody id=\\\"collapseobj_newpost_options\\\" style=\\\"$vbcollapse[collapseobj_newpost_options]\\\">\r\n	<tr valign=\\\"top\\\">\r\n		<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n		<div class=\\\"panel\\\">\r\n			<div align=\\\"$stylevar[left]\\\" style=\\\"max-width:$stylevar[formwidth]; width:auto !important; width:$stylevar[formwidth_usercp]\\\">\r\n\r\n				\".(($show[\'receivepmbuddies\']) ? (\"\r\n				<fieldset class=\\\"fieldset\\\">\r\n					<legend>$vbphrase[pm_non_contacts_heading]</legend>\r\n					<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n					<tr>\r\n						<td>\" . construct_phrase(\"$vbphrase[pm_non_contact_option_description]\", \"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"\") . \"</td>\r\n					</tr>\r\n					<tr>\r\n						<td><label for=\\\"cb_anyway\\\"><input type=\\\"checkbox\\\" name=\\\"sendanyway\\\" id=\\\"cb_anyway\\\" value=\\\"1\\\" $anywaychecked />$vbphrase[pm_non_contact_option]</label></td>\r\n					</tr>\r\n					</table>\r\n				</fieldset>\r\n				\") : (\"\")).\"\r\n\r\n				<fieldset class=\\\"fieldset\\\">\r\n					<legend>$vbphrase[miscellaneous_options]</legend>\r\n					<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n						\".(($show[\'trackpm\']) ? (\"<div><label for=\\\"cb_receipt\\\"><input type=\\\"checkbox\\\" name=\\\"receipt\\\" value=\\\"1\\\" id=\\\"cb_receipt\\\" $checked[receipt] />$vbphrase[request_receipt_for_message]</label></div>\") : (\"\")).\"\r\n						<div><label for=\\\"cb_savecopy\\\"><input type=\\\"checkbox\\\" name=\\\"savecopy\\\" value=\\\"1\\\" id=\\\"cb_savecopy\\\" tabindex=\\\"1\\\" $checked[savecopy] />\" . construct_phrase(\"$vbphrase[save_copy_in_sent_items_folder]\", \"private.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"folderid=-1\") . \"</label></div>\r\n						\".(($GLOBALS[\'vbulletin\']->userinfo[\'signature\']) ? (\"<div><label for=\\\"cb_signature\\\"><input type=\\\"checkbox\\\" name=\\\"signature\\\" value=\\\"1\\\" id=\\\"cb_signature\\\" tabindex=\\\"1\\\" $checked[signature] />$vbphrase[show_your_signature]</label></div>\") : (\"\")).\"\r\n						\".(($show[\'parseurl\']) ? (\"<div><label for=\\\"cb_parseurl\\\"><input type=\\\"checkbox\\\" name=\\\"parseurl\\\" value=\\\"1\\\" id=\\\"cb_parseurl\\\" tabindex=\\\"1\\\" $checked[parseurl] />$vbphrase[automatically_parse_links_in_text]</label></div>\") : (\"\")).\"\r\n						$disablesmiliesoption\r\n					</div>\r\n				</fieldset>\r\n\r\n			</div>\r\n		</div>\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n</table>\r\n\r\n</form>\r\n\r\n<br />\r\n\r\n$forumrules', '<form action=\"private.php?do=insertpm&amp;pmid=$pm[pmid]\" method=\"post\" name=\"vbform\"<if condition=\"!is_browser(\'webtv\')\"> onsubmit=\"return vB_Editor[\'$editorid\'].prepare_submit(this.title.value, 0)\"</if>>\r\n\r\n$postpreview\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">$vbphrase[post_new_private_message]</td>\r\n</tr>\r\n\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div align=\"$stylevar[left]\" style=\"max-width:$stylevar[formwidth]; width:auto !important; width:$stylevar[formwidth_usercp]\">\r\n\r\n		<!-- recipients field -->\r\n		<fieldset class=\"fieldset\">\r\n			<legend>$vbphrase[recipients]</legend>\r\n			<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n			<tr>\r\n				<td>\r\n					<if condition=\"$show[\'popups\']\">\r\n					<script type=\"text/javascript\" src=\"clientscript/vbulletin_ajax_namesugg.js?v=$vboptions[simpleversion]\"></script>\r\n					</if>\r\n					<div>$vbphrase[recipient_usernames]</div>\r\n					<div id=\"pmrecips\"><textarea id=\"pmrecips_txt\" name=\"recipients\" rows=\"<if condition=\"is_browser(\'mozilla\')\">1<else />2</if>\" cols=\"50\" tabindex=\"1\">$pm[recipients]</textarea></div>\r\n					<if condition=\"$show[\'popups\']\">\r\n						<div class=\"vbmenu_popup\" id=\"pmrecips_menu\" style=\"display:none; z-index:50\"></div>\r\n						<script type=\"text/javascript\">\r\n						<!--\r\n						vbmenu_register(\'pmrecips\', true);\r\n						recip_sugg = new vB_AJAX_NameSuggest(\'recip_sugg\', \'pmrecips_txt\', \'pmrecips\');\r\n						<if condition=\"$show[\'sendmultiple\']\">recip_sugg.allow_multiple = true;</if>\r\n						//-->\r\n						</script>\r\n					</if>\r\n					<if condition=\"$show[\'sendmultiple\']\">\r\n						<span style=\"display:none\" onclick=\"return swapbcc(this);\" id=\"bccspan1\">[<a href=\"#\">$vbphrase[bcc]</a>]</span>\r\n						<span id=\"bccspan2\">$vbphrase[bcc] $vbphrase[recipient_usernames]<br /></span>\r\n						<div id=\"bccpmrecips\"><textarea id=\"bccpmrecips_txt\" name=\"bccrecipients\" rows=\"<if condition=\"is_browser(\'mozilla\')\">1<else />2</if>\" cols=\"50\" tabindex=\"1\">$pm[bccrecipients]</textarea></div>\r\n						<if condition=\"$show[\'popups\']\">\r\n							<div class=\"vbmenu_popup\" id=\"bccpmrecips_menu\" style=\"display:none; z-index:50\"></div>\r\n							<script type=\"text/javascript\">\r\n							<!--\r\n							vbmenu_register(\'bccpmrecips\', true);\r\n							bccrecip_sugg = new vB_AJAX_NameSuggest(\'bccrecip_sugg\', \'bccpmrecips_txt\', \'bccpmrecips\');\r\n							bccrecip_sugg.allow_multiple = true;\r\n							<if condition=\"$show[\'bcclink\']\">\r\n							fetch_object(\'bccpmrecips\').style.display = \'none\';\r\n							fetch_object(\'bccspan2\').style.display = \'none\';\r\n							fetch_object(\'bccspan1\').style.display = \'\';\r\n							function swapbcc(obj)\r\n							{\r\n								obj.style.display = \'none\';\r\n								fetch_object(\'bccpmrecips\').style.display = \'\';\r\n								fetch_object(\'bccspan2\').style.display = \'\';\r\n								return false;\r\n							}\r\n							</if>\r\n							//-->\r\n							</script>\r\n						</if>\r\n					</if>\r\n				</td>\r\n			</tr>\r\n			<tr>\r\n				<td>\r\n					<if condition=\"$show[\'sendmax\']\"><div><phrase 1=\"$permissions[pmsendmax]\">$vbphrase[may_send_to_x_people]</phrase></div></if>\r\n					<if condition=\"$show[\'sendmultiple\']\"><div>$vbphrase[separate_multiple_names]</div></if>\r\n				</td>\r\n			</tr>\r\n			</table>\r\n		</fieldset>\r\n		<!-- / recipients field -->\r\n\r\n		<!-- subject field -->\r\n		<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" class=\"fieldset\">\r\n		<tr>\r\n			<td class=\"smallfont\" colspan=\"3\">$vbphrase[title]:</td>\r\n		</tr>\r\n		<tr>\r\n			<td><input type=\"text\" class=\"bginput\" name=\"title\" value=\"$pm[title]\" size=\"50\" maxlength=\"85\" tabindex=\"1\" /></td>\r\n			<td>&nbsp;&nbsp;</td>\r\n			<td><img id=\"display_posticon\" src=\"$selectedicon[src]\" alt=\"$selectedicon[alt]\" /></td>\r\n		</tr>\r\n		</table>\r\n		<!-- / subject field -->\r\n\r\n		<!-- message area -->\r\n		<div class=\"smallfont\">$vbphrase[message]:</div>\r\n		$messagearea\r\n		<!-- / message area -->\r\n\r\n		$posticons\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n		<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n		<input type=\"hidden\" name=\"do\" value=\"insertpm\" />\r\n		<input type=\"hidden\" name=\"pmid\" value=\"$pm[pmid]\" />\r\n		<input type=\"hidden\" name=\"forward\" value=\"$pm[forward]\" />\r\n		<input type=\"submit\" class=\"button\" name=\"sbutton\" id=\"{$editorid}_save\" value=\"$vbphrase[submit_message]\" accesskey=\"s\" tabindex=\"1\" />\r\n		<input type=\"submit\" class=\"button\" value=\"$vbphrase[preview_message]\" accesskey=\"r\" name=\"preview\" tabindex=\"1\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<thead>\r\n	<tr>\r\n		<td class=\"tcat\">\r\n 			<a name=\"options\" style=\"float:$stylevar[right]\" href=\"#top\" onclick=\"return toggle_collapse(\'newpost_options\')\"><img id=\"collapseimg_newpost_options\" src=\"$stylevar[imgdir_button]/collapse_tcat$vbcollapse[collapseimg_newpost_options].gif\" alt=\"\" border=\"0\" /></a>\r\n 			$vbphrase[additional_options]\r\n 		</td>\r\n	</tr>\r\n</thead>\r\n<tbody id=\"collapseobj_newpost_options\" style=\"$vbcollapse[collapseobj_newpost_options]\">\r\n	<tr valign=\"top\">\r\n		<td class=\"panelsurround\" align=\"center\">\r\n		<div class=\"panel\">\r\n			<div align=\"$stylevar[left]\" style=\"max-width:$stylevar[formwidth]; width:auto !important; width:$stylevar[formwidth_usercp]\">\r\n\r\n				<if condition=\"$show[\'receivepmbuddies\']\">\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[pm_non_contacts_heading]</legend>\r\n					<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\" width=\"100%\">\r\n					<tr>\r\n						<td><phrase 1=\"$session[sessionurl]\">$vbphrase[pm_non_contact_option_description]</phrase></td>\r\n					</tr>\r\n					<tr>\r\n						<td><label for=\"cb_anyway\"><input type=\"checkbox\" name=\"sendanyway\" id=\"cb_anyway\" value=\"1\" $anywaychecked />$vbphrase[pm_non_contact_option]</label></td>\r\n					</tr>\r\n					</table>\r\n				</fieldset>\r\n				</if>\r\n\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[miscellaneous_options]</legend>\r\n					<div style=\"padding:$stylevar[formspacer]px\">\r\n						<if condition=\"$show[\'trackpm\']\"><div><label for=\"cb_receipt\"><input type=\"checkbox\" name=\"receipt\" value=\"1\" id=\"cb_receipt\" $checked[receipt] />$vbphrase[request_receipt_for_message]</label></div></if>\r\n						<div><label for=\"cb_savecopy\"><input type=\"checkbox\" name=\"savecopy\" value=\"1\" id=\"cb_savecopy\" tabindex=\"1\" $checked[savecopy] /><phrase 1=\"private.php?$session[sessionurl]folderid=-1\">$vbphrase[save_copy_in_sent_items_folder]</phrase></label></div>\r\n						<if condition=\"$bbuserinfo[\'signature\']\"><div><label for=\"cb_signature\"><input type=\"checkbox\" name=\"signature\" value=\"1\" id=\"cb_signature\" tabindex=\"1\" $checked[signature] />$vbphrase[show_your_signature]</label></div></if>\r\n						<if condition=\"$show[\'parseurl\']\"><div><label for=\"cb_parseurl\"><input type=\"checkbox\" name=\"parseurl\" value=\"1\" id=\"cb_parseurl\" tabindex=\"1\" $checked[parseurl] />$vbphrase[automatically_parse_links_in_text]</label></div></if>\r\n						$disablesmiliesoption\r\n					</div>\r\n				</fieldset>\r\n\r\n			</div>\r\n		</div>\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n</table>\r\n\r\n</form>\r\n\r\n<br />\r\n\r\n$forumrules', 'template', 1212142724, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(338, -1, 'pm_nomessagehistory', '<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"alt2\\\" align=\\\"center\\\">\r\n		$vbphrase[no_message_history]\r\n	</td>\r\n</tr>\r\n</table>', '<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"alt2\" align=\"center\">\r\n		$vbphrase[no_message_history]\r\n	</td>\r\n</tr>\r\n</table>', 'template', 1226500884, 'vBulletin Solutions', '3.8.0 Beta 3', 'vbulletin'),
(339, -1, 'pm_popup_script', '<script type=\\\"text/javascript\\\">\r\n<!--\r\n// script to show new private message popup\r\n\r\nif (confirm(\\\"\" . construct_phrase(\"$vbphrase[have_new_pm_popup_x_y]\", \"$newpm[username]\", \"$newpm[title]\") . \"\\\"))\r\n{\r\n	// Output when OK is clicked\r\n	if (confirm(\\\"$vbphrase[open_message_in_new_window]\\\"))\r\n	{\r\n		var winobj = window.open(\\\"$pmpopupurl\\\", \\\"pmnew\\\", \\\"statusbar=yes,menubar=yes,scrollbars=yes,toolbar=yes,location=yes,directories=yes,resizable=yes,top=50,left=50\\\");\r\n		if (winobj == null)\r\n		{\r\n			alert(\\\"$vbphrase[window_open_failed_blocker]\\\");\r\n		}\r\n	}\r\n	else\r\n	{\r\n		window.location = \\\"$pmpopupurl\\\";\r\n	}\r\n}\r\n\r\n// end pm popup script\r\n//-->\r\n</script>', '<script type=\"text/javascript\">\r\n<!--\r\n// script to show new private message popup\r\n\r\nif (confirm(\"<phrase 1=\"$newpm[username]\" 2=\"$newpm[title]\">$vbphrase[have_new_pm_popup_x_y]</phrase>\"))\r\n{\r\n	// Output when OK is clicked\r\n	if (confirm(\"$vbphrase[open_message_in_new_window]\"))\r\n	{\r\n		var winobj = window.open(\"$pmpopupurl\", \"pmnew\", \"statusbar=yes,menubar=yes,scrollbars=yes,toolbar=yes,location=yes,directories=yes,resizable=yes,top=50,left=50\");\r\n		if (winobj == null)\r\n		{\r\n			alert(\"$vbphrase[window_open_failed_blocker]\");\r\n		}\r\n	}\r\n	else\r\n	{\r\n		window.location = \"$pmpopupurl\";\r\n	}\r\n}\r\n\r\n// end pm popup script\r\n//-->\r\n</script>', 'template', 1125409057, 'vBulletin Solutions', '3.5.0 Release Candidate 3', 'vbulletin'),
