(346, -1, 'pollnewbit', '<tr>\r\n	<td><label for=\\\"opt$option[number]\\\">\" . construct_phrase(\"$vbphrase[option_x]\", \"$option[number]\") . \":<br /><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"options[$option[number]]\\\" value=\\\"$option[question]\\\" size=\\\"50\\\" id=\\\"opt$option[number]\\\" tabindex=\\\"1\\\" /></label></td>\r\n</tr>\r\n', '<tr>\r\n	<td><label for=\"opt$option[number]\"><phrase 1=\"$option[number]\">$vbphrase[option_x]</phrase>:<br /><input type=\"text\" class=\"bginput\" name=\"options[$option[number]]\" value=\"$option[question]\" size=\"50\" id=\"opt$option[number]\" tabindex=\"1\" /></label></td>\r\n</tr>\r\n', 'template', 1070083614, 'vBulletin Solutions', '', 'vbulletin'),
(347, -1, 'polloption', '<div><label for=\\\"rb_optionnumber_$option[number]\\\"><input type=\\\"radio\\\" name=\\\"optionnumber\\\" value=\\\"$option[number]\\\" id=\\\"rb_optionnumber_$option[number]\\\" />$option[question]</label></div>\r\n', '<div><label for=\"rb_optionnumber_$option[number]\"><input type=\"radio\" name=\"optionnumber\" value=\"$option[number]\" id=\"rb_optionnumber_$option[number]\" />$option[question]</label></div>\r\n', 'template', 1069784992, 'vBulletin Solutions', '', 'vbulletin'),
(348, -1, 'polloptions_table', '<form action=\\\"poll.php?do=pollvote&amp;pollid=$pollinfo[pollid]\\\" method=\\\"post\\\">\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"pollvote\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"pollid\\\" value=\\\"$pollinfo[pollid]\\\" />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		\".(($show[\'editpoll\']) ? (\"<span class=\\\"smallfont\\\" style=\\\"float:$stylevar[right]\\\"><a href=\\\"poll.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=polledit&amp;pollid=$pollinfo[pollid]\\\">$vbphrase[edit_poll]</a></span>\") : (\"\")).\"\r\n		$vbphrase[poll]<span class=\\\"normal\\\">: $pollinfo[question]</span>\r\n	</td>\r\n</tr>\r\n\".(($show[\'pollenddate\']) ? (\"\r\n<tr>\r\n	<td class=\\\"thead\\\" align=\\\"center\\\" style=\\\"font-weight:normal\\\">\" . construct_phrase(\"$vbphrase[this_poll_will_close_on_x_at_y]\", \"$pollenddate\", \"$pollendtime\") . \"</td>\r\n</tr>\r\n\") : (\"\")).\"\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n			\".(($show[\'publicwarning\']) ? (\"\r\n			<div class=\\\"fieldset\\\">$vbphrase[public_poll_users_see_choices]</div>\r\n			\") : (\"\")).\"\r\n\r\n			<fieldset class=\\\"fieldset\\\">\r\n				<legend>$vbphrase[poll_options]</legend>\r\n				<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n					<div style=\\\"margin-bottom:$stylevar[formspacer]px\\\"><strong>$pollinfo[question]</strong></div>\r\n					$pollbits\r\n				</div>\r\n			</fieldset>\r\n\r\n			<div>\r\n				<span style=\\\"float:$stylevar[right]\\\"><a href=\\\"poll.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=showresults&amp;pollid=$pollinfo[pollid]\\\">$vbphrase[view_poll_results]</a></span>\r\n				<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[vote_now]\\\" />\r\n			</div>\r\n\r\n		</div>\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>\r\n\r\n<br />', '<form action=\"poll.php?do=pollvote&amp;pollid=$pollinfo[pollid]\" method=\"post\">\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n<input type=\"hidden\" name=\"do\" value=\"pollvote\" />\r\n<input type=\"hidden\" name=\"pollid\" value=\"$pollinfo[pollid]\" />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		<if condition=\"$show[\'editpoll\']\"><span class=\"smallfont\" style=\"float:$stylevar[right]\"><a href=\"poll.php?$session[sessionurl]do=polledit&amp;pollid=$pollinfo[pollid]\">$vbphrase[edit_poll]</a></span></if>\r\n		$vbphrase[poll]<span class=\"normal\">: $pollinfo[question]</span>\r\n	</td>\r\n</tr>\r\n<if condition=\"$show[\'pollenddate\']\">\r\n<tr>\r\n	<td class=\"thead\" align=\"center\" style=\"font-weight:normal\"><phrase 1=\"$pollenddate\" 2=\"$pollendtime\">$vbphrase[this_poll_will_close_on_x_at_y]</phrase></td>\r\n</tr>\r\n</if>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n\r\n			<if condition=\"$show[\'publicwarning\']\">\r\n			<div class=\"fieldset\">$vbphrase[public_poll_users_see_choices]</div>\r\n			</if>\r\n\r\n			<fieldset class=\"fieldset\">\r\n				<legend>$vbphrase[poll_options]</legend>\r\n				<div style=\"padding:$stylevar[formspacer]px\">\r\n					<div style=\"margin-bottom:$stylevar[formspacer]px\"><strong>$pollinfo[question]</strong></div>\r\n					$pollbits\r\n				</div>\r\n			</fieldset>\r\n\r\n			<div>\r\n				<span style=\"float:$stylevar[right]\"><a href=\"poll.php?$session[sessionurl]do=showresults&amp;pollid=$pollinfo[pollid]\">$vbphrase[view_poll_results]</a></span>\r\n				<input type=\"submit\" class=\"button\" value=\"$vbphrase[vote_now]\" />\r\n			</div>\r\n\r\n		</div>\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>\r\n\r\n<br />', 'template', 1208876587, 'vBulletin Solutions', '3.7.0 Release Candidate 4', 'vbulletin'),
(349, -1, 'polloption_multiple', '<div><label for=\\\"cb_optionnumber_$option[number]\\\"><input type=\\\"checkbox\\\" name=\\\"optionnumber[$option[number]]\\\" value=\\\"yes\\\" id=\\\"cb_optionnumber_$option[number]\\\" />$option[question]</label></div>\r\n', '<div><label for=\"cb_optionnumber_$option[number]\"><input type=\"checkbox\" name=\"optionnumber[$option[number]]\" value=\"yes\" id=\"cb_optionnumber_$option[number]\" />$option[question]</label></div>\r\n', 'template', 1069785015, 'vBulletin Solutions', '', 'vbulletin'),
(350, -1, 'pollpreview', '<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[poll_preview]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"alt1\\\">\r\n		<p><strong>$previewquestion</strong></p>\r\n		<div>$vbphrase[options]:<br />$pollpreviewbits</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />\r\n', '<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">$vbphrase[poll_preview]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"alt1\">\r\n		<p><strong>$previewquestion</strong></p>\r\n		<div>$vbphrase[options]:<br />$pollpreviewbits</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />\r\n', 'template', 1070526896, 'vBulletin Solutions', '', 'vbulletin'),
(351, -1, 'pollresult', '<tr>\r\n	<td class=\\\"alt1\\\" width=\\\"75%\\\">\r\n		\".(($option[\'uservote\']) ? (\"\r\n			<em>$option[question]</em>\r\n		\") : (\"\r\n			$option[question]\r\n		\")).\"\r\n		\".(($show[\'pollvoters\']) ? (\"<div class=\\\"alt2 smallfont\\\" style=\\\"border:inset 1px; margin-top:$stylevar[cellpadding]px; padding:$stylevar[cellpadding]px\\\">$names</div>\") : (\"\")).\"\r\n	</td>\r\n	<td class=\\\"alt2\\\" nowrap=\\\"nowrap\\\">\r\n		<img src=\\\"$stylevar[imgdir_poll]/bar$option[graphicnumber]-$option[open].gif\\\" alt=\\\"\\\" width=\\\"3\\\" height=\\\"10\\\"\r\n		/><img src=\\\"$stylevar[imgdir_poll]/bar$option[graphicnumber].gif\\\" alt=\\\"\\\" width=\\\"$option[barnumber]\\\" height=\\\"10\\\"\r\n		/><img src=\\\"$stylevar[imgdir_poll]/bar$option[graphicnumber]-$option[close].gif\\\" alt=\\\"\\\" width=\\\"3\\\" height=\\\"10\\\"\r\n		/><img src=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'cleargifurl\'] . \"\\\" alt=\\\"\\\" width=\\\"$option[remainder]\\\" height=\\\"10\\\" />\r\n	</td>\r\n	<td class=\\\"alt1\\\" width=\\\"12%\\\" align=\\\"center\\\" title=\\\"$vbphrase[votes]\\\" nowrap=\\\"nowrap\\\"><strong>$option[votes]</strong></td>\r\n	<td class=\\\"alt2\\\" width=\\\"13%\\\" align=\\\"$stylevar[right]\\\" nowrap=\\\"nowrap\\\">$option[percent]%</td>\r\n</tr>\r\n', '<tr>\r\n	<td class=\"alt1\" width=\"75%\">\r\n		<if condition=\"$option[\'uservote\']\">\r\n			<em>$option[question]</em>\r\n		<else />\r\n			$option[question]\r\n		</if>\r\n		<if condition=\"$show[\'pollvoters\']\"><div class=\"alt2 smallfont\" style=\"border:inset 1px; margin-top:$stylevar[cellpadding]px; padding:$stylevar[cellpadding]px\">$names</div></if>\r\n	</td>\r\n	<td class=\"alt2\" nowrap=\"nowrap\">\r\n		<img src=\"$stylevar[imgdir_poll]/bar$option[graphicnumber]-$option[open].gif\" alt=\"\" width=\"3\" height=\"10\"\r\n		/><img src=\"$stylevar[imgdir_poll]/bar$option[graphicnumber].gif\" alt=\"\" width=\"$option[barnumber]\" height=\"10\"\r\n		/><img src=\"$stylevar[imgdir_poll]/bar$option[graphicnumber]-$option[close].gif\" alt=\"\" width=\"3\" height=\"10\"\r\n		/><img src=\"$vboptions[cleargifurl]\" alt=\"\" width=\"$option[remainder]\" height=\"10\" />\r\n	</td>\r\n	<td class=\"alt1\" width=\"12%\" align=\"center\" title=\"$vbphrase[votes]\" nowrap=\"nowrap\"><strong>$option[votes]</strong></td>\r\n	<td class=\"alt2\" width=\"13%\" align=\"$stylevar[right]\" nowrap=\"nowrap\">$option[percent]%</td>\r\n</tr>\r\n', 'template', 1201278148, 'vBulletin Solutions', '3.7.0 Beta 5', 'vbulletin'),
(352, -1, 'pollresults', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $vbphrase[view_poll_results]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n$pollresults\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n<title>$vboptions[bbtitle] - $vbphrase[view_poll_results]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n$pollresults\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', 'template', 1195729862, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
(353, -1, 'pollresults_table', '<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\" colspan=\\\"4\\\">\r\n		\".(($show[\'editpoll\']) ? (\"<span class=\\\"smallfont\\\" style=\\\"float:$stylevar[right]\\\"><a href=\\\"poll.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=polledit&amp;pollid=$pollinfo[pollid]\\\">$vbphrase[edit_poll]</a></span>\") : (\"\")).\"\r\n		$vbphrase[view_poll_results]<span class=\\\"normal\\\">: $pollinfo[question]</span>\r\n	</td>\r\n</tr>\r\n\".(($show[\'pollenddate\']) ? (\"\r\n<tr>\r\n	<td class=\\\"thead\\\" colspan=\\\"4\\\" align=\\\"center\\\" style=\\\"font-weight:normal\\\">\" . construct_phrase(\"$vbphrase[this_poll_will_close_on_x_at_y]\", \"$pollenddate\", \"$pollendtime\") . \"</td>\r\n</tr>\r\n\") : (\"\")).\"\r\n$pollbits\r\n<tr>\r\n	<td class=\\\"tfoot\\\" colspan=\\\"4\\\" align=\\\"center\\\"><span class=\\\"smallfont\\\">\".(($show[\'multiple\']) ? (\"$vbphrase[multiple_choice_poll] \") : (\"\")).\"$vbphrase[voters]: <strong>$pollinfo[numbervotes]</strong>. $pollstatus</span></td>\r\n</tr>\r\n</table>\r\n\r\n<br />', '<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\" colspan=\"4\">\r\n		<if condition=\"$show[\'editpoll\']\"><span class=\"smallfont\" style=\"float:$stylevar[right]\"><a href=\"poll.php?$session[sessionurl]do=polledit&amp;pollid=$pollinfo[pollid]\">$vbphrase[edit_poll]</a></span></if>\r\n		$vbphrase[view_poll_results]<span class=\"normal\">: $pollinfo[question]</span>\r\n	</td>\r\n</tr>\r\n<if condition=\"$show[\'pollenddate\']\">\r\n<tr>\r\n	<td class=\"thead\" colspan=\"4\" align=\"center\" style=\"font-weight:normal\"><phrase 1=\"$pollenddate\" 2=\"$pollendtime\">$vbphrase[this_poll_will_close_on_x_at_y]</phrase></td>\r\n</tr>\r\n</if>\r\n$pollbits\r\n<tr>\r\n	<td class=\"tfoot\" colspan=\"4\" align=\"center\"><span class=\"smallfont\"><if condition=\"$show[\'multiple\']\">$vbphrase[multiple_choice_poll] </if>$vbphrase[voters]: <strong>$pollinfo[numbervotes]</strong>. $pollstatus</span></td>\r\n</tr>\r\n</table>\r\n\r\n<br />', 'template', 1105552570, 'vBulletin Solutions', '3.5.0 Beta 1', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(354, -1, 'postbit', '$template_hook[postbit_start]\r\n<table class=\\\"tborder\\\" id=\\\"post$post[postid]\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"thead\\\" $post[scrolltothis]>\r\n		<div class=\\\"normal\\\" style=\\\"float:$stylevar[right]\\\">\r\n			&nbsp;\r\n			\".(($show[\'postcount\']) ? (\"#<a href=\\\"showpost.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"p=$post[postid]&amp;postcount=$post[postcount]\\\" target=\\\"new\\\" rel=\\\"nofollow\\\" id=\\\"postcount$post[postid]\\\" name=\\\"$post[postcount]\\\"><strong>$post[postcount]</strong></a> &nbsp;\") : (\"\")).\"\r\n			\".(($show[\'reputationlink\']) ? (\"\r\n				<span id=\\\"reputationmenu_$post[postid]\\\"><a href=\\\"reputation.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"p=$post[postid]\\\" rel=\\\"nofollow\\\" id=\\\"reputation_$post[postid]\\\"><img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_button]/reputation.gif\\\" alt=\\\"\" . construct_phrase(\"$vbphrase[add_to_xs_reputation]\", \"$post[username]\") . \"\\\" border=\\\"0\\\" /></a></span>\r\n				\".(($show[\'popups\']) ? (\"<script type=\\\"text/javascript\\\"> vbrep_register(\\\"$post[postid]\\\")</script>\") : (\"\")).\"&nbsp;\r\n			\") : (\"\")).\"\r\n			\".(($show[\'infractionlink\']) ? (\"<a href=\\\"infraction.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=report&amp;p=$post[postid]\\\" rel=\\\"nofollow\\\"><img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_button]/infraction.gif\\\" alt=\\\"\" . construct_phrase(\"$vbphrase[add_infraction_for_x]\", \"$post[username]\") . \"\\\" border=\\\"0\\\" /></a> &nbsp;\") : (\"\")).\"\r\n			\".(($show[\'reportlink\']) ? (\"<a href=\\\"report.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"p=$post[postid]\\\" rel=\\\"nofollow\\\"><img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_button]/report.gif\\\" alt=\\\"$vbphrase[report_bad_post]\\\" border=\\\"0\\\" /></a> &nbsp;\") : (\"\")).\"\r\n			$post[iplogged]\r\n			\".(($show[\'inlinemod\']) ? (\"\r\n			<input type=\\\"checkbox\\\" name=\\\"plist[$postid]\\\" id=\\\"plist_$postid\\\" style=\\\"vertical-align:middle; padding:0px; margin:0px 0px 0px 5px\\\" value=\\\"$post[checkbox_value]\\\" />\r\n			\") : (\"\")).\"\r\n		</div>\r\n\r\n		<div class=\\\"normal\\\">\r\n			<!-- status icon and date -->\r\n			<a name=\\\"post$post[postid]\\\"><img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_statusicon]/post_$post[statusicon].gif\\\" alt=\\\"$post[statustitle]\\\" border=\\\"0\\\" /></a>\r\n			\".((!$show[\'announcement\']) ? (\"\r\n				$post[postdate]\".((!$show[\'detailedtime\']) ? (\", $post[posttime]\") : (\"\")).\"\r\n			\") : (\"\r\n				\" . construct_phrase(\"$vbphrase[x_until_y]\", \"$post[startdate]\", \"$post[enddate]\") . \"\r\n			\")).\"\r\n			$post[firstnewinsert]\r\n			<!-- / status icon and date -->\r\n		</div>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"alt2\\\" style=\\\"padding:0px\\\">\r\n		<!-- user info -->\r\n		<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[cellpadding]\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n		<tr>\r\n			\".(($show[\'avatar\']) ? (\"<td class=\\\"alt2\\\"><a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$post[userid]\\\"><img src=\\\"$post[avatarurl]\\\" $post[avwidth] $post[avheight] alt=\\\"\" . construct_phrase(\"$vbphrase[xs_avatar]\", \"$post[username]\") . \"\\\" border=\\\"0\\\" /></a></td>\") : (\"\")).\"\r\n			<td nowrap=\\\"nowrap\\\">\r\n\r\n				<div id=\\\"postmenu_$post[postid]\\\">\r\n					\".(($show[\'profile\']) ? (\"\r\n					<a class=\\\"bigusername\\\" href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$post[userid]\\\">$post[musername]</a>\r\n					$post[onlinestatus]\r\n					<script type=\\\"text/javascript\\\"> vbmenu_register(\\\"postmenu_$post[postid]\\\", true); </script>\r\n					\") : (\"\r\n					$post[musername]\r\n					\")).\"\r\n				</div>\r\n\r\n				\".(($post[\'usertitle\']) ? (\"<div class=\\\"smallfont\\\">$post[usertitle]</div>\") : (\"\")).\"\r\n				\".(($post[\'rank\']) ? (\"<div class=\\\"smallfont\\\">$post[rank]</div>\") : (\"\")).\"\r\n				$template_hook[postbit_userinfo_left]\r\n\r\n			</td>\r\n			<td width=\\\"100%\\\">&nbsp;</td>\r\n			<td valign=\\\"top\\\" nowrap=\\\"nowrap\\\">\r\n\r\n				<div class=\\\"smallfont\\\">\r\n					\".(($post[\'joindate\']) ? (\"<div>$vbphrase[join_date]: $post[joindate]</div>\") : (\"\")).\"\r\n					\".(($post[\'field2\']) ? (\"<div>$vbphrase[location_perm]: $post[field2]</div>\") : (\"\")).\"\r\n					\".(($post[\'age\']) ? (\"<div>$vbphrase[age]: $post[age]</div>\") : (\"\")).\"\r\n					<div>\r\n						$vbphrase[posts]: $post[posts]\r\n					</div>\r\n					$template_hook[postbit_userinfo_right_after_posts]\r\n					\".(($show[\'infraction\']) ? (\"<div>$vbphrase[infractions]: $post[warnings]/$post[infractions] ($post[ipoints])</div>\") : (\"\")).\"\r\n					\".(($show[\'reputation\']) ? (\"\".(($show[\'reppower\']) ? (\"$vbphrase[reppower]: <span id=\\\"reppower_$post[postid]_$post[userid]\\\">$post[reppower]</span> \") : (\"\")).\"<div><span id=\\\"repdisplay_$post[postid]_$post[userid]\\\">$post[reputationdisplay]</span></div>\") : (\"\")).\"\r\n					$template_hook[postbit_userinfo_right]\r\n					<div>$post[icqicon] $post[aimicon] $post[msnicon] $post[yahooicon] $post[skypeicon]</div>\r\n				</div>\r\n\r\n			</td>\r\n		</tr>\r\n		</table>\r\n		<!-- / user info -->\r\n	</td>\r\n</tr>\r\n<tr>\r\n	\".(($show[\'moderated\']) ? (\"\r\n	<td class=\\\"alt2\\\" id=\\\"td_post_$post[postid]\\\">\r\n	\") : (\"\r\n	<td class=\\\"alt1\\\" id=\\\"td_post_$post[postid]\\\">\r\n	\")).\"	\r\n	<!-- message, attachments, sig -->\r\n\r\n		$template_hook[postbit_messagearea_start]\r\n\r\n		\".(($show[\'messageicon\'] OR $post[\'title\']) ? (\"\r\n			<!-- icon and