" name=\"$post[postcount]\"><strong>$post[postcount]</strong></a> &nbsp;</if>\r\n			<if condition=\"$show[\'reputationlink\']\">\r\n				<span id=\"reputationmenu_$post[postid]\"><a href=\"reputation.php?$session[sessionurl]p=$post[postid]\" rel=\"nofollow\" id=\"reputation_$post[postid]\"><img class=\"inlineimg\" src=\"$stylevar[imgdir_button]/reputation.gif\" alt=\"<phrase 1=\"$post[username]\">$vbphrase[add_to_xs_reputation]</phrase>\" border=\"0\" /></a></span>\r\n				<if condition=\"$show[\'popups\']\"><script type=\"text/javascript\"> vbrep_register(\"$post[postid]\")</script></if>&nbsp;\r\n			</if>\r\n			<if condition=\"$show[\'infractionlink\']\"><a href=\"infraction.php?$session[sessionurl]do=report&amp;p=$post[postid]\" rel=\"nofollow\"><img class=\"inlineimg\" src=\"$stylevar[imgdir_button]/infraction.gif\" alt=\"<phrase 1=\"$post[username]\">$vbphrase[add_infraction_for_x]</phrase>\" border=\"0\" /></a> &nbsp;</if>\r\n			<if condition=\"$show[\'reportlink\']\"><a href=\"report.php?$session[sessionurl]p=$post[postid]\" rel=\"nofollow\"><img class=\"inlineimg\" src=\"$stylevar[imgdir_button]/report.gif\" alt=\"$vbphrase[report_bad_post]\" border=\"0\" /></a> &nbsp;</if>\r\n			$post[iplogged]\r\n			<if condition=\"$show[\'inlinemod\']\">\r\n			<input type=\"checkbox\" name=\"plist[$postid]\" id=\"plist_$postid\" style=\"vertical-align:middle; padding:0px; margin:0px 0px 0px 5px\" value=\"$post[checkbox_value]\" />\r\n			</if>\r\n		</div>\r\n\r\n		<div class=\"normal\">\r\n			<!-- status icon and date -->\r\n			<a name=\"post$post[postid]\"><img class=\"inlineimg\" src=\"$stylevar[imgdir_statusicon]/post_$post[statusicon].gif\" alt=\"$post[statustitle]\" border=\"0\" /></a>\r\n			<if condition=\"!$show[\'announcement\']\">\r\n				$post[postdate]<if condition=\"!$show[\'detailedtime\']\">, $post[posttime]</if>\r\n			<else />\r\n				<phrase 1=\"$post[startdate]\" 2=\"$post[enddate]\">$vbphrase[x_until_y]</phrase>\r\n			</if>\r\n			$post[firstnewinsert]\r\n			<!-- / status icon and date -->\r\n		</div>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"alt2\" style=\"padding:0px\">\r\n		<!-- user info -->\r\n		<table cellpadding=\"0\" cellspacing=\"$stylevar[cellpadding]\" border=\"0\" width=\"100%\">\r\n		<tr>\r\n			<if condition=\"$show[\'avatar\']\"><td class=\"alt2\"><a href=\"member.php?$session[sessionurl]u=$post[userid]\"><img src=\"$post[avatarurl]\" $post[avwidth] $post[avheight] alt=\"<phrase 1=\"$post[username]\">$vbphrase[xs_avatar]</phrase>\" border=\"0\" /></a></td></if>\r\n			<td nowrap=\"nowrap\">\r\n\r\n				<div id=\"postmenu_$post[postid]\">\r\n					<if condition=\"$show[\'profile\']\">\r\n					<a class=\"bigusername\" href=\"member.php?$session[sessionurl]u=$post[userid]\">$post[musername]</a>\r\n					$post[onlinestatus]\r\n					<script type=\"text/javascript\"> vbmenu_register(\"postmenu_$post[postid]\", true); </script>\r\n					<else />\r\n					$post[musername]\r\n					</if>\r\n				</div>\r\n\r\n				<if condition=\"$post[\'usertitle\']\"><div class=\"smallfont\">$post[usertitle]</div></if>\r\n				<if condition=\"$post[\'rank\']\"><div class=\"smallfont\">$post[rank]</div></if>\r\n				$template_hook[postbit_userinfo_left]\r\n\r\n			</td>\r\n			<td width=\"100%\">&nbsp;</td>\r\n			<td valign=\"top\" nowrap=\"nowrap\">\r\n\r\n				<div class=\"smallfont\">\r\n					<if condition=\"$post[\'joindate\']\"><div>$vbphrase[join_date]: $post[joindate]</div></if>\r\n					<if condition=\"$post[\'field2\']\"><div>$vbphrase[location_perm]: $post[field2]</div></if>\r\n					<if condition=\"$post[\'age\']\"><div>$vbphrase[age]: $post[age]</div></if>\r\n					<div>\r\n						$vbphrase[posts]: $post[posts]\r\n					</div>\r\n					$template_hook[postbit_userinfo_right_after_posts]\r\n					<if condition=\"$show[\'infraction\']\"><div>$vbphrase[infractions]: $post[warnings]/$post[infractions] ($post[ipoints])</div></if>\r\n					<if condition=\"$show[\'reputation\']\"><if condition=\"$show[\'reppower\']\">$vbphrase[reppower]: <span id=\"reppower_$post[postid]_$post[userid]\">$post[reppower]</span> </if><div><span id=\"repdisplay_$post[postid]_$post[userid]\">$post[reputationdisplay]</span></div></if>\r\n					$template_hook[postbit_userinfo_right]\r\n					<div>$post[icqicon] $post[aimicon] $post[msnicon] $post[yahooicon] $post[skypeicon]</div>\r\n				</div>\r\n\r\n			</td>\r\n		</tr>\r\n		</table>\r\n		<!-- / user info -->\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<if condition=\"$show[\'moderated\']\">\r\n	<td class=\"alt2\" id=\"td_post_$post[postid]\">\r\n	<else />\r\n	<td class=\"alt1\" id=\"td_post_$post[postid]\">\r\n	</if>	\r\n	<!-- message, attachments, sig -->\r\n\r\n		$template_hook[postbit_messagearea_start]\r\n\r\n		<if condition=\"$show[\'messageicon\'] OR $post[\'title\']\">\r\n			<!-- icon and title -->\r\n			<div class=\"smallfont\">\r\n				<if condition=\"$show[\'messageicon\']\"><img class=\"inlineimg\" src=\"$post[iconpath]\" alt=\"$post[icontitle]\" border=\"0\" /></if>\r\n				<if condition=\"$post[\'title\']\"><strong>$post[title]</strong></if>\r\n			</div>\r\n			<hr size=\"1\" style=\"color:$stylevar[tborder_bgcolor]; background-color:$stylevar[tborder_bgcolor]\" />\r\n			<!-- / icon and title -->\r\n		</if>\r\n\r\n		<!-- message -->\r\n		<div id=\"post_message_$post[postid]\">\r\n			$ad_location[ad_showthread_firstpost_start]\r\n			$post[message]\r\n		</div>\r\n		<!-- / message -->\r\n\r\n		<if condition=\"$show[\'attachments\']\">\r\n		<!-- attachments -->\r\n			<div style=\"padding:$stylevar[cellpadding]px\">\r\n\r\n			<if condition=\"$show[\'thumbnailattachment\']\">\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[attached_thumbnails]</legend>\r\n					<div style=\"padding:$stylevar[formspacer]px\">\r\n					$post[thumbnailattachments]\r\n					</div>\r\n				</fieldset>\r\n			</if>\r\n\r\n			<if condition=\"$show[\'imageattachment\']\">\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[attached_images]</legend>\r\n					<div style=\"padding:$stylevar[formspacer]px\">\r\n					$post[imageattachments]\r\n					</div>\r\n				</fieldset>\r\n			</if>\r\n\r\n			<if condition=\"$show[\'imageattachmentlink\']\">\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[attached_images]</legend>\r\n					<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n					$post[imageattachmentlinks]\r\n					</table>\r\n					</fieldset>\r\n			</if>\r\n\r\n			<if condition=\"$show[\'otherattachment\']\">\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[attached_files]</legend>\r\n					<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n					$post[otherattachments]\r\n					</table>\r\n				</fieldset>\r\n			</if>\r\n\r\n			<if condition=\"$show[\'moderatedattachment\']\">\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[attachments_pending_approval]</legend>\r\n					<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n					$post[moderatedattachments]\r\n					</table>\r\n				</fieldset>\r\n			</if>\r\n\r\n			</div>\r\n		<!-- / attachments -->\r\n		</if>\r\n\r\n		$template_hook[postbit_signature_start]\r\n		$ad_location[ad_showthread_firstpost_sig]\r\n\r\n		<if condition=\"$post[\'signature\']\">\r\n		<!-- sig -->\r\n			<div>\r\n				__________________<br />\r\n				$post[signature]\r\n			</div>\r\n		<!-- / sig -->\r\n		</if>\r\n\r\n		$template_hook[postbit_signature_end]\r\n\r\n		<if condition=\"$show[\'postedited\']\">\r\n		<!-- edit note -->\r\n			<div class=\"smallfont\">\r\n				<hr size=\"1\" style=\"color:$stylevar[tborder_bgcolor]; background-color:$stylevar[tborder_bgcolor]\" />\r\n				<em>\r\n					<if condition=\"$show[\'postedithistory\']\">\r\n						<phrase 1=\"$post[edit_username]\" 2=\"$post[edit_date]\" 3=\"$post[edit_time]\" 4=\"posthistory.php?$session[sessionurl]p=$post[postid]\">$vbphrase[last_edited_link_by_x_on_y_at_z_postid]</phrase>\r\n					<else />\r\n						<phrase 1=\"$post[edit_username]\" 2=\"$post[edit_date]\" 3=\"$post[edit_time]\">$vbphrase[last_edited_by_x_on_y_at_z]</phrase>\r\n					</if>\r\n					<if condition=\"$post[\'edit_reason\']\">\r\n						$vbphrase[reason]: $post[edit_reason]\r\n					</if>\r\n				</em>\r\n			</div>\r\n		<!-- / edit note -->\r\n		</if>\r\n\r\n		<div style=\"margin-top: 10px\" align=\"$stylevar[right]\">\r\n			<!-- controls -->\r\n			<if condition=\"$post[\'editlink\']\">\r\n				<img style=\"display: none\" id=\"progress_$postid\" src=\"$stylevar[imgdir_misc]/progress.gif\" alt=\"$vbphrase[loading_editor_please_wait]\" />\r\n				<a href=\"$post[editlink]\" name=\"vB::QuickEdit::$post[postid]\"><img src=\"$stylevar[imgdir_button]/edit.gif\" alt=\"$vbphrase[edit_delete_message]\" border=\"0\" /></a>\r\n			</if>\r\n			<if condition=\"$post[\'forwardlink\']\">\r\n				<a href=\"$post[forwardlink]\"><img src=\"$stylevar[imgdir_button]/forward.gif\" alt=\"$vbphrase[forward_message]\" border=\"0\" /></a>\r\n			</if>\r\n			<if condition=\"$post[\'replylink\']\">\r\n				<a href=\"$post[replylink]\" rel=\"nofollow\"><img src=\"$stylevar[imgdir_button]/<if condition=\"$post[\'forwardlink\']\">reply_small<else />quote</if>.gif\" alt=\"$vbphrase[reply_with_quote]\" border=\"0\" /></a>\r\n			</if>\r\n			<if condition=\"$show[\'multiquote_post\']\">\r\n				<a href=\"$post[replylink]\" rel=\"nofollow\" onclick=\"return false\"><img src=\"$stylevar[imgdir_button]/multiquote_<if condition=\"$show[\'multiquote_selected\']\">on<else />off</if>.gif\" alt=\"$vbphrase[multi_quote_this_message]\" border=\"0\" id=\"mq_$post[postid]\" /></a>\r\n			</if>\r\n			<if condition=\"$show[\'quickreply\'] AND !$show[\'threadedmode\']\">\r\n				<a href=\"$post[replylink]\" rel=\"nofollow\" id=\"qr_$post[postid]\" onclick=\"return false\"><img src=\"$stylevar[imgdir_button]/quickreply.gif\" alt=\"$vbphrase[quick_reply_to_this_message]\" border=\"0\" /></a>\r\n			</if>\r\n			<if condition=\"$show[\'moderated\']\">\r\n				<img src=\"$stylevar[imgdir_misc]/moderated.gif\" alt=\"$vbphrase[moderated_post]\" border=\"0\" />\r\n			</if>\r\n			<if condition=\"$show[\'spam\']\">\r\n				<img src=\"$stylevar[imgdir_misc]/spam_detected.png\" alt=\"$vbphrase[spam_post]\" border=\"0\" />\r\n			</if>\r\n			<if condition=\"$show[\'deletedpost\']\">\r\n				<if condition=\"$show[\'managepost\']\">\r\n					<a href=\"postings.php?$session[sessionurl]do=managepost&amp;p=$post[postid]\"><img src=\"$stylevar[imgdir_misc]/trashcan.gif\" alt=\"$vbphrase[manage]\" border=\"0\" /></a>\r\n				<else />\r\n					<img src=\"$stylevar[imgdir_misc]/trashcan.gif\" alt=\"$vbphrase[deleted_post]\" border=\"0\" />\r\n				</if>\r\n			</if>\r\n			<if condition=\"$show[\'redcard\']\">\r\n				<a href=\"infraction.php?$session[sessionurl]do=view&amp;p=$post[postid]\"><img src=\"$stylevar[imgdir_button]/redcard.gif\" alt=\"$vbphrase[received_infraction]\" border=\"0\" /></a>\r\n			<else />\r\n				<if condition=\"$show[\'yellowcard\']\">\r\n					<a href=\"infraction.php?$session[sessionurl]do=view&amp;p=$post[postid]\"><img src=\"$stylevar[imgdir_button]/yellowcard.gif\" alt=\"$vbphrase[received_warning]\" border=\"0\" /></a>\r\n				</if>\r\n			</if>\r\n			$template_hook[postbit_controls]\r\n			<!-- / controls -->\r\n		</div>\r\n\r\n	<!-- message, attachments, sig -->\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n$template_hook[postbit_end]\r\n\r\n<if condition=\"$show[\'profile\']\"> \r\n<!-- post $post[postid] popup menu -->\r\n<div class=\"vbmenu_popup\" id=\"postmenu_$post[postid]_menu\" style=\"display:none;\">\r\n	<table cellpadding=\"4\" cellspacing=\"1\" border=\"0\">\r\n	<tr>\r\n		<td class=\"thead\">$post[username]</td>\r\n	</tr>\r\n	<if condition=\"$show[\'profile\']\">\r\n		<tr><td class=\"vbmenu_option\"><a href=\"member.php?$session[sessionurl]u=$post[userid]\">$vbphrase[view_public_profile]</a></td></tr>\r\n	</if>\r\n	<if condition=\"$show[\'pmlink\']\">\r\n		<tr><td class=\"vbmenu_option\"><a href=\"private.php?$session[sessionurl]do=newpm&amp;u=$post[userid]\" rel=\"nofollow\"><phrase 1=\"$post[username]\">$vbphrase[send_private_message_to_x]</phrase></a></td></tr>\r\n	</if>\r\n	<if condition=\"$show[\'emaillink\']\">\r\n		<tr><td class=\"vbmenu_option\"><a href=\"sendmessage.php?$session[sessionurl]do=mailmember&amp;u=$post[userid]\" rel=\"nofollow\"><phrase 1=\"$post[username]\">$vbphrase[send_email_to_x]</phrase></a></td></tr>\r\n	</if>\r\n	<if condition=\"$show[\'homepage\']\">\r\n		<tr><td class=\"vbmenu_option\"><a href=\"$post[homepage]\"><phrase 1=\"$post[username]\">$vbphrase[visit_xs_homepage]</phrase></a></td></tr>\r\n	</if>\r\n	<if condition=\"$show[\'search\']\">\r\n		<tr><td class=\"vbmenu_option\"><a href=\"search.php?$session[sessionurl]do=finduser&amp;u=$post[userid]\" rel=\"nofollow\"><phrase 1=\"$post[username]\">$vbphrase[find_all_posts_by_x]</phrase></a></td></tr>\r\n	</if>\r\n	<if condition=\"$post[\'userid\'] AND $show[\'member\']\">\r\n	<tr><td class=\"vbmenu_option\"><a href=\"profile.php?$session[sessionurl]do=addlist&amp;userlist=buddy&amp;u=$post[userid]\"><phrase 1=\"$post[username]\">$vbphrase[add_x_to_contacts]</phrase></a></td></tr>\r\n	</if>\r\n	$template_hook[postbit_user_popup]\r\n	</table>\r\n</div>\r\n<!-- / post $post[postid] popup menu -->\r\n</if>', 'template', 1280350744, 'vBulletin Solutions', '3.8.7 Beta 1', 'vbulletin'),
(355, -1, 'postbit_attachment', '<tr>\r\n	<td><img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_attach]/$attachment[attachmentextension].gif\\\" alt=\\\"\" . construct_phrase(\"$vbphrase[file_type_x]\", \"$attachment[attachmentextension]\") . \"\\\" width=\\\"16\\\" height=\\\"16\\\" border=\\\"0\\\" style=\\\"vertical-align:baseline\\\" /></td>\r\n	<td><a href=\\\"attachment.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"attachmentid=$attachment[attachmentid]&amp;d=$attachment[dateline]\\\"\".(($show[\'newwindow\']) ? (\" target=\\\"_blank\\\"\") : (\"\")).\">$attachment[filename]</a> ($attachment[filesize]\".(($show[\'views\']) ? (\", \" . construct_phrase(\"$vbphrase[x_views]\", \"$attachment[counter]\") . \"\") : (\"\")).\")</td>\r\n</tr>', '<tr>\r\n	<td><img class=\"inlineimg\" src=\"$stylevar[imgdir_attach]/$attachment[attachmentextension].gif\" alt=\"<phrase 1=\"$attachment[attachmentextension]\">$vbphrase[file_type_x]</phrase>\" width=\"16\" height=\"16\" border=\"0\" style=\"vertical-align:baseline\" /></td>\r\n	<td><a href=\"attachment.php?$session[sessionurl]attachmentid=$attachment[attachmentid]&amp;d=$attachment[dateline]\"<if condition=\"$show[\'newwindow\']\"> target=\"_blank\"</if>>$attachment[filename]</a> ($attachment[filesize]<if condition=\"$show[\'views\']\">, <phrase 1=\"$attachment[counter]\">$vbphrase[x_views]</phrase></if>)</td>\r\n</tr>', 'template', 1219831366, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(356, -1, 'postbit_attachmentimage', '<img class=\\\"attach\\\" src=\\\"attachment.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"attachmentid=$attachment[attachmentid]&amp;stc=1&amp;d=$attachment[dateline]\\\" border=\\\"0\\\" alt=\\\"\\\" />&nbsp;', '<img class=\"attach\" src=\"attachment.php?$session[sessionurl]attachmentid=$attachment[attachmentid]&amp;stc=1&amp;d=$attachment[dateline]\" border=\"0\" alt=\"\" />&nbsp;', 'template', 1105654461, 'vBulletin Solutions', '3.5.0 Beta 1', 'vbulletin'),
(357, -1, 'postbit_attachmentmoderated', '<tr>\r\n	<td><img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_attach]/$attachment[attachmentextension].gif\\\" alt=\\\"\" . construct_phrase(\"$vbphrase[file_type_x]\", \"$attachment[attachmentextension]\") . \"\\\" width=\\\"16\\\" height=\\\"16\\\" border=\\\"0\\\" style=\\\"vertical-align:baseline\\\" /></td>\r\n	<td>\".(($show[\'modattachmentlink\']) ? (\"<a href=\\\"attachment.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"attachmentid=$attachment[attachmentid]&amp;d=$attachment[dateline]\\\"\".(($show[\'newwindow\']) ? (\" target=\\\"_blank\\\"\") : (\"\")).\">$attachment[filename]</a> ($attachment[filesize])\") : (\"$attachment[filename]\")).\"</td>\r\n</tr>', '<tr>\r\n	<td><img class=\"inlineimg\" src=\"$stylevar[imgdir_attach]/$attachment[attachmentextension].gif\" alt=\"<phrase 1=\"$attachment[attachmentextension]\">$vbphrase[file_type_x]</phrase>\" width=\"16\" height=\"16\" border=\"0\" style=\"vertical-align:baseline\" /></td>\r\n	<td><if condition=\"$show[\'modattachmentlink\']\"><a href=\"attachment.php?$session[sessionurl]attachmentid=$attachment[attachmentid]&amp;d=$attachment[dateline]\"<if condition=\"$show[\'newwindow\']\"> target=\"_blank\"</if>>$attachment[filename]</a> ($attachment[filesize])<else />$attachment[filename]</if></td>\r\n</tr>', 'template', 1151091065, 'vBulletin Solutions', '3.6.0 Beta 4', 'vbulletin'),
(358, -1, 'postbit_attachmentthumbnail', '\".(($show[\'cangetattachment\']) ? (\"\r\n<a href=\\\"attachment.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"attachmentid=$attachment[attachmentid]&amp;d=$attachment[dateline]\\\" rel=\\\"Lightbox_$post[postid]\\\" id=\\\"attachment$attachment[attachmentid]\\\"\".(($show[\'newwindow\']) ? (\" target=\\\"_blank\\\"\") : (\"\")).\"><img class=\\\"thumbnail\\\" src=\\\"attachment.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"attachmentid=$attachment[attachmentid]&amp;stc=1&amp;thumb=1&amp;d=$attachment[thumbnail_dateline]\\\" border=\\\"0\\\" alt=\\\"\" . construct_phrase(\"$vbphrase[image_larger_version_x_y_z]\", \"$attachment[filename]\", \"$attachment[counter]\", \"$attachment[filesize]\", \"$attachment[attachmentid]\") . \"\\\" /></a>\r\n&nbsp;\".(($show[\'br\']) ? (\"<br /><br />\") : (\"\")).\"\r\n\") : (\"\r\n<a href=\\\"attachment.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"attachmentid=$attachment[attachmentid]&amp;d=$attachment[dateline]\\\" rel=\\\"nofollow\\\" id=\\\"attach$attachment[attachmentid]\\\"><img class=\\\"thumbnail\\\" src=\\\"attachment.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"attachmentid=$attachment[attachmentid]&amp;stc=1&amp;thumb=1&amp;d=$attachment[thumbnail_dateline]\\\" border=\\\"0\\\" alt=\\\"$attachment[filename]\\\" /></a>\r\n&nbsp;\".(($show[\'br\']) ? (\"<br /><br />\") : (\"\")).\"\r\n\")).\"', '<if condition=\"$show[\'cangetattachment\']\">\r\n<a href=\"attachment.php?$session[sessionurl]attachmentid=$attachment[attachmentid]&amp;d=$attachment[dateline]\" rel=\"Lightbox_$post[postid]\" id=\"attachment$attachment[attachmentid]\"<if condition=\"$show[\'newwindow\']\"> target=\"_blank\"</if>><img class=\"thumbnail\" src=\"attachment.php?$session[sessionurl]attachmentid=$attachment[attachmentid]&amp;stc=1&amp;thumb=1&amp;d=$attachment[thumbnail_dateline]\" border=\"0\" alt=\"<phrase 1=\"$attachment[filename]\" 2=\"$attachment[counter]\" 3=\"$attachment[filesize]\" 4=\"$attachment[attachmentid]\">$vbphrase[image_larger_version_x_y_z]</phrase>\" /></a>\r\n&nbsp;<if condition=\"$show[\'br\']\"><br /><br /></if>\r\n<else />\r\n<a href=\"attachment.php?$session[sessionurl]attachmentid=$attachment[attachmentid]&amp;d=$attachment[dateline]\" rel=\"nofollow\" id=\"attach$attachment[attachmentid]\"><img class=\"thumbnail\" src=\"attachment.php?$session[sessionurl]attachmentid=$attachment[attachmentid]&amp;stc=1&amp;thumb=1&amp;d=$attachment[thumbnail_dateline]\" border=\"0\" alt=\"$attachment[filename]\" /></a>\r\n&nbsp;<if condition=\"$show[\'br\']\"><br /><br /></if>\r\n</if>', 'template', 1219929150, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(359, -1, 'postbit_automoderated', '<div id=\\\"post$postid\\\"> \r\n	<div style=\\\"padding: $stylevar[cellpadding]px; margin-bottom: $stylevar[formspacer]px; text-align: $stylevar[left];\\\" class=\\\"alt2 tborder\\\"> \r\n		<div style=\\\"float: $stylevar[right];\\\"> \r\n			<input type=\\\"button\\\" value=\\\"X\\\" class=\\\"button\\\" onclick=\\\"document.getElementById(\'post$postid\').style.display = \'none\';\\\" /> \r\n		</div> \r\n		<b>$post[username]</b><br/> \r\n		$vbphrase[post_has_been_automoderated] \r\n	</div> \r\n</div>', '<div id=\"post$postid\"> \r\n	<div style=\"padding: $stylevar[cellpadding]px; margin-bottom: $stylevar[formspacer]px; text-align: $stylevar[left];\" class=\"alt2 tborder\"> \r\n		<div style=\"float: $stylevar[right];\"> \r\n			<input type=\"button\" value=\"X\" class=\"button\" onclick=\"document.getElementById(\'post$postid\').style.display = \'none\';\" /> \r\n		</div> \r\n		<b>$post[username]</b><br/> \r\n		$vbphrase[post_has_been_automoderated] \r\n	</div> \r\n</div>', 'template', 1209557876, 'vBulletin Solutions', '3.7.1', 'vbulletin'),
(360, -1, 'postbit_deleted', '<table id=\\\"post$post[postid]\\\" class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr title=\\\"\" . construct_phrase(\"$vbphrase[post_x]\", \"$post[postid]\") . \"\\\">\r\n	<td class=\\\"thead\\\" style=\\\"font-weight:normal\\\" $post[scrolltothis]>\r\n		\".(($show[\'inlinemod\']) ? (\"\r\n			<input type=\\\"checkbox\\\" name=\\\"plist[$postid]\\\" id=\\\"plist_$postid\\\" style=\\\"float:$stylevar[right]; vertical-align:middle; padding:0px; margin:0px 0px 0px 5px\\\" value=\\\"$post[checkbox_value]\\\" onclick=\\\"inlineMod.toggle(this)\\\" />\r\n		\") : (\"\")).\"\r\n		\".(($show[\'viewpost\']) ? (\"<a style=\\\"float:$stylevar[right]\\\" href=\\\"showpost.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"p=$post[postid]\\\" target=\\\"_blank\\\" rel=\\\"nofollow\\\" onclick=\\\"return display_post($post[postid]);\\\">$vbphrase[view_post]</a>\") : (\"\")).\"\r\n		<a name=\\\"post$post[postid]\\\"><img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_statusicon]/post_$post[statusicon].gif\\\" alt=\\\"$post[statustitle]\\\" border=\\\"0\\\" /></a>\r\n		$post[postdate]\".((!$show[\'detailedtime\']) ? (\", $post[posttime]\") : (\"\")).\" $post[firstnewinsert]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"alt2\\\">\r\n		\".(($show[\'managepost\']) ? (\"<div class=\\\"smallfont\\\" style=\\\"float:$stylevar[right]\\\"><a href=\\\"postings.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=managepost&amp;p=$post[postid]\\\">$vbphrase[manage]</a></div>\") : (\"\")).\"\r\n		\".(($show[\'profile\']) ? (\"<a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$post[userid]\\\">$post[musername]</a>\") : (\"$post[musername]\")).\"\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"alt1\\\">\r\n\r\n		<div class=\\\"smallfont\\\">\r\n			\" . construct_phrase(\"$vbphrase[message_deleted_by_x]\", \"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$post[del_userid]\", \"$post[del_username]\") . \"\r\n			\".(($post[\'del_reason\']) ? (\"$vbphrase[reason]: <em>$post[del_reason]</em>\") : (\"\")).\"\r\n		</div>\r\n\r\n	</td>\r\n</tr>\r\n</table>', '<table id=\"post$post[postid]\" class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr title=\"<phrase 1=\"$post[postid]\">$vbphrase[post_x]</phrase>\">\r\n	<td class=\"thead\" style=\"font-weight:normal\" $post[scrolltothis]>\r\n		<if condition=\"$show[\'inlinemod\']\">\r\n			<input type=\"checkbox\" name=\"plist[$postid]\" id=\"plist_$postid\" style=\"float:$stylevar[right]; vertical-align:middle; padding:0px; margin:0px 0px 0px 5px\" value=\"$post[checkbox_value]\" onclick=\"inlineMod.toggle(this)\" />\r\n		</if>\r\n		<if condition=\"$show[\'viewpost\']\"><a style=\"float:$stylevar[right]\" href=\"showpost.php?$session[sessionurl]p=$post[postid]\" target=\"_blank\" rel=\"nofollow\" onclick=\"return display_post($post[postid]);\">$vbphrase[view_post]</a></if>\r\n		<a name=\"post$post[postid]\"><img class=\"inlineimg\" src=\"$stylevar[imgdir_statusicon]/post_$post[statusicon].gif\" alt=\"$post[statustitle]\" border=\"0\" /></a>\r\n		$post[postdate]<if condition=\"!$show[\'detailedtime\']\">, $post[posttime]</if> $post[firstnewinsert]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"alt2\">\r\n		<if condition=\"$show[\'managepost\']\"><div class=\"smallfont\" style=\"float:$stylevar[right]\"><a href=\"postings.php?$session[sessionurl]do=managepost&amp;p=$post[postid]\">$vbphrase[manage]</a></div></if>\r\n		<if condition=\"$show[\'profile\']\"><a href=\"member.php?$session[sessionurl]u=$post[userid]\">$post[musername]</a><else />$post[musername]</if>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"alt1\">\r\n\r\n		<div class=\"smallfont\">\r\n			<phrase 1=\"member.php?$session[sessionurl]u=$post[del_userid]\" 2=\"$post[del_username]\">$vbphrase[message_deleted_by_x]</phrase>\r\n			<if condition=\"$post[\'del_reason\']\">$vbphrase[reason]: <em>$post[del_reason]</em></if>\r\n		</div>\r\n\r\n	</td>\r\n</tr>\r\n</table>', 'template', 1183466945, 'vBulletin Solutions', '3.6.8', 'vbulletin'),
(361, -1, 'postbit_external', '<div>$post[message]</div>\r\n\r\n\".(($show[\'attachments\']) ? (\"\r\n	<br />\r\n	<div style=\\\"padding:$stylevar[cellpadding]px\\\">\r\n\r\n	\".(($show[\'thumbnailattachment\']) ? (\"\r\n		<fieldset class=\\\"fieldset\\\">\r\n			<legend>$vbphrase[attached_thumbnails]</legend>\r\n			<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n			$post[thumbnailattachments]\r\n			</div>\r\n		</fieldset>\r\n	\") : (\"\")).\"\r\n\r\n	\".(($show[\'imageattachment\']) ? (\"\r\n		<fieldset class=\\\"fieldset\\\">\r\n			<legend>$vbphrase[attached_images]</legend>\r\n			<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n			$post[imageattachments]\r\n			</div>\r\n		</fieldset>\r\n	\") : (\"\")).\"\r\n\r\n	\".(($show[\'imageattachmentlink\']) ? (\"\r\n		<fieldset class=\\\"fieldset\\\">\r\n			<legend>$vbphrase[attached_images]</legend>\r\n			<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n			$post[imageattachmentlinks]\r\n			</table>\r\n			</fieldset>\r\n	\") : (\"\")).\"\r\n\r\n	\".(($show[\'otherattachment\']) ? (\"\r\n		<fieldset class=\\\"fieldset\\\">\r\n			<legend>$vbphrase[attached_files]</legend>\r\n			<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n			$post[otherattachments]\r\n			</table>\r\n		</fieldset>\r\n	\") : (\"\")).\"\r\n\r\n	</div>\r\n\") : (\"\")).\"', '<div>$post[message]</div>\r\n\r\n<if condition=\"$show[\'attachments\']\">\r\n	<br />\r\n	<div style=\"padding:$stylevar[cellpadding]px\">\r\n\r\n	<if condition=\"$show[\'thumbnailattachment\']\">\r\n		<fieldset class=\"fieldset\">\r\n			<legend>$vbphrase[attached_thumbnails]</legend>\r\n			<div style=\"padding:$stylevar[formspacer]px\">\r\n			$post[thumbnailattachments]\r\n			</div>\r\n		</fieldset>\r\n	</if>\r\n\r\n	<if condition=\"$show[\'imageattachment\']\">\r\n		<fieldset class=\"fieldset\">\r\n			<legend>$vbphrase[attached_images]</legend>\r\n			<div style=\"padding:$stylevar[formspacer]px\">\r\n			$post[imageattachments]\r\n			</div>\r\n		</fieldset>\r\n	</if>\r\n\r\n	<if condition=\"$show[\'imageattachmentlink\']\">\r\n		<fieldset class=\"fieldset\">\r\n			<legend>$vbphrase[attached_images]</legend>\r\n			<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n			$post[imageattachmentlinks]\r\n			</table>\r\n			</fieldset>\r\n	</if>\r\n\r\n	<if condition=\"$show[\'otherattachment\']\">\r\n		<fieldset class=\"fieldset\">\r\n			<legend>$vbphrase[attached_files]</legend>\r\n			<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n			$post[otherattachments]\r\n			</table>\r\n		</fieldset>\r\n	</if>\r\n\r\n	</div>\r\n</if>', 'template', 1154367421, 'vBulletin Solutions', '3.6.0', 'vbulletin'),
(362, -1, 'postbit_ignore', '<table id=\\\"post$post[postid]\\\" class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr title=\\\"\" . construct_phrase(\"$vbphrase[post_x]\", \"$post[postid]\") . \"\\\">\r\n	<td class=\\\"thead\\\" style=\\\"font-weight:normal\\\" $post[scrolltothis]>\r\n		\".(($show[\'inlinemod\']) ? (\"\r\n			<input type=\\\"checkbox\\\" name=\\\"plist[$postid]\\\" id=\\\"plist_$postid\\\" style=\\\"float:$stylevar[right]; vertical-align:middle; padding:0px; margin:0px 0px 0px 5px\\\" value=\\\"$post[checkbox_value]\\\" onclick=\\\"inlineMod.toggle(this)\\\" />\r\n		\") : (\"\")).\"\r\n		<a style=\\\"float:$stylevar[right]\\\" href=\\\"showpost.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"p=$post[postid]\\\" target=\\\"_blank\\\" rel=\\\"nofollow\\\" onclick=\\\"return display_post($post[postid]);\\\">$vbphrase[view_post]</a>\r\n		<a name=\\\"post$post[postid]\\\"><img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_statusicon]/post_$post[statusicon].gif\\\" alt=\\\"$post[statustitle]\\\" border=\\\"0\\\" /></a>\r\n		$post[postdate]\".((!$show[\'detailedtime\']) ? (\", $post[posttime]\") : (\"\")).\" $post[firstnewinsert]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"alt2\\\">\r\n		<div class=\\\"smallfont\\\" style=\\\"float:$stylevar[right]\\\"><a href=\\\"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"userlist=ignore&amp;do=removelist&amp;u=$post[userid]\\\">$vbphrase[remove_user_from_ignore_list]</a></div>\r\n		<a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$post[userid]\\\">$post[musername]</a>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"alt1\\\">\r\n		\".(($show[\'moderated\']) ? (\"\r\n			<div style=\\\"float:$stylevar[right]\\\"><img src=\\\"$stylevar[imgdir_misc]/moderated.gif\\\" alt=\\\"$vbphrase[moderated_post]\\\" border=\\\"0\\\" /></div>\r\n		\") : (\"\")).\"\r\n		\".(($show[\'deletedpost\']) ? (\"\r\n			<div style=\\\"float:$stylevar[right]\\\"><img src=\\\"$stylevar[imgdir_misc]/trashcan.gif\\\" alt=\\\"$vbphrase[deleted_post]\\\" border=\\\"0\\\" /></div>\r\n		\") : (\"\")).\"\r\n		<div class=\\\"smallfont\\\">\r\n			\" . construct_phrase(\"$vbphrase[message_hidden_x_on_ignore_list]\", \"$post[username]\", \"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=ignorelist\") . \"\r\n		</div>\r\n\r\n	</td>\r\n</tr>\r\n<!-- / main bar -->\r\n</table>', '<table id=\"post$post[postid]\" class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr title=\"<phrase 1=\"$post[postid]\">$vbphrase[post_x]</phrase>\">\r\n	<td class=\"thead\" style=\"font-weight:normal\" $post[scrolltothis]>\r\n		<if condition=\"$show[\'inlinemod\']\">\r\n			<input type=\"checkbox\" name=\"plist[$postid]\" id=\"plist_$postid\" style=\"float:$stylevar[right]; vertical-align:middle; padding:0px; margin:0px 0px 0px 5px\" value=\"$post[checkbox_value]\" onclick=\"inlineMod.toggle(this)\" />\r\n		</if>\r\n		<a style=\"float:$stylevar[right]\" href=\"showpost.php?$session[sessionurl]p=$post[postid]\" target=\"_blank\" rel=\"nofollow\" onclick=\"return display_post($post[postid]);\">$vbphrase[view_post]</a>\r\n		<a name=\"post$post[postid]\"><img class=\"inlineimg\" src=\"$stylevar[imgdir_statusicon]/post_$post[statusicon].gif\" alt=\"$post[statustitle]\" border=\"0\" /></a>\r\n		$post[postdate]<if condition=\"!$show[\'detailedtime\']\">, $post[posttime]</if> $post[firstnewinsert]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"alt2\">\r\n		<div class=\"smallfont\" style=\"float:$stylevar[right]\"><a href=\"profile.php?$session[sessionurl]userlist=ignore&amp;do=removelist&amp;u=$post[userid]\">$vbphrase[remove_user_from_ignore_list]</a></div>\r\n		<a href=\"member.php?$session[sessionurl]u=$post[userid]\">$post[musername]</a>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"alt1\">\r\n		<if condition=\"$show[\'moderated\']\">\r\n			<div style=\"float:$stylevar[right]\"><img src=\"$stylevar[imgdir_misc]/moderated.gif\" alt=\"$vbphrase[moderated_post]\" border=\"0\" /></div>\r\n		</if>\r\n		<if condition=\"$show[\'deletedpost\']\">\r\n			<div style=\"float:$stylevar[right]\"><img src=\"$stylevar[imgdir_misc]/trashcan.gif\" alt=\"$vbphrase[deleted_post]\" border=\"0\" /></div>\r\n		</if>\r\n		<div class=\"smallfont\">\r\n			<phrase 1=\"$post[username]\" 2=\"profile.php?$session[sessionurl]do=ignorelist\">$vbphrase[message_hidden_x_on_ignore_list]</phrase>\r\n		</div>\r\n\r\n	</td>\r\n</tr>\r\n<!-- / main bar -->\r\n</table>', 'template', 1196095083, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(363, -1, 'postbit_ignore_global', '<table id=\\\"post$post[postid]\\\" class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr title=\\\"\" . construct_phrase(\"$vbphrase[post_x]\", \"$post[postid]\") . \"\\\">\r\n	<td class=\\\"thead\\\" style=\\\"font-weight:normal\\\" $post[scrolltothis]>\r\n		\".(($show[\'inlinemod\']) ? (\"\r\n			<input type=\\\"checkbox\\\" name=\\\"plist[$postid]\\\" id=\\\"plist_$postid\\\" style=\\\"float:$stylevar[right]; vertical-align:middle; padding:0px; margin:0px 0px 0px 5px\\\" value=\\\"$post[checkbox_value]\\\" onclick=\\\"inlineMod.toggle(this)\\\" />\r\n		\") : (\"\")).\"\r\n		<a style=\\\"float:$stylevar[right]\\\" href=\\\"showpost.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"p=$post[postid]\\\" target=\\\"_blank\\\" rel=\\\"nofollow\\\" onclick=\\\"return display_post($post[postid]);\\\">$vbphrase[view_post]</a>\r\n		<a name=\\\"post$post[postid]\\\"><img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_statusicon]/post_$post[statusicon].gif\\\" alt=\\\"$post[statustitle]\\\" border=\\\"0\\\" /></a>\r\n		$post[postdate]\".((!$show[\'detailedtime\']) ? (\", $post[posttime]\") : (\"\")).\" $post[firstnewinsert]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"alt2\\\">\r\n		<a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$post[userid]\\\">$post[musername]</a>\r\n	</td>\r\n</tr>\r\n\r\n\r\n<tr>\r\n	<td class=\\\"alt1\\\">\r\n		\".(($show[\'moderated\']) ? (\"\r\n			<div style=\\\"float:$stylevar[right]\\\"><img src=\\\"$stylevar[imgdir_misc]/moderated.gif\\\" alt=\\\"$vbphrase[moderated_post]\\\" border=\\\"0\\\" /></div>\r\n		\") : (\"\")).\"\r\n		\".(($show[\'deletedpost\']) ? (\"\r\n			<div style=\\\"float:$stylevar[right]\\\"><img src=\\\"$stylevar[imgdir_misc]/trashcan.gif\\\" alt=\\\"$vbphrase[deleted_post]\\\" border=\\\"0\\\" /></div>\r\n		\") : (\"\")).\"\r\n		<div class=\\\"smallfont\\\">\r\n			\" . construct_phrase(\"$vbphrase[administrator_decided_x_quiet]\", \"$post[username]\") . \"\r\n		</div>\r\n\r\n	</td>\r\n</tr>\r\n</table>', '<table id=\"post$post[postid]\" class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr title=\"<phrase 1=\"$post[postid]\">$vbphrase[post_x]</phrase>\">\r\n	<td class=\"thead\" style=\"font-weight:normal\" $post[scrolltothis]>\r\n		<if condition=\"$show[\'inlinemod\']\">\r\n			<input type=\"checkbox\" name=\"plist[$postid]\" id=\"plist_$postid\" style=\"float:$stylevar[right]; vertical-align:middle; padding:0px; margin:0px 0px 0px 5px\" value=\"$post[checkbox_value]\" onclick=\"inlineMod.toggle(this)\" />\r\n		</if>\r\n		<a style=\"float:$stylevar[right]\" href=\"showpost.php?$session[sessionurl]p=$post[postid]\" target=\"_blank\" rel=\"nofollow\" onclick=\"return display_post($post[postid]);\">$vbphrase[view_post]</a>\r\n		<a name=\"post$post[postid]\"><img class=\"inlineimg\" src=\"$stylevar[imgdir_statusicon]/post_$post[statusicon].gif\" alt=\"$post[statustitle]\" border=\"0\" /></a>\r\n		$post[postdate]<if condition=\"!$show[\'detailedtime\']\">, $post[posttime]</if> $post[firstnewinsert]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"alt2\">\r\n		<a href=\"member.php?$session[sessionurl]u=$post[userid]\">$post[musername]</a>\r\n	</td>\r\n</tr>\r\n\r\n\r\n<tr>\r\n	<td class=\"alt1\">\r\n		<if condition=\"$show[\'moderated\']\">\r\n			<div style=\"float:$stylevar[right]\"><img src=\"$stylevar[imgdir_misc]/moderated.gif\" alt=\"$vbphrase[moderated_post]\" border=\"0\" /></div>\r\n		</if>\r\n		<if condition=\"$show[\'deletedpost\']\">\r\n			<div style=\"float:$stylevar[right]\"><img src=\"$stylevar[imgdir_misc]/trashcan.gif\" alt=\"$vbphrase[deleted_post]\" border=\"0\" /></div>\r\n		</if>\r\n		<div class=\"smallfont\">\r\n			<phrase 1=\"$post[username]\">$vbphrase[administrator_decide