(364, -1, 'postbit_ip', '\".(($show[\'ip\']) ? (\"\r\n	$vbphrase[ip]: $post[ip]\r\n\") : (\"\r\n	<a href=\\\"postings.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=getip&amp;p=$post[postid]\\\"><img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_button]/ip.gif\\\" alt=\\\"$vbphrase[ip]\\\" title=\\\"$post[ip]\\\" border=\\\"0\\\" /></a>\r\n\")).\"', '<if condition=\"$show[\'ip\']\">\r\n	$vbphrase[ip]: $post[ip]\r\n<else />\r\n	<a href=\"postings.php?$session[sessionurl]do=getip&amp;p=$post[postid]\"><img class=\"inlineimg\" src=\"$stylevar[imgdir_button]/ip.gif\" alt=\"$vbphrase[ip]\" title=\"$post[ip]\" border=\"0\" /></a>\r\n</if>', 'template', 1071580820, 'vBulletin Solutions', '', 'vbulletin'),
