it_end]\r\n\r\n\".(($show[\'profile\']) ? (\" \r\n<!-- post $post[postid] popup menu -->\r\n<div class=\\\"vbmenu_popup\\\" id=\\\"postmenu_$post[postid]_menu\\\" style=\\\"display:none\\\">\r\n	<table cellpadding=\\\"4\\\" cellspacing=\\\"1\\\" border=\\\"0\\\">\r\n	<tr>\r\n		<td class=\\\"thead\\\">$post[username]</td>\r\n	</tr>\r\n	\".(($show[\'profile\']) ? (\"\r\n		<tr><td class=\\\"vbmenu_option\\\"><a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$post[userid]\\\">$vbphrase[view_public_profile]</a></td></tr>\r\n	\") : (\"\")).\"\r\n	\".(($show[\'pmlink\']) ? (\"\r\n		<tr><td class=\\\"vbmenu_option\\\"><a href=\\\"private.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=newpm&amp;u=$post[userid]\\\" rel=\\\"nofollow\\\">\" . construct_phrase(\"$vbphrase[send_private_message_to_x]\", \"$post[username]\") . \"</a></td></tr>\r\n	\") : (\"\")).\"\r\n	\".(($show[\'emaillink\']) ? (\"\r\n		<tr><td class=\\\"vbmenu_option\\\"><a href=\\\"sendmessage.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=mailmember&amp;u=$post[userid]\\\" rel=\\\"nofollow\\\">\" . construct_phrase(\"$vbphrase[send_email_to_x]\", \"$post[username]\") . \"</a></td></tr>\r\n	\") : (\"\")).\"\r\n	\".(($show[\'homepage\']) ? (\"\r\n		<tr><td class=\\\"vbmenu_option\\\"><a href=\\\"$post[homepage]\\\">\" . construct_phrase(\"$vbphrase[visit_xs_homepage]\", \"$post[username]\") . \"</a></td></tr>\r\n	\") : (\"\")).\"\r\n	\".(($show[\'search\']) ? (\"\r\n		<tr><td class=\\\"vbmenu_option\\\"><a href=\\\"search.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=finduser&amp;u=$post[userid]\\\" rel=\\\"nofollow\\\">\" . construct_phrase(\"$vbphrase[find_more_posts_by_x]\", \"$post[username]\") . \"</a></td></tr>\r\n	\") : (\"\")).\"\r\n	\".(($post[\'userid\'] AND $show[\'member\']) ? (\"\r\n	<tr><td class=\\\"vbmenu_option\\\"><a href=\\\"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=addlist&amp;userlist=buddy&amp;u=$post[userid]\\\">\" . construct_phrase(\"$vbphrase[add_x_to_contacts]\", \"$post[username]\") . \"</a></td></tr>\r\n	\") : (\"\")).\"\r\n	$template_hook[postbit_user_popup]\r\n	</table>\r\n</div>\r\n<!-- / post $post[postid] popup menu -->\r\n\") : (\"\")).\"', '$template_hook[postbit_start]\r\n<table id=\"post$post[postid]\" class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"0\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<if condition=\"$show[\'announcement\']\">\r\n		<td class=\"thead\" style=\"font-weight:normal; border: $stylevar[cellspacing]px solid $stylevar[tborder_bgcolor]\" colspan=\"2\">\r\n			<img class=\"inlineimg\" src=\"$stylevar[imgdir_statusicon]/post_$post[statusicon].gif\" alt=\"$post[statustitle]\" border=\"0\" />\r\n			<phrase 1=\"$post[startdate]\" 2=\"$post[enddate]\">$vbphrase[x_until_y]</phrase>\r\n		</td>\r\n	<else />\r\n		<td class=\"thead\" style=\"font-weight:normal; border: $stylevar[cellspacing]px solid $stylevar[tborder_bgcolor]; border-$stylevar[right]: 0px\" $post[scrolltothis]>\r\n			<!-- status icon and date -->\r\n			<a name=\"post$post[postid]\"><img class=\"inlineimg\" src=\"$stylevar[imgdir_statusicon]/post_$post[statusicon].gif\" alt=\"$post[statustitle]\" border=\"0\" /></a>\r\n			$post[postdate]<if condition=\"!$show[\'detailedtime\']\">, $post[posttime]</if>\r\n			$post[firstnewinsert]\r\n			<!-- / status icon and date -->\r\n		</td>\r\n		<td class=\"thead\" style=\"font-weight:normal; border: $stylevar[cellspacing]px solid $stylevar[tborder_bgcolor]; border-$stylevar[left]: 0px\" align=\"$stylevar[right]\">\r\n			&nbsp;\r\n			<if condition=\"$show[\'postcount\']\">#<a href=\"showpost.php?$session[sessionurl]p=$post[postid]&amp;postcount=$post[postcount]\" target=\"new\" rel=\"nofollow\" id=\"postcount$post[postid]\" name=\"$post[postcount]\"><strong>$post[postcount]</strong></a></if>\r\n			<if condition=\"$show[\'inlinemod\']\">\r\n				<input type=\"checkbox\" name=\"plist[$postid]\" id=\"plist_$postid\" style=\"vertical-align:middle; padding:0px; margin:0px 0px 0px 5px\" value=\"$post[checkbox_value]\" />\r\n			</if>\r\n		</td>\r\n	</if>\r\n</tr>\r\n<tr valign=\"top\">\r\n	<td class=\"alt2\" width=\"175\" style=\"border: $stylevar[cellspacing]px solid $stylevar[tborder_bgcolor]; border-top: 0px; border-bottom: 0px\">\r\n\r\n			<div id=\"postmenu_$post[postid]\">\r\n				<if condition=\"$show[\'profile\']\">\r\n				<a class=\"bigusername\" href=\"member.php?$session[sessionurl]u=$post[userid]\">$post[musername]</a>\r\n				<script type=\"text/javascript\"> vbmenu_register(\"postmenu_$post[postid]\", true); </script>\r\n				<else />\r\n				$post[musername]\r\n				</if>\r\n			</div>\r\n\r\n			<if condition=\"$post[\'usertitle\']\"><div class=\"smallfont\">$post[usertitle]</div></if>\r\n			<if condition=\"$post[\'rank\']\"><div class=\"smallfont\">$post[rank]</div></if>\r\n			$template_hook[postbit_userinfo_left]\r\n\r\n			<if condition=\"$show[\'avatar\']\">\r\n				<div class=\"smallfont\">\r\n					&nbsp;<br /><a href=\"member.php?$session[sessionurl]u=$post[userid]\"><img src=\"$post[avatarurl]\" $post[avwidth] $post[avheight] alt=\"<phrase 1=\"$post[username]\">$vbphrase[xs_avatar]</phrase>\" border=\"0\" /></a>\r\n				</div>\r\n			</if>\r\n\r\n			<div class=\"smallfont\">\r\n				&nbsp;<br />\r\n				<if condition=\"$post[\'joindate\']\"><div>$vbphrase[join_date]: $post[joindate]</div></if>\r\n				<if condition=\"$post[\'field2\']\"><div>$vbphrase[location_perm]: $post[field2]</div></if>\r\n				<if condition=\"$post[\'age\']\"><div>$vbphrase[age]: $post[age]</div></if>\r\n				<div>\r\n					$vbphrase[posts]: $post[posts]\r\n				</div>\r\n				$template_hook[postbit_userinfo_right_after_posts]\r\n				<if condition=\"$show[\'infraction\']\"><div>$vbphrase[infractions]: $post[warnings]/$post[infractions] ($post[ipoints])</div></if>\r\n				<if condition=\"$show[\'reputation\']\"><if condition=\"$show[\'reppower\']\">$vbphrase[reppower]: <span id=\"reppower_$post[postid]_$post[userid]\">$post[reppower]</span> </if><div><span id=\"repdisplay_$post[postid]_$post[userid]\">$post[reputationdisplay]</span></div></if>\r\n				$template_hook[postbit_userinfo_right]\r\n				<div>$post[icqicon] $post[aimicon] $post[msnicon] $post[yahooicon] $post[skypeicon]</div>\r\n			</div>\r\n\r\n	</td>\r\n	<if condition=\"$show[\'moderated\']\">\r\n	<td class=\"alt2\" id=\"td_post_$post[postid]\" style=\"border-$stylevar[right]: $stylevar[cellspacing]px solid $stylevar[tborder_bgcolor]\">\r\n	<else />\r\n	<td class=\"alt1\" id=\"td_post_$post[postid]\" style=\"border-$stylevar[right]: $stylevar[cellspacing]px solid $stylevar[tborder_bgcolor]\">\r\n	</if>\r\n		$template_hook[postbit_messagearea_start]\r\n		<if condition=\"$show[\'messageicon\'] OR $post[\'title\']\">\r\n			<!-- icon and title -->\r\n			<div class=\"smallfont\">\r\n				<if condition=\"$show[\'messageicon\']\"><img class=\"inlineimg\" src=\"$post[iconpath]\" alt=\"$post[icontitle]\" border=\"0\" /></if>\r\n				<if condition=\"$post[\'title\']\"><strong>$post[title]</strong></if>\r\n			</div>\r\n			<hr size=\"1\" style=\"color:$stylevar[tborder_bgcolor]; background-color:$stylevar[tborder_bgcolor]\" />\r\n			<!-- / icon and title -->\r\n		</if>\r\n\r\n		<!-- message -->\r\n		<div id=\"post_message_$post[postid]\">\r\n			$ad_location[ad_showthread_firstpost_start]\r\n			$post[message]\r\n		</div>\r\n		<!-- / message -->\r\n\r\n		<if condition=\"$show[\'attachments\']\">\r\n		<!-- attachments -->\r\n			<div style=\"padding:$stylevar[cellpadding]px\">\r\n\r\n			<if condition=\"$show[\'thumbnailattachment\']\">\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[attached_thumbnails]</legend>\r\n					<div style=\"padding:$stylevar[formspacer]px\">\r\n					$post[thumbnailattachments]\r\n					</div>\r\n				</fieldset>\r\n			</if>\r\n\r\n			<if condition=\"$show[\'imageattachment\']\">\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[attached_images]</legend>\r\n					<div style=\"padding:$stylevar[formspacer]px\">\r\n					$post[imageattachments]\r\n					</div>\r\n				</fieldset>\r\n			</if>\r\n\r\n			<if condition=\"$show[\'imageattachmentlink\']\">\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[attached_images]</legend>\r\n					<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n					$post[imageattachmentlinks]\r\n					</table>\r\n					</fieldset>\r\n			</if>\r\n\r\n			<if condition=\"$show[\'otherattachment\']\">\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[attached_files]</legend>\r\n					<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n					$post[otherattachments]\r\n					</table>\r\n				</fieldset>\r\n			</if>\r\n\r\n			<if condition=\"$show[\'moderatedattachment\']\">\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[attachments_pending_approval]</legend>\r\n					<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n					$post[moderatedattachments]\r\n					</table>\r\n				</fieldset>\r\n			</if>\r\n\r\n			</div>\r\n		<!-- / attachments -->\r\n		</if>\r\n\r\n		$template_hook[postbit_signature_start]\r\n		$ad_location[ad_showthread_firstpost_sig]\r\n\r\n		<if condition=\"$post[\'signature\']\">\r\n		<!-- sig -->\r\n			<div>\r\n				__________________<br />\r\n				$post[signature]\r\n			</div>\r\n		<!-- / sig -->\r\n		</if>\r\n\r\n		$template_hook[postbit_signature_end]\r\n\r\n		<if condition=\"$show[\'postedited\']\">\r\n		<!-- edit note -->\r\n			<div class=\"smallfont\">\r\n				<hr size=\"1\" style=\"color:$stylevar[tborder_bgcolor]; background-color:$stylevar[tborder_bgcolor]\" />\r\n				<em>\r\n					<if condition=\"$show[\'postedithistory\']\">\r\n						<phrase 1=\"$post[edit_username]\" 2=\"$post[edit_date]\" 3=\"$post[edit_time]\" 4=\"posthistory.php?$session[sessionurl]p=$post[postid]\">$vbphrase[last_edited_link_by_x_on_y_at_z_postid]</phrase>\r\n					<else />\r\n						<phrase 1=\"$post[edit_username]\" 2=\"$post[edit_date]\" 3=\"$post[edit_time]\">$vbphrase[last_edited_by_x_on_y_at_z]</phrase>\r\n					</if>\r\n					<if condition=\"$post[\'edit_reason\']\">\r\n						$vbphrase[reason]: $post[edit_reason]\r\n					</if>\r\n				</em>\r\n			</div>\r\n		<!-- / edit note -->\r\n		</if>\r\n\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"alt2\" style=\"border: $stylevar[cellspacing]px solid $stylevar[tborder_bgcolor]; border-top: 0px\">\r\n		$post[onlinestatus]\r\n		<if condition=\"$show[\'reputationlink\']\">\r\n			<span id=\"reputationmenu_$post[postid]\"><a href=\"reputation.php?$session[sessionurl]p=$post[postid]\" rel=\"nofollow\" id=\"reputation_$post[postid]\"><img class=\"inlineimg\" src=\"$stylevar[imgdir_button]/reputation.gif\" alt=\"<phrase 1=\"$post[username]\">$vbphrase[add_to_xs_reputation]</phrase>\" border=\"0\" /></a></span>\r\n			<if condition=\"$show[\'popups\']\"><script type=\"text/javascript\"> vbrep_register(\"$post[postid]\")</script></if>\r\n		</if>\r\n		<if condition=\"$show[\'infractionlink\']\"><a href=\"infraction.php?$session[sessionurl]do=report&amp;p=$post[postid]\" rel=\"nofollow\"><img class=\"inlineimg\" src=\"$stylevar[imgdir_button]/infraction.gif\" alt=\"<phrase 1=\"$post[username]\">$vbphrase[add_infraction_for_x]</phrase>\" border=\"0\" /></a></if>\r\n		<if condition=\"$show[\'reportlink\']\"><a href=\"report.php?$session[sessionurl]p=$post[postid]\" rel=\"nofollow\"><img class=\"inlineimg\" src=\"$stylevar[imgdir_button]/report.gif\" alt=\"$vbphrase[report_bad_post]\" border=\"0\" /></a></if>\r\n		$post[iplogged]\r\n		&nbsp;\r\n	</td>\r\n	<if condition=\"$show[\'moderated\']\">\r\n	<td class=\"alt2\" align=\"$stylevar[right]\" style=\"border: $stylevar[cellspacing]px solid $stylevar[tborder_bgcolor]; border-$stylevar[left]: 0px; border-top: 0px\">\r\n	<else />\r\n	<td class=\"alt1\" align=\"$stylevar[right]\" style=\"border: $stylevar[cellspacing]px solid $stylevar[tborder_bgcolor]; border-$stylevar[left]: 0px; border-top: 0px\">\r\n	</if>\r\n		<!-- controls -->\r\n		<if condition=\"$post[\'editlink\']\">\r\n			<img style=\"display: none\" id=\"progress_$postid\" src=\"$stylevar[imgdir_misc]/progress.gif\" alt=\"$vbphrase[loading_editor_please_wait]\" />\r\n			<a href=\"$post[editlink]\" name=\"vB::QuickEdit::$post[postid]\"><img src=\"$stylevar[imgdir_button]/edit.gif\" alt=\"$vbphrase[edit_delete_message]\" border=\"0\" /></a>\r\n		</if>\r\n		<if condition=\"$post[\'forwardlink\']\">\r\n			<a href=\"$post[forwardlink]\"><img src=\"$stylevar[imgdir_button]/forward.gif\" alt=\"$vbphrase[forward_message]\" border=\"0\" /></a>\r\n		</if>\r\n		<if condition=\"$post[\'replylink\']\">\r\n			<a href=\"$post[replylink]\" rel=\"nofollow\"><img src=\"$stylevar[imgdir_button]/<if condition=\"$post[\'forwardlink\']\">reply_small<else />quote</if>.gif\" alt=\"$vbphrase[reply_with_quote]\" border=\"0\" /></a>\r\n		</if>\r\n		<if condition=\"$show[\'multiquote_post\']\">\r\n			<a href=\"$post[replylink]\" rel=\"nofollow\" onclick=\"return false\"><img src=\"$stylevar[imgdir_button]/multiquote_<if condition=\"$show[\'multiquote_selected\']\">on<else />off</if>.gif\" alt=\"$vbphrase[multi_quote_this_message]\" border=\"0\" id=\"mq_$post[postid]\" /></a>\r\n		</if>\r\n		<if condition=\"$show[\'quickreply\'] AND !$show[\'threadedmode\']\">\r\n			<a href=\"$post[replylink]\" rel=\"nofollow\" id=\"qr_$post[postid]\" onclick=\"return false\"><img src=\"$stylevar[imgdir_button]/quickreply.gif\" alt=\"$vbphrase[quick_reply_to_this_message]\" border=\"0\" /></a>\r\n		</if>\r\n		<if condition=\"$show[\'moderated\']\">\r\n			<img src=\"$stylevar[imgdir_misc]/moderated.gif\" alt=\"$vbphrase[moderated_post]\" border=\"0\" />\r\n		</if>\r\n		<if condition=\"$show[\'spam\']\">\r\n			<img src=\"$stylevar[imgdir_misc]/spam_detected.png\" alt=\"$vbphrase[spam_post]\" border=\"0\" />\r\n		</if>\r\n		<if condition=\"$show[\'deletedpost\']\">\r\n			<if condition=\"$show[\'managepost\']\">\r\n				<a href=\"postings.php?$session[sessionurl]do=managepost&amp;p=$post[postid]\"><img src=\"$stylevar[imgdir_misc]/trashcan.gif\" alt=\"$vbphrase[manage]\" border=\"0\" /></a>\r\n			<else />\r\n				<img src=\"$stylevar[imgdir_misc]/trashcan.gif\" alt=\"$vbphrase[deleted_post]\" border=\"0\" />\r\n			</if>\r\n		</if>\r\n		<if condition=\"$show[\'redcard\']\">\r\n			<a href=\"infraction.php?$session[sessionurl]do=view&amp;p=$post[postid]\"><img src=\"$stylevar[imgdir_button]/redcard.gif\" alt=\"$vbphrase[received_infraction]\" border=\"0\" /></a>\r\n		<else />\r\n			<if condition=\"$show[\'yellowcard\']\">\r\n				<a href=\"infraction.php?$session[sessionurl]do=view&amp;p=$post[postid]\"><img src=\"$stylevar[imgdir_button]/yellowcard.gif\" alt=\"$vbphrase[received_warning]\" border=\"0\" /></a>\r\n			</if>\r\n		</if>\r\n		$template_hook[postbit_controls]\r\n		<!-- / controls -->\r\n	</td>\r\n</tr>\r\n</table>\r\n$template_hook[postbit_end]\r\n\r\n<if condition=\"$show[\'profile\']\"> \r\n<!-- post $post[postid] popup menu -->\r\n<div class=\"vbmenu_popup\" id=\"postmenu_$post[postid]_menu\" style=\"display:none\">\r\n	<table cellpadding=\"4\" cellspacing=\"1\" border=\"0\">\r\n	<tr>\r\n		<td class=\"thead\">$post[username]</td>\r\n	</tr>\r\n	<if condition=\"$show[\'profile\']\">\r\n		<tr><td class=\"vbmenu_option\"><a href=\"member.php?$session[sessionurl]u=$post[userid]\">$vbphrase[view_public_profile]</a></td></tr>\r\n	</if>\r\n	<if condition=\"$show[\'pmlink\']\">\r\n		<tr><td class=\"vbmenu_option\"><a href=\"private.php?$session[sessionurl]do=newpm&amp;u=$post[userid]\" rel=\"nofollow\"><phrase 1=\"$post[username]\">$vbphrase[send_private_message_to_x]</phrase></a></td></tr>\r\n	</if>\r\n	<if condition=\"$show[\'emaillink\']\">\r\n		<tr><td class=\"vbmenu_option\"><a href=\"sendmessage.php?$session[sessionurl]do=mailmember&amp;u=$post[userid]\" rel=\"nofollow\"><phrase 1=\"$post[username]\">$vbphrase[send_email_to_x]</phrase></a></td></tr>\r\n	</if>\r\n	<if condition=\"$show[\'homepage\']\">\r\n		<tr><td class=\"vbmenu_option\"><a href=\"$post[homepage]\"><phrase 1=\"$post[username]\">$vbphrase[visit_xs_homepage]</phrase></a></td></tr>\r\n	</if>\r\n	<if condition=\"$show[\'search\']\">\r\n		<tr><td class=\"vbmenu_option\"><a href=\"search.php?$session[sessionurl]do=finduser&amp;u=$post[userid]\" rel=\"nofollow\"><phrase 1=\"$post[username]\">$vbphrase[find_more_posts_by_x]</phrase></a></td></tr>\r\n	</if>\r\n	<if condition=\"$post[\'userid\'] AND $show[\'member\']\">\r\n	<tr><td class=\"vbmenu_option\"><a href=\"profile.php?$session[sessionurl]do=addlist&amp;userlist=buddy&amp;u=$post[userid]\"><phrase 1=\"$post[username]\">$vbphrase[add_x_to_contacts]</phrase></a></td></tr>\r\n	</if>\r\n	$template_hook[postbit_user_popup]\r\n	</table>\r\n</div>\r\n<!-- / post $post[postid] popup menu -->\r\n</if>', 'template', 1280350756, 'vBulletin Solutions', '3.8.7 Beta 1', 'vbulletin'),
(366, -1, 'postbit_onlinestatus', '\".(($onlinestatus==0) ? (\"<img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_statusicon]/user_offline.gif\\\" alt=\\\"\" . construct_phrase(\"$vbphrase[x_is_offline]\", \"$user[username]\") . \"\\\" border=\\\"0\\\" />\") : (\"\")).\"\r\n\".(($onlinestatus==1) ? (\"<img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_statusicon]/user_online.gif\\\" alt=\\\"\" . construct_phrase(\"$vbphrase[x_is_online_now]\", \"$user[username]\") . \"\\\" border=\\\"0\\\" />\") : (\"\")).\"\r\n\".(($onlinestatus==2) ? (\"<img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_statusicon]/user_invisible.gif\\\" alt=\\\"\" . construct_phrase(\"$vbphrase[x_is_invisible]\", \"$user[username]\") . \"\\\" border=\\\"0\\\" />\") : (\"\")).\"', '<if condition=\"$onlinestatus==0\"><img class=\"inlineimg\" src=\"$stylevar[imgdir_statusicon]/user_offline.gif\" alt=\"<phrase 1=\"$user[username]\">$vbphrase[x_is_offline]</phrase>\" border=\"0\" /></if>\r\n<if condition=\"$onlinestatus==1\"><img class=\"inlineimg\" src=\"$stylevar[imgdir_statusicon]/user_online.gif\" alt=\"<phrase 1=\"$user[username]\">$vbphrase[x_is_online_now]</phrase>\" border=\"0\" /></if>\r\n<if condition=\"$onlinestatus==2\"><img class=\"inlineimg\" src=\"$stylevar[imgdir_statusicon]/user_invisible.gif\" alt=\"<phrase 1=\"$user[username]\">$vbphrase[x_is_invisible]</phrase>\" border=\"0\" /></if>', 'template', 1071580897, 'vBulletin Solutions', '', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(367, -1, 'postbit_quickedit', '\".(($show[\'quick_edit_form_tag\']) ? (\"<form>\") : (\"\")).\"\r\n\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"1\\\" align=\\\"center\\\" width=\\\"95%\\\" id=\\\"{$editorid}_editor\\\">\r\n<tr>\r\n	<td class=\\\"vBulletin_editor\\\">\r\n	\".(($show[\'editor_toolbar\']) ? (\"\r\n	<div id=\\\"{$editorid}_controls\\\" class=\\\"controlbar\\\">\r\n		<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\">\r\n		<tr>\r\n			<td><div class=\\\"imagebutton\\\" id=\\\"{$editorid}_cmd_removeformat\\\"><img src=\\\"$stylevar[imgdir_editor]/removeformat.gif\\\" width=\\\"21\\\" height=\\\"20\\\" alt=\\\"$vbphrase[remove_text_formatting]\\\" /></div></td>\r\n		\".(($show[\'basic_bbcode\']) ? (\"\r\n			<td><img src=\\\"$stylevar[imgdir_editor]/separator.gif\\\" width=\\\"6\\\" height=\\\"20\\\" alt=\\\"\\\" /></td>\r\n			<td><div class=\\\"imagebutton\\\" id=\\\"{$editorid}_cmd_bold\\\"><img src=\\\"$stylevar[imgdir_editor]/bold.gif\\\" width=\\\"21\\\" height=\\\"20\\\" alt=\\\"$vbphrase[bold]\\\" /></div></td>\r\n			<td><div class=\\\"imagebutton\\\" id=\\\"{$editorid}_cmd_italic\\\"><img src=\\\"$stylevar[imgdir_editor]/italic.gif\\\" width=\\\"21\\\" height=\\\"20\\\" alt=\\\"$vbphrase[italic]\\\" /></div></td>\r\n			<td><div class=\\\"imagebutton\\\" id=\\\"{$editorid}_cmd_underline\\\"><img src=\\\"$stylevar[imgdir_editor]/underline.gif\\\" width=\\\"21\\\" height=\\\"20\\\" alt=\\\"$vbphrase[underline]\\\" /></div></td>\r\n		\") : (\"\")).\"\r\n		\".(($show[\'color_bbcode\']) ? (\"\r\n			<td><img src=\\\"$stylevar[imgdir_editor]/separator.gif\\\" width=\\\"6\\\" height=\\\"20\\\" alt=\\\"\\\" /></td>\r\n			<td><div class=\\\"imagebutton\\\" id=\\\"{$editorid}_popup_forecolor\\\" title=\\\"$vbphrase[colors]\\\">\r\n				<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\">\r\n				<tr>\r\n					<td id=\\\"{$editorid}_color_out\\\"><img src=\\\"$stylevar[imgdir_editor]/color.gif\\\" width=\\\"21\\\" height=\\\"16\\\" alt=\\\"\\\" /><br /><img src=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'cleargifurl\'] . \"\\\" id=\\\"{$editorid}_color_bar\\\" alt=\\\"\\\" style=\\\"background-color:black\\\" width=\\\"21\\\" height=\\\"4\\\" /></td>\r\n					<td class=\\\"alt_pickbutton\\\"><img src=\\\"$stylevar[imgdir_editor]/menupop.gif\\\" alt=\\\"\\\" width=\\\"11\\\" height=\\\"16\\\" /></td>\r\n				</tr>\r\n				</table>\r\n			</div></td>\r\n		\") : (\"\")).\"\r\n		\".(($show[\'url_bbcode\'] OR $show[\'img_bbcode\']) ? (\"\r\n			<td><img src=\\\"$stylevar[imgdir_editor]/separator.gif\\\" width=\\\"6\\\" height=\\\"20\\\" alt=\\\"\\\" /></td>\r\n		\") : (\"\")).\"\r\n		\".(($show[\'url_bbcode\']) ? (\"\r\n			<td><div class=\\\"imagebutton\\\" id=\\\"{$editorid}_cmd_createlink\\\"><img src=\\\"$stylevar[imgdir_editor]/createlink.gif\\\" width=\\\"21\\\" height=\\\"20\\\" alt=\\\"$vbphrase[insert_link]\\\" /></div></td>\r\n		\") : (\"\")).\"\r\n		\".(($show[\'img_bbcode\']) ? (\"\r\n			<td><div class=\\\"imagebutton\\\" id=\\\"{$editorid}_cmd_insertimage\\\"><img src=\\\"$stylevar[imgdir_editor]/insertimage.gif\\\" width=\\\"21\\\" height=\\\"20\\\" alt=\\\"$vbphrase[insert_image]\\\" /></div></td>\r\n		\") : (\"\")).\"\r\n		\".(($show[\'quote_bbcode\']) ? (\"\r\n			<td><img src=\\\"$stylevar[imgdir_editor]/separator.gif\\\" width=\\\"6\\\" height=\\\"20\\\" alt=\\\"\\\" /></td>\r\n			<td><div class=\\\"imagebutton\\\" id=\\\"{$editorid}_cmd_wrap0_quote\\\"><img src=\\\"$stylevar[imgdir_editor]/quote.gif\\\" width=\\\"21\\\" height=\\\"20\\\" alt=\\\"$vbphrase[wrap_quote_tags]\\\" /></div></td>\r\n		\") : (\"\")).\"\r\n		\".((!is_browser(\'opera\')) ? (\"\r\n			<td width=\\\"100%\\\">&nbsp;</td>\r\n		\") : (\"\")).\"\r\n		\".((is_browser(\'ie\')) ? (\"\r\n			<td><img src=\\\"$stylevar[imgdir_editor]/separator.gif\\\" width=\\\"6\\\" height=\\\"20\\\" alt=\\\"\\\" /></td>\r\n			<td><div class=\\\"imagebutton\\\" id=\\\"{$editorid}_cmd_spelling\\\"><img src=\\\"$stylevar[imgdir_editor]/spelling.gif\\\" width=\\\"21\\\" height=\\\"20\\\" alt=\\\"$vbphrase[check_spelling]\\\" /></div></td>\r\n		\") : (\"\")).\"\r\n			<td>\r\n				<div class=\\\"imagebutton\\\" id=\\\"{$editorid}_cmd_resize_0_99\\\"><img src=\\\"$stylevar[imgdir_editor]/resize_0.gif\\\" width=\\\"21\\\" height=\\\"9\\\" alt=\\\"$vbphrase[decrease_size]\\\" /></div>\r\n				<div class=\\\"imagebutton\\\" id=\\\"{$editorid}_cmd_resize_1_99\\\"><img src=\\\"$stylevar[imgdir_editor]/resize_1.gif\\\" width=\\\"21\\\" height=\\\"9\\\" alt=\\\"$vbphrase[increase_size]\\\" /></div>\r\n			</td>\r\n		\".(($show[\'wysiwyg_compatible\']) ? (\"\r\n			<td><img src=\\\"$stylevar[imgdir_editor]/separator.gif\\\" width=\\\"6\\\" height=\\\"20\\\" alt=\\\"\\\" /></td>\r\n			<td><div class=\\\"imagebutton\\\" id=\\\"{$editorid}_cmd_switchmode\\\"><img src=\\\"$stylevar[imgdir_editor]/switchmode.gif\\\" width=\\\"21\\\" height=\\\"20\\\" alt=\\\"$vbphrase[switch_editor_mode]\\\" /></div></td>\r\n		\") : (\"\")).\"\r\n		</tr>\r\n		</table>\r\n	</div>\r\n	\") : (\"\")).\"\r\n\r\n	<div class=\\\"controlbar\\\">\r\n		<div><textarea name=\\\"message\\\" id=\\\"{$editorid}_textarea\\\" rows=\\\"10\\\" cols=\\\"60\\\" style=\\\"width:500px; height:{$editor_height}px\\\" tabindex=\\\"1\\\" dir=\\\"$stylevar[textdirection]\\\">$newpost[message]</textarea></div>\r\n		<div class=\\\"fieldset\\\" style=\\\"margin-top:$stylevar[formspacer]px\\\">\r\n			<div>$vbphrase[reason_for_editing]:</div>\r\n			<div><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"reason\\\" id=\\\"{$editorid}_edit_reason\\\" value=\\\"\\\" size=\\\"50\\\" maxlength=\\\"125\\\" tabindex=\\\"1\\\" title=\\\"$vbphrase[optional]\\\" /></div>\r\n		</div>\r\n	</div>\r\n\r\n	<div align=\\\"$stylevar[right]\\\">\r\n		<img style=\\\"vertical-align:middle; display: none\\\" id=\\\"{$editorid}_posting_msg\\\" src=\\\"$stylevar[imgdir_misc]/progress.gif\\\" alt=\\\"$vbphrase[posting_message_please_wait]\\\" />\r\n		<input type=\\\"button\\\" class=\\\"button\\\" tabindex=\\\"1\\\" accesskey=\\\"s\\\" value=\\\"$vbphrase[save]\\\" id=\\\"{$editorid}_save\\\" />\r\n		<input type=\\\"button\\\" class=\\\"button\\\" tabindex=\\\"1\\\" accesskey=\\\"r\\\" value=\\\"$vbphrase[go_advanced]\\\" id=\\\"{$editorid}_adv\\\" />\r\n		\".(($show[\'deletepostoption\']) ? (\"\r\n		<input type=\\\"button\\\" class=\\\"button\\\" tabindex=\\\"1\\\" value=\\\"$vbphrase[delete]\\\" id=\\\"{$editorid}_delete\\\" />\r\n		\") : (\"\")).\"\r\n		<input type=\\\"button\\\" class=\\\"button\\\" tabindex=\\\"1\\\" accesskey=\\\"r\\\" value=\\\"$vbphrase[cancel]\\\" id=\\\"{$editorid}_abort\\\" />\r\n	</div>\r\n\r\n	<input type=\\\"hidden\\\" name=\\\"wysiwyg\\\" id=\\\"{$editorid}_mode\\\" value=\\\"$editortype\\\" />\r\n\r\n	\".(($show[\'deletepostoption\']) ? (\"\r\n	<div id=\\\"quickedit_delete\\\" style=\\\"display:none\\\">\r\n\r\n		<hr />\r\n\r\n		<div class=\\\"fieldset\\\">\r\n			<div>$vbphrase[delete_message_check_appropriate_option]</div>\r\n			\".(($show[\'firstpostnote\']) ? (\"\r\n				<div>$vbphrase[deleting_message_deletion_of_thread]</div>\r\n			\") : (\"\")).\"\r\n		</div>\r\n\r\n		<fieldset class=\\\"fieldset\\\">\r\n			<legend>$vbphrase[deletion_options]</legend>\r\n			<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n				<div>\r\n					<label for=\\\"rb_del_leave\\\"><input type=\\\"radio\\\" name=\\\"deletepost\\\" value=\\\"\\\" id=\\\"rb_del_leave\\\" tabindex=\\\"1\\\" checked=\\\"checked\\\" />$vbphrase[do_not_delete_message]</label>\r\n				</div>\r\n				\".(($show[\'softdeleteoption\']) ? (\"\r\n				<div>\r\n					<label for=\\\"rb_del_soft\\\"><input type=\\\"radio\\\" name=\\\"deletepost\\\" value=\\\"delete\\\" id=\\\"rb_del_soft\\\" tabindex=\\\"1\\\" />$vbphrase[delete_message]</label>\r\n					\".(($show[\'physicaldeleteoption\'] AND $show[\'keepattachmentsoption\']) ? (\"(<label for=\\\"cb_keepattachments\\\"><input type=\\\"checkbox\\\" name=\\\"keepattachments\\\" value=\\\"1\\\" id=\\\"cb_keepattachments\\\" tabindex=\\\"1\\\" />$vbphrase[keep_attachments]</label>)\") : (\"\")).\"\r\n				</div>\r\n				\") : (\"\")).\"\r\n				\".(($show[\'physicaldeleteoption\']) ? (\"\r\n				<div>\r\n					<label for=\\\"rb_del_hard\\\"><input type=\\\"radio\\\" name=\\\"deletepost\\\" value=\\\"remove\\\" id=\\\"rb_del_hard\\\" tabindex=\\\"1\\\" />$vbphrase[physically_remove_message]</label>\r\n				</div>\r\n				\") : (\"\")).\"\r\n			</div>\r\n		</fieldset>\r\n\r\n		<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n		<tr valign=\\\"bottom\\\">\r\n			<td class=\\\"smallfont\\\">\r\n				<div>$vbphrase[reason_for_deletion]:</div>\r\n				<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"reason\\\" id=\\\"del_reason\\\" size=\\\"50\\\" tabindex=\\\"1\\\" title=\\\"$vbphrase[optional]\\\" />\r\n			</td>\r\n			<td align=\\\"$stylevar[right]\\\"><input type=\\\"button\\\" class=\\\"button\\\" value=\\\"$vbphrase[delete_this_message]\\\" tabindex=\\\"1\\\" id=\\\"quickedit_dodelete\\\" /></td>\r\n		</tr>\r\n		</table>\r\n\r\n	</div>\r\n	\") : (\"\")).\"\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n\".(($show[\'quick_edit_form_tag\']) ? (\"</form>\") : (\"\")).\"', '<if condition=\"$show[\'quick_edit_form_tag\']\"><form></if>\r\n\r\n<table cellpadding=\"0\" cellspacing=\"0\" border=\"1\" align=\"center\" width=\"95%\" id=\"{$editorid}_editor\">\r\n<tr>\r\n	<td class=\"vBulletin_editor\">\r\n	<if condition=\"$show[\'editor_toolbar\']\">\r\n	<div id=\"{$editorid}_controls\" class=\"controlbar\">\r\n		<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\r\n		<tr>\r\n			<td><div class=\"imagebutton\" id=\"{$editorid}_cmd_removeformat\"><img src=\"$stylevar[imgdir_editor]/removeformat.gif\" width=\"21\" height=\"20\" alt=\"$vbphrase[remove_text_formatting]\" /></div></td>\r\n		<if condition=\"$show[\'basic_bbcode\']\">\r\n			<td><img src=\"$stylevar[imgdir_editor]/separator.gif\" width=\"6\" height=\"20\" alt=\"\" /></td>\r\n			<td><div class=\"imagebutton\" id=\"{$editorid}_cmd_bold\"><img src=\"$stylevar[imgdir_editor]/bold.gif\" width=\"21\" height=\"20\" alt=\"$vbphrase[bold]\" /></div></td>\r\n			<td><div class=\"imagebutton\" id=\"{$editorid}_cmd_italic\"><img src=\"$stylevar[imgdir_editor]/italic.gif\" width=\"21\" height=\"20\" alt=\"$vbphrase[italic]\" /></div></td>\r\n			<td><div class=\"imagebutton\" id=\"{$editorid}_cmd_underline\"><img src=\"$stylevar[imgdir_editor]/underline.gif\" width=\"21\" height=\"20\" alt=\"$vbphrase[underline]\" /></div></td>\r\n		</if>\r\n		<if condition=\"$show[\'color_bbcode\']\">\r\n			<td><img src=\"$stylevar[imgdir_editor]/separator.gif\" width=\"6\" height=\"20\" alt=\"\" /></td>\r\n			<td><div class=\"imagebutton\" id=\"{$editorid}_popup_forecolor\" title=\"$vbphrase[colors]\">\r\n				<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\r\n				<tr>\r\n					<td id=\"{$editorid}_color_out\"><img src=\"$stylevar[imgdir_editor]/color.gif\" width=\"21\" height=\"16\" alt=\"\" /><br /><img src=\"$vboptions[cleargifurl]\" id=\"{$editorid}_color_bar\" alt=\"\" style=\"background-color:black\" width=\"21\" height=\"4\" /></td>\r\n					<td class=\"alt_pickbutton\"><img src=\"$stylevar[imgdir_editor]/menupop.gif\" alt=\"\" width=\"11\" height=\"16\" /></td>\r\n				</tr>\r\n				</table>\r\n			</div></td>\r\n		</if>\r\n		<if condition=\"$show[\'url_bbcode\'] OR $show[\'img_bbcode\']\">\r\n			<td><img src=\"$stylevar[imgdir_editor]/separator.gif\" width=\"6\" height=\"20\" alt=\"\" /></td>\r\n		</if>\r\n		<if condition=\"$show[\'url_bbcode\']\">\r\n			<td><div class=\"imagebutton\" id=\"{$editorid}_cmd_createlink\"><img src=\"$stylevar[imgdir_editor]/createlink.gif\" width=\"21\" height=\"20\" alt=\"$vbphrase[insert_link]\" /></div></td>\r\n		</if>\r\n		<if condition=\"$show[\'img_bbcode\']\">\r\n			<td><div class=\"imagebutton\" id=\"{$editorid}_cmd_insertimage\"><img src=\"$stylevar[imgdir_editor]/insertimage.gif\" width=\"21\" height=\"20\" alt=\"$vbphrase[insert_image]\" /></div></td>\r\n		</if>\r\n		<if condition=\"$show[\'quote_bbcode\']\">\r\n			<td><img src=\"$stylevar[imgdir_editor]/separator.gif\" width=\"6\" height=\"20\" alt=\"\" /></td>\r\n			<td><div class=\"imagebutton\" id=\"{$editorid}_cmd_wrap0_quote\"><img src=\"$stylevar[imgdir_editor]/quote.gif\" width=\"21\" height=\"20\" alt=\"$vbphrase[wrap_quote_tags]\" /></div></td>\r\n		</if>\r\n		<if condition=\"!is_browser(\'opera\')\">\r\n			<td width=\"100%\">&nbsp;</td>\r\n		</if>\r\n		<if condition=\"is_browser(\'ie\')\">\r\n			<td><img src=\"$stylevar[imgdir_editor]/separator.gif\" width=\"6\" height=\"20\" alt=\"\" /></td>\r\n			<td><div class=\"imagebutton\" id=\"{$editorid}_cmd_spelling\"><img src=\"$stylevar[imgdir_editor]/spelling.gif\" width=\"21\" height=\"20\" alt=\"$vbphrase[check_spelling]\" /></div></td>\r\n		</if>\r\n			<td>\r\n				<div class=\"imagebutton\" id=\"{$editorid}_cmd_resize_0_99\"><img src=\"$stylevar[imgdir_editor]/resize_0.gif\" width=\"21\" height=\"9\" alt=\"$vbphrase[decrease_size]\" /></div>\r\n				<div class=\"imagebutton\" id=\"{$editorid}_cmd_resize_1_99\"><img src=\"$stylevar[imgdir_editor]/resize_1.gif\" width=\"21\" height=\"9\" alt=\"$vbphrase[increase_size]\" /></div>\r\n			</td>\r\n		<if condition=\"$show[\'wysiwyg_compatible\']\">\r\n			<td><img src=\"$stylevar[imgdir_editor]/separator.gif\" width=\"6\" height=\"20\" alt=\"\" /></td>\r\n			<td><div class=\"imagebutton\" id=\"{$editorid}_cmd_switchmode\"><img src=\"$stylevar[imgdir_editor]/switchmode.gif\" width=\"21\" height=\"20\" alt=\"$vbphrase[switch_editor_mode]\" /></div></td>\r\n		</if>\r\n		</tr>\r\n		</table>\r\n	</div>\r\n	</if>\r\n\r\n	<div class=\"controlbar\">\r\n		<div><textarea name=\"message\" id=\"{$editorid}_textarea\" rows=\"10\" cols=\"60\" style=\"width:500px; height:{$editor_height}px\" tabindex=\"1\" dir=\"$stylevar[textdirection]\">$newpost[message]</textarea></div>\r\n		<div class=\"fieldset\" style=\"margin-top:$stylevar[formspacer]px\">\r\n			<div>$vbphrase[reason_for_editing]:</div>\r\n			<div><input type=\"text\" class=\"bginput\" name=\"reason\" id=\"{$editorid}_edit_reason\" value=\"\" size=\"50\" maxlength=\"125\" tabindex=\"1\" title=\"$vbphrase[optional]\" /></div>\r\n		</div>\r\n	</div>\r\n\r\n	<div align=\"$stylevar[right]\">\r\n		<img style=\"vertical-align:middle; display: none\" id=\"{$editorid}_posting_msg\" src=\"$stylevar[imgdir_misc]/progress.gif\" alt=\"$vbphrase[posting_message_please_wait]\" />\r\n		<input type=\"button\" class=\"button\" tabindex=\"1\" accesskey=\"s\" value=\"$vbphrase[save]\" id=\"{$editorid}_save\" />\r\n		<input type=\"button\" class=\"button\" tabindex=\"1\" accesskey=\"r\" value=\"$vbphrase[go_advanced]\" id=\"{$editorid}_adv\" />\r\n		<if condition=\"$show[\'deletepostoption\']\">\r\n		<input type=\"button\" class=\"button\" tabindex=\"1\" value=\"$vbphrase[delete]\" id=\"{$editorid}_delete\" />\r\n		</if>\r\n		<input type=\"button\" class=\"button\" tabindex=\"1\" accesskey=\"r\" value=\"$vbphrase[cancel]\" id=\"{$editorid}_abort\" />\r\n	</div>\r\n\r\n	<input type=\"hidden\" name=\"wysiwyg\" id=\"{$editorid}_mode\" value=\"$editortype\" />\r\n\r\n	<if condition=\"$show[\'deletepostoption\']\">\r\n	<div id=\"quickedit_delete\" style=\"display:none\">\r\n\r\n		<hr />\r\n\r\n		<div class=\"fieldset\">\r\n			<div>$vbphrase[delete_message_check_appropriate_option]</div>\r\n			<if condition=\"$show[\'firstpostnote\']\">\r\n				<div>$vbphrase[deleting_message_deletion_of_thread]</div>\r\n			</if>\r\n		</div>\r\n\r\n		<fieldset class=\"fieldset\">\r\n			<legend>$vbphrase[deletion_options]</legend>\r\n			<div style=\"padding:$stylevar[formspacer]px\">\r\n				<div>\r\n					<label for=\"rb_del_leave\"><input type=\"radio\" name=\"deletepost\" value=\"\" id=\"rb_del_leave\" tabindex=\"1\" checked=\"checked\" />$vbphrase[do_not_delete_message]</label>\r\n				</div>\r\n				<if condition=\"$show[\'softdeleteoption\']\">\r\n				<div>\r\n					<label for=\"rb_del_soft\"><input type=\"radio\" name=\"deletepost\" value=\"delete\" id=\"rb_del_soft\" tabindex=\"1\" />$vbphrase[delete_message]</label>\r\n					<if condition=\"$show[\'physicaldeleteoption\'] AND $show[\'keepattachmentsoption\']\">(<label for=\"cb_keepattachments\"><input type=\"checkbox\" name=\"keepattachments\" value=\"1\" id=\"cb_keepattachments\" tabindex=\"1\" />$vbphrase[keep_attachments]</label>)</if>\r\n				</div>\r\n				</if>\r\n				<if condition=\"$show[\'physicaldeleteoption\']\">\r\n				<div>\r\n					<label for=\"rb_del_hard\"><input type=\"radio\" name=\"deletepost\" value=\"remove\" id=\"rb_del_hard\" tabindex=\"1\" />$vbphrase[physically_remove_message]</label>\r\n				</div>\r\n				</if>\r\n			</div>\r\n		</fieldset>\r\n\r\n		<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\r\n		<tr valign=\"bottom\">\r\n			<td class=\"smallfont\">\r\n				<div>$vbphrase[reason_for_deletion]:</div>\r\n				<input type=\"text\" class=\"bginput\" name=\"reason\" id=\"del_reason\" size=\"50\" tabindex=\"1\" title=\"$vbphrase[optional]\" />\r\n			</td>\r\n			<td align=\"$stylevar[right]\"><input type=\"button\" class=\"button\" value=\"$vbphrase[delete_this_message]\" tabindex=\"1\" id=\"quickedit_dodelete\" /></td>\r\n		</tr>\r\n		</table>\r\n\r\n	</div>\r\n	</if>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<if condition=\"$show[\'quick_edit_form_tag\']\"></form></if>', 'template', 1237516405, 'vBulletin Solutions', '3.8.2', 'vbulletin'),
(368, -1, 'postbit_reputation', '<img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_reputation]/reputation_$posneg.gif\\\" alt=\\\"$post[username] $post[level]\\\" border=\\\"0\\\" />', '<img class=\"inlineimg\" src=\"$stylevar[imgdir_reputation]/reputation_$posneg.gif\" alt=\"$post[username] $post[level]\" border=\"0\" />', 'template', 1071580916, 'vBulletin Solutions', '', 'vbulletin'),
