(371, -1, 'posthistory_content_changed', '\".(($compare_show[olddata]) ? (\"\r\n<tr valign=\\\"top\\\" class=\\\"diffold\\\">\r\n	<td width=\\\"20\\\">-</td>\r\n	<td width=\\\"100%\\\">$compare_show[olddata]</td>\r\n</tr>\r\n\") : (\"\")).\"\r\n\".(($compare_show[newdata]) ? (\"\r\n<tr valign=\\\"top\\\" class=\\\"diffnew\\\">\r\n	<td width=\\\"20\\\">+</td>\r\n	<td width=\\\"100%\\\">$compare_show[newdata]</td>\r\n</tr>\r\n\") : (\"\")).\"\r\n', '<if condition=\"$compare_show[olddata]\">\r\n<tr valign=\"top\" class=\"diffold\">\r\n	<td width=\"20\">-</td>\r\n	<td width=\"100%\">$compare_show[olddata]</td>\r\n</tr>\r\n</if>\r\n<if condition=\"$compare_show[newdata]\">\r\n<tr valign=\"top\" class=\"diffnew\">\r\n	<td width=\"20\">+</td>\r\n	<td width=\"100%\">$compare_show[newdata]</td>\r\n</tr>\r\n</if>\r\n', 'template', 1194539281, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
