(373, -1, 'posthistory_listbit', '<tr class=\\\"$bgclass\\\">\r\n    <td><input type=\\\"radio\\\" name=\\\"oldver\\\" value=\\\"$history[postedithistoryid]\\\" $oldver_selected /></td>\r\n    <td><input type=\\\"radio\\\" name=\\\"newver\\\" value=\\\"$history[postedithistoryid]\\\" $newver_selected /></td>\r\n    <td>\".(($history[\'reason\'] != \'\') ? (\"$history[reason]\") : (\"$vbphrase[n_a]\")).\"</td>\r\n    <td><a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$history[userid]\\\">$history[username]</a></td>\r\n    <td>$history[strdate] <span class=\\\"time\\\">$history[strtime]</span></td>\r\n</tr>\r\n', '<tr class=\"$bgclass\">\r\n    <td><input type=\"radio\" name=\"oldver\" value=\"$history[postedithistoryid]\" $oldver_selected /></td>\r\n    <td><input type=\"radio\" name=\"newver\" value=\"$history[postedithistoryid]\" $newver_selected /></td>\r\n    <td><if condition=\"$history[\'reason\'] != \'\'\">$history[reason]<else />$vbphrase[n_a]</if></td>\r\n    <td><a href=\"member.php?$session[sessionurl]u=$history[userid]\">$history[username]</a></td>\r\n    <td>$history[strdate] <span class=\"time\">$history[strtime]</span></td>\r\n</tr>\r\n', 'template', 1194539334, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
