(376, -1, 'printthread', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n<meta http-equiv=\\\"Content-Type\\\" content=\\\"text/html; charset=$stylevar[charset]\\\" />\r\n<meta name=\\\"generator\\\" content=\\\"vBulletin \" . $GLOBALS[\'vbulletin\']->options[\'templateversion\'] . \"\\\" />\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $threadinfo[prefix_plain_html] $threadinfo[title]</title>\r\n<style type=\\\"text/css\\\">\r\n<!--\r\ntd, p, li, div\r\n{\r\n	font: 10pt verdana, geneva, lucida, \'lucida grande\', arial, helvetica, sans-serif;\r\n}\r\n.smallfont\r\n{\r\n	font-size: 11px;\r\n}\r\n.tborder\r\n{\r\n	border: 1px solid #808080;\r\n}\r\n.thead\r\n{\r\n	background-color: #EEEEEE;\r\n}\r\n.page\r\n{\r\n	background-color: #FFFFFF;\r\n	color: #000000;\r\n}\r\n-->\r\n</style>\r\n</head>\r\n<body class=\\\"page\\\">\r\n\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n<tr valign=\\\"bottom\\\">\r\n	<td><a href=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'bburl\'] . \"/\\\"><img src=\\\"$stylevar[titleimage]\\\" alt=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \"\\\" border=\\\"0\\\" /></a></td>\r\n	<td align=\\\"$stylevar[right]\\\">\r\n		<div class=\\\"smallfont\\\">$pagenav</div>\r\n		\".(($show[\'pagenav\']) ? (\"\r\n		<div class=\\\"smallfont\\\"><a href=\\\"printthread.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"t=$threadid&amp;pp=$maxperpage\\\">\" . construct_phrase(\"$vbphrase[show_x_posts_on_one_page]\", \"$maxperpage\") . \"</a></div>\r\n		\") : (\"\")).\"\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />\r\n\r\n<div>\r\n	<a href=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'bburl\'] . \"/\" . $GLOBALS[\'vbulletin\']->options[\'forumhome\'] . \".php\\\" accesskey=\\\"1\\\"><strong>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \"</strong>