(381, -1, 'register_rules', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - \".(($show[\'coppa\']) ? (\"$vbphrase[coppa_rules]\") : (\"$vbphrase[forum_rules]\")).\"</title>\r\n</head>\r\n<body>\r\n$header\r\n\r\n<br />\r\n<br />\r\n\r\n<form action=\\\"register.php?do=register\\\" method=\\\"post\\\">\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"register\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"url\\\" value=\\\"$url\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"month\\\" value=\\\"$month\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"day\\\" value=\\\"$day\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"year\\\" value=\\\"$year\\\" />\r\n\".(($show[\'coppa\']) ? (\"\r\n<input type=\\\"hidden\\\" name=\\\"who\\\" value=\\\"coppa\\\" />\r\n\") : (\"\r\n<input type=\\\"hidden\\\" name=\\\"who\\\" value=\\\"adult\\\" />\r\n\")).\"\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\" . construct_phrase(\"$vbphrase[x_rules]\", \"\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \"\") . \"</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n			<fieldset class=\\\"fieldset\\\">\r\n				<legend>$vbphrase[forum_rules]</legend>\r\n				<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n				<tr>\r\n					<td>$vbphrase[to_proceed_must_agree]</td>\r\n				</tr>\r\n				<tr>\r\n					<td>\r\n						<div class=\\\"page\\\" style=\\\"border:thin inset; padding:$stylevar[cellpadding]px;\".((!is_browser(\'konqueror\')) ? (\" height:175px; overflow:auto\") : (\"\")).\"\\\">\r\n\r\n							\".(($show[\'coppa\']) ? (\"\r\n							<!-- coppa regulations -->\r\n							<p><strong>$vbphrase[coppa_policy]</strong></p>\r\n\r\n							\" . construct_phrase(\"$vbphrase[coppa_rules_description]\", \"\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \"\", \"\" . $GLOBALS[\'vbulletin\']->options[\'forumhome\'] . \".php\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl_q\'] . \"\", \"register.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=coppaform\", \"\" . $GLOBALS[\'vbulletin\']->options[\'webmasteremail\'] . \"\") . \"\r\n							<!-- / coppa regulations -->\r\n							\") : (\"\")).\"\r\n\r\n							<!-- regular forum rules -->\r\n							\" . construct_phrase(\"$vbphrase[forum_rules_registration]\", \"\" . $GLOBALS[\'vbulletin\']->options[\'forumhome\'] . \".php\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl_q\'] . \"\", \"\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \"\") . \"\r\n							\" . construct_phrase(\"$vbphrase[forum_rules_description]\", \"\" . $GLOBALS[\'vbulletin\']->options[\'forumhome\'] . \".php\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl_q\'] . \"\", \"\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \"\") . \"\r\n							<!-- regular forum rules -->\r\n\r\n						</div>\r\n						<div><label for=\\\"cb_rules_agree\\\"><input type=\\\"checkbox\\\" name=\\\"agree\\\" id=\\\"cb_rules_agree\\\" value=\\\"1\\\" /><strong>\" . construct_phrase(\"$vbphrase[read_agree_abide_by_rules]\", \"\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \"\") . \"</strong></label></div>\r\n					</td>\r\n				</tr>\r\n				</table>\r\n			</fieldset>\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[register]\\\" accesskey=\\\"s\\\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>\r\n\r\n<br />\r\n<br />\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n<title>$vboptions[bbtitle] - <if condition=\"$show[\'coppa\']\">$vbphrase[coppa_rules]<else />$vbphrase[forum_rules]</if></title>\r\n</head>\r\n<body>\r\n$header\r\n\r\n<br />\r\n<br />\r\n\r\n<form action=\"register.php?do=register\" method=\"post\">\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n<input type=\"hidden\" name=\"do\" value=\"register\" />\r\n<input type=\"hidden\" name=\"url\" value=\"$url\" />\r\n<input type=\"hidden\" name=\"month\" value=\"$month\" />\r\n<input type=\"hidden\" name=\"day\" value=\"$day\" />\r\n<input type=\"hidden\" name=\"year\" value=\"$year\" />\r\n<if condition=\"$show[\'coppa\']\">\r\n<input type=\"hidden\" name=\"who\" value=\"coppa\" />\r\n<else />\r\n<input type=\"hidden\" name=\"who\" value=\"adult\" />\r\n</if>\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\"><phrase 1=\"$vboptions[bbtitle]\">$vbphrase[x_rules]</phrase></td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n\r\n			<fieldset class=\"fieldset\">\r\n				<legend>$vbphrase[forum_rules]</legend>\r\n				<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\" width=\"100%\">\r\n				<tr>\r\n					<td>$vbphrase[to_proceed_must