(382, -1, 'register_verify_age', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n	<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $vbphrase[register]</title>\r\n<script type=\\\"text/javascript\\\">\r\n<!--\r\nfunction checkform(formobj)\r\n{\r\n	if (formobj.month.selectedIndex == 0)\r\n	{\r\n		alert(\\\"$vbphrase[select_a_month]\\\");\r\n		return false;\r\n	}\r\n	if (formobj.day.selectedIndex == 0)\r\n	{\r\n		alert(\\\"$vbphrase[select_a_day]\\\");\r\n		return false;\r\n	}\r\n	if (! formobj.year.value.match(/^\\\\d{4}$/))\r\n	{\r\n 		alert(\\\"$vbphrase[please_enter_a_proper_year]\\\");\r\n		return false;\r\n	}\r\n	return true;\r\n}\r\n// -->\r\n</script>\r\n</head>\r\n<body>\r\n$header\r\n\r\n<br />\r\n<br />\r\n\r\n<form action=\\\"register.php?do=checkdate\\\" method=\\\"post\\\" onsubmit=\\\"return checkform(this)\\\">\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"checkdate\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"url\\\" value=\\\"$url\\\" />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"70%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\" . construct_phrase(\"$vbphrase[register_at_x]\", \"\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \"\") . \"</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:70%\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n			<fieldset class=\\\"fieldset\\\">\r\n				<legend>$vbphrase[please_enter_your_date_of_birth]