(383, -1, 'reputation', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $vbphrase[reputation]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<form action=\\\"reputation.php?do=addreputation&amp;p=$postid\\\" method=\\\"post\\\">\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[reputation]</td>\r\n</tr>\r\n$reputationbit\r\n</table>\r\n</form>\r\n\r\n$footer\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n<title>$vboptions[bbtitle] - $vbphrase[reputation]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<form action=\"reputation.php?do=addreputation&amp;p=$postid\" method=\"post\">\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">$vbphrase[reputation]</td>\r\n</tr>\r\n$reputationbit\r\n</table>\r\n</form>\r\n\r\n$footer\r\n</body>\r\n</html>', 'template', 1195729860, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
(384, -1, 'reputationbit', '<tr>\r\n	<td class=\\\"thead\\\">$vbphrase[add_to_reputation]: <span style=\\\"font-weight:normal\\\">$userinfo[username]</span></td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div \".((!$show[\'ajax\']) ? (\"style=\\\"width:$stylevar[formwidth]\\\"\") : (\"\")).\" align=\\\"$stylevar[left]\\\">\r\n\r\n		<fieldset class=\\\"fieldset\\\">\r\n			<legend>\" . construct_phrase(\"$vbphrase[what_do_you_think_of_xs_post]\", \"$userinfo[username]\") . \"</legend>\r\n			<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n			<tr>\r\n				<td>\r\n					<div><label for=\\\"rb_reputation_pos_$postid\\\"><input type=\\\"radio\\\" name=\\\"reputation\\\" value=\\\"pos\\\" id=\\\"rb_reputation_pos_$postid\\\" checked=\\\"checked\\\" />$vbphrase[i_approve]</label></div>\r\n					\".(($show[\'negativerep\']) ? (\"<div><label for=\\\"rb_reputation_neg_$postid\\\"><input type=\\\"radio\\\" name=\\\"reputation\\\" value=\\\"neg\\\" id=\\\"rb_reputation_neg_$postid\\\" />$vbphrase[i_disapprove]</label></div>\") : (\"\")).\"\r\n				</td>\r\n			</tr>\r\n			<tr>\r\n				<td>\r\n					$vbphrase[your_comments_on_this_post]:<br />\r\n					<input type=\\\"text\\\" class=\\\"bginput\\\" size=\\\"40\\\" maxlength=\\\"250\\\" name=\\\"reason\\\" id=\\\"reason_$postid\\\"/>\r\n				</td>\r\n			</tr>\r\n			</table>\r\n		</fieldset>\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"addreputation\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"p\\\" value=\\\"$postid\\\" />\r\n		<input type=\\\"hidden\\\" name=\\