(387, -1, 'reputation_yourpost', '<tr>\r\n	<td class=\\\"thead\\\">\" . construct_phrase(\"$vbphrase[reputation_on_post_is_x]\", \"showthread.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"p=$postid#post$postid\", \"$reputation\") . \"</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div \".((!$show[\'ajax\']) ? (\"style=\\\"width:$stylevar[formwidth]\\\"\") : (\"\")).\" align=\\\"$stylevar[left]\\\">\r\n\r\n		<fieldset class=\\\"fieldset\\\">\r\n			<legend>$vbphrase[comments_on_this_post]</legend>\r\n			<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n			$reputation_reasonbits\r\n			</table>\r\n		</fieldset>\r\n\r\n		<div class=\\\"fieldset\\\"><strong>\" . construct_phrase(\"$vbphrase[you_have_x_reputation_points]\", \"\" . $GLOBALS[\'vbulletin\']->userinfo[\'reputation\'] . \"\") . \"</strong></div>\r\n\r\n		</div>\r\n	</div>\r\n	</td>\r\n</tr>', '<tr>\r\n	<td class=\"thead\"><phrase 1=\"showthread.php?$session[sessionurl]p=$postid#post$postid\" 2=\"$reputation\">$vbphrase[reputation_on_post_is_x]</phrase></td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div <if condition=\"!$show[\'ajax\']\">style=\"width:$stylevar[formwidth]\"</if> align=\"$stylevar[left]\">\r\n\r\n		<fieldset class=\"fieldset\">\r\n			<legend>$vbphrase[comments_on_this_post]</legend>\r\n			<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n			$reputation_reasonbits\r\n			</table>\r\n		</fieldset>\r\n\r\n		<div class=\"fieldset\"><strong><phrase 1=\"$bbuserinfo[reputation]\">$vbphrase[you_have_x_reputation_points]</phrase></strong></div>\r\n\r\n		</div>\r\n	</div>\r\n	</td>\r\n</tr>', 'template', 1147900455, 'vBulletin Solutions', '3.6.0 Beta 1', 'vbulletin'),
(388, -1, 'search_forums', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - \".(($show[\'searchthread\']) ? (\"$vbphrase[search_thread]\") : (\"$vbphrase[search_forums]\")).\"</title>\r\n$tag_cloud_headinclude\r\n</head>\r\n\r\n<body>\r\n$header\r\n$navbar\r\n\r\n\".(($show[\'errors\']) ? (\"\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n			$vbphrase[errors_occured_with_search]:\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"alt1\\\">\r\n			<ol>$errorlist</ol>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />\r\n\") : (\"\")).\"\r\n\r\n<form action=\\\"search.php?do=process\\\" method=\\\"post\\\" name=\\\"vbform\\\" id=\\\"searchform\\\" style=\\\"display:block; margin:0px\\\">\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"process\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"searchthreadid\\\" value=\\\"$searchthreadid\\\" />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		\".(($show[\'searchthread\']) ? (\"$vbphrase[search_thread] - <a href=\\\"showthread.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"t=$threadinfo[threadid]\\\">$threadinfo[title]</a>\") : (\"$vbphrase[search_forums]\")).\"\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\"