width:150px\">\r\n						<option value=\"0\" $searchdateselected[0]>$vbphrase[any_date]</option>\r\n						<option value=\"lastvisit\" $searchdateselected[lastvisit]>$vbphrase[your_last_visit]</option>\r\n						<option value=\"1\" $searchdateselected[1]>$vbphrase[yesterday]</option>\r\n						<option value=\"7\" $searchdateselected[7]>$vbphrase[a_week_ago]</option>\r\n						<option value=\"14\" $searchdateselected[14]><phrase 1=\"2\">$vbphrase[x_weeks_ago]</phrase></option>\r\n						<option value=\"30\" $searchdateselected[30]>$vbphrase[a_month_ago]</option>\r\n						<option value=\"90\" $searchdateselected[90]><phrase 1=\"3\">$vbphrase[x_months_ago]</phrase></option>\r\n						<option value=\"180\" $searchdateselected[180]><phrase 1=\"6\">$vbphrase[x_months_ago]</phrase></option>\r\n						<option value=\"365\" $searchdateselected[365]>$vbphrase[a_year_ago]</option>\r\n					</select>\r\n					<select name=\"beforeafter\">\r\n						<option value=\"after\" $beforeafterselected[after]>$vbphrase[and_newer]</option>\r\n						<option value=\"before\" $beforeafterselected[before]>$vbphrase[and_older]</option>\r\n					</select>\r\n				</div>\r\n			</fieldset>\r\n\r\n			<if condition=\"!$show[\'searchthread\']\">\r\n			<fieldset class=\"fieldset\">\r\n				<legend>$vbphrase[sort_results_by]</legend>\r\n				<div style=\"padding:$stylevar[formspacer]px\">\r\n					<select name=\"sortby\" style=\"width:150px\">\r\n						<option value=\"rank\" $sortbyselected[rank]>$vbphrase[relevancy]</option>\r\n						<option value=\"title\" $sortbyselected[title]>$vbphrase[title]</option>\r\n						<option value=\"replycount\" $sortbyselected[replycount]>$vbphrase[number_of_replies]</option>\r\n						<option value=\"views\" $sortbyselected[views]>$vbphrase[number_of_views]</option>\r\n						<option value=\"threadstart\" $sortbyselected[threadstart]>$vbphrase[thread_start_date]</option>\r\n						<option value=\"lastpost\" $sortbyselected[lastpost]>$vbphrase[last_posting_date]</option>\r\n						<option value=\"postusername\" $sortbyselected[postusername]>$vbphrase[username]</option>\r\n						<option value=\"forum\" $sortbyselected[forum]>$vbphrase[forum]</option>\r\n					</select>\r\n					<select name=\"order\">\r\n						<option value=\"descending\" $sortorderselected[descending]>$vbphrase[in_descending_order]</option>\r\n						<option value=\"ascending\" $sortorderselected[ascending]>$vbphrase[in_ascending_order]</option>\r\n					</select>\r\n				</div>\r\n			</fieldset>\r\n\r\n			<fieldset class=\"fieldset\">\r\n				<legend>$vbphrase[show_results_as]</legend>\r\n				<div style=\"padding:$stylevar[formspacer]px\">\r\n					<label for=\"rb_showposts_0\"><input type=\"radio\" name=\"showposts\" value=\"0\" id=\"rb_showposts_0\" $showpostschecked[0] />$vbphrase[threads]</label>\r\n					<label for=\"rb_showposts_1\"><input type=\"radio\" name=\"showposts\" value=\"1\" id=\"rb_showposts_1\" $showpostschecked[1] />$vbphrase[posts]</label>\r\n				</div>\r\n			</fieldset>\r\n			</if>\r\n		</td>\r\n		<if condition=\"!$show[\'searchthread\']\">\r\n		<td width=\"50%\">\r\n			<if condition=\"$show[\'tag_option\']\">\r\n			<fieldset class=\"fieldset\">\r\n				<legend>$vbphrase[search_by_tag]</legend>\r\n				<div style=\"padding:$stylevar[formspacer]px\">\r\n					<div>$vbphrase[tag]:</div>\r\n					<div id=\"tag_add\"><input type=\"text\" class=\"bginput\" name=\"tag\" id=\"tag_add_input\" size=\"35\" value=\"$formdata[tag]\" style=\"width:250px\" /></div>\r\n\r\n					<if condition=\"$show[\'popups\']\">\r\n						<div id=\"tag_add_menu\" class=\"vbmenu_popup\" style=\"display:none\"></div>\r\n						<script type=\"text/javascript\" src=\"clientscript/vbulletin_ajax_tagsugg.js?v=$vboptions[simpleversion]\"></script>\r\n						<script type=\"text/javascript\">\r\n						<!--\r\n						vbmenu_register(\'tag_add\', true);\r\n						tag_add_comp = new vB_AJAX_TagSuggest(\'tag_add_comp\', \'tag_add_input\', \'tag_add\');\r\n						//-->\r\n						</script>\r\n					</if>\r\n				</div>\r\n			</fieldset>\r\n			</if>\r\n\r\n			<fieldset class=\"fieldset\" style=\"margin:0px\">\r\n				<legend>$vbphrase[search_in_forums]</legend>\r\n				<div style=\"padding:$stylevar[formspacer]px\">\r\n					<div>\r\n						<select style=\"width:100%\" name=\"forumchoice[]\" size=\"13\" multiple=\"multiple\">\r\n							<option value=\"0\" $noforumselected>$vbphrase[search_all_open_forums]</option>\r\n							<option value=\"subscribed\">$vbphrase[search_subscribed_forums]</option>\r\n							$searchforumbits\r\n						</select>\r\n					</div>\r\n					<div><label for=\"cb_childforums\"><input type=\"checkbox\" name=\"childforums\" value=\"1\" id=\"cb_childforums\" $childforumschecked[1] />$vbphrase[also_search_in_child_forums]</label></div>\r\n					<if condition=\"$show[\'cantsearchposts\']\">$vbphrase[you_can_only_search_thread_titles]</if>\r\n				</div>\r\n			</fieldset>\r\n		</td>\r\n		</if>\r\n	</tr>\r\n	</table>\r\n	</div>\r\n\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"submit\" class=\"button\" name=\"dosearch\" value=\"$vbphrase[search_now]\" accesskey=\"s\" />\r\n		<input type=\"reset\" class=\"button\" value=\"$vbphrase[reset_fields]\" accesskey=\"r\" onclick=\"window.location=\'search.php?$session[sessionurl]type=advanced\';\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<if condition=\"$show[\'member\']\">\r\n	<div align=\"center\" style=\"margin-top:20px\">\r\n		<select name=\"saveprefs\">\r\n			<option value=\"1\" selected=\"selected\">$vbphrase[save_search_preferences]</option>\r\n			<option value=\"0\">$vbphrase[clear_search_preferences]</option>\r\n		</select>\r\n		<input type=\"submit\" class=\"button\" name=\"doprefs\" value=\"$vbphrase[go]\" id=\"save_searchprefs\" />\r\n		<input type=\"image\" src=\"$vboptions[cleargifurl]\" style=\"width: 1px; height: 1px;\" />\r\n		<script type=\"text/javascript\" src=\"clientscript/vbulletin_ajax_search.js?v=$vboptions[simpleversion]\"></script>\r\n		<script type=\"text/javascript\">\r\n\r\n		<!--\r\n		vB_AJAX_SearchPrefs_Init(\'save_searchprefs\');\r\n		//-->\r\n\r\n		</script>\r\n	</div>\r\n</if>\r\n\r\n</form>\r\n\r\n<if condition=\"$tag_cloud\">\r\n	<div style=\"margin-top:20px\">$tag_cloud</div>\r\n</if>\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', 'template', 1213274609, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(389, -1, 'search_results', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $vbphrase[search_results]</title>\r\n\".(($show[\'inlinemod\']) ? (\"<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_inlinemod.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\") : (\"\")).\"\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n$template_hook[search_results_top]\r\n\r\n\".(($pagenav) ? (\"\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\" style=\\\"margin-bottom:3px\\\">\r\n<tr valign=\\\"bottom\\\">\r\n	<td align=\\\"$stylevar[right]\\\">$pagenav</td>\r\n</tr>\r\n</table>\r\n\") : (\"\")).\"\r\n\r\n<form action=\\\"inlinemod.php?forumid=$forumid\\\" method=\\\"post\\\" id=\\\"inlinemodform\\\">\r\n<input type=\\\"hidden\\\" name=\\\"url\\\" value=\\\"$url\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"forumid\\\" value=\\\"$forumid\\\" />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\" id=\\\"threadslist\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\" colspan=\\\"$threadcolspan\\\" style=\\\"font-weight:normal\\\">\r\n\r\n		\".(($show[\'inlinemod\'] AND $search[\'showposts\']) ? (\"<input name=\\\"allbox\\\" style=\\\"margin: 0px 0px 0px 5px; padding: 0px; float: $stylevar[right]; vertical-align: middle;\\\" id=\\\"checkall_all\\\" title=\\\"$vbphrase[check_uncheck_all]\\\" onclick=\\\"inlineMod.check_all();\\\" type=\\\"checkbox\\\" />\") : (\"\")).\"\r\n		<span class=\\\"smallfont\\\" style=\\\"float:$stylevar[right]\\\">\r\n			\".(($show[\'results\']) ? (\"\r\n			\" . construct_phrase(\"$vbphrase[showing_results_x_to_y_of_z]\", \"$first\", \"$last\", \"$numitems\") . \"\r\n			<br />\r\n			\") : (\"\")).\"\r\n			\".(($show[\'generated\']) ? (\"\r\n			\" . construct_phrase(\"$vbphrase[search_took_x_seconds_gen_y_mins]\", \"$searchtime\", \"$searchminutes\") . \"\r\n			\") : (\"\r\n			\" . construct_phrase(\"$vbphrase[search_took_x_seconds]\", \"$searchtime\") . \"\r\n			\")).\"\r\n		</span>\r\n\r\n		<a href=\\\"search.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"$searchquery\\\"><strong>$vbphrase[search]:</strong></a>\r\n		<span class=\\\"smallfont\\\">\r\n		\".(($action == \'process\') ? (\"\r\n			\".(($displayWords) ? (\"$vbphrase[key_words]: $displayWords\") : (\"\")).\"\r\n\r\n			\".(($displayUsers) ? (\"\r\n				\".(($displayWords) ? (\"; \") : (\"\")).\"\r\n				\".(($starteronly) ? (\"$vbphrase[threads_started_by]\") : (\"$vbphrase[posts_made_by]\")).\": $displayUsers\r\n			\") : (\"\")).\"\r\n\r\n			\".(($display_tag) ? (\"\r\n				\".(($displayWords OR $displayUsers) ? (\"; \") : (\"\")).\"\r\n				$vbphrase[tag]: $display_tag\r\n			\") : (\"\")).\"\r\n\r\n			\".(($display_prefixes) ? (\"\r\n				\".(($displayWords OR $displayUsers OR $display_tag) ? (\"; \") : (\"\")).\"\r\n				$vbphrase[prefix]: $display_prefixes \".(($show[\'no_prefix\']) ? (\"$vbphrase[or_no_prefix]\") : (\"\")).\"\r\n			\") : (\"\")).\"\r\n		\") : (\"\".(($action == \'getnew\') ? (\"\r\n			$vbphrase[new_posts_nav]\r\n		\") : (\"\".(($action == \'getdaily\') ? (\"\r\n			$vbphrase[posts_from_last_day]\r\n		\") : (\"\")).\"\")).\"\")).\"\r\n\r\n		\".(($displayForums) ? (\"\r\n			; $vbphrase[forum]: $displayForums \".(($childforums) ? (\"$vbphrase[and_child_forums]\") : (\"\")).\"\r\n		\") : (\"\")).\"\r\n		\".(($show[\'titleonlysearch\']) ? (\"\r\n			<br /><strong>\" . construct_phrase(\"$vbphrase[thread_titles_only_search]\", \"$titlesearchurl\") . \"</strong>\r\n		\") : (\"\")).\"\r\n		</span>\r\n	</td>\r\n</tr>\r\n\r\n\".(($displayCommon) ? (\"\r\n<tr>\r\n	<td class=\\\"thead\\\" style=\\\"font-weight: normal\\\" colspan=\\\"$threadcolspan\\\">$vbphrase[words_very_common]: $displayCommon</td>\r\n</tr>\r\n\") : (\"\")).\"\r\n\r\n\".(($search[\'showposts\']) ? (\"\r\n\r\n</table>\r\n\r\n$searchbits\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n\r\n\") : (\"\r\n$announcebits\r\n<tr>\r\n	\".(($show[\'threadicons\']) ? (\"\r\n		<td class=\\\"thead\\\" colspan=\\\"2\\\">&nbsp;</td>\r\n	\") : (\"\r\n		<td class=\\\"thead\\\">&nbsp;</td>\r\n	\")).\"\r\n	<td class=\\\"thead\\\" width=\\\"75%\\\">$vbphrase[thread] / $vbphrase[thread_starter]</td>\r\n	<td class=\\\"thead\\\" width=\\\"150\\\" align=\\\"center\\\" nowrap=\\\"nowrap\\\">$vbphrase[last_post]</td>\r\n	<td class=\\\"thead\\\" align=\\\"center\\\" nowrap=\\\"nowrap\\\">$vbphrase[replies]</td>\r\n	<td class=\\\"thead\\\" align=\\\"center\\\" nowrap=\\\"nowrap\\\">$vbphrase[views]</td>\r\n	<td class=\\\"thead\\\" width=\\\"25%\\\">$vbphrase[forum]</td>\r\n\r\n	\".(($show[\'inlinemod\']) ? (\"\r\n		\".(($show[\'popups\']) ? (\"\r\n			<td class=\\\"vbmenu_control\\\" id=\\\"imod\\\" align=\\\"center\\\" title=\\\"$vbphrase[moderation]\\\"> <script type=\\\"text/javascript\\\"> vbmenu_register(\'imod\'); </script> </td>\r\n		\") : (\"\r\n			<td class=\\\"thead\\\" align=\\\"center\\\">\r\n				<input type=\\\"checkbox\\\" name=\\\"allbox\\\" id=\\\"checkall_all\\\" title=\\\"$vbphrase[check_uncheck_all]\\\" onclick=\\\"inlineMod.check_all()\\\" />\r\n			</td>\r\n		\")).\"\r\n\r\n\r\n	\") : (\"\")).\"\r\n\r\n</tr>\r\n\r\n\".((!$show[\'results\']) ? (\"\r\n	<!-- show no threads message -->\r\n	<tr>\r\n		<td class=\\\"alt1\\\" colspan=\\\"$threadcolspan\\\" align=\\\"center\\\">\r\n			<div style=\\\"padding: 16px\\\">\r\n				<strong>$vbphrase[no_unread_threads]</strong>\r\n			</div>\r\n		</td>\r\n	</tr>\r\n	<!-- end show no threads message -->\r\n\") : (\"\r\n$searchbits\r\n\")).\"\r\n\r\n\")).\"\r\n\r\n<tr>\r\n	<td class=\\\"tfoot\\\" colspan=\\\"$threadcolspan\\\" align=\\\"$stylevar[right]\\\">\r\n		\".(($show[\'results\']) ? (\"\r\n		<span class=\\\"smallfont\\\">\" . construct_phrase(\"$vbphrase[showing_results_x_to_y_of_z]\", \"$first\", \"$last\", \"$numitems\") . \"</span>\r\n		\") : (\"\r\n		&nbsp;\r\n		\")).\"\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n\".(($pagenav) ? (\"\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\" style=\\\"margin-top:3px\\\">\r\n<tr valign=\\\"top\\\">\r\n	\".(($pagenav) ? (\"<td align=\\\"$stylevar[right]\\\">$pagenav</td>\") : (\"\")).\"\r\n</tr>\r\n</table>\r\n\") : (\"\")).\"\r\n\r\n\".(($show[\'ajax_js\'] AND $show[\'results\'] AND !$search[\'showposts\']) ? (\"\r\n	<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_ajax_threadslist.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n	<script type=\\\"text/javascript\\\">\r\n	<!--\r\n	vB_AJAX_Threadlist_Init(\'threadslist\');\r\n	var titlemaxchars = parseInt(\\\"\" . $GLOBALS[\'vbulletin\']->options[\'titlemaxchars\'] . \"\\\");\r\n	//-->\r\n	</script>\r\n\") : (\"\")).\"\r\n\r\n\".(($show[\'inlinemod\']) ? (\"\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\" style=\\\"margin-top:3px\\\">\r\n<tr valign=\\\"top\\\">\r\n	<td align=\\\"$stylevar[right]\\\">\r\n		<div class=\\\"smallfont\\\" style=\\\"text-align:$stylevar[left]; white-space:nowrap; float:$stylevar[right]\\\">\r\n		<strong>$vbphrase[moderation]</strong><br />\r\n		\".((!$search[\'showposts\']) ? (\"\r\n			<select name=\\\"do\\\">\r\n				\".(($show[\'deletethread\'] OR $show[\'spamctrls\'] OR $show[\'openthread\'] OR $show[\'approvethread\'] OR $show[\'movethread\'] OR $template_hook[\'inlinemod_thread_bottom\']) ? (\"\r\n				<optgroup label=\\\"$vbphrase[option]\\\">\r\n\r\n					\".(($show[\'deletethread\']) ? (\"\r\n					<option value=\\\"deletethread\\\">$vbphrase[delete_threads]</option>\r\n					<option value=\\\"undeletethread\\\">$vbphrase[undelete_threads]</option>\r\n					\") : (\"\")).\"\r\n\r\n					\".(($show[\'spamctrls\']) ? (\"\r\n					<option value=\\\"spamthread\\\">$vbphrase[delete_threads_as_spam]</option>\r\n					\") : (\"\")).\"\r\n\r\n					\".(($show[\'openthread\']) ? (\"\r\n					<option value=\\\"open\\\">$vbphrase[open_threads]</option>\r\n					<option value=\\\"close\\\">$vbphrase[close_threads]</option>\r\n					\") : (\"\")).\"\r\n\r\n					\".(($show[\'approvethread\']) ? (\"\r\n					<option value=\\\"approvethread\\\">$vbphrase[approve_threads]</option>\r\n					<option value=\\\"unapprovethread\\\">$vbphrase[unapprove_threads]</option>\r\n					\") : (\"\")).\"\r\n\r\n					\".(($show[\'movethread\']) ? (\"\r\n					<option value=\\\"stick\\\">$vbphrase[stick_threads]</option>\r\n					<option value=\\\"unstick\\\">$vbphrase[unstick_threads]</option>\r\n					<option value=\\\"movethread\\\">$vbphrase[move_threads]</option>\r\n					<option value=\\\"mergethread\\\">$vbphrase[merge_threads]</option>\r\n					\") : (\"\")).\"\r\n\r\n					$template_hook[inlinemod_thread_bottom]\r\n				</optgroup>\r\n				\") : (\"\")).\"\r\n				<optgroup label=\\\"____________________\\\">\r\n					<option value=\\\"viewthread\\\">$vbphrase[view_selected_threads]</option>\r\n					<option value=\\\"clearthread\\\">$vbphrase[clear_thread_list]</option>\r\n				</optgroup>\r\n			</select><input type=\\\"submit\\\" class=\\\"button\\\" id=\\\"inlinego\\\" value=\\\"$vbphrase[go]\\\" />\r\n			<script type=\\\"text/javascript\\\">\r\n			<!--\r\n			inlineMod = new vB_Inline_Mod(\'inlineMod\', \'thread\', \'inlinemodform\', \'$vbphrase[go_x]\');\r\n			//-->\r\n			</script>\r\n		\") : (\"\r\n			<select name=\\\"do\\\">\r\n				<optgroup label=\\\"$vbphrase[option]\\\">\r\n					\".(($show[\'managethread\']) ? (\"\r\n					<option value=\\\"mergeposts\\\">$vbphrase[merge_posts]</option>\r\n					<option value=\\\"moveposts\\\">$vbphrase[move_posts]</option>\r\n					<option value=\\\"copyposts\\\">$vbphrase[copy_posts]</option>\r\n					\") : (\"\")).\"\r\n\r\n					\".(($show[\'spamctrls\']) ? (\"\r\n					<option value=\\\"spampost\\\">$vbphrase[delete_posts_as_spam]</option>\r\n					\") : (\"\")).\"\r\n\r\n					\".(($show[\'managepost\']) ? (\"\r\n					<option value=\\\"deleteposts\\\">$vbphrase[delete_posts]</option>\r\n					<option value=\\\"undeleteposts\\\">$vbphrase[undelete_posts]</option>\r\n					\") : (\"\")).\"\r\n\r\n					\".(($show[\'approvepost\']) ? (\"\r\n					<option value=\\\"approveposts\\\">$vbphrase[approve_posts]</option>\r\n					<option value=\\\"unapproveposts\\\">$vbphrase[unapprove_posts]</option>\r\n					\") : (\"\")).\"\r\n\r\n					\".(($show[\'approveattachment\']) ? (\"\r\n					<option value=\\\"approveattachments\\\">$vbphrase[approve_attachments]</option>\r\n					<option value=\\\"unapproveattachments\\\">$vbphrase[unapprove_attachments]</option>\r\n					\") : (\"\")).\"\r\n\r\n					$template_hook[inlinemod_post_bottom]\r\n				</optgroup>\r\n				<optgroup label=\\\"____________________\\\">\r\n					<option value=\\\"viewpost\\\">$vbphrase[view_selected_posts]</option>\r\n					<option value=\\\"clearpost\\\">$vbphrase[clear_post_list]</option>\r\n				</optgroup>\r\n			</select><input type=\\\"submit\\\" class=\\\"button\\\" id=\\\"inlinego\\\" value=\\\"$vbphrase[go]\\\" />\r\n			<script type=\\\"text/javascript\\\">\r\n			<!--\r\n			inlineMod = new vB_Inline_Mod(\'inlineMod\', \'post\', \'inlinemodform\', \'$vbphrase[go_x]\');\r\n			//-->\r\n			</script>\r\n		\")).\"\r\n		</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\") : (\"\")).\"\r\n\r\n</form>\r\n\r\n<br />\r\n\r\n$template_hook[search_results_bottom]\r\n\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n<tr>\r\n	<td width=\\\"100%\\\">&nbsp;</td>\r\n	<td>$forumjump</td>\r\n</tr>\r\n</table>\r\n\r\n\".(($show[\'inlinemod\'] AND $show[\'popups\']) ? (\"\r\n	<div class=\\\"vbmenu_popup\\\" id=\\\"imod_menu\\\" style=\\\"display:none\\\" align=\\\"$stylevar[left]\\\">\r\n		$threadadmin_imod_menu\r\n	</div>\r\n\") : (\"\")).\"\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n<title>$vboptions[bbtitle] - $vbphrase[search_results]</title>\r\n<if condition=\"$show[\'inlinemod\']\"><script type=\"text/javascript\" src=\"clientscript/vbulletin_inlinemod.js?v=$vboptions[simpleversion]\"></script></if>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n$template_hook[search_results_top]\r\n\r\n<if condition=\"$pagenav\">\r\n<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"margin-bottom:3px\">\r\n<tr valign=\"bottom\">\r\n	<td align=\"$stylevar[right]\">$pagenav</td>\r\n</tr>\r\n</table>\r\n</if>\r\n\r\n<form action=\"inlinemod.php?forumid=$forumid\" method=\"post\" id=\"inlinemodform\">\r\n<input type=\"hidden\" name=\"url\" value=\"$url\" />\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n<input type=\"hidden\" name=\"forumid\" value=\"$forumid\" />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\" id=\"threadslist\">\r\n<tr>\r\n	<td class=\"tcat\" colspan=\"$threadcolspan\" style=\"font-weight:normal\">\r\n\r\n		<if condition=\"$show[\'inlinemod\'] AND $search[\'showposts\']\"><input name=\"allbox\" style=\"margin: 0px 0px 0px 5px; padding: 0px; float: $stylevar[right]; vertical-align: middle;\" id=\"checkall_all\" title=\"$vbphrase[check_uncheck_all]\" onclick=\"inlineMod.check_all();\" type=\"checkbox\" /></if>\r\n		<span class=\"smallfont\" style=\"float:$stylevar[right]\">\r\n			<if condition=\"$show[\'results\']\">\r\n			<phrase 1=\"$first\" 2=\"$last\" 3=\"$numitems\">$vbphrase[showing_results_x_to_y_of_z]</phrase>\r\n			<br />\r\n			</if>\r\n			<if condition=\"$show[\'generated\']\">\r\n			<phrase 1=\"$searchtime\" 2=\"$searchminutes\">$vbphrase[search_took_x_seconds_gen_y_mins]</phrase>\r\n			<else />\r\n			<phrase 1=\"$searchtime\">$vbphrase[search_took_x_seconds]</phrase>\r\n			</if>\r\n		</span>\r\n\r\n		<a href=\"search.php?$session[sessionurl]$searchquery\"><strong>$vbphrase[search]:</strong></a>\r\n		<span class=\"smallfont\">\r\n		<if condition=\"$action == \'process\'\">\r\n			<if condition=\"$displayWords\">$vbphrase[key_words]: $displayWords</if>\r\n\r\n			<if condition=\"$displayUsers\">\r\n				<if condition=\"$displayWords\">; </if>\r\n				<if condition=\"$starteronly\">$vbphrase[threads_started_by]<else />$vbphrase[posts_made_by]</if>: $displayUsers\r\n			</if>\r\n\r\n			<if condition=\"$display_tag\">\r\n				<if condition=\"$displayWords OR $displayUsers\">; </if>\r\n				$vbphrase[tag]: $display_tag\r\n			</if>\r\n\r\n			<if condition=\"$display_prefixes\">\r\n				<if condition=\"$displayWords OR $displayUsers OR $display_tag\">; </if>\r\n				$vbphrase[prefix]: $display_prefixes <if condition=\"$show[\'no_prefix\']\">$vbphrase[or_no_prefix]</if>\r\n			</if>\r\n		<else /><if condition=\"$action == \'getnew\'\">\r\n			$vbphrase[new_posts_nav]\r\n		<else /><if condition=\"$action == \'getdaily\'\">\r\n			$vbphrase[posts_from_last_day]\r\n		</if></if></if>\r\n\r\n		<if condition=\"$displayForums\">\r\n			; $vbphrase[forum]: $displayForums <if condition=\"$childforums\">$vbphrase[and_child_forums]</if>\r\n		</if>\r\n		<if condition=\"$show[\'titleonlysearch\']\">\r\n			<br /><strong><phrase 1=\"$titlesearchurl\">$vbphrase[thread_titles_only_search]</phrase></strong>\r\n		</if>\r\n		</span>\r\n	</td>\r\n</tr>\r\n\r\n<if condition=\"$displayCommon\">\r\n<tr>\r\n	<td class=\"thead\" style=\"font-weight: normal\" colspan=\"$threadcolspan\">$vbphrase[words_very_common]: $displayCommon</td>\r\n</tr>\r\n</if>\r\n\r\n<if condition=\"$search[\'showposts\']\">\r\n\r\n</table>\r\n\r\n$searchbits\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n\r\n<else />\r\n$announcebits\r\n<tr>\r\n	<if condition=\"$show[\'threadicons\']\">\r\n		<td class=\"thead\" colspan=\"2\">&nbsp;</td>\r\n	<else />\r\n		<td class=\"thead\">&nbsp;</td>\r\n	</if>\r\n	<td class=\"thead\" width=\"75%\">$vbphrase[thread] / $vbphrase[thread_starter]</td>\r\n	<td class=\"thead\" width=\"150\" align=\"center\" nowrap=\"nowrap\">$vbphrase[last_post]</td>\r\n	<td class=\"thead\" align=\"center\" nowrap=\"nowrap\">$vbphrase[replies]</td>\r\n	<td class=\"thead\" align=\"center\" nowrap=\"nowrap\">$vbphrase[views]</td>\r\n	<td class=\"thead\" width=\"25%\">$vbphrase[forum]</td>\r\n\r\n	<if condition=\"$show[\'inlinemod\']\">\r\n		<if condition=\"$show[\'popups\']\">\r\n			<td class=\"vbmenu_control\" id=\"imod\" align=\"center\" title=\"$vbphrase[moderation]\"> <script type=\"text/javascript\"> vbmenu_register(\'imod\'); </script> </td>\r\n		<else />\r\n			<td class=\"thead\" align=\"center\">\r\n				<input type=\"checkbox\" name=\"allbox\" id=\"checkall_all\" title=\"$vbphrase[check_uncheck_all]\" onclick=\"inlineMod.check_all()\" />\r\n			</td>\r\n		</if>\r\n\r\n\r\n	</if>\r\n\r\n</tr>\r\n\r\n<if condition=\"!$show[\'results\']\">\r\n	<!-- show no threads message -->\r\n	<tr>\r\n		<td class=\"alt1\" colspan=\"$threadcolspan\" align=\"center\">\r\n			<div style=\"padding: 16px\">\r\n				<strong>$vbphrase[no_unread_threads]</strong>\r\n			</div>\r\n		</td>\r\n	</tr>\r\n	<!-- end show no threads message -->\r\n<else />\r\n$searchbits\r\n</if>\r\n\r\n</if>\r\n\r\n<tr>\r\n	<td class=\"tfoot\" colspan=\"$threadcolspan\" align=\"$stylevar[right]\">\r\n		<if condition=\"$show[\'results\']\">\r\n		<span class=\"smallfont\"><phrase 1=\"$first\" 2=\"$last\" 3=\"$numitems\">$vbphrase[showing_results_x_to_y_of_z]</phrase></span>\r\n		<else />\r\n		&nbsp;\r\n		</if>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<if condition=\"$pagenav\">\r\n<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"margin-top:3px\">\r\n<tr valign=\"top\">\r\n	<if condition=\"$pagenav\"><td align=\"$stylevar[right]\">$pagenav</td></if>\r\n</tr>\r\n</table>\r\n</if>\r\n\r\n<if condition=\"$show[\'ajax_js\'] AND $show[\'results\'] AND !$search[\'showposts\']\">\r\n	<script type=\"text/javascript\" src=\"clientscript/vbulletin_ajax_threadslist.js?v=$vboptions[simpleversion]\"></script>\r\n	<script type=\"text/javascript\">\r\n	<!--\r\n	vB_AJAX_Threadlist_Init(\'threadslist\');\r\n	var titlemaxchars = parseInt(\"$vboptions[titlemaxchars]\");\r\n	//-->\r\n	</script>\r\n</if>\r\n\r\n<if condition=\"$show[\'inlinemod\']\">\r\n<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"margin-top:3px\">\r\n<tr valign=\"top\">\r\n	<td align=\"$stylevar[right]\">\r\n		<div class=\"smallfont\" style=\"text-align:$stylevar[left]; white-space:nowrap; float:$stylevar[right]\">\r\n		<strong>$vbphrase[moderation]</strong><br />\r\n		<if condition=\"!$search[\'showposts\']\">\r\n			<select name=\"do\">\r\n				<if condition=\"$show[\'deletethread\'] OR $show[\'spamctrls\'] OR $show[\'openthread\'] OR $show[\'approvethread\'] OR $show[\'movethread\'] OR $template_hook[\'inlinemod_thread_bottom\']\">\r\n				<optgroup label=\"$vbphrase[option]\">\r\n\r\n					<if condition=\"$show[\'deletethread\']\">\r\n					<option value=\"deletethread\">$vbphrase[delete_threads]</option>\r\n					<option value=\"undeletethread\">$vbphrase[undelete_threads]</option>\r\n					</if>\r\n\r\n					<if condition=\"$show[\'spamctrls\']\">\r\n					<option value=\"spamthread\">$vbphrase[delete_threads_as_spam]</option>\r\n					</if>\r\n\r\n					<if condition=\"$show[\'openthread\']\">\r\n					<option value=\"open\">$vbphrase[open_threads]</option>\r\n					<option value=\"close\">$vbphrase[close_threads]</option>\r\n					</if>\r\n\r\n					<if condition=\"$show[\'approvethread\']\">\r\n					<option value=\"approvethread\">$vbphrase[approve_threads]</option>\r\n					<option value=\"unapprovethread\">$vbphrase[unapprove_threads]</option>\r\n					</if>\r\n\r\n					<if condition=\"$show[\'movethread\']\">\r\n					<option value=\"stick\">$vbphrase[stick_threads]</option>\r\n					<option value=\"unstick\">$vbphrase[unstick_threads]</option>\r\n					<option value=\"movethread\">$vbphrase[move_threads]</option>\r\n					<option value=\"mergethread\">$vbphrase[merge_threads]</option>\r\n					</if>\r\n\r\n					$template_hook[inlinemod_thread_bottom]\r\n				</optgroup>\r\n				</if>\r\n				<optgroup label=\"____________________\">\r\n					<option value=\"viewthread\">$vbphrase[view_selected_threads]</option>\r\n					<option value=\"clearthread\">$vbphrase[clear_thread_list]</option>\r\n				</optgroup>\r\n			</select><input type=\"submit\" class=\"button\" id=\"inlinego\" value=\"$vbphrase[go]\" />\r\n			<script type=\"text/javascript\">\r\n			<!--\r\n			inlineMod = new vB_Inline_Mod(\'inlineMod\', \'thread\', \'inlinemodform\', \'$vbphrase[go_x]\');\r\n			//-->\r\n			</script>\r\n		<else />\r\n			<select name=\"do\">\r\n				<optgroup label=\"$vbphrase[option]\">\r\n					<if condition=\"$show[\'managethread\']\">\r\n					<option value=\"mergeposts\">$vbphrase[merge_posts]</option>\r\n					<option value=\"moveposts\">$vbphrase[move_posts]</option>\r\n					<option value=\"copyposts\">$vbphrase[copy_posts]</option>\r\n					</if>\r\n\r\n					<if condition=\"$show[\'spamctrls\']\">\r\n					<option value=\"spampost\">$vbphrase[delete_posts_as_spam]</option>\r\n					</if>\r\n\r\n					<if condition=\"$show[\'managepost\']\">\r\n					<option value=\"deleteposts\">$vbphrase[delete_posts]</option>\r\n					<option value=\"undeleteposts\">$vbphrase[undelete_posts]</option>\r\n					</if>\r\n\r\n					<if condition=\"$show[\'approvepost\']\">\r\n					<option value=\"approveposts\">$vbphrase[approve_posts]</option>\r\n					<option value=\"unapproveposts\">$vbphrase[unapprove_posts]</option>\r\n					</if>\r\n\r\n					<if condition=\"$show[\'approveattachment\']\">\r\n					<option value=\"approveattachments\">$vbphrase[approve_attachments]</option>\r\n					<option value=\"unapproveattachments\">$vbphrase[unapprove_attachments]</option>\r\n					</if>\r\n\r\n					$template_hook[inlinemod_post_bottom]\r\n				</optgroup>\r\n				<optgroup label=\"____________________\">\r\n					<option value=\"viewpost\">$vbphrase[view_selected_posts]</option>\r\n					<option value=\"clearpost\">$vbphrase[clear_post_list]</option>\r\n				</optgroup>\r\n			</select><input type=\"submit\" class=\"button\" id=\"inlinego\" value=\"$vbphrase[go]\" />\r\n			<script type=\"text/javascript\">\r\n			<!--\r\n			inlineMod = new vB_Inline_Mod(\'inlineMod\', \'post\', \'inlinemodform\', \'$vbphrase[go_x]\');\r\n			//-->\r\n			</script>\r\n		</if>\r\n		</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n</if>\r\n\r\n</form>\r\n\r\n<br />\r\n\r\n$template_hook[search_results_bottom]\r\n\r\n<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\r\n<tr>\r\n	<td width=\"100%\">&nbsp;</td>\r\n	<td>$forumjump</td>\r\n</tr>\r\n</table>\r\n\r\n<if condition=\"$show[\'inlinemod\'] AND $show[\'popups\']\">\r\n	<div class=\"vbmenu_popup\" id=\"imod_menu\" style=\"display:none\" align=\"$stylevar[left]\">\r\n		$threadadmin_imod_menu\r\n	</div>\r\n</if>\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', 'template', 1223077314, 'vBulletin Solutions', '3.8.0 Alpha 2', 'vbulletin'),
(390, -1, 'search_results_postbit', '<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\" style=\\\"margin:$stylevar[cellpadding]px 0px $stylevar[cellpadding]px 0px\\\" id=\\\"post$post[postid]\\\">\r\n<tr>\r\n	<td class=\\\"thead\\\" style=\\\"font-weight:normal\\\">\r\n		\".(($show[\'inlinemod\']) ? (\"\r\n			<input type=\\\"checkbox\\\" name=\\\"plist[$post[postid]]\\\" id=\\\"plist_$post[postid]\\\" style=\\\"float:$stylevar[right]; vertical-align:middle; padding:0px; margin:0px 0px 0px 5px\\\" value=\\\"1\\\" \".(($show[\'disabled\']) ? (\"disabled=\\\"disabled\\\"\") : (\"\")).\" />\r\n		\") : (\"\")).\"\r\n		<span style=\\\"float:$stylevar[right]\\\">\r\n			$vbphrase[forum]: <a href=\\\"forumdisplay.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"f=$post[forumid]\\\">$post[forumtitle]</a>\r\n		</span>\r\n		<img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_statusicon]/post_$post[post_statusicon].gif\\\" alt=\\\"\\\" border=\\\"0\\\" />\r\n		$post[postdate]\".((!$show[\'detailedtime\']) ? (\", $post[posttime]\") : (\"\")).\"\r\n	</td>\r\n</tr>\r\n<tr>\r\n	\".(($show[\'moderated\']) ? (\"\r\n	<td class=\\\"alt2\\\">\r\n	\") : (\"\r\n	<td class=\\\"alt1\\\">\r\n	\")).\"\r\n		<div class=\\\"smallfont\\\" style=\\\"float:$stylevar[right]\\\">\r\n			$vbphrase[replies]: <strong>$post[replycount]</strong>\r\n		</div>\r\n		<div>\r\n			<img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_statusicon]/thread$post[statusicon].gif\\\" alt=\\\"\\\" border=\\\"0\\\" />\r\n			$post[typeprefix] $post[prefix_rich] <a href=\\\"showthread.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"t=$post[threadid]$post[highlight]\\\"><strong>$post[threadtitle]</strong></a>\r\n		</div>\r\n		<div class=\\\"smallfont\\\" style=\\\"float:$stylevar[right]\\\">\r\n			$vbphrase[views]: <strong>$post[views]</strong>\r\n		</div>\r\n		<div class=\\\"smallfont\\\">\r\n			$vbphrase[posted_by]\r\n			\".(($post[userid]) ? (\"<a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$post[userid]\\\">$post[username]</a>\") : (\"$post[username]\")).\"\r\n		</div>\r\n\r\n		<div class=\\\"alt2\\\" style=\\\"margin:$stylevar[cellpadding]px 0px $stylevar[cellpadding]px 0px; padding:$stylevar[cellpadding]px; border:2px groove\\\">\r\n			<div class=\\\"smallfont\\\"><em>\r\n				\".(($post[posticon]) ? (\"<img class=\\\"inlineimg\\\" src=\\\"$post[posticonpath]\\\" alt=\\\"$post[posticontitle]\\\" border=\\\"0\\\" />\") : (\"\")).\"\r\n				<a href=\\\"showthread.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"p=$post[postid]$post[highlight]#post$post[postid]\\\">$post[posttitle]</a><br />\r\n				<br />\r\n				$post[pagetext]\r\n			</em></div>\r\n		</div>\r\n\r\n		\".(($show[\'moderated\']) ? (\"\r\n			<div style=\\\"float:$stylevar[right]\\\"><img src=\\\"$stylevar[imgdir_misc]/moderated.gif\\\" alt=\\\"$vbphrase[moderated_post]\\\" border=\\\"0\\\" /></div>\r\n		\") : (\"\")).\"\r\n\r\n		\".(($show[\'deleted\']) ? (\"\r\n		<div style=\\\"float:$stylevar[right]\\\"><img src=\\\"$stylevar[imgdir_misc]/trashcan.gif\\\" alt=\\\"$vbphrase[deleted_post]\\\" border=\\\"0\\\" /></div>\r\n		<div class=\\\"smallfont\\\">\r\n			\" . construct_phrase(\"$post[del_phrase]\", \"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$post[del_userid]\", \"$post[del_username]\") . \"\r\n			\".(($post[\'del_reason\']) ? (\"$vbphrase[reason]: <em>$post[del_reason]</em>\") : (\"\")).\"\r\n		</div>\r\n		\") : (\"\")).\"\r\n	</td>\r\n</tr>\r\n</table>', '<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\" style=\"margin:$stylevar[cellpadding]px 0px $stylevar[cellpadding]px 0px\" id=\"post$post[postid]\">\r\n<tr>\r\n	<td class=\"thead\" style=\"font-weight:normal\">\r\n		<if condition=\"$show[\'inlinemod\']\">\r\n			<input type=\"checkbox\" name=\"plist[$post[postid]]\" id=\"plist_$post[postid]\" style=\"float:$stylevar[right]; vertical-align:middle; padding:0px; margin:0px 0px 0px 5px\" value=\"1\" <if condition=\"$show[\'disabled\']\">disabled=\"disabled\"</if> />\r\n		</if>\r\n		<span style=\"float:$stylevar[right]\">\r\n			$vbphrase[forum]: <a href=\"forumdisplay.php?$session[sessionurl]f=$post[forumid]\">$post[forumtitle]</a>\r\n		</span>\r\n		<img class=\"inlineimg\" src=\"$stylevar[imgdir_statusicon]/post_$post[post_statusicon].gif\" alt=\"\" border=\"0\" />\r\n		$post[postdate]<if condition=\"!$show[\'detailedtime\']\">, $post[posttime]</if>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<if condition=\"$show[\'moderated\']\">\r\n	<td class=\"alt2\">\r\n	<else />\r\n	<td class=\"alt1\">\r\n	</if>\r\n		<div class=\"smallfont\" style=\"float:$stylevar[right]\">\r\n			$vbphrase[replies]: <strong>$post[replycount]</strong>\r\n		</div>\r\n		<div>\r\n			<img class=\"inlineimg\" src=\"$stylevar[imgdir_statusicon]/thread$post[statusicon].gif\" alt=\"\" border=\"0\" />\r\n			$post[typeprefix] $post[prefix_rich] <a href=\"showthread.php?$session[sessionurl]t=$post[threadid]$post[highlight]\"><strong>$post[threadtitle]</strong></a>\r\n		</div>\r\n		<div class=\"smallfont\" style=\"float:$stylevar[right]\">\r\n			$vbphrase[views]: <strong>$post[views]</strong>\r\n		</div>\r\n		<div class=\"smallfont\">\r\n			$vbphrase[posted_by]\r\n			<if condition=\"$post[userid]\"><a href=\"member.php?$session[sessionurl]u=$post[userid]\">$post[username]</a><else />$post[username]</if>\r\n		</div>\r\n\r\n		<div class=\"alt2\" style=\"margin:$stylevar[cellpadding]px 0px $stylevar[cellpadding]px 0px; padding:$stylevar[cellpadding]px; border:2px groove\">\r\n			<div class=\"smallfont\"><em>\r\n				<if condition=\"$post[posticon]\"><img class=\"inlineimg\" src=\"$post[posticonpath]\" alt=\"$post[posticontitle]\" border=\"0\" /></if>\r\n				<a href=\"showthread.php?$session[sessionurl]p=$post[postid]$post[highlight]#post$post[postid]\">$post[posttitle]</a><br />\r\n				<br />\r\n				$post[pagetext]\r\n			</em></div>\r\n		</div>\r\n\r\n		<if condition=\"$show[\'moderated\']\">\r\n			<div style=\"float:$stylevar[right]\"><img src=\"$stylevar[imgdir_misc]/moderated.gif\" alt=\"$vbphrase[moderated_post]\" border=\"0\" /></div>\r\n		</if>\r\n\r\n		<if condition=\"$show[\'deleted\']\">\r\n		<div style=\"float:$stylevar[right]\"><img src=\"$stylevar[imgdir_misc]/trashcan.gif\" alt=\"$vbphrase[deleted_post]\" border=\"0\" /></div>\r\n		<div class=\"smallfont\">\r\n			<phrase 1=\"member.php?$session[sessionurl]u=$post[del_userid]\" 2=\"$post[del_username]\">$post[del_phrase]</phrase>\r\n			<if condition=\"$post[\'del_reason\']\">$vbphrase[reason]: <em>$post[del_reason]</em></if>\r\n		</div>\r\n		</if>\r\n	</td>\r\n</tr>\r\n</table>', 'template', 1233751411, 'vBulletin Solutions', '3.8.2', 'vbulletin'),
(391, -1, 'search_results_postbit_lastvisit', '<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\" style=\\\"margin:$stylevar[cellpadding]px 0px $stylevar[cellpadding]px 0px\\\">\r\n<tr>\r\n	<td class=\\\"alt1\\\" align=\\\"center\\\"><span class=\\\"smallfont\\\"><strong>$vbphrase[all_posts_below_here]</strong></span></td>\r\n</tr>\r\n</table>', '<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\" style=\"margin:$stylevar[cellpadding]px 0px $stylevar[cellpadding]px 0px\">\r\n<tr>\r\n	<td class=\"alt1\" align=\"center\"><span class=\"smallfont\"><strong>$vbphrase[all_posts_below_here]</strong></span></td>\r\n</tr>\r\n</table>', 'template', 1149792002, 'vBulletin Solutions', '3.6.0 Beta 2', 'vbulletin'),
(392, -1, 'SHOWGROUPS', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $vbphrase[show_groups]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n\".(($moderatorbits) ? (\"\r\n<!-- moderators -->\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\" colspan=\\\"4\\\">$vbphrase[moderators]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"thead\\\">&nbsp;</td>\r\n	<td class=\\\"thead\\\" width=\\\"50%\\\">$vbphrase[username]\".(($show[\'locationfield\']) ? (\" / $vbphrase[location_perm]\") : (\"\")).\"</td>\r\n	<td class=\\\"thead\\\" width=\\\"50%\\\">$vbphrase[forums]</td>\r\n	\".(($show[\'contactinfo\']) ? (\"<td class=\\\"thead\\\">$vbphrase[contact]</td>\") : (\"\")).\"\r\n</tr>\r\n$moderatorbits\r\n</table>\r\n<br />\r\n<!-- end moderators -->\r\n\") : (\"\")).\"\r\n\r\n$usergroups\r\n\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n<tr>\r\n	<td width=\\\"100%\\\">&nbsp;</td>\r\n	<td>$forumjump</td>\r\n</tr>\r\n</table>\r\n\r\n$footer\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n<title>$vboptions[bbtitle] - $vbphrase[show_groups]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<if condition=\"$moderatorbits\">\r\n<!-- moderators -->\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\" colspan=\"4\">$vbphrase[moderators]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"thead\">&nbsp;</td>\r\n	<td class=\"thead\" width=\"50%\">$vbphrase[username]<if condition=\"$show[\'locationfield\']\"> / $vbphrase[location_perm]</if></td>\r\n	<td class=\"thead\" width=\"50%\">$vbphrase[forums]</td>\r\n	<if condition=\"$show[\'contactinfo\']\"><td class=\"thead\">$vbphrase[contact]</td></if>\r\n</tr>\r\n$moderatorbits\r\n</table>\r\n<br />\r\n<!-- end moderators -->\r\n</if>\r\n\r\n$usergroups\r\n\r\n<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\">\r\n<tr>\r\n	<td width=\"100%\">&nbsp;</td>\r\n	<td>$forumjump</td>\r\n</tr>\r\n</table>\r\n\r\n$footer\r\n</body>\r\n</html>', 'template', 1231162002, 'vBulletin Solutions', '3.8.0 Release Candidate 3', 'vbulletin'),
(393, -1, 'showgroups_forumbit', '<a href=\\\"forumdisplay.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"f=$forumid\\\">$forumtitle</a>', '<a href=\"forumdisplay.php?$session[sessionurl]f=$forumid\">$forumtitle</a>', 'template', 1069772461, 'vBulletin Solutions', '', 'vbulletin'),
(394, -1, 'showgroups_usergroup', '<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\" colspan=\\\"3\\\">$user[title]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"thead\\\">&nbsp;</td>\r\n	<td class=\\\"thead\\\" width=\\\"100%\\\">$vbphrase[user_name]\".(($show[\'locationfield\']) ? (\" / $vbphrase[location_perm]\") : (\"\")).\"</td>\r\n	\".(($show[\'contactinfo\']) ? (\"<td class=\\\"thead\\\">$vbphrase[contact]</td>\") : (\"\")).\"\r\n</tr>\r\n$usergroupbits\r\n</table>\r\n<br />\r\n', '<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\" colspan=\"3\">$user[title]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"thead\">&nbsp;</td>\r\n	<td class=\"thead\" width=\"100%\">$vbphrase[user_name]<if condition=\"$show[\'locationfield\']\"> / $vbphrase[location_perm]</if></td>\r\n	<if condition=\"$show[\'contactinfo\']\"><td class=\"thead\">$vbphrase[contact]</td></if>\r\n</tr>\r\n$usergroupbits\r\n</table>\r\n<br />\r\n', 'template', 1231161696, 'vBulletin Solutions', '3.8.0 Release Candidate 3', 'vbulletin'),
(395, -1, 'showgroups_usergroupbit', '<tr>\r\n	<td class=\\\"$bgclass\\\">$user[onlinestatus]</td>\r\n	<td class=\\\"$bgclass\\\">\r\n		<a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$user[userid]\\\">$user[musername]</a>\r\n		\".(($show[\'locationfield\'] AND $user[\'field2\']) ? (\"<div class=\\\"smallfont\\\" title=\\\"$vbphrase[location_perm]\\\">$user[field2]</div>\") : (\"\")).\"\r\n	</td>\r\n	\".(($showforums) ? (\"\r\n		<td class=\\\"$bgclass\\\"><div class=\\\"smallfont\\\">$user[forumbits]</div></td>\r\n	\") : (\"\")).\"\r\n	\".(($show[\'contactinfo\']) ? (\"\r\n	<td class=\\\"$bgclass\\\" nowrap=\\\"nowrap\\\">\r\n		\".(($show[\'pmlink\']) ? (\"<a href=\\\"private.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=newpm&amp;u=$user[userid]\\\" rel=\\\"nofollow\\\"><img src=\\\"$stylevar[imgdir_button]/sendpm.gif\\\" alt=\\\"\" . construct_phrase(\"$vbphrase[send_private_message_to_x]\", \"$user[username]\") . \"\\\" border=\\\"0\\\" /></a>\") : (\"\")).\"\r\n		\".(($show[\'emaillink\']) ? (\"<a href=\\\"sendmessage.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=mailmember&amp;u=$user[userid]\\\" rel=\\\"nofollow\\\"><img src=\\\"$stylevar[imgdir_button]/email.gif\\\" alt=\\\"\" . construct_phrase(\"$vbphrase[send_message_via_email_to_x]\", \"$user[username]\") . \"\\\" border=\\\"0\\\" /></a>\") : (\"\")).\"\r\n	</td>\r\n	\") : (\"\")).\"\r\n</tr>', '<tr>\r\n	<td class=\"$bgclass\">$user[onlinestatus]</td>\r\n	<td class=\"$bgclass\">\r\n		<a href=\"member.php?$session[sessionurl]u=$user[userid]\">$user[musername]</a>\r\n		<if condition=\"$show[\'locationfield\'] AND $user[\'field2\']\"><div class=\"smallfont\" title=\"$vbphrase[location_perm]\">$user[field2]</div></if>\r\n	</td>\r\n	<if condition=\"$showforums\">\r\n		<td class=\"$bgclass\"><div class=\"smallfont\">$user[forumbits]</div></td>\r\n	</if>\r\n	<if condition=\"$show[\'contactinfo\']\">\r\n	<td class=\"$bgclass\" nowrap=\"nowrap\">\r\n		<if condition=\"$show[\'pmlink\']\"><a href=\"private.php?$session[sessionurl]do=newpm&amp;u=$user[userid]\" rel=\"nofollow\"><img src=\"$stylevar[imgdir_button]/sendpm.gif\" alt=\"<phrase 1=\"$user[username]\">$vbphrase[send_private_message_to_x]</phrase>\" border=\"0\" /></a></if>\r\n		<if condition=\"$show[\'emaillink\']\"><a href=\"sendmessage.php?$session[sessionurl]do=mailmember&amp;u=$user[userid]\" rel=\"nofollow\"><img src=\"$stylevar[imgdir_button]/email.gif\" alt=\"<phrase 1=\"$user[username]\">$vbphrase[send_message_via_email_to_x]</phrase>\" border=\"0\" /></a></if>\r\n	</td>\r\n	</if>\r\n</tr>', 'template', 1231161424, 'vBulletin Solutions', '3.8.0 Release Candidate 3', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(396, -1, 'SHOWTHREAD', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n	$headinclude\r\n	<title>$thread[prefix_plain_html] $thread[title]\".(($pagenumber>1) ? (\" - \" . construct_phrase(\"$vbphrase[page_x]\", \"$pagenumber\") . \"\") : (\"\")).\" - \" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \"</title>\r\n	<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_post_loader.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n	<style type=\\\"text/css\\\" id=\\\"vbulletin_showthread_css\\\">\r\n	<!--\r\n	\".(($show[\'tag_box\']) ? (\"\r\n	#tag_edit_list { list-style:none; margin:0px; padding:0px; }\r\n	#tag_edit_list li { float:$stylevar[left]; display:block; width:200px; }\r\n	#tag_edit_list li.mine { font-weight:bold; }\r\n	\") : (\"\")).\"\r\n	#links div { white-space: nowrap; }\r\n	#links img { vertical-align: middle; }\r\n	-->\r\n	</style>\r\n</head>\r\n<body onload=\\\"$onload\\\">\r\n$header\r\n$navbar\r\n\r\n$poll\r\n\r\n\".(($show[\'inlinemod\']) ? (\"\r\n$spacer_close\r\n<form action=\\\"inlinemod.php?threadid=$threadinfo[threadid]&amp;p=$postid\\\" method=\\\"post\\\" id=\\\"inlinemodform\\\">\r\n$spacer_open\r\n\") : (\"\")).\"\r\n\r\n<a name=\\\"poststop\\\" id=\\\"poststop\\\"></a>\r\n\r\n<!-- controls above postbits -->\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\" style=\\\"margin-bottom:3px\\\">\r\n<tr valign=\\\"bottom\\\">\r\n	\".(($show[\'largereplybutton\']) ? (\"\r\n		<td class=\\\"smallfont\\\"><a href=\\\"newreply.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=newreply&amp;noquote=1&amp;p=$FIRSTPOSTID\\\" rel=\\\"nofollow\\\">\".(($show[\'closethread\']) ? (\"<img src=\\\"$stylevar[imgdir_button]/reply.gif\\\" alt=\\\"$vbphrase[reply]\\\" border=\\\"0\\\" />\") : (\"<img src=\\\"$stylevar[imgdir_button]/thread