er=\\\"0\\\">\r\n		\".((!$show[\'popups\'] AND $show[\'adminoptions\']) ? (\"\r\n		<tr>\r\n			<td>\r\n			<div class=\\\"smallfont\\\" style=\\\"text-align:$stylevar[left]; white-space:nowrap\\\">\r\n			<form action=\\\"postings.php?t=$threadid\\\" method=\\\"post\\\" name=\\\"adminoptionsform\\\">\r\n			<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n			<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n			<input type=\\\"hidden\\\" name=\\\"t\\\" value=\\\"$threadid\\\" />\r\n			<strong>$vbphrase[admin_tools]</strong>:<br />\r\n			<select name=\\\"do\\\" onchange=\\\"this.form.submit()\\\">\r\n				\".(($show[\'openclose\']) ? (\"<option value=\\\"openclosethread\\\" selected=\\\"selected\\\">\".(($show[\'closethread\']) ? (\"$vbphrase[close_thread]\") : (\"$vbphrase[open_thread]\")).\"</option>\") : (\"\")).\"\r\n				\".(($show[\'moderatethread\']) ? (\"<option value=\\\"moderatethread\\\">\".(($show[\'approvethread\']) ? (\"$vbphrase[approve_thread]\") : (\"$vbphrase[unapprove_thread]\")).\"</option>\") : (\"\")).\"\r\n				\".(($show[\'editthread\']) ? (\"<option value=\\\"editthread\\\">$vbphrase[edit_thread]</option>\") : (\"\")).\"\r\n				\".(($show[\'deletethread\']) ? (\"<option value=\\\"deletethread\\\">$vbphrase[delete_thread]</option>\") : (\"\")).\"\r\n				\".(($show[\'movethread\']) ? (\"<option value=\\\"movethread\\\">$vbphrase[move_thread]</option>\r\n				<option value=\\\"copythread\\\">$vbphrase[copy_thread]</option>\") : (\"\")).\"\r\n				\".(($show[\'managethread\']) ? (\"\r\n						<option value=\\\"stick\\\">\".(($show[\'unstick\']) ? (\"$vbphrase[unstick_thread]\") : (\"$vbphrase[stick_thread]\")).\"</option>\r\n					<option value=\\\"mergethread\\\">$vbphrase[merge_threads]</option>\r\n					<option value=\\\"removeredirect\\\">$vbphrase[remove_redirects]</option>\r\n				\") : (\"\