n						</label>\r\n					</div>\r\n					</if>\r\n				</div>\r\n			</fieldset>\r\n\r\n			<div class=\"smallfont\">\r\n				<div>$vbphrase[reason_for_deletion]:</div>\r\n				<input type=\"text\" class=\"bginput\" name=\"reason\" size=\"50\" tabindex=\"1\" title=\"$vbphrase[optional]\" />\r\n			</div>\r\n\r\n			</div>\r\n		</div>\r\n\r\n		<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n			<input type=\"submit\" class=\"button\" value=\"$vbphrase[delete]\" tabindex=\"1\" accesskey=\"d\" />\r\n		</div>\r\n\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n</table>\r\n</form>\r\n<br />\r\n</if>\r\n\r\n$postpreview\r\n\r\n<form action=\"group.php?do=message\" name=\"vbform\" method=\"post\"<if condition=\"!is_browser(\'webtv\')\"> onsubmit=\"return vB_Editor[\'$editorid\'].prepare_submit(0, $vboptions[postminchars])\"</if>>\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		<if condition=\"$show[\'edit\']\">\r\n			<span class=\"smallfont\" style=\"float:$stylevar[right]\"><strong>$vbphrase[social_group]</strong>: <a href=\"group.php?$session[sessionurl]groupid=$group[groupid]\">$group[name]</a></span>\r\n			<if condition=\"$edit_discussion\">\r\n				$vbphrase[edit_discussion]\r\n		<else />\r\n				$vbphrase[edit_message]\r\n		</if>\r\n		<else />\r\n			<if condition=\"$edit_discussion\">\r\n				$vbphrase[post_new_discussion]\r\n			<else />\r\n				$vbphrase[reply_to_discussion]\r\n			</if>\r\n		</if>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div align=\"$stylevar[left]\" style=\"max-width:$stylevar[formwidth]; width:auto !important; width:$stylevar[formwidth_usercp]\">\r\n\r\n		$usernamecode\r\n\r\n		$human_verify\r\n\r\n		<if condition=\"$edit_discussion\">\r\n			<div class=\"smallfont\">$vbphrase[subject]:</div>\r\n			<input type=\"text\" class=\"bginput\" name=\"subject\" value=\"$message[title]\" size=\"50\" maxlength=\"$vboptions[titlemaxchars]\" tabindex=\"1\" title=\"$vbphrase[subject]\" />\r\n		</if>\r\n		<!-- message area -->\r\n		<div class=\"smallfont\">$vbphrase[message]: <if condition=\"$show[\'auto_moderation\']\"><span class=\"shade\">$vbphrase[this_post_will_be_automatically_moderated]</span></if></div>\r\n		$messagearea\r\n		<!-- / message area -->\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n		<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n		<input type=\"hidden\" name=\"do\" value=\"message\" />\r\n		<input type=\"hidden\" name=\"gmid\" value=\"$messageinfo[gmid]\" />\r\n		<input type=\"hidden\" name=\"posthash\" value=\"$posthash\" />\r\n		<input type=\"hidden\" name=\"loggedinuser\" value=\"$bbuserinfo[userid]\" />\r\n		<input type=\"hidden\" name=\"groupid\" value=\"$group[groupid]\" />\r\n		<input type=\"hidden\" name=\"discussionid\" value=\"$discussion[discussionid]\" />\r\n					<input type=\"submit\" class=\"button\" name=\"sbutton\" id=\"{$editorid}_save\" value=\"$vbphrase[post_message]\" accesskey=\"s\" tabindex=\"1\" />\r\n		<input type=\"submit\" class=\"button\" name=\"preview\" value=\"$vbphrase[preview]\" accesskey=\"r\" tabindex=\"1\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<if condition=\"$show[\'additional_options\']\">\r\n<br />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<thead>\r\n	<tr>\r\n		<td class=\"tcat\">\r\n			<a style=\"float:$stylevar[right]\" href=\"#top\" onclick=\"return toggle_collapse(\'newpost_options\')\"><img id=\"collapseimg_newpost_options\" src=\"$stylevar[imgdir_button]/collapse_tcat$vbcollapse[collapseimg_newpost_options].gif\" alt=\"\" border=\"0\" /></a>\r\n			$vbphrase[additional_options]\r\n		</td>\r\n	</tr>\r\n</thead>\r\n<tbody id=\"collapseobj_newpost_options\" style=\"$vbcollapse[collapseobj_newpost_options]\">\r\n	<tr valign=\"top\">\r\n		<td class=\"panelsurround\" align=\"center\">\r\n		<div class=\"panel\">\r\n			<div align=\"$stylevar[left]\" style=\"max-width:$stylevar[formwidth]; width:auto !important; width:$stylevar[formwidth_usercp]\">\r\n\r\n				<if condition=\"$show[\'misc_options\']\">\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[miscellaneous_options]</legend>\r\n					<div style=\"padding:$stylevar[formspacer]px\">\r\n						<if condition=\"$show[\'parseurl\']\"><div><label for=\"cb_parseurl\"><input type=\"checkbox\" name=\"parseurl\" value=\"1\" id=\"cb_parseurl\" tabindex=\"1\" $checked[parseurl] />$vbphrase[automatically_parse_links_in_text]</label></div></if>\r\n						$disablesmiliesoption\r\n					</div>\r\n				</fieldset>\r\n				</if>\r\n			</div>\r\n		</div>\r\n\r\n		<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n						<input type=\"submit\" class=\"button\" name=\"sbutton\" value=\"$vbphrase[post_message]\" accesskey=\"s\" tabindex=\"1\" />\r\n			<input type=\"submit\" class=\"button\" name=\"preview\" value=\"$vbphrase[preview]\" accesskey=\"r\" tabindex=\"1\" />\r\n		</div>\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n</table>\r\n</if>\r\n\r\n</form>\r\n\r\n<if condition=\"$messagebits\">\r\n<br />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\">\r\n<thead>\r\n	<tr>\r\n		<td class=\"tcat\">\r\n			<a style=\"float:$stylevar[right]\" href=\"#top\" onclick=\"return toggle_collapse(\'newmessage_dialog\')\"><img id=\"collapseimg_newmessage_dialog\" src=\"$stylevar[imgdir_button]/collapse_tcat$vbcollapse[collapseimg_newmessage_dialog].gif\" alt=\"\" border=\"0\" /></a>\r\n					$vbphrase[message_dialog]\r\n		</td>\r\n	</tr>\r\n</thead>\r\n<tbody id=\"collapseobj_newmessage_dialog\" style=\"$vbcollapse[collapseobj_newmessage_dialog]\">\r\n	<tr valign=\"top\">\r\n		<td class=\"panelsurround\">\r\n		<div class=\"panel\">\r\n\r\n			$messagebits\r\n\r\n		</div>\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n</table>\r\n</if>\r\n\r\n<br />\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', 'template', 1221757660, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(426, -1, 'socialgroups_form', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $custompagetitle</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n\".((!$icononly) ? (\"\r\n<form action=\\\"group.php?do=$action\\\" method=\\\"post\\\">\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"$action\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"groupid\\\" value=\\\"$group[groupid]\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"url\\\" value=\\\"$url\\\" />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		$phrase\r\n		\".(($_REQUEST[\'do\'] == \'edit\') ? (\"\r\n			<span class=\\\"normal\\\"><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"groupid=$group[groupid]\\\">$group[name]</a></span>\r\n		\") : (\"\")).\"\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n		<div class=\\\"panel\\\">\r\n			<table><tr><td align=\\\"$stylevar[left]\\\">\r\n\r\n				<div class=\\\"smallfont\\\">\r\n					<label for=\\\"socialgroupcategoryid\\\">$vbphrase[social_group_category]:</label><br />\r\n					<select name=\\\"socialgroupcategoryid\\\" id=\\\"socialgroupcategoryid\\\">\r\n						<option value=\\\"\\\">$vbphrase[select_a_category]</option>\r\n						$categoryoptions\r\n					</select>\r\n				</div>\r\n\r\n				\".(($show[\'title\']) ? (\"\r\n					<div class=\\\"smallfont\\\">\r\n					<label for=\\\"groupname\\\">$vbphrase[group_name]:</label><br />\r\n						<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"groupname\\\" id=\\\"groupname\\\" size=\\\"50\\\" maxlength=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'sg_name_maxchars\'] . \"\\\" value=\\\"$group[rawname]\\\" tabindex=\\\"1\\\" />\r\n					</div>\r\n				\") : (\"\")).\"\r\n\r\n				<div class=\\\"smallfont\\\" style=\\\"margin-top:$stylevar[formspacer]px\\\">\r\n					<label for=\\\"groupdescription\\\">$vbphrase[group_description]: <span class=\\\"shade\\\">($vbphrase[bbcode_not_allowed])</span></label><br />\r\n					<textarea class=\\\"bginput\\\" name=\\\"groupdescription\\\" id=\\\"groupdescription\\\" cols=\\\"50\\\" rows=\\\"5\\\" tabindex=\\\"1\\\">$group[rawdescription]</textarea>\r\n				</div>\r\n\r\n				<div class=\\\"smallfont\\\" style=\\\"margin-top:$stylevar[formspacer]px\\\">\r\n					<label for=\\\"grouptype\\\">$vbphrase[group_type]:</label><br />\r\n					<select name=\\\"grouptype\\\" id=\\\"grouptype\\\">\r\n						<option value=\\\"public\\\"$typeselected[public]>$vbphrase[group_type_public]</option>\r\n						<option value=\\\"moderated\\\"$typeselected[moderated]>$vbphrase[group_type_moderated]</option>\r\n						<option value=\\\"inviteonly\\\"$typeselected[inviteonly]>$vbphrase[group_type_inviteonly]</option>\r\n					</select>\r\n				</div>\r\n\r\n				\".(($show[\'options\']) ? (\"\r\n					<fieldset class=\\\"fieldset\\\" style=\\\"margin-top:$stylevar[formspacer]px\\\">\r\n						<legend>$vbphrase[group_options]</legend>\r\n						<div class=\\\"smallfont\\\">\r\n							\".(($show[\'enable_group_albums\']) ? (\"\r\n								<div>\r\n									<label for=\\\"enable_group_albums\\\"><input type=\\\"checkbox\\\" name=\\\"options[enable_group_albums]\\\" id=\\\"enable_group_albums\\\" value=\\\"1\\\" $checked[enable_group_albums]/> $vbphrase[enable_albums]</label>\r\n								</div>\r\n							\") : (\"\")).\"\r\n							\".(($show[\'enable_group_messages\']) ? (\"\r\n								<div>\r\n									<label for=\\\"enable_group_messages\\\"><input type=\\\"checkbox\\\" name=\\\"options[enable_group_messages]\\\" id=\\\"enable_group_messages\\\" value=\\\"1\\\" $checked[enable_group_messages]/> $vbphrase[enable_messages]</label>\r\n								</div>\r\n							\") : (\"\")).\"\r\n							\".(($show[\'mod_queue\']) ? (\"\r\n							<div>\r\n								<label for=\\\"group_owner_mod_queue\\\"><input type=\\\"checkbox\\\" name=\\\"options[owner_mod_queue]\\\" id=\\\"group_owner_mod_queue\\\" value=\\\"1\\\" $checked[mod_queue]/> $vbphrase[messages_must_be_approved_by_owner]</label>\r\n								</div>\r\n							\") : (\"\")).\"\r\n							\".(($show[\'join_to_view\']) ? (\"\r\n							<div>\r\n								<label for=\\\"join_to_view\\\"><input type=\\\"checkbox\\\" name=\\\"options[join_to_view]\\\" id=\\\"join_to_view\\\" value=\\\"1\\\" $checked[join_to_view]/> $vbphrase[users_must_join_to_view_content]</label>\r\n								</div>\r\n							\") : (\"\")).\"\r\n							\".(($show[\'only_owner_discussions\']) ? (\"\r\n								<div>\r\n									<label for=\\\"only_owner_discussions\\\"><input type=\\\"checkbox\\\" name=\\\"options[only_owner_discussions]\\\" id=\\\"only_owner_discussions\\\" value=\\\"1\\\" $checked[only_owner_discussions]/> $vbphrase[only_owner_can_create_new_discussions]</label>\r\n						</div>\r\n							\") : (\"\r\n								<input type=\\\"hidden\\\" name=\\\"options[only_owner_discussions]\\\" id=\\\"only_owner_discussions\\\" value=\\\"$checked[only_owner_discussions]\\\" />\r\n							\")).\"\r\n						</div>\r\n					</fieldset>\r\n				\") : (\"\")).\"\r\n			</td></tr></table>\r\n		</div>\r\n\r\n		<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n			<input type=\\\"submit\\\" value=\\\"$vbphrase[save]\\\" class=\\\"button\\\" accesskey=\\\"s\\\" tabindex=\\\"1\\\" />\r\n			<input type=\\\"reset\\\" value=\\\"$vbphrase[reset]\\\" class=\\\"button\\\" />\r\n		</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>\r\n\") : (\"\")).\"\r\n\r\n\".(($show[editicon]) ? (\"\r\n\".((!$icononly) ? (\"<br />\") : (\"\")).\"\r\n\r\n\r\n<form enctype=\\\"multipart/form-data\\\" action=\\\"group.php?do=updateicon\\\" method=\\\"post\\\">\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"updateicon\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"groupid\\\" value=\\\"$group[groupid]\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"icononly\\\" value=\\\"$icononly\\\" />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\" colspan=\\\"2\\\">\".(($icononly) ? (\"$vbphrase[create_group_icon]\") : (\"$vbphrase[edit_group_icon]\")).\"</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth_usercp]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n			<fieldset class=\\\"fieldset\\\">\r\n				<legend>$vbphrase[current_group_icon]</legend>\r\n				<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n				<tr valign=\\\"top\\\">\r\n					\".((!$groupiconurl) ? (\"\r\n					<td class=\\\"alt1\\\" style=\\\"border:1px inset; padding:$stylevar[cellpadding]px\\\">\r\n					<span class=\\\"smallfont\\\">$vbphrase[no_group_icon]</span>\r\n					</td>\r\n					\") : (\"\r\n						<td class=\\\"smallfont\\\">\r\n						<img src=\\\"$groupiconurl\\\" alt=\\\"$vbphrase[current_group_icon]\\\"  border=\\\"0\\\" style=\\\"margin-$stylevar[right]:8px;border:1px solid gray\\\" />\r\n						</td>\r\n					\")).\"\r\n					<td class=\\\"smallfont\\\">\r\n						<div style=\\\"margin-bottom:$stylevar[formspacer]px\\\">$vbphrase[group_icon_desc]</div>\r\n						\".(($show[\'deleteicon\']) ? (\"<div style=\\\"margin-bottom:$stylevar[formspacer]px\\\"><label for=\\\"groupicon\\\"><input type=\\\"checkbox\\\" name=\\\"deletegroupicon\\\" value=\\\"1\\\" id=\\\"groupicon\\\" />$vbphrase[delete_current_image]</label></div>\") : (\"\")).\"\r\n					</td>\r\n				</tr>\r\n				</table>\r\n			</fieldset>\r\n\r\n\r\n			<fieldset class=\\\"fieldset\\\">\r\n				<legend>$vbphrase[custom_group_icon]</legend>\r\n\r\n				<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n				<div class=\\\"fieldset\\\">\r\n\r\n				$vbphrase[may_upload_custom_image_controls]<br /><br />\r\n\r\n				\".(($show[\'url_option\']) ? (\"\r\n				$vbphrase[enter_url_to_image]\r\n				<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n					<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"iconurl\\\" value=\\\"\\\" size=\\\"45\\\" dir=\\\"ltr\\\" />\r\n				</div>\r\n				\") : (\"\")).\"\r\n\r\n				\".(($show[\'url_option\']) ? (\"$vbphrase[option_2_upload_image_from_computer]\") : (\"$vbphrase[upload_image_from_computer]\")).\"\r\n				<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n					<input type=\\\"file\\\" class=\\\"bginput\\\" name=\\\"upload\\\" size=\\\"45\\\" />\r\n					<input type=\\\"hidden\\\" name=\\\"MAX_FILE_SIZE\\\" value=\\\"$inimaxattach\\\" />\r\n				</div>\r\n\r\n				$maxnote\r\n\r\n				</div>\r\n				</div>\r\n			</fieldset>\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[save_changes]\\\" accesskey=\\\"s\\\" />\r\n		<input type=\\\"reset\\\" class=\\\"button\\\" value=\\\"$vbphrase[reset_fields]\\\" accesskey=\\\"r\\\" />\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[skip]\\\" name=\\\"skip\\\" accesskey=\\\"p\\\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>\r\n\") : (\"\")).\"\r\n\r\n$footer\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n<title>$vboptions[bbtitle] - $custompagetitle</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<if condition=\"!$icononly\">\r\n<form action=\"group.php?do=$action\" method=\"post\">\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n<input type=\"hidden\" name=\"do\" value=\"$action\" />\r\n<input type=\"hidden\" name=\"groupid\" value=\"$group[groupid]\" />\r\n<input type=\"hidden\" name=\"url\" value=\"$url\" />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		$phrase\r\n		<if condition=\"$_REQUEST[\'do\'] == \'edit\'\">\r\n			<span class=\"normal\"><a href=\"group.php?$session[sessionurl]groupid=$group[groupid]\">$group[name]</a></span>\r\n		</if>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n		<div class=\"panel\">\r\n			<table><tr><td align=\"$stylevar[left]\">\r\n\r\n				<div class=\"smallfont\">\r\n					<label for=\"socialgroupcategoryid\">$vbphrase[social_group_category]:</label><br />\r\n					<select name=\"socialgroupcategoryid\" id=\"socialgroupcategoryid\">\r\n						<option value=\"\">$vbphrase[select_a_category]</option>\r\n						$categoryoptions\r\n					</select>\r\n				</div>\r\n\r\n				<if condition=\"$show[\'title\']\">\r\n					<div class=\"smallfont\">\r\n					<label for=\"groupname\">$vbphrase[group_name]:</label><br />\r\n						<input type=\"text\" class=\"bginput\" name=\"groupname\" id=\"groupname\" size=\"50\" maxlength=\"$vboptions[sg_name_maxchars]\" value=\"$group[rawname]\" tabindex=\"1\" />\r\n					</div>\r\n				</if>\r\n\r\n				<div class=\"smallfont\" style=\"margin-top:$stylevar[formspacer]px\">\r\n					<label for=\"groupdescription\">$vbphrase[group_description]: <span class=\"shade\">($vbphrase[bbcode_not_allowed])</span></label><br />\r\n					<textarea class=\"bginput\" name=\"groupdescription\" id=\"groupdescription\" cols=\"50\" rows=\"5\" tabindex=\"1\">$group[rawdescription]</textarea>\r\n				</div>\r\n\r\n				<div class=\"smallfont\" style=\"margin-top:$stylevar[formspacer]px\">\r\n					<label for=\"grouptype\">$vbphrase[group_type]:</label><br />\r\n					<select name=\"grouptype\" id=\"grouptype\">\r\n						<option value=\"public\"$typeselected[public]>$vbphrase[group_type_public]</option>\r\n						<option value=\"moderated\"$typeselected[moderated]>$vbphrase[group_type_moderated]</option>\r\n						<option value=\"inviteonly\"$typeselected[inviteonly]>$vbphrase[group_type_inviteonly]</option>\r\n					</select>\r\n				</div>\r\n\r\n				<if condition=\"$show[\'options\']\">\r\n					<fieldset class=\"fieldset\" style=\"margin-top:$stylevar[formspacer]px\">\r\n						<legend>$vbphrase[group_options]</legend>\r\n						<div class=\"smallfont\">\r\n							<if condition=\"$show[\'enable_group_albums\']\">\r\n								<div>\r\n									<label for=\"enable_group_albums\"><input type=\"checkbox\" name=\"options[enable_group_albums]\" id=\"enable_group_albums\" value=\"1\" $checked[enable_group_albums]/> $vbphrase[enable_albums]</label>\r\n								</div>\r\n							</if>\r\n							<if condition=\"$show[\'enable_group_messages\']\">\r\n								<div>\r\n									<label for=\"enable_group_messages\"><input type=\"checkbox\" name=\"options[enable_group_messages]\" id=\"enable_group_messages\" value=\"1\" $checked[enable_group_messages]/> $vbphrase[enable_messages]</label>\r\n								</div>\r\n							</if>\r\n							<if condition=\"$show[\'mod_queue\']\">\r\n							<div>\r\n								<label for=\"group_owner_mod_queue\"><input type=\"checkbox\" name=\"options[owner_mod_queue]\" id=\"group_owner_mod_queue\" value=\"1\" $checked[mod_queue]/> $vbphrase[messages_must_be_approved_by_owner]</label>\r\n								</div>\r\n							</if>\r\n							<if condition=\"$show[\'join_to_view\']\">\r\n							<div>\r\n								<label for=\"join_to_view\"><input type=\"checkbox\" name=\"options[join_to_view]\" id=\"join_to_view\" value=\"1\" $checked[join_to_view]/> $vbphrase[users_must_join_to_view_content]</label>\r\n								</div>\r\n							</if>\r\n							<if condition=\"$show[\'only_owner_discussions\']\">\r\n								<div>\r\n									<label for=\"only_owner_discussions\"><input type=\"checkbox\" name=\"options[only_owner_discussions]\" id=\"only_owner_discussions\" value=\"1\" $checked[only_owner_discussions]/> $vbphrase[only_owner_can_create_new_discussions]</label>\r\n						</div>\r\n							<else />\r\n								<input type=\"hidden\" name=\"options[only_owner_discussions]\" id=\"only_owner_discussions\" value=\"$checked[only_owner_discussions]\" />\r\n							</if>\r\n						</div>\r\n					</fieldset>\r\n				</if>\r\n			</td></tr></table>\r\n		</div>\r\n\r\n		<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n			<input type=\"submit\" value=\"$vbphrase[save]\" class=\"button\" accesskey=\"s\" tabindex=\"1\" />\r\n			<input type=\"reset\" value=\"$vbphrase[reset]\" class=\"button\" />\r\n		</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>\r\n</if>\r\n\r\n<if condition=\"$show[editicon]\">\r\n<if condition=\"!$icononly\"><br /></if>\r\n\r\n\r\n<form enctype=\"multipart/form-data\" action=\"group.php?do=updateicon\" method=\"post\">\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n<input type=\"hidden\" name=\"do\" value=\"updateicon\" />\r\n<input type=\"hidden\" name=\"groupid\" value=\"$group[groupid]\" />\r\n<input type=\"hidden\" name=\"icononly\" value=\"$icononly\" />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\" colspan=\"2\"><if condition=\"$icononly\">$vbphrase[create_group_icon]<else />$vbphrase[edit_group_icon]</if></td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth_usercp]\" align=\"$stylevar[left]\">\r\n\r\n			<fieldset class=\"fieldset\">\r\n				<legend>$vbphrase[current_group_icon]</legend>\r\n				<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n				<tr valign=\"top\">\r\n					<if condition=\"!$groupiconurl\">\r\n					<td class=\"alt1\" style=\"border:1px inset; padding:$stylevar[cellpadding]px\">\r\n					<span class=\"smallfont\">$vbphrase[no_group_icon]</span>\r\n					</td>\r\n					<else />\r\n						<td class=\"smallfont\">\r\n						<img src=\"$groupiconurl\" alt=\"$vbphrase[current_group_icon]\"  border=\"0\" style=\"margin-$stylevar[right]:8px;border:1px solid gray\" />\r\n						</td>\r\n					</if>\r\n					<td class=\"smallfont\">\r\n						<div style=\"margin-bottom:$stylevar[formspacer]px\">$vbphrase[group_icon_desc]</div>\r\n						<if condition=\"$show[\'deleteicon\']\"><div style=\"margin-bottom:$stylevar[formspacer]px\"><label for=\"groupicon\"><input type=\"checkbox\" name=\"deletegroupicon\" value=\"1\" id=\"groupicon\" />$vbphrase[delete_current_image]</label></div></if>\r\n					</td>\r\n				</tr>\r\n				</table>\r\n			</fieldset>\r\n\r\n\r\n			<fieldset class=\"fieldset\">\r\n				<legend>$vbphrase[custom_group_icon]</legend>\r\n\r\n				<div style=\"padding:$stylevar[formspacer]px\">\r\n				<div class=\"fieldset\">\r\n\r\n				$vbphrase[may_upload_custom_image_controls]<br /><br />\r\n\r\n				<if condition=\"$show[\'url_option\']\">\r\n				$vbphrase[enter_url_to_image]\r\n				<div style=\"padding:$stylevar[formspacer]px\">\r\n					<input type=\"text\" class=\"bginput\" name=\"iconurl\" value=\"\" size=\"45\" dir=\"ltr\" />\r\n				</div>\r\n				</if>\r\n\r\n				<if condition=\"$show[\'url_option\']\">$vbphrase[option_2_upload_image_from_computer]<else />$vbphrase[upload_image_from_computer]</if>\r\n				<div style=\"padding:$stylevar[formspacer]px\">\r\n					<input type=\"file\" class=\"bginput\" name=\"upload\" size=\"45\" />\r\n					<input type=\"hidden\" name=\"MAX_FILE_SIZE\" value=\"$inimaxattach\" />\r\n				</div>\r\n\r\n				$maxnote\r\n\r\n				</div>\r\n				</div>\r\n			</fieldset>\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"submit\" class=\"button\" value=\"$vbphrase[save_changes]\" accesskey=\"s\" />\r\n		<input type=\"reset\" class=\"button\" value=\"$vbphrase[reset_fields]\" accesskey=\"r\" />\r\n		<input type=\"submit\" class=\"button\" value=\"$vbphrase[skip]\" name=\"skip\" accesskey=\"p\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>\r\n</if>\r\n\r\n$footer\r\n</body>\r\n</html>', 'template', 1227096129, 'vBulletin Solutions', '3.8.0 Beta 3', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(427, -1, 'socialgroups_group', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n	$headinclude\r\n	<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $custompagetitle</title>\r\n	$socialgroups_css\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n\".(($show[\'groupinfo\']) ? (\"\r\n	<div class=\\\"social_group tborder content_block\\\">\r\n	<div class=\\\"tcat block_title\\\">\r\n		\".(($groupoptions[\'join\'] OR $groupoptions[\'leave\']) ? (\"\r\n		<span class=\\\"smallfont\\\" style=\\\"float:$stylevar[right]\\\">\r\n			\".(($groupoptions[\'join\']) ? (\"\r\n					<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=join&amp;groupid=$group[groupid]\\\">$vbphrase[join_group]</a>\r\n			\") : (\"\r\n				\".((!$group[\'membertype\'] AND $group[\'type\'] == \'inviteonly\') ? (\"\r\n						$vbphrase[group_type_inviteonly]\r\n				\") : (\"\")).\"\r\n			\")).\"\r\n			\".(($groupoptions[\'join\'] AND $groupoptions[\'leave\']) ? (\"\r\n				&nbsp;|&nbsp;\r\n			\") : (\"\")).\"\r\n				\".(($groupoptions[\'leave\']) ? (\"<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=leave&amp;groupid=$group[groupid]\\\">$groupoptions[leavephrase]</a>\") : (\"\")).\"\r\n		</span>\r\n		\") : (\"\")).\"\r\n		\".(($group[membermoderated]) ? (\"$vbphrase[moderated_social_group]\") : (\"$vbphrase[social_group]\")).\"\r\n	</div>\r\n\r\n	<!-- group info -->\r\n	<div class=\\\"alt1 block_row\\\">\r\n		\".(($groupiconurl) ? (\"\r\n		<img src=\\\"$groupiconurl\\\" alt=\\\"\\\" style=\\\"float:$stylevar[right]\\\" class=\\\"sgicon\\\" />\r\n		\") : (\"\")).\"\r\n		<h1 id=\\\"group_name\\\">$group[name]</h1>\r\n		<div id=\\\"group_creator\\\" class=\\\"smallfont\\\">\" . construct_phrase(\"$vbphrase[group_maintained_by_x]\", \"$ownerlink\", \"$group[creatorusername]\") . \"</div>\r\n		\".(($group[\'description\']) ? (\"\r\n			<p id=\\\"group_description\\\">$group[description]</p>\r\n		\") : (\"\")).\"\r\n	</div>\r\n\r\n	<!-- members -->\r\n	<div class=\\\"thead block_row\\\">\r\n		<a id=\\\"view_all_members_link\\\" class=\\\"smallfont\\\" href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=viewmembers&amp;groupid=$group[groupid]\\\">$vbphrase[view_all_members]</a>\r\n		\" . construct_phrase(\"$vbphrase[showing_x_of_y_members]\", \"$members_shown\", \"$group[members]\") . \"\r\n	</div>\r\n\r\n	<div class=\\\"alt2 block_row\\\">\r\n		<ul id=\\\"group_member_list\\\">$short_member_list_bits</ul>\r\n	</div>\r\n\r\n	<!-- pictures -->\r\n	\".(($show[\'pictures_block\']) ? (\"\r\n	<div class=\\\"thead block_row\\\">\r\n		<div id=\\\"picture_links\\\" class=\\\"smallfont\\\">\r\n			<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=grouppictures&amp;groupid=$group[groupid]\\\">$vbphrase[view_pictures]</a>\r\n			\".(($show[\'add_pictures_link\']) ? (\"| <a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=addpictures&amp;groupid=$group[groupid]\\\">$vbphrase[add_pictures]</a>\") : (\"\")).\"\r\n		</div>\r\n		\".(($pictures_shown) ? (\"\r\n			\" . construct_phrase(\"$vbphrase[showing_x_of_y_pictures]\", \"$pictures_shown\", \"$group[picturecount]\") . \"\r\n		\") : (\"\r\n			$vbphrase[group_pictures]\r\n		\")).\"\r\n	</div>\r\n	<div class=\\\"alt1 block_row\\\">\r\n		\".(($picturebits) ? (\"\r\n			$picturebits\r\n		\") : (\"\r\n			$vbphrase[no_pictures_added_group_yet]\r\n			\".(($show[\'add_pictures_link\']) ? (\"<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=addpictures&amp;groupid=$group[groupid]\\\">$vbphrase[add_pictures_to_this_group]</a>\") : (\"\")).\"\r\n		\")).\"\r\n	</div>\r\n	\") : (\"\")).\"\r\n\r\n	</div><br />\r\n\") : (\"\")).\"\r\n\r\n\r\n<!-- Discussions -->\r\n\".(($show[\'groupdiscussions\']) ? (\"\r\n	<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_group_read_marker.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n	<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" style=\\\"border-bottom-width:0px\\\">\r\n	<tr>\r\n		<td class=\\\"tcat\\\" width=\\\"100%\\\" colspan=\\\"3\\\">\r\n			\".(($messagebits OR $searchtext) ? (\"\r\n				<div style=\\\"float:$stylevar[right]\\\" class=\\\"normal\\\">\r\n					<form action=\\\"group.php\\\" method=\\\"post\\\">\r\n						$vbphrase[search_discussions]\r\n						<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"searchtext\\\" value=\\\"$searchtext\\\" style=\\\"font-size: 11px;\\\" />&nbsp;<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[go]\\\" />\r\n						<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n						<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n						<input type=\\\"hidden\\\" name=\\\"groupid\\\" value=\\\"$group[groupid]\\\" />\r\n						<input type=\\\"hidden\\\" name=\\\"perpage\\\" value=\\\"$perpage\\\" />\r\n\r\n\r\n					</form>\r\n					</div>\r\n	\") : (\"\")).\"\r\n			\".((!$show[\'groupinfo\']) ? (\"\r\n				\" . construct_phrase(\"$vbphrase[social_group_discussions_in_x]\", \"$group[name]\") . \"\r\n			\") : (\"\r\n				$vbphrase[social_group_discussions]\r\n			\")).\"\r\n		</td>\r\n		<td class=\\\"vbmenu_control\\\" id=\\\"grouptools\\\" nowrap=\\\"nowrap\\\"><a href=\\\"$show[nojs_link]#goto_grouptools\\\" rel=\\\"nofollow\\\">$vbphrase[group_tools]</a> <script type=\\\"text/javascript\\\"> vbmenu_register(\\\"grouptools\\\"); </script></td>\r\n	</tr>\r\n	</table>\r\n\r\n	\".(($messagebits) ? (\"\r\n	\".(($show[\'inlinemod\']) ? (\"\r\n		<form action=\\\"group_inlinemod.php?groupid=$group[groupid]\\\" method=\\\"post\\\" id=\\\"group_discussion_inlinemod_form\\\">\r\n	\") : (\"\")).\"\r\n	<table class=\\\"tborder discussion_list\\\" id=\\\"discussion_list\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n	<tr class=\\\"block_title\\\">\r\n		$template_hook[group_discussionlist_start_col]\r\n		<td class=\\\"thead\\\" width=\\\"100%\\\">\r\n			\".(($messagetotal) ? (\"\r\n				<span style=\\\"float:$stylevar[right]\\\"><a href=\\\"$orderlinks[dateline]&amp;pp=$perpage&amp;page=$pagenumber\\\">$vbphrase[group_created] $sortarrow[dateline]</a></span>\r\n				\".(($messagestart > 1) ? (\"\r\n					\" . construct_phrase(\"$vbphrase[showing_discussions_x_to_y_of_z]\", \"$messagestart\", \"$messageend\", \"$messagetotal\") . \"\r\n				\") : (\"\r\n					\" . construct_phrase(\"$vbphrase[showing_discussions_x_of_y]\", \"$messageshown\", \"$messagetotal\") . \"\r\n				\")).\"\r\n			\") : (\"\")).\"\r\n		</td>\r\n		<td class=\\\"thead\\\" align=\\\"center\\\" nowrap=\\\"nowrap\\\">\r\n			<a href=\\\"$orderlinks[replies]&amp;pp=$perpage&amp;page=$pagenumber\\\">$vbphrase[replies]</a> $sortarrow[replies]\r\n		</td>\r\n		<td class=\\\"thead\\\" align=\\\"center\\\" nowrap=\\\"nowrap\\\">\r\n			<a href=\\\"$orderlinks[lastpost]&amp;pp=$perpage&amp;page=$pagenumber\\\">$vbphrase[last_post]</a> $sortarrow[lastpost]\r\n		</td>\r\n\r\n		\".(($show[\'inlinemod\']) ? (\"\r\n			<td class=\\\"thead\\\" align=\\\"center\\\" nowrap=\\\"nowrap\\\">\r\n				<a id=\\\"discussion_inlinemodsel\\\"></a>\r\n			</td>\r\n		\") : (\"\")).\"\r\n		$template_hook[group_discussionlist_end_col]\r\n	</tr>\r\n		$messagebits\r\n	</table>\r\n\r\n	\".(($show[\'inlinemod\'] OR $pagenav OR $show[\'postlink\']) ? (\"\r\n		<div class=\\\"floatcontainer\\\">\r\n			\".(($pagenav) ? (\"\r\n				<div id=\\\"discussion_pagenav\\\">\r\n					$pagenav\r\n				</div>\r\n			\") : (\"\")).\"\r\n					\".(($show[\'inlinemod\']) ? (\"\r\n				<div id=\\\"discussion_moderation\\\">\r\n					<div class=\\\"smallfont push_down\\\"><label for=\\\"moderation_select_comments\\\"><strong>$vbphrase[moderation]</strong></label></div>\r\n							<select id=\\\"moderation_select_comments\\\" name=\\\"do\\\">\r\n								\".(($show[\'delete\'] OR $show[\'undelete\'] OR $show[\'approve\']) ? (\"\r\n								<optgroup label=\\\"$vbphrase[option]\\\" id=\\\"moderation_select_comments_optgroup\\\">\r\n									\".(($show[\'delete\']) ? (\"\r\n								<option value=\\\"inlinedelete\\\" id=\\\"inlinemod_comment_controls_delete\\\">$vbphrase[delete_discussions]</option>\r\n									\") : (\"\")).\"\r\n									\".(($show[\'undelete\']) ? (\"\r\n								<option value=\\\"inlineundelete\\\" id=\\\"inlinemod_comment_controls_undelete\\\">$vbphrase[undelete_discussions]</option>\r\n									\") : (\"\")).\"\r\n									\".(($show[\'approve\']) ? (\"\r\n								<option value=\\\"inlineapprove\\\" id=\\\"inlinemod_comment_controls_approve\\\">$vbphrase[approve_discussions]</option>\r\n								<option value=\\\"inlineunapprove\\\" id=\\\"inlinemod_comment_controls_unapprove\\\">$vbphrase[unapprove_discussions]</option>\r\n									\") : (\"\")).\"\r\n								</optgroup>\r\n								\") : (\"\")).\"\r\n								<optgroup label=\\\"____________________\\\">\r\n							<option value=\\\"clearmessage\\\">$vbphrase[deselect_all_discussions]</option>\r\n								</optgroup>\r\n							</select>\r\n					<input type=\\\"submit\\\" value=\\\"$vbphrase[go]\\\" id=\\\"gdiscussion_inlinego\\\" class=\\\"button\\\" />\r\n							<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n							<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n				</div>\r\n					\") : (\"\")).\"\r\n			\".(($show[\'postlink\']) ? (\"<div class=\\\"action_links\\\"><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=message&amp;groupid=$group[groupid]\\\" rel=\\\"nofollow\\\">$vbphrase[new_discussion]</a></div>\") : (\"\")).\"\r\n				</div>\r\n			\") : (\"\")).\"\r\n\r\n		\".(($show[\'inlinemod\']) ? (\"\r\n		\".(($show[popups]) ? (\"\r\n			<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_inlinemod.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n			<script type=\\\"text/javascript\\\">\r\n			<!--\r\n			inlineMod_comment = new vB_Inline_Mod(\'inlineMod_comment\', \'gdiscussion\', \'group_discussion_inlinemod_form\', \'$vbphrase[go_x]\', \'vbulletin_inline\', \'thread\');\r\n			vBmenu.register(\\\"discussion_inlinemodsel\\\");\r\n			//-->\r\n			</script>\r\n\r\n			<!-- inline mod selection popup -->\r\n			<ul id=\\\"discussion_inlinemodsel_menu\\\" class=\\\"vbmenu_popup list_no_decoration\\\" style=\\\"display:none\\\">\r\n				<li class=\\\"thead first\\\">$vbphrase[from_this_page]</li>\r\n				<li class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod_comment.check_all(true)\\\">$vbphrase[select_all]</li>\r\n				<li class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod_comment.check_all(false)\\\">$vbphrase[deselect_all]</li>\r\n				<li class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod_comment.check_all(\'invert\')\\\">$vbphrase[invert_selection]</li>\r\n				<li class=\\\"thead\\\"><img src=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'cleargifurl\'] . \"\\\" alt=\\\"\\\" width=\\\"1\\\" height=\\\"1\\\" /></li>\r\n				<li class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod_comment.check_all(true, 1)\\\">$vbphrase[select_unapproved_posts]</li>\r\n				<li class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod_comment.check_all(true, 2)\\\">$vbphrase[select_deleted_posts]</li>\r\n			</ul>\r\n			<!-- / inline mod selection popup -->\r\n		\") : (\"\")).\"\r\n\r\n		<input type=\\\"hidden\\\" name=\\\"inline_discussion\\\" value=\\\"1\\\" />\r\n		</form>\r\n		<!-- / inline moderation form -->\r\n	\") : (\"\")).\"\r\n\") : (\"\r\n	<div class=\\\"tborder social_group\\\">\r\n		<div class=\\\"alt2 block_row\\\">\r\n			\".(($searchtext) ? (\"\r\n				$vbphrase[no_discussions_found]\r\n			\") : (\"\r\n				$vbphrase[group_has_no_discussions]\r\n			\")).\"\r\n		</div>\r\n	</div>\r\n	\".(($show[\'postlink\']) ? (\"<div class=\\\"action_links\\\"><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=message&amp;groupid=$group[groupid]\\\" rel=\\\"nofollow\\\">$vbphrase[new_discussion]</a></div>\") : (\"\")).\"\r\n\")).\"\r\n\r\n\".(($show[popups]) ? (\"\r\n<!-- group tools popup -->\r\n<ul id=\\\"grouptools_menu\\\" class=\\\"vbmenu_popup list_no_decoration\\\" style=\\\"display:none\\\">\r\n	<li class=\\\"thead first\\\">$vbphrase[group_tools]</li>\r\n	<li class=\\\"vbmenu_option\\\"><a href=\\\"#\\\" rel=\\\"nofollow\\\" onclick=\\\"return mark_group_read($group[groupid]);\\\">$vbphrase[mark_this_group_read]</a></li>\r\n\r\n	\".(($show[subscribe]) ? (\"\r\n		\".((!$group[subscribed]) ? (\"\r\n			<li class=\\\"vbmenu_option\\\"><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=subscribe&amp;groupid=$group[groupid]\\\" rel=\\\"nofollow\\\">$vbphrase[subscribe_to_this_group]</a></li>\r\n		\") : (\"\r\n			<li class=\\\"vbmenu_option\\\"><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=unsubscribe&amp;groupid=$group[groupid]\\\" rel=\\\"nofollow\\\">$vbphrase[unsubscribe_from_this_group]</a></li>\r\n		\")).\"\r\n	\") : (\"\")).\"\r\n</ul>\r\n<!-- / group tools popup -->\r\n\") : (\"\r\n<!-- group tools -->\r\n<br />\r\n<div class=\\\"tborder social_group smallfont\\\">\r\n	<a name=\\\"goto_grouptools\\\"></a>\r\n	<div class=\\\"thead\\\">$vbphrase[group_tools]</div>\r\n	<div class=\\\"alt1 block_row\\\">\r\n		<img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_button]/subscribe.gif\\\" alt=\\\"$vbphrase[mark_this_group_read]\\\" vspace=\\\"1\\\" /> <a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=markread&amp;groupid=$group[groupid]\\\" rel=\\\"nofollow\\\">$vbphrase[mark_this_group_read]</a>\r\n	</div>\r\n	\".(($show[subscribe]) ? (\"\r\n		\".((!$group[subscribed]) ? (\"\r\n			<div class=\\\"alt2 block_row\\\"><img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_button]/subscribe.gif\\\" alt=\\\"$vbphrase[subscribe_to_this_group]\\\" vspace=\\\"1\\\" /> <a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=subscribe&amp;groupid=$group[groupid]\\\" rel=\\\"nofollow\\\">$vbphrase[subscribe_to_this_group]</a></div>\r\n		\") : (\"\r\n			<div class=\\\"alt2 block_row\\\"><img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_button]/subscribe.gif\\\" alt=\\\"$vbphrase[unsubscribe_from_this_group]\\\" vspace=\\\"1\\\" /> <a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=unsubscribe&amp;groupid=$group[groupid]\\\" rel=\\\"nofollow\\\">$vbphrase[unsubscribe_from_this_group]</a></div>\r\n		\")).\"\r\n	\") : (\"\")).\"\r\n</div>\r\n\")).\"\r\n<!-- / group tools -->\r\n\r\n\") : (\"\")).\"\r\n\r\n\".((!$group[\'canviewcontent\']) ? (\"\r\n	<div id=\\\"join_to_view\\\" class=\\\"tborder social_group\\\">\r\n		<div class=\\\"alt2 block_row\\\">\r\n			$vbphrase[must_join_to_view]\r\n		</div>\r\n	</div>\r\n\") : (\"\")).\"\r\n\r\n	\".(($show[\'groupoptions\']) ? (\"\r\n\r\n	<br />\r\n	<div id=\\\"discussion_foot\\\" class=\\\"social_group tborder content_block\\\">\r\n		<div class=\\\"tfoot block_title\\\">\r\n		<ul id=\\\"group_footer_links\\\">\r\n			\".(($groupoptions[\'join\']) ? (\"\r\n				<li class=\\\"smallfont\\\">\r\n					<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=join&amp;groupid=$group[groupid]\\\">$vbphrase[join_group]</a>\r\n				</li>\r\n			\") : (\"\r\n				\".(($group[\'membertype\'] != \'member\' AND $group[\'type\'] == \'inviteonly\') ? (\"\r\n					<li class=\\\"smallfont\\\">\r\n						$vbphrase[group_type_inviteonly]\r\n					</li>\r\n				\") : (\"\")).\"\r\n			\")).\"\r\n			\".(($groupoptions[\'leave\']) ? (\"<li class=\\\"smallfont\\\"><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=leave&amp;groupid=$group[groupid]\\\">$groupoptions[leavephrase]</a></li>\") : (\"\")).\"\r\n			\".(($groupoptions[\'edit\']) ? (\"<li class=\\\"smallfont\\\"><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=edit&amp;groupid=$group[groupid]\\\">$vbphrase[edit_group]</a></li>\") : (\"\")).\"\r\n			\".(($groupoptions[\'delete\']) ? (\"<li class=\\\"smallfont\\\"><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=delete&amp;groupid=$group[groupid]\\\">$vbphrase[delete_group]</a></li>\") : (\"\")).\"\r\n			\".(($groupoptions[\'manage\']) ? (\"\r\n				<li class=\\\"smallfont\\\">\r\n					<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=manage&amp;groupid=$group[groupid]\\\">$vbphrase[pending_and_invited_members]</a>\r\n				</li>\r\n			\") : (\"\")).\"\r\n			\".(($groupoptions[\'managemembers\']) ? (\"\r\n				<li class=\\\"smallfont\\\">\r\n					<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=managemembers&amp;groupid=$group[groupid]\\\">$vbphrase[manage_members]</a>\r\n				</li>\r\n			\") : (\"\")).\"\r\n			\".(($groupoptions[\'transfergroup\']) ? (\"\r\n			<li class=\\\"smallfont\\\">\r\n				<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=transfer&amp;groupid=$group[groupid]\\\">$vbphrase[transfer_group]</a>\r\n			</li>\r\n			\") : (\"\")).\"\r\n		</ul>\r\n	</div>\r\n	</div>\r\n	\") : (\"\")).\"\r\n\r\n$footer\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n	$headinclude\r\n	<title>$vboptions[bbtitle] - $custompagetitle</title>\r\n	$socialgroups_css\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<if condition=\"$show[\'groupinfo\']\">\r\n	<div class=\"social_group tborder content_block\">\r\n	<div class=\"tcat block_title\">\r\n		<if condition=\"$groupoptions[\'join\'] OR $groupoptions[\'leave\']\">\r\n		<span class=\"smallfont\" style=\"float:$stylevar[right]\">\r\n			<if condition=\"$groupoptions[\'join\']\">\r\n					<a href=\"group.php?$session[sessionurl]do=join&amp;groupid=$group[groupid]\">$vbphrase[join_group]</a>\r\n			<else />\r\n				<if condition=\"!$group[\'membertype\'] AND $group[\'type\'] == \'inviteonly\'\">\r\n						$vbphrase[group_type_inviteonly]\r\n				</if>\r\n			</if>\r\n			<if condition=\"$groupoptions[\'join\'] AND $groupoptions[\'leave\']\">\r\n				&nbsp;|&nbsp;\r\n			</if>\r\n				<if condition=\"$groupoptions[\'leave\']\"><a href=\"group.php?$session[sessionurl]do=leave&amp;groupid=$group[groupid]\">$groupoptions[leavephrase]</a></if>\r\n		</span>\r\n		</if>\r\n		<if condition=\"$group[membermoderated]\">$vbphrase[moderated_social_group]<else />$vbphrase[social_group]</if>\r\n	</div>\r\n\r\n	<!-- group info -->\r\n	<div class=\"alt1 block_row\">\r\n		<if condition=\"$groupiconurl\">\r\n		<img src=\"$groupiconurl\" alt=\"\" style=\"float:$stylevar[right]\" class=\"sgicon\" />\r\n		</if>\r\n		<h1 id=\"group_name\">$group[name]</h1>\r\n		<div id=\"group_creator\" class=\"smallfont\"><phrase 1=\"$ownerlink\" 2=\"$group[creatorusername]\">$vbphrase[group_maintained_by_x]</phrase></div>\r\n		<if condition=\"$group[\'description\']\">\r\n			<p id=\"group_description\">$group[description]</p>\r\n		</if>\r\n	</div>\r\n\r\n	<!-- members -->\r\n	<div class=\"thead block_row\">\r\n		<a id=\"view_all_members_link\" class=\"smallfont\" href=\"group.php?$session[sessionurl]do=viewmembers&amp;groupid=$group[groupid]\">$vbphrase[view_all_members]</a>\r\n		<phrase 1=\"$members_shown\" 2=\"$group[members]\">$vbphrase[showing_x_of_y_members]</phrase>\r\n	</div>\r\n\r\n	<div class=\"alt2 block_row\">\r\n		<ul id=\"group_member_list\">$short_member_list_bits</ul>\r\n	</div>\r\n\r\n	<!-- pictures -->\r\n	<if condition=\"$show[\'pictures_block\']\">\r\n	<div class=\"thead block_row\">\r\n		<div id=\"picture_links\" class=\"smallfont\">\r\n			<a href=\"group.php?$session[sessionurl]do=grouppictures&amp;groupid=$group[groupid]\">$vbphrase[view_pictures]</a>\r\n			<if condition=\"$show[\'add_pictures_link\']\">| <a href=\"group.php?$session[sessionurl]do=addpictures&amp;groupid=$group[groupid]\">$vbphrase[add_pictures]</a></if>\r\n		</div>\r\n		<if condition=\"$pictures_shown\">\r\n			<phrase 1=\"$pictures_shown\" 2=\"$group[picturecount]\">$vbphrase[showing_x_of_y_pictures]</phrase>\r\n		<else />\r\n			$vbphrase[group_pictures]\r\n		</if>\r\n	</div>\r\n	<div class=\"alt1 block_row\">\r\n		<if condition=\"$picturebits\">\r\n			$picturebits\r\n		<else />\r\n			$vbphrase[no_pictures_added_group_yet]\r\n			<if condition=\"$show[\'add_pictures_link\']\"><a href=\"group.php?$session[sessionurl]do=addpictures&amp;groupid=$group[groupid]\">$vbphrase[add_pictures_to_this_group]</a></if>\r\n		</if>\r\n	</div>\r\n	</if>\r\n\r\n	</div><br />\r\n</if>\r\n\r\n\r\n<!-- Discussions -->\r\n<if condition=\"$show[\'groupdiscussions\']\">\r\n	<script type=\"text/javascript\" src=\"clientscript/vbulletin_group_read_marker.js?v=$vboptions[simpleversion]\"></script>\r\n	<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" style=\"border-bottom-width:0px\">\r\n	<tr>\r\n		<td class=\"tcat\" width=\"100%\" colspan=\"3\">\r\n			<if condition=\"$messagebits OR $searchtext\">\r\n				<div style=\"float:$stylevar[right]\" class=\"normal\">\r\n					<form action=\"group.php\" method=\"post\">\r\n						$vbphrase[search_discussions]\r\n						<input type=\"text\" class=\"bginput\" name=\"searchtext\" value=\"$searchtext\" style=\"font-size: 11px;\" />&nbsp;<input type=\"submit\" class=\"button\" value=\"$vbphrase[go]\" />\r\n						<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n						<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n						<input type=\"hidden\" name=\"groupid\" value=\"$group[groupid]\" />\r\n						<input type=\"hidden\" name=\"perpage\" value=\"$perpage\" />\r\n\r\n\r\n					</form>\r\n					</div>\r\n	</if>\r\n			<if condition=\"!$show[\'groupinfo\']\">\r\n				<phrase 1=\"$group[name]\">$vbphrase[social_group_discussions_in_x]</phrase>\r\n			<else />\r\n				$vbphrase[social_group_discussions]\r\n			</if>\r\n		</td>\r\n		<td class=\"vbmenu_control\" id=\"grouptools\" nowrap=\"nowrap\"><a href=\"$show[nojs_link]#goto_grouptools\" rel=\"nofollow\">$vbphrase[group_tools]</a> <script type=\"text/javascript\"> vbmenu_register(\"grouptools\"); </script></td>\r\n	</tr>\r\n	</table>\r\n\r\n	<if condition=\"$messagebits\">\r\n	<if condition=\"$show[\'inlinemod\']\">\r\n		<form action=\"group_inlinemod.php?groupid=$group[groupid]\" method=\"post\" id=\"group_discussion_inlinemod_form\">\r\n	</if>\r\n	<table class=\"tborder discussion_list\" id=\"discussion_list\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\">\r\n	<tr class=\"block_title\">\r\n		$template_hook[group_discussionlist_start_col]\r\n		<td class=\"thead\" width=\"100%\">\r\n			<if condition=\"$messagetotal\">\r\n				<span style=\"float:$stylevar[right]\"><a href=\"$orderlinks[dateline]&amp;pp=$perpage&amp;page=$pagenumber\">$vbphrase[group_created] $sortarrow[dateline]</a></span>\r\n				<if condition=\"$messagestart > 1\">\r\n					<phrase 1=\"$messagestart\" 2=\"$messageend\" 3=\"$messagetotal\">$vbphrase[showing_discussions_x_to_y_of_z]</phrase>\r\n				<else />\r\n					<phrase 1=\"$messageshown\" 2=\"$messagetotal\">$vbphrase[showing_discussions_x_of_y]</phrase>\r\n				</if>\r\n			</if>\r\n		</td>\r\n		<td class=\"thead\" align=\"center\" nowrap=\"nowrap\">\r\n			<a href=\"$orderlinks[replies]&amp;pp=$perpage&amp;page=$pagenumber\">$vbphrase[replies]</a> $sortarrow[replies]\r\n		</td>\r\n		<td class=\"thead\" align=\"center\" nowrap=\"nowrap\">\r\n			<a href=\"$orderlinks[lastpost]&amp;pp=$perpage&amp;page=$pagenumber\">$vbphrase[last_post]</a> $sortarrow[lastpost]\r\n		</td>\r\n\r\n		<if condition=\"$show[\'inlinemod\']\">\r\n			<td class=\"thead\" align=\"center\" nowrap=\"nowrap\">\r\n				<a id=\"discussion_inlinemodsel\"></a>\r\n			</td>\r\n		</if>\r\n		$template_hook[group_discussionlist_end_col]\r\n	</tr>\r\n		$messagebits\r\n	</table>\r\n\r\n	<if condition=\"$show[\'inlinemod\'] OR $pagenav OR $show[\'postlink\']\">\r\n		<div class=\"floatcontainer\">\r\n			<if condition=\"$pagenav\">\r\n				<div id=\"discussion_pagenav\">\r\n					$pagenav\r\n				</div>\r\n			</if>\r\n					<if condition=\"$show[\'inlinemod\']\">\r\n				<div id=\"discussion_moderation\">\r\n					<div class=\"smallfont push_down\"><label for=\"moderation_select_comments\"><strong>$vbphrase[moderation]</strong></label></div>\r\n							<select id=\"moderation_select_comments\" name=\"do\">\r\n								<if condition=\"$show[\'delete\'] OR $show[\'undelete\'] OR $show[\'approve\']\">\r\n								<optgroup label=\"$vbphrase[option]\" id=\"moderation_select_comments_optgroup\">\r\n									<if condition=\"$show[\'delete\']\">\r\n								<option value=\"inlinedelete\" id=\"inlinemod_comment_controls_delete\">$vbphrase[delete_discussions]</option>\r\n									</if>\r\n									<if condition=\"$show[\'undelete\']\">\r\n								<option value=\"inlineundelete\" id=\"inlinemod_comment_controls_undelete\">$vbphrase[undelete_discussions]</option>\r\n									</if>\r\n									<if condition=\"$show[\'approve\']\">\r\n								<option value=\"inlineapprove\" id=\"inlinemod_comment_controls_approve\">$vbphrase[approve_discussions]</option>\r\n								<option value=\"inlineunapprove\" id=\"inlinemod_comment_controls_unapprove\">$vbphrase[unapprove_discussions]</option>\r\n									</if>\r\n								</optgroup>\r\n								</if>\r\n								<optgroup label=\"____________________\">\r\n							<option value=\"clearmessage\">$vbphrase[deselect_all_discussions]</option>\r\n								</optgroup>\r\n							</select>\r\n					<input type=\"submit\" value=\"$vbphrase[go]\" id=\"gdiscussion_inlinego\" class=\"button\" />\r\n							<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n							<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n				</div>\r\n					</if>\r\n			<if condition=\"$show[\'postlink\']\"><div class=\"action_links\"><a href=\"group.php?$session[sessionurl]do=message&amp;groupid=$group[groupid]\" rel=\"nofollow\">$vbphrase[new_discussion]</a></div></if>\r\n				</div>\r\n			</if>\r\n\r\n		<if condition=\"$show[\'inlinemod\']\">\r\n		<if condition=\"$show[popups]\">\r\n			<script type=\"text/javascript\" src=\"clientscript/vbulletin_inlinemod.js?v=$vboptions[simpleversion]\"></script>\r\n			<script type=\"text/javascript\">\r\n			<!--\r\n			inlineMod_comment = new vB_Inline_Mod(\'inlineMod_comment\', \'gdiscussion\', \'group_discussion_inlinemod_form\', \'$vbphrase[go_x]\', \'vbulletin_inline\', \'thread\');\r\n			vBmenu.register(\"discussion_inlinemodsel\");\r\n			//-->\r\n			</script>\r\n\r\n			<!-- inline mod selection popup -->\r\n			<ul id=\"discussion_inlinemodsel_menu\" class=\"vbmenu_popup list_no_decoration\" style=\"display:none\">\r\n				<li class=\"thead first\">$vbphrase[from_this_page]</li>\r\n				<li class=\"vbmenu_option\" onclick=\"inlineMod_comment.check_all(true)\">$vbphrase[select_all]</li>\r\n				<li class=\"vbmenu_option\" onclick=\"inlineMod_comment.check_all(false)\">$vbphrase[deselect_all]</li>\r\n				<li class=\"vbmenu_option\" onclick=\"inlineMod_comment.check_all(\'invert\')\">$vbphrase[invert_selection]</li>\r\n				<li class=\"thead\"><img src=\"$vboptions[cleargifurl]\" alt=\"\" width=\"1\" height=\"1\" /></li>\r\n				<li class=\"vbmenu_option\" onclick=\"inlineMod_comment.check_all(true, 1)\">$vbphrase[select_unapproved_posts]</li>\r\n				<li class=\"vbmenu_option\" onclick=\"inlineMod_comment.check_all(true, 2)\">$vbphrase[select_deleted_posts]</li>\r\n			</ul>\r\n			<!-- / inline mod selection popup -->\r\n		</if>\r\n\r\n		<input type=\"hidden\" name=\"inline_discussion\" value=\"1\" />\r\n		</form>\r\n		<!-- / inline moderation form -->\r\n	</if>\r\n<else />\r\n	<div class=\"tborder social_group\">\r\n		<div class=\"alt2 block_row\">\r\n			<if condition=\"$searchtext\">\r\n				$vbphrase[no_discussions_found]\r\n			<else />\r\n				$vbphrase[group_has_no_discussions]\r\n			</if>\r\n		</div>\r\n	</div>\r\n	<if condition=\"$show[\'postlink\']\"><div class=\"action_links\"><a href=\"group.php?$session[sessionurl]do=message&amp;groupid=$group[groupid]\" rel=\"nofollow\">$vbphrase[new_discussion]</a></div></if>\r\n</if>\r\n\r\n<if condition=\"$show[popups]\">\r\n<!-- group tools popup -->\r\n<ul id=\"grouptools_menu\" class=\"vbmenu_popup list_no_decoration\" style=\"display:none\">\r\n	<li class=\"thead first\">$vbphrase[group_tools]</li>\r\n	<li class=\"vbmenu_option\"><a href=\"#\" rel=\"nofollow\" onclick=\"return mark_group_read($group[groupid]);\">$vbphrase[mark_this_group_read]</a></li>\r\n\r\n	<if condition=\"$show[subscribe]\">\r\n		<if condition=\"!$group[subscribed]\">\r\n			<li class=\"vbmenu_option\"><a href=\"group.php?$session[sessionurl]do=subscribe&amp;groupid=$group[groupid]\" rel=\"nofollow\">$vbphrase[subscribe_to_this_group]</a></li>\r\n		<else />\r\n			<li class=\"vbmenu_option\"><a href=\"group.php?$session[sessionurl]do=unsubscribe&amp;groupid=$group[groupid]\" rel=\"nofollow\">$vbphrase[unsubscribe_from_this_group]</a></li>\r\n		</if>\r\n	</if>\r\n</ul>\r\n<!-- / group tools popup -->\r\n<else />\r\n<!-- group tools -->\r\n<br />\r\n<div class=\"tborder social_group smallfont\">\r\n	<a name=\"goto_grouptools\"></a>\r\n	<div class=\"thead\">$vbphrase[group_tools]</div>\r\n	<div class=\"alt1 block_row\">\r\n		<img class=\"inlineimg\" src=\"$stylevar[imgdir_button]/subscribe.gif\" alt=\"$vbphrase[mark_this_group_read]\" vspace=\"1\" /> <a href=\"group.php?$session[sessionurl]do=markread&amp;groupid=$group[groupid]\" rel=\"nofollow\">$vbphrase[mark_this_group_read]</a>\r\n	</div>\r\n	<if condition=\"$show[subscribe]\">\r\n		<if condition=\"!$group[subscribed]\">\r\n			<div class=\"alt2 block_row\"><img class=\"inlineimg\" src=\"$stylevar[imgdir_button]/subscribe.gif\" alt=\"$vbphrase[subscribe_to_this_group]\" vspace=\"1\" /> <a href=\"group.php?$session[sessionurl]do=subscribe&amp;groupid=$group[groupid]\" rel=\"nofollow\">$vbphrase[subscribe_to_this_group]</a></div>\r\n		<else />\r\n			<div class=\"alt2 block_row\"><img class=\"inlineimg\" src=\"$stylevar[imgdir_button]/subscribe.gif\" alt=\"$vbphrase[unsubscribe_from_this_group]\" vspace=\"1\" /> <a href=\"group.php?$session[sessionurl]do=unsubscribe&amp;groupid=$group[groupid]\" rel=\"nofollow\">$vbphrase[unsubscribe_from_this_group]</a></div>\r\n		</if>\r\n	</if>\r\n</div>\r\n</if>\r\n<!-- / group tools -->\r\n\r\n</if>\r\n\r\n<if condition=\"!$group[\'canviewcontent\']\">\r\n	<div id=\"join_to_view\" class=\"tborder social_group\">\r\n		<div class=\"alt2 block_row\">\r\n			$vbphrase[must_join_to_view]\r\n		</div>\r\n	</div>\r\n</if>\r\n\r\n	<if condition=\"$show[\'groupoptions\']\">\r\n\r\n	<br />\r\n	<div id=\"discussion_foot\" class=\"social_group tborder content_block\">\r\n		<div class=\"tfoot block_title\">\r\n		<ul id=\"group_footer_links\">\r\n			<if condition=\"$groupoptions[\'join\']\">\r\n				<li class=\"smallfont\">\r\n					<a href=\"group.php?$session[sessionurl]do=join&amp;groupid=$group[groupid]\">$vbphrase[join_group]</a>\r\n				</li>\r\n			<else />\r\n				<if condition=\"$group[\'membertype\'] != \'member\' AND $group[\'type\'] == \'inviteonly\'\">\r\n					<li class=\"smallfont\">\r\n						$vbphrase[group_type_inviteonly]\r\n					</li>\r\n				</if>\r\n			</if>\r\n			<if condition=\"$groupoptions[\'leave\']\"><li class=\"smallfont\"><a href=\"group.php?$session[sessionurl]do=leave&amp;groupid=$group[groupid]\">$groupoptions[leavephrase]</a></li></if>\r\n			<if condition=\"$groupoptions[\'edit\']\"><li class=\"smallfont\"><a href=\"group.php?$session[sessionurl]do=edit&amp;groupid=$group[groupid]\">$vbphrase[edit_group]</a></li></if>\r\n			<if condition=\"$groupoptions[\'delete\']\"><li class=\"smallfont\"><a href=\"group.php?$session[sessionurl]do=delete&amp;groupid=$group[groupid]\">$vbphrase[delete_group]</a></li></if>\r\n			<if condition=\"$groupoptions[\'manage\']\">\r\n				<li class=\"smallfont\">\r\n					<a href=\"group.php?$session[sessionurl]do=manage&amp;groupid=$group[groupid]\">$vbphrase[pending_and_invited_members]</a>\r\n				</li>\r\n			</if>\r\n			<if condition=\"$groupoptions[\'managemembers\']\">\r\n				<li class=\"smallfont\">\r\n					<a href=\"group.php?$session[sessionurl]do=managemembers&amp;groupid=$group[groupid]\">$vbphrase[manage_members]</a>\r\n				</li>\r\n			</if>\r\n			<if condition=\"$groupoptions[\'transfergroup\']\">\r\n			<li class=\"smallfont\">\r\n				<a href=\"group.php?$session[sessionurl]do=transfer&amp;groupid=$group[groupid]\">$vbphrase[transfer_group]</a>\r\n			</li>\r\n			</if>\r\n		</ul>\r\n	</div>\r\n	</div>\r\n	</if>\r\n\r\n$footer\r\n</body>\r\n</html>', 'template', 1234873522, 'vBulletin Solutions', '3.8.2', 'vbulletin'),
(428, -1, 'socialgroups_grouplist_bit', '<tr>\r\n	<td class=\\\"alt1\\\" width=\\\"100%\\\" valign=\\\"top\\\">\r\n		\".(($group[iconurl]) ? (\"\r\n			<div class=\\\"sgicon\\\" style=\\\"float:$stylevar[left];padding:2px 4px 2px 0\\\">\r\n				<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"groupid=$group[groupid]\\\">\r\n					<img class=\\\"sgicon\\\" src=\\\"$group[iconurl]\\\" alt=\\\"$group[shortdescription]\\\" />\r\n				</a>\r\n			</div>\r\n		\") : (\"\")).\"\r\n		\".(($show[category_names]) ? (\"\r\n			<span style=\\\"float:$stylevar[right]\\\" class=\\\"smallfont\\\"><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=grouplist&amp;cat=$group[categoryid]\\\" style=\\\"font-weight:normal\\\">$group[categoryname]</a></span>\r\n		\") : (\"\")).\"\r\n		<div style=\\\"margin-bottom:$stylevar[cellpadding]px; margin-$stylevar[left]:$stylevar[cellspacing]px\\\">\r\n			<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"groupid=$group[groupid]\\\" \".((!$group[\'is_read\']) ? (\"class=\\\"unread\\\"\") : (\"\")).\">$group[name]</a>\r\n		</div>\r\n\r\n		<div>$group[mediumdescription]</div>\r\n\r\n	</td>\r\n	<td class=\\\"alt2\\\" align=\\\"center\\\"><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=viewmembers&amp;groupid=$group[groupid]\\\">$group[members]</a></td>\r\n	\".(($show[\'gminfo\']) ? (\"\r\n		<td class=\\\"alt1\\\" align=\\\"center\\\">$group[discussions]</td>\r\n		<td class=\\\"alt2\\\" align=\\\"center\\\">$group[visible]</td>\r\n	\") : (\"\")).\"\r\n	\".(($show[\'pictureinfo\']) ? (\"<td class=\\\"alt1\\\" align=\\\"center\\\">\".(($group[\'picturecount\']) ? (\"<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=grouppictures&amp;groupid=$group[groupid]\\\">$group[picturecount]</a>\") : (\"$group[picturecount]\")).\"</td>\") : (\"\")).\"\r\n\r\n	\".(($show[\'gminfo\']) ? (\"\r\n	<td class=\\\"$lastpostalt smallfont\\\" align=\\\"center\\\" nowrap=\\\"nowrap\\\">\r\n	\".(($show[\'lastpostinfo\']) ? (\"\r\n		<div style=\\\"text-align: center\\\">\r\n			$group[lastpostdate]\r\n			\".((!$show[\'detailedtime\']) ? (\"\r\n				<br /><span class=\\\"time\\\">$group[lastposttime]</span>\r\n			\") : (\"\")).\"\r\n		</div>\r\n	\") : (\"\r\n		<div style=\\\"text-align: center\\\">\r\n			$group[createdate]\r\n		</div>\r\n	\")).\"\r\n	</td>\r\n	\") : (\"\")).\"\r\n</tr>', '<tr>\r\n	<td class=\"alt1\" width=\"100%\" valign=\"top\">\r\n		<if condition=\"$group[iconurl]\">\r\n			<div class=\"sgicon\" style=\"float:$stylevar[left];padding:2px 4px 2px 0\">\r\n				<a href=\"group.php?$session[sessionurl]groupid=$group[groupid]\">\r\n					<img class=\"sgicon\" src=\"$group[iconurl]\" alt=\"$group[shortdescription]\" />\r\n				</a>\r\n			</div>\r\n		</if>\r\n		<if condition=\"$show[category_names]\">\r\n			<span style=\"float:$stylevar[right]\" class=\"smallfont\"><a href=\"group.php?$session[sessionurl]do=grouplist&amp;cat=$group[categoryid]\" style=\"font-weight:normal\">$group[categoryname]</a></span>\r\n		</if>\r\n		<div style=\"margin-bottom:$stylevar[cellpadding]px; margin-$stylevar[left]:$stylevar[cellspacing]px\">\r\n			<a href=\"group.php?$session[sessionurl]groupid=$group[groupid]\" <if condition=\"!$group[\'is_read\']\">class=\"unread\"</if>>$group[name]</a>\r\n		</div>\r\n\r\n		<div>$group[mediumdescription]</div>\r\n\r\n	</td>\r\n	<td class=\"alt2\" align=\"center\"><a href=\"group.php?$session[sessionurl]do=viewmembers&amp;groupid=$group[groupid]\">$group[members]</a></td>\r\n	<if condition=\"$show[\'gminfo\']\">\r\n		<td class=\"alt1\" align=\"center\">$group[discussions]</td>\r\n		<td class=\"alt2\" align=\"center\">$group[visible]</td>\r\n	</if>\r\n	<if condition=\"$show[\'pictureinfo\']\"><td class=\"alt1\" align=\"center\"><if condition=\"$group[\'picturecount\']\"><a href=\"group.php?$session[sessionurl]do=grouppictures&amp;groupid=$group[groupid]\">$group[picturecount]</a><else />$group[picturecount]</if></td></if>\r\n\r\n	<if condition=\"$show[\'gminfo\']\">\r\n	<td class=\"$lastpostalt smallfont\" align=\"center\" nowrap=\"nowrap\">\r\n	<if condition=\"$show[\'lastpostinfo\']\">\r\n		<div style=\"text-align: center\">\r\n			$group[lastpostdate]\r\n			<if condition=\"!$show[\'detailedtime\']\">\r\n				<br /><span class=\"time\">$group[lastposttime]</span>\r\n			</if>\r\n		</div>\r\n	<else />\r\n		<div style=\"text-align: center\">\r\n			$group[createdate]\r\n		</div>\r\n	</if>\r\n	</td>\r\n	</if>\r\n</tr>', 'template', 1232979416, 'vBulletin Solutions', '3.8.1', 'vbulletin'),
(429, -1, 'socialgroups_groupmodlist_bit', '<tr>\r\n	<td class=\\\"alt1\\\" width=\\\"100%\\\" valign=\\\"top\\\" rowspan=\\\"\".(($show[pictureinfo]) ? (\"3\") : (\"2\")).\"\\\">\r\n		<div><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"groupid=$group[groupid]\\\" \".((!$group[\'is_read\']) ? (\"class=\\\"unread\\\"\") : (\"\")).\">$group[name]</a></div>\r\n		<div class=\\\"smallfont\\\">$group[shortdescription]</div>\r\n			\r\n	</td>\r\n	<td class=\\\"smallfont alt2\\\">$vbphrase[group_members]</td>\r\n	<td class=\\\"smallfont alt2\\\"><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=viewmembers&amp;groupid=$group[groupid]\\\">$group[members]</a></td>\r\n\r\n	<td class=\\\"alt1 smallfont\\\" align=\\\"center\\\" nowrap=\\\"nowrap\\\" rowspan=\\\"\".(($show[pictureinfo]) ? (\"3\") : (\"2\")).\"\\\">\r\n		\".(($show[\'lastpostinfo\']) ? (\"\r\n			\".(($group[\'lastposterid\']) ? (\"\r\n				<div style=\\\"text-align: $stylevar[left]\\\">\r\n					<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=discuss&amp;gmid=$group[lastgmid]#gmessage$group[lastgmid]\\\" style=\\\"white-space:nowrap\\\" title=\\\"$vbphrase[go_to_last_post]\\\"><strong>$group[trimdiscussion]</strong></a>\r\n				</div>\r\n			\") : (\"\")).\"\r\n			<div style=\\\"text-align: $stylevar[left]\\\">\r\n				$group[lastpostdate] \r\n				\".((!$show[\'detailedtime\']) ? (\"\r\n					<span class=\\\"time\\\">$group[lastposttime]</span>\r\n				\") : (\"\")).\"\r\n			</div>\r\n			\".(($group[\'lastposterid\']) ? (\"\r\n				<div style=\\\"text-align: $stylevar[right]\\\">\r\n			\" . construct_phrase(\"$vbphrase[by_x]\", \"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$group[lastposterid]\", \"$group[lastposter]\") . \"\r\n					<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=discuss&amp;gmid=$group[lastgmid]#gmessage$group[lastgmid]\\\"><img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_button]/lastpost.gif\\\" alt=\\\"$vbphrase[go_to_last_post]\\\" border=\\\"0\\\" /></a>\r\n		</div>\r\n		\") : (\"\")).\"\r\n		\") : (\"\r\n			<div style=\\\"text-align: $stylevar[left]\\\">\r\n				<div style=\\\"text-align: $stylevar[left]\\\">\r\n					$vbphrase[group_created]\r\n				</div>\r\n				$group[lastpostdate] \r\n				\".((!$show[\'detailedtime\']) ? (\"\r\n					<span class=\\\"time\\\">$group[lastposttime]</span>\r\n		\") : (\"\")).\"\r\n			</div>\r\n		\")).\"\r\n	</td>\r\n</tr>\r\n<!-- <tr>\r\n	<td class=\\\"smallfont alt1\\\">$vbphrase[discussions]</td>\r\n	<td class=\\\"smallfont alt1\\\">$group[discussions]</td>\r\n</tr> -->\r\n<tr>\r\n	<td class=\\\"smallfont alt2\\\">$vbphrase[messages]</td>\r\n	<td class=\\\"smallfont alt2\\\">$group[visible]</td>\r\n</tr>\r\n\".(($show[\'pictureinfo\']) ? (\"\r\n<tr>\r\n	<td class=\\\"smallfont alt2\\\">$vbphrase[pictures]</td>\r\n	<td class=\\\"smallfont alt2\\\">\r\n		\".(($group[\'picturecount\']) ? (\"\r\n			<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=grouppictures&amp;groupid=$group[groupid]\\\">$group[picturecount]</a>\r\n		\") : (\"\r\n			$group[picturecount]\r\n		\")).\"\r\n	</td>\r\n</tr>\r\n\") : (\"\")).\"', '<tr>\r\n	<td class=\"alt1\" width=\"100%\" valign=\"top\" rowspan=\"<if condition=\"$show[pictureinfo]\">3<else />2</if>\">\r\n		<div><a href=\"group.php?$session[sessionurl]groupid=$group[groupid]\" <if condition=\"!$group[\'is_read\']\">class=\"unread\"</if>>$group[name]</a></div>\r\n		<div class=\"smallfont\">$group[shortdescription]</div>\r\n			\r\n	</td>\r\n	<td class=\"smallfont alt2\">$vbphrase[group_members]</td>\r\n	<td class=\"smallfont alt2\"><a href=\"group.php?$session[sessionurl]do=viewmembers&amp;groupid=$group[groupid]\">$group[members]</a></td>\r\n\r\n	<td class=\"alt1 smallfont\" align=\"center\" nowrap=\"nowrap\" rowspan=\"<if condition=\"$show[pictureinfo]\">3<else />2</if>