roup.php?$session[sessionurl]gmid=$message[gmid]#gmessage$message[gmid]\" 2=\"$message[groupname]\">$vbphrase[group_x]</phrase></span>\r\n			</if>\r\n			<if condition=\"$show[\'discussion\']\">\r\n				<span><phrase 1=\"group.php?$session[sessionurl]gmid=$message[gmid]#gmessage$message[gmid]\" 2=\"$message[discussiontitle]\">$vbphrase[discussion_x]</phrase></span>\r\n			</if>\r\n			</div>\r\n			</if>\r\n		</div>\r\n	</div>\r\n\r\n		<div class=\"social_group_message_body\">\r\n			<if condition=\"$show[\'deleted\']\">\r\n				$message[message]<br />\r\n			</if>\r\n	<div class=\"smallfont deletedmessage\">\r\n		<phrase 1=\"member.php?$session[sessionurl]u=$message[del_userid]\" 2=\"$message[del_username]\">$vbphrase[message_deleted_by_x]</phrase>\r\n		<if condition=\"$message[\'del_reason\']\"><span class=\"shade\">$vbphrase[reason]</span> <em>$message[del_reason]</em></if>\r\n	</div>\r\n	\r\n		<ul class=\"list_no_decoration controls\">\r\n			<if condition=\"$show[\'edit\']\">\r\n					<li class=\"smallfont\"><a class=\"smallfont\" href=\"group.php?$session[sessionurl]do=message&amp;gmid=$message[gmid]&amp;page=$show[pagenumber]\">$vbphrase[edit]</a></li>\r\n			</if>\r\n			<if condition=\"$show[\'reportlink\']\">\r\n				<li class=\"smallfont\"><a class=\"smallfont\" href=\"group.php?$session[sessionurl]do=report&amp;gmid=$message[gmid]\">$vbphrase[report]</a></li>\r\n			</if>\r\n		</ul>\r\n		</div>\r\n	</div>\r\n</div>', 'template', 1219079849, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(437, -1, 'socialgroups_message_ignored', '<div class=\\\"social_group_message\\\">\r\n	<div id=\\\"gmessage$message[gmid]\\\" class=\\\"floatcontainer alt1 tborder\\\">\r\n	<div class=\\\"tborder info_bar\\\">\r\n		<div class=\\\"alt2 smallfont\\\">\r\n			\".(($show[\'inlinemod\']) ? (\"<input type=\\\"checkbox\\\" class=\\\"inlinemod_checkbox\\\" name=\\\"gmessagelist[$message[gmid]]\\\" id=\\\"gmessagelist_$message[gmid]\\\" value=\\\"$message[checkbox_value]\\\" title=\\\"$vbphrase[select_this_item_for_inline_moderation]\\\" />\") : (\"\")).\"\r\n			<div class=\\\"group_message_date\\\">$message[date]\".((!$show[\'detailedtime\']) ? (\" <span class=\\\"time\\\">$message[time]</span>\") : (\"\")).\"</div>\r\n				<a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$message[postuserid]\\\" class=\\\"username\\\">$message[musername]</a>\r\n\r\n			\".(($show[\'group\'] OR $show[\'discussion\']) ? (\"\r\n			<div>\r\n			\".(($show[\'group\']) ? (\"\r\n				<span>\" . construct_phrase(\"$vbphrase[group_x]\", \"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"gmid=$message[gmid]#gmessage$message[gmid]\", \"$message[groupname]\") . \"</span>\r\n			\") : (\"\")).\"\r\n			\".(($show[\'discussion\']) ? (\"\r\n				<span>\" . construct_phrase(\"$vbphrase[discussion_x]\", \"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"gmid=$message[gmid]#gmessage$message[gmid]\", \"$message[discussiontitle]\") . \"</span>\r\n			\") : (\"\")).\"\r\n			</div>\r\n			\") : (\"\")).\"\r\n		</div>\r\n	</div>\r\n		\r\n		<div class=\\\"social_group_message_body smallfont\\\">\r\n			\".(($show[\'moderation\']) ? (\"<div class=\\\"shade smallfont\\\">$vbphrase[this_message_is_moderated]</div>\") : (\"\")).\"\r\n		\" . construct_phrase(\"$vbphrase[message_hidden_x_on_ignore_list]\", \"$message[username]\", \"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=ignorelist\") . \"\r\n			\r\n			<ul class=\\\"list_no_decoration controls\\\">\r\n				<li class=\\\"smallfont\\\"><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"groupid=$group[groupid]&amp;gmid=$message[gmid]&amp;&amp;do=discuss&amp;showignored=1#gmessage$message[gmid]\\\">$vbphrase[show_message_text]</a></li>\r\n			</ul>\r\n	</div>\r\n	</div>\r\n</div>', '<div class=\"social_group_message\">\r\n	<div id=\"gmessage$message[gmid]\" class=\"floatcontainer alt1 tborder\">\r\n	<div class=\"tborder info_bar\">\r\n		<div class=\"alt2 smallfont\">\r\n			<if condition=\"$show[\'inlinemod\']\"><input type=\"checkbox\" class=\"inlinemod_checkbox\" name=\"gmessagelist[$message[gmid]]\" id=\"gmessagelist_$message[gmid]\" value=\"$message[checkbox_value]\" title=\"$vbphrase[select_this_item_for_inline_moderation]\" /></if>\r\n			<div class=\"group_message_date\">$message[date]<if condition=\"!$show[\'detailedtime\']\"> <span class=\"time\">$message[time]</span></if></div>\r\n				<a href=\"member.php?$session[sessionurl]u=$message[postuserid]\" class=\"username\">$message[musername]</a>\r\n\r\n			<if condition=\"$show[\'group\'] OR $show[\'discussion\']\">\r\n			<div>\r\n			<if condition=\"$show[\'group\']\">\r\n				<span><phrase 1=\"group.php?$session[sessionurl]gmid=$message[gmid]#gmessage$message[gmid]\" 2=\"$message[groupname]\">$vbphrase[group_x]</phrase></span>\r\n			</if>\r\n			<if condition=\"$show[\'discussion\']\">\r\n				<span><phrase 1=\"group.php?$session[sessionurl]gmid=$message[gmid]#gmessage$message[gmid]\" 2=\"$message[discussiontitle]\">$vbphrase[discussion_x]</phrase></span>\r\n			</if>\r\n			</div>\r\n			</if>\r\n		</div>\r\n	</div>\r\n		\r\n		<div class=\"social_group_message_body smallfont\">\r\n			<if condition=\"$show[\'moderation\']\"><div class=\"shade smallfont\">$vbphrase[this_message_is_moderated]</div></if>\r\n		<phrase 1=\"$message[username]\" 2=\"profile.php?$session[sessionurl]do=ignorelist\">$vbphrase[message_hidden_x_on_ignore_list]</phrase>\r\n			\r\n			<ul class=\"list_no_decoration controls\">\r\n				<li class=\"smallfont\"><a href=\"group.php?$session[sessionurl]groupid=$group[groupid]&amp;gmid=$message[gmid]&amp;&amp;do=discuss&amp;showignored=1#gmessage$message[gmid]\">$vbphrase[show_message_text]</a></li>\r\n			</ul>\r\n	</div>\r\n	</div>\r\n</div>', 'template', 1219079869, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(438, -1, 'socialgroups_mygroups_bit', '<div class=\\\"sgicon\\\">\r\n	<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"groupid=$mygroup[groupid]\\\">\r\n		<img class=\\\"sgicon\\\" src=\\\"$mygroup[iconurl]\\\" alt=\\\"$mygroup[shortdescription]\\\" />\r\n		<span class=\\\"smallfont \".((!$mygroup[is_read]) ? (\"unread\") : (\"\")).\"\\\">$mygroup[name]</span>\r\n	</a>\r\n	$template_hook[group_after_mygroups_bit]\r\n</div>', '<div class=\"sgicon\">\r\n	<a href=\"group.php?$session[sessionurl]groupid=$mygroup[groupid]\">\r\n		<img class=\"sgicon\" src=\"$mygroup[iconurl]\" alt=\"$mygroup[shortdescription]\" />\r\n		<span class=\"smallfont <if condition=\"!$mygroup[is_read]\">unread</if>\">$mygroup[name]</span>\r\n	</a>\r\n	$template_hook[group_after_mygroups_bit]\r\n</div>', 'template', 1218628617, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(439, -1, 'socialgroups_mygroups_listview_bit', '<tr>\r\n	<td class=\\\"alt1\\\" width=\\\"100%\\\">\r\n		<span style=\\\"float:$stylevar[right]\\\" class=\\\"smallfont\\\"><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=grouplist&amp;cat=$mygroup[categoryid]\\\" style=\\\"font-weight:normal\\\">$mygroup[categoryname]</a></span>\r\n		<div style=\\\"margin-bottom:$stylevar[cellpadding]px; margin-$stylevar[left]:$stylevar[cellspacing]px\\\">\r\n			<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"groupid=$mygroup[groupid]\\\" \".((!$mygroup[\'is_read\']) ? (\"class=\\\"unread\\\"\") : (\"\")).\">$mygroup[name]</a>\r\n			<div class=\\\"smallfont\\\">$mygroup[shortdescription]</div>\r\n		</div>\r\n	</td>\r\n	\r\n	<td class=\\\"alt2\\\" align=\\\"center\\\" nowrap=\\\"nowrap\\\">$mygroup[joindate]</td>\r\n	<td class=\\\"alt1 smallfont\\\" align=\\\"center\\\" nowrap=\\\"nowrap\\\">\r\n		\".(($mygroup[\'group_options\']) ? (\"\r\n		\".(($mygroup[\'edit_group\']) ? (\"\r\n			<div><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=edit&amp;groupid=$mygroup[groupid]\\\">$vbphrase[edit_group]</a></div>\r\n		\") : (\"\")).\"\r\n		\".(($mygroup[\'delete_group\']) ? (\"\r\n			<div><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=delete&amp;groupid=$mygroup[groupid]\\\">$vbphrase[delete_group]</a></div>\r\n		\") : (\"\")).\"\r\n		\".(($mygroup[\'leave_group\']) ? (\"\r\n			<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=leave&amp;groupid=$mygroup[groupid]\\\">$vbphrase[leave_social_group]</a>\r\n		\") : (\"\")).\"\r\n		\") : (\"\r\n			$vbphrase[n_a]\r\n		\")).\"\r\n	</td>\r\n</tr>', '<tr>\r\n	<td class=\"alt1\" width=\"100%\">\r\n		<span style=\"float:$stylevar[right]\" class=\"smallfont\"><a href=\"group.php?$session[sessionurl]do=grouplist&amp;cat=$mygroup[categoryid]\" style=\"font-weight:normal\">$mygroup[categoryname]</a></span>\r\n		<div style=\"margin-bottom:$stylevar[cellpadding]px; margin-$stylevar[left]:$stylevar[cellspacing]px\">\r\n			<a href=\"group.php?$session[sessionurl]groupid=$mygroup[groupid]\" <if condition=\"!$mygroup[\'is_read\']\">class=\"unread\"</if>>$mygroup[name]</a>\r\n			<div class=\"smallfont\">$mygroup[shortdescription]</div>\r\n		</div>\r\n	</td>\r\n	\r\n	<td class=\"alt2\" align=\"center\" nowrap=\"nowrap\">$mygroup[joindate]</td>\r\n	<td class=\"alt1 smallfont\" align=\"center\" nowrap=\"nowrap\">\r\n		<if condition=\"$mygroup[\'group_options\']\">\r\n		<if condition=\"$mygroup[\'edit_group\']\">\r\n			<div><a href=\"group.php?$session[sessionurl]do=edit&amp;groupid=$mygroup[groupid]\">$vbphrase[edit_group]</a></div>\r\n		</if>\r\n		<if condition=\"$mygroup[\'delete_group\']\">\r\n			<div><a href=\"group.php?$session[sessionurl]do=delete&amp;groupid=$mygroup[groupid]\">$vbphrase[delete_group]</a></div>\r\n		</if>\r\n		<if condition=\"$mygroup[\'leave_group\']\">\r\n			<a href=\"group.php?$session[sessionurl]do=leave&amp;groupid=$mygroup[groupid]\">$vbphrase[leave_social_group]</a>\r\n		</if>\r\n		<else />\r\n			$vbphrase[n_a]\r\n		</if>\r\n	</td>\r\n</tr>', 'template', 1232023585, 'vBulletin Solutions', '3.8.1', 'vbulletin'),
(440, -1, 'socialgroups_newgroup_bit', '<div class=\\\"sgicon\\\">\r\n	<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"groupid=$group[groupid]\\\">\r\n		<img class=\\\"sgicon\\\" src=\\\"$group[iconurl]\\\" alt=\\\"$group[shortdescription]\\\" />\r\n		<span class=\\\"smallfont \".((!$group[\'is_read\']) ? (\"unread\") : (\"\")).\"\\\">$group[name]</span>\r\n	</a>\r\n	$template_hook[group_after_newgroup_bit]\r\n</div>', '<div class=\"sgicon\">\r\n	<a href=\"group.php?$session[sessionurl]groupid=$group[groupid]\">\r\n		<img class=\"sgicon\" src=\"$group[iconurl]\" alt=\"$group[shortdescription]\" />\r\n		<span class=\"smallfont <if condition=\"!$group[\'is_read\']\">unread</if>\">$group[name]</span>\r\n	</a>\r\n	$template_hook[group_after_newgroup_bit]\r\n</div>', 'template', 1218628472, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(441, -1, 'socialgroups_newgroup_listview_bit', '<tr>\r\n	<td class=\\\"alt1\\\">\r\n		<div style=\\\"margin:0 $stylevar[cellpadding]px\\\">\r\n			<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"groupid=$group[groupid]\\\">$group[name]</a>\r\n			<div class=\\\"smallfont\\\">$group[shortdescription]</div>\r\n		</div>\r\n	</td>\r\n	<td class=\\\"alt2 smallfont\\\" align=\\\"center\\\" nowrap=\\\"nowrap\\\"><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=grouplist&amp;cat=$group[categoryid]\\\" style=\\\"font-weight:normal\\\">$group[categoryname]</a></td>\r\n</tr>', '<tr>\r\n	<td class=\"alt1\">\r\n		<div style=\"margin:0 $stylevar[cellpadding]px\">\r\n			<a href=\"group.php?$session[sessionurl]groupid=$group[groupid]\">$group[name]</a>\r\n			<div class=\"smallfont\">$group[shortdescription]</div>\r\n		</div>\r\n	</td>\r\n	<td class=\"alt2 smallfont\" align=\"center\" nowrap=\"nowrap\"><a href=\"group.php?$session[sessionurl]do=grouplist&amp;cat=$group[categoryid]\" style=\"font-weight:normal\">$group[categoryname]</a></td>\r\n</tr>', 'template', 1232023618, 'vBulletin Solutions', '3.8.1', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(442, -1, 'socialgroups_overview', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $custompagetitle</title>\r\n$socialgroups_css\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n$template_hook[group_overview_start]\r\n\r\n<div class=\\\"floatcontainer\\\">\r\n	<div class=\\\"floatwrapper\\\">\r\n\r\n		$template_hook[group_overview_before_categories]\r\n\r\n		\".(($categorybits) ? (\"\r\n		<div id=\\\"sg_catcloud\\\">\r\n			<form action=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=grouplist\\\" method=\\\"post\\\">\r\n				<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" align=\\\"center\\\" width=\\\"100%\\\">\r\n				<tr>\r\n					<td class=\\\"tcat\\\">\r\n						<div style=\\\"float:$stylevar[right]\\\" class=\\\"normal\\\">$vbphrase[search_groups] <input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"filtertext\\\" value=\\\"$filters[text]\\\" style=\\\"font-size: 11px;\\\" />&nbsp;<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[go]\\\" /></div>\r\n						$vbphrase[categories]\r\n					</td>\r\n				</tr>\r\n				<tr>\r\n					<td class=\\\"alt1\\\">\r\n						$categorybits\r\n					</td>\r\n				</tr>\r\n				<tr>\r\n					<td align=\\\"$stylevar[right]\\\" class=\\\"tfoot smallfont\\\">\r\n						<strong><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=categorylist\\\">$vbphrase[view_all_categories]</a></strong>\r\n					</td>\r\n				</tr>\r\n				</table>\r\n\r\n				<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n				<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n				<input type=\\\"hidden\\\" name=\\\"dofilter\\\" value=\\\"1\\\" />\r\n			</form>\r\n		</div>\r\n		\") : (\"\")).\"\r\n\r\n		$template_hook[group_overview_after_categories]\r\n\r\n		\".(($randomgroup) ? (\"\r\n		<div id=\\\"sg_randomgroup\\\">\r\n			<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" align=\\\"center\\\" width=\\\"100%\\\">\r\n			<tr>\r\n				<td class=\\\"tcat\\\">\r\n					$vbphrase[random_group]\r\n				</td>\r\n			</tr>\r\n			<tr>\r\n				<td class=\\\"alt1\\\">\r\n					<span style=\\\"float:$stylevar[right]\\\" class=\\\"smallfont\\\">\" . construct_phrase(\"$vbphrase[in_category_x]\", \"<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=grouplist&amp;cat=$randomgroup[categoryid]\\\" style=\\\"font-weight:normal\\\">$randomgroup[categoryname]</a>\") . \"</span>\r\n					<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"groupid=$randomgroup[groupid]\\\" \".((!$randomgroup[is_read]) ? (\"class=\\\"unread\\\"\") : (\"\")).\">$randomgroup[name]</a><br />\r\n				</td>\r\n			</tr>\r\n			<tr>\r\n				<td class=\\\"alt1\\\">\r\n					\".(($show[\'sgicons\']) ? (\"<div class=\\\"sgicon\\\"><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"groupid=$randomgroup[groupid]\\\"><img class=\\\"sgicon\\\" src=\\\"$randomgroup[iconurl]\\\" alt=\\\"$randomgroup[shortdescription]\\\" /></a></div>\") : (\"\")).\"\r\n					<span style=\\\"display:block\\\">$randomgroup[mediumdescription]</span>\r\n					<div id=\\\"sg_randomgroup_info\\\">\r\n						<table cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" border=\\\"0\\\">\r\n						<tr>\r\n							<td nowrap=\\\"nowrap\\\" align=\\\"$stylevar[left]\\\" valign=\\\"top\\\">\r\n								<div><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionid\'] . \"groupid=$randomgroup[groupid]\\\">$vbphrase[group_members]:</a> <strong>$randomgroup[members]</strong></div>\r\n							\".(($show[\'pictureinfo\']) ? (\"\r\n								<div><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionid\'] . \"do=grouppictures&amp;groupid=$randomgroup[groupid]\\\">$vbphrase[pictures]:</a> <strong>$randomgroup[picturecount]</strong></div>\r\n							\") : (\"\")).\"\r\n							</td>\r\n							\".(($show[\'messageinfo\']) ? (\"\r\n							<td nowrap=\\\"nowrap\\\" align=\\\"$stylevar[left]\\\" valign=\\\"top\\\">\r\n								<div><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"groupid=$randomgroup[groupid]\\\">$vbphrase[discussions]:</a> <strong>$randomgroup[discussions]</strong></div>\r\n								<div><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionid\'] . \"groupid=$randomgroup[groupid]\\\">$vbphrase[messages]:</a> <strong>$randomgroup[visible]</strong></div>\r\n							</td>\r\n							\") : (\"\")).\"\r\n						</tr>\r\n						</table>\r\n					</div>\r\n					$template_hook[group_random_group_info]\r\n				</td>\r\n			</tr>\r\n			<tr>\r\n				<td class=\\\"tfoot smallfont\\\">\r\n					<span style=\\\"float:$stylevar[right]\\\"><strong><a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=grouplist\\\">$vbphrase[view_all_groups]</a></strong></span>\r\n				</td>\r\n			</tr>\r\n			</table>\r\n		</div>\r\n		\") : (\"\")).\"\r\n\r\n		$template_hook[group_overview_after_random_group]\r\n\r\n		\".(($owngroup) ? (\"\r\n		<div id=\\\"sg_owngroups\\\">\r\n			$owngroup\r\n		</div>\r\n		\") : (\"\")).\"\r\n\r\n		$template_hook[group_overview_after_own_groups]\r\n\r\n\r\n		<div id=\\\"sg_mygroups\\\">\r\n			<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" style=\\\"margin-bottom:20px\\\">\r\n			<tr>\r\n				<td class=\\\"tcat\\\" colspan=\\\"3\\\">$vbphrase[your_groups]</td>\r\n			</tr>\r\n\