		</if>\r\n					<if condition=\"$show[\'reportlink\']\">\r\n						<div><a href=\"group.php?$session[sessionurl]do=reportpicture&amp;groupid=$group[groupid]&amp;pictureid=$pictureinfo[pictureid]\">$vbphrase[report_picture]</a></div>\r\n					</if>\r\n					</div>\r\n				</if>\r\n				<div><span class=\"shade\">$vbphrase[picture_added]:</span> $pictureinfo[adddate] <if condition=\"!$show[\'detailedtime\']\"><span class=\"time\">$pictureinfo[addtime]</span></if></div>\r\n				<div><span class=\"shade\">$vbphrase[picture_by]:</span> <a href=\"member.php?$session[sessionurl]u=$pictureinfo[userid]\">$pictureinfo[username]</a></div>\r\n			</td>\r\n		</tr>\r\n		</table>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<if condition=\"$show[\'picture_nav\']\">\r\n	<div class=\"smallfont\" align=\"center\" style=\"margin-top: $stylevar[cellpadding]px\">\r\n		<a href=\"group.php?$session[sessionurl]do=picture&amp;groupid=$group[groupid]&amp;pictureid=$pic_location[prev_pictureid]\">$pic_location[prev_text]</a> |\r\n		<a href=\"group.php?$session[sessionurl]do=picture&amp;groupid=$group[groupid]&amp;pictureid=$pic_location[next_pictureid]\">$pic_location[next_text]</a>\r\n	</div>\r\n</if>\r\n\r\n$picturecomment_commentarea\r\n\r\n<if condition=\"$show[\'picturecomment_options\'] AND $show[\'picture_nav\']\">\r\n	<div class=\"smallfont\" align=\"center\" style=\"margin-top: $stylevar[cellpadding]px\">\r\n		<a href=\"group.php?$session[sessionurl]do=picture&amp;groupid=$group[groupid]&amp;pictureid=$pic_location[prev_pictureid]\">$pic_location[prev_text]</a> |\r\n		<a href=\"group.php?$session[sessionurl]do=picture&amp;groupid=$group[groupid]&amp;pictureid=$pic_location[next_pictureid]\">$pic_location[next_text]</a>\r\n	</div>\r\n</if>\r\n\r\n$footer\r\n</body>\r\n</html>', 'template', 1214218742, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(445, -1, 'socialgroups_picturebit', '<table style=\\\"width:{$picturebit_width}px; margin:5px; float:$stylevar[left]\\\" border=\\\"0\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\">\r\n<tr>\r\n	<td class=\\\"smallfont\\\" align=\\\"center\\\" valign=\\\"middle\\\" style=\\\"height:{$picturebit_height}px\\\">\r\n	\".(($picture[\'thumburl\']) ? (\"\r\n		<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=picture&amp;groupid=$group[groupid]&amp;pictureid=$picture[pictureid]\\\"><img class=\\\"alt2\\\" src=\\\"$picture[thumburl]\\\" alt=\\\"$picture[caption_preview]\\\" border=\\\"0\\\" style=\\\"\r\n			padding:$stylevar[cellpadding]px;\r\n			\".((!$usercss) ? (\"border:solid $stylevar[cellspacing]px $stylevar[tborder_bgcolor];\") : (\"\")).\"\r\n		\\\" $picture[dimensions] /></a>\r\n	\") : (\"\r\n		<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=picture&amp;groupid=$group[groupid]&amp;pictureid=$picture[pictureid]\\\">\".(($picture[\'caption_preview\']) ? (\"$picture[caption_preview]\") : (\"$vbphrase[picture]\")).\"</a>\r\n	\")).\"\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"smallfont\\\" align=\\\"center\\\" style=\\\"overflow:hidden; white-space: nowrap\\\">\r\n		\".(($picture[\'username\']) ? (\"\r\n			\" . construct_phrase(\"$vbphrase[from_x]\", \"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"\", \"$picture[userid]\", \"$picture[username]\") . \"\r\n		\") : (\"\r\n			&nbsp;\r\n		\")).\"\r\n	</td>\r\n</tr>\r\n</table>', '<table style=\"width:{$picturebit_width}px; margin:5px; float:$stylevar[left]\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tr>\r\n	<td class=\"smallfont\" align=\"center\" valign=\"middle\" style=\"height:{$picturebit_height}px\">\r\n	<if condition=\"$picture[\'thumburl\']\">\r\n		<a href=\"group.php?$session[sessionurl]do=picture&amp;groupid=$group[groupid]&amp;pictureid=$picture[pictureid]\"><img class=\"alt2\" src=\"$picture[thumburl]\" alt=\"$picture[caption_preview]\" border=\"0\" style=\"\r\n			padding:$stylevar[cellpadding]px;\r\n			<if condition=\"!$usercss\">border:solid $stylevar[cellspacing]px $stylevar[tborder_bgcolor];</if>\r\n		\" $picture[dimensions] /></a>\r\n	<else />\r\n		<a href=\"group.php?$session[sessionurl]do=picture&amp;groupid=$group[groupid]&amp;pictureid=$picture[pictureid]\"><if condition=\"$picture[\'caption_preview\']\">$picture[caption_preview]<else />$vbphrase[picture]</if></a>\r\n	</if>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"smallfont\" align=\"center\" style=\"overflow:hidden; white-space: nowrap\">\r\n		<if condition=\"$picture[\'username\']\">\r\n			<phrase 1=\"$session[sessionurl]\" 2=\"$picture[userid]\" 3=\"$picture[username]\">$vbphrase[from_x]</phrase>\r\n		<else />\r\n			&nbsp;\r\n		</if>\r\n	</td>\r\n</tr>\r\n</table>', 'template', 1213886222, 'vBulletin Solutions', '3.7.1', 'vbulletin'),
(446, -1, 'socialgroups_pictures', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n	$headinclude\r\n	<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $custompagetitle</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n\".(($pagenav) ? (\"<div style=\\\"margin-bottom:3px\\\">$pagenav</div>\") : (\"\")).\"\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		\".(($show[\'add_pictures_link\']) ? (\"<a class=\\\"smallfont\\\" style=\\\"float: $stylevar[right]\\\" href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=addpictures&amp;groupid=$group[groupid]\\\">$vbphrase[add_pictures]</a>\") : (\"\")).\"\r\n		\" . construct_phrase(\"$vbphrase[pictures_from_group_x]\", \"$group[name]\") . \"\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"alt1 floatcontainer\\\" id=\\\"picturebits\\\">\r\n		\".(($picturebits) ? (\"\r\n			$picturebits\r\n		\") : (\"\r\n			$vbphrase[no_pictures_added_group_yet]\r\n			\".(($show[\'add_pictures_link\']) ? (\"<a href=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=addpictures&amp;groupid=$group[groupid]\\\">$vbphrase[add_pictures_to_this_group]</a>\") : (\"\")).\"\r\n		\")).\"\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n\".(($pagenav) ? (\"<div style=\\\"margin-top:3px\\\">$pagenav</div>\") : (\"\")).\"\r\n\r\n$footer\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n	$headinclude\r\n	<title>$vboptions[bbtitle] - $custompagetitle</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<if condition=\"$pagenav\"><div style=\"margin-bottom:3px\">$pagenav</div></if>\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		<if condition=\"$show[\'add_pictures_link\']\"><a class=\"smallfont\" style=\"float: $stylevar[right]\" href=\"group.php?$session[sessionurl]do=addpictures&amp;groupid=$group[groupid]\">$vbphrase[add_pictures]</a></if>\r\n		<phrase 1=\"$group[name]\">$vbphrase[pictures_from_group_x]</phrase>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"alt1 floatcontainer\" id=\"picturebits\">\r\n		<if condition=\"$picturebits\">\r\n			$picturebits\r\n		<else />\r\n			$vbphrase[no_pictures_added_group_yet]\r\n			<if condition=\"$show[\'add_pictures_link\']\"><a href=\"group.php?$session[sessionurl]do=addpictures&amp;groupid=$group[groupid]\">$vbphrase[add_pictures_to_this_group]</a></if>\r\n		</if>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<if condition=\"$pagenav\"><div style=\"margin-top:3px\">$pagenav</div></if>\r\n\r\n$footer\r\n</body>\r\n</html>', 'template', 1196261152, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(447, -1, 'socialgroups_search', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n	$headinclude\r\n	<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $pagetitle</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n\".(($show[\'errors\']) ? (\"\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr align=\\\"$stylevar[left]\\\">\r\n	<td class=\\\"tcat\\\">\r\n	\".((!$grouplisttitle) ? (\"$vbphrase[errors_occured_with_search]\r\n	\") : (\"$grouplisttitle\")).\"\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"alt1\\\">\r\n		\".(($show[\'noresults\']) ? (\"\r\n			<ol style=\\\"list-style-type:none\\\">$errorlist</ol>\r\n		\") : (\"\r\n			<ol>$errorlist</ol>\r\n		\")).\"\r\n	</td>\r\n</tr>\r\n</table>\r\n<br /><br />\r\n\") : (\"\")).\"\r\n\r\n<form action=\\\"group.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=grouplist\\\" method=\\\"post\\\">\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" align=\\\"center\\\" width=\\\"100%\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[advanced_search]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n		<div class=\\\"panel\\\">\r\n		<table style=\\\"width:$stylevar[formwidth]\\\" align=\\\"center\\\" border=\\\"0\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\">\r\n		<tr valign=\\\"top\\\">\r\n			<td width=\\\"50%\\\" align=\\\"$stylevar[left]\\\">\r\n				<fieldset class=\\\"fieldset\\\">\r\n					<legend>$vbphrase[search_by_key_word]</legend>\r\n					<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n						<div><label for=\\\"filter_keywords\\\">$vbphrase[key_words]:</label></div>\r\n						<div><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"filtertext\\\" id=\\\"filter_keywords\\\" size=\\\"35\\\" value=\\\"$filters[text]\\\" style=\\\"width:250px\\\" /></div>\r\n					</div>\r\n				</fieldset>\r\n				<fieldset class=\\\"fieldset\\\">\r\n					<legend>$vbphrase[find_groups_with]</legend>\r\n					<table cellspacing=\\\"0\\\" cellpadding=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n					<tr>\r\n						<td>\r\n							<select name=\\\"memberless\\\" style=\\\"width:150px\\\">\r\n								<option value=\\\"0\\\" $memberlessselected[0]>$vbphrase[at_least]</option>\r\n								<option value=\\\"1\\\" $memberlessselected[1]>$vbphrase[at_most]</option>\r\n							</select>\r\n						</td>\r\n						<td align=\\\"$stylevar[left]\\\">\r\n							<label for=\\\"memberlimit\\\"><input type=\\\"text\\\" class=\\\"bginput\\\" style=\\\"font-size:11px\\\" name=\\\"memberlimit\\\" id=\\\"memberlimit\\\" size=\\\"3\\\" value=\\\"$memberlimit\\\" /> $vbphrase[members]</label>\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td>\r\n							<select name=\\\"discussionless\\\" style=\\\"width:150px\\\">\r\n								<option value=\\\"0\\\" $discussionlessselected[0]>$vbphrase[at_least]</option>\r\n								<option value=\\\"1\\\" $discussionlessselected[1]>$vbphrase[at_most]</option>\r\n							</select>\r\n						</td>\r\n						<td align=\\\"$stylevar[left]\\\">\r\n							<label for=\\\"discussionlimit\\\"><input type=\\\"text\\\" class=\\\"bginput\\\" style=\\\"font-size:11px\\\" name=\\\"discussionlimit\\\" id=\\\"discussionlimit\\\" size=\\\"3\\\" value=\\\"$discussionlimit\\\" /> $vbphrase[discussions]</label>\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td>\r\n							<select name=\\\"messageless\\\" style=\\\"width:150px\\\">\r\n								<option value=\\\"0\\\" $messagelessselected[0]>$vbphrase[at_least]</option>\r\n								<option value=\\\"1\\\" $messagelessselected[1]>$vbphrase[at_most]</option>\r\n							</select>\r\n						</td>\r\n						<td align=\\\