(461, -1, 'subscription_payment', '<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[select_payment_method]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div align=\\\"$stylevar[left]\\\">\r\n\r\n			<div class=\\\"fieldset\\\">\r\n				$vbphrase[to_pay_for_your_subscription]\r\n			</div>\r\n\r\n			<div class=\\\"fieldset\\\">\r\n				<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n				<tr>\r\n					<td>$vbphrase[subscription]:</td>\r\n					<td><strong>$subscription_title</strong></td>\r\n				</tr>\r\n				<tr>\r\n					<td>$vbphrase[duration]:</td>\r\n					<td><strong>$subscription_length</strong></td>\r\n				</tr>\r\n				<tr>\r\n					<td>$vbphrase[cost]:</td>\r\n					<td><strong>$subscription_cost</strong></td>\r\n				</tr>\r\n				</table>\r\n			</div>\r\n\r\n			$orderbits\r\n\r\n		</div>\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>', '<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">$vbphrase[select_payment_method]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div align=\"$stylevar[left]\">\r\n\r\n			<div class=\"fieldset\">\r\n				$vbphrase[to_pay_for_your_subscription]\r\n			</div>\r\n\r\n			<div class=\"fieldset\">\r\n				<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n				<tr>\r\n					<td>$vbphrase[subscription]:</td>\r\n					<td><strong>$subscription_title</strong></td>\r\n				</tr>\r\n				<tr>\r\n					<td>$vbphrase[duration]:</td>\r\n					<td><strong>$subscription_length</strong></td>\r\n				</tr>\r\n				<tr>\r\n					<td>$vbphrase[cost]:</td>\r\n					<td><strong>$subscription_cost</strong></td>\r\n				</tr>\r\n				</table>\r\n			</div>\r\n\r\n			$orderbits\r\n\r\n		</div>\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>', 'template', 1125401481, 'vBulletin Solutions', '3.5.0 Release Candidate 3', 'vbulletin'),
(462, -1, 'subscription_paymentbit', '<form action=\\\"$form[action]\\\" method=\\\"$form[method]\\\">\r\n	<fieldset class=\\\"fieldset\\\">\r\n		<legend>\" . construct_phrase(\"$vbphrase[order_using_x]\", \"{$vbphrase[$method[classname]]}\") . \"</legend>\r\n		<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n			<div style=\\\"margin-bottom:$stylevar[formspacer]px\\\">$vbphrase[$typetext]</div>\r\n			<div>\r\n				$form[hiddenfields]\r\n				<input type=\\\"submit\\\" class=\\\"button\\\" style=\\\"font-weight:normal\\\" value=\\\"\" . construct_phrase(\"$vbphrase[order_using_x]\", \"{$vbphrase[$method[classname]]}\") . \"\\\" />\r\n			</div>\r\n		</div>\r\n	</fieldset>\r\n</form>', '<form action=\"$form[action]\" method=\"$form[method]\">\r\n	<fieldset class=\"fieldset\">\r\n		<legend><phrase 1=\"{$vbphrase[$method[classname]]}\">$vbphrase[order_using_x]</phrase></legend>\r\n		<div style=\"padding:$stylevar[formspacer]px\">\r\n			<div style=\"margin-bottom:$stylevar[formspacer]px\">$vbphrase[$typetext]</div>\r\n			<div>\r\n				$form[hiddenfields]\r\n				<input type=\"submit\" class=\"button\" style=\"font-weight:normal\" value=\"<phrase 1=\"{$vbphrase[$method[classname]]}\">$vbphrase[order_using_x]</phrase>\" />\r\n			</div>\r\n		</div>\r\n	</fieldset>\r\n</form>', 'template', 1119630159, 'vBulletin Solutions', '3.5.0 Beta 3', 'vbulletin'),
(463, -1, 'subscription_payment_2checkout', '<input type=\\\"hidden\\\" name=\\\"sid\\\" value=\\\"$settings[twocheckout_id]\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"cart_order_id\\\" value=\\\"$item\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"total\\\" value=\\\"$cost\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"id_type\\\" value=\\\"2\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"c_prod\\\" value=\\\"$subinfo[twocheckout_prodid]\\\" />', '<input type=\"hidden\" name=\"sid\" value=\"$settings[twocheckout_id]\" />\r\n<input type=\"hidden\" name=\"cart_order_id\" value=\"$item\" />\r\n<input type=\"hidden\" name=\"total\" value=\"$cost\" />\r\n<input type=\"hidden\" name=\"id_type\" value=\"2\" />\r\n<input type=\"hidden\" name=\"c_prod\" value=\"$subinfo[twocheckout_prodid]\" />', 'template', 1170440078, 'vBulletin Solutions', '3.6.6', 'vbulletin'),
(464, -1, 'subscription_payment_authorizenet', '<input type=\\\"hidden\\\" name=\\\"x_login\\\" value=\\\"$settings[authorize_loginid]\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"x_fp_sequence\\\" value=\\\"$sequence\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"x_fp_timestamp\\\" value=\\\"$timenow\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"x_fp_hash\\\" value=\\\"$fingerprint\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"x_show_form\\\" value=\\\"PAYMENT_FORM\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"x_amount\\\" value=\\\"$cost\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"x_currency_code\\\" value=\\\"$currency\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"x_invoice_num\\\" value=\\\"$userinfo[username]\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"x_description\\\" value=\\\"\" . construct_phrase(\"$vbphrase[x_subscription]\", \"$item\") . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"x_relay_response\\\" value=\\\"TRUE\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"x_relay_url\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'bburl\'] . \"/payment_gateway.php?method=authorizenet\\\" />', '<input type=\"hidden\" name=\"x_login\" value=\"$settings[authorize_loginid]\" />\r\n<input type=\"hidden\" name=\"x_fp_sequence\" value=\"$sequence\" />\r\n<input type=\"hidden\" name=\"x_fp_timestamp\" value=\"$timenow\" />\r\n<input type=\"hidden\" name=\"x_fp_hash\" value=\"$fingerprint\" />\r\n<input type=\"hidden\" name=\"x_show_form\" value=\"PAYMENT_FORM\" />\r\n<input type=\"hidden\" name=\"x_amount\" value=\"$cost\" />\r\n<input type=\"hidden\" name=\"x_currency_code\" value=\"$currency\" />\r\n<input type=\"hidden\" name=\"x_invoice_num\" value=\"$userinfo[username]\" />\r\n<input type=\"hidden\" name=\"x_description\" value=\"<phrase 1=\"$item\">$vbphrase[x_subscription]</phrase>\" />\r\n<input type=\"hidden\" name=\"x_relay_response\" value=\"TRUE\" />\r\n<input type=\"hidden\" name=\"x_relay_url\" value=\"$vboptions[bburl]/payment_gateway.php?meth