(465, -1, 'subscription_payment_ccbill', '<input type=\\\"hidden\\\" name=\\\"clientAccnum\\\" value=\\\"$settings[clientAccnum]\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"clientSubacc\\\" value=\\\"$settings[clientSubacc]\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"formName\\\" value=\\\"$settings[formName]\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"subscriptionTypeId\\\" value=\\\"$subinfo[ccbillsubid]\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"allowedTypes\\\" value=\\\"$subinfo[ccbillsubid]\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"email\\\" value=\\\"$settings[email]\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"hash\\\" value=\\\"$hash\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"username\\\" value=\\\"NOUSERNAME\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"password\\\" value=\\\"NOPASSWORD\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"noCache\\\" value=\\\"1\\\" />', '<input type=\"hidden\" name=\"clientAccnum\" value=\"$settings[clientAccnum]\" />\r\n<input type=\"hidden\" name=\"clientSubacc\" value=\"$settings[clientSubacc]\" />\r\n<input type=\"hidden\" name=\"formName\" value=\"$settings[formName]\" />\r\n<input type=\"hidden\" name=\"subscriptionTypeId\" value=\"$subinfo[ccbillsubid]\" />\r\n<input type=\"hidden\" name=\"allowedTypes\" value=\"$subinfo[ccbillsubid]\" />\r\n<input type=\"hidden\" name=\"email\" value=\"$settings[email]\" />\r\n<input type=\"hidden\" name=\"hash\" value=\"$hash\" />\r\n<input type=\"hidden\" name=\"username\" value=\"NOUSERNAME\" />\r\n<input type=\"hidden\" name=\"password\" value=\"NOPASSWORD\" />\r\n<input type=\"hidden\" name=\"noCache\" value=\"1\" />', 'template', 1146784809, 'vBulletin Solutions', '3.6.0 Beta 1', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(466, -1, 'subscription_payment_moneybookers', '<input type=\\\"hidden\\\" name=\\\"pay_to_email\\\" value=\\\"$settings[mbemail]\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"transaction_id\\\" value=\\\"$hash\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"amount\\\" value=\\\"$cost\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"currency\\\" value=\\\"$currency\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"return_url\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'bburl\'] . \"/\" . $GLOBALS[\'vbulletin\']->options[\'forumhome\'] . \".php\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"cancel_url\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'bburl\'] . \"/\" . $GLOBALS[\'vbulletin\']->options[\'forumhome\'] . \".php\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"status_url\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'bburl\'] . \"/payment_gateway.php?method=moneybookers\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"detail1_description\\\" value=\\\"$vbphrase[username]\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"detail1_text\\\" value=\\\"$userinfo[username]\\\" />', '<input type=\"hidden\" name=\"pay_to_email\" value=\"$settings[mbemail]\" />\r\n<input type=\"hidden\" name=\"transaction_id\" value=\"$hash\" />\r\n<input type=\"hidden\" name=\"amount\" value=\"$cost\" />\r\n<input type=\"hidden\" name=\"currency\" value=\"$currency\" />\r\n<input type=\"hidden\" name=\"return_url\" value=\"$vboptions[bburl]/$vboptions[forumhome].php\" />\r\n<input type=\"hidden\" name=\"cancel_url\" value=\"$vboptions[bburl]/$vboptions[forumhome].php\" />\r\n<input type=\"hidden\" name=\"status_url\" value=\"$vboptions[bburl]/payment_gateway.php?method=moneybookers\" />\r\n<input type=\"hidden\" name=\"detail1_description\" value=\"$vbphrase[username]\" />\r\n<input type=\"hidden\" name=\"detail1_text\" value=\"$userinfo[username]\" />', 'template', 1123594101, 'vBulletin Solutions', '3.5.0 Release Candidate 3', 'vbulletin'),
(467, -1, 'subscription_payment_nochex', '<input type=\\\"hidden\\\" name=\\\"merchant_id\\\" value=\\\"$settings[ncxemail]\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"amount\\\" value=\\\"$cost\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"order_id\\\" value=\\\"$item\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"success_url\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'bburl\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"responder_url\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'bburl\'] . \"/payment_gateway.php?method=nochex\\\" />', '<input type=\"hidden\" name=\"merchant_id\" value=\"$settings[ncxemail]\" />\r\n<input type=\"hidden\" name=\"amount\" value=\"$cost\" />\r\n<input type=\"hidden\" name=\"order_id\" value=\"$item\" />\r\n<input type=\"hidden\" name=\"success_url\" value=\"$vboptions[bburl]\" />\r\n<input type=\"hidden\" name=\"responder_url\" value=\"$vboptions[bburl]/payment_gateway.php?method=nochex\" />', 'template', 1170869888, 'vBulletin Solutions', '3.6.6', 'vbulletin'),
(468, -1, 'subscription_payment_paypal', '\".(($show[\'recurring\']) ? (\"\r\n<input type=\\\"hidden\\\" name=\\\"cmd\\\" value=\\\"_xclick-subscriptions\\\" />\r\n\") : (\"\r\n<input type=\\\"hidden\\\" name=\\\"cmd\\\" value=\\\"_xclick\\\" />\r\n\")).\"\r\n<input type=\\\"hidden\\\" name=\\\"business\\\" value=\\\"$settings[ppemail]\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"item_name\\\" value=\\\"\" . construct_phrase(\"$vbphrase[x_subscription]\", \"$subinfo[title]\") . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"item_number\\\" value=\\\"$item\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"currency_code\\\" value=\\\"$currency\\\" />\r\n\".(($show[\'recurring\']) ? (\"\r\n<input type=\\\"hidden\\\" name=\\\"a3\\\" value=\\\"$cost\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"p3\\\" value=\\\"$timeinfo[length]\\\">\r\n<input type=\\\"hidden\\\" name=\\\"t3\\\" value=\\\"$timeinfo[units]\\\">\r\n<input type=\\\"hidden\\\" name=\\\"src\\\" value=\\\"1\\\">\r\n<input type=\\\"hidden\\\" name=\\\"sra\\\" value=\\\"1\\\">\r\n\") : (\"\r\n<input type=\\\"hidden\\\" name=\\\"amount\\\" value=\\\"$cost\\\" />\r\n\")).\"\r\n<input type=\\\"hidden\\\" name=\\\"no_shipping\\\" value=\\\"$no_shipping\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"shipping\\\" value=\\\"0.00\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"return\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'bburl\'] . \"/\" . $GLOBALS[\'vbulletin\']->options[\'forumhome\'] . \".php\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"cancel_return\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'bburl\'] . \"/\" . $GLOBALS[\'vbulletin\']->options[\'forumhome\'] . \".php\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"notify_url\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'bburl\'] . \"/payment_gateway.php?method=paypal\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"custom\\\" value=\\\"$userinfo[username]\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"no_note\\\" value=\\\"1\\\" />\r\n\".(($show[\'notax\']) ? (\"\r\n<input type=\\\"hidden\\\" name=\\\"tax\\\" value=\\\"0.00\\\" />\r\n\") : (\"\")).\"', '<if condition=\"$show[\'recurring\']\">\r\n<input type=\"hidden\" name=\"cmd\" value=\"_xclick-subscriptions\" />\r\n<else />\r\n<input type=\"hidden\" name=\"cmd\" value=\"_xclick\" />\r\n</if>\r\n<input type=\"hidden\" name=\"business\" value=\"$settings[ppemail]\" />\r\n<input type=\"hidden\" name=\"item_name\" value=\"<phrase 1=\"$subinfo[title]\">$vbphrase[x_subscription]</phrase>\" />\r\n<input type=\"hidden\" name=\"item_number\" value=\"$item\" />\r\n<input type=\"hidden\" name=\"currency_code\" value=\"$currency\" />\r\n<if condition=\"$show[\'recurring\']\">\r\n<input type=\"hidden\" name=\"a3\" value=\"$cost\" />\r\n<input type=\"hidden\" name=\"p3\" value=\"$timeinfo[length]\">\r\n<input type=\"hidden\" name=\"t3\" value=\"$timeinfo[units]\">\r\n<input type=\"hidden\" name=\"src\" value=\"1\">\r\n<input type=\"hidden\" name=\"sra\" value=\"1\">\r\n<else />\r\n<input type=\"hidden\" name=\"amount\" value=\"$cost\" />\r\n</if>\r\n<input type=\"hidden\" name=\"no_shipping\" value=\"$no_shipping\" />\r\n<input type=\"hidden\" name=\"shipping\" value=\"0.00\" />\r\n<input type=\"hidden\" name=\"return\" value=\"$vboptions[bburl]/$vboptions[forumhome].php\" />\r\n<input type=\"hidden\" name=\"cancel_return\" value=\"$vboptions[bburl]/$vboptions[forumhome].php\" />\r\n<input type=\"hidden\" name=\"notify_url\" value=\"$vboptions[bburl]/payment_gateway.php?method=paypal\" />\r\n<input type=\"hidden\" name=\"custom\" value=\"$userinfo[username]\" />\r\n<input type=\"hidden\" name=\"no_note\" value=\"1\" />\r\n<if condition=\"$show[\'notax\']\">\r\n<input type=\"hidden\" name=\"tax\" value=\"0.00\" />\r\n</if>', 'template', 1168864939, 'vBulletin Solutions', '3.6.6', 'vbulletin'),
(469, -1, 'subscription_payment_worldpay', '<input type=\\\"hidden\\\" name=\\\"desc\\\" value=\\\"$item\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"cost\\\" value=\\\"$cost\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"currency\\\" value=\\\"$currency\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"instId\\\" value=\\\"$settings[worldpay_instid]\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"cartId\\\" value=\\\"\" . construct_phrase(\"$vbphrase[x_subscription]\", \"$title\") . \"\\\" />', '<input type=\"hidden\" name=\"desc\" value=\"$item\" />\r\n<input type=\"hidden\" name=\"cost\" value=\"$cost\" />\r\n<input type=\"hidden\" name=\"currency\" value=\"$currency\" />\r\n<input type=\"hidden\" name=\"instId\" value=\"$settings[worldpay_instid]\" />\r\n<input type=\"hidden\" name=\"cartId\" value=\"<phrase 1=\"$title\">$vbphrase[x_subscription]</phrase>\" />', 'template', 1168864913, 'vBulletin Solutions', '3.6.6', 'vbulletin'),
(470, -1, 'tagbit', '<a href=\\\"tags.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"tag=$tag_url\\\">$tag</a>', '<a href=\"tags.php?$session[sessionurl]tag=$tag_url\">$tag</a>', 'template', 1196350380, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
