(484, -1, 'threadadmin_deleteposts', '<form action=\\\"inlinemod.php?t=$threadid&amp;p=$postid&amp;postids=$postids\\\" method=\\\"post\\\" name=\\\"vbform\\\">\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"t\\\" value=\\\"$threadid\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"p\\\" value=\\\"$postid\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"postids\\\" value=\\\"$postids\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"dodeleteposts\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"url\\\" value=\\\"$url\\\"  />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[delete_posts]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n		<fieldset class=\\\"fieldset\\\">\r\n			<legend>$vbphrase[deletion_options]</legend>\r\n\r\n			<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n\r\n			\".(($show[\'deleteoption\']) ? (\"<div class=\\\"fieldset\\\">$vbphrase[how_would_you_like_to_delete]</div>\") : (\"\")).\"\r\n			\".(($show[\'deleteposts\']) ? (\"\r\n			<div class=\\\"fieldset\\\">\r\n				<label for=\\\"rb_del_soft\\\"><input type=\\\"radio\\\" name=\\\"deletetype\\\" value=\\\"1\\\" id=\\\"rb_del_soft\\\" $checked[delete] />$vbphrase[soft_delete_leave_deleted_message]</label>\r\n				<br /><img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_misc]/tree_$stylevar[textdirection].gif\\\" alt=\\\"\\\" border=\\\"0\\\" /><label for=\\\"cb_keepattachments\\\"><input type=\\\"checkbox\\\" c