>\r\n							<if condition=\"$show[\'ips\']\">\r\n							<ol id=\"iplist\">$ips</ol>\r\n							<else />\r\n							<ol id=\"iplist\"><li class=\"shade\">$vbphrase[n_a]</li></ol>\r\n							</if>\r\n						</div>\r\n					</fieldset>\r\n				</td>\r\n			</tr>\r\n			</table>\r\n		</div>\r\n	</div>\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"submit\" class=\"button\" value=\"$vbphrase[proceed]\" accesskey=\"s\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>', 'template', 1229517663, 'vBulletin Solutions', '3.8.0 Release Candidate 2', 'vbulletin'),
(488, -1, 'threadadmin_easyspam_ban', '<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		$vbphrase[ban_user]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n\r\n	<div class=\\\"panel\\\">\r\n\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n\r\n			<fieldset class=\\\"fieldset\\\">\r\n				<legend>$vbphrase[ban_options]</legend>\r\n				<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n					<tr>\r\n						<td>$vbphrase[place_ban_users_in]</td>\r\n						<td><select name=\\\"usergroupid\\\">$ban_usergroups</select></td>\r\n					</tr>\r\n					<tr>\r\n						<td>$vbphrase[lift_ban]</td>\r\n						<td>\r\n							<select name=\\\"period\\\">\r\n								\".(($temp_ban_periods) ? (\"\r\n								<optgroup label=\\\"$vbphrase[temporary_ban_options]\\\">\r\n								$temp_ban_periods\r\n								</optgroup>\r\n								\") : (\"\")).\"\r\n								<optgroup label=\\\"$vbphrase[permanent_ban_options]\\\">\r\n								<option value=\\\"PERMANENT\\\" selected=\\\"selected\\\">$vbphrase[permanent_ban] - $vbphrase[never_lift_ban]</option>\r\n								</optgroup>\r\n							</select>\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td>$vbphrase[ban_reason]</td>\r\n						<td><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"reason\\\" value=\\\"\\\" size=\\\"45\\\" /></td>\r\n					</tr>\r\n				</table>\r\n			</fieldset>\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"dodeletespam\\\" />\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" name=\\\"sbutton\\\" id=\\\"{$editorid}_save\\\" value=\\\"$vbphrase[ban_user]\\\" accesskey=\\\"s\\\" />\r\n	</div>\r\n\r\n	</td>\r\n</tr>\r\n</table>', '<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		$vbphrase[ban_user]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n\r\n	<div class=\"panel\">\r\n\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n\r\n\r\n			<fieldset class=\"fieldset\">\r\n				<legend>$vbphrase[ban_options]</legend>\r\n				<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n					<tr>\r\n						<td>$vbphrase[place_ban_users_in]</td>\r\n						<td><select name=\"usergroupid\">$ban_usergroups</select></td>\r\n					</tr>\r\n					<tr>\r\n						<td>$vbphrase[lift_ban]</td>\r\n						<td>\r\n							<select name=\"period\">\r\n								<if condition=\"$temp_ban_periods\">\r\n								<optgroup label=\"$vbphrase[temporary_ban_options]\">\r\n								$temp_ban_periods\r\n								</optgroup>\r\n								</if>\r\n								<optgroup label=\"$vbphrase[permanent_ban_options]\">\r\n								<option value=\"PERMANENT\" selected=\"selected\">$vbphrase[permanent_ban] - $vbphrase[never_lift_ban]</option>\r\n								</optgroup>\r\n							</select>\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td>$vbphrase[ban_reason]</td>\r\n						<td><input type=\"text\" class=\"bginput\" name=\"reason\" value=\"\" size=\"45\" /></td>\r\n					</tr>\r\n				</table>\r\n			</fieldset>\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"hidden\" name=\"do\" value=\"dodeletespam\" />\r\n		<input type=\"submit\" class=\"button\" name=\"sbutton\" id=\"{$editorid}_save\" value=\"$vbphrase[ban_user]\" accesskey=\"s\" />\r\n	</div>\r\n\r\n	</td>\r\n</tr>\r\n</table>', 'template', 1220003853, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(489, -1, 'threadadmin_easyspam_confirm', '<form action=\\\"inlinemod.php?do=dodeletespam\\\" method=\\\"post\\\" name=\\\"vbform\\\">\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"url\\\" value=\\\"$url\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"dodeletespam\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"p\\\" value=\\\"$postid\\\" />\r\n\".(($type == \'thread\') ? (\"\r\n<input type=\\\"hidden\\\" name=\\\"threadids\\\" value=\\\"$threadids\\\" />\r\n\") : (\"\r\n<input type=\\\"hidden\\\" name=\\\"postids\\\" value=\\\"$postids\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"t\\\" value=\\\"$threadinfo[threadid]\\\" />\r\n\")).\"\r\n<!-- Spam Stuff -->\r\n<input type=\\\"hidden\\\" name=\\\"useraction\\\" value=\\\"$useraction\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"deleteother\\\" value=\\\"$deleteother\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"deletetype\\\" value=\\\"$deletetype\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"deletereason\\\" value=\\\"$deletereason\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"keepattachments\\\" value=\\\"$keepattachments\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"report\\\" value=\\\"$report\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"type\\\" value=\\\"$type\\\" />\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[spam_management]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n				<fieldset class=\\\"fieldset\\\">\r\n						<legend>$vbphrase[applying_punitive_action_to]</legend>\r\n						\".(($show[\'username_bits\']) ? (\"\r\n						<div style=\\\"padding:$stylevar[cellpadding]px\\\">\r\n							<ul class=\\\"inlinelist\\\">\r\n							$username_bits\r\n							</ul>\r\n						</div>\r\n						\".(($show[\'remove_info\']) ? (\"\r\n						<div style=\\\"padding:$stylevar[cellpadding]px\\\">\r\n							\" . construct_phrase(\"$vbphrase[spam_management_remove_posts_warning]\", \"50\") . \"\r\n						</div>\r\n						\") : (\"\")).\"\r\n						\") : (\"\r\n						<div style=\\\"padding:$stylevar[cellpadding]px\\\">\r\n							$vbphrase[no_punitive_action_users_are_guests]\r\n						</div>\r\n						\")).\"\r\n				</fieldset>\r\n\r\n		</div>\r\n	</div>\r\n\r\n	\".((!$show[\'punitive_action\']) ? (\"\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[proceed]\\\" accesskey=\\\"s\\\" />\r\n	</div>\r\n	\") : (\"\")).\"\r\n	</td>\r\n</tr>\r\n\r\n</table>\r\n\r\n\".(($show[\'punitive_action\']) ? (\"\r\n	<br />\r\n	$punitive_action\r\n\") : (\"\")).\"\r\n</form>', '<form action=\"inlinemod.php?do=dodeletespam\" method=\"post\" name=\"vbform\">\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n<input type=\"hidden\" name=\"url\" value=\"$url\" />\r\n<input type=\"hidden\" name=\"do\" value=\"dodeletespam\" />\r\n<input type=\"hidden\" name=\"p\" value=\"$postid\" />\r\n<if condition=\"$type == \'thread\'\">\r\n<input type=\"hidden\" name=\"threadids\" value=\"$threadids\" />\r\n<else />\r\n<input type=\"hidden\" name=\"postids\" value=\"$postids\" />\r\n<input type=\"hidden\" name=\"t\" value=\"$threadinfo[threadid]\" />\r\n</if>\r\n<!-- Spam Stuff -->\r\n<input type=\"hidden\" name=\"useraction\" value=\"$useraction\" />\r\n<input type=\"hidden\" name=\"deleteother\" value=\"$deleteother\" />\r\n<input type=\"hidden\" name=\"deletetype\" value=\"$deletetype\" />\r\n<input type=\"hidden\" name=\"deletereason\" value=\"$deletereason\" />\r\n<input type=\"hidden\" name=\"keepattachments\" value=\"$keepattachments\" />\r\n<input type=\"hidden\" name=\"report\" value=\"$report\" />\r\n<input type=\"hidden\" name=\"type\" value=\"$type\" />\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">$vbphrase[spam_management]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n				<fieldset class=\"fieldset\">\r\n						<legend>$vbphrase[applying_punitive_action_to]</legend>\r\n						<if condition=\"$show[\'username_bits\']\">\r\n						<div style=\"padding:$stylevar[cellpadding]px\">\r\n							<ul class=\"inlinelist\">\r\n							$username_bits\r\n							</ul>\r\n						</div>\r\n						<if condition=\"$show[\'remove_info\']\">\r\n						<div style=\"padding:$stylevar[cellpadding]px\">\r\n							<phrase 1=\"50\">$vbphrase[spam_management_remove_posts_warning]</phrase>\r\n						</div>\r\n						</if>\r\n						<else />\r\n						<div style=\"padding:$stylevar[cellpadding]px\">\r\n							$vbphrase[no_punitive_action_users_are_guests]\r\n						</div>\r\n						</if>\r\n				</fieldset>\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<if condition=\"!$show[\'punitive_action\']\">\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"submit\" class=\"button\" value=\"$vbphrase[proceed]\" accesskey=\"s\" />\r\n	</div>\r\n	</if>\r\n	</td>\r\n</tr>\r\n\r\n</table>\r\n\r\n<if condition=\"$show[\'punitive_action\']\">\r\n	<br />\r\n	$punitive_action\r\n</if>\r\n</form>', 'template', 1230039592, 'vBulletin Solutions', '3.8.0 Release Candidate 3', 'vbulletin'),
(490, -1, 'threadadmin_easyspam_headinclude', '<style type=\\\"text/css\\\" id=\\\"vbulletin_threadadmin_easyspam_css\\\">\r\n<!--\r\nul.spamoptions, #userlist, #iplist, ul.inlinelist { list-style-type:none; margin:0px; padding:0px; }\r\nul.spamoptions li, #userlist li, #iplist li { margin-top:$stylevar[cellpadding]px; }\r\n#userlist li div.userinfo { white-space:nowrap; }\r\ntd.leftcell { padding-$stylevar[right]:$stylevar[cellpadding]px; }\r\ntd.rightcell { padding-$stylevar[left]:$stylevar[cellpadding]px; }\r\n-->\r\n</style>', '<style type=\"text/css\" id=\"vbulletin_threadadmin_easyspam_css\">\r\n<!--\r\nul.spamoptions, #userlist, #iplist, ul.inlinelist { list-style-type:none; margin:0px; padding:0px; }\r\nul.spamoptions li, #userlist li, #iplist li { margin-top:$stylevar[cellpadding]px; }\r\n#userlist li div.userinfo { white-space:nowrap; }\r\ntd.leftcell { padding-$stylevar[right]:$stylevar[cellpadding]px; }\r\ntd.rightcell { padding-$stylevar[left]:$stylevar[cellpadding]px; }\r\n-->\r\n</style>', 'template', 1197387733, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
(491, -1, 'threadadmin_easyspam_infraction', '<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		\".(($foruminfo[forumid]) ? (\"<span class=\\\"smallfont\\\" style=\\\"float:$stylevar[right]\\\"><strong>$vbphrase[forum]</strong>: <a href=\\\"forumdisplay.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"f=$foruminfo[forumid]\\\">$foruminfo[title]</a></span>\") : (\"\")).\"\r\n		$vbphrase[user_infraction]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n\r\n	<div class=\\\"panel\\\">\r\n\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n\r\n			<fieldset class=\\\"fieldset\\\">\r\n				<legend>$vbphrase[infraction_level]</legend>\r\n				<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\" width=\\\"75%\\\" align=\\\"center\\\">\r\n				<tr>\r\n					<td width=\\\"45%\\\"><strong>$vbphrase[title]</strong></td>\r\n					\".(($show[\'count\']) ? (\"<td width=\\\"10%\\\" align=\\\"center\\\"><strong>$vbphrase[active]</strong></td>\") : (\"\")).\"\r\n					<td width=\\\"10%\\\" align=\\\"center\\\"><strong>$vbphrase[points]</strong></td>\r\n					<td width=\\\"15%\\\" align=\\\"center\\\"><strong>$vbphrase[expires]</strong></td>\r\n					<td width=\\\"10%\\\" nowrap=\\\"nowrap\\\"><strong>$vbphrase[warning]</strong></td>\r\n				</tr>\r\n				$infractionbits\r\n				\".(($show[\'custominfraction\']) ? (\"\r\n				<tr>\r\n					<td colspan=\\\"\".(($show[\'count\']) ? (\"5\") : (\"4\")).\"\\\"><strong>$vbphrase[custom_infraction]</strong></td>\r\n				</tr>\r\n				<tr>\r\n					<td colspan=\\\"\".(($show[\'count\']) ? (\"5\") : (\"4\")).\"\\\">\r\n					<table cellpadding=\\\"0\\\" cellspacing=\\\"1\\\" border=\\\"0\\\" align=\\\"center\\\" width=\\\"75%\\\">\r\n					<tr>\r\n						\".(($infractionbits) ? (\"<td valign=\\\"top\\\"><input type=\\\"radio\\\" name=\\\"infractionlevelid\\\" value=\\\"0\\\" $checked_inf tabindex=\\\"1\\\" /></td>\") : (\"\")).\"\r\n						<td>$vbphrase[reason]<br /><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"customreason\\\" value=\\\"$customreason\\\" size=\\\"40\\\" tabindex=\\\"1\\\" /></td>\r\n						<td valign=\\\"top\\\" align=\\\"center\\\" style=\\\"padding-$stylevar[left]: 5px\\\">$vbphrase[points]<br /><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"points\\\" value=\\\"$custompoints\\\" size=\\\"1\\\" style=\\\"width: 1.5em\\\" tabindex=\\\"1\\\" /></td>\r\n						<td valign=\\\"top\\\" style=\\\"padding-$stylevar[left]: 5px\\\" nowrap=\\\"nowrap\\\">$vbphrase[expires]<br /><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"expires\\\" value=\\\"$customexpires\\\" size=\\\"1\\\" style=\\\"width: 1.5em\\\" tabindex=\\\"1\\\" /> <select name=\\\"period\\\" tabindex=\\\"1\\\">\r\n							<option value=\\\"H\\\" $periodselected[H]>$vbphrase[hours]</option>\r\n							<option value=\\\"D\\\" $periodselected[D]>$vbphrase[days]</option>\r\n							<option value=\\\"M\\\" $periodselected[M]>$vbphrase[months]</option>\r\n							<option value=\\\"N\\\" $periodselected[N]>$vbphrase[never]</option>\r\n						</select></td>\r\n						<td width=\\\"100%\\\">&nbsp;</td>\r\n					</tr>\r\n					</table>\r\n					</td>\r\n				</tr>\r\n				\") : (\"\")).\"\r\n				</table>\r\n			</fieldset>\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" name=\\\"sbutton\\\" id=\\\"{$editorid}_save\\\" value=\\\"$vbphrase[give_infraction]\\\" accesskey=\\\"s\\\" tabindex=\\\"1\\\" />\r\n	</div>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n<br />\r\n\r\n$postpreview\r\n\r\n\".(($show[\'pm\']) ? (\"\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		$vbphrase[post_new_private_message]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n		<!-- note field -->\r\n		<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" class=\\\"fieldset\\\">\r\n		<tr>\r\n			<td class=\\\"smallfont\\\" colspan=\\\"3\\\">$vbphrase[administrative_note]</td>\r\n		</tr>\r\n		<tr>\r\n			<td><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"note\\\" value=\\\"$note\\\" size=\\\"50\\\" tabindex=\\\"1\\\" /></td>\r\n			<td>&nbsp;&nbsp;</td>\r\n			<td><img id=\\\"display_posticon\\\" src=\\\"$selectedicon[src]\\\" alt=\\\"$selectedicon[alt]\\\" /></td>\r\n		</tr>\r\n		</table>\r\n		<!-- / note field -->\r\n\r\n		<!-- message area -->\r\n		<div class=\\\"smallfont\\\">$vbphrase[message_to_user]</div>\r\n		$messagearea\r\n		<!-- / message area -->\r\n\r\n		$posticons\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" name=\\\"sbutton\\\" id=\\\"{$editorid}_save\\\" value=\\\"$vbphrase[give_infraction]\\\" accesskey=\\\"s\\\" tabindex=\\\"1\\\" />\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[preview_message]\\\" accesskey=\\\"r\\\" name=\\\"preview\\\" tabindex=\\\"1\\\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		<a name=\\\"options\\\" style=\\\"float:$stylevar[right]\\\" href=\\\"#top\\\" onclick=\\\"return toggle_collapse(\'newpost_options\')\\\"><img id=\\\"collapseimg_newpost_options\\\" src=\\\"$stylevar[imgdir_button]/collapse_tcat$vbcollapse[collapseimg_newpost_options].gif\\\" alt=\\\"\\\" border=\\\"0\\\" /></a>\r\n		$vbphrase[additional_options]\r\n	</td>\r\n</tr>\r\n<tbody id=\\\"collapseobj_newpost_options\\\" style=\\\"$vbcollapse[collapseobj_newpost_options]\\\">\r\n	<tr valign=\\\"top\\\">\r\n		<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n		<div class=\\\"panel\\\">\r\n			<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n				<fieldset class=\\\"fieldset\\\">\r\n					<legend>$vbphrase[miscellaneous_options]</legend>\r\n					<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n						\".(($show[\'trackpm\']) ? (\"<div><label for=\\\"cb_receipt\\\"><input type=\\\"checkbox\\\" name=\\\"receipt\\\" value=\\\"1\\\" id=\\\"cb_receipt\\\" $checked[receipt] />$vbphrase[request_receipt_for_message]</label></div>\") : (\"\")).\"\r\n						<div><label for=\\\"cb_savecopy\\\"><input type=\\\"checkbox\\\" name=\\\"savecopy\\\" value=\\\"1\\\" id=\\\"cb_savecopy\\\" tabindex=\\\"1\\\" $checked[savecopy] />\" . construct_phrase(\"$vbphrase[save_copy_in_sent_items_folder]\", \"private.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"folderid=-1\") . \"</label></div>\r\n						\".(($GLOBALS[\'vbulletin\']->userinfo[\'signature\']) ? (\"<div><label for=\\\"cb_signature\\\"><input type=\\\"checkbox\\\" name=\\\"signature\\\" value=\\\"1\\\" id=\\\"cb_signature\\\" tabindex=\\\"1\\\" $checked[signature] />$vbphrase[show_your_signature]</label></div>\") : (\"\")).\"\r\n						\".(($show[\'parseurl\']) ? (\"<div><label for=\\\"cb_parseurl\\\"><input type=\\\"checkbox\\\" name=\\\"parseurl\\\" value=\\\"1\\\" id=\\\"cb_parseurl\\\" tabindex=\\\"1\\\" $checked[parseurl] />$vbphrase[automatically_parse_links_in_text]</label></div>\") : (\"\")).\"\r\n						$disablesmiliesoption\r\n					</div>\r\n				</fieldset>\r\n\r\n			</div>\r\n		</div>\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n</table>\r\n\r\n<br />\r\n\r\n$forumrules\r\n\") : (\"\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		$vbphrase[send_new_message]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n		<!-- note field -->\r\n		<div class=\\\"fieldset\\\">\r\n			$vbphrase[administrative_note]<br />\r\n			<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"note\\\" value=\\\"$note\\\" size=\\\"50\\\" tabindex=\\\"1\\\" />\r\n		</div>\r\n		<!-- / note field -->\r\n\r\n		\".(($show[\'email\']) ? (\"\r\n			<!-- message area -->\r\n			<div class=\\\"fieldset\\\">\r\n				$vbphrase[message_to_user]<br />\r\n				<textarea name=\\\"message\\\" rows=\\\"10\\\" cols=\\\"50\\\" style=\\\"width:$stylevar[messagewidth]\\\">$postmessage</textarea>\r\n			</div>\r\n			<!-- / message area -->\r\n		\") : (\"\")).\"\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" name=\\\"sbutton\\\" id=\\\"{$editorid}_save\\\" value=\\\"$vbphrase[give_infraction]\\\" accesskey=\\\"s\\\" tabindex=\\\"1\\\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\")).\"', '<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		<if condition=\"$foruminfo[forumid]\"><span class=\"smallfont\" style=\"float:$stylevar[right]\"><strong>$vbphrase[forum]</strong>: <a href=\"forumdisplay.php?$session[sessionurl]f=$foruminfo[forumid]\">$foruminfo[title]</a></span></if>\r\n		$vbphrase[user_infraction]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n\r\n	<div class=\"panel\">\r\n\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n\r\n\r\n			<fieldset class=\"fieldset\">\r\n				<legend>$vbphrase[infraction_level]</legend>\r\n				<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\" width=\"75%\" align=\"center\">\r\n				<tr>\r\n					<td width=\"45%\"><strong>$vbphrase[title]</strong></td>\r\n					<if condition=\"$show[\'count\']\"><td width=\"10%\" align=\"center\"><strong>$vbphrase[active]</strong></td></if>\r\n					<td width=\"10%\" align=\"center\"><strong>$vbphrase[points]</strong></td>\r\n					<td width=\"15%\" align=\"center\"><strong>$vbphrase[expires]</strong></td>\r\n					<td width=\"10%\" nowrap=\"nowrap\"><strong>$vbphrase[warning]</strong></td>\r\n				</tr>\r\n				$infractionbits\r\n				<if condition=\"$show[\'custominfraction\']\">\r\n				<tr>\r\n					<td colspan=\"<if condition=\"$show[\'count\']\">5<else />4</if>\"><strong>$vbphrase[custom_infraction]</strong></td>\r\n				</tr>\r\n				<tr>\r\n					<td colspan=\"<if condition=\"$show[\'count\']\">5<else />4</if>\">\r\n					<table cellpadding=\"0\" cellspacing=\"1\" border=\"0\" align=\"center\" width=\"75%\">\r\n					<tr>\r\n						<if condition=\"$infractionbits\"><td valign=\"top\"><input type=\"radio\" name=\"infractionlevelid\" value=\"0\" $checked_inf tabindex=\"1\" /></td></if>\r\n						<td>$vbphrase[reason]<br /><input type=\"text\" class=\"bginput\" name=\"customreason\" value=\"$customreason\" size=\"40\" tabindex=\"1\" /></td>\r\n						<td valign=\"top\" align=\"center\" style=\"padding-$stylevar[left]: 5px\">$vbphrase[points]<br /><input type=\"text\" class=\"bginput\" name=\"points\" value=\"$custompoints\" size=\"1\" style=\"width: 1.5em\" tabindex=\"1\" /></td>\r\n						<td valign=\"top\" style=\"padding-$stylevar[left]: 5px\" nowrap=\"nowrap\">$vbphrase[expires]<br /><input type=\"text\" class=\"bginput\" name=\"expires\" value=\"$customexpires\" size=\"1\" style=\"width: 1.5em\" tabindex=\"1\" /> <select name=\"period\" tabindex=\"1\">\r\n							<option value=\"H\" $periodselected[H]>$vbphrase[hours]</option>\r\n							<option value=\"D\" $periodselected[D]>$vbphrase[days]</option>\r\n							<option value=\"M\" $periodselected[M]>$vbphrase[months]</option>\r\n							<option value=\"N\" $periodselected[N]>$vbphrase[never]</option>\r\n						</select></td>\r\n						<td width=\"100%\">&nbsp;</td>\r\n					</tr>\r\n					</table>\r\n					</td>\r\n				</tr>\r\n				</if>\r\n				</table>\r\n			</fieldset>\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"submit\" class=\"button\" name=\"sbutton\" id=\"{$editorid}_save\" value=\"$vbphrase[give_infraction]\" accesskey=\"s\" tabindex=\"1\" />\r\n	</div>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n<br />\r\n\r\n$postpreview\r\n\r\n<if condition=\"$show[\'pm\']\">\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		$vbphrase[post_new_private_message]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n\r\n		<!-- note field -->\r\n		<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" class=\"fieldset\">\r\n		<tr>\r\n			<td class=\"smallfont\" colspan=\"3\">$vbphrase[administrative_note]</td>\r\n		</tr>\r\n		<tr>\r\n			<td><input type=\"text\" class=\"bginput\" name=\"note\" value=\"$note\" size=\"50\" tabindex=\"1\" /></td>\r\n			<td>&nbsp;&nbsp;</td>\r\n			<td><img id=\"display_posticon\" src=\"$selectedicon[src]\" alt=\"$selectedicon[alt]\" /></td>\r\n		</tr>\r\n		</table>\r\n		<!-- / note field -->\r\n\r\n		<!-- message area -->\r\n		<div class=\"smallfont\">$vbphrase[message_to_user]</div>\r\n		$messagearea\r\n		<!-- / message area -->\r\n\r\n		$posticons\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"submit\" class=\"button\" name=\"sbutton\" id=\"{$editorid}_save\" value=\"$vbphrase[give_infraction]\" accesskey=\"s\" tabindex=\"1\" />\r\n		<input type=\"submit\" class=\"button\" value=\"$vbphrase[preview_message]\" accesskey=\"r\" name=\"preview\" tabindex=\"1\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		<a name=\"options\" style=\"float:$stylevar[right]\" href=\"#top\" onclick=\"return toggle_collapse(\'newpost_options\')\"><img id=\"collapseimg_newpost_options\" src=\"$stylevar[imgdir_button]/collapse_tcat$vbcollapse[collapseimg_newpost_options].gif\" alt=\"\" border=\"0\" /></a>\r\n		$vbphrase[additional_options]\r\n	</td>\r\n</tr>\r\n<tbody id=\"collapseobj_newpost_options\" style=\"$vbcollapse[collapseobj_newpost_options]\">\r\n	<tr valign=\"top\">\r\n		<td class=\"panelsurround\" align=\"center\">\r\n		<div class=\"panel\">\r\n			<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[miscellaneous_options]</legend>\r\n					<div style=\"padding:$stylevar[formspacer]px\">\r\n						<if condition=\"$show[\'trackpm\']\"><div><label for=\"cb_receipt\"><input type=\"checkbox\" name=\"receipt\" value=\"1\" id=\"cb_receipt\" $checked[receipt] />$vbphrase[request_receipt_for_message]</label></div></if>\r\n						<div><label for=\"cb_savecopy\"><input type=\"checkbox\" name=\"savecopy\" value=\"1\" id=\"cb_savecopy\" tabindex=\"1\" $checked[savecopy] /><phrase 1=\"private.php?$session[sessionurl]folderid=-1\">$vbphrase[save_copy_in_sent_items_folder]</phrase></label></div>\r\n						<if condition=\"$bbuserinfo[\'signature\']\"><div><label for=\"cb_signature\"><input type=\"checkbox\" name=\"signature\" value=\"1\" id=\"cb_signature\" tabindex=\"1\" $checked[signature] />$vbphrase[show_your_signature]</label></div></if>\r\n						<if condition=\"$show[\'parseurl\']\"><div><label for=\"cb_parseurl\"><input type=\"checkbox\" name=\"parseurl\" value=\"1\" id=\"cb_parseurl\" tabindex=\"1\" $checked[parseurl] />$vbphrase[automatically_parse_links_in_text]</label></div></if>\r\n						$disablesmiliesoption\r\n					</div>\r\n				</fieldset>\r\n\r\n			</div>\r\n		</div>\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n</table>\r\n\r\n<br />\r\n\r\n$forumrules\r\n<else />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		$vbphrase[send_new_message]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n\r\n		<!-- note field -->\r\n		<div class=\"fieldset\">\r\n			$vbphrase[administrative_note]<br />\r\n			<input type=\"text\" class=\"bginput\" name=\"note\" value=\"$note\" size=\"50\" tabindex=\"1\" />\r\n		</div>\r\n		<!-- / note field -->\r\n\r\n		<if condition=\"$show[\'email\']\">\r\n			<!-- message area -->\r\n			<div class=\"fieldset\">\r\n				$vbphrase[message_to_user]<br />\r\n				<textarea name=\"message\" rows=\"10\" cols=\"50\" style=\"width:$stylevar[messagewidth]\">$postmessage</textarea>\r\n			</div>\r\n			<!-- / message area -->\r\n		</if>\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"submit\" class=\"button\" name=\"sbutton\" id=\"{$editorid}_save\" value=\"$vbphrase[give_infraction]\" accesskey=\"s\" tabindex=\"1\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n</if>', 'template', 1206451841, 'vBulletin Solutions', '3.7.0 Release Candidate 2', 'vbulletin'),
(492, -1, 'threadadmin_easyspam_ipbit', '<li><a href=\\\"postings.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=getip&amp;ip=$ip\\\" target=\\\"ipinfo\\\">$ip</a><input type=\\\"hidden\\\" name=\\\"ip[]\\\" value=\\\"$ip_long\\\" /></li>', '<li><a href=\"postings.php?$session[sessionurl]do=getip&amp;ip=$ip\" target=\"ipinfo\">$ip</a><input type=\"hidden\" name=\"ip[]\" value=\"$ip_long\" /></li>', 'template', 1203935130, 'vBulletin Solutions', '3.7.0 Beta 6', 'vbulletin'),
(493, -1, 'threadadmin_easyspam_ip_option', '<li><input type=\\\"checkbox\\\" name=\\\"ip[]\\\" value=\\\"$ip\\\" checked=\\\"checked\\\" /><a href=\\\"postings.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=getip&amp;p=$postid\\\" target=\\\"ipinfo\\\">$ip</a></li>', '<li><input type=\"checkbox\" name=\"ip[]\" value=\"$ip\" checked=\"checked\" /><a href=\"postings.php?$session[sessionurl]do=getip&amp;p=$postid\" target=\"ipinfo\">$ip</a></li>', 'template', 1190373941, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
(494, -1, 'threadadmin_easyspam_skipped_prune', '<form action=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'forumhome\'] . \".php\\\" method=\\\"get\\\" onsubmit=\\\"window.location = \'$url\'; return false;\\\" name=\\\"vbform\\\">\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[spam_management]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n			<fieldset class=\\\"fieldset\\\">\r\n				<legend>$vbphrase[affected_users]</legend>\r\n				<div>$vbphrase[users_too_many_post_warning]</div>\r\n				<div class=\\\"shade\\\">$vbphrase[punitive_actions_still_performed]</div>\r\n				<ol id=\\\"userlist\\\">$users</ol>\r\n			</fieldset>\r\n		</div>\r\n	</div>\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[okay]\\\" accesskey=\\\"s\\\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>', '<form action=\"$vboptions[forumhome].php\" method=\"get\" onsubmit=\"window.location = \'$url\'; return false;\" name=\"vbform\">\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">$vbphrase[spam_management]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n			<fieldset class=\"fieldset\">\r\n				<legend>$vbphrase[affected_users]</legend>\r\