(495, -1, 'threadadmin_easyspam_userbit', '<li><a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$user[userid]\\\" target=\\\"userinfo\\\">$user[username]</a><input type=\\\"hidden\\\" name=\\\"userid[]\\\" value=\\\"$user[userid]\\\" /></li>', '<li><a href=\"member.php?$session[sessionurl]u=$user[userid]\" target=\"userinfo\">$user[username]</a><input type=\"hidden\" name=\"userid[]\" value=\"$user[userid]\" /></li>', 'template', 1191581142, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
(496, -1, 'threadadmin_easyspam_user_option', '<li>\r\n\".(($show[\'userid_checkbox\']) ? (\"\r\n	\".(($show[\'prevent_userselection\']) ? (\"\r\n		*\r\n	\") : (\"\r\n		<input type=\\\"checkbox\\\" name=\\\"userid[]\\\" value=\\\"$user[userid]\\\" checked=\\\"checked\\\" style=\\\"float:$stylevar[left]\\\" />\r\n	\")).\"\r\n\") : (\"\")).\"\r\n<a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$user[userid]\\\" target=\\\"spamuserinfo\\\">$user[username]</a> <div class=\\\"userinfo\\\">\" . construct_phrase(\"$vbphrase[registered_x_posts_y]\", \"$user[joindate_string]\", \"$user[post_count]\") . \"</div>\r\n</li>', '<li>\r\n<if condition=\"$show[\'userid_checkbox\']\">\r\n	<if condition=\"$show[\'prevent_userselection\']\">\r\n		*\r\n	<else />\r\n		<input type=\"checkbox\" name=\"userid[]\" value=\"$user[userid]\" checked=\"checked\" style=\"float:$stylevar[left]\" />\r\n	</if>\r\n</if>\r\n<a href=\"member.php?$session[sessionurl]u=$user[userid]\" target=\"spamuserinfo\">$user[username]</a> <div class=\"userinfo\"><phrase 1=\"$user[joindate_string]\" 2=\"$user[post_count]\">$vbphrase[registered_x_posts_y]</phrase></div>\r\n</li>', 'template', 1199287452, 'vBulletin Solutions', '3.7.0 Beta 4', 'vbulletin'),
(497, -1, 'threadadmin_editthread', '<form action=\\\"postings.php?do=updatethread&amp;t=$threadid\\\" method=\\\"post\\\" name=\\\"vbform\\\">\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"t\\\" value=\\\"$threadid\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"updatethread\\\" />\r\n\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[edit_thread]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"thead\\\">$vbphrase[title]: <span style=\\\"font-weight:normal\\\">$threadinfo[prefix_plain_html] $threadinfo[title]</span></td>\r\n</tr>\r\n\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n		<!-- subject field -->\r\n		<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" style=\\\"margin-bottom:$stylevar[formspacer]px\\\">\r\n		<tr>\r\n			<td class=\\\"smallfont\\\" colspan=\\\"3\\\">$vbphrase[title]:</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n				\".(($prefix_options) ? (\"\r\n					<select name=\\\"prefixid\\\" class=\\\"bginput\\\">\r\n						<option value=\\\"\\\">$vbphrase[no_prefix_meta]</option>\r\n						$prefix_options\r\n					</select>\r\n				\") : (\"\")).\"\r\n				<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"title\\\" value=\\\"$threadinfo[title]\\\" size=\\\"50\\\" maxlength=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'titlemaxchars\'] . \"\\\" tabindex=\\\"1\\\" />\r\n			</td>\r\n			<td>&nbsp;&nbsp;</td>\r\n			<td><img id=\\\"display_posticon\\\" src=\\\"$selectedicon[src]\\\" alt=\\\"$selectedicon[alt]\\\" /></td>\r\n		</tr>\r\n		</table>\r\n		<!-- / subject field -->\r\n\r\n		<div class=\\\"fieldset\\\">\r\n			$vbphrase[moderator_notes] / $vbphrase[thread_summary]:<br />\r\n			<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"notes\\\" value=\\\"$threadinfo[notes]\\\" size=\\\"50\\\" maxlength=\\\"250\\\" title=\\\"$vbphrase[optional]\\\" />\r\n		</div>\r\n\r\n		\".(($show[\'undeleteoption\']) ? (\"\r\n		<fieldset class=\\\"fieldset\\\">\r\n			<legend>$vbphrase[deletion_status]</legend>\r\n			<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n			<tr>\r\n				<td>$vbphrase[item_deleted_would_you_like_to]</td>\r\n			</tr>\r\n			<tr>\r\n				<td>\r\n					<div><label for=\\\"rb_threadstatus_0\\\"><input type=\\\"radio\\\" name=\\\"threadstatus\\\" value=\\\"0\\\" id=\\\"rb_threadstatus_0\\\" checked=\\\"checked\\\" />$vbphrase[leave_it_deleted]</label></div>\r\n					<div><label for=\\\"rb_threadstatus_1\\\"><input type=\\\"radio\\\" name=\\\"threadstatus\\\" value=\\\"1\\\" id=\\\"rb_threadstatus_1\\\" />$vbphrase[undelete_it_restore]</label></div>\r\n					\".(($show[\'removeoption\']) ? (\"\r\n					<div><label for=\\\"rb_threadstatus_2\\\"><input type=\\\"radio\\\" name=\\\"threadstatus\\\" value=\\\"2\\\" id=\\\"rb_threadstatus_2\\\" />$vbphrase[physically_remove]</label></div>\r\n					\") : (\"\")).\"\r\n				</td>\r\n			</tr>\r\n			<tr>\r\n				<td>\r\n					$vbphrase[reason_for_deletion]:<br />\r\n					<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"reason\\\" value=\\\"$threadinfo[del_reason]\\\" size=\\\"50\\\" maxlength=\\\"125\\\" />\r\n				</td>\r\n			</tr>\r\n			<tr>\r\n				<td>\r\n					<div><label for=\\\"cb_keepattachments\\\"><input type=\\\"checkbox\\\" name=\\\"keepattachments\\\" value=\\\"yes\\\" id=\\\"cb_keepattachments\\\" checked=\\\"checked\\\" />$vbphrase[keep_attachments]</label></div>\r\n				</td>\r\n			</tr>\r\n			</table>\r\n		</fieldset>\r\n		\") : (\"\")).\"\r\n\r\n		\".(($show[\'options\']) ? (\"\r\n		<fieldset class=\\\"fieldset\\\">\r\n			<legend>$vbphrase[options]</legend>\r\n			<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n				<div><label for=\\\"cb_open\\\"><input type=\\\"checkbox\\\" name=\\\"open\\\" value=\\\"yes\\\" id=\\\"cb_open\\\" $openchecked />$vbphrase[thread_is_open]</label></div>\r\n				<div><label for=\\\"cb_sticky\\\"><input type=\\\"checkbox\\\" name=\\\"sticky\\\" value=\\\"yes\\\" id=\\\"cb_sticky\\\" $stickychecked />$vbphrase[thread_is_sticky]</label></div>\r\n				\".(($show[\'moderateoption\']) ? (\"\r\n					<div><label for=\\\"cb_visible\\\"><input type=\\\"checkbox\\\" name=\\\"visible\\\" value=\\\"yes\\\" id=\\\"cb_visible\\\" $visiblechecked />$vbphrase[thread_is_visible]</label></div>\r\n				\") : (\"\")).\"\r\n			</div>\r\n		</fieldset>\r\n		\") : (\"\")).\"\r\n\r\n		\".(($show[\'redirect\']) ? (\"\r\n		<fieldset class=\\\"fieldset\\\">\r\n			<legend>$vbphrase[redirect]</legend>\r\n			<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n				\".(($show[\'expires\']) ? (\"<div>\" . construct_phrase(\"$vbphrase[this_redirect_expires_on_x_at_y]\", \"$threadinfo[expiredate]\", \"$threadinfo[expiretime]\") . \"</div>\") : (\"\")).\"\r\n				\".(($show[\'cpermanent\']) ? (\"<label for=\\\"rb_redirect_perm\\\"><input type=\\\"radio\\\" name=\\\"redirect\\\" value=\\\"perm\\\" id=\\\"rb_redirect_perm\\\" />$vbphrase[change_to_permanent_redirect]</label><br />\") : (\"\")).\"\r\n				\".(($show[\'cexpires\']) ? (\"\r\n					<label for=\\\"rb_redirect_expires\\\"><input type=\\\"checkbox\\\" name=\\\"redirect\\\" value=\\\"expires\\\" id=\\\"rb_redirect_expires\\\" />$vbphrase[change_to_expiring_redirect]</label><br />\r\n				\") : (\"\r\n					<label for=\\\"rb_redirect_expires\\\"><input type=\\\"radio\\\" name=\\\"redirect\\\" value=\\\"expires\\\" id=\\\"rb_redirect_expires\\\" />$vbphrase[change_expiring_time]</label><br />\r\n				\")).\"\r\n				<img style=\\\"padding-$stylevar[left]: 4px\\\" class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_misc]/tree_$stylevar[textdirection].gif\\\" alt=\\\"\\\" border=\\\"0\\\" /> $vbphrase[expires_in]\r\n				<select name=\\\"period\\\">\r\n					<option value=\\\"1\\\">1</option>\r\n					<option value=\\\"2\\\">2</option>\r\n					<option value=\\\"3\\\">3</option>\r\n					<option value=\\\"4\\\">4</option>\r\n					<option value=\\\"5\\\">5</option>\r\n					<option value=\\\"6\\\">6</option>\r\n					<option value=\\\"7\\\">7</option>\r\n					<option value=\\\"8\\\">8</option>\r\n					<option value=\\\"9\\\">9</option>\r\n					<option value=\\\"10\\\">10</option>\r\n				</select>\r\n\r\n				<select name=\\\"frame\\\">\r\n					<option value=\\\"h\\\">$vbphrase[hours]</option>\r\n					<option value=\\\"d\\\">$vbphrase[days]</option>\r\n					<option value=\\\"w\\\">$vbphrase[weeks]</option>\r\n					<option value=\\\"m\\\" selected=\\\"selected\\\">$vbphrase[months]</option>\r\n					<option value=\\\"y\\\">$vbphrase[years]</option>\r\n				</select>\r\n			</div>\r\n		</fieldset>\r\n		\") : (\"\")).\"\r\n\r\n		$posticons\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[save_changes]\\\" accesskey=\\\"s\\\" />\r\n		<input type=\\\"reset\\\" class=\\\"button\\\" value=\\\"$vbphrase[reset_fields]\\\" accesskey=\\\"r\\\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>\r\n\r\n\".(($show[\'modlog\']) ? (\"\r\n<br />\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\" colspan=\\\"5\\\">\r\n		<a style=\\\"float:$stylevar[right]\\\" href=\\\"#top\\\" onclick=\\\"return toggle_collapse(\'editthread_modlog\')\\\"><img id=\\\"collapseimg_editthread_modlog\\\" src=\\\"$stylevar[imgdir_button]/collapse_tcat$vbcollapse[collapseimg_editthread_modlog].gif\\\" alt=\\\"\\\" border=\\\"0\\\" /></a>\r\n		$vbphrase[moderator_log]\r\n	</td>\r\n</tr>\r\n<tbody id=\\\"collapseobj_editthread_modlog\\\" style=\\\"$vbcollapse[collapseobj_editthread_modlog]\\\">\r\n	<tr>\r\n		<td class=\\\"thead\\\" nowrap=\\\"nowrap\\\">$vbphrase[date]</td>\r\n		<td class=\\\"thead\\\" nowrap=\\\"nowrap\\\">$vbphrase[username]</td>\r\n		<td class=\\\"thead\\\" align=\\\"center\\\">$vbphrase[action]</td>\r\n		<td class=\\\"thead\\\" align=\\\"center\\\">$vbphrase[post]</td>\r\n		\".(($show[\'ipaddress\']) ? (\"\r\n		<td class=\\\"thead\\\" nowrap=\\\"nowrap\\\">$vbphrase[ip_address]</td>\r\n		\") : (\"\")).\"\r\n	</tr>\r\n	$logbits\r\n</tbody>\r\n</table>\r\n\") : (\"\")).\"', '<form action=\"postings.php?do=updatethread&amp;t=$threadid\" method=\"post\" name=\"vbform\">\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n<input type=\"hidden\" name=\"t\" value=\"$threadid\" />\r\n<input type=\"hidden\" name=\"do\" value=\"updatethread\" />\r\n\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">$vbphrase[edit_thread]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"thead\">$vbphrase[title]: <span style=\"font-weight:normal\">$threadinfo[prefix_plain_html] $threadinfo[title]</span></td>\r\n</tr>\r\n\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n\r\n		<!-- subject field -->\r\n		<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-bottom:$stylevar[formspacer]px\">\r\n		<tr>\r\n			<td class=\"smallfont\" colspan=\"3\">$vbphrase[title]:</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n				<if condition=\"$prefix_options\">\r\n					<select name=\"prefixid\" class=\"bginput\">\r\n						<option value=\"\">$vbphrase[no_prefix_meta]</option>\r\n						$prefix_options\r\n					</select>\r\n				</if>\r\n				<input type=\"text\" class=\"bginput\" name=\"title\" value=\"$threadinfo[title]\" size=\"50\" maxlength=\"$vboptions[titlemaxchars]\" tabindex=\"1\" />\r\n			</td>\r\n			<td>&nbsp;&nbsp;</td>\r\n			<td><img id=\"display_posticon\" src=\"$selectedicon[src]\" alt=\"$selectedicon[alt]\" /></td>\r\n		</tr>\r\n		</table>\r\n		<!-- / subject field -->\r\n\r\n		<div class=\"fieldset\">\r\n			$vbphrase[moderator_notes] / $vbphrase[thread_summary]:<br />\r\n			<input type=\"text\" class=\"bginput\" name=\"notes\" value=\"$threadinfo[notes]\" size=\"50\" maxlength=\"250\" title=\"$vbphrase[optional]\" />\r\n		</div>\r\n\r\n		<if condition=\"$show[\'undeleteoption\']\">\r\n		<fieldset class=\"fieldset\">\r\n			<legend>$vbphrase[deletion_status]</legend>\r\n			<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n			<tr>\r\n				<td>$vbphrase[item_deleted_would_you_like_to]</td>\r\n			</tr>\r\n			<tr>\r\n				<td>\r\n					<div><label for=\"rb_threadstatus_0\"><input type=\"radio\" name=\"threadstatus\" value=\"0\" id=\"rb_threadstatus_0\" checked=\"checked\" />$vbphrase[leave_it_deleted]</label></div>\r\n					<div><label for=\"rb_threadstatus_1\"><input type=\"radio\" name=\"threadstatus\" value=\"1\" id=\"rb_threadstatus_1\" />$vbphrase[undelete_it_restore]</label></div>\r\n					<if condition=\"$show[\'removeoption\']\">\r\n					<div><label for=\"rb_threadstatus_2\"><input type=\"radio\" name=\"threadstatus\" value=\"2\" id=\"rb_threadstatus_2\" />$vbphrase[physically_remove]</label></div>\r\n					</if>\r\n				</td>\r\n			</tr>\r\n			<tr>\r\n				<td>\r\n					$vbphrase[reason_for_deletion]:<br />\r\n					<input type=\"text\" class=\"bginput\" name=\"reason\" value=\"$threadinfo[del_reason]\" size=\"50\" maxlength=\"125\" />\r\n				</td>\r\n			</tr>\r\n			<tr>\r\n				<td>\r\n					<div><label for=\"cb_keepattachments\"><input type=\"checkbox\" name=\"keepattachments\" value=\"yes\" id=\"cb_keepattachments\" checked=\"checked\" />$vbphrase[keep_attachments]</label></div>\r\n				</td>\r\n			</tr>\r\n			</table>\r\n		</fieldset>\r\n		</if>\r\n\r\n		<if condition=\"$show[\'options\']\">\r\n		<fieldset class=\"fieldset\">\r\n			<legend>$vbphrase[options]</legend>\r\n			<div style=\"padding:$stylevar[formspacer]px\">\r\n				<div><label for=\"cb_open\"><input type=\"checkbox\" name=\"open\" value=\"yes\" id=\"cb_open\" $openchecked />$vbphrase[thread_is_open]</label></div>\r\n				<div><label for=\"cb_sticky\"><input type=\"checkbox\" name=\"sticky\" value=\"yes\" id=\"cb_sticky\" $stickychecked />$vbphrase[thread_is_sticky]</label></div>\r\n				<if condition=\"$show[\'moderateoption\']\">\r\n					<div><label for=\"cb_visible\"><input type=\"checkbox\" name=\"visible\" value=\"yes\" id=\"cb_visible\" $visiblechecked />$vbphrase[thread_is_visible]</label></div>\r\n				</if>\r\n			</div>\r\n		</fieldset>\r\n		</if>\r\n\r\n		<if condition=\"$show[\'redirect\']\">\r\n		<fieldset class=\"fieldset\">\r\n			<legend>$vbphrase[redirect]</legend>\r\n			<div style=\"padding:$stylevar[formspacer]px\">\r\n				<if condition=\"$show[\'expires\']\"><div><phrase 1=\"$threadinfo[expiredate]\" 2=\"$threadinfo[expiretime]\">$vbphrase[this_redirect_expires_on_x_at_y]</phrase></div></if>\r\n				<if condition=\"$show[\'cpermanent\']\"><label for=\"rb_redirect_perm\"><input type=\"radio\" name=\"redirect\" value=\"perm\" id=\"rb_redirect_perm\" />$vbphrase[change_to_permanent_redirect]</label><br /></if>\r\n				<if condition=\"$show[\'cexpires\']\">\r\n					<label for=\"rb_redirect_expires\"><input type=\"checkbox\" name=\"redirect\" value=\"expires\" id=\"rb_redirect_expires\" />$vbphrase[change_to_expiring_redirect]</label><br />\r\n				<else />\r\n					<label for=\"rb_redirect_expires\"><input type=\"radio\" name=\"redirect\" value=\"expires\" id=\"rb_redirect_expires\" />$vbphrase[change_expiring_time]</label><br />\r\n				</if>\r\n				<img style=\"padding-$stylevar[left]: 4px\" class=\"inlineimg\" src=\"$stylevar[imgdir_misc]/tree_$stylevar[textdirection].gif\" alt=\"\" border=\"0\" /> $vbphrase[expires_in]\r\n				<select name=\"period\">\r\n					<option value=\"1\">1</option>\r\n					<option value=\"2\">2</option>\r\n					<option value=\"3\">3</option>\r\n					<option value=\"4\">4</option>\r\n					<option value=\"5\">5</option>\r\n					<option value=\"6\">6</option>\r\n					<option value=\"7\">7</option>\r\n					<option value=\"8\">8</option>\r\n					<option value=\"9\">9</option>\r\n					<option value=\"10\">10</option>\r\n				</select>\r\n\r\n				<select name=\"frame\">\r\n					<option value=\"h\">$vbphrase[hours]</option>\r\n					<option value=\"d\">$vbphrase[days]</option>\r\n					<option value=\"w\">$vbphrase[weeks]</option>\r\n					<option value=\"m\" selected=\"selected\">$vbphrase[months]</option>\r\n					<option value=\"y\">$vbphrase[years]</option>\r\n				</select>\r\n			</div>\r\n		</fieldset>\r\n		</if>\r\n\r\n		$posticons\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"submit\" class=\"button\" value=\"$vbphrase[save_changes]\" accesskey=\"s\" />\r\n		<input type=\"reset\" class=\"button\" value=\"$vbphrase[reset_fields]\" accesskey=\"r\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>\r\n\r\n<if condition=\"$show[\'modlog\']\">\r\n<br />\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\" colspan=\"5\">\r\n		<a style=\"float:$stylevar[right]\" href=\"#top\" onclick=\"return toggle_collapse(\'editthread_modlog\')\"><img id=\"collapseimg_editthread_modlog\" src=\"$stylevar[imgdir_button]/collapse_tcat$vbcollapse[collapseimg_editthread_modlog].gif\" alt=\"\" border=\"0\" /></a>\r\n		$vbphrase[moderator_log]\r\n	</td>\r\n</tr>\r\n<tbody id=\"collapseobj_editthread_modlog\" style=\"$vbcollapse[collapseobj_editthread_modlog]\">\r\n	<tr>\r\n		<td class=\"thead\" nowrap=\"nowrap\">$vbphrase[date]</td>\r\n		<td class=\"thead\" nowrap=\"nowrap\">$vbphrase[username]</td>\r\n		<td class=\"thead\" align=\"center\">$vbphrase[action]</td>\r\n		<td class=\"thead\" align=\"center\">$vbphrase[post]</td>\r\n		<if condition=\"$show[\'ipaddress\']\">\r\n		<td class=\"thead\" nowrap=\"nowrap\">$vbphrase[ip_address]</td>\r\n		</if>\r\n	</tr>\r\n	$logbits\r\n</tbody>\r\n</table>\r\n</if>', 'template', 1208875813, 'vBulletin Solutions', '3.7.0 Release Candidate 4', 'vbulletin'),
(498, -1, 'threadadmin_imod_menu_post', '<table cellpadding=\\\"4\\\" cellspacing=\\\"1\\\" border=\\\"0\\\">\r\n\r\n<tr><td class=\\\"thead\\\">$vbphrase[from_this_page]</td></tr>\r\n<tr><td class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod.check_all(true)\\\">$vbphrase[select_all]</td></tr>\r\n<tr><td class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod.check_all(false)\\\">$vbphrase[deselect_all]</td></tr>\r\n<tr><td class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod.check_all(\'invert\')\\\">$vbphrase[invert_selection]</td></tr>\r\n\r\n<tr><td class=\\\"thead\\\"><img src=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'cleargifurl\'] . \"\\\" alt=\\\"\\\" width=\\\"1\\\" height=\\\"1\\\" /></td></tr>\r\n<tr><td class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod.check_all(true, 1)\\\">$vbphrase[select_unapproved_posts]</td></tr>\r\n<tr><td class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod.check_all(true, 2)\\\">$vbphrase[select_deleted_posts]</td></tr>\r\n<tr><td class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod.check_all(true, 4)\\\">$vbphrase[select_posts_with_attachments]</td></tr>\r\n<tr><td class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod.check_all(true, 8)\\\">$vbphrase[select_posts_from_guests]</td></tr>\r\n\r\n</table>', '<table cellpadding=\"4\" cellspacing=\"1\" border=\"0\">\r\n\r\n<tr><td class=\"thead\">$vbphrase[from_this_page]</td></tr>\r\n<tr><td class=\"vbmenu_option\" onclick=\"inlineMod.check_all(true)\">$vbphrase[select_all]</td></tr>\r\n<tr><td class=\"vbmenu_option\" onclick=\"inlineMod.check_all(false)\">$vbphrase[deselect_all]</td></tr>\r\n<tr><td class=\"vbmenu_option\" onclick=\"inlineMod.check_all(\'invert\')\">$vbphrase[invert_selection]</td></tr>\r\n\r\n<tr><td class=\"thead\"><img src=\"$vboptions[cleargifurl]\" alt=\"\" width=\"1\" height=\"1\" /></td></tr>\r\n<tr><td class=\"vbmenu_option\" onclick=\"inlineMod.check_all(true, 1)\">$vbphrase[select_unapproved_posts]</td></tr>\r\n<tr><td class=\"vbmenu_option\" onclick=\"inlineMod.check_all(true, 2)\">$vbphrase[select_deleted_posts]</td></tr>\r\n<tr><td class=\"vbmenu_option\" onclick=\"inlineMod.check_all(true, 4)\">$vbphrase[select_posts_with_attachments]</td></tr>\r\n<tr><td class=\"vbmenu_option\" onclick=\"inlineMod.check_all(true, 8)\">$vbphrase[select_posts_from_guests]</td></tr>\r\n\r\n</table>', 'template', 1194370354, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(499, -1, 'threadadmin_imod_menu_thread', '<table cellpadding=\\\"4\\\" cellspacing=\\\"1\\\" border=\\\"0\\\">\r\n\r\n<tr><td class=\\\"thead\\\">$vbphrase[from_this_page]</td></tr>\r\n<tr><td class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod.check_all(true)\\\">$vbphrase[select_all]</td></tr>\r\n<tr><td class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod.check_all(false)\\\">$vbphrase[deselect_all]</td></tr>\r\n<tr><td class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod.check_all(\'invert\')\\\">$vbphrase[invert_selection]</td></tr>\r\n\r\n<tr><td class=\\\"thead\\\"><img src=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'cleargifurl\'] . \"\\\" alt=\\\"\\\" width=\\\"1\\\" height=\\\"1\\\" /></td></tr>\r\n<tr><td class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod.check_all(true, 1)\\\">$vbphrase[select_closed_threads]</td></tr>\r\n<tr><td class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod.check_all(true, 2)\\\">$vbphrase[select_unapproved_threads]</td></tr>\r\n<tr><td class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod.check_all(true, 4)\\\">$vbphrase[select_deleted_threads]</td></tr>\r\n<tr><td class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod.check_all(true, 8)\\\">$vbphrase[select_sticky_threads]</td></tr>\r\n<tr><td class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod.check_all(true, 16)\\\">$vbphrase[select_threads_with_polls]</td></tr>\r\n<tr><td class=\\\"vbmenu_option\\\" onclick=\\\"inlineMod.check_all(true, 32)\\\">$vbphrase[select_threads_with_attachments]</td></tr>\r\n\r\n</table>', '<table cellpadding=\"4\" cellspacing=\"1\" border=\"0\">\r\n\r\n<tr><td class=\"thead\">$vbphrase[from_this_page]</td></tr>\r\n<tr><td class=\"vbmenu_option\" onclick=\"inlineMod.check_all(true)\">$vbphrase[select_all]</td></tr>\r\n<tr><td class=\"vbmenu_option\" onclick=\"inlineMod.check_all(false)\">$vbphrase[deselect_all]</td></tr>\r\n<tr><td class=\"vbmenu_option\" onclick=\"inlineMod.check_all(\'invert\')\">$vbphrase[invert_selection]</td></tr>\r\n\r\n<tr><td class=\"thead\"><img src=\"$vboptions[cleargifurl]\" alt=\"\" width=\"1\" height=\"1\" /></td></tr>\r\n<tr><td class=\"vbmenu_option\" onclick=\"inlineMod.check_all(true, 1)\">$vbphrase[select_closed_threads]</td></tr>\r\n<tr><td class=\"vbmenu_option\" onclick=\"inlineMod.check_all(true, 2)\">$vbphrase[select_unapproved_threads]</td></tr>\r\n<tr><td class=\"vbmenu_option\" onclick=\"inlineMod.check_all(true, 4)\">$vbphrase[select_deleted_threads]</td></tr>\r\n<tr><td class=\"vbmenu_option\" onclick=\"inlineMod.check_all(true, 8)\">$vbphrase[select_sticky_threads]</td></tr>\r\n<tr><td class=\"vbmenu_option\" onclick=\"inlineMod.check_all(true, 16)\">$vbphrase[select_threads_with_polls]</td></tr>\r\n<tr><td class=\"vbmenu_option\" onclick=\"inlineMod.check_all(true, 32)\">$vbphrase[select_threads_with_attachments]</td></tr>\r\n\r\n</table>', 'template', 1194370360, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
(500, -1, 'threadadmin_logbit', '<tr>\r\n	<td class=\\\"$bgclass\\\" nowrap=\\\"nowrap\\\">$log[dateline]</td>\r\n	<td class=\\\"$bgclass\\\" nowrap=\\\"nowrap\\\">$log[username]</td>\r\n	<td class=\\\"$bgclass\\\">$log[action]</td>\r\n	<td class=\\\"$bgclass\\\">\".(($log[\'postid\']) ? (\"<a href=\\\"showthread.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"p=$log[postid]\\\">$log[title]</a>\") : (\"&nbsp;\")).\"</td>\r\n	\".(($show[\'ipaddress\']) ? (\"<td class=\\\"$bgclass\\\">\".(($log[\'ipaddress\']) ? (\"<a href=\\\"postings.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=getip&amp;ip=$log[ipaddress]\\\">$log[ipaddress]</a>\") : (\"&nbsp;\")).\"</td>\") : (\"\")).\"\r\n</tr>', '<tr>\r\n	<td class=\"$bgclass\" nowrap=\"nowrap\">$log[dateline]</td>\r\n	<td class=\"$bgclass\" nowrap=\"nowrap\">$log[username]</td>\r\n	<td class=\"$bgclass\">$log[action]</td>\r\n	<td class=\"$bgclass\"><if condition=\"$log[\'postid\']\"><a href=\"showthread.php?$session[sessionurl]p=$log[postid]\">$log[title]</a><else />&nbsp;</if></td>\r\n	<if condition=\"$show[\'ipaddress\']\"><td class=\"$bgclass\"><if condition=\"$log[\'ipaddress\']\"><a href=\"postings.php?$session[sessionurl]do=getip&amp;ip=$log[ipaddress]\">$log[ipaddress]</a><else />&nbsp;</if></td></if>\r\n</tr>', 'template', 1116343439, 'vBulletin Solutions', '3.5.0 Beta 1', 'vbulletin'),
(501, -1, 'threadadmin_managepost', '<form action=\\\"postings.php?do=domanagepost&amp;t=$threadid&amp;p=$postid\\\" method=\\\"post\\\" name=\\\"vbform\\\">\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"t\\\" value=\\\"$threadid\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"domanagepost\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"p\\\" value=\\\"$postid\\\" />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[manage_post]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n		\".(($show[\'undeleteoption\']) ? (\"\r\n		<fieldset class=\\\"fieldset\\\">\r\n			<legend>$vbphrase[deletion_status]</legend>\r\n			<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n			<tr>\r\n				<td>$vbphrase[item_deleted_would_you_like_to]</td>\r\n			</tr>\r\n			<tr>\r\n				<td>\r\n					<div><label for=\\\"rb_poststatus_0\\\"><input type=\\\"radio\\\" name=\\\"poststatus\\\" value=\\\"0\\\" id=\\\"rb_poststatus_0\\\" checked=\\\"checked\\\" />$vbphrase[leave_it_deleted]</label></div>\r\n					<div><label for=\\\"rb_poststatus_1\\\"><input type=\\\"radio\\\" name=\\\"poststatus\\\" value=\\\"1\\\" id=\\\"rb_poststatus_1\\\" />$vbphrase[undelete_it_restore]</label></div>\r\n					\".(($show[\'harddelete\']) ? (\"<div><label for=\\\"rb_poststatus_2\\\"><input type=\\\"radio\\\" name=\\\"poststatus\\\" value=\\\"2\\\" id=\\\"rb_poststatus_2\\\" />$vbphrase[physically_remove]</label></div>\") : (\"\")).\"\r\n				</td>\r\n			</tr>\r\n			<tr>\r\n				<td>\r\n					$vbphrase[reason_for_deletion]:<br />\r\n					<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"reason\\\" value=\\\"$postinfo[del_reason]\\\" size=\\\"50\\\" maxlength=\\\"125\\\" />\r\n				</td>\r\n			</tr>\r\n			</table>\r\n		</fieldset>\r\n		\") : (\"\")).\"\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[save_changes]\\\" accesskey=\\\"s\\\" />\r\n		<input type=\\\"reset\\\" class=\\\"button\\\" value=\\\"$vbphrase[reset_fields]\\\" accesskey=\\\"r\\\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[info]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"alt1\\\">\r\n		<span style=\\\"float:$stylevar[right]\\\" class=\\\"smallfont\\\">\r\n			$postinfo[postdate] <span class=\\\"time\\\">$postinfo[posttime]</span>\r\n		</span>\r\n		<a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$postinfo[userid]\\\"><strong>$postinfo[username]</strong></a>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"alt2\\\">$postinfo[pagetext]</td>\r\n</tr>\r\n</table>\r\n\r\n</form>', '<form action=\"postings.php?do=domanagepost&amp;t=$threadid&amp;p=$postid\" method=\"post\" name=\"vbform\">\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n<input type=\"hidden\" name=\"t\" value=\"$threadid\" />\r\n<input type=\"hidden\" name=\"do\" value=\"domanagepost\" />\r\n<input type=\"hidden\" name=\"p\" value=\"$postid\" />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">$vbphrase[manage_post]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n\r\n		<if condition=\"$show[\'undeleteoption\']\">\r\n		<fieldset class=\"fieldset\">\r\n			<legend>$vbphrase[deletion_status]</legend>\r\n			<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n			<tr>\r\n				<td>$vbphrase[item_deleted_would_you_like_to]</td>\r\n			</tr>\r\n			<tr>\r\n				<td>\r\n					<div><label for=\"rb_poststatus_0\"><input type=\"radio\" name=\"poststatus\" value=\"0\" id=\"rb_poststatus_0\" checked=\"checked\" />$vbphrase[leave_it_deleted]</label></div>\r\n					<div><label for=\"rb_poststatus_1\"><input type=\"radio\" name=\"poststatus\" value=\"1\" id=\"rb_poststatus_1\" />$vbphrase[undelete_it_restore]</label></div>\r\n					<if condition=\"$show[\'harddelete\']\"><div><label for=\"rb_poststatus_2\"><input type=\"radio\" name=\"poststatus\" value=\"2\" id=\"rb_poststatus_2\" />$vbphrase[physically_remove]</label></div></if>\r\n				</td>\r\n			</tr>\r\n			<tr>\r\n				<td>\r\n					$vbphrase[reason_for_deletion]:<br />\r\n					<input type=\"text\" class=\"bginput\" name=\"reason\" value=\"$postinfo[del_reason]\" size=\"50\" maxlength=\"125\" />\r\n				</td>\r\n			</tr>\r\n			</table>\r\n		</fieldset>\r\n		</if>\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"submit\" class=\"button\" value=\"$vbphrase[save_changes]\" accesskey=\"s\" />\r\n		<input type=\"reset\" class=\"button\" value=\"$vbphrase[reset_fields]\" accesskey=\"r\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">$vbphrase[info]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"alt1\">\r\n		<span style=\"float:$stylevar[right]\" class=\"smallfont\">\r\n			$postinfo[postdate] <span class=\"time\">$postinfo[posttime]</span>\r\n		</span>\r\n		<a href=\"member.php?$session[sessionurl]u=$postinfo[userid]\"><strong>$postinfo[username]</strong></a>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"alt2\">$postinfo[pagetext]</td>\r\n</tr>\r\n</table>\r\n\r\n</form>', 'template', 1208875790, 'vBulletin Solutions', '3.7.0 Release Candidate 4', 'vbulletin'),
(502, -1, 'threadadmin_mergeposts', '<script type=\\\"text/javascript\\\">\r\n	<!--\r\n\r\n	    var threadtitles = Array();\r\n\r\n	    $js_titles\r\n\r\n	    function fetch_title(value)\r\n	    {\r\n	    fetch_object(\\\"thread_title\\\").innerHTML = threadtitles[value];\r\n	    }\r\n\r\n	    //-->\r\n</script>\r\n\r\n<form action=\\\"inlinemod.php?do=domergeposts&amp;t=$threadid&amp;postids=$postids\\\" method=\\\"post\\\" name=\\\"vbform\\\"\".((!is_browser(\'webtv\')) ? (\" onsubmit=\\\"return vB_Editor[\'$editorid\'].prepare_submit(0, \" . $GLOBALS[\'vbulletin\']->options[\'postminchars\'] . \")\\\"\") : (\"\")).\">\r\n\r\n	$errorreview\r\n\r\n	<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n		<tr>\r\n			<td class=\\\"tcat\\\">$vbphrase[merge_posts]</td>\r\n		</tr>\r\n		<tr>\r\n\r\n			<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n				<div class=\\\"panel\\\">\r\n					<div align=\\\"$stylevar[left]\\\" style=\\\"width:$stylevar[formwidth]\\\">\r\n\r\n						<fieldset class=\\\"fieldset\\\">\r\n							<legend>$vbphrase[options]</legend>\r\n\r\n							<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n\r\n								<div class=\\\"fieldset\\\" style=\\\"display:none\\\" id=\\\"threadbit\\\">\r\n									$vbphrase[thread]<br />\r\n									<div><strong id=\\\"thread_title\\\">$titlebit</strong></div>\r\n								</div>\r\n\r\n								<script type=\\\"text/javascript\\\">\r\n									<!--\r\n\r\n									    fetch_object(\\\"threadbit\\\").style.display = \\\"\\\";\r\n\r\n									    //-->\r\n								</script>\r\n\r\n								<!-- Date field -->\r\n								<div class=\\\"fieldset\\\">\r\n									$vbphrase[post]<br />\r\n									<select name=\\\"postid\\\" onchange=\\\"fetch_title(this.options[this.selectedIndex].value)\\\">\r\n										$postlistbit\r\n									</select>\r\n								</div>\r\n								<!-- / Date field -->\r\n\r\n								<!-- User name field -->\r\n								\".(($show[\'userchoice\']) ? (\"\r\n									<div class=\\\"fieldset\\\">\r\n										$vbphrase[username]<br />\r\n										<select name=\\\"username\\\">\r\n										$usernamebit\r\n									</select>\r\n								</div>\r\n							\") : (\"\")).\"\r\n							<!-- / user name field -->\r\n\r\n							<!-- subject field -->\r\n							<div class=\\\"fieldset\\\">\r\n								$vbphrase[title]<br />\r\n								<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"title\\\" size=\\\"50\\\" maxlength=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'titlemaxchars\'] . \"\\\" tabindex=\\\"1\\\" title=\\\"$vbphrase[optional]\\\" value=\\\"$edit[title]\\\" />\r\n							</div>\r\n							<!-- / subject field -->\r\n\r\n							<!-- edit reason field -->\r\n							<div class=\\\"fieldset\\\">\r\n								$vbphrase[reason]<br />\r\n								<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"reason\\\" value=\\\"$edit[reason]\\\" size=\\\"50\\\" maxlength=\\\"200\\\" tabindex=\\\"1\\\" title=\\\"$vbphrase[optional]\\\" />\r\n							</div>\r\n							<!-- / edit reason field -->\r\n\r\n						</div>\r\n\r\n					</fieldset>\r\n\r\n					<fieldset class=\\\"fieldset\\\">\r\n						<legend>$vbphrase[notes]</legend>\r\n						<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n							<div class=\\\"fieldset\\\">\" . construct_phrase(\"$vbphrase[merging_x_posts_from_y_threads_in_z_forums]\", \"$postcount\", \"$threadcount\", \"$forumcount\") . \"</div>\r\n							<div class=\\\"fieldset\\\">$vbphrase[you_must_have_the_required_permission]</div>\r\n						</div>\r\n					</fieldset>\r\n\r\n					<!-- message area -->\r\n					<div class=\\\"smallfont\\\">$vbphrase[message]</div>\r\n\r\n					$messagearea\r\n					<!-- / message area -->\r\n\r\n					<div align=\\\"center\\\" style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n						<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />