(505, -1, 'threadadmin_moveposts', '<form action=\\\"inlinemod.php?do=domoveposts&amp;t=$threadid&amp;postids=$postids\\\" method=\\\"post\\\" name=\\\"vbform\\\">\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"postids\\\" value=\\\"$postids\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"t\\\" value=\\\"$threadid\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"domoveposts\\\" />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[move_posts]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n			<fieldset class=\\\"fieldset\\\">\r\n				<legend>$vbphrase[move_posts_to_new_thread]</legend>\r\n				<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n				<tr valign=\\\"top\\\">\r\n					<td><input type=\\\"radio\\\" name=\\\"type\\\" value=\\\"0\\\" checked=\\\"checked\\\" /></td>\r\n					<td class=\\\"fieldset\\\">\r\n						<div><label for=\\\"destforumid\\\">$vbphrase[destination_forum]\r\n							<select name=\\\"destforumid\\\" id=\\\"destforumid\\\" style=\\\"display:block\\\">\r\n								$moveforumbits\r\n							</select>\r\n						</label></div>\r\n						<div style=\\\"margin-top:$stylevar[formspacer]px\\\"><label for=\\\"title_textbox\\\">$vbphrase[title]\r\n							<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"title\\\" id=\\\"title_textbox\\\" value=\\\"$post[title]\\\" size=\\\"50\\\" maxlength=\\\"\" . $GLOBALS[\'vbulletin\']->options