(521, -1, 'userfield_checkbox_option', '<td valign=\\\"top\\\"><label for=\\\"cb_cpf_{$profilefieldname}_$key\\\"><input type=\\\"checkbox\\\" name=\\\"userfield[$profilefieldname][]\\\" value=\\\"$key\\\" id=\\\"cb_cpf_{$profilefieldname}_$key\\\" $checked />$val</label></td>', '<td valign=\"top\"><label for=\"cb_cpf_{$profilefieldname}_$key\"><input type=\"checkbox\" name=\"userfield[$profilefieldname][]\" value=\"$key\" id=\"cb_cpf_{$profilefieldname}_$key\" $checked />$val</label></td>', 'template', 1199994839, 'vBulletin Solutions', '3.7.0 Beta 4', 'vbulletin'),
(522, -1, 'userfield_optional_input', '<tr>\r\n	\".(($show[\'optionspage\']) ? (\"\r\n	<td><span style=\\\"float:$stylevar[right]\\\"><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"userfield[$optionalname]\\\" value=\\\"$optional\\\" size=\\\"$profilefield[size]\\\" maxlength=\\\"$profilefield[maxlength]\\\" $tabindex /></span>$vbphrase[or_enter_your_choice_here]:</td>\r\n	\") : (\"\r\n	<td>$vbphrase[or_enter_your_choice_here]:<br /><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"userfield[$optionalname]\\\" value=\\\"$optional\\\" size=\\\"$profilefield[size]\\\" maxlength=\\\"$profilefield[maxlength]\\\" $tabindex /></td>\r\n	\")).\"\r\n</tr>', '<tr>\r\n	<if condition=\"$show[\'optionspage\']\">\r\n	<td><span style=\"float:$stylevar[right]\"><input type=\"text\" class=\"bginput\" name=\"userfield[$optionalname]\" value=\"$optional\" size=\"$profilefield[size]\" maxlength=\"$profilefield[maxlength]\" $tabindex /></span>$vbphrase[or_enter_your_choice_here]:</td>\r\n	<else />\r\n	<td>$vbphrase[or_enter_your_choice_here]:<br /><input type=\"text\" class=\"bginput\" name=\"userfield[$optionalname]\" value=\"$optional\" size=\"$profilefield[size]\" maxlength=\"$profilefield[maxlength]\" $tabindex /></td>\r\n	</if>\r\n</tr>', 'template', 1182960252, 'vBulletin Solutions', '3.6.8', 'vbulletin'),
(523, -1, 'userfield_radio', '<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n	<tr>\r\n		<td>$profilefield[description]</td>\r\n	</tr>\r\n	<tr>\r\n	<td>\r\n		<table cellpadding=\\\"2\\\" cellspacing=\\\"0\\\" border=\\\"0\\\">\r\n		$radiobits\r\n		</table>\r\n		<input type=\\\"hidden\\\" name=\\\"userfield[{$profilefieldname}_set]\\\" value=\\\"1\\\" />\r\n	</td>\r\n	</tr>\r\n	$optionalfield\r\n</table>', '<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\" width=\"100%\">\r\n	<tr>\r\n		<td>$profilefield[description]</td>\r\n	</tr>\r\n	<tr>\r\n	<td>\r\n		<table cellpadding=\"2\" cellspacing=\"0\" border=\"0\">\r\n		$radiobits\r\n		</table>\r\n		<input type=\"hidden\" name=\"userfield[{$profilefieldname}_set]\" value=\"1\" />\r\n	</td>\r\n	</tr>\r\n	$optionalfield\r\n</table>', 'template', 1199993518, 'vBulletin Solutions', '3.7.0 Beta 4', 'vbulletin'),
(524, -1, 'userfield_radio_option', '<td valign=\\\"top\\\"><label for=\\\"rb_cpf_{$profilefieldname}_$key\\\"><input type=\\\"radio\\\" name=\\\"userfield[$profilefieldname]\\\" value=\\\"$key\\\" id=\\\"rb_cpf_{$profilefieldname}_$key\\\" $checked />$val</label></td>', '<td valign=\"top\"><label for=\"rb_cpf_{$profilefieldname}_$key\"><input type=\"radio\" name=\"userfield[$profilefieldname]\" value=\"$key\" id=\"rb_cpf_{$profilefieldname}_$key\" $checked />$val</label></td>', 'template', 1199994902, 'vBulletin Solutions', '3.7.0 Beta 4', 'vbulletin'),
(525, -1, 'userfield_select', '<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n	<tr>\r\n		<td>$profilefield[description]</td>\r\n	</tr>\r\n	<tr>\r\n		<td>\r\n			\".(($show[\'optionspage\']) ? (\"<span style=\\\"float:$stylevar[right]\\\">\") : (\"\")).\"\r\n\r\n			<select name=\\\"userfield[$profilefieldname]\\\" id=\\\"csel_$profilefieldname\\\">\r\n				\".(($show[\'noemptyoption\']) ? (\"<option value=\\\"0\\\" $selected></option>\") : (\"\")).\"\r\n				$selectbits\r\n			</select>\r\n\r\n			\".(($show[\'optionspage\']) ? (\"</span><label for=\\\"csel_$profilefieldname\\\">$profilefield[title]:</label>\") : (\"\")).\"\r\n\r\n		<input type=\\\"hidden\\\" name=\\\"userfield[{$profilefieldname}_set]\\\" value=\\\"1\\\" />\r\n		</td>\r\n	</tr>\r\n	$optionalfield\r\n</table>', '<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\" width=\"100%\">\r\n	<tr>\r\n		<td>$profilefield[description]</td>\r\n	</tr>\r\n	<tr>\r\n		<td>\r\n			<if condition=\"$show[\'optionspage\']\"><span style=\"float:$stylevar[right]\"></if>\r\n\r\n			<select name=\"userfield[$profilefieldname]\" id=\"csel_$profilefieldname\">\r\n				<if condition=\"$show[\'noemptyoption\']\"><option value=\"0\" $selected></option></if>\r\n				$selectbits\r\n			</select>\r\n\r\n			<if condition=\"$show[\'optionspage\']\"></span><label for=\"csel_$profilefieldname\">$profilefield[title]:</label></if>\r\n\r\n		<input type=\"hidden\" name=\"userfield[{$profilefieldname}_set]\" value=\"1\" />\r\n		</td>\r\n	</tr>\r\n	$optionalfield\r\n</table>', 'template', 1193764575, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
(526, -1, 'userfield_select_multiple', '<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n	<tr>\r\n		<td>$profilefield[description]</td>\r\n	</tr>\r\n	<tr>\r\n		<td>\r\n			\".(($show[\'optionspage\']) ? (\"<span style=\\\"float:$stylevar[right]\\\">\") : (\"\")).\"\r\n\r\n			<select name=\\\"userfield[$profilefieldname][]\\\" id=\\\"csel_$profilefieldname\\\" size=\\\"$profilefield[height]\\\" multiple=\\\"multiple\\\">\r\n				$selectbits\r\n			</select>\r\n\r\n			\".(($show[\'optionspage\']) ? (\"</span><label for=\\\"sel_threadedmode\\\">$profilefield[title]:</label>\") : (\"\")).\"\r\n\r\n		<input type=\\\"hidden\\\" name=\\\"userfield[{$profilefieldname}_set]\\\" value=\\\"1\\\" />\r\n		</td>\r\n	</tr>\r\n	</table>\r\n\r\n', '<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\" width=\"100%\">\r\n	<tr>\r\n		<td>$profilefield[description]</td>\r\n	</tr>\r\n	<tr>\r\n		<td>\r\n			<if condition=\"$show[\'optionspage\']\"><span style=\"float:$stylevar[right]\"></if>\r\n\r\n			<select name=\"userfield[$profilefieldname][]\" id=\"csel_$profilefieldname\" size=\"$profilefield[height]\" multiple=\"multiple\">\r\n				$selectbits\r\n			</select>\r\n\r\n			<if condition=\"$show[\'optionspage\']\"></span><label for=\"sel_threadedmode\">$profilefield[title]:</label></if>\r\n\r\n		<input type=\"hidden\" name=\"userfield[{$profilefieldname}_set]\" value=\"1\" />\r\n		</td>\r\n	</tr>\r\n	</table>\r\n\r\n', 'template', 1193764609, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
(527, -1, 'userfield_select_option', '<option value=\\\"$key\\\" $selected>$val</option>', '<option value=\"$key\" $selected>$val</option>', 'template', 1068173170, 'vBulletin Solutions', '', 'vbulletin'),
(528, -1, 'userfield_textarea', '<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n	<tr>\r\n		<td>$profilefield[description]</td>\r\n	</tr>\r\n	<tr>\r\n	<td>\r\n		<textarea class=\\\"bginput\\\" name=\\\"userfield[$profilefieldname]\\\" id=\\\"cta_$profilefieldname\\\" rows=\\\"$profilefield[height]\\\" cols=\\\"$profilefield[size]\\\">\" . $GLOBALS[\'vbulletin\']->userinfo[$profilefieldname] . \"</textarea>\r\n\r\n		<input type=\\\"hidden\\\" name=\\\"userfield[{$profilefieldname}_set]\\\" value=\\\"1\\\" />\r\n	</td>\r\n	</tr>\r\n</table>', '<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\" width=\"100%\">\r\n	<tr>\r\n		<td>$profilefield[description]</td>\r\n	</tr>\r\n	<tr>\r\n	<td>\r\n		<textarea class=\"bginput\" name=\"userfield[$profilefieldname]\" id=\"cta_$profilefieldname\" rows=\"$profilefield[height]\" cols=\"$profilefield[size]\">$bbuserinfo[$profilefieldname]</textarea>\r\n\r\n		<input type=\"hidden\" name=\"userfield[{$profilefieldname}_set]\" value=\"1\" />\r\n	</td>\r\n	</tr>\r\n</table>', 'template', 1206451852, 'vBulletin Solutions', '3.7.0 Release Candidate 2', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(529, -1, 'userfield_textbox', '<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n	<tr>\r\n		<td>$profilefield[description]</td>\r\n	</tr>\r\n	<tr>\r\n	<td>\r\n		<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"userfield[$profilefieldname]\\\" id=\\\"ctb_$profilefieldname\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[$profilefieldname] . \"\\\" size=\\\"$profilefield[size]\\\" maxlength=\\\"$profilefield[maxlength]\\\" />\r\n\r\n		<input type=\\\"hidden\\\" name=\\\"userfield[{$profilefieldname}_set]\\\" value=\\\"1\\\" />\r\n	</td>\r\n	</tr>\r\n</table>', '<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\" width=\"100%\">\r\n	<tr>\r\n		<td>$profilefield[description]</td>\r\n	</tr>\r\n	<tr>\r\n	<td>\r\n		<input type=\"text\" class=\"bginput\" name=\"userfield[$profilefieldname]\" id=\"ctb_$profilefieldname\" value=\"$bbuserinfo[$profilefieldname]\" size=\"$profilefield[size]\" maxlength=\"$profilefield[maxlength]\" />\r\n\r\n		<input type=\"hidden\" name=\"userfield[{$profilefieldname}_set]\" value=\"1\" />\r\n	</td>\r\n	</tr>\r\n</table>', 'template', 1193764644, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
(530, -1, 'userfield_wrapper', '<fieldset class=\\\"fieldset\\\">\r\n	<legend>$profilefield[title]</legend>\r\n	$custom_field_holder\r\n</fieldset>', '<fieldset class=\"fieldset\">\r\n	<legend>$profilefield[title]</legend>\r\n	$custom_field_holder\r\n</fieldset>', 'template', 1193767296, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
(531, -1, 'userinfraction', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $vbphrase[user_infraction]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n\".(($show[\'pm\']) ? (\"\r\n<form action=\\\"infraction.php?do=update\\\" method=\\\"post\\\" name=\\\"vbform\\\"\".((!is_browser(\'webtv\')) ? (\" onsubmit=\\\"return vB_Editor[\'$editorid\'].prepare_submit(0, 0)\\\"\") : (\"\")).\">\r\n\") : (\"\r\n<form action=\\\"infraction.php?do=update\\\" method=\\\"post\\\">\r\n\")).\"\r\n\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		\".(($foruminfo[forumid]) ? (\"<span class=\\\"smallfont\\\" style=\\\"float:$stylevar[right]\\\"><strong>$vbphrase[forum]</strong>: <a href=\\\"forumdisplay.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"f=$foruminfo[forumid]\\\">$foruminfo[title]</a></span>\") : (\"\")).\"\r\n		$vbphrase[user_infraction]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n			<fieldset class=\\\"fieldset\\\">\r\n				<legend>$userinfo[username]</legend>\r\n				<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\" width=\\\"\".(($show[\'groups\'] OR $show[\'possiblegroups\']) ? (\"90%\") : (\"25%\")).\"\\\" align=\\\"center\\\">\r\n				<tr>\r\n					<td nowrap=\\\"nowrap\\\">$vbphrase[infractions_active_total]</td>\r\n					<td nowrap=\\\"nowrap\\\"><strong>$userinfo[infractions] / $totalinfractions</strong></td>\r\n				</tr>\r\n				<tr>\r\n					<td>$vbphrase[points]</td>\r\n					<td><strong>$userinfo[ipoints]</strong></td>\r\n				</tr>\r\n				<tr>\r\n					<td>$vbphrase[warnings]</td>\r\n					<td><strong>$userinfo[warnings]</strong></td>\r\n				</tr>\r\n				\".(($show[\'groups\']) ? (\"\r\n				<tr>\r\n					<td nowrap=\\\"nowrap\\\" width=\\\"40%\\\">$vbphrase[current_infraction_groups]</td>\r\n					<td><strong>$infractiongroups</strong></td>\r\n				</tr>\r\n				\") : (\"\")).\"\r\n				\".(($show[\'possiblegroups\']) ? (\"\r\n\r\n				<tr>\r\n					<td nowrap=\\\"nowrap\\\" width=\\\"40%\\\">$vbphrase[possible_infraction_groups]</td>\r\n					<td>\" . construct_phrase(\"$vbphrase[x_y_points]\", \"$firstgroup\", \"$firstpoints\") . \"</td>\r\n				</tr>\r\n				\".(($show[\'moregroups\']) ? (\"\r\n					$moregroups\r\n				\") : (\"\")).\"\r\n				\") : (\"\")).\"\r\n				</table>\r\n			</fieldset>\r\n		</div>\r\n\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n\r\n			<fieldset class=\\\"fieldset\\\">\r\n				<legend>$vbphrase[infraction_level]</legend>\r\n				<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\" width=\\\"75%\\\" align=\\\"center\\\">\r\n				<tr>\r\n					<td width=\\\"45%\\\"><strong>$vbphrase[title]</strong></td>\r\n					\".(($show[\'count\']) ? (\"<td width=\\\"10%\\\" align=\\\"center\\\"><strong>$vbphrase[active]</strong></td>\") : (\"\")).\"\r\n					<td width=\\\"10%\\\" align=\\\"center\\\"><strong>$vbphrase[points]</strong></td>\r\n					<td width=\\\"15%\\\" align=\\\"center\\\"><strong>$vbphrase[expires]</strong></td>\r\n					<td width=\\\"10%\\\" nowrap=\\\"nowrap\\\"><strong>$vbphrase[warning]</strong></td>\r\n				</tr>\r\n				$infractionbits\r\n				\".(($show[\'custominfraction\']) ? (\"\r\n				<tr>\r\n					<td colspan=\\\"\".(($show[\'count\']) ? (\"5\") : (\"4\")).\"\\\"><strong>$vbphrase[custom_infraction]</strong></td>\r\n				</tr>\r\n				<tr>\r\n					<td colspan=\\\"\".(($show[\'count\']) ? (\"5\") : (\"4\")).\"\\\">\r\n					<table cellpadding=\\\"0\\\" cellspacing=\\\"1\\\" border=\\\"0\\\" align=\\\"center\\\" width=\\\"75%\\\">\r\n					<tr>\r\n						\".(($infractionbits) ? (\"<td valign=\\\"top\\\"><input type=\\\"radio\\\" name=\\\"infractionlevelid\\\" value=\\\"0\\\" $checked_inf tabindex=\\\"1\\\" /></td>\") : (\"\")).\"\r\n						<td>$vbphrase[reason]<br /><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"customreason\\\" value=\\\"$customreason\\\" size=\\\"40\\\" tabindex=\\\"1\\\" /></td>\r\n						<td valign=\\\"top\\\" align=\\\"center\\\" style=\\\"padding-$stylevar[left]: 5px\\\">$vbphrase[points]<br /><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"points\\\" value=\\\"$custompoints\\\" size=\\\"1\\\" style=\\\"width: 1.5em\\\" tabindex=\\\"1\\\" /></td>\r\n						<td valign=\\\"top\\\" style=\\\"padding-$stylevar[left]: 5px\\\" nowrap=\\\"nowrap\\\">$vbphrase[expires]<br /><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"expires\\\" value=\\\"$customexpires\\\" size=\\\"1\\\" style=\\\"width: 1.5em\\\" tabindex=\\\"1\\\" /> <select name=\\\"period\\\" tabindex=\\\"1\\\">\r\n							<option value=\\\"H\\\" $periodselected[H]>$vbphrase[hours]</option>\r\n							<option value=\\\"D\\\" $periodselected[D]>$vbphrase[days]</option>\r\n							<option value=\\\"M\\\" $periodselected[M]>$vbphrase[months]</option>\r\n							<option value=\\\"N\\\" $periodselected[N]>$vbphrase[never]</option>\r\n						</select></td>\r\n						<td width=\\\"100%\\\">&nbsp;</td>\r\n					</tr>\r\n					</table>\r\n					</td>\r\n				</tr>\r\n				\") : (\"\")).\"\r\n				</table>\r\n			</fieldset>\r\n\r\n			\".(($show[\'banreason\']) ? (\"\r\n			<fieldset class=\\\"fieldset\\\">\r\n				<legend>$vbphrase[automatic_ban]</legend>\r\n\r\n				<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\" width=\\\"75%\\\" align=\\\"center\\\">\r\n				<tr>\r\n					<td width=\\\"45%\\\" nowrap=\\\"nowrap\\\"><strong>$vbphrase[ban_usergroup]</strong></td>\r\n					<td width=\\\"10%\\\" align=\\\"center\\\"><strong>$vbphrase[points]</strong></td>\r\n					<td width=\\\"10%\\\" align=\\\"center\\\"><strong>$vbphrase[infractions]</strong></td>\r\n					<td width=\\\"10%\\\" nowrap=\\\"nowrap\\\" align=\\\"$stylevar[right]\\\"><strong>$vbphrase[ban_period]</strong></td>\r\n				</tr>\r\n				$banbits\r\n				<tr>\r\n					<td colspan=\\\"4\\\"><strong>$vbphrase[ban_reason]</strong></td>\r\n				</tr>\r\n				<tr>\r\n					<td colspan=\\\"4\\\">\r\n						<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"banreason\\\" value=\\\"$banreason\\\" size=\\\"40\\\" tabindex=\\\"1\\\" />\r\n					</td>\r\n				</tr>\r\n				</table>\r\n\r\n			</fieldset>\r\n			\") : (\"\")).\"\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"hidden\\\" name=\\\"p\\\" value=\\\"$postinfo[postid]\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"u\\\" value=\\\"$userinfo[userid]\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"update\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"url\\\" value=\\\"$url\\\" />\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" name=\\\"sbutton\\\" id=\\\"{$editorid}_save\\\" value=\\\"$vbphrase[give_infraction]\\\" accesskey=\\\"s\\\" tabindex=\\\"1\\\" />\r\n	</div>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n<br />\r\n\r\n$postpreview\r\n\r\n\".(($show[\'pm\']) ? (\"\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		$vbphrase[post_new_private_message]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n		<!-- note field -->\r\n		<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" class=\\\"fieldset\\\">\r\n		<tr>\r\n			<td class=\\\"smallfont\\\" colspan=\\\"3\\\">$vbphrase[administrative_note]</td>\r\n		</tr>\r\n		<tr>\r\n			<td><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"note\\\" value=\\\"$note\\\" size=\\\"50\\\" tabindex=\\\"1\\\" /></td>\r\n			<td>&nbsp;&nbsp;</td>\r\n			<td><img id=\\\"display_posticon\\\" src=\\\"$selectedicon[src]\\\" alt=\\\"$selectedicon[alt]\\\" /></td>\r\n		</tr>\r\n		</table>\r\n		<!-- / note field -->\r\n\r\n		<!-- message area -->\r\n		<div class=\\\"smallfont\\\">$vbphrase[message_to_user]</div>\r\n		$messagearea\r\n		<!-- / message area -->\r\n\r\n		$posticons\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" name=\\\"sbutton\\\" id=\\\"{$editorid}_save\\\" value=\\\"$vbphrase[give_infraction]\\\" accesskey=\\\"s\\\" tabindex=\\\"1\\\" />\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[preview_message]\\\" accesskey=\\\"r\\\" name=\\\"preview\\\" tabindex=\\\"1\\\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		<a name=\\\"options\\\" style=\\\"float:$stylevar[right]\\\" href=\\\"#top\\\" onclick=\\\"return toggle_collapse(\'newpost_options\')\\\"><img id=\\\"collapseimg_newpost_options\\\" src=\\\"$stylevar[imgdir_button]/collapse_tcat$vbcollapse[collapseimg_newpost_options].gif\\\" alt=\\\"\\\" border=\\\"0\\\" /></a>\r\n		$vbphrase[additional_options]\r\n	</td>\r\n</tr>\r\n<tbody id=\\\"collapseobj_newpost_options\\\" style=\\\"$vbcollapse[collapseobj_newpost_options]\\\">\r\n	<tr valign=\\\"top\\\">\r\n		<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n		<div class=\\\"panel\\\">\r\n			<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n				<fieldset class=\\\"fieldset\\\">\r\n					<legend>$vbphrase[miscellaneous_options]</legend>\r\n					<div style=\\\"padding:$stylevar[formspacer]px\\\">\r\n						\".(($show[\'trackpm\']) ? (\"<div><label for=\\\"cb_receipt\\\"><input type=\\\"checkbox\\\" name=\\\"receipt\\\" value=\\\"1\\\" id=\\\"cb_receipt\\\" $checked[receipt] />$vbphrase[request_receipt_for_message]</label></div>\") : (\"\")).\"\r\n						<div><label for=\\\"cb_savecopy\\\"><input type=\\\"checkbox\\\" name=\\\"savecopy\\\" value=\\\"1\\\" id=\\\"cb_savecopy\\\" tabindex=\\\"1\\\" $checked[savecopy] />\" . construct_phrase(\"$vbphrase[save_copy_in_sent_items_folder]\", \"private.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"folderid=-1\") . \"</label></div>\r\n						\".(($GLOBALS[\'vbulletin\']->userinfo[\'signature\']) ? (\"<div><label for=\\\"cb_signature\\\"><input type=\\\"checkbox\\\" name=\\\"signature\\\" value=\\\"1\\\" id=\\\"cb_signature\\\" tabindex=\\\"1\\\" $checked[signature] />$vbphrase[show_your_signature]</label></div>\") : (\"\")).\"\r\n						\".(($show[\'parseurl\']) ? (\"<div><label for=\\\"cb_parseurl\\\"><input type=\\\"checkbox\\\" name=\\\"parseurl\\\" value=\\\"1\\\" id=\\\"cb_parseurl\\\" tabindex=\\\"1\\\" $checked[parseurl] />$vbphrase[automatically_parse_links_in_text]</label></div>\") : (\"\")).\"\r\n						$disablesmiliesoption\r\n					</div>\r\n				</fieldset>\r\n\r\n			</div>\r\n		</div>\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n</table>\r\n\r\n<br />\r\n\r\n$forumrules\r\n\") : (\"\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		$vbphrase[send_new_message]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n		<!-- note field -->\r\n		<div class=\\\"fieldset\\\">\r\n			$vbphrase[administrative_note]<br />\r\n			<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"note\\\" value=\\\"$note\\\" size=\\\"50\\\" tabindex=\\\"1\\\" />\r\n		</div>\r\n		<!-- / note field -->\r\n\r\n		\".(($show[\'email\']) ? (\"\r\n			<!-- message area -->\r\n			<div class=\\\"fieldset\\\">\r\n				$vbphrase[message_to_user]<br />\r\n				<textarea name=\\\"message\\\" rows=\\\"10\\\" cols=\\\"50\\\" style=\\\"width:$stylevar[messagewidth]\\\">$postmessage</textarea>\r\n			</div>\r\n			<!-- / message area -->\r\n		\") : (\"\")).\"\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" name=\\\"sbutton\\\" id=\\\"{$editorid}_save\\\" value=\\\"$vbphrase[give_infraction]\\\" accesskey=\\\"s\\\" tabindex=\\\"1\\\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\")).\"\r\n\r\n</form>\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n<title>$vboptions[bbtitle] - $vbphrase[user_infraction]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<if condition=\"$show[\'pm\']\">\r\n<form action=\"infraction.php?do=update\" method=\"post\" name=\"vbform\"<if condition=\"!is_browser(\'webtv\')\"> onsubmit=\"return vB_Editor[\'$editorid\'].prepare_submit(0, 0)\"</if>>\r\n<else />\r\n<form action=\"infraction.php?do=update\" method=\"post\">\r\n</if>\r\n\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		<if condition=\"$foruminfo[forumid]\"><span class=\"smallfont\" style=\"float:$stylevar[right]\"><strong>$vbphrase[forum]</strong>: <a href=\"forumdisplay.php?$session[sessionurl]f=$foruminfo[forumid]\">$foruminfo[title]</a></span></if>\r\n		$vbphrase[user_infraction]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n\r\n			<fieldset class=\"fieldset\">\r\n				<legend>$userinfo[username]</legend>\r\n				<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\" width=\"<if condition=\"$show[\'groups\'] OR $show[\'possiblegroups\']\">90%<else />25%</if>\" align=\"center\">\r\n				<tr>\r\n					<td nowrap=\"nowrap\">$vbphrase[infractions_active_total]</td>\r\n					<td nowrap=\"nowrap\"><strong>$userinfo[infractions] / $totalinfractions</strong></td>\r\n				</tr>\r\n				<tr>\r\n					<td>$vbphrase[points]</td>\r\n					<td><strong>$userinfo[ipoints]</strong></td>\r\n				</tr>\r\n				<tr>\r\n					<td>$vbphrase[warnings]</td>\r\n					<td><strong>$userinfo[warnings]</strong></td>\r\n				</tr>\r\n				<if condition=\"$show[\'groups\']\">\r\n				<tr>\r\n					<td nowrap=\"nowrap\" width=\"40%\">$vbphrase[current_infraction_groups]</td>\r\n					<td><strong>$infractiongroups</strong></td>\r\n				</tr>\r\n				</if>\r\n				<if condition=\"$show[\'possiblegroups\']\">\r\n\r\n				<tr>\r\n					<td nowrap=\"nowrap\" width=\"40%\">$vbphrase[possible_infraction_groups]</td>\r\n					<td><phrase 1=\"$firstgroup\" 2=\"$firstpoints\">$vbphrase[x_y_points]</phrase></td>\r\n				</tr>\r\n				<if condition=\"$show[\'moregroups\']\">\r\n					$moregroups\r\n				</if>\r\n				</if>\r\n				</table>\r\n			</fieldset>\r\n		</div>\r\n\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n\r\n\r\n			<fieldset class=\"fieldset\">\r\n				<legend>$vbphrase[infraction_level]</legend>\r\n				<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\" width=\"75%\" align=\"center\">\r\n				<tr>\r\n					<td width=\"45%\"><strong>$vbphrase[title]</strong></td>\r\n					<if condition=\"$show[\'count\']\"><td width=\"10%\" align=\"center\"><strong>$vbphrase[active]</strong></td></if>\r\n					<td width=\"10%\" align=\"center\"><strong>$vbphrase[points]</strong></td>\r\n					<td width=\"15%\" align=\"center\"><strong>$vbphrase[expires]</strong></td>\r\n					<td width=\"10%\" nowrap=\"nowrap\"><strong>$vbphrase[warning]</strong></td>\r\n				</tr>\r\n				$infractionbits\r\n				<if condition=\"$show[\'custominfraction\']\">\r\n				<tr>\r\n					<td colspan=\"<if condition=\"$show[\'count\']\">5<else />4</if>\"><strong>$vbphrase[custom_infraction]</strong></td>\r\n				</tr>\r\n				<tr>\r\n					<td colspan=\"<if condition=\"$show[\'count\']\">5<else />4</if>\">\r\n					<table cellpadding=\"0\" cellspacing=\"1\" border=\"0\" align=\"center\" width=\"75%\">\r\n					<tr>\r\n						<if condition=\"$infractionbits\"><td valign=\"top\"><input type=\"radio\" name=\"infractionlevelid\" value=\"0\" $checked_inf tabindex=\"1\" /></td></if>\r\n						<td>$vbphrase[reason]<br /><input type=\"text\" class=\"bginput\" name=\"customreason\" value=\"$customreason\" size=\"40\" tabindex=\"1\" /></td>\r\n						<td valign=\"top\" align=\"center\" style=\"padding-$stylevar[left]: 5px\">$vbphrase[points]<br /><input type=\"text\" class=\"bginput\" name=\"points\" value=\"$custompoints\" size=\"1\" style=\"width: 1.5em\" tabindex=\"1\" /></td>\r\n						<td valign=\"top\" style=\"padding-$stylevar[left]: 5px\" nowrap=\"nowrap\">$vbphrase[expires]<br /><input type=\"text\" class=\"bginput\" name=\"expires\" value=\"$customexpires\" size=\"1\" style=\"width: 1.5em\" tabindex=\"1\" /> <select name=\"period\" tabindex=\"1\">\r\n							<option value=\"H\" $periodselected[H]>$vbphrase[hours]</option>\r\n							<option value=\"D\" $periodselected[D]>$vbphrase[days]</option>\r\n							<option value=\"M\" $periodselected[M]>$vbphrase[months]</option>\r\n							<option value=\"N\" $periodselected[N]>$vbphrase[never]</option>\r\n						</select></td>\r\n						<td width=\"100%\">&nbsp;</td>\r\n					</tr>\r\n					</table>\r\n					</td>\r\n				</tr>\r\n				</if>\r\n				</table>\r\n			</fieldset>\r\n\r\n			<if condition=\"$show[\'banreason\']\">\r\n			<fieldset class=\"fieldset\">\r\n				<legend>$vbphrase[automatic_ban]</legend>\r\n\r\n				<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\" width=\"75%\" align=\"center\">\r\n				<tr>\r\n					<td width=\"45%\" nowrap=\"nowrap\"><strong>$vbphrase[ban_usergroup]</strong></td>\r\n					<td width=\"10%\" align=\"center\"><strong>$vbphrase[points]</strong></td>\r\n					<td width=\"10%\" align=\"center\"><strong>$vbphrase[infractions]</strong></td>\r\n					<td width=\"10%\" nowrap=\"nowrap\" align=\"$stylevar[right]\"><strong>$vbphrase[ban_period]</strong></td>\r\n				</tr>\r\n				$banbits\r\n				<tr>\r\n					<td colspan=\"4\"><strong>$vbphrase[ban_reason]</strong></td>\r\n				</tr>\r\n				<tr>\r\n					<td colspan=\"4\">\r\n						<input type=\"text\" class=\"bginput\" name=\"banreason\" value=\"$banreason\" size=\"40\" tabindex=\"1\" />\r\n					</td>\r\n				</tr>\r\n				</table>\r\n\r\n			</fieldset>\r\n			</if>\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"hidden\" name=\"p\" value=\"$postinfo[postid]\" />\r\n		<input type=\"hidden\" name=\"u\" value=\"$userinfo[userid]\" />\r\n		<input type=\"hidden\" name=\"do\" value=\"update\" />\r\n		<input type=\"hidden\" name=\"url\" value=\"$url\" />\r\n		<input type=\"submit\" class=\"button\" name=\"sbutton\" id=\"{$editorid}_save\" value=\"$vbphrase[give_infraction]\" accesskey=\"s\" tabindex=\"1\" />\r\n	</div>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n<br />\r\n\r\n$postpreview\r\n\r\n<if condition=\"$show[\'pm\']\">\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		$vbphrase[post_new_private_message]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n\r\n		<!-- note field -->\r\n		<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" class=\"fieldset\">\r\n		<tr>\r\n			<td class=\"smallfont\" colspan=\"3\">$vbphrase[administrative_note]</td>\r\n		</tr>\r\n		<tr>\r\n			<td><input type=\"text\" class=\"bginput\" name=\"note\" value=\"$note\" size=\"50\" tabindex=\"1\" /></td>\r\n			<td>&nbsp;&nbsp;</td>\r\n			<td><img id=\"display_posticon\" src=\"$selectedicon[src]\" alt=\"$selectedicon[alt]\" /></td>\r\n		</tr>\r\n		</table>\r\n		<!-- / note field -->\r\n\r\n		<!-- message area -->\r\n		<div class=\"smallfont\">$vbphrase[message_to_user]</div>\r\n		$messagearea\r\n		<!-- / message area -->\r\n\r\n		$posticons\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"submit\" class=\"button\" name=\"sbutton\" id=\"{$editorid}_save\" value=\"$vbphrase[give_infraction]\" accesskey=\"s\" tabindex=\"1\" />\r\n		<input type=\"submit\" class=\"button\" value=\"$vbphrase[preview_message]\" accesskey=\"r\" name=\"preview\" tabindex=\"1\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		<a name=\"options\" style=\"float:$stylevar[right]\" href=\"#top\" onclick=\"return toggle_collapse(\'newpost_options\')\"><img id=\"collapseimg_newpost_options\" src=\"$stylevar[imgdir_button]/collapse_tcat$vbcollapse[collapseimg_newpost_options].gif\" alt=\"\" border=\"0\" /></a>\r\n		$vbphrase[additional_options]\r\n	</td>\r\n</tr>\r\n<tbody id=\"collapseobj_newpost_options\" style=\"$vbcollapse[collapseobj_newpost_options]\">\r\n	<tr valign=\"top\">\r\n		<td class=\"panelsurround\" align=\"center\">\r\n		<div class=\"panel\">\r\n			<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n\r\n				<fieldset class=\"fieldset\">\r\n					<legend>$vbphrase[miscellaneous_options]</legend>\r\n					<div style=\"padding:$stylevar[formspacer]px\">\r\n						<if condition=\"$show[\'trackpm\']\"><div><label for=\"cb_receipt\"><input type=\"checkbox\" name=\"receipt\" value=\"1\" id=\"cb_receipt\" $checked[receipt] />$vbphrase[request_receipt_for_message]</label></div></if>\r\n						<div><label for=\"cb_savecopy\"><input type=\"checkbox\" name=\"savecopy\" value=\"1\" id=\"cb_savecopy\" tabindex=\"1\" $checked[savecopy] /><phrase 1=\"private.php?$session[sessionurl]folderid=-1\">$vbphrase[save_copy_in_sent_items_folder]</phrase></label></div>\r\n						<if condition=\"$bbuserinfo[\'signature\']\"><div><label for=\"cb_signature\"><input type=\"checkbox\" name=\"signature\" value=\"1\" id=\"cb_signature\" tabindex=\"1\" $checked[signature] />$vbphrase[show_your_signature]</label></div></if>\r\n						<if condition=\"$show[\'parseurl\']\"><div><label for=\"cb_parseurl\"><input type=\"checkbox\" name=\"parseurl\" value=\"1\" id=\"cb_parseurl\" tabindex=\"1\" $checked[parseurl] />$vbphrase[automatically_parse_links_in_text]</label></div></if>\r\n						$disablesmiliesoption\r\n					</div>\r\n				</fieldset>\r\n\r\n			</div>\r\n		</div>\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n</table>\r\n\r\n<br />\r\n\r\n$forumrules\r\n<else />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		$vbphrase[send_new_message]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n\r\n		<!-- note field -->\r\n		<div class=\"fieldset\">\r\n			$vbphrase[administrative_note]<br />\r\n			<input type=\"text\" class=\"bginput\" name=\"note\" value=\"$note\" size=\"50\" tabindex=\"1\" />\r\n		</div>\r\n		<!-- / note field -->\r\n\r\n		<if condition=\"$show[\'email\']\">\r\n			<!-- message area -->\r\n			<div class=\"fieldset\">\r\n				$vbphrase[message_to_user]<br />\r\n				<textarea name=\"message\" rows=\"10\" cols=\"50\" style=\"width:$stylevar[messagewidth]\">$postmessage</textarea>\r\n			</div>\r\n			<!-- / message area -->\r\n		</if>\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"submit\" class=\"button\" name=\"sbutton\" id=\"{$editorid}_save\" value=\"$vbphrase[give_infraction]\" accesskey=\"s\" tabindex=\"1\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n</if>\r\n\r\n</form>\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', 'template', 1208875510, 'vBulletin Solutions', '3.7.0 Release Candidate 4', 'vbulletin'),
(532, -1, 'userinfractionbit', '<tr align=\\\"center\\\">\r\n	<td align=\\\"$stylevar[left]\\\"><label for=\\\"il_$infraction[infractionlevelid]\\\"><input id=\\\"il_$infraction[infractionlevelid]\\\" type=\\\"radio\\\" name=\\\"infractionlevelid\\\" value=\\\"$infraction[infractionlevelid]\\\" $checked_inf tabindex=\\\"1\\\" />$title</label></td>\r\n	\".(($show[\'count\']) ? (\"<td>$count</td>\") : (\"\")).\"\r\n	<td>$infraction[points]</td>\r\n	<td>$expires</td>\r\n	<td align=\\\"$stylevar[left]\\\">\".(($show[\'warning\']) ? (\"<input type=\\\"checkbox\\\" name=\\\"warning[$infraction[infractionlevelid]]\\\" value=\\\"1\\\" $checked_warn tabindex=\\\"1\\\" />\") : (\"&nbsp;\")).\"</td>\r\n</tr>', '<tr align=\"center\">\r\n	<td align=\"$stylevar[left]\"><label for=\"il_$infraction[infractionlevelid]\"><input id=\"il_$infraction[infractionlevelid]\" type=\"radio\" name=\"infractionlevelid\" value=\"$infraction[infractionlevelid]\" $checked_inf tabindex=\"1\" />$title</label></td>\r\n	<if condition=\"$show[\'count\']\"><td>$count</td></if>\r\n	<td>$infraction[points]</td>\r\n	<td>$expires</td>\r\n	<td align=\"$stylevar[left]\"><if condition=\"$show[\'warning\']\"><input type=\"checkbox\" name=\"warning[$infraction[infractionlevelid]]\" value=\"1\" $checked_warn tabindex=\"1\" /><else />&nbsp;</if></td>\r\n</tr>', 'template', 1155937480, 'vBulletin Solutions', '3.6.1', 'vbulletin'),
