le>\r\n</if>\r\n\r\n</form>\r\n\r\n<if condition=\"$messagebits\">\r\n<br />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\">\r\n<thead>\r\n	<tr>\r\n		<td class=\"tcat\">\r\n			<a style=\"float:$stylevar[right]\" href=\"#top\" onclick=\"return toggle_collapse(\'newmessage_dialog\')\"><img id=\"collapseimg_newmessage_dialog\" src=\"$stylevar[imgdir_button]/collapse_tcat$vbcollapse[collapseimg_nemessage_dialog].gif\" alt=\"\" border=\"0\" /></a>\r\n					$vbphrase[message_dialog]\r\n		</td>\r\n	</tr>\r\n</thead>\r\n<tbody id=\"collapseobj_newmessage_dialog\" style=\"$vbcollapse[collapseobj_newmessage_dialog]\">\r\n	<tr valign=\"top\">\r\n		<td class=\"panelsurround\">\r\n		<div class=\"panel\">\r\n\r\n			$messagebits\r\n\r\n		</div>\r\n		</td>\r\n	</tr>\r\n</tbody>\r\n</table>\r\n</if>\r\n\r\n<br />\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', 'template', 1213617623, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(540, -1, 'visitormessage_preview', '<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		\".(($show[\'errors\']) ? (\"\r\n			$vbphrase[errors_occured_when_submitted]:\r\n		\") : (\"\r\n			$vbphrase[preview]\r\n		\")).\"\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"alt1\\\">\r\n		\".(($show[\'errors\']) ? (\"\r\n			<!--POSTERROR do not remove this comment-->\r\n			<ol>$errorlist</ol>\r\n			<!--/POSTERROR do not remove this comment-->\r\n		\") : (\"\r\n\r\n			\".(($newpost[\'title\']) ? (\"\r\n				<!-- icon and title -->\r\n				<div class=\\\"smallfont\\\">\r\n					<strong>$message[title]</strong>\r\n				</div>\r\n				<hr size=\\\"1\\\" style=\\\"color:$stylevar[tborder_bgcolor]; background-color:$stylevar[tborder_bgcolor]\\\" />\r\n				<!-- / icon and title -->\r\n			\") : (\"\")).\"\r\n			$previewmessage\r\n		\")).\"\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />', '<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		<if condition=\"$show[\'errors\']\">\r\n			$vbphrase[errors_occured_when_submitted]:\r\n		<else />\r\n			$vbphrase[preview]\r\n		</if>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"alt1\">\r\n		<if condition=\"$show[\'errors\']\">\r\n			<!--POSTERROR do not remove this comment-->\r\n			<ol>$errorlist</ol>\r\n			<!--/POSTERROR do not remove this comment-->\r\n		<else />\r\n\r\n			<if condition=\"$newpost[\'title\']\">\r\n				<!-- icon and title -->\r\n				<div class=\"smallfont\">\r\n					<strong>$message[title]</strong>\r\n				</div>\r\n				<hr size=\"1\" style=\"color:$stylevar[tborder_bgcolor]; background-color:$stylevar[tborder_bgcolor]\" />\r\n				<!-- / icon and title -->\r\n			</if>\r\n			$previewmessage\r\n		</if>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />', 