(541, -1, 'visitormessage_simpleview', '<div class=\\\"alt1\\\">\r\n\r\n	<div>\r\n		<div valign=\\\"top\\\" align=\\\"$stylevar[right]\\\" style=\\\"float:$stylevar[right]\\\" class=\\\"smallfont\\\">\r\n			<a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$message[postuserid]\\\">$message[username]</a>\r\n			<br />\r\n			$message[date]\".((!$show[\'detailedtime\']) ? (\", $message[time]\") : (\"\")).\"\r\n		</div>\r\n\r\n		<div class=\\\"smallfont\\\" style=\\\"padding-bottom:10px\\\">$message[message]</div>\r\n	</div>\r\n\r\n\r\n	\".(($show[\'moderation\']) ? (\"\r\n		<img class=\\\"inlineimg\\\" src=\\\"$stylevar[imgdir_misc]/moderated.gif\\\" alt=\\\"$vbphrase[moderated_visitor_message]\\\" border=\\\"0\\\" />\r\n	\") : (\"\")).\"\r\n\r\n</div>\r\n<hr />', '<div class=\"alt1\">\r\n\r\n	<div>\r\n		<div valign=\"top\" align=\"$stylevar[right]\" style=\"float:$stylevar[right]\" class=\"smallfont\">\r\n			<a href=\"member.php?$session[sessionurl]u=$message[postuserid]\">$message[username]</a>\r\n			<br />\r\n			$message[date]<if condition=\"!$show[\'detailedtime\']\">, $message[time]</if>\r\n		</div>\r\n\r\n		<div class=\"smallfont\" style=\"padding-bottom:10px\">$message[message]</div>\r\n	</div>\r\n\r\n\r\n	<if condition=\"$show[\'moderation\']\">\r\n		<img class=\"inlineimg\" src=\"$stylevar[imgdir_misc]/moderated.gif\" alt=\"$vbphrase[moderated_visitor_message]\" border=\"0\" />\r\n	</if>\r\n\r\n</div>\r\n<hr />', 'template', 1219144986, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(542, -1, 'visitormessage_simpleview_deleted', '<div class=\\\"alt1\\\">\r\n\r\n	<div valign=\\\"top\\\" align=\\\"$stylevar[right]\\\" style=\\\"float:$stylevar[right]\\\" class=\\\"smallfont\\\">\r\n		<a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$message[postuserid]\\\">$message[username]</a>\r\n\r\n\r\n		<br />\r\n		$message[date]\".((!$show[\'detailedtime\']) ? (\", $message[time]\") : (\"\")).\"\r\n		<br />\r\n	</div>\r\n\r\n	<div class=\\\"smallfont\\\">\r\n		\" . construct_phrase(\"$vbphrase[message_deleted_by_x]\", \"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$message[del_userid]\", \"$message[del_username]\") . \"\r\n		\".(($message[\'del_reason\']) ? (\"$vbphrase[reason]: <em>$message[del_reason]</em>\") : (\"\")).\"\r\n	</div>\r\n\r\n</div>\r\n<hr />', '<div class=\"alt1\">\r\n\r\n	<div valign=\"top\" align=\"$stylevar[right]\" style=\"float:$stylevar[right]\" class=\"smallfont\">\r\n		<a href=\"member.php?$session[sessionurl]u=$message[postuserid]\">$message[username]</a>\r\n\r\n\r\n		<br />\r\n		$message[date]<if condition=\"!$show[\'detailedtime\']\">, $message[time]</if>\r\n		<br />\r\n	</div>\r\n\r\n	<div class=\"smallfont\">\r\n		<phrase 1=\"member.php?$session[sessionurl]u=$message[del_userid]\" 2=\"$message[del_username]\">$vbphrase[message_deleted_by_x]</phrase>\r\n		<if condition=\"$message[\'del_reason\']\">$vbphrase[reason]: <em>$message[del_reason]</em></if>\r\n	</div>\r\n\r\n</div>\r\n<hr />', 'template', 1219144781, 'vBulletin Solutions', '3.8.0 Alpha 1', 'vbulletin'),
(543, -1, 'WHOPOSTED', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n	$headinclude\r\n	<title>$vbphrase[who_posted] - \" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \"</title>\r\n</head>\r\n<body onload=\\\"self.focus()\\\" style=\\\"margin:0px\\\">\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\" colspan=\\\"2\\\">\r\n		$vbphrase[who_posted]\r\n		<div class=\\\"smallfont\\\">\" . construct_phrase(\"$vbphrase[total_posts_x]\", \"$totalposts\") . \"</div>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"thead\\\" width=\\\"100%\\\">$vbphrase[username]</td>\r\n	<td class=\\\"thead\\\">$vbphrase[posts]</td>\r\n</tr>\r\n$posters\r\n<tr>\r\n	<td class=\\\"tfoot\\\" colspan=\\\"2\\\" align=\\\"center\\\"><div class=\\\"smallfont\\\">\r\n		<a href=\\\"showthread.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"t=$threadid\\\" onclick=\\\"opener.location=(\'showthread.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"t=$threadid\'); self.close();\\\"><strong>$vbphrase[show_thread_and_close_window]</strong></a>\r\n	</div></td>\r\n</tr>\r\n</table>\r\n\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n	$headinclude\r\n	<title>$vbphrase[who_posted] - $vboptions[bbtitle]</title>\r\n</head>\r\n<body onload=\"self.focus()\" style=\"margin:0px\">\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\">\r\n<tr>\r\n	<td class=\"tcat\" colspan=\"2\">\r\n		$vbphrase[who_posted]\r\n		<div class=\"smallfont\"><phrase 1=\"$totalposts\">$vbphrase[total_posts_x]</phrase></div>\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"thead\" width=\"100%\">$vbphrase[username]</td>\r\n	<td class=\"thead\">$vbphrase[posts]</td>\r\n</tr>\r\n$posters\r\n<tr>\r\n	<td class=\"tfoot\" colspan=\"2\" align=\"center\"><div class=\"smallfont\">\r\n		<a href=\"showthread.php?$session[sessionurl]t=$threadid\" onclick=\"opener.location=(\'showthread.php?$session[sessionurl]t=$threadid\'); self.close();\"><strong>$vbphrase[show_thread_and_close_window]</strong></a>\r\n	</div></td>\r\n</tr>\r\n</table>\r\n\r\n</body>\r\n</html>', 'template', 1195729840, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
(544, -1, 'whopostedbit', '<tr>\r\n	<td class=\\\"$bgclass\\\">\r\n		\".(($show[\'memberlink\']) ? (\"\r\n			<a href=\\\"member.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"u=$post[userid]\\\" target=\\\"_blank\\\">$post[username]</a>\r\n		\") : (\"\r\n			$post[username]\r\n		\")).\"\r\n	</td>\r\n	<td class=\\\"$bgclass\\\">\".(($post[\'userid\']) ? (\"<a href=\\\"search.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=finduser&amp;userid=$post[userid]&amp;searchthreadid=$threadinfo[threadid]\\\" onclick=\\\"opener.location=(\'search.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=finduser&amp;userid=$post[userid]&amp;searchthreadid=$threadinfo[threadid]\'); self.close();\\\">$post[posts]</a>\") : (\"$post[posts]\")).\"</td>\r\n</tr>', '<tr>\r\n	<td class=\"$bgclass\">\r\n		<if condition=\"$show[\'memberlink\']\">\r\n			<a href=\"member.php?$session[sessionurl]u=$post[userid]\" target=\"_blank\">$post[username]</a>\r\n		<else />\r\n			$post[username]\r\n		</if>\r\n	</td>\r\n	<td class=\"$bgclass\"><if condition=\"$post[\'userid\']\"><a href=\"search.php?$session[sessionurl]do=finduser&amp;userid=$post[userid]&amp;searchthreadid=$threadinfo[threadid]\" onclick=\"opener.location=(\'search.php?$session[sessionurl]do=finduser&amp;userid=$post[userid]&amp;searchthreadid=$threadinfo[threadid]\'); self.close();\">$post[posts]</a><else />$post[posts]</if></td>\r\n</tr>', 'template', 1264029590, 'vBulletin Solutions', '3.8.5', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(545, -1, 'WHOSONLINE', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n\".(($show[\'refresh\']) ? (\"\r\n	\".((is_browser(\'mozilla\')) ? (\"\r\n		<script type=\\\"text/javascript\\\">\r\n		<!--\r\n			var myvar = \\\"\\\";\r\n			var timeout = $refreshtime;\r\n	\r\n			function exec_refresh()\r\n			{\r\n				var timerID = setTimeout(\\\"exec_refresh();\\\", 100);\r\n				if (timeout > 0)\r\n				{\r\n					timeout -= 1;\r\n				}\r\n				else\r\n				{\r\n					clearTimeout(timerID);\r\n					window.location=\\\"online.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl_js\'] . \"order=$sortorder&sort=$sortfield&pp=$perpage&page=$pagenumber$refreshargs_js\\\";\r\n				}\r\n			}\r\n			exec_refresh();\r\n		//-->\r\n		</script>\r\n	\") : (\"\r\n		<meta http-equiv=\\\"refresh\\\" content=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'WOLrefresh\'] . \";url=online.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"order=$sortorder&amp;sort=$sortfield&amp;pp=$perpage&amp;page=$pagenumber$refreshargs\\\" />\r\n	\")).\"\r\n\") : (\"\")).\"\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $vbphrase[whos_online]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n\".(($pagenav) ? (\"\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\" style=\\\"margin-bottom:3px\\\">\r\n<tr valign=\\\"bottom\\\">\r\n	<td align=\\\"$stylevar[right]\\\">$pagenav</td>\r\n</tr>\r\n</table>\r\n\") : (\"\")).\"\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\" id=\\\"woltable\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\" colspan=\\\"$colspan\\\"><div class=\\\"smallfont\\\">\r\n		<span style=\\\"float:$stylevar[right]\\\">\r\n			<a href=\\\"$reloadurl\\\"><strong>$vbphrase[reload_this_page]</strong></a>\r\n		</span>\r\n		<strong>\" . construct_phrase(\"$vbphrase[x_members_and_y_guests]\", \"$numbervisible\", \"$numberguests\") . \"</strong><br />\" . construct_phrase(\"$vbphrase[most_users_ever_online_was_x_y_at_z]\", \"$recordusers\", \"$recorddate\", \"$recordtime\") . \"\r\n	</div></td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"thead\\\">\r\n		<span style=\\\"float:$stylevar[right]\\\">\r\n			<a href=\\\"$sorturl\".((!$show[\'sorturlnoargs\']) ? (\"&amp;\") : (\"\")).\"order=desc&amp;sort=time&amp;pp=$perpage&amp;page=$pagenumber\\\">$vbphrase[last_activity]</a> $sortarrow[time]\r\n		</span>\r\n		<a href=\\\"$sorturl\".((!$show[\'sorturlnoargs\']) ? (\"&amp;\") : (\"\")).\"order=asc&amp;sort=username&amp;pp=$perpage&amp;page=$pagenumber\\\">$vbphrase[username]</a> $sortarrow[username]\r\n	</td>\r\n	<td class=\\\"thead\\\"><a href=\\\"$sorturl\".((!$show[\'sorturlnoargs\']) ? (\"&amp;\") : (\"\")).\"order=asc&amp;sort=location&amp;pp=$perpage&amp;page=$pagenumber\\\">$vbphrase[location_temp]</a> $sortarrow[location]</td>\r\n	\".(($show[\'ip\']) ? (\"<td class=\\\"thead\\\">$vbphrase[ip_address]</td>\") : (\"\")).\"\r\n	\".(($GLOBALS[\'vbulletin\']->options[\'showimicons\']) ? (\"<td class=\\\"thead\\\" align=\\\"center\\\">$vbphrase[instant_messaging]</td>\") : (\"\")).\"\r\n</tr>\r\n$onlinebits\r\n</table>\r\n\r\n\".(($show[\'ajax_resolve\']) ? (\"\r\n	<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_ajax_wolresolve.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n	<script type=\\\"text/javascript\\\">\r\n	<!--\r\n	vB_AJAX_WolResolve_Init(\'woltable\');\r\n	//-->\r\n	</script>\r\n\") : (\"\")).\"\r\n\r\n<br />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"alt1\\\" align=\\\"center\\\">\r\n\r\n		<form action=\\\"online.php\\\" method=\\\"get\\\">\r\n		<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"sortfield\\\" value=\\\"$sortfield\\\" />\r\n		<input type=\\\"hidden\\\" name=\\\"sortorder\\\" value=\\\"$sortorder\\\" />\r\n		<div class=\\\"fieldset\\\" style=\\\"margin:0px\\\">\r\n\r\n			\".(($GLOBALS[\'vbulletin\']->options[\'WOLguests\']) ? (\"\r\n				$vbphrase[display]:\r\n				<select name=\\\"who\\\">\r\n					<option value=\\\"all\\\" $whoselected[0]>$vbphrase[all]</option>\r\n					<option value=\\\"members\\\" $whoselected[1]>$vbphrase[members]</option>\r\n					<option value=\\\"guests\\\" $whoselected[2]>$vbphrase[guests]</option>\r\n					\".(($GLOBALS[\'vbulletin\']->options[\'enablespiders\']) ? (\"\r\n						<option value=\\\"spiders\\\" $whoselected[3]>$vbphrase[search_bots]</option>\r\n					\") : (\"\")).\"\r\n				</select>\r\n				&nbsp; &nbsp;\r\n			\") : (\"\")).\"\r\n\r\n			\".(($show[\'ip\']) ? (\"\r\n				$vbphrase[user_agent]:\r\n				<select name=\\\"ua\\\">\r\n					<option value=\\\"1\\\" $uaselected[1]>$vbphrase[yes]</option>\r\n					<option value=\\\"0\\\" $uaselected[0]>$vbphrase[no]</option>\r\n				</select>\r\n				&nbsp; &nbsp;\r\n			\") : (\"\")).\"\r\n\r\n			$vbphrase[per_page]:\r\n			<input type=\\\"text\\\" class=\\\"bginput\\\" style=\\\"font-size:11px\\\" name=\\\"pp\\\" value=\\\"$perpage\\\" size=\\\"2\\\" />\r\n			&nbsp; &nbsp;\r\n\r\n\r\n\r\n			<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[display]\\\" accesskey=\\\"s\\\" />\r\n\r\n		</div>\r\n		</form>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n\".(($pagenav) ? (\"\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"100%\\\" style=\\\"margin-top:3px\\\">\r\n<tr valign=\\\"top\\\">\r\n	<td align=\\\"$stylevar[right]\\\">$pagenav</td>\r\n</tr>\r\n</table>\r\n\") : (\"\")).\"\r\n\r\n<br />\r\n\r\n<!-- icons and forum jump -->\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"2\\\" border=\\\"0\\\" width=\\\"100%\\\">\r\n<tr valign=\\\"bottom\\\">\r\n	<td width=\\\"100%\\\">\r\n		<table cellpadding=\\\"2\\\" cellspacing=\\\"0\\\" border=\\\"0\\\">\r\n		<col align=\\\"center\\\"></col>\r\n		<tr>\r\n			<td><strong>+</strong></td>\r\n			<td class=\\\"smallfont\\\">&nbsp; $vbphrase[user_is_on_your_contact_list]</td>\r\n		</tr>\r\n		\".(($show[\'hidden\']) ? (\"\r\n		<tr>\r\n			<td><strong>*</strong></td>\r\n			<td class=\\\"smallfont\\\">&nbsp; $vbphrase[user_is_invisible_to_others]</td>\r\n		</tr>\r\n		\") : (\"\")).\"\r\n		\".(($show[\'badlocation\']) ? (\"\r\n			<tr>\r\n				<td><img src=\\\"$stylevar[imgdir_statusicon]/wol_lockedout.gif\\\" alt=\\\"$vbphrase[viewing_forum_closed]\\\" /></td>\r\n				<td class=\\\"smallfont\\\">&nbsp; $vbphrase[viewing_forum_closed]</td>\r\n			</tr>\r\n			<tr>\r\n				<td><img src=\\\"$stylevar[imgdir_statusicon]/wol_nopermission.gif\\\" alt=\\\"$vbphrase[viewing_no_permission_message]\\\" /></td>\r\n				<td class=\\\"smallfont\\\">&nbsp; $vbphrase[viewing_no_permission_message]</td>\r\n			</tr>\r\n			<tr>\r\n				<td><img src=\\\"$stylevar[imgdir_statusicon]/wol_error.gif\\\" alt=\\\"$vbphrase[viewing_error_message]\\\" /></td>\r\n				<td class=\\\"smallfont\\\">&nbsp; $vbphrase[viewing_error_message]</td>\r\n			</tr>\r\n		\") : (\"\")).\"\r\n		</table>\r\n	</td>\r\n	<td>\r\n		$forumjump\r\n	</td>\r\n</tr>\r\n</table>\r\n<!-- / icons and forum jump -->\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n<if condition=\"$show[\'refresh\']\">\r\n	<if condition=\"is_browser(\'mozilla\')\">\r\n		<script type=\"text/javascript\">\r\n		<!--\r\n			var myvar = \"\";\r\n			var timeout = $refreshtime;\r\n	\r\n			function exec_refresh()\r\n			{\r\n				var timerID = setTimeout(\"exec_refresh();\", 100);\r\n				if (timeout > 0)\r\n				{\r\n					timeout -= 1;\r\n				}\r\n				else\r\n				{\r\n					clearTimeout(timerID);\r\n					window.location=\"online.php?$session[sessionurl_js]order=$sortorder&sort=$sortfield&pp=$perpage&page=$pagenumber$refreshargs_js\";\r\n				}\r\n			}\r\n			exec_refresh();\r\n		//-->\r\n		</script>\r\n	<else />\r\n		<meta http-equiv=\"refresh\" content=\"$vboptions[WOLrefresh];url=online.php?$session[sessionurl]order=$sortorder&amp;sort=$sortfield&amp;pp=$perpage&amp;page=$pagenumber$refreshargs\" />\r\n	</if>\r\n</if>\r\n<title>$vboptions[bbtitle] - $vbphrase[whos_online]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<if condition=\"$pagenav\">\r\n<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"margin-bottom:3px\">\r\n<tr valign=\"bottom\">\r\n	<td align=\"$stylevar[right]\">$pagenav</td>\r\n</tr>\r\n</table>\r\n</if>\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\" id=\"woltable\">\r\n<tr>\r\n	<td class=\"tcat\" colspan=\"$colspan\"><div class=\"smallfont\">\r\n		<span style=\"float:$stylevar[right]\">\r\n			<a href=\"$reloadurl\"><strong>$vbphrase[reload_this_page]</strong></a>\r\n		</span>\r\n		<strong><phrase 1=\"$numbervisible\" 2=\"$numberguests\">$vbphrase[x_members_and_y_guests]</phrase></strong><br /><phrase 1=\"$recordusers\" 2=\"$recorddate\" 3=\"$recordtime\">$vbphrase[most_users_ever_online_was_x_y_at_z]</phrase>\r\n	</div></td>\r\n</tr>\r\n<tr>\r\n	<td class=\"thead\">\r\n		<span style=\"float:$stylevar[right]\">\r\n			<a href=\"$sorturl<if condition=\"!$show[\'sorturlnoargs\']\">&amp;</if>order=desc&amp;sort=time&amp;pp=$perpage&amp;page=$pagenumber\">$vbphrase[last_activity]</a> $sortarrow[time]\r\n		</span>\r\n		<a href=\"$sorturl<if condition=\"!$show[\'sorturlnoargs\']\">&amp;</if>order=asc&amp;sort=username&amp;pp=$perpage&amp;page=$pagenumber\">$vbphrase[username]</a> $sortarrow[username]\r\n	</td>\r\n	<td clas