$vbphrase[your_name] :<br />\r\n						<input type=\"text\" class=\"bginput\" name=\"name\" value=\"$name\" size=\"50\" />\r\n					</td>\r\n				</tr>\r\n				<tr>\r\n					<td>\r\n						$vbphrase[email_address] :<br />\r\n						<input type=\"text\" class=\"bginput\" name=\"email\" value=\"$email\" size=\"50\" dir=\"ltr\" />\r\n					</td>\r\n				</tr>\r\n				</table>\r\n			</fieldset>\r\n\r\n			<fieldset class=\"fieldset\">\r\n				<legend>$vbphrase[subject]</legend>\r\n				<div style=\"padding:$stylevar[formspacer]px\">\r\n					<if condition=\"$vboptions[\'contactusoptions\']\">\r\n						$contactusoptions\r\n						<if condition=\"$vboptions[\'contactusother\']\">\r\n							<div>\r\n								<label for=\"rb_subjother\"><input type=\"radio\" name=\"subject\" value=\"other\" id=\"rb_subjother\" $other_subject_checked />$vbphrase[other]</label>\r\n								<input type=\"text\" class=\"bginput\" name=\"other_subject\" size=\"40\" value=\"$other_subject\" maxlength=\"85\" />\r\n							</div>\r\n						</if>\r\n					<else />\r\n						$vbphrase[subject] :<br />\r\n						<input type=\"text\" class=\"bginput\" name=\"subject\" value=\"$subject\" size=\"50\" maxlength=\"85\" />\r\n					</if>\r\n				</div>\r\n			</fieldset>\r\n\r\n			$human_verify\r\n\r\n			<div class=\"fieldset\">\r\n				$vbphrase[message]:<br />\r\n				<textarea name=\"message\" rows=\"10\" cols=\"50\" style=\"width:$stylevar[messagewidth]\">$message</textarea>\r\n			</div>\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\"margin-top:$stylevar[cellpadding]px\">\r\n		<input type=\"submit\" class=\"button\" value=\"$vbphrase[send]\" accesskey=\"s\" />\r\n		<input type=\"reset\" class=\"button\" name=\"reset\" value=\"$vbphrase[reset_fields]\" accesskey=\"r\" />\r\n	</div>\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', 'template', 1265204281, 'vBulletin Solutions', '3.8.5', 'vbulletin'),
(554, -1, 'contactus_option', '<div><label for=\\\"rb_subj$index\\\"><input type=\\\"radio\\\" name=\\\"subject\\\" id=\\\"rb_subj$index\\\" value=\\\"$index\\\" $checked />$title</label></div>\r\n', '<div><label for=\"rb_subj$index\"><input type=\"radio\" name=\"subject\" id=\"rb_subj$index\" value=\"$index\" $checked />$title</label></div>\r\n', 'template', 1068724587, 'vBulletin Solutions', '', 'vbulletin'),
(555, -1, 'converse', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n\r\n$usercss\r\n$memberinfo_css\r\n\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $pagetitle</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<div id=\\\"usercss\\\">\r\n	<div class=\\\"tborder content_block\\\" id=\\\"visitor_messaging\\\">\r\n		<div class=\\\"tcat block_row block_title\\\">\r\n			\".(($show[\'usercss_switch\']) ? (\"\r\n				<div class=\\\"smallfont\\\" style=\\\"float:$stylevar[right]\\\">\r\n					<a href=\\\"profile.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=switchusercss&amp;hash=\" . $GLOBALS[\'vbulletin\']->userinfo[\'logouthash\'] . \"&amp;u=$userinfo[userid]\\\">$usercss_switch_phrase</a>\r\n				</div>\r\n			\") : (\"\")).\"\r\n			$pagetitle\r\n		</div>\r\n		$html\r\n	</div>\r\n</div>\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n\r\n$usercss\r\n$memberinfo_css\r\n\r\n<title>$vboptions[bbtitle] - $pagetitle</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<div id=\"usercss\">\r\n	<div class=\"tborder content_block\" id=\"visitor_messaging\">\r\n		<div class=\"tcat block_row block_title\">\r\n			<if condition=\"$show[\'usercss_switch\']\">\r\n				<div class=\"smallfont\" style=\"float:$stylevar[right]\">\r\n					<a href=\"profile.php?$session[sessionurl]do=switchusercss&amp;hash=$bbuserinfo[logouthash]&amp;u=$userinfo[userid]\">$usercss_switch_phrase</a>\r\n				</div>\r\n			</if>\r\n			$pagetitle\r\n		</div>\r\n		$html\r\n	</div>\r\n</div>\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', 'template', 1204913623, 'vBulletin Solutions', '3.7.0 Release Candidate 1', 'vbulletin');
INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(556, -1, 'editpoll', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n$headinclude\r\n<title>\" . $GLOBALS[\'vbulletin\']->options[\'bbtitle\'] . \" - $vbphrase[edit_poll]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<form action=\\\"poll.php?do=updatepoll&amp;pollid=$pollid\\\" method=\\\"post\\\">\r\n<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"updatepoll\\\" />\r\n<input type=\\\"hidden\\\" name=\\\"pollid\\\" value=\\\"$pollid\\\" />\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"100%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">\r\n		<span class=\\\"smallfont\\\" style=\\\"float:$stylevar[right]\\\"><strong>$vbphrase[thread]</strong>: $threadinfo[prefix_plain_html] <a href=\\\"showthread.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"t=$threadinfo[threadid]\\\">$threadinfo[title]</a></span>\r\n		$vbphrase[edit_poll]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div style=\\\"width:$stylevar[formwidth]\\\" align=\\\"$stylevar[left]\\\">\r\n\r\n		$usernamecode\r\n\r\n		<div class=\\\"fieldset\\\">\r\n			<div><label for=\\\"pollquestion\\\">$vbphrase[poll_question]</label>:</div>\r\n			<input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"pollquestion\\\" value=\\\"$pollinfo[question]\\\" id=\\\"pollquestion\\\" size=\\\"50\\\" maxlength=\\\"\" . $GLOBALS[\'vbulletin\']->options[\'titlemaxchars\'] . \"\\\" />\r\n		</div>\r\n\r\n		<fieldset class=\\\"fieldset\\\">\r\n			<legend>$vbphrase[poll_options]</legend>\r\n			<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n			$pollbits\r\n\r\n			\".(($show[\'additional_option1\']) ? (\"\r\n			<tr>\r\n				<td colspan=\\\"2\\\"><label for=\\\"add1\\\">$vbphrase[additional_option_1]:<br /><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"options[]\\\" id=\\\"add1\\\" size=\\\"50\\\" /></label></td>\r\n			</tr>\r\n			\") : (\"\")).\"\r\n\r\n			\".(($show[\'additional_option2\']) ? (\"\r\n			<tr>\r\n				<td colspan=\\\"2\\\"><label for=\\\"add2\\\">$vbphrase[additional_option_2]:<br /><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"options[]\\\" id=\\\"add2\\\" size=\\\"50\\\" /></label></td>\r\n			</tr>\r\n			\") : (\"\")).\"\r\n			<tr>\r\n				<td colspan=\\\"2\\\">$vbphrase[keep_poll_options_short]</td>\r\n			</tr>\r\n			</table>\r\n		</fieldset>\r\n\r\n		<fieldset class=\\\"fieldset\\\">\r\n			<legend>$vbphrase[poll_timeout]</legend>\r\n			<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n			<tr>\r\n				<td>$vbphrase[automatically_close_poll_enter_days]</td>\r\n			</tr>\r\n			<tr>\r\n				<td><label for=\\\"poll_timeout\\\">$vbphrase[close_poll] <input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"timeout\\\" value=\\\"$pollinfo[timeout]\\\" size=\\\"5\\\" id=\\\"poll_timeout\\\" /> \" . construct_phrase(\"$vbphrase[days_after_x]\", \"$pollinfo[postdate]\") . \"</label></td>\r\n			</tr>\r\n			</table>\r\n		</fieldset>\r\n\r\n		\".(($show[\'makeprivate\']) ? (\"\r\n		<fieldset class=\\\"fieldset\\\">\r\n			<legend>$vbphrase[poll_options]</legend>\r\n			<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n			<tr>\r\n				<td><label for=\\\"cb_public\\\"><input type=\\\"checkbox\\\" name=\\\"public\\\" value=\\\"1\\\" id=\\\"cb_public\\\" tabindex=\\\"1\\\" $pollinfo[public] />$vbphrase[make_votes_public]</label></td>\r\n			</tr>\r\n			</table>\r\n		</fieldset>\r\n		\") : (\"\")).\"\r\n\r\n		<fieldset class=\\\"fieldset\\\">\r\n			<legend>$vbphrase[close_poll]</legend>\r\n			<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\">\r\n			<tr>\r\n				<td><label for=\\\"cb_closepoll\\\"><input type=\\\"checkbox\\\" name=\\\"closepoll\\\" value=\\\"yes\\\" id=\\\"cb_closepoll\\\" $pollinfo[closed] />$vbphrase[to_close_this_poll_check_this_box]</label></td>\r\n			</tr>\r\n			<tr>\r\n				<td>$vbphrase[closing_poll_impossible_to_vote]</td>\r\n			</tr>\r\n			</table>\r\n		</fieldset>\r\n\r\n		</div>\r\n	</div>\r\n\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" name=\\\"sbutton\\\" accesskey=\\\"s\\\" value=\\\"$vbphrase[save_changes]\\\" />\r\n		<input type=\\\"reset\\\" class=\\\"button\\\" value=\\\"$vbphrase[reset_fields]\\\" />\r\n	</div>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n</form>\r\n\r\n<br />\r\n\r\n$forumrules\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n$headinclude\r\n<title>$vboptions[bbtitle] - $vbphrase[edit_poll]</title>\r\n</head>\r\n<body>\r\n$header\r\n$navbar\r\n\r\n<form action=\"poll.php?do=updatepoll&amp;pollid=$pollid\" method=\"post\">\r\n<input type=\"hidden\" name=\"s\" value=\"$session[sessionhash]\" />\r\n<input type=\"hidden\" name=\"securitytoken\" value=\"$bbuserinfo[securitytoken]\" />\r\n<input type=\"hidden\" name=\"do\" value=\"updatepoll\" />\r\n<input type=\"hidden\" name=\"pollid\" value=\"$pollid\" />\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"100%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">\r\n		<span class=\"smallfont\" style=\"float:$stylevar[right]\"><strong>$vbphrase[thread]</strong>: $threadinfo[prefix_plain_html] <a href=\"showthread.php?$session[sessionurl]t=$threadinfo[threadid]\">$threadinfo[title]</a></span>\r\n		$vbphrase[edit_poll]\r\n	</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div style=\"width:$stylevar[formwidth]\" align=\"$stylevar[left]\">\r\n\r\n		$usernamecode\r\n\r\n		<div class=\"fieldset\">\r\n			<div><label for=\"pollquestion\">$vbphrase[poll_question]</label>:</div>\r\n			<input type=\"text\" class=\"bginput\" name=\"pollquestion\" value=\"$pollinfo[question]\" id=\"pollquestion\" size=\"50\" maxlength=\"$vboptions[titlemaxchars]\" />\r\n		</div>\r\n\r\n		<fieldset class=\"fieldset\">\r\n			<legend>$vbphrase[poll_options]</legend>\r\n			<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n			$pollbits\r\n\r\n			<if condition=\"$show[\'additional_option1\']\">\r\n			<tr>\r\n				<td colspan=\"2\"><label for=\"add1\">$vbphrase[additional_option_1]:<br /><input type=\"text\" class=\"bginput\" name=\"options[]\" id=\"add1\" size=\"50\" /></label></td>\r\n			</tr>\r\n			</if>\r\n\r\n			<if condition=\"$show[\'additional_option2\']\">\r\n			<tr>\r\n				<td colspan=\"2\"><label for=\"add2\">$vbphrase[additional_option_2]:<br /><input type=\"text\" class=\"bginput\" name=\"options[]\" id=\"add2\" size=\"50\" /></label></td>\r\n			</tr>\r\n			</if>\r\n			<tr>\r\n				<td colspan=\"2\">$vbphrase[keep_poll_options_short]</td>\r\n			</tr>\r\n			</table>\r\n		</fieldset>\r\n\r\n		<fieldset class=\"fieldset\">\r\n			<legend>$vbphrase[poll_timeout]</legend>\r\n			<table cellpadding=\"0\" cellspacing=\"$stylevar[formspacer]\" border=\"0\">\r\n			<tr>\r\n				<td>$vbphrase[automatically_close_poll_enter_days]</td>\r\n			</tr>\r\n			<tr>\r\n				<td><label for=\"poll_timeout\">$vbphrase[close_poll] <input type=\"text\" class=\"bginput\" name=\"timeout\" value=\"$pollinfo[timeout]\" size=\"5\" id=\"poll_timeout\" /> <phrase 1=\"$pollinfo[postdate]\">$vbphrase[days_after_x]</phrase></label></td>\r\n			</tr>\