INSERT INTO `vb3_template` (`templateid`, `styleid`, `title`, `template`, `template_un`, `templatetype`, `dateline`, `username`, `version`, `product`) VALUES
(576, -1, 'spacer_open', '<!-- open content container -->\r\n\".(($show[\'old_explorer\']) ? (\"\r\n	<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" width=\\\"$stylevar[outertablewidth]\\\" align=\\\"center\\\"><tr><td class=\\\"page\\\" style=\\\"padding:0px $stylevar[spacersize]px 0px $stylevar[spacersize]px\\\">\r\n\") : (\"\r\n<div align=\\\"center\\\">\r\n	<div class=\\\"page\\\" style=\\\"width:$stylevar[outerdivwidth]; text-align:$stylevar[left]\\\">\r\n		<div style=\\\"padding:0px $stylevar[spacersize]px 0px $stylevar[spacersize]px\\\" align=\\\"$stylevar[left]\\\">\r\n\")).\"', '<!-- open content container -->\r\n<if condition=\"$show[\'old_explorer\']\">\r\n	<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"$stylevar[outertablewidth]\" align=\"center\"><tr><td class=\"page\" style=\"padding:0px $stylevar[spacersize]px 0px $stylevar[spacersize]px\">\r\n<else />\r\n<div align=\"center\">\r\n	<div class=\"page\" style=\"width:$stylevar[outerdivwidth]; text-align:$stylevar[left]\">\r\n		<div style=\"padding:0px $stylevar[spacersize]px 0px $stylevar[spacersize]px\" align=\"$stylevar[left]\">\r\n</if>', 'template', 1193831811, 'vBulletin Solutions', '3.7.0 Beta 1', 'vbulletin'),
(577, -1, 'STANDARD_ERROR', '$stylevar[htmldoctype]\r\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" dir=\\\"$stylevar[textdirection]\\\" lang=\\\"$stylevar[languagecode]\\\">\r\n<head>\r\n\".(($show[\'search_noindex\']) ? (\"<meta name=\\\"robots\\\" content=\\\"noindex,follow\\\" />\") : (\"\")).\"\r\n$headinclude\r\n	<title>$pagetitle</title>\r\n$headinsert\r\n</head>\r\n<body>\r\n$header\r\n\".(($navbar) ? (\"\r\n$navbar\r\n\") : (\"\r\n<br /><br /><br />\r\n\")).\"\r\n\r\n<table class=\\\"tborder\\\" cellpadding=\\\"$stylevar[cellpadding]\\\" cellspacing=\\\"$stylevar[cellspacing]\\\" border=\\\"0\\\" width=\\\"70%\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td class=\\\"tcat\\\">$vbphrase[vbulletin_message]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\\\"panelsurround\\\" align=\\\"center\\\">\r\n	<div class=\\\"panel\\\">\r\n		<div align=\\\"$stylevar[left]\\\">\r\n\r\n		\".(($show[\'permission_error\']) ? (\"\r\n			<script type=\\\"text/javascript\\\" src=\\\"clientscript/vbulletin_md5.js?v=\" . $GLOBALS[\'vbulletin\']->options[\'simpleversion\'] . \"\\\"></script>\r\n			<form action=\\\"login.php?do=login\\\" method=\\\"post\\\" onsubmit=\\\"md5hash(vb_login_password, vb_login_md5password, vb_login_md5password_utf, $show[nopasswordempty])\\\">\r\n			<input type=\\\"hidden\\\" name=\\\"do\\\" value=\\\"login\\\" />\r\n			<input type=\\\"hidden\\\" name=\\\"url\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->scriptpath . \"\\\" />\r\n			<input type=\\\"hidden\\\" name=\\\"vb_login_md5password\\\" />\r\n			<input type=\\\"hidden\\\" name=\\\"vb_login_md5password_utf\\\" />\r\n			$postvars\r\n\r\n			<input type=\\\"hidden\\\" name=\\\"s\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionhash\'] . \"\\\" />\r\n			<input type=\\\"hidden\\\" name=\\\"securitytoken\\\" value=\\\"\" . $GLOBALS[\'vbulletin\']->userinfo[\'securitytoken\'] . \"\\\" />\r\n\r\n			<!-- permission error message - user not logged in -->\r\n\r\n\r\n			<div class=\\\"smallfont\\\">$vbphrase[not_logged_no_permission]</div>\r\n\r\n			<ol>\r\n				<li class=\\\"smallfont\\\">$vbphrase[not_logged_in_fill_in_form]</li>\r\n				<li class=\\\"smallfont\\\">$vbphrase[may_not_have_sufficient_privileges]</li>\r\n				<li class=\\\"smallfont\\\">$vbphrase[administrator_may_disabled_account]</li>\r\n			</ol>\r\n\r\n			<fieldset class=\\\"fieldset\\\">\r\n				<legend>$vbphrase[log_in]</legend>\r\n				<table cellpadding=\\\"0\\\" cellspacing=\\\"$stylevar[formspacer]\\\" border=\\\"0\\\" align=\\\"center\\\">\r\n				<tr>\r\n					<td>$vbphrase[username]:<br /><input type=\\\"text\\\" class=\\\"bginput\\\" name=\\\"vb_login_username\\\" size=\\\"50\\\" accesskey=\\\"u\\\" tabindex=\\\"1\\\" /></td>\r\n				</tr>\r\n				<tr>\r\n					<td>$vbphrase[password]:<br /><input type=\\\"password\\\" class=\\\"bginput\\\" name=\\\"vb_login_password\\\" size=\\\"50\\\" tabindex=\\\"1\\\" /></td>\r\n				</tr>\r\n				<tr>\r\n					<td>\r\n						<span style=\\\"float:$stylevar[right]\\\"><a href=\\\"login.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=lostpw\\\">$vbphrase[forgotten_your_password]</a></span>\r\n						<label for=\\\"cb_cookieuser\\\"><input type=\\\"checkbox\\\" name=\\\"cookieuser\\\" value=\\\"1\\\" id=\\\"cb_cookieuser\\\" tabindex=\\\"1\\\" />$vbphrase[remember_me]</label>\r\n					</td>\r\n				</tr>\r\n				<tr>\r\n					<td align=\\\"$stylevar[right]\\\">\r\n						<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[log_in]\\\" accesskey=\\\"s\\\" tabindex=\\\"1\\\" />\r\n						<input type=\\\"reset\\\" class=\\\"button\\\" value=\\\"$vbphrase[reset_fields]\\\" accesskey=\\\"r\\\" tabindex=\\\"1\\\" />\r\n					</td>\r\n				</tr>\r\n				</table>\r\n			</fieldset>\r\n\r\n			<div class=\\\"smallfont\\\">\" . construct_phrase(\"$vbphrase[admin_required_register]\", \"register.php?\" . $GLOBALS[\'vbulletin\']->session->vars[\'sessionurl\'] . \"do=signup\") . \"</div>\r\n			</form>\r\n\r\n			<!-- / permission error message - user not logged in -->\r\n		\") : (\"\r\n			<!-- main error message -->\r\n\r\n\r\n			<div style=\\\"margin: 10px\\\">$errormessage</div>\r\n\r\n\r\n			<!-- / main error message -->\r\n		\")).\"\r\n\r\n		</div>\r\n	</div>\r\n	<!--\r\n	<div style=\\\"margin-top:$stylevar[cellpadding]px\\\">\r\n		<input type=\\\"submit\\\" class=\\\"button\\\" value=\\\"$vbphrase[go_back]\\\" accesskey=\\\"s\\\" onclick=\\\"history.back(1); return false\\\" />\r\n	</div>\r\n	-->\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n<br />\r\n\r\n\".((!$show[\'enableforumjump\']) ? (\"\r\n<!-- forum jump -->\r\n<table cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" border=\\\"0\\\" align=\\\"center\\\">\r\n<tr>\r\n	<td>$forumjump</td>\r\n</tr>\r\n</table>\r\n<!-- / forum jump -->\r\n\") : (\"\")).\"\r\n\r\n<br />\r\n\r\n$footer\r\n\r\n</body>\r\n</html>', '$stylevar[htmldoctype]\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\" dir=\"$stylevar[textdirection]\" lang=\"$stylevar[languagecode]\">\r\n<head>\r\n<if condition=\"$show[\'search_noindex\']\"><meta name=\"robots\" content=\"noindex,follow\" /></if>\r\n$headinclude\r\n	<title>$pagetitle</title>\r\n$headinsert\r\n</head>\r\n<body>\r\n$header\r\n<if condition=\"$navbar\">\r\n$navbar\r\n<else />\r\n<br /><br /><br />\r\n</if>\r\n\r\n<table class=\"tborder\" cellpadding=\"$stylevar[cellpadding]\" cellspacing=\"$stylevar[cellspacing]\" border=\"0\" width=\"70%\" align=\"center\">\r\n<tr>\r\n	<td class=\"tcat\">$vbphrase[vbulletin_message]</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"panelsurround\" align=\"center\">\r\n	<div class=\"panel\">\r\n		<div align=\"$stylevar[left]\">\r\n\r\n		<if condition=\"$show[\'permission_error\']\">\r\n			<script type=\"text/javascript\" src=\"clientscript/vbulletin_md5.js?v=$vboptions[simpleversion]\"></script>\r\n			<form action=\"login.php?do=login\" method=\"post\" onsubmit=\"md5hash(vb_login_password, vb_login_md5password, vb_login_md5password_utf, $show[nopasswordempty])\">\r\n			<input type=\"hidden\" name=\"do\" value=\"login\" />\r